INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11818,'Разделить на две части слоеное тесто.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11818,'Первую часть раскатать в форме круга, переложить на смазанный маслом противень.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11818,'Выложить начинку из яиц, добавить заранее отваренный рис.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11818,'Положить два блина, можно смазать жирной сметаной.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11818,'Второй слой – грибная смесь, высыпать треть риса, разровнять, закрыть оставшимися блинами.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11818,'Последний слой – курица и оставшаяся рисовая крупа.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11818,'Закрыть пирог второй раскатанной частью теста, хорошо защипать края.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11818,'Смазать пирог взбитым куриным яйцом, печь в заранее прогретой духовке, время – 35 минут, температура – 180 градусов.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11819,'Тесто разморозить, раскатать, выложить на противень, заранее смазанный растительным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11819,'Выложить первый блин, на него – нарезанное куриное мясо, обжаренное до готовности на сковороде, второй блин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11819,'Далее – картофельное пюре с обжаренным репчатым луком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11819,'Накрыть начинку следующим блином.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11819,'Выложить обжарку из шампиньонов, остатки обжарки из лука.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11819,'Края теста завернуть наверх.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11819,'Смазать пирог взбитым желтком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11819,'Время приготовления в духовом шкафу – 25 минут, температура – 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11820,'Куриное филе замариновать с перцем, солью, луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11820,'Мясо подержать со специями в течение 15 или 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11820,'Болгарский перец нарезать, обжарить вместе с репчатым луком до получения золотистой корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11820,'Сырой картофель очистить и нарезать тонкими пластинками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11820,'Продукт посолить и поперчить по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11820,'Часть слоеного теста раскатать, выложить на смазанный растительным маслом противень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11820,'Сверху положить готовое куриное филе, кусочки сливочного масла.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11820,'Часть твердого сыра натереть, закрыть массу из мяса.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11820,'Следующий слой – нарезанный картофель и луковая обжарка.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11820,'Еще раз посыпать пирог тертым сыром.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11820,'Вторую часть слоеного теста раскатать, закрыть пирог, скрепить с первой частью.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11820,'Температура выпекания пирога – 180 градусов, время – около сорока минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11821,'Свинину отварить, нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11821,'Нарезать лук и грибы, перемешать, жарить до готовности на сковороде с маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11821,'Очистить и тонко нарезать небольшие клубни картофеля.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11821,'Соль и молотый перец добавить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11821,'Раскатать готовое слоеное тесто, нарезать круги размером с тарелку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11821,'Выложить мясо, грибы и картофель слоями.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11821,'Защипать тесто так, чтобы в середине осталось отверстие.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11821,'Положить в него нарезанное кусочками сливочное масло.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11821,'Приготовить остальные пироги по этому же рецепту.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11821,'Выложить на смазанный противень, печь в течение 35 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11822,'Готовое слоеное тесто раскатать по размеру чаши мультиварки, смазать ее маслом, выложить лепешку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11822,'Далее – слой отваренного куриного мяса, тушеной белокочанной капусты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11822,'Начинку смазать майонезом, закрыть второй лепешкой, защипать края.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11822,'Выставить режим «Выпечка», время приготовления – 25 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11823,'Отварить неочищенную свеклу в течение 40 или 45 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11823,'Овощ очистить и натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11823,'Измельчить чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11823,'Салат посолить по вкусу, заправить майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11823,'Ингредиенты перемешать, поставить в холодильник для настаивания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11824,'Отварить до мягкости свеклу, сразу переложить в холодную воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11824,'Очистить и натереть корнеплод на крупной терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11824,'Соль и молотый перец – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11824,'Очистить и порубить чеснок, можно воспользоваться чеснокодавкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11824,'Очистить грецкие орехи, обжарить на сковороде без масла.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11824,'Порубить ножом или измельчить при помощи кофемолки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11824,'Добавить в свеклу, заправить маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11825,'Измельчите лук, нашинкуйте капусту. Поджарьте на сковороде. Посолите и поперчите по вкусу.','https://vkuso.ru/data/cache/data/45/2b869361b6b8045_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11825,'В миску насыпьте сахар, соль и дрожжи. Налейте теплой воды, перемешайте. Постепенно добавляйте муку. Перемешивая ложкой.','https://vkuso.ru/data/cache/data/b3/6a96efb9726bbb3_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11825,'Вымесит тесто на столе, прикройте миской и оставьте на 30 минут на столе.','https://vkuso.ru/data/cache/data/8f/549707080252c8f_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11825,'Тесто немного вымесите, возьмите часть теста и раскатайте блин, толщиной 5 мм. С помощью кружки или формочки вырежьте кружки.','https://vkuso.ru/data/cache/data/2b/402d565fbd7b72b_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11825,'В середину кружка положите начинку и сформируйте вареник.','https://vkuso.ru/data/cache/data/aa/75b41cbdc3138aa_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11825,'Вареники отправьте в кипящую подсоленную воду. После закипания варите 5 минут.','https://vkuso.ru/data/cache/data/60/f96409f16c8db60_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11825,'Вареники с капустой готовы! Всем приятного аппетита!','https://vkuso.ru/data/cache/data/fc/ae2596f1851aefc_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11826,'Копченые свиные ребра выложить в чашу мультиварки на них —  грибы, нашинкованный полукольцами лук, брусочки картофеля и раздавленный прессом чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11826,'Растворить в небольшом количестве воды соль, добавить молотый черный перец, пряности, размешать и залить смесь в чаше.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11826,'Поставить режим «Тушение», жаркое с копчеными ребрышками  и грибами в мультиварке будет готово через полтора часа. При подаче в тарелках присыпать измельченной зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11827,'Горячие бутерброды в нашей семье все очень любят. Для приготовления использую любой хлеб, который есть дома. Лучше брать не очень свежий, так как после приготовления они могут разваливаться в руках.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11827,'Сверху на хлеб с майонезом положила колечко помидора, затем колечко колбасы и кусочек твердого сыра.','https://vkuso.ru/data/cache/data/47/3b0aa84a2b5c547_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11827,'Запекала в микроволновке пару минут до расплавления сыра.','https://vkuso.ru/data/cache/data/0a/a1a702e82cca80a_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11828,'Посолить, поперчить куски курицы, натереть специями. Залить  в чашу мультиварки масло, переложить курицу, присыпать сверху полукольцами лука, выставить режим «Выпечка», крышку не закрывать, готовить 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11828,'Через 15 минут перевернуть куски и если будет пригорать, то перемешать. После звукового сигнала залить сметаной (майонезом) со специями, добавить лавровый лист и сбрызнуть соком лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11844,'Смазать маслом формы из силикона, на дно выложить любые сезонные ягоды или кусочки сухофруктов, сверху – творожную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11828,'Переключить на режим «Молочная каша», крышку закрыть (время устанавливается автоматически). В этом режиме курица пропитается сметаной и станет такой нежной, что просто будет таять во рту. После сигнала сочная курочка в мультиварке готова, подавать к столу горячей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11829,'Разделить белки и желтки яиц, белки убрать на холод. Залить манку на полчаса кефиром, чтобы набухла. Творог протереть до однородности через сито, добавить желтки и взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11829,'Всыпать к нему разрыхлитель, влить набухшую смесь манки с кефиром и  добавить ванильный сахар, взбить миксером или блендером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11829,'Взбить холодные яичные белки в пышную и крепкую пену, смешать аккуратно с творожной смесью. Всыпать промытый и распаренный изюм, хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11829,'Вылить полученную смесь в смазанную маслом и обсыпанную манкой чашу мультиварки. Выставить режим «Выпечка» и готовить аппетитную творожную запеканку с изюмом в мультиварке 40 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11829,'После сигнала отключить «Подогрев» и дать запеканке постоять минут десять для остывания.  Достать запеканку из мультиварки присыпать сахарной пудрой и подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11830,'Сварить до готовности макароны в режиме «Молочная каша», слить над дуршлагом, остудить. Для начинки поджарить в режиме «Выпечка» фарш, всыпать тертую морковь, кабачок, нарезанный кубиками и нашинкованный лук, переключить в режим «Тушение».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11830,'Готовить 20 минут, подсолить и поперчить, засыпать тертый сыр, перемешать. Переложить начинку в миску и дать чуть остыть. В охлажденные макароны вбить яйца и перемешать. Выложить половину макарон в смазанную маслом и присыпанную сухарями чашу мультиварки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11830,'Разровнять по ее поверхности мясную начинку, прикрыть второй половиной макарон. Выставить режим «Выпечка», запеканка из макарон с фаршем и копченым сыром в мультиварке будет готова через 20 минут, подавать с кетчупом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11831,'Перемешать яйца с сахаром, добавить протертый творог, сливочное масло, сметану, ванилин, манку, разрыхлитель, перемешать, отставить на четверть часа для набухания манки.  Переложить смесь в смазанную маслом чашу мультиварки, выставить режим «Выпечка»',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11831,'Творожная запеканка «Ягодка» в мультиварке будет готова через 45 минут. После сигнала желательно оставить на режиме «Автоподогрев» еще на 15 минут. Дать запеканке чуть остыть, подавать с вареньем, присыпать кокосовой стружкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11832,'Нарезать мясо крупными кусками, обвалять в смеси тмина с черным перцем и солью, дать чуть полежать и пропитаться. Переложить в чашу мультиварки, обжарить на режиме «Выпечка» 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11832,'Нарезать фенхель на тонки полукольца, раздавить чеснок прессом, высыпать все к мясу, добавить лавровый лист и готовить еще (режим не переключать) 2 часа. Свинина запеченная с фенхелем в мультиварке подается с овощами или рисом, а можно и с картофелем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11833,'Корнеплоды отварить, второй способ – запечь до мягкости в духовом шкафу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11833,'Остудить, очистить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11833,'Свеклу натереть, выложить в салатницу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11833,'Перемешать с измельченным чесноком, тертым твердым сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11833,'Соль и майонез – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11834,'Корнеплод завернуть в фольгу, запечь в духовом шкафу до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11834,'Готовый овощ очистить, натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11834,'Грецкие орехи обжарить без масла в течение двух минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11834,'Порубить ножом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11834,'Вымыть чернослив, залить кипятком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11834,'Размягченный сухофрукт нарезать кусочками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11834,'Ингредиенты перемешать вместе с измельченным чесноком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11834,'Приготовить соус из свежего апельсинового сока, соли, молотого перца и бальзамического уксуса.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11834,'По желанию добавить сахарный песок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11834,'Салат заправить полученной смесью, перемешать, подать к столу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11835,'Положить замороженные пельмени в мультиварку, а на них – кусочки сливочного масла. Смешать сметану с кипятком, добавить чеснок из под пресса, влить соевый соус, чуть подсолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11844,'Влить воду в чашу мультиварки, поставить решетку, разместить сырники.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11844,'Выставить режим «Пар» на 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11835,'Залить смесью пельмени, положить листики лаврушки, выставить режим «Выпечка», а время 15 минут (крышку не закрывать). Перемешать через 7 минут, после окончания времени закрыть крышку и готовить еще полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11835,'Разложить пельмени запеченные со сметаной в мультиварке по тарелкам, присыпать тертым сыром и измельченной зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11836,'Отварить свеклу до мягкости, охладить, очистить, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11836,'Сыр также нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11836,'Порубить соленые огурцы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11836,'Добавить рубленую зелень, зеленый горошек из банки, давленый чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11836,'Заправить майонезом, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11836,'Поставить в прохладное место.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11837,'Свеклу отварить, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11837,'Очистить сырую морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11837,'Овощи очистить, нарезать стружкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11837,'Перемешать, добавить рубленый чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11837,'Обжарить на сухой сковороде ядра грецких орехов, порубить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11837,'Вымыть чернослив, залить кипящей водой, дать постоять, затем измельчить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11837,'Все ингредиенты перемешать, посолить, заправить оливковым маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11838,'Отварить морковь, картофель и свеклу в подсоленной воде, отдельно – куриное мясо, яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11838,'Натереть картофель, выложить на тарелку, посолить, намазать майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11838,'В середину тарелки поставить стакан.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11838,'Второй слой – тертая свекла с рублеными грецкими орехами, заправленная майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11838,'Следующий слой – куриное мясо, разобранное на волокна. Промазать майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11838,'Четвертый слой – распаренный чернослив, нарезанный полосками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11838,'Натереть морковь, выложить на чернослив, смазать майонезом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11838,'Соль – по вкусу и желанию.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11838,'Верхний слой – измельченные яйца, перемешанные с майонезом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11838,'Салат украсить гранатовыми зернами.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11838,'Стакан удалить.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11838,'Поставить салат в холодильник на полчаса или чуть больше.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11839,'Отварить свеклу, время – от 35 до 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11839,'Другой способ – запечь корнеплод в духовке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11839,'Измельчить хрен, раздавить чеснок, ингредиенты добавить в свеклу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11839,'Соль – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11839,'Салат можно заправить нежирной сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11840,'Размять в миске обезжиренный творог.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11840,'Вбить сырое яйцо, добавить муку, сахарный песок и соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11840,'Массу хорошо перемешать, в ней не должно быть комков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11840,'Разложить готовое тесто в силиконовые формы для кексов, поставить на поддон, налить в мультиварку воду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11840,'Время приготовления – 10 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11841,'Творог размять вилкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11841,'Всыпать заранее просеянную муку, ванильный и обычный сахар, вбить сырое яйцо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11841,'Массу хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11841,'В нижнюю емкость пароварки влить воду, верхнюю смазать растительным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11841,'Сформовать творожники при помощи ложки, выложить в чашу на расстоянии друг от друга.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11841,'Время приготовления – 25 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11841,'Подать к столу остывшими.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11842,'Удалить у яблок сердцевину, надрезать в середине несколько раз ножом. Смешать в блендере сахар и сметану, всыпать толченые грецкие орехи, залить смесь в серединку яблок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11842,'Переложить яблоки в чашу, выставить режим «Выпечка», через 20 минут яблоки запеченные с грецкими орехами в мультиварке будут готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11843,'Залить маковое семя кипящей водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11843,'Распарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11843,'Отделить желтки от белков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11843,'В миску выложить обезжиренный творог, всыпать распаренный мак, цельнозерновую пшеничную муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11843,'Добавить взбитые белки, соль и ванильный сахар.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11843,'Тесто вымесить руками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11843,'Чашу пароварки смазать маслом, выложить небольшие творожные лепешки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11843,'Готовить от 15 до 20 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11844,'Творог перемешать с яйцом, сахаром, мукой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11845,'Вбить сырое куриное яйцо, добавить соль и сахарный песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11845,'Использовать кухонный комбайн или блендер.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11845,'Сформовать лепешки или шарики, по желанию творожную массу можно выложить в силиконовые формочки для выпечки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11845,'Решетку или чашу мультиварки смазать маслом, поместить изделия.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11845,'Время приготовления – 20 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11845,'В тесто можно добавить любимые ягоды, нарезанные фрукты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11846,'Растереть творог с сахарным песком, всыпать манку и муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11846,'Творожную массу хорошо перемешать, сформовать лепешки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11846,'Варить на пару в течение 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11847,'Ребра хорошо промыть проточной холодной водой, лишний жир удалить, мясо обсушить при помощи бумажного полотенца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11847,'Нарезать крупными кусками или оставить целиком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11847,'В растительное масло выдавить чеснок, всыпать соль, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11847,'Натереть смесью ребра, оставить на 15 или 20 минут для пропитывания, можно оставить на ночь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11847,'Поставить в духовой шкаф, время – 40 минут, температура – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11847,'Ребрышки поливать стекающим соком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11847,'Готовность определяется образованием золотистой корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11847,'Отдельно отварить картофель на гарнир, его можно запечь и сразу с ребрами.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11847,'Другой вариант: картофель и тушеная капуста.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11847,'Без гарнира ребрышки можно подать к пиву.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11848,'Разрезать утку пополам, наколоть их вилкой по всей поверхности. Смешать в блендере распаренную курагу,  мед, соевый соус, апельсиновую цедру и чуть посолить, смазать щедро смесью половинки утки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11848,'Утка с персиками в мультиварке готовится 3 часа на режиме «Тушение». Слить в кастрюльку сок от персиков, нагреть, влить кукурузный крахмал, размешанный в небольшом количестве воды, проварить до густой консистенции, добавить нарезанные персики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11849,'Куски мяса хорошо промыть, смазать любыми пряностями, завернуть в фольгу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11849,'Время запекания мясных кусочков – около часа, температура – 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11849,'За десять минут до готовности блюда фольгу развернуть, допечь ребрышки до образования корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11849,'Можно использовать режим «Гриль».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11850,'Мед прогреть на водяной бане, перемешать с дижонской горчицей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11850,'Натереть ребрышки, дать мясу пропитаться, для этого понадобится несколько часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11850,'Выложить продукт в форму, время запекания – 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11851,'В соевый соус добавить тертый имбирь, чеснок, сок лимона, мед.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11851,'Натереть мясо, дать промариноваться, а затем запечь в духовке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11852,'Шоколад мелко нарубить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11852,'В маленькую кастрюльку добавьте какао, сахар и воду, поставьте на маленький огонь
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11852,'Добавить шоколад, перемешать до однородной массы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11852,'Влить теплое молоко, хорошо перемешать, не доводя до кипения снять с огня.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11852,'Для пенки:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11853,'В маринад для ребрышек добавить чернослив, уксус, «жидкий дым».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11853,'Жарить ребрышки в режиме «Гриль» до образования аппетитной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11854,'Растереть масло с сахаром, вбить яйца, добавить ванилин, взбить до однородного состояния миксером. Натереть корень имбиря, добавить в смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11854,'Постепенно всыпать муку с содой, перемешать. Натереть больше половины шоколада на крупную терку, пересыпать в тесто, добавить изюм, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11854,'Вылить тесто в смазанную маслом чашку мультиварки. Шоколадно-имбирное печенье в мультиварке готовить на режиме «Выпечка» до полного пропекания, посыпать шоколадом. Дать коржу остыть и нарезать на квадратики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11855,'Кусочки мяса натереть любимым маринадом, поставить для пропитывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11855,'Продукт обсушить, выложить в рукав или в пакет для запекания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11855,'Разогреть духовку до 180 градусов. Время тушения – от 40 до 50 минут, температура – 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11855,'За 15 минут до готовности пакет разрезать и дожарить мясо до получения румяной корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11855,'По желанию ребрышки можно запечь одновременно с картофелем, она впитает лишний мясной сок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11856,'Багет, батон или любой другой легкий и воздушный хлеб нарезать кусочками наискосок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11856,'Ломтики смазать сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11856,'Подержать на полной мощности в микроволновой печи. Другой вариант – горячая духовка. Можно обойтись и без термообработки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11856,'Приготовить пасту в блендере из лимонного сока, мякоти авокадо и сливочного сыра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11856,'Намазать ломтики хлеба поверх масла.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11856,'Выложить тонко нарезанную слабосоленую семгу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11856,'Украсить бутерброды тонко нарезанным лимоном, маслинами, листочками зелени.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11857,'Тостерный хлеб обжарить на сковороде с оливковым маслом. Другой способ: сбрызнуть маслом и запечь в духовке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11857,'Выложить ломтики на бумажные салфетки, чтобы впитался лишний жир.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11857,'Авокадо очистить, вынуть косточку, мякоть измельчить блендером или размять вилкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11857,'Пропустить через пресс чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11857,'Добавить в пюре из авокадо вместе с солью и лимонным соком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11857,'Перемешать. Намазать тосты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11858,'Нарезать мясо индейки на кубики, переложить в мультиварку, посолить, поперчить, добавить любимые специи и лавровый лист.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11858,'Положить сверху замороженные овощи, выставить режим «Суп» или «Тушение». Диетические овощи тушеные с индейкой в мультиварке  будут готовы через час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11859,'Хлеб порезать ломтиками, сбрызнуть растительным маслом, посыпать любимыми специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11859,'Подсушить в тостере, в духовке или на обычной сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11859,'Положить в блендер сыр «Рикотта», чеснок, мякоть авокадо, любые орехи или семечки кунжута.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11859,'Смесь превратить в кремообразную массу, посолить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11859,'Заправить майонезом, сушеной зеленью, влить немного винного уксуса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11859,'Получившимся кремом намазать тосты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11859,'Украсить веточками зелени, ломтиками лимона.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11860,'Два кусочка хлеба покрыть майонезом, еще два смазать дижонской горчицей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11860,'Рукколу вымыть и высушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11860,'Выложить на слой майонеза, далее – пластинки копченой курицы, дольки помидоров и порезанное кусочками авокадо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11860,'Накрыть тосты хлебом с горчицей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11861,'Очистить авокадо, мякоть превратить в пюре при помощи блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11861,'Добавить несладкий натуральный йогурт, сок цитруса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11861,'Взбить блендером еще раз.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11861,'Соль и черный молотый перец – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11861,'Хлеб подсушить в духовке или в тостере.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11861,'Смесью покрыть бутерброды, положить листья зеленого салата, хорошо промытые и обсушенные.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11861,'Сырые куриные яйца осторожно разбить в кипящую воду.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11861,'Варить две минуты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11861,'Выложить на тосты.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11862,'Белый хлеб нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11862,'Авокадо освободить от косточки и кожуры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11862,'Нашинковать репчатый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11862,'Ингредиенты положить в чашу блендера, влить оливковое масло и лимонный сок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11862,'Посолить, поперчить, добавить зелень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11862,'Массу взбить в пюре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11862,'Намазать на хлеб.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11863,'Курдючный жир порубить, поместить в казан.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11863,'Обжарить, шкварки вынуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11863,'Нарезать морковь, положить в казан для обжаривания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11863,'Через несколько минут добавить репчатый лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11863,'Овощи жарить до тех пор, пока они не станут золотистыми.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11863,'Баранину порубить на крупные куски, положить к овощам и обжарить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11863,'Посолить, добавить сушеный барбарис, стручок горького острого перца, зиру, специи для плова.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11863,'Влить воду, она должна покрыть продукты полностью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11863,'Варить полчаса.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11863,'Перловку промыть и обсушить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11863,'Насыпать на горячую сковороду и обжарить в течение трех минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11863,'Всыпать в казан, добавить неочищенные зубчики чеснока.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11863,'Потомить плов полчаса.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11863,'Огонь погасить, настоять блюдо в течение 15 минут.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11864,'Нарезать баранину на кусочки, переложить в миску, притрусить мукой, перемешать, обжарить в масле на сковороде до светлой корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11864,'Заполнить чашу мультиварки на треть водой, переложить баранину, задать режим «Тушение» и время 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11864,'Приготовить овощи для рагу из баранины. Обжарить нашинкованный лук, тертый имбирь и чеснок, добавить мелко порезанные помидоры, влить йогурт и уксус, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11864,'Всыпать зеленый горошек, кубики моркови и сельдерея, влить чуть воды, тушить под крышкой 5 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11864,'Переложить овощную смесь к мясу, тушить еще 40 минут, подать рагу по-индейски из баранины в мультиварке украсив листьями кориандра.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11865,'Перловку промыть, затем прокалить на сухой сковороде в течение восьми минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11865,'Лук нашинковать, морковь натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11865,'Куриные грудки пропустить через мясорубку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11865,'Растопить жир на сковороде, добавить овощи, прогревать пять минут, затем положить куриный фарш.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11865,'Соль – по вкусу, жарить, помешивая.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11865,'Всыпать перловую крупу, специи, влить воду. Жидкость должна покрыть продукты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11865,'Положить зубчики чеснока, накрыть крышкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11865,'Блюдо не перемешивать, тушить до тех пор, пока вода не впитается в крупу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11866,'Половину нормы сливочного масла выложить в кастрюлю, прогреть, добавить промытую перловку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11866,'Жарить три минуты, массу постоянно перемешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11866,'Нарезать репчатый лук, стебель сельдерея, порубить грибы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11866,'Вынуть перловку из кастрюли.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11866,'В кастрюлю добавить оставшееся масло, всыпать лук и сельдерей, шампиньоны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11866,'Жарить до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11866,'Положить сверху перловку, влить овощной бульон и обычную воду.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11866,'Довести плов до кипения, всыпать тимьян, черный перец.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11866,'Перемешать, потомить массу в течение часа под крышкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11866,'Порубить свежую зелень петрушки, всыпать в плов и еще раз перемешать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11867,'Мясо нарезать кусками, выложить в чашу мультиварки, выставить режим «Жарка» на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11867,'Нарезать морковь кубиками, репчатый лук – примерно так же.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11867,'Выложить овощи к мясу, томить все вместе восемь минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11867,'Всыпать перловую крупу, соль и специи – по вкусу и желанию.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11867,'Влить воду, выставить режим «Плов».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11867,'Подать блюдо горячим.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11868,'Перловку залить водой, оставить на шесть часов для набухания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11868,'Натереть морковь, нарезать лук, очистить чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11868,'Свинину нарезать кусками и обсушить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11868,'Влить масло в казан, обжарить овощи, добавить мясо и прогревать все вместе 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11868,'Всыпать специи для плова, соль, добавить лавровый лист, ингредиенты перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11868,'Всыпать перловую крупу, влить немного томатной пасты, добавить зубчики чеснока, влить воду.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11868,'Тушить в духовке под крышкой в течение получаса, температура – 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11869,'Замочить крупу в воде на шесть часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11869,'Говядину нарезать кусочками, обжарить в казане на масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11869,'Влить половину нормы воды, тушить час под крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11869,'Нарезать лук и морковь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11869,'Если мясо стало мягким – к нему пора добавлять овощи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11869,'Потушить все вместе семь минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11869,'Влить воду, всыпать специи, посолить, добавить очищенные зубчики чеснока.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11869,'Всыпать перловку, влить воду, продукты должны быть покрыты на сантиметр.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11869,'Укрыть крышкой, тушить до готовности.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11869,'Огонь отключить, настоять блюдо 17 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11870,'Перловку залить водой, подержать семь часов, жидкость слить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12284,'Массу перелить в блендер.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11870,'В сотейник влить растительное масло, всыпать специи, соль, овощи, обжарить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11870,'Нарезать томаты, добавить в обжарку, влить томатную пасту.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11870,'Очистить тыкву, мякоть порубить, добавить в сотейник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11870,'Всыпать перловку, нарезанный сладкий болгарский перец, зубчики чеснока.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11870,'Влить воду. Тушить 17 – 20 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11871,'Хлеб нужно порезать вдоль и вынуть не иного мякоти. Вспрыснуть оливковым масло и обжарить на сохой сковороде, а на другой сковороде обжарим на масле лук и перец (минут 5-7) и добавим сливочное масло.','https://vkuso.ru/data/cache/data/0d/4e19dcf201bb80d_434x295_notrise.jpeg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11871,'Теперь обжарим мясо. Тем временем в посуде смешаем орегано, соль , чеснок, паприку и кумин. Смешаем смесь и добавим к мясу. По готовности мясо добавить моцарелла.','https://vkuso.ru/data/cache/data/1d/4b008ac11b14e1d_434x295_notrise.jpeg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11871,'Соберём сендвич. Нальём японский майонез, порезанный мелко авокадо, смесь лука с перцем и мясо. Сэндвич готов.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11872,'Помытые огурцы разрезать пополам вдоль и осторожно вычистить из каждой половинки мякоть так, чтобы получились этакие «лодочки».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11872,'Изъятую мякоть, укроп и сладкий перец мелко порезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11872,'Очищенный чеснок пропустить через чесночницу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11872,'Сложить в миску все подготовленные ингредиенты, добавить к ним творог.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11872,'Массу посолить, поперчить, тщательно все перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11872,'Получившейся начинкой нафаршировать «лодочки» из свежих огурцов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11873,'Засыпать в ступку перец, горчицу, сахар, соль, можжевельник, хорошо все размять пестиком, перемешать. Подготовленное филе обсушить, обмазать полученной смесью специй, обсыпать мятой с укропом, полить лимонным соком, сбрызнуть маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11873,'Сложить половинки филе вместе, обернуть пленкой, переложить в подходящий по размеру лоток, прижать грузом, отправить в холодильник примерно на двое суток.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11873,'Приготовить соус, смешав все ингредиенты. Достать лоток, освободить рыбу от пленки, нарезать домашний засоленный лосось с соусом из горчицы и укропа наискосок на кусочки, разложить на плоское блюдо, в центре которого поставить пиалу с соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11874,'Для теста растерла желтки с сахаром, добавила сметану, все хорошо смешала. Затем влила заранее растопленный маргарин и добавила соду гашеную уксусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11874,'Чтобы тесто было мягким, муку добавляла постепенно. Оно получается довольно жирным, поэтому форму не смазывала, а просто разровняла по дну.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11874,'Затем абрикосы положила на сырое тесто и присыпала по вкусу сахаром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11874,'Для меренги взбила белки с сахаром, пока не получилась плотная масса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11874,'На абрикосы выложила меренгу и поставила пирог в духовку, разогретую до 180°.  Выпекала до готовности коржа, но при этом следила за белками, чтобы они не подгорели.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11875,'Сначала делаем начинку: лук, оливки и ветчину нарезаем очень мелко, добавляем тертый сыр и сметану - все перемешиваем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11875,'Огурцы очистить от кожицы, нарезаем с помощью овощечистки на тонкие слайсы. Укладываем по 2 слайса с расстоянием друг на друга, на них кладем начинку и заворачиваем рулетиком, скрепляем шпажкой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11876,'Морковь крупно нашинковать, репчатый лук нарезать тонкими полукольцами, дольки чеснока очистить от шелухи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11876,'Мясо промыть, обсушить, нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11876,'В казан налить масло, прогреть, обжарить овощи и мясо, чеснок не добавлять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11876,'Время обжаривания – от шести до семи минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11876,'Всыпать промытый рис.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11876,'Через 15 – 17 минут после начала термообработки добавить соль и специи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11876,'Сверху насыпать крупу, влить воду.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11876,'Потомить блюдо под крышкой до тех пор, пока крупа не впитает в себя всю жидкость.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11876,'Добавить оставшиеся специи, крупу перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11876,'Вдавить головки или зубчики чеснока.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11876,'Потомить плов еще полчаса.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11876,'Далее закрыть казан одеялом, оставить на 20 минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11877,'Нашинковать полукольцами репчатый лук, нарезать брусками морковь, очистить чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11877,'Разогреть курдючный жир, обжарить целую очищенную луковицу до черного цвета, удалить ее из казана.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11877,'Всыпать овощи, обжарить до румяного цвета, добавить сушеный барбарис, кориандр, мясо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11877,'Убавить огонь до среднего, влить кипящую воду, положить острый перец.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11877,'Потомить один час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11877,'Насыпать рис, влить подсоленный кипяток, уровень должен быть выше продуктов на палец.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11877,'Тушить до впитывания влаги.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11877,'Положить чеснок, в рисе сделать отверстия, оставить на тихом огне на 25 минут под крышкой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11878,'Рис сорта «Жасмин» промыть и отварить до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11878,'Куриное мясо освободить от костей, нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11878,'Морковь нарезать соломкой, лук – кольцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11878,'Плоды айвы разрезать на шесть или восемь частей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11878,'Промыть урюк горячей водой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11878,'Разогреть масло, обжарить целую луковицу до черноты, выбросить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11878,'Обжарить мясо с овощами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11878,'При готовности моркови всыпать в казан соль, специи, урюк и айву, влить кипяток.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11878,'Потомить блюдо на тихом огне в течение часа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11878,'Всыпать рис, разровнять.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11878,'Влить еще часть кипятка, уровень жидкости должен быть выше рисового слоя на два сантиметра.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11878,'Готовить на сильном огне до испарения и впитывания жидкости.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11879,'Подготовить грудку, освободить от кожи, порезать на кусочки, обжарить до появления золотистого колера. Удалить кожуру и косточки у крупного яблока, порезать на кубики. Разрезать зеленый болгарский перец пополам, убрать семечки, нарезать на такие же кубики. Нашинковать зеленые перья от одной луковицы вместе с белой частью, смешать с перцем и яблоком. Высыпать смесь в сковороду к курице, тушить 3-4 минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11879,'Залить в высокий стакан миксера соевый соус, сухое белое вино, томатный кетчуп, всыпать сахар, взбить до полного его растворения. Полученный соус вылить в сковороду с мясом, готовить 10 минут, приправить черным перцем, подсолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11879,'Приготовить по следующему рецепту рассыпчатый рис для гарнира. Промыть хорошо рис (стекающая вода должна стать прозрачной), сварить в соленой воде до мягкости снаружи и легкого похрустывания зерен внутри, воду сцедить, рис чуть промыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11879,'В кастрюлю залить воду примерно на 4 см по высоте, влить пару ложек масла, дать закипеть, всыпать горкой рис (вода должна покрыть его до половины). Прикрыть кастрюлю крышкой, дождаться пара, выложить на рис немного сливочного масла, обернуть вокруг крышки тканевое полотенце.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11879,'Прикрутить огонь до минимума, томить четверть часа. Все, курица в кисло-сладком соусе с рассыпчатым рисом для гарнира готовы, подать блюдо пока оно горячее, в качестве украшения его уже в тарелке можно дополнить несколькими кусочками свежих овощей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11880,'Разогреть масло, обжарить кусочки говядины среднего размера, нарезанный кубиками лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11880,'Всыпать морковь, нашинкованную соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11880,'Продукты накрыть крышкой, потомить 15–16 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11880,'Выложить рис, посолить, добавить приправы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11880,'Влить горячую воду, уровень должен быть на сантиметр выше риса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11880,'Тушить до полного впитывания влаги.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11881,'Нут замочить на ночь в холодной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11881,'Разогреть масло в казане, обжарить нарезанную морковь, полукольца лука, ломтики любого мяса, обсушенные бумажным полотенцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11881,'Тушить все вместе под крышкой в течение получаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11881,'Отдельно отварить рис в подсоленной воде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11881,'Насыпать в казан специи и соль, через 12 минут добавить рис.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11881,'Влить горячую воду, выложить нут, головку чеснока без шелухи. Жидкость должна покрыть продукты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11881,'Готовить все вместе до впитывания жидкости.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11882,'Мясо птицы нарезать кусками среднего размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11882,'Нарезать лук и морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12284,'Другой вариант – взбить венчиком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11882,'Разогреть масло в казане, обжарить лук, затем добавить морковь и индейку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11882,'Все вместе потомить шесть или семь минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11882,'Массу посолить, посыпать специями, потушить еще несколько минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11882,'Высыпать поверх зирвака заранее промытый рис.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11882,'Вдавить головки чеснока без шелухи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11882,'Влить кипяток, он должен покрыть продукты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11882,'Тушить плов до впитывания жидкости.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11883,'С ног птицы удалить жир, прогревать его до шкварок в казане.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11883,'Добавить оливковое масло, шкварки удалить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11883,'В хорошо прогретой смеси обжарить нашинкованную морковь, нарезанный полукольцами репчатый лук, мясо с костей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11883,'При готовности овощей в казан добавить зиру и барбарис, головку чеснока, воду. Соль – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11883,'Жидкости должно быть достаточно, массу прогревать полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11883,'Насыпать поверх хорошо промытый рис.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11883,'Влить еще литр кипящей воды с солью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11883,'Прогревать плов до готовности, не перемешивать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11883,'После испарения влаги томить блюдо на тихом огне еще 17 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11883,'Снять блюдо с огня, хорошо перемешать и подать к столу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11884,'В чашу миксера влить кефир, всыпать сахар, разрыхлитель, муку, вбить пару яиц, добавить мед, как следует взбить. Разделить полученную смесь поровну на две части, выпечь из каждой по коржу, каждый разрезать потом вдоль, в результате получается 4 тонких коржа, дать им полностью остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11884,'Порубить в блендере курагу, изюм, чернослив, отдельно – обжаренный миндаль в мелкую крошку, но не в сильно мелкую, перемешать. В сметану всыпать сахар, взбить до полного его растворения. Сильно охлажденный шоколад измельчить на мелкой терке, всыпать четверть крошки миндаля, смесь использовать для окончательного оформления торта.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11884,'Нанести на корж крем, равномерно разровнять по всей поверхности, сверху присыпать слоем орехов, накрыть вторым коржом со слоем сухофруктов. Полить прослойку на втором корже кремом, присыпать орехами, накрыть следующим коржом. Распределить по его поверхности крем с орехами, накрыть последним коржом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11884,'Оформить верх очень простого торта «Выпускной» остатками крема и шоколадной стружкой с орехами. Дать десерту «вызреть», пусть постоит несколько часов, чтобы стал нежным и мягким, убрать в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11885,'Очищенный лук нарезать полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11885,'Нарезать морковь длинной соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11885,'Свинину нарезать кусками среднего размера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11885,'Поставить на плиту казан, влить масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11885,'Прожарить несколько лепестков лука до получения коричневого оттенка, овощ выбросить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11885,'Добавить нарезку, подрумянить, положить мясо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11885,'Влить горячую подсоленную воду, всыпать специи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11885,'Все вместе тушить полчаса.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11885,'Всыпать хорошо промытый рис сортов «Басмати» или «Жасмин».',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11885,'В нескольких местах воткнуть неочищенный чеснок.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11885,'После частичного выпаривания жидкости, рис собрать горкой, прикрыть тарелкой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11885,'Далее блюдо готовить еще 15 или 17 минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11886,'Баранину нарезать небольшими кусками, посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11886,'Растительное масло налить в казан, довести до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11886,'Положить мясо, обжарить до появления корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11886,'Очистить и нарезать репчатый лук, добавить к мясу, тушить все вместе.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11886,'Нарезать морковь соломкой, положить в казан.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11886,'Рис хорошо промыть, лучше использовать длиннозерновые сорта.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11886,'Размять зиру в ступке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11886,'Влить в казан кипящую воду, всыпать соль, зиру, неочищенный чеснок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11886,'Смесь потушить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11886,'При готовности моркови чеснок вынуть и выбросить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11886,'Выложить рис, влить еще часть горячей воды, жидкость должна покрыть рис.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11886,'Варить при открытой крышке до испарения жидкости.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11886,'Рис собрать горкой.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11887,'Баранье сало нарезать, положить в казан и обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11887,'Мясо нарезать небольшими кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11887,'Сало вынуть, положить мясо в натопившийся жир, прогревать до получения аппетитной корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11887,'Лук нарезать, добавить в мясо, обжарить все вместе.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11887,'Измельчить морковь, также поместить в казан.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11887,'Добавить любые пряности: ажгон, красный молотый перец, барбарис.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11887,'Промыть рис, выложить поверх обжарки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11887,'Осторожно влить воду, рис должен быть покрыт на два сантиметра.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11887,'Тушить под крышкой до полной готовности, не перемешивать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11888,'Включить для прогрева до 200 градусов духовой шкаф. Подготовить филе от одной курицы, каждое разрезать пополам, должно получиться четыре стейка. Аккуратно отбить каждый, присолить, сдобрить черным свежемолотым перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11888,'Прессом для чеснока раздавить в кашицу пару зубчиков, обмазать стейки, дать чуть постоять, переложить их в керамическую форму. Подготовить овощи для запекания, помыть, почистить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11888,'Морковь измельчить на средней терке, лук — на мелкие кубики, кабачок – тонкими брусочками. Нарезать сладкий красный перец небольшими кусочками, черри – на четвертинки, добавить кусочки стручковой фасоли.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11888,'Все овощи объединить в  большой миске, перемешать, подсолить, еще раз аккуратно перемешать, выложить на мясо, присыпать сырной стружкой, влить по краям небольшое количество воды.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11888,'Убрать форму в уже прогретый духовой шкаф, стейки из куриного филе с овощами под сыром будут готовы примерно через 40 минут, достать блюдо, дать чуть остыть, на стол подать прямо в форме.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11889,'Баклажан не отрезая хвостик, нарезаю тонкими пластинами не до конца.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11889,'Кабачок нарезаю таким же способом. Куриное филе нарезаю на тонкие пластины вдоль филе, помидоры кружочками.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11889,'Овощи выкладываю на смазанный маслом противень, кабачки солю, баклажан нет, т. к он был в соленой воде, на каждую пластину выкладываю мясо и помидоры, формирую веер и отправляю в разогретую духовку на 50-60 мин, за 5 минут до окончания приготовления овощи посыпаю натертым сыром. Блюдо горячим подаю на стол.','https://vkuso.ru/data/cache/data/d4/efc2f8a8b0d85d4_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11890,'Первым делом подготовим ингредиенты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11890,'Салями нарезаем полукольцами',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11890,'Копченое мясо для бутербродов ( или же ветчина) нарезаем ломтиком, и потом пополам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11890,'Сыр натираем на мелкой терке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11890,'Слоеное тесто, немного раскатываем и режим на равные части.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11890,'Берем ломтик теста, посыпаем чесноком, укладываем копченое мясо для бутербродов (или же ветчину), и посыпаем сыром, и заворачиваем в конвертик, и сжимаем по краям.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11890,'Снова берем ломтик теста, посыпаем чесноком, но уже укладываем салями, после этого посыпаем сыром, и заворачиваем в конвертик, и сжимаем по краям.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11890,'Все это перекладываем на противень и смазываем взбитым куриным яйцом, и отправляем в духовку при 200 С на 15-20 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11891,'Разморозьте вишню.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11891,'Сливочное масло комнатной температуры перетереть с сахаром, добавить яйца, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11891,'Добавить хлопья, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11891,'Добавить муку и разрыхлитель, перешешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11891,'Добавить вишню, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11891,'Выложить тесто в форму для выпечки. Выпекать 50-55 мин. при 180 С.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11891,'Дайте кексу остыть, затем выньте его из формы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11892,'Мякоть свинины хорошо вымыть, зачистить от пленок, обсушить, порезать на ломти (примерно по 1 см толщиной), отбить каждый, присыпать перцем с солью, дать немного постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11896,'Вынуть сочный и вкусный тортик на плоское блюдо, подать его на стол горячим. Если гости не справятся, что мало вероятно, то остаток можно доесть холодным на следующий день: будет тоже вкусно.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11892,'Почистить луковицы, разрезать пополам, нашинковать на полукольца, если луковицы мелкие, то можно —  кольцами. Подготовить противень, выстлать фольгой, слегка смазать маслом, разложить ломти мяса, прикрыть слоем лука, сверху – майонезом, присыпать стружкой сыра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11892,'Задвинуть противень в духовку с температурой около 180 градусов, очень вкусная свинина под сыром будет готова примерно через 25 минут, дать постоять четверть часа. Мясо разложить по тарелкам, посыпать зеленью, подать пока горячее.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11893,'Морковь нарезать соломкой, репчатый лук нашинковать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11893,'Баранину нарезать порционными кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11893,'Влить растительное масло в чашу, обжарить морковь, лук, добавить мясо, соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11893,'Рис хорошо промыть, воду менять несколько раз, всыпать в чашу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11893,'Добавить специи, влить подсоленную воду.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11893,'Сверху выложить чесночные зубчики и нарезанный сладкий болгарский перец.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11893,'Выставить режим «Плов» или «Тушение» на час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11894,'Нут залить водой, оставить для набухания на два часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11894,'Рисовые зерна хорошо промыть, оставить в воде на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11894,'С баранины срезать прожилки, мясо нарезать кубиками со стороной в три сантиметра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11894,'Морковь нарезать соломкой, репчатый лук – кольцами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11894,'В казане довести до кипения подсолнечное масло, обжарить лук до золотистой корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11894,'Добавить мясо, соль, жарить на сильном огне.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11894,'Добавить морковь, жарить все вместе еще пять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11894,'Влить воду, положить стручок острого перца чили.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11894,'Всыпать набухший нут, зубчики чеснока, добавить соль.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11894,'Варить все вместе 15 минут, перец и чеснок вынуть.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11894,'Выложить рис, в центре плова сделать отверстие для выхода пара.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11894,'Тушить полчаса.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11894,'Перец и чеснок вернуть в плов, тушить блюдо еще полчаса.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11895,'Нарезать морковь тонкой соломкой, лучше выбрать зрелые и крупные корнеплоды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11895,'Репчатый лук измельчить кольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11895,'Курдючное сало мелко порубить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11895,'Прогреть казан, положить сало, вытопить до получения шкварок, их нужно вынуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11895,'В казан добавить кунжутное и подсолнечное масло, смесь прокалить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11895,'Выложить баранину, посолить по вкусу, добавить репчатый лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11895,'Все вместе обжарить до золотистой корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11895,'Выложить морковь, массу не перемешивать, тушить 15 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11895,'Всыпать специи для плова: зиру, кориандр, неочищенный чеснок, сушеный барбарис.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11895,'Влить кипящую воду, она должна покрыть продукты полностью.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11895,'Тушить сорок минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11895,'Рис промыть, выложить в подогретую воду, всыпать соль, подержать 30 минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11895,'Выложить рис на морковь, влить кипяток, сделать это аккуратно, слои продуктов должны сохраниться.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11895,'Тушить 15 минут. Жидкость должна полностью испариться.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11895,'Сформовать горку, сделать отверстия в рисе в нескольких местах для выхода пара.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11895,'В центр выложить стручок острого перца, блюдо тушить около 15 минут.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11896,'Порезать на куски грудку курицы, сложить в чашу блендера, слегка размолоть, всыпать перец, соль, перемолоть до состояния фарша.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11896,'Разрезать сладкий перец пополам, вынуть семена, измельчить на тонкие полоски, пересыпать в сковороду, потушить при малом нагреве, дать остыть. Порубить базилик, зеленый лук, кинзу, шпинат, укроп.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11896,'Взбить блендером белки яиц с творогом и молотой паприкой. Заполнить фаршем круглую форму, разровнять его и сделать бортики. По всей поверхности мяса разложить мягкие перцы, далее – слой шпината, потом – смесь из зелени, аккуратно залить «Торт» из курицы и шпината творожной массой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11896,'Поставить форму в духовой шкаф, запекать блюдо при 220 градусах примерно треть часа. Начинать готовить на нижней полочке духовки, затем переставить на верхнюю для образования корочки приятного золотистого колера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11897,'Вымесить из воды и муки с солью тесто (месить пока не станет отлипать от рук), дать ему полежать под тканевым полотенцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11897,'Сварить картофель, размять в пюре, обжарить с маслом тертую морковь с луком, объединить с картофелем (часть зажарки оставить), всыпать мелко измельченную зелень, сдобрить солью, перцем, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11897,'Раскатать тесто в тонкий пласт, вырезать рюмкой, подходящего диаметра кружочки, положит на каждый ложку начинки, тщательно защипать края, иначе внутрь попадет вода, и вкус вареников с картофелем, морковью и луком значительно пострадает.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11897,'Сварить в кипятке вареники, после закипания варить минут 7-8 (зависит от размера и толщины сочней), вынуть на блюдо, уложить сверху лук с морковью и зелень',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11898,'Баранину очистить от пленок, мясо порубить кусками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11898,'Разогреть подсолнечное масло, обжарить мясо до получения корочки, продукт посолить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11898,'Нашинковать репчатый лук, нарезать морковь, добавить сушеный барбарис, красный острый перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11898,'Продукты залить подогретой водой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11898,'Все вместе тушить полтора часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11898,'Промыть изюм без косточек, добавить в казан, всыпать рис.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11898,'Долить воду, если есть такая необходимость, посолить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11898,'Тушить полчаса, дать постоять.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11899,'Нашинковать пару зубков чеснока и лук, обжарить до изменения цвета. Нарезать болгарский перец в форме лапши, грибы – на пластинки, высыпать к чесноку и луку, обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11899,'После того, как грибы будут мягкими влить соевый соус, перемешать, тушить пару минут, оставить рядом с плитой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11899,'Сварить спагетти, высыпать в дуршлаг, дать хорошо стечь воде, переложить в тарелку , сверху выложить грибы, присыпать зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11900,'Ребра разрезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11900,'Морковь нашинковать соломкой, репчатый лук – кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11900,'В казан влить масло и прокалить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11900,'Добавить ребра, прожарить и посолить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11900,'Добавить лук, жарить до золотисто-коричневой корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11900,'Положить морковь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11900,'Влить воду, жидкость должна полностью покрыть продукты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11900,'Добавить неочищенные зубчики чеснока.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11900,'Всыпать перец, зиру, барбарис.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11900,'Промыть рис, добавить в общий котел, не перемешивать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11900,'Долить воду, ее уровень должен быть выше риса.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11900,'Тушить плов под крышкой до готовности.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11900,'Блюдо оставить на полчаса для настаивания, затем подать на стол.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11901,'Мясо двух сортов вымыть, удалить прожилки, филе нарезать кусками и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11901,'Репчатый лук крупно нарезать, морковь нашинковать брусками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11901,'В казан влить масло, прогреть, добавить мясо, жарить до корочки, посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11901,'Добавить и спассеровать репчатый лук, затем – морковь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11901,'Всыпать барбарис, куркуму, зиру, лавровый лист.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11901,'Влить воду, все вместе тушить полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11901,'Рис промыть, выложить в казан к остальным продуктам.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11901,'Если есть необходимость – добавить воду, соль.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11901,'Выложить чеснок, продукты тушить полчаса под крышкой. Жидкость должна впитаться, как только это произойдет – огонь отключить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11901,'Подержать плов под крышкой в течение 15 или 20 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11902,'Существует не менее трехсот рецептов этого вкусного и сытного кушанья.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11902,'Куриные ножки вымыть и обсушить салфетками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11902,'Шкурку снять, ножки разрубить пополам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11902,'Разогреть оливковое масло на сковороде, обжарить птицу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11902,'Нарезать лук, чеснок, овощи добавить на сковороду, жарить пять или семь минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11902,'Соленые помидоры очистить от кожицы, нарезать кубиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11902,'Покрошить сладкий болгарский перец.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11902,'Продукты добавить на сковороду, подержать на тихом огне до испарения влаги.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11902,'Приправить специями, всыпать заранее промытый рис, жарить все вместе семь или восемь минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11902,'Долить куриный бульон, паэлью варить на среднем огне полчаса, помешивать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11902,'В конце приготовления огонь увеличить на две минуты до максимального.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11903,'Сварить филе курицы в небольшом количестве воды, дать остыть (лучше прямо в бульоне), порезать небольшими кубиками. Залить нашинкованный полукольцами лук на 10 минут крутым кипятком, сцедить, промыть холодной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11903,'Отварить и остудить яйца, белки и желтки по отдельности измельчить в мелкую стружку, сыр — на такой же терке. Яблоки натереть на средней терке, орехи измельчить до состояния мелкой крошки (несколько штук оставить целиком).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11903,'Для салата нужно взять плоское блюдо, овалом выложить белки, чуть присолить, промазать майонезом. Следующим слоем положить курятину и тоже промазать майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11903,'Далее выложить полукольца лука, потом стружку яблока, и майонез. Прикрыть слоем сыра (оставить столовую ложку) с майонезной прослойкой. Завершить слоем из желтков и майонеза, присыпать ореховой крошкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11903,'Приставить к горке салата с куриной грудкой «Черепаха» яйцо – это будет голова, глаза сделать из горошков черного перца или бутончиков гвоздики. Из оставленных целыми орехов сделать лапки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11904,'Сыр «тофу» нарезать кубиками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11904,'Налить на сковороду оливковое масло, прогреть, обжарить сыр до получения корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11904,'Грибы промыть, очистить, нарезать такими же кусочками, как и сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11904,'Выложить на сковороду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11904,'Коричневый рис отварить до полуготовности в подсоленной воде.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11904,'Развести шафран в небольшом количестве воды, влить в емкость с рисом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11904,'Нарезать кружочками морковь, покрошить репчатый лук, переложить вместе со специями на сковороду с остальными продуктами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11904,'Всыпать консервированную кукурузу в сковороду, нарезанные помидоры, измельченный или пропущенный через пресс чеснок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11904,'Добавить бульон и рис.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11904,'Тушить все вместе под крышкой в течение 15 минут. Жидкость должна полностью выпариться.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11904,'Сверху насыпать консервированный горошек, прогреть под крышкой две минуты.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11904,'Блюдо снять с плиты, посыпать измельченным зеленым луком, сбрызнуть свежим лимонным соком.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11905,'Отварить королевские креветки в подсоленной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11905,'Отдельно отварить мидии, время – от пяти до шести минут до момента открытия.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11905,'Бульоны процедить, смешать и приправить по вкусу шафраном.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11905,'На сковороду налить масло, всыпать нарезанный лук и чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11905,'Зеленый перец и очищенные помидоры нарезать кубиками',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11905,'Всыпать кольца кальмаром, потушить до выпаривания жидкости.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11905,'Добавить рис, жарить от семи до десяти минут, помешивать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11905,'Влить жидкость, варить 20 минут на тихом огне, бульон можно добавлять по необходимости.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11905,'Красный перец нарезать соломкой, порубить петрушку, всыпать ингредиенты в основную массу вместе с горошком и мидиями.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11906,'Растительное масло прогреть на сковороде, длиннозерный рис обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11906,'Влить бульон, посолить по вкусу, варить все вместе до выпаривания жидкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11906,'Нарезать кубиками куриное филе, заправить измельченным луком и специями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11906,'Сладкий болгарский перец нарезать, пересыпать к мясу, жарить от семи до десяти минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11906,'Ингредиенты перемешать, всыпать консервированный горошек, прогреть до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11907,'Обжарить кубики лука на масле до изменения цвета на золотистый, добавить тертую морковь, соломку болгарского перца, приправить молотым перцем, присолить, перемешать, слегка обжарить, добавить пару-тройку порубленных зубчиков чеснока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11907,'Макароны проварить после закипания пару минут, сцедить, перемешать с маслом. Мясо курицы порезать на небольшие кусочки. Смешать молоко с яйцами, всыпать измельченный сыр, зелень, соль (желательно мелкого помола), перец, хорошо взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11920,'Очистить и нарезать любым способом морковь, репчатый лук, чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11907,'Выложить ингредиенты запеканки из макарон с овощами и куриным мясом в форму в следующем порядке. Первым слоем будет макаронный, затем овощной и последний мясной, залитый яично-молочной смесью. Отправить форму на полчаса в духовку температурой 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11908,'Куриное филе промыть и нарезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11908,'Сладкий болгарский перец покрошить точно так же.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11908,'Прогреть растительное масло в сотейнике, обжарить лук и чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11908,'Добавить куриное мясо, обжарить до получения корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11908,'Всыпать перец, горошек, креветки, рис, влить бульон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11908,'В небольшом количестве воды развести шафран и куркуму.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11908,'Перелить в основную массу, тушить под крышкой в течение 45 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11908,'Готовое блюдо украсить отваренными тигровыми креветками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11909,'Кальмары отварить в течение двух или трех минут в подсоленной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11909,'Мидии промыть, креветки очистить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11909,'Влить растительное масло в чашу мультиварки, выставить режим «Жарка».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11909,'Раздавить чеснок, добавить в масло для аромата.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11909,'Через две минуты его можно выбросить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11909,'Добавить морепродукты, соль.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11909,'Прогреть, через три или четыре минуты влить белое вино, тушить пять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11909,'Нарезать кольцами кальмары, добавить в чашу мультиварки вместе с обжаренным чесноком, прогревать две минуты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11909,'Перец очистить от кожицы, нарезать соломкой, добавить к остальным продуктам вместе с нарезанными кубиками томатов и покрошенным репчатым луком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11909,'Долить масло, жарить пять минут, посолить по вкусу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11909,'Промыть рис, всыпать в мультиварку, обжаривать до полупрозрачности.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11909,'Влить воду, всыпать специи. Выставить режим «Плов» на сорок минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11910,'Сварить филе курицы (не более трети часа после закипания), дать остыть прямо в бульоне. Отварить пару яиц вкрутую, дать им полежать в кастрюле с холодной водой. Луковицы разрезать на четвертинки, тонко нашинковать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11910,'Ветчину порезать на аккуратные тонкие брусочки. На такие же брусочки нарезать остывшую курятину без кожи, покрошить яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11910,'Переложить яйца, опята, лук, ветчину в глубокую миску, сдобрить черным перчиком, майонезом, подсолить, хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11910,'Выложить листьями салата большую плоскую тарелку, переложить на него салат «Мужская мечта» с куриным филе, оформить верх закуски кусочками помидоров.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11911,'Разрезаем перец на несколько частей и отправляем в разогретую духовку на температуру 200 градусов на 30-35 мин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11911,'Баклажаны нарезаем пластинами вдоль примерно по 0,7-0,8 см.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11911,'Каждую пластинку баклажанов смазываем растительным маслом и обжариваем с обеих сторон на сухой сковороде. В процессе обжаривания солим по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11911,'Перец извлекаем из духовки, складываем в отдельную тарелку и закрываем пищевой пленкой и оставляем на 10 мин. По истечению указанного времени снимаем с перца кожицу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11911,'Нарезаем пластинками сыр и измельчаем зелень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11911,'Подготовим форму: Я использую одноразовую форму для выпечки емкостью 900 мл. Смочив ее внутри водой, чтобы пищевая пленка плотно прилипла к стенкам формы, выстилаю ее пленкой, оставляя края пленки свисать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11911,'Собираем террин: выкладываем баклажаны веером, внахлест друг на друга, оставляя их края свисать с формы. В произвольной последовательности, выкладываем слоями остальные ингредиенты, чередуя их по цвету. Самым верхним слоем должны оказаться концы баклажанов, которые свисали с формы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11911,'Накрываем террин свисающими концами пленки. Сверху помещаем гнет и отправляем форму с террином в холодильник на ночь.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11911,'Извлекаем террин из формы и перед подачей нарезаем кусочками.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11912,'У огурца снять шкурку, порезать тоненькими брусочками, высыпать в салатник. Филе подкопченной курицы освободить от кожи, порезать на куски, а потом разобрать на волокна, соединить с огурцами, добавить нашинкованный укроп.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11912,'Сладкий красный перец разрезать пополам, убрать семена, порезать на кусочки, помидор – на такие же по размеру кусочки, добавить несколько ложек консервированной кукурузы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11912,'Сдобрить салат с копченым окороком «Парижель» майонезом, свежемолотым перцем, подсолит по вкусу, аккуратно и тщательно перемешать, сформовать в виде горки, оформить веточками укропа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11913,'Печенье нужно измельчить в крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11913,'В миску перекладываем творог, и туда же ломаем бананы, и добавляем сахар. Все это хорошо перемешиваем.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11913,'Постепенно к творожно-банановой массе добавляем песочную крошку, и снова все хорошо замешиваем.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11913,'Как только все замешали, берем немножко массы и катаем шарик, после этого посыпаем его в кокосовой стружке, перекладываем на тарелку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11913,'Отправляем в холодильник, на 25 минут, что бы десерт немного застыл.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11913,'После чего вынимаем и подаем к чаю.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11914,'Творог перемешать с сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11914,'Добавить муку, вымесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11914,'Сформировать колбаску из теста, нарезать кружочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11914,'Разогрейте масло в сковороде на средне-сильном огне.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11914,'Перевернуть, накрыть крышкой, жарить на слабом огне 8-10 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11915,'Достать заранее яйца, взбить вместе с сахаром, добавить пару-тройку ст.л. меда, взбить еще раз. Перемешать муку, какао и разрыхлитель, добавить орехи и взбитые яйца, замесить тесто, вылить его в подготовленную форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11915,'Выпекать около 40 минут (не открывать духовку 25 минут) при температуре печи примерно в 170 градусов. Готовность несколько раз проверить зубочисткой. Достать корж, остудить, разрезать вдоль на несколько коржей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11915,'Пока остывает бисквит приготовить крем: всыпать сахар в сметану, хорошо смешать, чтобы в сметане не осталось его крупинок. Измельчить  размоченный чернослив, порезать бананы на кружочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11915,'На большую плоскую тарелку положить корж, распределить по его поверхности равномерно сладкую сметану, выложить сверху на нее чернослив. Прикрыть вторым коржом, также промазать кремом, выложить кружочками банана.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11915,'Уложить сверху оставшийся корж, промазать сметаной, присыпать бисквитной крошкой, оформить по своему усмотрению. Дать тортику с черносливом и бананом постоять, стать более мягким, для этого хватит пару часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11916,'Смешать в одной посуде все ингредиенты, вылить в подготовленную высокую прямоугольную форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11916,'Готовить кекс «Снежинка» со сгущенкой примерно 20-30 минут в духовом шкафу с температурой в 190 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11917,'Очистить и нарезать белые грибы, сладкий болгарский перец, репчатый лук, куриную грудку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11917,'Ингредиенты обжарить на сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11917,'Всыпать гречку, влить томатную пасту, заранее сваренный грибной бульон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11917,'Добавить любимые специи, прогревать все вместе пять или семь минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11917,'Прогреть духовой шкаф до 190 градусов, время приготовления паэльи – от десяти до пятнадцати минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11918,'Зубчик чеснока нарезать, обжарить на сковороде со сливочным маслом, затем убрать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11918,'Натереть морковь, выложить на ту же сковороду, жарить две минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11918,'Добавить нарезанное на небольшие кубики куриное филе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11918,'Всыпать рис.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11918,'Влить вино.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11918,'Прогревать ризотто до выпаривания жидкости.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11918,'Влить бульон порционно, всыпать специи, тертый сыр.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11918,'Прогреть и подать на стол.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11919,'Отварить макароны в подсоленой воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11919,'Масло растопить в кастрюльке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11919,'Добавить муку быстро перемешать венчиком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11919,'Небольшими порциями введите молоко, постоянно помешивая.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11919,'Варить до тех пор, пока соус не загустеет. Посолить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11919,'В миске смешать вареные макароны, соус и сыр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11920,'Выставить режим «Выпечка» на десять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11920,'Промыть и нарезать кубиками куриное мясо, добавить в обжарку, прогревать все вместе двадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11920,'Всыпать рис, любые приправы, влить бульон или воду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11920,'Потушить сорок минут, режимы «Каша», «Гречка» или «Плов».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11921,'Куриное мясо нарезать кубиками, подержать на огне до золотистого цвета, масло – оливковое.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11921,'Очистить и нарезать сладкий болгарский перец, помидоры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11921,'Обжарить репчатый лук отдельно, перемешать с бульоном и рисом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11921,'Дождаться впитывания бульона, всыпать специи, положить овощи, все вместе тушить пять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11921,'Перемешать с курицей, подать на стол.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11922,'Репчатый лук нарезать, обжарить со сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11922,'Добавить куриное филе, все вместе жарить еще две минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11922,'Всыпать рис, влить белое вино, дождаться выпаривания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11922,'Грибы нарезать пластинками, перемешать с рисом, влить бульон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11922,'Прогревать до выпаривания жидкости.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11922,'Всыпать специи по вкусу и желанию.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11922,'Посыпать тертым сыром, добавить кусочек сливочного масла.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11923,'Филе курицы обмыть, удалить кожу, обсушить, порезать на полоски, подрумянить их на разогретой сковороде с небольшим количеством масла до полной готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11923,'Сварить в соленой воде мороженую стручковую фасоль, но переваривать нельзя (она должна остаться чуть-чуть твердоватой), сцедить, дать обсохнуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11923,'Перец разрезать, вынуть семена, нарезать на полоски, лук нашинковать, обжарить все в сковороде, где жарили мясо до мягкости,  засыпать фасоль при малом нагреве готовить минут 5-7, добавить мясо, перемешать, прогреть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11923,'Переложить теплый салат из куриного филе и стручковой фасоли в глубокий салатник. В миску влить бальзамический уксус, горячую воду, подсолить, приправить молотым перцем, сухим укропом, перемешать, вылить к салату, аккуратно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11924,'Очистить репчатый лук и морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11924,'Лук нарезать, морковь натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11924,'Выложить на сковороду со сливочным маслом репчатый лук, жарить до румянца, всыпать тертую морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11924,'Жарить овощи пять минут, добавить кубики куриного филе.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11924,'Всыпать рис, влить вино, подержать на огне до впитывания и выпаривания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11924,'Всыпать любимые приправы, влить бульон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11924,'Довести блюдо до готовности, положить кусочек сливочного масла.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11925,'Смешаем соус цезарь и острый соус с Максом салатов','https://vkuso.ru/data/cache/data/13/b25bada5ce42213_434x295_notrise.jpeg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11925,'Возьмём две тарелки . В одну добавим муку, соль, перец и перемешаем. Во вторую сливки, острый соус , паприку и перемешаем. Теперь обваляем курицу сначала в сливках, потом в муке. И начнём жарить во фритюре','https://vkuso.ru/data/cache/data/bb/55588a5253ac9bb_434x295_notrise.jpeg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11925,'На сковороде разогреем тортилью и положим два кусочка сыра','https://vkuso.ru/data/cache/data/09/9e2778d5ddeb509_434x295_notrise.jpeg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11925,'Начнём собирать буррито. Кладём на сыр курицу и салат. Можно после обжарить с двух сторон','https://vkuso.ru/data/cache/data/4a/86da1ec520e174a_434x295_notrise.jpeg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11926,'Готовим маринад: смешиваем лимонный сок, мед, корицу, имбирь, соль, растительное масло до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11926,'В бедрышках делаем проколы, чтобы маринад их лучше пропитал.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11926,'Заливаем курицу маринадом и оставляем мариноваться 1-1,5 часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11926,'Помещаем курицу в форму для запекания, смазанную растительным маслом, посыпаем кунжутом и накрываем форму фольгой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11926,'Отправляем курицу в разогретую духовку на температуру 200 градусов на 20 минут, через 20 минут фольгу снимаем и снова отправляем в духовку до зарумянивания, примерно на 15-20 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11927,'На одну сковороду положить сливочное масло, пропущенный через пресс чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11927,'Влить сливки, прогреть две или три минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11927,'В другую сковороду положить репчатый лук, куриное мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11927,'Продукты обжарить до золотистого цвета, всыпать рис, специи, влить вино.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11927,'Прогревать до впитывания жидкости.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11927,'Перелить сливочный соус, потушить три или четыре минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11927,'Подать к столу горячим.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11928,'Сковороду прогреть, растопить сливочное масло, обжарить чеснок, затем его выбросить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11928,'Добавить репчатый лук, куриное мясо, измельченное кубиками, довести продукты до румянца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11928,'Всыпать рис, влить вино, дать жидкости впитаться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11928,'Добавить специи по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11928,'Влить бульон порциями, он должен успевать впитываться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11928,'Нарезать грибы ломтиками, добавить в основную массу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11928,'Потушить до мягкости риса на тихом огне.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11929,'Включить прогреться духовой шкаф до 180 градусов. Мелко нашинковать петрушку, лук, чеснок, пересыпать в сковороду со сливочным маслом, обжарить при слабом нагреве.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11929,'В подготовленный фарш поместить содержимое сковороды, сдобрить горчицей, солью, молотым перцем, добавить слегка взбитое яйцо (оставить небольшое количество для обработки верха рулета), перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11929,'Готовое слоеное тесто раскатать в форме прямоугольника, но не слишком тонко, разложить на середину часть фарша, на него уложить 3 сваренных вкрутую яйца, разрезанные пополам, прикрыть оставшимся фаршем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11929,'Края прямоугольника разрезать с наклоном в градусов 30-40 через каждые 2 см. Нижним  и верхним краем теста прикрыть фарш. Полосы поднять вверх, соединить крестом, аккуратно прижать к начинке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11929,'Смазать верх и бока домашнего мясного рулета в тесте яйцом, отправить в нагретый духовой шкаф, вытащить можно будет через 40 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11930,'Чеснок нарезать или пропустить через чеснокодавку, обжарить на сливочном масле, убрать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11930,'Нарезать кубиками репчатый лук, добавить в чесночное масло вместе с куриным мясом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11930,'Подержать продукты на огне до зарумянивания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11930,'Всыпать рис, специи, влить бульон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11930,'Довести массу до выпаривания жидкости, влить вторую порцию бульона.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11930,'Незадолго до подачи посыпать ризотто тертым сыром, положить кусочек сливочного масла.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11931,'Прогреть сковороду, влить оливковое масло, выложить смесь морепродуктов, всыпать зелень, обжарить все вместе до румяного цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11931,'Всыпать отваренный до полуготовности рис, подержать на тихом огне несколько минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11931,'Влить белое сухое вино, продолжать прогревать ризотто до тех пор, пока жидкость не испарится.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11931,'Подлить бульон и томатный соус, перемешать, тушить еще десять минут. Рис должен стать мягким.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11932,'Постное масло прогреть на сковороде, добавить нарезанный репчатый лук и чеснок, довести овощи до румяного оттенка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11932,'Всыпать рис, ввести вино, прогревать до тех пор, пока жидкость не выпарится.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11932,'Влить рыбный бульон небольшими порциями, в конце приготовления рис должен стать мягким.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11932,'За десять минут до готовности всыпать смесь морепродуктов, добавить приправы, тертый сыр, влить сливки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11932,'Продукты перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11933,'Выставить режим «Жарка», влить постное масло, накрошенный репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11933,'Довести овощ до золотистого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11933,'Всыпать рис, подержать пять минут, выставить программу «Тушение».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11933,'Влить вино, всыпать специи, прогревать блюдо до испарения жидкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11933,'Влить воду или рыбный бульон, поменять режим на «Рис».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11933,'На другой сковороде обжарить морепродукты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11933,'Переложить их к рису за восемь минут до готовности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11934,'Грибы промыть, нарезать, обжарить на растительном масле, лучше использовать оливковое.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11934,'Измельчить чеснок, переложить в блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11934,'Продукты подержать на огне две минуты, всыпать специи, прогреть две минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11934,'Растопить в другой сковороде сливочное масло, соединить с луком, довести до прозрачного состояния.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11934,'Выложить вторую порцию чеснока, всыпать рис.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11934,'Влить рыбный бульон в несколько приемов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11934,'Морепродукты обжарить отдельно, добавить в крупу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11935,'Налить на сковороду оливковое масло, выложить любую смесь овощей, жарить несколько минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11935,'Всыпать рис, влить порциями бульон, прогревать до выпаривания, рис должен стать мягким.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11935,'Добавить морепродукты, всыпать специи, подержать блюдо на огне в течение двух минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11936,'Разогреть на сковороде два вида масла – оливковое и сливочное.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11936,'Добавить нарезанный чеснок, морепродукты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11936,'Все вместе жарить пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11936,'На другой сковороде на смеси масел обжарить лук до золотистого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11936,'Добавить в него рис, жарить пять минут, продукты постоянно помешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11936,'Влить вино, прогревать до испарения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11936,'Влить немного бульона, варить рис до готовности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11936,'Когда жидкость впитается – влить следующую порцию.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11936,'За четыре или шесть минут до окончания процесса приготовления морепродукты перемешать с рисом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11936,'Натереть сыр, посыпать ризотто при подаче.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11937,'Измельчить лук и чеснок, обжарить продукты на оливковом масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11937,'Добавить часть белого сухого вина, довести смесь до кипения, всыпать перловую крупу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11937,'Подержать под крышкой пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11937,'Влить бульон частями, продолжать прогревать блюдо до готовности крупы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11937,'Всыпать тертый сыр, специи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11937,'После того как перловка впитает всю жидкость, соединить ее с обжаренными морепродуктами, подлить остатки вина.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11937,'Прогреть и дать настояться десять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11938,'Помыть и почистить картофель, поставить варить в соленой воде до полной готовности.Для начинки нарезать на кубики лук, обжарить до соломенного цвета на масле, добавить фарш, подсолить, обжарить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11938,'Приготовить из отварного картофеля с молоком и маслом однородное пюре без комочков, добавить сырое яйцо, очень быстро и тщательно смешать. Если мешать медленно, то яйцо заварится.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11938,'В форму, смазанную сливочным маслом переложить часть пюре, разровнять, уложить на него слой фарша, чуть-чуть вдавить, прикрыть оставшейся частью картофеля, слегка придавить, верх присыпать молотыми сухарями. Для получения аппетитной золотистой корочки смазать верх запеканки из картофеля «Как в детском саду» взбитым желтком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11938,'Отправить форму в духовку примерно на полчаса, готовить при температуре чуть меньше 200 градусов. В качестве соуса можно подать подливу из томатной пасты, кетчуп или сметану, а для любителей поострее – домашний хрен.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11939,'Влить на сковороду оливковое масло, обжарить лук, добавить длиннозерный рис, прогреть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11939,'Вливать по чашке воду или бульон, следующую порцию добавлять тогда, когда испарится предыдущая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11939,'Обжарить смесь морепродуктов на другой сковороде вместе с фасолью, специи, соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11939,'Перемешать с рисом, посыпать тертым сыром и подать на стол.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11940,'Измельчить репчатый лук, обжарить до румянца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11940,'Добавить хорошо вымытую, очищенную и нарезанную каракатицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11940,'Потушить до изменения цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11940,'Прогреть вторую сковороду, обжарить рис, влить вино, жидкость выпарить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11940,'Влить немного рыбного бульона, он должен впитаться в рис.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11940,'Добавить еще одну порцию жидкости.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11940,'Продукты соединить, добавить чернила, тушить под крышкой двадцать минут на среднем огне.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11941,'Перловую крупу промыть несколько раз холодной водой, оставить на ночь для набухания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11941,'Воду слить, крупу поставить варить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11941,'Добавить соль по вкусу, свежую воду, томить на тихом огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11941,'Время приготовления – от пятидесяти минут до часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11941,'Говядину нарезать кубиками, репчатый лук – полукольцами, морковь натереть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11941,'Сотейник с толстым дном прогреть, положить кусочек сливочного масла, влить растительное.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11941,'Обжарить на сильном огне овощи с мясом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11941,'Приправы, соль, перец – по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11941,'Когда мясо станет мягким – соединить продукты с перловкой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11941,'Все вместе потомить на тихом огне десять или пятнадцать минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11941,'Добавить лавровый лист, огонь погасить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11941,'При подаче лист удалить, иначе блюдо будет горчить.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11942,'Накануне приготовления перловку замочить в большом количестве воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11942,'В горшочки положить кусочки мяса, обжаренный репчатый лук и морковь. По желанию можно добавить любые другие овощи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11942,'Всыпать крупу, до горлышка горшочка должно остаться немного свободного пространства.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11942,'Соль и специи – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11942,'Влить воду или бульон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11942,'Закрыть горшочки крышками, поставить на час в духовку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11942,'Температура приготовления – 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11942,'При подаче в горшочки можно положить по кусочку сливочного масла, рубленый укроп.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11942,'Блюдо украсить веточками петрушки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11943,'Перловую крупу промыть в холодной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11943,'Мясо нарезать небольшими кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11943,'Лук и морковь покрошить соломкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11943,'Выставить режим «Жарка», готовить мясо и овощи до появления золотистой корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11943,'Соль, специи по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11943,'Всыпать крупу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11943,'Влить воду, она должна покрыть продукты на два сантиметра.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11943,'Закрыть крышку, готовить в режиме «Каша».',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11944,'Сварить в кастрюле перловую кашу до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11944,'Отдельно спассеровать куриное филе и овощи, добавить растительное масло и немного воды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11944,'Для каши можно использовать кабачки, баклажаны, морковь, любую капусту, зеленый горошек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11944,'Ингредиенты перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11944,'Влить воду или овощной бульон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11944,'Потушить блюдо до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11945,'Отрезать 4 одинаковых листа фольги, слегка смазать оливковым маслом. Куски рыбы сполоснуть под проточной струей, обсушить, переложить кожей вниз на фольгу. Все ингредиенты маринада перемешать, равномерно нанести на каждый кусок филе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11945,'Запаковать семгу, только сильно к рыбе фольгу не прижимать, но края должны быть тщательно завернуты без дырок. Переложить пакетики на противень, задвинуть его в прогретую до 170 градусов духовку, сочные медальоны из семги будут готовы через 25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11946,'Перловую крупу залить водой на два или три часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11946,'Продукт еще раз промыть холодной водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11946,'Выставить в мультиварке режим «Выпечка», растопить сливочное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11946,'Добавить натертую морковь, нарезанный лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11946,'Овощи жарить в течение пяти минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11946,'Добавить куриное филе, срезанное с окорочков и бедер.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11946,'Продукты перемешать, обжарить до получения золотистой корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11946,'Положить в блюдо маринованные маслята или опята, шампиньоны, все вместе обжарить еще раз.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11946,'Всыпать набухшую крупу, закрыть крышкой. Выставить режим «Каша».',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11947,'Говядину обжарить с овощами, положить смесь в горшочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11947,'Всыпать отваренную фасоль, заранее замоченную перловку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11947,'По желанию можно использовать готовую красную или белую фасоль из магазина в томатном или собственном соку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11947,'Жидкость не выливать, добавить в обжарку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11947,'В дополнение к жареной говядине использовать копченые свиные ребрышки, курицу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11948,'Сварить мясной бульон из говяжьей грудинки, время приготовления – от часа до полутора.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11948,'Перловку замочить в холодной воде для набухания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11948,'На сливочном масле спассеровать лук и морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11948,'Готовое мясо из кастрюли вынуть, положить овощи и крупу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11948,'Варить суп около часа на тихом огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11948,'Добавить нарезанное на кусочки мясо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11948,'Заправить лавровым листом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11949,'В сметану вбить сырые куриные яйца, всыпать сахарный песок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11949,'Массу взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11949,'Добавить муку, еще раз взбить, всыпать гашенную пищевую соду, перемешать, оставить на полчаса для настаивания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11949,'Треть готового теста влить в форму, выпечь корж. Температура приготовления – 180 градусов, время – 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11949,'В оставшееся тесто всыпать какао-порошок, хорошо взбить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11949,'Половину массы перелить в форму и выпечь второй корж коричневого цвета.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11949,'Аналогично приготовить третий корж.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11949,'Сметану взбить, всыпать ванилин из пакетика и сахар, крем настоять полчаса в холодильнике.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11949,'Коржи темного цвета нарезать квадратиками или поломать руками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11949,'На большое блюдо выложить белый корж, намазать кремом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11949,'Темные кусочки обмакнуть в сметанный крем, выложить горкой на основу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11949,'Остатки крема вылить сверху.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11949,'Приготовить глазурь из сливочного масла, какао-порошка, сахара и сметаны.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11949,'Смесь проварить, должна получиться однородная масса.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11949,'До кипения не доводить.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11949,'Торт залить полученной смесью, настоять в течение суток в холодильнике.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11950,'Обмыть кабачки, удалить кожуру (у молодых кабачков можно оставить), настругать вдоль на длинные пластины овощечисткой очень тонко. Из масла, чеснока, меда, перца, нашинкованной мелко зелени и уксуса приготовить маринад.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11950,'Переложить пластинки в широкую миску, залить маринадом, поставить кабачки маринованные закусочные по-светински на пару часов в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11951,'Куриное яйцо соединить с сахаром, всыпать погашенную соду, массу перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11951,'Всыпать муку, смесь взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11951,'Переложить тесто в форму, выпечь корж в течение получаса, температура – 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11951,'Оставшийся сахар взбить с белками, должна получиться густая масса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11951,'Застелить противень пергаментом, разместить на нем заготовки с помощью кондитерского шприца или ложки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11951,'Время запекания – один час, температура – около 100 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11951,'Приготовить крем из белков и сахарной пудры.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11951,'Порубить грецкие орехи, перемешать с кремом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11951,'В сливочное масло добавить сгущенное молоко, взбить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11951,'Добавить концентрированное молоко, перемешать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11951,'Корж разрезать пополам, половину поместить на блюдо, смазать сливочным кремом, выложить второй корж, его также смазать кремом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11951,'Безе обмакнуть в белый крем, выложить на коржи произвольной горкой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11951,'Шоколад растопить на водяной бане, полученной глазурью полить десерт.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11952,'Сырые желтки перемешать с частью сахара, массу хорошо растереть, влить сгущенное молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11952,'Добавить соль, гашенную соду, ванилин, муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11952,'Ингредиенты еще раз взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11952,'Оставшуюся часть сахарного песка взбить с белками в густую пену.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11952,'Обе массы соединить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11952,'Половину теста перелить в форму, печь при температуре 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11952,'В оставшуюся массу всыпать какао-порошок, взбить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11952,'Выпечь темный корж.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11952,'Белый бисквит разрезать на две половины по горизонтали, темный – поломать руками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11952,'Приготовить крем из сметаны, пудры и сгущенного молока, взбить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11952,'Промазать полученным кремом белые коржи.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11952,'Темные кусочки обмакнуть в массу и выложить горкой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11952,'Слои перекрывать консервированными ананасами.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11952,'Растопить шоколад, полить торт сверху.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11953,'Для начала приготовим соус.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11953,'Туда же выжимаем половинку лимона, добавляем кефир, майонез, сметану, и соль и перец. Все хорошо перемешиваем и убираем в строну.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11953,'Теперь подготовим ингредиенты для хот-дога.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11953,'Малосольные (или слабосоленые) огурцы режим на полукольца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11953,'Пекинскую капусту режим соломкой,',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11953,'И теперь все соединяем.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11953,'Разогреваем гриль, или же сковороду, после немного смазываем хот-дог растительным маслом, и после чего жарим на сковороде или же гриле до небольшой корочки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11954,'Для начала я почистила перец от семян, вынула плодоножку и почистила картофель. Затем приступила к приготовлению фарша.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11954,'Пока варились перцы разрезала картошку на четыре части, если крупная на 6 или 8. Разрезанный картофель добавила в кастрюлю к перцам, заполняя пустоты между перцами. Посолила по вкусу и варила до готовности картофеля.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11954,'Обжарила лук до прозрачности, затем с ним обжарила морковь. Влила томатный сок и все вместе тушила до готовности.','https://vkuso.ru/data/cache/data/0d/f9ec414f1efc30d_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11954,'Когда картофель стал уже мягким, но еще не начал разваливаться, добавила томатную заправку и проварила еще 5 минут.','https://vkuso.ru/data/cache/data/a3/f1bbf9fc14a69a3_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11954,'Надеюсь, Вам понравится. Приятного аппетита!','https://vkuso.ru/data/cache/data/be/42b79e4242469be_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11955,'Грибы порезать тонкими пластинками, потушить в сливках с кубиками лука и специям, натереть в отдельные емкости сыр и морковь. Грудку нарезать на тонкие полосы, промариновать с соком лимона и специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11955,'Уложить курятину (немного оставить для верхнего слоя) в форму, притрусить сырной стружкой, положить слой грибов, на них – тертую морковь и спиралью остатки курятины. Запекать порядка получаса при нагреве духовки в 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11955,'Слить выделившийся сок, присыпать соединения кусочков мяса сыром, поставить в духовку до начала расплавления сыра, дать 10 минут остыть прямо в форме, затем вынуть вкуснятину из куриной грудки на большое блюдо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11956,'Сырые белки взбить в плотную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11956,'Всыпать сахарный песок, массу взбить в течение семи минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11956,'На лист пергамента выложить безе при помощи шприца или ложки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11956,'Время запекания – два часа, температура – 100 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11956,'Далее температуру увеличить до 120 градусов, подержать полчаса, изделия остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11956,'Чернослив вымыть, пропустить через мясорубку вместе с орехами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11956,'Взбить размягченное сливочное масло, добавить сгущенное молоко, взбить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11956,'Посыпать крем орехами и черносливом, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11956,'Безе выложить на тарелку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11956,'Промазать слои кремом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11956,'Готовое блюдо полить шоколадом, растопленным на бане.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11957,'Сахарный песок перемешать с яйцами, массу взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11957,'Подлить молоко, размягченное масло, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11957,'Добавить погашенную соду, какао-порошок, муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11957,'Массу взбить, подлить кипящую воду и еще раз перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11957,'Перелить тесто в чашу мультиварки, выставить режим «Выпечка» на час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11957,'После сигнала крышку не открывать, оставить блюдо в режиме подогрева на 15 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11957,'Перемешать и взбить сахар со сметаной.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11957,'Готовый корж разрезать по горизонтали.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11957,'Нижнюю часть намазать кремом, верхнюю поломать или разрезать кусочками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11957,'Обмакнуть их в крем, выложить горкой на первый корж.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11957,'Остатками крема полить десерт сверху.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11957,'Приготовить глазурь из сахара, какао-порошка, молока, сливочного масла.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11957,'Полить торт.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11958,'Сырые куриные белки взбить, всыпать сахарную пудру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11958,'Массу еще раз взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11958,'Выложить ложкой безе на противень, печь два часа, температура – 150 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11958,'Грецкие орехи очистить и порубить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11958,'Взбить мягкое сливочное масло, добавить сгущенное молоко, перемешать, всыпать орехи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11958,'Сахарное печенье поломать, выложить в один слой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11958,'Безе обмакнуть в крем, выложить следующий слой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11958,'Посыпать ломаным печеньем.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11958,'Выложить еще один слой безе с кремом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11958,'Процесс повторить несколько раз, пока не закончатся продукты.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11958,'Горку посыпать оставшимися крошками.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11959,'Сварить мясо, даже можно переварить, говядина должна стать очень мягкой, дать остыть прямо в бульоне, отварить яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11959,'Мелкие луковицы нашинковать полукольцами, развести уксус пополам с водой, опустить в него лук, подержать около 4 часов, отцедить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11959,'Грибы разрезать частей на 8, сыр порезать средними кубиками, остывшее мясо – брусочками. Яйца разрезать на 2 части, а потом каждую порезать на полукольца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11959,'Поместить все в глубокий салатник, добавить майонез, присолить салат «Купеческий» с говядиной и грибами по вкусу и осторожно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11960,'Сырые яйца взбить с сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11960,'Добавить картофельный крахмал, массу перемешать, влить молоко, всыпать муку и взбить еще раз.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11960,'Довести оставшееся молоко до кипения, влить в него яйца, массу помешивать, проварить до густоты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11960,'Остудить, добавить сливочное масло, взбить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11960,'Влить немного коньяка, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11960,'Безе обмакнуть в массу, выложить на большую тарелку слоями, горкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11960,'Сверху вылить остатки крема.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11960,'Шоколадную плитку натереть, порубить орехи.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11960,'Обсыпать десерт.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11961,'Яйца взбить, всыпать сахар, влить сметану, погашенную соду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11961,'Массу взбить, добавить муку, взбить повторно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11961,'В половину массы всыпать какао-порошок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11961,'Приготовить два коржа – белый и темный.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11961,'Время выпекания – полчаса, температура – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11961,'Приготовить крем из сахарного песка, ванилина, сметаны.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11961,'Бисквиты нарезать или поломать небольшими кусочками, обмакнуть в крем, выложить на красивую тарелку горкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11961,'Растопить темный или молочный шоколад, полить торт.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11962,'Заранее приготовьте куриную грудку, ее нужно сварить в подсоленой воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11962,'Как только куриная грудка приготовилась, достаем ее, и даем остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11962,'Как только куриная грудка остыла, нарезаем ее мелким кубиком, или просто мелко-мелко. И перекладываем в миску.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11962,'Укроп мелко-мелко рубим, и перекладываем в ту же миску.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11962,'Чеснок точно так же мелко-мелко рубим, и в ту же миску.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11962,'Сыр натираем на мелкой терке, и в ту же миску.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11962,'Арахис нужно измельчить в крошку, и перекладываем в отдельную тарелку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11962,'В миску где у вас все подготовленные ингредиенты, добавляем майонез, и сметану по 3 ч.л. Соль, перец по вкусу. Все хорошо перемешиваем.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11962,'После того как перемешали, из полученной массы катаем шарики, и после этого обсыпаем их в арахисовой крошке. Перекладываем на тарелку, и отправляем в холодильник на 15 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11963,'Сварить предварительно очищенный картофель, приготовить пока он варится мясную прослойку. Лук нашинковать мелкими кубиками, довести в разогретом масле до красивого цвета, добавить в сковороду размороженный фарш, тщательно обжарить, во время приготовления несколько раз перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11963,'Слить из кастрюли с картофелем отвар, хорошо размять с добавлением сырого яйца, подогретого молока и сливочного масла до однородного пюре без комочков, подсолить, размешать. Для выпекания можно использовать глубокую сковороду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11969,'Приготовить глазурь из сливочного масла, какао, сахарного песка, сметаны.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11969,'Массу проварить до однородного состояния.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11969,'Залить торт.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11963,'Переложить в нее часть картофеля (около половины), далее ровным слоем положить фарш, прикрыть остатками картофеля. Пару яиц и чуть – чуть сливок взбить, равномерно полить запеканку, присыпать рубленой зеленью и сыром. Поставить домашнюю картофельную запеканку с фаршем запекаться в духовой шкаф на треть часа при 200 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11964,'Влить воду в кастрюлю, довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11964,'Всыпать немного соли и сахарного песка, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11964,'Ввести крупу тонкой струйкой, быстро помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11964,'Варить три минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11964,'Накрыть готовое блюдо крышкой, дать постоять пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11964,'Подать с кусочком сливочного масла.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11965,'Изюм без косточек промыть, залить кипящей водой на десять минут, затем слить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11965,'В чашу мультиварки всыпать сахар и соль, изюм, манную крупу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11965,'Влить воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11965,'Выставить режим «Каша» на 15 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11965,'По окончании процесса прибор открыть, в кашу добавить сливочное масло, оставить на пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11966,'В широкой емкости доводим до кипения молоко, смешанное с растительным маслом и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11966,'Добавляем крахмал и быстро перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11966,'Выключаем огонь, добавляем яйца и снова перемешиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11966,'Затем добавляем сыр, натертый на мелкой терке. Замешиваем тесто эластичное маслянистое тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11966,'Лист для выпечки смазываем маслом и присыпаем мукой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11966,'Из теста формируем небольшие шарики и выкладываем их на лист на расстоянии друг от друга.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11966,'Отправляем булочки в разогретую духовку на температуру 180 градусов примерно на 25 минут до золотистого цвета.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11967,'Нарежьте лук и огурец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11967,'Разогрейте сковороду, обжарьте сосиски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11967,'Затем обжарьте бекон до золотистости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11967,'Нарежьте бекон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11967,'Намажьте горчицу на багет.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11967,'Положите латук, сосиску, лук, огурец и бекон и полейте кетчупом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11968,'Масло сливочное растопить, смешать его в средней миске вместе со сметаной, яйцом, солью и содой для выпечки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11968,'Добавить в масляную массу 2 стакана муки и попробовать замесить довольно мягкое тесто: оно не должно липнуть к миске и рукам.Если замесить такое тесто не получается, добавить остальную муку и вымешивать тесто до нужного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11968,'Разделить готовое тесто на 2 части так, чтобы одна часть была чуть больше другой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11968,'Оба тестяных куска обернуть пищевой пленкой и убрать в сторону.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11968,'Тонко нашинковать очищенный репчатый лук, маленькими кубиками порезать баранину и очищенный картофель.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11968,'Смешать подготовленные ингредиенты, добавить соль, кумин (не путать с тмином) и черный перец, тщательно все перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11968,'Лист для выпечки посыпать мукой и раскатать на нем больший кусок теста.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11968,'По тестяному пласту, оставив по краям немного места, распределить подготовленную начинку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11968,'Раскатать второй кусок теста в пласт, закрыть им начинку, запечатав все края.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11968,'С небольшим количеством воды смешать яйцо и, получившейся «болтушкой», смазать будущий мясной пирог из баранины.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11968,'Выпекать изделие до готовности в предварительно разогретой до 375 градусов духовке.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11969,'Сырые куриные яйца взбить с сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11969,'Долить сметану, всыпать муку, взбить массу еще раз.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11969,'Добавить гашеную соду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11969,'В форму для выпекания перелить половину массы, печь при температуре 180 градусов, время – полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11969,'В оставшуюся массу всыпать какао-порошок, взбить до однородности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11969,'Выпечь второй корж.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11969,'Приготовить крем из сметаны, ванилина, загустителя для сметаны и сахарного песка, массу взбить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11969,'Белый бисквит разрезать, промазать кремом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11969,'Темный корж поломать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11969,'Кусочки обмакивать в сметанный крем, выкладывать горкой на белый корж.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11970,'Налить воду, довести до кипения, всыпать сахар и соль, крупу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11970,'Добавить кусочки тыквы, выставить режим «Каша» или аналогичный.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11970,'В готовое блюдо добавить мед или сливочное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11971,'Довести до кипения воду в небольшой кастрюле, всыпать сахарный песок и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11971,'Ввести крупу при постоянном помешивании, варить на тихом огне две минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11971,'Огонь выключить, блюдо подержать под крышкой четыре минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11971,'Банан очистить, нарезать кусочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11971,'Взбить в чаше блендера в пюре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11971,'Перемешать с кашей и подать на стол.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11972,'Довести воду до кипения, ввести сахар, ванилин, корицу, кардамон – на выбор.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11972,'Добавить немного соли.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11972,'Всыпать манную крупу, варить при постоянном помешивании три минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11972,'Кастрюлю накрыть крышкой, убрать с плиты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11972,'Очистить орехи, обжарить в течение минуты, измельчить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11972,'В готовую кашу всыпать цукаты, любые фрукты, орехи, добавить кусочек сливочного масла.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11972,'Отделить яичные желтки от белков.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11972,'Желтки перемешать, добавить в общую массу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11972,'Белки взбить, перемешать с кашей, выложить в форму для запекания.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11972,'Блюдо посыпать сахаром.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11972,'Печь до получения корочки золотистого цвета, температура приготовления – 180 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11973,'Для заготовок потребуются огурцы, выращенные в грунте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11973,'Овощи хорошо промыть, нарезать брусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11973,'Перемешать в большой емкости с сахарным песком, солью, молотым перцем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11973,'Влить растительное масло и столовый уксус, всыпать рубленую зелень петрушки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11973,'Смесь оставить для пропитывания на шесть часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11973,'Поставить кастрюлю на огонь, довести содержимое до кипения, варить в течение десяти минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11973,'Прокипятить банки, влить овощную смесь, закатать металлическими крышками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11973,'Банки перевернуть вверх дном до остывания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11974,'Огурцы небольшого размера вымыть и залить водой на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11974,'Вынуть, нарезать широкими полосками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11974,'Очистить и нарезать длинной соломкой морковь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11974,'Раздавить чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11974,'Ингредиенты соединить, посолить, всыпать сахар и корейские специи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11974,'Отдельно соединить постное масло с уксусом, залить маринадом овощи, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11974,'Время настаивания – десять часов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11974,'Смесь выложить в чистые банки, влить выделившуюся жидкость.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11974,'Время стерилизации: поллитровые банки – 12 минут, литровые – 20 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11974,'Салат закатать, укутать одеялом и дать остыть.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11975,'Маленькие помидоры и огурцы аккуратно нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11975,'Томаты разделить на четыре части, огурцы нашинковать кружками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11975,'Репчатый лук нарезать кольцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11975,'В стерильные банки выложить слоями: огурцы, помидоры, лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11975,'Для маринада вскипятить воду, влить уксус, добавить соль и специи, варить все вместе три минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11975,'Горячим маринадом залить овощную смесь в банках, накрыть крышками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11975,'В большой таз налить воду, довести до кипения, поставить банки, подержать 15 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11975,'Заготовки закатать крышками, оставить на сутки в перевернутом виде.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11976,'Огурцы вымыть, поместить в воду на час, вынуть нарезать половинками кругляшей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11976,'Очистить репчатый лук, нарезать кольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11976,'Овощи перемешать, добавить соль, дать постоять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11976,'Отдельно влить в емкость уксус, всыпать сахарный песок, положить лавровый лист, семя горчицы, смесь перцев, соль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11976,'Влить растительное масло, ингредиенты перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11976,'Смесь поставить на огонь, посыпать нарезанным укропом, довести до кипения, время приготовления – семь минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11976,'Содержимое кастрюли помешивать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11976,'Чистые стеклянные банки наполнить салатом, закрутить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11977,'В отдельной емкости смешать муку, манную крупу, разрыхлитель и сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11977,'Смазать противень растительным маслом и выложить на него слой мучной смеси.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11977,'Поверх «сухого» слоя распределить ровным слоем подготовленные яблоки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11977,'Далее снова выложить сухую смесь и завершить «выкладку» яблочным слоем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11977,'Сливочное масло натереть на терке и посыпать им последний слой будущего пирога.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11977,'Поместить противень с заготовкой в духовку и выпекать ',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11977,'Перед подачей посыпать готовое изделие молотой корицей.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11978,'Огурцы нарезать одинаковыми кружочками, репчатый лук – кольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11978,'Овощи положить в большую емкость, посолить, всыпать сахарный песок, оставить на три или четыре часа, должен появиться сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11978,'Влить в салат рафинированное масло, влить уксус, всыпать перец-горошек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11978,'Кастрюлю поставить на огонь, довести смесь до кипения, варить несколько минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11978,'Огонь погасить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11978,'Горячие овощи переложить в банки, закрутить крышками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11979,'У плодов огурца отрезать хвостики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11979,'Положить в холодную воду на два часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11979,'Разрезать пополам, а затем на четыре части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11979,'Репчатый лук очистить и нарезать полукольцами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11979,'В большую кастрюлю влить растительное масло, положить измельченный чеснок, горький и черный перец-горошек, соль и сахар.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11979,'Влить уксус.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11979,'Пересыпать овощи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11979,'Содержимое кастрюли перемешать, оставить на пять часов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11979,'Банки простерилизовать, затем наполнить салатом, влить маринад.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11979,'Прикрыть емкости крышками, поставить в таз с кипятком для стерилизации.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11979,'Время прогревания – около двадцати минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11979,'Банки вынуть, закупорить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11979,'Оставить салат под пледом на сутки.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11980,'Вымыть огурцы, разрезать на три или пять частей в зависимости от размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11980,'Плоды сложить в кастрюлю, всыпать соль и сахар, нарезанный чеснок, острый перец чили, сухую горчицу, черный перец, влить уксус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11980,'Массу оставить для настаивания на шесть часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11980,'Огурцы перемешать, переложить в чистые банки небольшого размера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11980,'Поставить их в таз с водой, довести до кипения, подержать 15 минут, вынуть, закатать стерильными крышками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11980,'Банки перевернуть, убрать в прохладное место для хранения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11981,'Молодые огурцы нарезать тонкими пластинками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11981,'Укроп и петрушку вымыть, порубить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11981,'Нарезать соломкой репчатый лук, пропустить через пресс чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11981,'Овощи соединить, добавить зелень, влить растительное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11981,'Всыпать соль, сахар, душистый перец, влить уксус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11981,'Массу перемешать, оставить на четыре часа для пропитывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11981,'Поставить кастрюлю с салатом на огонь, варить пять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11981,'Переложить заготовку в небольшие банки, закатать крышками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11982,'Клубнику разморозить, образовавшийся сок слить в стакан или чашку и отставить в сторону (не выливать).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11982,'При помощи блендера перебить ягоды в пюре, добавить в эту кашицу желатин и дать ему время набухнуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11982,'Далее в клубничное пюре нужно добавить сахарную пудру и сок половины лимона.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11982,'Массу хорошенько перемешать и нагреть на среднем огне (не кипятить!), все время помешивая, пока желатин полностью не раствориться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11982,'Остудить получившуюся массу до комнатной температуры и миксером на высокой скорости взбить в течение 5-7 минут, пока она не станет густой, светлой и не увеличится в объеме.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11982,'В форму положить лист вощеной бумаги и распределить по нему ровным слоем клубничную массу. В прохладное место убрать форму, чтобы масса полностью застыла.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11982,'Поверхность присыпать сахарной пудрой и перевернуть на нее форму с застывшей массой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12284,'Влить сгущенное молоко, всыпать тертый шоколад.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11982,'Аккуратно удалить лист бумаги и порезать клубничный пласт кубиками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11982,'Получившиеся домашние конфеты «Клубничные облака» обвалять в сахарной пудре и подать к столу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11983,'Вымыть огурцы, нарезать брусками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11983,'Чеснок очистить, мелко нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11983,'Влить в жаропрочную емкость воду, довести жидкость до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11983,'Всыпать соль, куркуму, влить натуральный мед, уксус.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11983,'Все вместе варить две минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11983,'В стеклянные банки положить на дно укроп, лавровый лист, перец-горошек, чеснок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11983,'Сверху – огурцы, влить маринад.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11983,'Банки накрыть крышками, дать постоять один час.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11983,'Поставить заготовки в таз с водой, прокипятить в течение 15 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11983,'Закатать салат крышками.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11984,'Вымыть и нарезать помидоры крупными кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11984,'Из сладкого болгарского перца удалить семечки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11984,'Плоды разрезать на несколько частей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11984,'Чеснок очистить, вымыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11984,'Овощи пропустить через мясорубку для получения пюре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11984,'Огурцы вымыть, нарезать тонкими пластинками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11984,'Положить овощи в емкость с толстыми стенками, добавить пюре, сахарный песок, соль, растительное масло.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11984,'Ингредиенты перемешать, довести до кипения.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11984,'Время томления на тихом огне – полчаса.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11984,'Содержимое кастрюли помешивать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11984,'Влить уксус, прогревать закуску еще пять или шесть минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11984,'Заготовку переложить в банки, закрутить прокипяченными крышками, перевернуть до остывания.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11985,'Огурцы промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11985,'Чеснок и лук очистить, нарезать произвольно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11985,'В банки выложить огурцы, лук и чеснок, всыпать перец-горошек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11985,'Отдельно довести воду до кипения, влить в банки, накрыть крышками, оставить до остывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11985,'В кастрюлю всыпать сахар и соль, положить лавровый лист, специи, влить уксус и воду из банок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11985,'Маринад кипятить пять минут, влить в стерильные банки, закрыть жестяными крышками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11985,'Банки перевернуть, оставить при комнатной температуре на сутки или двое.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11986,'Огурцы вымыть и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11986,'Нарезать плоды тонкими кружками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11986,'Очистить лук, нарезать тонкими кольцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11986,'Ингредиенты соединить, всыпать сахарный песок, соль и перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11986,'Овощи должны постоять в темном помещении полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11986,'Поставить смесь на огонь, довести до кипения, влить растительное масло и уксус.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11986,'Варить содержимое кастрюли в течение семи минут, помешивать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11986,'В стерильные банки выложить горячие овощи, уплотнить, добавить перец-горошек.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11986,'Закрыть консервы жестяными крышками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11986,'Банки перевернуть вверх дном, укрыть пледом до остывания.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11987,'Огурцы промыть, нарезать кубиками или кружками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11987,'Добавить сахарный песок, соль, рубленую зелень и нарезанный чеснок, влить уксус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11987,'Ингредиенты перемешать, оставить для пропитывания на 12 часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11987,'Салат переложить в стерильные банки, закрыть капроновыми крышками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11988,'Огурцы вымыть, нарезать одинаковыми кружками, выложить в емкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11988,'Промыть зелень укропа, нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11988,'Натереть очищенный чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11988,'Порошковую горчицу развести до полужидкой консистенции.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11988,'Добавить в огурцы, влить растительное масло, уксус, всыпать сахарный песок, соль, перец чили или молотый черный, чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11988,'Массу осторожно перемешать, оставить для пропитывания на три часа в холодном месте.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11988,'Небольшие банки стерилизовать любым доступным способом: в пароварке, мультиварке, микроволновой печи или в духовке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11988,'Огуречный салат разложить в банки, прикрыть полиэтиленовыми крышками и хранить в холоде.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12033,'Курицу вымыть, разделить на части, кожицу не снимать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11989,'Яблочный уксус перемешать с растительным маслом, сахарным песком, солью, перцем, лавровым листом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11989,'Маринад довести до кипения и убрать с огня.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11989,'Нарезать кубиками огурцы, очищенный репчатый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11989,'Помидоры среднего размера нарезать четвертинками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11989,'Маринад остудить, залить овощи, перемешать и варить на тихом огне в течение получаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11989,'Время от времени салат помешивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11989,'Смесь разложить в банки, закатать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11990,'Взбить до кремообразного состояния масло сливочное несоленое вместе с сахарной пудрой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11990,'Добавить в масляную массу ванильную эссенцию и яичные желтки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11990,'Тщательно перемешать все до однородности и порциями подмешать муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11990,'Замесить очень эластичное тесто, чтобы оно не липло к рукам, после чего получившийся кусок разделить на 2 шара: один шарик должен быть немного больше другого.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11990,'Шарик поменьше обернуть пищевой пленкой и поместить в холодильник, противень выстелить бумагой для выпечки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11990,'Равномерным слоем распределить, делая небольшие бортики, по всей площади противня большой кусок теста.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11990,'Чуть подмерзшее тесто натереть на крупной терке, смазать заготовку в форме клубничным джемом и посыпать сверху подготовленным тертым тестом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11990,'Поместить противень с будущим печеньем на 20-25 минут в предварительно разогретую до 180 градусов духовку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11990,'Готовый слегка подрумянившийся пирог достать из духовки, порезать на квадратики желаемого размера и дать печенью немного остыть.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11990,'Переложить венское печенье с клубничным джемом на сервировочное блюдо, подать либо в теплом, либо в холодном виде.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11991,'У длинных огурцов обрезать кончики, вымыть, овощи замочить в холодной воде на три часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11991,'На дно банок положить слоями веточки зеленого укропа, листья вишни и смородины, нарезанную кружками морковь, далее – нарезанный кусочками очищенный сладкий перец, немного горького перца, перец-горошек, рубленый чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11991,'Когда банки будут полностью заполнены – залить сверху кипящую воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11991,'Оставить салат на пятнадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11991,'Воду слить в кастрюлю, добавить соль и сахарный песок, кипятить ее пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11991,'Всыпать в банки лимонную кислоту, влить рассол и закатать металлическими крышками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11991,'Емкости перевернуть, укутать одеялом, оставить на сутки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11992,'Вымыть огурцы, нарезать тонкими кружками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11992,'Репчатый лук нарезать полукольцами, добавить в огурцы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11992,'Сверху влить растительное масло, уксус, всыпать соль, сахар, нарезанный перец чили и кориандр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11992,'Салат перемешать, поставить на тихий огонь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11992,'Варить массу в течение пятнадцати минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11992,'Цвет и консистенция состава должны измениться.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11992,'Массу разложить в небольшие банки, утрамбовать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11992,'Овощи должны быть полностью покрыты маринадом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11992,'Салат закатать крышками, банки перевернуть, обернуть тканью, оставить на ночь.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11993,'У огурцов срезать кончики, разрезать плоды вдоль на две половины, затем поперек тонкими полосками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11993,'Очистить сладкий болгарский перец, нарезать тонкими брусками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11993,'Очистить и натереть на терке морковь, как для салата по-корейски.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11993,'Измельчить чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11993,'Все ингредиенты перемешать, посолить, добавить сахарный песок, растительное масло, уксус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11993,'Смесь накрыть крышкой, оставить на десять часов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11993,'Закуску разложить в стерильные банки, залить образовавшимся маринадом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11993,'Банки закатать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11994,'Белокочанную капусту крупно нарезать, бланшировать пять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11994,'Нарезать кабачки и огурцы кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11994,'Очистить и пропустить через пресс чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11994,'Ошпарить помидоры, снять кожицу, мякоть измельчить при помощи блендера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11994,'Сложить овощи в стерильные банки слоями, пересыпать продукты рубленой зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11994,'В томатную массу добавить специи, соль, чеснок, варить на тихом огне от десяти до двадцати пяти минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11994,'Разлить в банки, закатать, укрыть пледом, оставить на ночь до остывания.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11995,'Свежие огурцы, болгарский перец и зеленое яблоко натереть на крупной терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11995,'Репчатый лук нарезать полукольцами, обжарить на растительном масле вместе с тертой морковью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11995,'Помидоры пропустить через мясорубку, соединить с обжаркой и остальными овощами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11995,'Посолить, добавить яблочный уксус, молотую корицу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11995,'Тушить двадцать минут на тихом огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11995,'Готовую икру выложить в банки, закатать и оставить на ночь для остывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11996,'Для блюда понадобится сушеная спаржа, приправы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11996,'Продукт необходимо замочить на семь или восемь часов в холодной воде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11996,'Побеги отжать от лишней влаги, нарезать соломкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11996,'Белый репчатый лук измельчить, обжарить на любом растительном масле до золотистого оттенка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11996,'В отдельной емкости пропущенный через пресс чеснок соединить с соевым соусом, маслом, сахарным песком, солью, специями для моркови по-корейски.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11996,'Массу перемешать до однородного состояния.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11996,'Залить получившимся соусом спаржу, закрыть герметичной крышкой, поставить в холод на пять или шесть часов для пропитывания.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11997,'Размягчить сливочное масло, поместив его на некоторое время во включенную микроволновую печь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11997,'Всыпать в миску с маслом оба вида сахара, но если тростникового нет, можно использовать обычный.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11997,'Туда же вбить яйцо, добавить просеянную с разрыхлителем муку и тщательно все перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11997,'Бананы очистить и любым удобным способом сделать из них пюре, которое затем смешать с тестом, при необходимости добавив еще муки (если тесто получилось жидким).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11997,'Получившееся тесто распределить по формочкам и выпекать 30 минут в духовке при 200 градусах.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11997,'Плитку шоколада (молочного или темного) поломать на кусочки, переложить в миску и растопить в микроволновке. Готовые изделия смазать подготовленным шоколадом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11997,'Маффины из бананов с шоколадом можно подавать как порционно, так и на большом сервировочном блюде.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11998,'Воду довести до кипения, залить сушеную спаржу на один час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11998,'Морковь очистить и нашинковать на специальной терке для приготовления корейских блюд.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11998,'Приготовить маринад из уксуса, соли, сахарного песка и измельченного чеснока.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11998,'Полученную смесь прогреть на среднем огне, довести до кипения, огонь погасить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11998,'Готовый маринад вылить на нарезанную спаржу, перемешанную с морковью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11998,'Закуску поставить под гнет на час, смесь держать в тепле.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11998,'Далее спаржу хранить в холодильнике.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11999,'Спаржу замочить на пять часов в холодной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11999,'Продукт отжать, нарезать маленькими кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11999,'Морковь натереть, перемешать со спаржей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11999,'Кунжутное семя обжарить на сухой сковороде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11999,'Перемешать с основной массой, добавить соль и сахарный песок, уксус, чеснок, красный молотый перец, специи для моркови по-корейски.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11999,'Любое растительное масло довести на сковороде до кипения, залить продукты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (11999,'Подержать спаржу в холоде шесть часов и подать к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12000,'Сушеную спаржу поломать кусочками и залить подогретой водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12000,'Соль – по вкусу, оставить закуску на час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12000,'Измельчить репчатый лук, сладкий болгарский перец, добавить намокшую спаржу, воду, специи, чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12000,'Смесь потушить на тихом огне, время – от десяти до двенадцати минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12000,'Готовую смесь перемешать с морковью по-корейски, полить соевым соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12001,'Сухую спаржу замочить на ночь в холодной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12001,'Отжать, нарезать наискосок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12001,'Спаржу перемешать с обжаркой, залить смесью из соевого соуса, сахарного песка, уксуса, специй, соли.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12001,'Банки стерилизовать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12001,'Переложить закуску, хранить в холодильнике.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12002,'Куриное филе хорошо промыть, обсушить бумажными полотенцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12002,'Мясо нарезать ломтиками толщиной в один сантиметр, отбить и нарезать полосками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12002,'Раскалить сковороду, нагреть растительное масло, обжарить курицу до получения румяной корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12002,'Мясо приправить столовой горчицей, солью, перцем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12002,'Репчатый лук очистить и мелко нашинковать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12002,'Спассеровать в сотейнике, присыпать мукой, добавить жирную домашнюю сметану.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12002,'Влить порциями теплую воду, массу помешивать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12002,'Должна получиться густая подлива.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12002,'Куриное мясо заправить сметанным соусом, прогреть до кипения.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12002,'Огонь уменьшить, сотейник прикрыть крышкой, тушить блюдо в течение двадцати минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12003,'В небольшой мисочке смешать сахар и манную крупу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12003,'В отдельной емкости (побольше) смешать кефир, соль и соду, вбить яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12003,'В кефирную массу всыпать сахарно-манную смесь, тщательно перемешать и замесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12003,'Добавить в получившееся тесто промытый изюм (если используется) и еще раз перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12003,'Перелить тесто в форму и убрать ее в духовку (предварительно разогретую).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12003,'Выпекать классический манник на кефире с изюмом до полной готовности при 180-200 градусах.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12004,'Мясо курицы промыть и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12004,'Продукт посолить и поперчить, обжарить на постном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12004,'Лук-репку очистить, нашинковать пластинками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12004,'Половину продукта добавить в мясо, влить часть сметаны, тушить пятнадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12004,'Свежие грибы промыть, обсушить, нарезать тонкими пластинками, обжарить отдельно от других продуктов до получения коричневатой корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12004,'Добавить в шампиньоны остатки лука и сметаны, приправить специями.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12004,'Мясной и грибной составы соединить, перемешать, потомить под крышкой пятнадцать минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12004,'Чеснок добавить по желанию.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12005,'Куриную грудку вымыть, обсушить и нашинковать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12005,'Лук очистить от шелухи, нарезать полукольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12005,'Копченую свиную грудку нарезать кубиками, обжарить на среднем огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12005,'Обжарить лук до золотистого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12005,'Добавить куриное мясо и муку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12005,'Массу перемешать, продолжать обжаривать до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12005,'Влить жирные сливки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12005,'Добавить специи, приправы, чеснок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12005,'Прогреть готовый бефстроганов в течение пяти минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12006,'Куриную грудку нарезать тонкими полосками, отбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12006,'Мультиварку включить на режим «Жарка» или «Выпечка» на три минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12006,'Влить немного кукурузного масла, добавить нашинкованный полукольцами лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12006,'Овощ обжарить до розовато-золотистого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12006,'Добавить в луковую обжарку курицу, прогревать пятнадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12006,'Добавить консервированные помидоры без кожицы, всыпать смесь перцев, соль, сушеные травы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12006,'Порциями добавить густую свежую сметану.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12006,'Выставить режим «Тушение», закрыть мультиварку крышкой, готовить еще пятнадцать минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12006,'Готовое блюдо можно посыпать рубленым зеленым луком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12007,'Теплое молоко смешать с сахаром и растворить в нем дрожжи. Убрать смесь в теплое место на некоторое время: дрожжи должны запениться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12007,'30 г растопленного сливочного масла взбить с желтком, добавить соль, муку, влить дрожжи и замесить тесто чистыми руками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12007,'Миску промаслить, переложить в нее тесто и накрыть  кухонным полотенцем. Поставить тесто на 1-2 часа в теплое место или в выключенную духовку, заранее нагретую до 300 С.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12007,'3-4 ложки сахара, 50 г сливочного масла и корицу перемешать до однородности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12007,'Тесто размять руками и раскатать в пласт толщиной 1 см, который смазать масляно-сахарной массой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12007,'Тестяной пласт скрутить в плотный рулет, разрезать вдоль пополам так, чтобы кончик остался неразрезанным.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12007,'2 половинки переплести и соединить концы, сформировав замкнутый круг.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12007,'Смазать заготовку оставшейся масляной массой, переложить на противень, выпекать при 200 градусах 20-25 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12007,'За 5-10 минут до готовности температуру можно убавить до 180 градусов, после чего достать готовое изделие из духовки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12007,'Перед подачей ',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12008,'Куриное филе промыть холодной водой, нарезать длинными тонкими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12008,'Приготовить соус в сотейнике: влить свежую сметану, теплый бульон и томатную пасту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12008,'Соль и перец – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12008,'Прогреть соус до кипения, убрать с огня.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12008,'Кусочки куриного филе запанировать в муке, это можно сделать в дуршлаге – лишняя панировка осыплется.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12008,'Очистить репчатый лук, нарезать, спассеровать в масле до мягкости.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12008,'Сверху выложить курицу, обжарить на сильном огне, помешивать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12008,'Когда мясо изменит цвет, влить соус.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12008,'Потушить двадцать минут под крышкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12009,'Куриную грудку вымыть, обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12009,'Мясо нарезать соломкой толщиной до одного сантиметра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12009,'Очистить репчатый лук, нашинковать полукольцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12009,'Прогреть сковороду на среднем огне, влить растительное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12009,'Выложить мясо, добавить чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12009,'Жарить курицу при постоянном помешивании до получения румяной корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12009,'Добавить лук, обжарить до золотого оттенка.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12009,'В емкость влить воду, всыпать муку, разбить комочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12009,'Отдельно соединить сметану с водой, солью, перцем и паприкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12009,'Влить мучной состав в сковороду с мясом, массу перемешать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12009,'Ввести сметанную заправку.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12009,'Продолжать помешивать продукты, пока смесь не загустеет.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12010,'Куриное мясо нашинковать тонкой соломкой, обжарить в течение нескольких минут на сковороде с кубиками репчатого лука.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12010,'Влить густую сметану, добавить соль, перец, нарезанный чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12010,'Все вместе потушить десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12010,'Шампиньоны или лесные грибы очистить и промыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12010,'Нарезать кусочками, жарить на масле до легкого румянца.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12010,'Влить оставшуюся сметану, перемешать, прогреть до кипения, потомить пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12010,'Мясную массу выложить в форму для запекания, сверху вылить грибную смесь.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12010,'Натереть сыр твердого сорта, посыпать блюдо, запекать в духовом шкафу десять минут, температура – 180 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12011,'Плоды вымыть, удалить плодоножку, мякоть нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12011,'Постное масло влить в чашу мультиварки, прогреть в режиме «Жарка».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12011,'Кубики баклажанов всыпать в мультиварку, выставить режим «Тушение» на полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12011,'Небольшие стеклянные банки вымыть, стерилизовать при помощи микроволновой печи или паром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12011,'Очистить и нарезать чеснок, добавить в основную массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12011,'Перед нарезанием чеснок лучше раздавить ножом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12011,'Всыпать душистый перец, соль, семена укропа, все вместе тушить пять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12011,'Еще не остывшие овощи быстро переложить в банки, влить уксусную эссенцию.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12011,'Закрутить крышки, емкости перевернуть, укутать платком.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12011,'Через сутки банки перевернуть и подержать еще двадцать четыре часа укутанными.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12012,'Вымыть баклажаны, удалить плодоножки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12012,'Кожуру срезать, мякоть нашинковать небольшими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12012,'Всыпать соль, подождать два часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12012,'Выделившийся сок слить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12012,'Овощи переложить в емкость, влить воду.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12012,'Поставить на плиту, довести до кипения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12012,'Образовавшуюся пенку убрать, добавить уксус, поварить пять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12012,'Закатать консервы крышками, банки перевернуть, укрыть одеялом, оставить до остывания на двое суток.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12013,'Плоды вымыть, очистить, нарезать кубиками или брусками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12013,'Чеснок пропустить через пресс.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12013,'Укроп нарезать или протереть, можно использовать сушеный продукт.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12013,'Кастрюлю поставить на огонь, влить воду, всыпать специи, соль, сахарный песок, влить уксус.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12013,'Довести рассол до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12013,'Выложить часть баклажанов, варить десять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12013,'Переложить кусочки в миску, засыпать укропом с семенами, чесноком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12013,'Массу перемешать, разложить в сухие чистые банки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12013,'Долить в каждую банку по ложке прокаленного растительного масла.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12013,'Банки перевернуть, укутать, оставить на сутки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12013,'Одеяло снять, хранить банки в прохладном месте.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12014,'Молоко влить в кастрюлю, прогреть до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12014,'Всыпать соль, сахарный песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12014,'Манку всыпать тонкой струйкой, постоянно помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12014,'Время варки – пять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12014,'Добавить сливочное масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12014,'Кашу перемешать и дать немного постоять.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12015,'Перекладываем творог в миску, и туда же добавляем банан и сахар по вкусу. Все это хорошо перемешиваем.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12015,'Слоеное тесто немного раскатываем и после этого делим на равные части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12015,'Куриное яйцо взбиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12015,'Берем ломтик подготовленного слоеного теста, и на него укладываем творожно-банановую начинку, после чего заворачиваем в конверт, и защепляем края вилкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12015,'Смазываем слойки взбитым куриным яйцом и отправляем в духовку при 200 С, на 15-20 минут, до тех пор, пока слойки не подрумянятся.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12015,'Достаем и подаем к чаю.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12016,'Манку перемешать с солью, сахарным песком, влить охлажденное молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12016,'Дать постоять пять минут для набухания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12016,'Перемешать, поставить на тихий огонь, довести до закипания, огонь уменьшить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12016,'Варить две минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12016,'Кашу помешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12016,'Блюдо остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12017,'В небольшой кастрюле перемешать молоко с водой, довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12017,'Крупу всыпать в жидкость через сито, кашу помешивать венчиком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12017,'Добавить соль, варить две минуты, всыпать сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12017,'Кастрюлю накрыть крышкой и полотенцем, подать к столу через десять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12018,'Молоко довести до кипения в сотейнике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12018,'Всыпать манку, соль – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12018,'Влить молоко тонкой струйкой, помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12018,'Варить две минуты на тихом огне, подержать кашу под крышкой и полотенцем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12018,'Желток растереть с сахаром, ввести в кашу через пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12018,'Взбить в пену белок, также аккуратно вмешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12019,'Влить в молоко в кастрюлю, дать закипеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12019,'Огонь убавить до минимальной величины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12019,'Крупу разбавить холодным молоком, влить в горячую жидкость тонкой струйкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12019,'Варить кашу пять минут при слабом кипении, помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12019,'Добавить по вкусу сахар и соль.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12019,'Томить все вместе 30 секунд, снять с огня.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12019,'Заправить кашу сливочным маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12020,'Влить в чашу воду, молоко, положить кусочек сливочного масла, всыпать манку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12020,'Добавить сахар и соль, кашу перемешать до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12020,'Выставить режим «Плов» или «Каша» на двадцать пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12020,'Добавить сливочное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12021,'Воду прогреть до сорока градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12021,'Засыпать сухое молоко, помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12021,'Кастрюлю поставить на огонь, добавить сахар, соль, манку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12021,'Крупу всыпать тонкой струйкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12021,'Огонь уменьшить до минимума, варить десять минут, кашу постоянно помешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12022,'Смешиваем сухие ингредиенты: мука, 2 ст.л. сахара и разрыхлитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12022,'Смешиваем жидкие ингредиенты используя миксер: растопленное сливочное масло, яйца и молоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12022,'Замешиваем тесто, соединяя сухие и жидкие ингредиенты до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12022,'Сливы разламываем на половинки и извлекаем косточки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12022,'В сковороду со съемной или металлической ручкой налить воду и всыпать оставшийся сахар. Довести до кипения, помешивая варить 3 минуты. Затем выложить сливы срезом вверх и оставить еще на пару минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12022,'Залить сливы тестом и отправить в духовку на температуру 180 градусов примерно на 30 минут, ориентируясь на свою духовку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12022,'Готовый пирог накрыть блюдом и сразу же перевернуть, пока карамель не прилипла к дну сковороды.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12023,'Курицу разделать, удалить лишний жир, копчиковую железу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12023,'Курицу промыть, разрезать на порции, кожу оставить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12023,'Мясо еще раз промыть, обсушить и положить на сухую сковороду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12023,'Тушить без масла, в собственном соку, под крышкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12023,'Надрезать крест-накрест кожицу на помидорах, залить на три минуты кипящей водой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12023,'Кожицу снять, мякоть мелко нашинковать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12023,'Мясо тушить двадцать минут, добавить томатную массу, прогревать все вместе на тихом огне еще пятнадцать минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12023,'Сладкий болгарский перец и репчатый лук нарезать полукольцами.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12023,'В блюдо добавить кинзу, лук, рубленый реган.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12023,'Все вместе тушить десять минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12023,'Далее положить оставшиеся специи и болгарский перец.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12023,'Вместо слишком острых приправ добавить хмели-сунели.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12023,'Острый красный перец и чеснок положить в конце приготовления.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12023,'Дать блюду настояться.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12024,'Куриные окорочка хорошо вымыть или вымочить в течение двух или трех часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12024,'Разрезать на куски с мясом и костями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12024,'Поставить мультиварку в режим «Выпечка» на пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12024,'Влить растительное масло, курицу вынуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12024,'Репчатый лук нарезать кубиками, обжарить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12024,'Нарезать помидоры кубиками, добавить в лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12024,'Через три или четыре минуты куриное мясо выложить на обжарку вместе с полукольцами перца, томатной пастой и специями.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12024,'При необходимости влить воду.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12024,'Закрыть крышку, прогревать блюдо в режиме «Тушение», время – от тридцати до сорока минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12024,'В конце добавить рубленую зелень и зубчики чеснока.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12025,'Куриное мясо нарезать, тушить с репчатым луком и сливочным маслом в течение десяти или пятнадцати минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12025,'Влить воду, мясо должно быть скрыто, варить пятнадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12025,'Очистить грецкие орехи, перемешать с помидорами, взбить в блендере.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12025,'Смесь влить в куриный бульон, добавить лавровый лист.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12025,'Ингредиенты перемешать, чахохбили поварить еще пять или семь минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12025,'Всыпать чеснок и рубленую зелень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12025,'Довести блюдо до кипения, сковороду снять с огня, подержать под крышкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12026,'В миске смешать масло с яйцом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12026,'Мелко нарезать лук, ветчину, грибы и брокколи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12026,'Разогреть сковороду. Добавить масло и обжарить лук.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12026,'В миске взбить яйцо, добавить сливки, сыр, мускатный орех и соль, хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12026,'Распределить тесто по форме.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12026,'Выложить смесь из ветчины и овощей и сверху вылить заливку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12027,'Приготовить маринад из томатной пасты, соли, сахара, чеснока, лаврового листа и воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12027,'Сахар и соль растворить в воде, добавить остальные продукты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12027,'В смесь положить мясо, подержать двенадцать часов в холодильнике.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12027,'Нарезать репчатый лук, кинзу, помидоры и чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12027,'В горячую сковороду влить растительное масло, выложить куриное мясо, потушить на тихом огне от пятнадцати до двадцати минут, массу помешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12027,'Добавить томаты, жарить еще пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12027,'Приправить блюдо сухой кинзой, чесноком и хмели-сунели.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12027,'Отдельно взбить яйца, добавить в остальную массу, перемешать с остальными ингредиентами.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12027,'Время прогревания – от двух до трех минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12028,'Курицу разрезать на кусочки, лишний жир удалить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12028,'Покрошить репчатый лук, обжарить в курином жире до полупрозрачного состояния, добавить немного сливочного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12028,'Обжаренный лук переложить в кастрюлю, добавить курицу, влить белое сухое вино или воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12028,'Продукты тушить под крышкой в течение тридцати пяти или сорока минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12028,'Добавить очищенные от кожуры томаты, мякоть можно нарезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12028,'Довести блюдо до кипения, добавить соль, перец, зелень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12028,'Все вместе варить двадцать минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12029,'Растопить сливочное масло в казане с толстыми стенками, обжарить репчатый лук, нарезанный кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12029,'Обжарку переложить на тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12029,'В казан добавить куриное мясо, нарезанное кусками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12029,'Продукт жарить под крышкой, время – от пяти до десяти минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12029,'Слить сок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12029,'Курицу продолжать жарить до корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12029,'Выложить в казан луковую обжарку, добавить давленый чеснок и лимонный сок, прогревать пять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12029,'Нарезать томаты, сладкий перец, картофель, добавить в мясо.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12029,'Влить слитый сок, специи, соль.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12029,'Варить чахохбили десять минут, огонь – средний.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12029,'За пять минут до конца приготовления добавить рубленую зелень.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12030,'Куриную тушку поделить на порции, удалить кости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12030,'Мясо вымыть холодной водой и обсушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12030,'В сотейнике с толстыми стенками подрумянить курицу, жир не использовать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12030,'Репчатый лук и острый перец нарезать полукольцами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12030,'Овощи спассеровать на отдельной сковороде на сливочном масле.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12030,'Обжарку добавить к мясу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12030,'Сладкий болгарский перец нарезать полосками средней величины, прогреть на масле в течение пяти минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12030,'Помидоры надрезать крестиками, залить кипящей водой, через две секунды переложить в холодную воду.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12030,'Снять кожицу, мякоть нарезать кусочками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12030,'Продукт переложить к остальным ингредиентам, сотейник накрыть крышкой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12030,'Массу томить до мягкости, соль – по вкусу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12030,'Нарезать чеснок и зелень, добавить в сотейник, всыпать специи, прогревать от семи до десяти минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12031,'Листья салата промыть, обсушить, нарезать и выложить на блюдо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12031,'Промытый огурец нарезать кубиками, очищенную морковь – соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12031,'Ростки сои также промыть и обсушить, чеснок очистить и нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12031,'На сковороде разогреть одну столовую ложку оливкового масла и положить туда подготовленный чеснок и зелень кинзы или базилика (если используются).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12031,'Обжарить все на большом огне 30 секунд и добавить говядину, предварительно нарезанную тонкими полосками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12031,'Мясо слегка посолить и поперчить, обжарить в течение 2-3 минут, после чего шумовкой переложить на овощи на блюде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12031,'В туже сковородку влить оставшееся оливковое масло, лаймовый сок, добавить соус чили и готовить соус не дольше 1 минуты при непрерывном помешивании.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12031,'Готовой заправкой полить тайский салат с говядиной и соевыми ростками и подать блюдо к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12032,'Курицу порубить на части, жир и кожу оставить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12032,'Вымыть, обсушить полотенцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12032,'Выставить режим «Жарка», положить мясо в чашу, всыпать приправы, перемешать и жарить десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12032,'Очистить от семян сладкий болгарский перец, помидоры, лук, чеснок, измельчить при помощи блендера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12033,'Подрумянить на сухой сковороде, огонь – умеренный.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12033,'Переложить в сотейник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12033,'На сковороде спассеровать репчатый лук и тертую морковь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12033,'Подрумяненные овощи переложить к курице, все вместе тушить пятнадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12033,'Влить сухое красное вино, положить томатную пасту, специи и соль по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12033,'Массу тушить на тихом огне.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12033,'Ошпарить и очистить томаты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12033,'Нарезать дольками, добавить в сотейник к остальным продуктам.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12033,'Потушить блюдо полчаса, украсить рубленой зеленью.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12034,'Баклажаны прокалываем ножом и отправляем в духовку на температуру 200 градусов. Запекать баклажаны нужно до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12034,'Из остывших баклажанов снимаем кожицу, а мякоть отправляем в чашу блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12034,'Измельчаем баклажаны до однородной массы, добавляем измельченный чеснок, сок половинки лимона и заправляем растительным маслом/оливковым маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12034,'Перемешиваем и икра готова.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12035,'Курицу вымыть, разрезать острым ножом на порционные куски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12035,'Обжарить на сковороде с толстыми стенками в течение пяти минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12035,'Слить в отдельную емкость выделившийся сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12035,'Репчатый лук очистить, нарезать полукольцами, добавить к курице.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12035,'Всыпать специи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12035,'Жарить до полуготовности, можно подливать воду, чтобы продукты не подгорели.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12035,'Добавить сливочное масло.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12035,'Клубни картофеля очистить и вымыть, нарезать кубиками, варить до полуготовности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12035,'В форму для запекания положить курицу, лук, картофель, томаты. Накрыть блюдо фольгой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12035,'Прогреть духовой шкаф до температуры 180 градусов, поставит противень с чахохбили на полчаса.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12036,'Курицу хорошо промыть, разрезать на куски средней величины, удалить кости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12036,'Сковороду прогреть, обжарить мясо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12036,'Нарезать репчатый лук, обжарить на сковороде на сливочном масле до золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12036,'Обжарку переложить к курице, добавить лавровый лист, томатный соус, специи для чахохбили.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12036,'Через две минуты добавить очищенные и разрезанные пополам помидоры.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12036,'Все продукты переложить на противень с бортиками, накрыть листом фольги.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12036,'Поставить блюдо в духовой шкаф на двадцать пять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12036,'Температура приготовления – 180 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12037,'Шампиньоны промыть, обсушить, подрезать острым ножом и вынуть ножки (не выбрасывать).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12037,'Форму, в которой будет запекаться блюдо, выстелить пекарской бумагой и разложить по ней шляпки грибов так, чтобы получившиеся отверстия «смотрели» вверх.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12037,'Куриное филе нарезать маленькими кусочками и в течение 5 минут обжарить их, помешивая, в сковороде с разогретым на среднем огне растительным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12037,'Ножки шампиньонов мелко порезать, добавить их к курице и жарить все вместе еще 5 минут, не забывая помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12037,'Муку смешать со сметаной и, уменьшив огонь, влить получившуюся смесь в курино-грибную массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12037,'Содержимое сковородки посолить, поперчить, перемешать и тушить на протяжении 8-10 минут: масса должна загустеть. Снять сковороду с огня и дать ее содержимому остыть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12037,'На терке натереть фету, добавить сыр и измельченную петрушку к курице с грибами, хорошо перемешать. Равномерно распределить получившуюся начинку по форме между шляпками грибов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12037,'Сыр моцарелла натереть на терке и сверху посыпать ей содержимое формы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12037,'Запекать шампиньоны с курицей и сыром при 180 градусах в районе 15-20 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12037,'Готовому блюду дать слегка остыть, после чего подать к столу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12038,'Готовим фарш: пропускаем через мясорубку куриное филе и луковицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12038,'Натираем на терке сыр и яблоки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12038,'На дно формы, смазанной маслом, помещаем фарш, затем яблоки и сверху натертый сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12038,'Смазываем верх сметаной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12038,'Отправляем в духовку на 40 мин. при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12038,'Готовой запеканке даем настояться 20 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12039,'Влить в кастрюлю немного воды и отварить в ней очищенный картофель, после чего воду слить, а корнеплоды обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12039,'Горячий картофель размять, добавить сливочное масло, измельченный укроп, тертый сыр (любой).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12039,'Массу тщательно перемешать, предварительно ее, поперчив и посолив.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12039,'Из сметаны, муки, соли, кефира, яиц и сливочного масла замесить густое тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12039,'На кусочки по 50 г разделить получившийся тестяной кусок и каждый шарик раскатать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12039,'Положить в центр каждой лепешки подготовленную начинку и хорошенько защипать края.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12039,'С обеих сторон обжарить чебуреки с картофелем и твердым сыром на довольно горячем растительном масле.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12039,'Переложить готовые чебуреки на бумажные салфетки, чтобы они впитали лишний жир, а затем подать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12040,'Куриную тушку вымыть, обсушить и разрезать на порции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12040,'Обжарить мясо в казане или в глубокой сковороде с толстыми стенками, без масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12040,'Нашинковать лук, добавить к курице вместе с чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12040,'Потушить несколько минут, влить сухое белое вино, томатную пасту, приправить специями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12040,'Накрыть блюдо крышкой, потомить 40 минут, огонь – минимальный.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12041,'Мясо промыть, обсушить в дуршлаге, разрезать на небольшие порции, затем на кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12041,'Обжарить в прогретом сотейнике до золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12041,'Добавить сливочное масло и нарезанный репчатый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12041,'Через пятнадцать минут добавить очищенные помидоры.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12041,'Очистить и измельчить грецкие орехи, добавить в основную массу, приправить любимыми специями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12041,'Все вместе потушить пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12042,'Куриное мясо обсушить, удалить кости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12042,'Филе нарезать на кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12042,'Нашинковать репчатый лук полукольцами, чеснок мелко нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12042,'Прогреть глубокую сковороду, обжарить мясо в течение пяти минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12042,'Добавить лук, специи, помидоры, сладкий болгарский перец, чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12042,'Через несколько минут блюдо посолить, влить сухое грузинское белое вино.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12042,'Все вместе потушить до готовности и всыпать рубленую зелень.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12043,'Нарезать курицу, баклажаны, помидоры, красный болгарский перец, лук, чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12043,'Баклажаны заранее запечь в духовом шкафу, удалить кожицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12043,'Прожарить муку на сухой сковороде, подлить молоко.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12043,'Через три минуты добавить баклажаны, соль, острый перец, все вместе потомить еще несколько минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12043,'Куриное мясо обжарить до румяной корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12043,'Добавить перец и лук, помидоры, измельченный чеснок, тушить блюдо полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12043,'Полить курицу соусом из баклажанов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12044,'Кабачки натереть на мелкой терке, отжать лишнюю жидкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12044,'Мякоть перемешать с тертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12044,'Вбить сырые куриные яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12044,'Добавить рубленую зелень и специи, всыпать муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12044,'Масса должна получиться густой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12044,'Сформовать котлеты столовой ложкой, жарить с двух сторон на заранее прогретой сковороде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12045,'Перец освобождаем от хвостиков и семян. Выкладываем перцы в подходящую посуду, где будем тушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12045,'Измельчаем грибы, лук, чеснок, зелень и мяту, томатную пасту разводим водой до состояния томатного сока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12045,'Готовим начинку: обжариваем на растительном масле лук и чеснок, добавляем шампиньоны, разведенную водой томатную пасту и булгур.  Обжариваем все до испарения жидкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12045,'Доводим начинку до вкуса: добавляем соль, сахар, перец, зелень укропа и мяты, всыпаем изюм и тщательно перемешиваем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12045,'Наполняем каждый перец начинкой на 2/3, т.к. в процессе тушения булгур набухнет.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12059,'С одной стороны натереть хлеб чесноком, выложить по кружочку помидора и рыбки из банки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12045,'Вливаем воду так, чтобы она по уровню была чуть ниже краев перца и добавляем лимонный сок (тогда перец останется целеньким и мягким, а шкурка перца не отделится от его мякоти).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12045,'Тушим под закрытой крышкой примерно 35 минут, до готовности булгура.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12046,'До 175 градусов разогреть духовку, разморозить слоеное тесто при комнатной температуре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12046,'Порезать или поломать шоколад на мелкие кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12046,'Посыпать рабочую поверхность мукой и немного раскатать на ней оттаявшее тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12046,'Разрезать тестяной пласт на желаемое количество квадратов одинакового размера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12046,'Положить в центр каждой заготовки 2 ст. л. подготовленного шоколада и смазать все края предварительно взбитым яйцом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12046,'Сверху накрыть квадрат с шоколадом другим тестяным квадратом и при помощи вилки защипать края.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12046,'Выложить на противень все слойки с шоколадом, смазать их яйцом (взбитым) и выпекать до зарумянивания 15 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12046,'Готовым изделиям дать остыть, посыпать их сахарной пудрой и подать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12047,'Смешиваем сухие ингредиенты: муку, какао, соль, ванилин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12047,'В другой емкости: смешиваем воду, растительное масло, кофе, сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12047,'Затем смешиваем все ингредиенты и замешиваем тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12047,'Отправляем торт выпекаться при температуре 180 градусов на 40-45 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12047,'При желании, торт можно разрезать на несколько частей и смазать любым кремом и покрыть торт шоколадной глазурью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12048,'На небольшие кусочки поломать шоколад чистыми руками и переложить его в кастрюльку или миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12048,'Добавить в емкость с шоколадом сливочное масло и, поставив посудину на небольшой огонь или водяную баню, растопить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12048,'В растопленную масляно-шоколадную массу влить коньяк и дать ей практически закипеть, но ни в коем случае не кипятить смесь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12048,'Массу немного остудить, после чего накрыть посудину пищевой пленкой и на 20 минут поместить в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12048,'Слепить из остывшего шоколада желаемое количество конфет любой формы и обвалять их в какао-порошке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12048,'Убрать конфеты на 10 минут в холодильник, после чего снова обвалять их в какао.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12048,'Подавать конфеты «Трюфель» с коньяком по-домашнему лучше с коньяком, но также подойдет чай или кофе.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12049,'Натереть на терке твердый сыр и кабачки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12049,'Добавить зелень, яйца и специи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12049,'Массу перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12049,'Всыпать муку, масса должна стать клейкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12049,'Наполнить силиконовые формочки, запечь в духовом шкафу в течение 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12049,'Температура приготовления – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12050,'Кабачки очистить от кожуры, мякоть натереть на терке, отжать от лишней влаги.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12050,'Сыр также натереть, перемешать с кабачковой массой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12050,'Массу посолить по вкусу, добавить давленый чеснок, рубленую зелень и любые приправы для овощей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12050,'Вбить сырые яйца, всыпать муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12050,'Фарш должен получиться густым.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12050,'Сформовать небольшие круглые котлеты, обвалять их в панировочных сухарях, жарить до румяной корочки с двух сторон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12051,'Если для приготовления блюда использовать молодые кабачки, то их можно не чистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12051,'Спелые овощи лучше почистить, натереть и посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12051,'Через некоторое время массу отжать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12051,'Всыпать манку, оставить на время для набухания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12051,'Вбить сырое яйцо, всыпать любую рубленую зелень, острый перец.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12051,'Сформовать котлеты произвольной формы, жарить на сковороде с двух сторон до коричневатой корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12052,'В мелкую крошку поломать овсяное печенье (или пшеничное), смешать его со сливочным растопленным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12052,'Выложить получившуюся массу в форму, сделать бортики и основу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12060,'Багет нарезать ломтиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12060,'Помидоры вымыть, нарезать кружками, лучше выбрать плотные сорта.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12060,'Натереть сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12052,'На кусочки поломать шоколад, влить к нему сливки (4 ст. л.) и на водяной бане все это растопить. Мешать шоколад, пока он не станет гладким и однородным, после чего снова добавить сливки (3 ст. л.) и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12052,'Массу хорошенько размешать, вылить слоем поверх печенья в форме и разровнять.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12052,'Убрать форму в морозилку на 15 минут, как только шоколад схватится, переставить ее в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12052,'Для творожного слоя нужно смешать нежирный творог со сливками (10%) и сахаром (5-6 ст.л.), взбить массу до гладкости.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12052,'В воде замочить желатин, убрать его в сторону, чтобы набух.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12052,'На медленной скорости взбить до кремообразного состояния сливки (35%) с сахаром (2-3 ст.л.).',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12052,'Ввести взбитые сливки в творог, всыпать ванилин и влить ликер (если используется) и еще раз все взбить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12052,'В микроволновой печи подогреть (не перегреть) до полного растворения разбухший желатин и, не переставая взбивать, подмешать его в творожную массу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12052,'В течение нескольких минут продолжать взбивать творог, пока масса не станет однородной.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12052,'Получившуюся массу вылить на шоколадный слой, разровнять и убрать творожный торт с шоколадом на 3 часа (лучше на ночь) в холодильник.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12053,'Приготовить фарш из куриного мяса или использовать готовый продукт из магазина.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12053,'Очистить репчатый лук и кабачки, натереть на терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12053,'Добавить рубленую петрушку, укроп.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12053,'Заправить специями, вбить яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12053,'Мясной фарш соединить с овощным.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12053,'Сформовать котлеты, жарить на масле или использовать сковороду с антипригарным покрытием.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12053,'Обжарить с двух сторон.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12054,'Фарш можно приобрести в магазине или приготовить самостоятельно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12054,'Пропустить через мясорубку лук и кабачки, другой вариант – перебить в кухонном комбайне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12054,'Добавить измельченную зелень, сушеные травы, специи, яйца, чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12054,'Из готового фарша сформовать котлеты, жарить до румянца на хорошо прогретой сковороде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12055,'К креветками добавить паприку, чеснок раздавленный, соль, перец, острый перец, цедру лайма и тщательно перемешаем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12055,'Подготовим другие ингредиенты. Порежем салат, манго и авокадо кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12055,'Теперь пожарим креветки и выжмем сок из лайма.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12055,'Теперь разогреем тортилью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12055,'После можно собирать тако, добавим майонез, салат, авокадо, манго и сверху добавим креветки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12056,'Картофель отварить в «мундире».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12056,'Натереть остывший и очищенный картофель и кабачки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12056,'Овощи перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12056,'Добавить приправы, муку, зелень, по желанию чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12056,'Слепить котлеты небольшого размера, обжарить на растительном масле.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12057,'Приготовить фарш из индейки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12057,'Добавить натертый на крупной терке кабачок, лишний сок отжать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12057,'Вбить яйца, нарезанную зелень, соль, муку, приправы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12057,'Приготовить небольшие круглые котлеты, присыпать мукой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12057,'Жарить по несколько минут с каждой стороны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12058,'В подсоленной воде отварить спагетти, затем слить с них воду и переложить в форму, предварительно смазанную маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12058,'На сковороде до коричневатого цвета обжарить свиную колбасу и переложить ее на тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12058,'До хрустящей корочки обжарить на той же сковородке в течение 4 минут пепперони.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12058,'Выложить обжаренную колбасу на спагетти, полить ее томатной пастой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12058,'Распределить по пасте 1/2 часть пепперони, затем смесь тертых  твердых сыров и завершить все оставшейся половиной пепперони.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12058,'Выпекать блюдо 30 минут в духовке при 1750  градусах: сыр начнет плавиться и приобретать коричневатый оттенок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12058,'Подаются спагетти, запеченные с пепперони и сыром на сервировочном блюде, либо перед подачей режется на порционные куски.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12059,'Ломтики черного хлеба обжарить с двух сторон до корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12060,'Хлебные ломтики намазать майонезом, выложить по кружку томата, шпроты из банки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12060,'Нарисовать майонезную сетку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12060,'Закуску посыпать тертым сыром и зеленым луком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12060,'Бутерброды запечь в микроволновой печи, время: от трех до пяти минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12061,'Багет нарезать ломтиками средней толщины, подсушить в духовом шкафу до легкого хруста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12061,'Смазать ломтики майонезом, в него можно добавить давленый чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12061,'Отварить куриные яйца, остудить, очистить и нарезать тонкими ломтиками наискосок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12061,'Сверху выложить маринованные огурцы, также нарезанные по диагонали.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12061,'Добавить по рыбке из банки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12061,'Готовые бутерброды украсить свежим укропом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12062,'Смешиваем просеянную муку и дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12062,'Растапливаем 2/3 сливочного масла, добавляем теплое молоко, сахар (30 г оставляем на посыпку), соль и яйцо. Все перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12062,'Добавляем жидкую составляющую в муку. Замешиваем тесто и отправляем в теплое место на 40 минут подходить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12062,'Обминаем тесто и выкладываем в форму диаметром 26-28 см смазанную маслом, формируя небольшие бортики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12062,'Сливы разрезаем на 2 или 4 части и выкладываем на тесто срезом вниз, слегка вдавливая их в тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12062,'Сверху сливы посыпаем оставшимся сахаром, смешанным с корицей.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12062,'Поверх слив выкладываем кусочки сливочного масла. Даем пирогу подойти в течении 20 мин.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12062,'Отправляем пирог в разогретую духовку на температуру 175 градусов примерно на 35-40 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12063,'Сыр нарезаем на ломтики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12063,'Колбасу тоже нарезаем на ломтики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12063,'Пекинскую капусту нарезаем на 4 части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12063,'Помидор нарезаем на полукольца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12063,'При помощи тарелки тонкий лаваш нарезаем по кругу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12063,'На подготовленный лаваш укладываем пекинскую капусту, помидор, колбасу и сыр. И заворачиваем в виде "Тако"',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12063,'На разогретой сковороде поджариваем нашу закуску до корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12064,'В кастрюльке смешать сливочное масло, сахар, муку и яичные желтки (3 шт.), растереть все до однородной консистенции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12064,'Поставить емкость с массой на средний огонь, добавить молоко и дать содержимому кастрюли закипеть, при этом ее необходимо все время помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12064,'Поварить массу в течение 15 минут, после чего всыпать ванилин и убрать кастрюлю с огня.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12064,'Получившуюся массу остудить при частом помешивании (чтобы не образовалась корка), как только она станет еле теплой, добавить желтки (2 шт.) и перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12064,'В густую пену взбить белки, ввести в них 2 ч. л. сахарной пудры и еще раз взбить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12064,'Аккуратно подмешать взбитые белки в остывшую массу и немного перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12064,'Огнеупорную посуду смазать маслом и чуть присыпать мукой, выложить в нее получившуюся массу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12064,'Выпекать молочное суфле с ванилином 15-20 минут в предварительно разогретой до 220-260 градусов духовке.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12064,'Готовое суфле сразу же посыпать сахарной пудрой и подать к столу, так как оно быстро оседает.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12065,'В подсоленной воде отварить до готовности куриные грудки, после чего нарезать его полосками, либо чистыми руками разобрать на волокна.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12065,'Сыр измельчить на крупной терке, маринованные огурцы порезать полосками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12065,'Смешать в большой миске мясо, корейскую морковь, сыр и огурцы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12065,'Через пресс пропустить очищенный чеснок и добавить в миску с подготовленными ингредиентами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12065,'В  салат с курицей,  корейской морковью и маринованными огурцами добавить майонез и все хорошенько перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12065,'Перед подачей салат можно при желании украсить рубленой свежей зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12066,'Черный зерновой хлеб нарезать треугольниками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12066,'Обжарить на горячей сухой сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12066,'Натереть сырую морковь, перемешать с рублеными орехами, давленым чесноком и майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12066,'Покрыть хлеб морковной пастой. Выложить по рыбке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12067,'Зелень мелко порубить, пропустить чеснок через пресс, красный лук мелко нашинковать, перец чили мелко порезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12067,'Все подготовленные ингредиенты сложить в чашу блендера, влить белый винный уксус и оливковое масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12067,'Добавить в чашу соль, французскую черную горчицу и молотый перец, измельчить содержимое чаши до мелких кусочков (не должно получиться пюре).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12067,'Готовый «Чимичурри» подавать с любым мясным блюдом или овощами гриль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12068,'Хлеб нарезать ломтиками, можно использовать формочки для печенья.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12068,'Подсушить на противне в духовом шкафу или на сухой сковороде с антипригарным покрытием.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12068,'Натереть чесноком, смазать майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12068,'Отварить и остудить яйца, натереть, насыпать на соус, соль – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12068,'Выложить рыбу, небольшие кусочки помидоров и рубленую петрушку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12068,'Бутерброды украсить тонкими ломтиками лимона.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12069,'Белый хлеб обжарить с обеих сторон до корочки на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12069,'Натереть свежим чесноком, намазать майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12069,'Тонкими овальными пластинками нарезать огурцы вместе с кожурой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12069,'Выложить шпроты, сверху – огурцы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12069,'Украсить зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12070,'Нарезать батон или купить уже готовый продукт.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12070,'Смазать майонезом или сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12070,'Тонкими пластинками нарезать соленые огурцы, натереть твердый сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12070,'Выложить на хлеб огурцы, затем шпроты, сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12070,'Бутерброды выложить на плоское широкое блюдо, поставить в духовой шкаф, время – от восьми до девяти минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12070,'Другой вариант – использовать микроволновую печь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12071,'Хлеб нарезать, обжарить на масле до хрустящей корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12071,'Тонко нарезать хорошо вымытый лимон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12071,'Выложить на хлеб, сверху – шпроты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12072,'Тонко нарезать говядину.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12072,'Говядину положить в миску, добавить чеснок. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12072,'Лапшу замочить в холодной воде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12072,'Нарезать лук, морковь, зеленый лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12072,'В воду добавить соль, довести до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12072,'В кипящую воду выложить лук, морковь, зеленый лук и мясо.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12072,'Добавить лапшу, варить 5 мин.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12072,'Добавить грибы, варить 10 мин.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12073,'Подготовить рыбу: отрезать голову, удалить глаза и жабры, отделить филе и убрать его в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12073,'В кастрюлю сложить хвост, скелет, кожу и голову рыбы, залить все холодной чистой водой так, чтобы она покрыла рыбу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12073,'Поставить емкость на большой огонь, дать воде закипеть, снять появившуюся пену шумовкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12073,'Огонь сделать средним, положить к рыбе лавровый лист, перец, очищенную луковицу и одну морковь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12073,'Варить бульон в течение 30 минут при слабом кипении, после чего достать из кастрюли все, что в ней варилось.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12073,'Процеживать бульон до тех пор, пока он не станет прозрачным, затем его посолить и снова поставить на огонь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12073,'Небольшую луковицу мелко нашинковать, морковь измельчить на мелкой терке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12073,'До прозрачности обжарить лук в небольшом количестве масла, добавить к нему морковь и готовить овощи вместе до мягкости.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12073,'Очищенный картофель нарезать мелкими кубиками и отправить в кипящий рыбный бульон.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12073,'В сливочном масле обжарить 1 ст. л. (без верха) муки, влить в сковородку немного бульона и размешать смесь до однородности.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12073,'За несколько минут до готовности картофеля добавить в суп луково-морковную и мучную смеси.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12073,'Отложенное филе лосося нарезать кусочками, которые будут немного крупнее картофеля, и положить в кастрюлю с овощами.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12073,'В суп влить сливки, засыпать измельченный укроп, довести все до кипения и выключить огонь.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12100,'В центр насыпать крошку и положить дижонскую горчицу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12073,'Подавать сливочный суп с лососем и зеленью в горячем виде со свежим хлебом, посыпав перед подачей рубленой петрушкой.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12074,'Смешать с 1 ст. л. сахара предварительно очищенную от косточек вишню (свежую, консервированную или замороженную).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12074,'С остальным сахаром взбить яйца, влить молоко и посолить яичную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12074,'Не прекращая взбивать, ввести муку в массу и мешать, пока не получится тесто однородной консистенции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12074,'В форму, смазанную маслом, слоем выложить подготовленные ягоды и залить их получившимся тестом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12074,'Выпекать французский десерт «Клафути с вишней» на протяжении 40 минут при 180 градусах.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12074,'Посыпать готовое изделие перед подачей сахарной пудрой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12075,'Заранее достать масло из холодильника, чтобы размякло, смешать с молоком и сахаром, слегка нагреть до полного растворения сахара и образования гомогенной смеси.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12075,'Для приготовления коржей перемешать масло с добавлением какао, муки и разрыхлителя, вбить яйца очень хорошо перемешать. Переложить полученную массу в подготовленную форму, отправить ее на 50-60 минут в духовку с температурой около 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12075,'Пока печется основа сделать ганаш. Положить в небольшую кастрюльку кусочки черного шоколада, масло сливочное, налить сливки, слегка подогреть на слабом огне до расплавления шоколадных кусочков. Дать массе чуть остыть, перемешать миксером до однородности, всыпать сахар, сухое молоко, добавить солод, хорошенько взбить и дать остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12075,'Очень осторожно разрезать готовый корж на 4 части, но если не получится, то на 3. Каждый корж промазать кремом, облить глазурью (оставить часть для оформления верха), собрать торт, убрать в холодильник на полтора часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12075,'Достать шоколадный торт из холодильника, равномерно размазать оставшийся ганаш по верху торта, оформить конфетами Maltesers.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12076,'Белый хлеб нарезать ломтиками средней толщины, выложить на противень, застеленный пергаментом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12076,'Прогреть духовой шкаф, поставить хлеб на одну или две минуты для запекания. По желанию можно использовать тостер.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12076,'Шпроты достать из банки, размять вилкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12076,'Добавить майонез, белый репчатый лук, нарезанный мелкими кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12076,'Если лук острый, его заранее можно окатить кипящей водой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12076,'Хлеб смазать мягким сливочным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12076,'Сверху выложить кружки очищенных плодов киви, рыбную смесь с майонезом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12077,'Порезать курятину на небольшие куски, чуть обжарить в оливковом масле, почистить и порезать овощи: картошку – на кубики, морковку – полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12077,'Переложить мясо в кастрюлю с бульоном или водой, дать закипеть, приправить лаврушкой, душистым перчиком, поварить минут 7, сделать меньший нагрев, всыпать нарезку овощей, проварить примерно четверть часа после закипания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12077,'Плавленый сыр порезать на маленькие кусочки (а можно заморозить и натереть на терке), высыпать в бульон, перемешать до полного растворения, приправить перцем, солью. Порубить зелень, всыпать в сырный суп с куриным филе и овощами, дать закипеть, снять с плиты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12078,'Нарезать белый хлеб кружочками, подсушить на сковороде без масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12078,'Натереть чесноком в горячем виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12078,'Натереть сыр на мелкой терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12078,'Шпроты вынуть из банки, удалить хвосты и крупные кости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12078,'Рыбу размять вилкой, перемешать с сыром и майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12078,'Намазать бутерброды получившейся массой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12078,'Тонко нарезать свежие огурцы, сложить в виде паруса, установить на бутерброды, закрепить зубочистками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12079,'Натереть чеснок и твердый сыр отдельно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12079,'Вместо свежего чеснока можно взять гранулированный продукт.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12079,'Ингредиенты перемешать, заправить майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12079,'Черный хлеб нарезать, поджарить в духовке, ломтики остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12079,'Шпроты вынуть из банки, выложить на бумажное полотенце, чтобы лишнее масло впиталось.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12079,'Шпроты превратить в кашицу при помощи блендера, перемешать с сыром и посолить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12079,'Выложить паштет на хлеб, сверху – кружки огурца и вареного яйца. Готовую закуску украсить рубленой зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12080,'Хлеб нарезать ломтиками, обжарить на сковороде с маслом до хрустящей корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12080,'Смазать ломтики майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12080,'Крабовые палочки разморозить и аккуратно развернуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12080,'Внутрь поместить по рыбке из банки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12080,'Часть крабовых палочек покрошить и насыпать на майонез.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12080,'Выложить завернутые шпроты, украсить кусочками свежих помидоров.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12081,'Тонко нарезать хлеб, обжарить на сухой сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12081,'Раздавить чеснок, перемешать с майонезом, намазать кусочки багета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12081,'Сверху насыпать тертый сыр, выложить кусочки отваренных перепелиных яиц, рыбу и тонко нарезанный полукружочками свежий огурец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12082,'Достать за несколько часов до приготовления полпачки масла, смешать его в чаше блендера с яйцами до однородности, влить сгущенку, взбить, влить уксус, смешанный с содой, еще раз взбить. Засыпать муку, тщательно вымесить до густоты хорошей сметаны, полученную массу поделить на две части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12082,'Одну часть оставить, вторую смешать с порошком какао, поместить их в формы, поставить в духовку с температурой в 180 градусов, печь коржи для торта порядка 20 минут. Коржи достать, дать остыть, каждый разрезать вдоль, т.е. должно получиться 2 светлых и 2 «шоколадных» коржа, аккуратно обрезать у каждого краешки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12082,'Каждый корж промазать кремом, сложить в стопку: темный – светлый – темный – светлый. Бока домашнего нежного торта «Сметанник»  тоже аккуратно смазать кремом. Смешать для глазури хорошее сливочное масло, сахар, какао, молоко. Поставить сотейник на  плиту, нагреть до закипания, убрать, остудить, нанести наверх десерта глазурь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12083,'Подготовить для варки рис, залить его холодной водой, оставить на час. Рисовый уксус подогреть, всыпать в него соль с сахаром, размешать, поставить остывать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12083,'Выложить рис на сито, дать постоять полчаса, налить 360 мл воды в кастрюлю, пересыпать рис, дать закипеть, проварить 5 минут под крышкой, уменьшить нагрев до минимума, проварить еще 5 минут, убрать с плиты, крышку не открывать, дать постоять 10 минут. Влить в рис уксус, размешать, остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12083,'Рыбу порезать на небольшие кусочки, перемешать с маслом авокадо и кунжутным семенем, убрать в холодильник. Удалить у большого огурца шкурку, порезать ломтиками, разрезать пополам авокадо, убрать косточку, почистить, порезать кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12083,'Подготовить форму, вырезать лист нори по размерам, переложить его на дно. Смочить руки водой, положить примерно половину риса на лист, разровнять, придавить. Поверх риса положить огурец, авокадо, завершить лососем, повторить все операции еще раз. Убрать суши-торт из огурца, лосося и авокадо в холодильник, достать перед самой подачей к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12084,'Перебрать и промыть рис, сварить в соленой воде, промыть. Мясо грудки некрупно порезать. Перемешать вместе рис, яйца, мясо, сметану, подсолить, переложить в подготовленную форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12084,'Готовить примерно минут 40 до красивой корочки золотистого колера, температуру духовки поддерживать около 200 градусов, верх домашней запеканки из индейки с рисом посыпать сыром (по желанию), оформить веточками зелени.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12085,'Измельчаем зелень и смешиваем со специями, добавляем туда же растительное масло.','https://vkuso.ru/data/cache/data/01/18eb54d50f6cf01_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12085,'Хорошо промытый картофель, разрезаем на 6-8 частей вдоль и отправляем его вариться на 2 минуты после закипания.','https://vkuso.ru/data/cache/data/12/d8476b600a44d12_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12085,'Горячий картофель отправляем в подготовленную смесь из специй и перемешиваем. В форму для выпекания выкладываем картофель шкуркой вниз в один слой.','https://vkuso.ru/data/cache/data/ef/0cd778c60ecaaef_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12085,'Отправляем в духовку на 200 градусов на 20-30 мин. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12086,'Обжарить кубики лука до изменения цвета, добавить паприку, тщательно перемешать, прогреть пару минут, чтобы паприка пропиталась жиром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12100,'Бородинский хлеб сбрызнуть оливковым маслом, поставить в духовку, подсушить, затем превратить в крошку при помощи блендера.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12086,'Порезать довольно крупными кусками мясо, положить к луку, сдобрить перцем, подсолить, обжарить на сильном огне, влить чуть воды, прикрыть крышкой, готовить около часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12086,'Порезать морковь, болгарский перец, помидоры, мелко порубить чеснок. Высыпать все к мясу, влить еще воды (горячей), перемешать, закрыть крышкой, продолжить тушить четверть часа, мясо должно стать мягким.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12086,'Нарезать крупно картофель, положить к мясу, тушить до его готовности, убрать с плиты, крышку не снимать, гуляш из говядины с болгарским перцем и картофелем должен «дозреть».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12087,'Ржаной хлеб нарезать ломтиками толщиной в один сантиметр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12087,'Выложить хлеб на противень, поставить в духовой шкаф.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12087,'Печь двадцать минут, температура – 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12087,'Ломтики перевернуть, обжарить с другой стороны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12087,'Хлеб остудить, намазать сливочным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12087,'Сельдь очистить, вынуть косточки, филе нарезать кусочками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12087,'Выложить на масло, посыпать рубленым зеленым луком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12088,'Взять горшочки (примерно чуть больше 500 мл.), заложить в них кусочки мяса, моркови, лук, засыпать крупу, залить подсоленной водой (ниже края на 2 пальца).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12088,'Прикрыть горшочки крышками, установить в духовку с температурой в 160 градусов. Гречка с мясом и овощами в горшочках будет готова примерно через 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12089,'Свеклу отварить, натереть, добавить измельченный чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12089,'Черный хлеб нарезать треугольниками, смазать свекольной массой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12089,'Выложить кусочки филе сельди.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12089,'Бутерброды украсить кольцами репчатого лука.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12090,'Бородинский хлеб нарезать ломтиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12090,'Филе очистить от кожицы и костей, нарезать полосками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12090,'Киви также очистить и нарезать кружками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12090,'Хлеб намазать маслом, положить киви и сельдь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12091,'Морковь хорошо вымыть, отварить и очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12091,'Сельдь очистить, отделить кости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12091,'Плавленый сыр, морковь, сельдь размельчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12091,'Продукты перемешать с майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12091,'Белый батон нарезать кружками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12091,'Намазать рыбной пастой, посыпать рубленой зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12092,'Багет нарезать ломтиками средней толщины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12092,'Очистить сельдь, филе нарезать кусочками, сыр – кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12092,'Зелень вымыть и обсушить, измельчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12092,'Перемешать с сыром и сельдью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12092,'Хлеб намазать сырно-селедочной массой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12093,'Зажарить в сметане пластинки грибов и полукольца лука, дать постоять (до полого остывания), переложить первым слоем в салатник с широким дном.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12093,'Сварить филе курицы, остудить, порезать на одинаковые кусочки, положить поверх грибов, промазать майонезом – это второй слой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12093,'Для третьего слоя сварить яйца, охладить, натереть или мелко нарезать на кубики, промазать майонезом. Открыть банку с ананасами, сок сцедить, плоды порезать мелкими кубиками, прикрыть ими яичный слой, промазать майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12093,'Последним слоем салата с курицей и ананасом «Хэлэл» выложить натертый сыр, оформить кружками киви.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12094,'Очень хорошо промыть изюм, залить на минуту крутым кипятком, слить воду, ягоды обсушить. Всыпать в творог сахар (половину необходимого по рецепту количества), вбить яйца, добавить ванилин, тщательно размешать, чтобы не было больших комочков. Всыпать постепенно муку, добавить изюм, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12094,'Прогреть сковороду, налить немного масла, смочить руки маслом, взять небольшое количество творожного теста, скатать колобок, обмакнуть в муку, расплющить, обжарить с каждой стороны до аппетитного румяного цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12094,'Теперь заключительный и уникальный момент приготовления сырников с изюмом как у бабушки. Сложить слоями сырники в толстостенную посуду, каждый пересыпать сахаром и проложить кусочками масла. Предварительно масло можно растопить и полить сверху сырники.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12100,'Замороженную рыбу освободить от пленки, нарезать на кусочки, выложить по кругу на тарелку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12094,'Поставить заполненную посуду на полчаса тушиться в духовку. К столу блюдо подать с вареньем из кислых фруктов или ягод и сметаной, запить можно морсом или молоком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12095,'Порезать рыбу на куски, присолить, поперчить, переложить в подходящую форму, присыпать рубленым чесноком. Помидор разрезать пополам, а потом — на полукольца. Смазать рыбу хорошей сметаной, прикрыть пластинками помидора, присолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12095,'Натереть сыр, зелень порубить мелко ножом, смешать вместе,  щедро присыпать помидоры. Запекать  рыбу с помидорами под сыром в духовке полчаса с температурой 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12096,'Для начинки нашинковать зеленый лук (часть оставить для добавления к тесту), смешать с измельченными на крупной терке яйцами, приправить черным перцем, присолить, перемешать. Смешать сырые яйца и кефир, присолить, добавить муку, соду, оставшуюся часть лука, хорошо все взбить, тесто должно напоминать густую сметану.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12096,'Вылить на подготовленный противень половину теста, уложить на него начинку и небольшие кусочки сливочного масла, прикрыть второй половиной теста. Поставить пирог с яйцом и зеленым луком на кефире в духовой шкаф, запечь до образования красивой аппетитной и румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12097,'Включить прогреваться духовку до 180 градусов. Разбить в чашу блендера яйца, взбить до получения светлой массы, добавить муку и порошок какао, просто перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12097,'Подобрать подходящую форму, смазать маслом, перелить  тесто, задвинуть ее в уже прогретую духовку. Выпекать около 25 минут, достать, дать хорошо остыть, порезать на три коржа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12097,'Для приготовления крема в молоко добавить муку и яйца, перемешать, поставить кастрюльку на плиту, помешивая довести до состояния густой однородной смеси, всыпать какао, еще раз перемешать, остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12097,'Коржи смазать кремом, сложить друг на друга в стопку, поставить в холодильник часов на шесть. Подогреть сливки, поломать шоколад, растопить, перемешать, достать торт, полить глазурью, дать ей застыть. Шоколадный бисквитный торт в глазури готов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12098,'Разрезать слегка подсушенный батон на два длинных куска, удалить всю мякоть, оставить только твердые стенки и дно. Все составляющие части порезать на кубики, зелень мелко нашинковать. Дно и стенки подготовленного батона тонко промазать маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12098,'Заполнить половинки начинкой, выкладывать слоями в следующем порядке: колбаса, кусочки помидора, зелень укропа с петрушкой, твердый сыр, майонез, поставить в прогретую духовку минут на 10. Домашние горячие бутерброды на скорую руку готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12099,'Влить в воду масло, перемешать, добавить, предварительно растворенную  в небольшом количестве воды соль, всыпать, перемешивая (постепенно) сквозь сито муку. Должно получиться довольно упругое, но эластичное тесто, прикрыть полотенцем, забыть минут на 20, приготовить за это время начинку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12099,'Хорошо отжать капусту от рассола, положить в сковороду с прогретым маслом, тушить до полной готовности. Обжарить до золотистости в отдельной сковороде кубики лука, добавить в конце обжарки рубленый укроп, слегка поперчить, перемешать, объединить с капустой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12099,'Раскатать «отдохнувшее» тесто в пласт (примерно как для лапши), порезать квадратами приблизительно 20х20 см. Уложить в середину каждого горку начинки, но так, чтобы можно было легко соединить противоположные углы и аккуратно защипать по швам',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12099,'Подготовить противень, переложить вэрзэре с квашеной капустой, смазать молочным раствором сахара верхушки пирожков, отправить в духовой шкаф с температурой около 200 градусов, примерно через полчаса пирожки можно будет вынуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12100,'Сельдь очистить, филе нарезать очень тонкими пластинками, часть – просто измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12100,'Отварить морковь и яйцо, нарезать мелкими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12100,'Репчатый лук также нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12100,'Продукты перемешать, добавить жидкий плавленый сыр и растопленное сливочное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12100,'Застелить разделочную доску пищевой пленкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12100,'Выложить тонкую пластинку филе сельди, выложить форшмак, накрыть еще одной пластинкой филе.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12100,'Рыбу намазать маслом, обернуть пленкой, отправить в морозилку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12101,'Маринованные корнишоны нарезать длинными полосками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12101,'Продолговатые булочки с хрустящей корочкой разрезать вдоль так, чтобы они не разделились до конца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12101,'На каждую половину выложить по половинке селедочного филе, накрыть огурцом и луком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12101,'Сэндвичи закрыть, разрезать на несколько порций и подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12102,'В кастрюлю с холодной водой положить говядину. Сварить мясо, и в полученный бульон добавить порезанный кубиками картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12102,'Нарезать свеклу сырую соломкой и обжарить слегка на сковороде. К ней добавить морковь и лук, тоже порезанные, но только кубиками. Обжарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12102,'Далее снять кожицу с помидор и натереть их на терке. Добавить томатную пасту и натертые помидоры в зажарку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12102,'После того, как вся масса немного загустеет, подлить стакан бульона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12102,'Болгарский перец нарезать кубиками и добавить в эту же сковороду. Потушить 10 минут. Пока тушиться, нашинковать капусту.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12102,'Теперь положить зажарку в кастрюлю с бульоном. Когда закипит, добавить капусту и зелень. Немного пусть поварится, затем добавить соль.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12102,'Сало с чесноком растолочь и положить в борщ вместе с лавровым листом. Сразу же выключить плиту. Борщ украинский готов!',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12103,'Сырые куриные яйца отварить, очистить, нарезать пластинками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12103,'Черный хлеб нарезать ломтиками, отправить в духовой шкаф для подсушивания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12103,'Сельдь очистить от костей и кожицы, филе нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12103,'Растопить сливочное масло, перемешать с горчицей, сельдью и рубленой зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12103,'Остывший хлеб намазать получившейся смесью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12103,'Выложить яйца.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12104,'Прокрутить через мясорубку корень хрена.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12104,'Отдельно пропустить через мясорубку спелые помидоры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12104,'Так же поступить с чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12104,'Излишки сока от помидоров можно слить, чтобы приправа была гуще.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12104,'Ингредиенты перемешать, посолить по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12104,'Поставить в холод на полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12104,'Стерилизовать банки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12104,'Наполнить хреновиной.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12104,'Сверху влить немного кипяченого подсолнечного масла.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12105,'Средний кочан цветной капусты разобрать на соцветия, отварить, но с сохранением небольшой жесткости, откинуть на дуршлаг (отвар можно использовать для приготовления овощного супа), облить холодной водой, дать хорошо стечь воде. Если будет необходимость, то непосредственно перед обжаркой дополнительно обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12105,'Смешать блендером яйца, молоко, щепотку соли, сметану и муку до однородной массы. Влить в сковороду большое количество масла, хорошо прогреть, окунуть каждое соцветие  в кляр, обжарить, выложить очень вкусную цветную капусту в кляре на широкое блюдо, выстланное бумажными полотенцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12105,'Порвать на кусочки зелень базилика прямо в чашу блендера, всыпать орешки кедра, добавить пармезан и пару-тройку зубчиков чеснока, влить масло (желательно оливковое), подсолить, взбить до получения однородного соуса песто, переложить в соусник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12105,'Измельчить до состояния пюре очищенные от семян и кожуры мясистые помидоры и пару зубков чеснока, добавить соль, перемешать, всыпать крахмал, довести до однородности. Вылить полученную смесь для томатного соуса в сковороду, проварить до получения желаемой густоты, дать остыть, перелить в соусник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12106,'Пропустить через мясорубку спелые помидоры, горький перец без семян, чеснок и хрен. Количество чеснока можно увеличить до 1 кг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12106,'Соль добавить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12106,'Продукты перемешать, перелить в ведро.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12106,'Накрыть емкость тканью, оставить на пять дней при комнатной температуре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12106,'Массу периодически перемешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12106,'В зависимости от температуры в помещении сбраживание может остановиться раньше или позже.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12106,'Массу переложить в чистые сухие банки или разлить в пластиковые бутылки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12106,'Хранить приправу лучше в холодильнике.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12107,'Корень хрена очистить и обдать кипятком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12107,'Помидоры также обдать кипятком, снять кожицу, удалить плодоножки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12107,'По желанию можно использовать неочищенные томаты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12107,'Все продукты натереть на крупной терке или пропустить через мясорубку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12107,'Ингредиенты перемешать, соль и сахар добавить по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12107,'Варить массу пять минут или дольше, до выпаривания части жидкости.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12107,'Банки стерилизовать, разлить приправу, закрыть крышками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12107,'Оставить до остывания при комнатной температуре.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12107,'Хранить в прохладном месте.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12108,'Натереть корень хрена.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12108,'Перемешать пропущенные через мясорубку помидоры, сливы без косточек, чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12108,'Добавить сахарный песок и соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12108,'Массу положить в банки, закрыть крышками, хранить в холодильнике.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12109,'Яблоки разрезать на четыре части, удалить семена, отварить до мягкости в небольшом количестве воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12109,'Другие варианты: запечь плоды в духовке или мультиварке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12109,'Готовые яблоки протереть через сито или дуршлаг. Кожуру выбросить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12109,'Натереть хрен.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12109,'Добавить в яблочную массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12109,'Добавить соль и сахарный песок, варить хреновину при слабом кипении пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12109,'Массу помешивать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12109,'В конце добавить уксус.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12109,'Закуску переложить в чистые, стерильные банки и закатать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12110,'Для картофельной «шубы» приготовить по обычному рецепту густое пюре, всыпать мелко порубленную петрушку, добавить молотый перец и масло, тщательно смешать. Лист лаваша порезать на 4 части прямоугольной формы (в длину под размер сосиски, а в ширину на 13-14 см)',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12110,'Нанести на каждый кусок лаваша не слишком толстый слой пюре, присыпать стружкой сыра, уложить с краю сосиску, скатать в рулончик. Обжарить сосиски с картофелем в тонком лаваше до красивого соломенного колера со всех сторон, подать с порцией салата, сметаной или с любым острым соусом (для любителей остренького).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12111,'Натереть хрен.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12111,'Отварить и натереть свеклу, сок отжать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12111,'Добавить соль и сахар, уксус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12111,'Если масса получилась слишком густой, добавить холодную кипяченую воду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12112,'Срезать корочку с ржаного хлеба, подсушить ее на сухой сковороде или в духовке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12112,'Белую редьку очистить и пропустить через мясорубку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12112,'Сок слить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12112,'Пропустить через мясорубку хлеб, хрен.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12112,'Продукты перемешать, добавить соль, уксус, мед, молотую гвоздику или сушеную мяту, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12113,'Овощи вымыть, натереть на терке вместе с кожурой, лишнюю жидкость слить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12113,'Вбить сырое куриное яйцо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12113,'Нарезать репчатый лук, ввести в основную массу вместе с мукой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12113,'Добавить по вкусу соль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12113,'Тесто замесить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12113,'Смазать маслом противень, выложить лепешки и поместить в духовой шкаф.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12113,'Время выпекания – от пятнадцати до двадцати минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12114,'Достать заранее масло, переложить в миску, всыпать обычный сахар и ванильный, растереть в однородную массу. В масляную смесь вбить (по одному) все яйца, после каждой добавки все тщательно перемешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12114,'Всыпать в яично-масляный состав постепенно подсоленную муку с разрыхлителем, тесто хорошо вымесить до эластичного состояния, прикрыть тканью, дать постоять около получаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12114,'Присыпать стол мукой, раскатать тесто в пласт, порезать на кусочки желаемой формы. Зажарить в хорошо разогретом масле (в масло закладывать тесто небольшими порциями) до корочки соломенного цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12114,'Вынуть хрустящий хворост классический шумовкой, переложить на широкое блюдо, выстланное бумажными полотенцами. Обсушенный от масла десерт, переложить горкой на тарелку, присыпать сквозь ситечко сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12142,'Кабачки натереть, отжать лишнюю жидкость и добавить специи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12142,'Нарезать укроп, зеленый лук, чеснок, добавить в основную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12115,'Вынуть из морозилки пачку маргарина, половину натереть на крупную терку, всыпать подсоленную муку, к масляной крошке добавить хорошую сметану с содой, вымесить тесто до гладкости, дать ему постоять и «дозреть».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12115,'Измельчить на крупной терке плавленые сырки, вбить 1 яйцо, добавить еще один белок (желток оставить для смазывания), растертую сухую зелень, все присолить и хорошо перемешать. Порезать колбасу кружочками, 4 вареных яйца – на тонкие ломтики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12115,'Шар теста поделить на две части, каждую раскатать, один пласт теста переложить в форму, прикрыть слоем из половины яиц, затем стружкой из плавленого сыра, далее  кружками колбасы и опять яйцами, закрыть другим пластом теста, защипать края вместе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12115,'Смазать верх пирога с плавлеными сырками, колбасой и яйцом разболтанным желтком, отправить форму в духовой шкаф минут на 40. Примерно через 10 минут сделать прокол вилкой в середине пирога для выпускания пара.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12116,'Порезать подготовленное и зачищенное от сухожилий, излишков жира и пленок мясо на примерно одинаковые куски сравнительно небольшого размера. Пару крупных  луковиц разрезать пополам, а потом каждую часть порезать на полукольца. Картофель порезать кусками слегка крупнее, чем говядину',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12116,'В толстостенной кастрюле, а лучше в чугунном казане прогреть масло до видимого дымка, бросить в него мясо, очень быстро обжарить, чтобы оно осталось внутри сочным. Если некоторые куски пристанут к дну посуды, то беспокоиться не надо, поскольку после полного прожаривания они освободятся.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12116,'Когда говядина изменит цвет на светлый в посуду бросить полукольца лука, перемешать, прикрутить огонь, тушить еще четверть часа. Если жидкость выкипела, то влить чуть-чуть бульона или воды. Разрезать корнеплод моркови пополам, а потом каждую половинку нашинковать поперек, обжарить в разогретом масле до изменения цвета, переложить к мясу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12116,'Отправить на освободившуюся сковороду картофель, зажарить до светло желтого колера со всех сторон и тоже пересыпать к мясу. Всю массу сдобрить перчиком, солью и еще раз аккуратно перемешать. Если необходимо, то долить еще чуть воды (картофель должен быть покрыт водой), прикрыть крышкой, убавить огонь до минимального и тушить около 50 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12116,'Через 30-35 минут заправить жаркое лаврушкой, хмели-сунели или другими любимыми специями, но обязательно добавить молотого красного перца примерно половину чайной ложки. Перемешать, закрыть крышку, еще четверть часа тушить на малом огне. Проверить готовность, посуду снять с плиты, и настоять ароматное жаркое из говядины с картофелем под крышкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12117,'Перемешать муку с солью, сахаром и разрыхлителем, вбить пару яиц, взбить до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12117,'Вылить тесто на подготовленный противень, разровнять, отправить в прогретый до 180 градусов духовой шкаф. Выпекать до золотисто-соломенной корочки, для этого хватит всего 6 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12117,'Пока печется основа десерта, чуть подогреть любой джем для начинки, но вкуснее всего получается с клубничным. Хотя у каждого человека свой вкус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12117,'Достать корж, промазать слоем джема, свернуть его в трубочку, полученный рулет с джемом к чаю за 15 минут  присыпать сахарной пудрой с корицей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12118,'Вскипятить воду с солью, положить промытые небольшие соцветия цветной капусты, варить после повторного закипания еще около 6-7 минут. Сцедить отвар (пригодится для варки овощного супа), капусту выложить в дуршлаг, чтобы обсохла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12118,'Подготовить для запекания подходящую форму, переложить туда черешками вниз соцветия капусты. Измельчить сыр на терке (лучше мелкой), тщательно перемешать сметану и муку с солью, залить смесью форму, присыпать сырной стружкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12118,'Поставить цветную капусту в сметанном соусе под сыром запекаться на треть часа в прогретую до 180 градусов духовку. Можно есть, как самостоятельное горячее блюдо, а можно подать и как гарнир с мясными или рыбными блюдами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12128,'Для основы крема яйцо растереть  с мукой, ванилином и сахаром, залить эту сухую смесь молоком, смешать венчиком до однородности, поставить на плиту. Варить при слабом нагреве, постоянно помешивая пока состав не загустеет, снять с плиты, дать полностью остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12119,'Вымыть грибы, порезать, обжарить в масле, отварить и нарезать яйца, ветчину, порубить зелень молодой петрушки (у старой черешки лучше не использовать, а только листья). Все ссыпать в просторную миску и аккуратно перемешать, сдобрить майонезом, молотой паприкой, молотым черным перчиком и солью, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12119,'Весь кусок сыра поместить в достаточно горячую воду на треть часа, вынуть, раскатать в пласт не толще 5 мм. Сырную основу рулета промазать готовым фаршем, свернуть с усилием в рулон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12119,'Готовый рулет из сыра, шампиньонов и ветчины обернуть фольгой, на пару часов положить «отдохнуть» в холодильник.  Достать, порезать, подать как закуску, или приготовить замечательно вкусные и питательные бутерброды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12120,'Охладить сливки, протереть свежайший творог (лучше домашний) дважды сквозь сито, соединить со сливками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12120,'Перелить все в чашу блендера, взбить при низких оборотах до однородной массы с устойчивыми пиками. Домашний сливочный сыр маскарпоне готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12121,'Кабачки промыть, срезать хвостики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12121,'Кожуру можно снять, если плоды зрелые.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12121,'Мякоть натереть на крупной терке, добавить рубленый зеленый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12121,'Кефир перемешать с содой, подождать несколько минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12121,'Кефир соединить с кабачковой массой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12121,'Компоненты перемешать, всыпать муку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12121,'На сковороду с толстым дном влить растительное масло.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12121,'Тесто выкладывать столовой ложкой. Жарить до золотого цвета с двух сторон.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12122,'Очистить кабачок от кожуры, мякоть натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12122,'Чеснок пропустить через пресс, добавить молотый перец и соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12122,'Всыпать муку порциями, приготовить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12122,'Оладьи обжарить на масле, по три минуты с каждой стороны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12123,'Заранее подготовить почти целую скорлупу яиц: тщательно вымыть, слегка разбить с тупого конца и выпустить содержимое, обработать внутри, обсушить снаружи и внутри.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12123,'Залить желатин на 10 минут водой, поставить на плиту, прогреть до растворения, но не кипятить, перемешать с бульоном и процедить. Порезать перец и ветчину на кубики небольшого размера, отцедить из вскрытой банки кукурузу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12123,'Поместить ингредиенты слоями в скорлупу, влить бульон, поставить в холодильник. Застывшие заливные яйца с ветчиной, кукурузой и перцем освободить о скорлупы (почистить, как обычные яйца), разложить на широкое блюдо, оформить зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12124,'Репчатый лук и кабачок вымыть, очистить от кожуры, натереть на крупной терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12124,'Вбить сырое куриное яйцо, добавить куриный фарш.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12124,'Добавить соль и перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12124,'Всыпать муку, замесить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12124,'Прогреть сковороду, влить растительное масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12124,'Обжарить оладьи с двух сторон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12125,'Кабачки вымыть, натереть, посолить и поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12125,'Фарш отжать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12125,'Всыпать муку и приготовить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12125,'Обжарить оладьи на минимальном количестве растительного масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12126,'Подготовить яблоки: помыть, удалить кожуру и семечки, нарезать на кубики. Всыпать в яйца сахар, влить растительное масло и йогурт, хорошо перемешать, добавить смесь разрыхлителя и муки, размешать еще раз до однородной смеси.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12126,'Объединить полученное тесто с яблоками еще раз хорошо размешать. Вылить состав в круглую форму, отправить в прогретую духовку (оптимально до 180 градусов), выпекать яблочный пирог примерно час. Готовность проверять периодически с помощью зубочистки. Подать домашний яблочный пирог на натуральном йогурте к чаю.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12127,'Тушим сливы до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12127,'Мелко нарезаем зелень и чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12127,'Перетираем сливы через сито для однородности (Можно измельчить сливы блендером, но тогда в соусе будет присутствовать шкурка со слив)',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12127,'В протертую массу добавляем зелень, чеснок, соль, сахар, перец, хмели-сунели и мяту.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12127,'Отправляем соус на медленный огонь и после закипания провариваем 5-7 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12140,'Жарить оладьи на масле до получения корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12128,'К творогу добавить яйца, всыпать сахар, ванилин и соду, размешать, всыпать по частям муку, перемешать до получения пластичного, плотного теста. Разделить цельный кусок теста на 6-7 частей, раскатать тонкие коржи по диаметру сковороды, вилкой проколоть каждый в нескольких местах, иначе будут пузыри при выпекании.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12128,'Переложить корж на сухую сковороду, подрумянить с обеих сторон, вынуть готовый корж, подравнять края, испечь так все коржи, хорошо их все остудить. Положить мягкое масло в чашу миксера, добавить по частям остывшую основу крема, как следует взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12128,'Каждый корж промазать кремом, присыпать орехами, сложить в стопку. Верхушку творожного торта с орехами на сковороде оформить измельченным шоколадом и дать постоять в прохладе для пропитки не менее 6 часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12129,'Для начала приготовим соус.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12129,'Туда же добавляем майонез, сметану и кетчуп, соль перец по вкусу. все перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12129,'Как перемешали убираем соус в сторону, чтобы дать ему настояться!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12129,'Нарезаем куриное филе на небольшие кубики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12129,'И на разогретой сковороде обжариваем до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12129,'Слоеное тесто раскатываем немного, и нарезаем на равные чести.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12129,'На подготовленное слоеное тесто, выкладываем обжаренное мясо, и чуть чуть добавляем соус. заворачиваем и защиплем кроя,',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12129,'Взбитым куриным яйцом смазываем тесто, и отправляем слойки в разогретую духовку на 15 20 миннут, до тех пор пока слойки не подрумянится.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12130,'Измельчить все ингредиенты салата, далее необходимо переложить каждый послойно в глубокую салатницу. Порядок слоев должен быть таким: белки, желтки, апельсин, семга, укроп, сыр, белок, семга, картофель. Между каждым слоем поместить тоненький слой майонеза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12130,'Теперь основной этап в приготовлении. Накрыть салатницу подходящей по размеру плоской тарелкой и резко, но осторожно перевернуть. Оформить верх салата-перевертыша с семгой и апельсином зернами красной икры, убрать в прохладное место на несколько часов, пусть все слои хорошо пропитаются.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12131,'Айву нарезаем дольками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12131,'Перец разрезаем на 4 или 8 частей (зависит от перца).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12131,'В каждую банку (0,5 л) вливаем по столовой ложке уксуса, кладем гвоздичку, горошину перца и кусочек корицы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12131,'Заполняем банки айвой и перцем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12131,'Готовим сироп: 3 стакана воды  и 150 г сахара, доводим до кипения и заливаем им содержимое всех баночек.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12131,'Стерилизуем в течении 15 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12131,'Закатываем банки, переворачиваем горлышком вниз и укутываем до полного остывания.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12132,'Кабачок хорошо вымыть и натереть, лишнюю жидкость отжать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12132,'Вбить сырые куриные яйца, соль, сахарный песок с ванилином и гашеную соду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12132,'Всыпать муку и замесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12132,'Готовую кабачковую икру выложить на сковороду с маслом столовой ложкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12132,'Жарить до готовности на сильном огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12133,'Кабачки вымыть, снять кожуру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12133,'Мякоть натереть, отжать сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12133,'Влить кефир с содой, вбить сырые яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12133,'Массу хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12133,'Всыпать манную крупу, оставить на два часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12133,'Всыпать муку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12133,'Сковороду раскалить, жарить оладьи с двух сторон.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12134,'Кабачки очистить от кожицы и натереть на крупной терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12134,'Отжать лишний сок, добавить специи и соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12134,'Протереть творог через сито, натереть брынзу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12134,'Оба продукта добавить в овощи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12134,'Взбить яйца отдельно, добавить в основную массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12134,'Должно получиться тесто средней густоты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12134,'Раскалить масло, испечь оладьи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12141,'Картофель и кабачки натереть, отжать сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12141,'Всыпать в овощную смесь нарезанный зеленый лук, укроп, петрушку, чеснок, вбить яйцо и добавить специи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12141,'Всыпать муку порциями, приготовить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12135,'Достать заранее масло, включить для прогрева духовку. Смешать муку, имбирь, сахарную пудру, соль, мягкое масло и порошок какао в однородную массу. Посыпать стол мукой, выложить ком теста, накрыть пленкой, раскатать, переложить на подготовленный противень, отправить на треть часа  в прогретую духовку, достать, хорошо остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12135,'Холодный корж измельчить на куски, переложить в блендер или комбайн, засыпать миндаль, коричневый сахар, добавить сливочное масло, смолоть все в однородную массу. Переложить полученное тесто в форму, поставить в духовку примерно на 10 минут, достать, дать остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12135,'В миксер насыпать сахар, добавить сливочный сыр, яйцо, взбить около минуты. Далее добавить по одному остальные яйца, взбивать после каждого по минуте. Влить сметану, взбить, добавить сливки, лимонный сок, цедру лимона, имбирь, перемешать начинку до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12135,'Приготовить из шоколада и сливок ганаш. Влить в небольшую кастрюльку сливки (можно заменить сметаной), дать закипеть, снять с плиты, поломать шоколад, положить в сливки, минуты через 3 перемешать, слегка остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12135,'Перемешать ганаш с третью начинки, перелить в форму с основанием чизкейка. Оставшуюся часть ганаша переложить в кондитерский мешок, выдавить в виде шоколадной решетки на верх десерта. Зубочисткой провести диагонали у всех квадратиков.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12135,'Поставить шоколадные пирожные со сливочным сыром выпекаться на 25 минут в горячую духовку, вынуть, слегка остудить, убрать на холод, примерно на 4 часа. Вынуть из холодильника, поставить на пару секунд на плиту, чтобы легче достать из формы, порезать десерт на квадратные пирожные и подать к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12136,'В кастрюлю отправляем вымытую луковую шелуху, лавровый лист и душистый горошек, соль и заливаем водой.','https://vkuso.ru/data/cache/data/c6/06053463084b6c6_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12136,'Опускаем сало и отправляем на огонь, кипятим 10-15 минут.','https://vkuso.ru/data/cache/data/eb/3337d1b06a515eb_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12136,'Остуживаем сало и отправляем в холодильник на 12 часов.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12136,'Смешиваем паприку, черный перец и выдавленный через пресс чеснок.','https://vkuso.ru/data/cache/data/57/459b5a6b73bfc57_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12136,'Приготовленной смесью специй обмазываем сало со всех сторон.','https://vkuso.ru/data/cache/data/0d/c5e4ca71389040d_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12136,'Помещаем сало в пакет и отправляем в холодильник.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12137,'Сливочное масло натираем на крупной терке в муку',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12137,'Добавляем сахар и растираем смесь в жирную крошку',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12137,'Добавляем желток и уксус и постепенно вливаем воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12137,'Замешиваем тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12137,'Отправляем тесто в пакет и в холодильник на 30-40 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12137,'Раскатываем тесто и вырезаем печенье произвольной формы и размера',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12137,'Посыпаем печенье смесью корицы и сахара.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12137,'Отправляем в разогретую духовку на температуру 190 градусов примерно на 10-12 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12138,'Подготовить форму: смазать маслом, всыпать ложку манки, распределить равномерно по дну и стенкам. Смешать с любыми ягодами обезжиренный творог, пару ложек манки, яйцо, добавить соду, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12138,'Заполнить смесью форму, присыпать манкой, поставить в духовой шкаф примерно на полчаса. Творожная запеканка с ягодами в духовке готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12139,'Порезать картофель крупными кусками, сварить в воде с солью, сцедить воду, обсушить картофель, чуть обжарить, дать остыть, взбить вместе с маслом в пышное по консистенции пюре без кусочков. Влить в пюре сливки, всыпать стружку пармезана, добавить желтки, сдобрить солью, мускатным орехом, перцем, хорошо взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12139,'Прогреть духовку (достаточной температурой будет 200 градусов). Выстелить на противень пекарскую бумагу, смазать маслом, заполнить шприц картофельным пюре, высадить розочками на противень, задвинуть его в духовку. Выпекать картофельный гарнир по-герцогски минут 20, розочки должны слегка «загореть».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12140,'Натереть кабачок, сок – отжать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12140,'Добавить соль по вкусу, специи, яйцо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12140,'Массу перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12142,'Выставить время – полчаса. Через пятнадцать минут оладьи перевернуть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12142,'Излишки масла после обжарки можно удалить с помощью бумажных салфеток.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12143,'Кабачки цуккини натереть, перемешать с тертым сыром и взбитым яйцом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12143,'Всыпать муку, соль и молотый перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12143,'Жарить до корочки на растительном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12144,'Из всех ингредиентов замесить тесто (соду погасить уксусом), которое не будет липнуть к рукам, раскатать, но не слишком тонко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12144,'Вырезать формочкой сердечки, присыпать их сахарным песком, переложить на противень, задвинуть его в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12144,'Выпекать сметанные коржики «Сердечные» до слабого подрумянивания при температуре не выше 180 градусов, иначе можно пересушить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12145,'На терке со средней решеткой натереть кабачки цуккини.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12145,'Перемешать с рубленой зеленью и яйцом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12145,'Молотый перец и соль добавить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12145,'Всыпать муку и орегано.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12145,'Разогреть растительное масло на сковороде, жарить оладьи на среднем огне, время – по три или четыре минуты с каждой стороны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12146,'Кабачки цуккини натереть, посолить, вбить сырое яйцо, всыпать муку, сахар, пищевую соду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12146,'Прогреть масло на сковороде, сформовать оладьи, жарить с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12147,'Сыр и кабачки цуккини натереть, нарубить зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12147,'Всыпать соль, перец, вбить сырые яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12147,'Очистить томаты от кожицы, нарезать кружками, смешать с творогом и давленым чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12147,'Сковороду разогреть, смазать маслом, выложить тесто в виде оладий, сверху – помидорная начинка, второй слой теста.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12147,'Жарить до золотой корочки с двух сторон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12148,'Укроп мелко мелко нарезаем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12148,'Сыр натираем на мелкой терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12148,'В миску для замеса теста, добавляем воду 200 мл, щепотку соли, и 1 кур. яйцо. Все взбиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12148,'После этого туда же добавляем 2 щепотки разхрытеля и постепенно кукурузную муку. Замащиваем тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12148,'Как только немного замещали тесто, добавляем подготовленный укроп и сыр, все еще раз замещать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12148,'И далее из полученной массы делаем шарики, после перекладываем на притвинь. И отправляем в духовку при 180С на 35 мин.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12149,'Натереть кабачки на крупной терке, жидкость отжать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12149,'Перемешать с яйцом, содой, кефиром, соль – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12149,'Добавить муку до нужной консистенции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12149,'Жарить оладьи по две минуты с каждой стороны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12150,'Кабачки цуккини натереть, через несколько минут отжать сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12150,'Добавить муку, черный перец, соль, специи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12150,'Сформовать котлеты, жарить с обеих сторон на масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12151,'Кабачки цуккини очистить, мякоть мелко натереть, добавить соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12151,'Через десять минут слить выделившуюся жидкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12151,'Кабачковую массу перемешать с измельченной зеленью, мясом, яйцами и давленым чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12151,'Всыпать соль, муку, специи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12151,'Жарить оладьи по четыре минуты с каждой стороны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12152,'Кабачки очистить, удалить семена, мякоть натереть, слить сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12152,'Перемешать с тертым картофелем, рубленой зеленью, давленым чесноком и репчатым луком, нарезанным небольшими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12152,'Всыпать соль, перец, муку, вбить сырое яйцо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12152,'Жарить оладьи с двух сторон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12153,'Порубить шпинат и куриное филе в блендере, добавить яйцо, мелко порезанный чеснок, перемешать, сдобрить солью, черным перцем, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12153,'Отварить морковь и картофель, морковь мелко потереть, картофель растолочь в пюре, перемешать, вбить яйцо, еще раз перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12153,'Прямоугольную форму смазать сливочным маслом, заполнить половиной картофельно-морковного пюре, на него выложить шпинат и оставшееся пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12153,'Положить на поверхность запеканки небольшие кусочки масла, при желании присыпать стружкой сыра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12284,'Продолжать взбивать блендером или миксером.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12153,'Поставить форму с картофельной запеканкой с куриным филе и шпинатом в прогретую чуть ниже 200 градусов духовку минут на 40.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12154,'Овощи очистить от кожуры и натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12154,'Перемешать с разрыхлителем, яйцом и мукой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12154,'Массу посолить и поперчить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12154,'Смазать сковороду маслом, выложить оладьи, жарить с двух сторон до корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12154,'Готовые изделия выложить на бумажное полотенце.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12155,'Натереть репчатый лук и кабачки, отжать лишний сок, мякоть перемешать с мукой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12155,'Влить молоко, вмешать взбитый белок, соль и перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12155,'Оладьи выложить на противень столовой ложкой, время выпекания – 15 минут, температура – 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12155,'Изделия перевернуть, готовить еще несколько минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12156,'Кабачки с кожурой и репчатый лук натереть на мелкой терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12156,'Добавить кефир, яйца, измельченную зелень и специи, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12156,'Постепенно добавить муку. Можно взять овсяную муку или манку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12156,'Соль – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12156,'Прогреть духовку до 180 или 190 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12156,'Застелить противень пергаментом, смазать бумагу растительным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12156,'Тесто выложить ложкой, время выпекания – от 18 до 25 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12156,'Оладьи во время приготовления перевернуть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12157,'Свежие шампиньоны перебрать, промыть, измельчить в фарш.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12157,'Очистить кабачки, удалить семена.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12157,'Натереть вместе с морковью и репчатым луком, чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12157,'Продукты соединить, добавить соль и перец, всыпать муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12157,'Массу перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12157,'Застелить противень пергаментом, выложить тесто в виде оладий, печь при температуре 25 минут. Температура нагрева – средняя.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12158,'Подогреть сливки и молоко в небольшой кастрюльке, убрать с плиты. Соединить со смесью для приготовления горячего шоколада и кофе, тщательно перемешать, разлить по высоким кружкам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12158,'Каждую оформить сверху маршмеллоу и шоколадным сиропом, украсить горячий ароматный  кокачино взбитыми сливками, присыпать порошком какао',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12159,'Перетереть творог с солью и яйцом, влить кефир.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12159,'Нарезать кубиками мякоть кабачков, натереть морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12159,'Продукты соединить с мукой и рубленой зеленью. Массу перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12159,'Духовку прогреть, застелить противень пергаментом, выложить оладьи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12159,'Время приготовления – от 20 до 23 минут, температура – от 190 до 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12160,'Репчатый лук очистить и нарезать, добавить в мясной фарш вместе с зеленью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12160,'Натереть кабачки, морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12160,'Всыпать манную крупу, дать массе постоять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12160,'Тесто должно получиться достаточно густым.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12160,'Застелить противень фольгой, смазать маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12160,'Выложить оладьи, запечь в духовке, температура приготовления – 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12160,'Чтобы блюдо не получилось слишком сухим, оладьи можно накрыть сверху пергаментом или еще одним слоем фольги.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12161,'Опустить проростки в кипящую воду на 1-2 минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12161,'Затем промыть в холодной воде и просушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12161,'Нарубить мелко чеснок, лук, добавить к сое.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12161,'Добавить рыбный соус, масло, соль, кунжут, хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12162,'Вымыть свинину, обсушить полотенцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12162,'Пропустить через мясорубку вместе с луком, другой вариант – использовать блендер.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12162,'Кабачки вымыть, удалить семена и кожуру, мякоть натереть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12162,'Обе массы соединить, вбить сырое яйцо, всыпать муку, еще раз хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12162,'Разогреть масло на сковороде, выпечь небольшие оладьи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12163,'Кабачки измельчить на терке, посолить, оставить на десять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12163,'Отжать сок, в основную массу ввести мясной фарш.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12163,'Перетереть брынзу или сыр, добавить к кабачкам вместе чесноком и яйцом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12163,'Всыпать муку, соль и перец',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12163,'Массу перемешать еще раз.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12163,'Чашу мультиварки смазать маслом, выставить режим «Выпечка» или «Жарка».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12163,'Обжарить оладьи при открытой крышке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12164,'Репчатый лук и кабачки натереть на терке, пропустить через пресс чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12164,'Продукты соединить со специями и мясом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12164,'Всыпать муку, масса должна напоминать густую сметану.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12164,'Жарить оладьи на раскаленной сковороде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12165,'Смазать одну сторону ломтей хлеба сливочным маслом. Нагреть большую сковороду (лучше всего подойдет с антипригарным покрытием), положить ломтик батона, а на него половину ломтей бри, присыпать щедро шоколадом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12165,'Положить на него половину нарезанных клубничных  ягод, прикрыть вторым кусочком хлеба (слой масла должен остаться вверху). Уложить «собранный» таким образом бутерброд на прогретую сковороду,  аналогично сделать второй бутерброд.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12165,'Сковороду закрыть крышкой минуты на 3 до плавления шоколада и сыра, перевернуть сэндвичи с сыром бри, клубникой и шоколадом и поджарить под крышкой с другой стороны. Подать десерт горячим.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12166,'Пропустить через мясорубку классический набор продуктов: помидоры, чеснок, хрен.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12166,'Перемешать и добавить толченый аспирин из расчета 1 таблетка на 1 л хреновины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12166,'Массу перемешать, разлить в банки, закатать металлическими крышками или закрыть полиэтиленовыми.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12167,'Спелые, сочные плоды лимона, апельсина, лайма вымыть и разрезать пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12167,'Сок отжать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12167,'Филе лосося нарезать кубиками, посолить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12167,'Рыбу залить соком цитрусовых, поставить в холод на 45 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12167,'Нарезать тонкими ломтиками авокадо, добавить рубленый шнитт-лук или лук-резанец.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12167,'Слить жидкость с рыбного филе.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12167,'В маринад добавить майонез, красный молотый перец, мед.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12167,'Смесь взбить в пену вилкой или венчиком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12167,'Рыбу соединить с авокадо и луком, заправить майонезным соусом и сразу подать к столу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12168,'Для блюда использовать свежую семгу. Рыбу нарезать тонкими ломтиками, соль – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12168,'Вымыть лайм, сок отжать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12168,'Очистить от семян перец чили, нарезать вместе с луком-шалотом, зеленью петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12168,'Добавить оливковое масло и цитрусовый сок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12168,'Рыбную нарезку перемешать с маринадом, убрать в холодильник на десять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12168,'Помидоры нарезать дольками, сладкий красный болгарский перец – полосками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12168,'Ржаной хлеб подсушить на сковороде с антипригарным покрытием.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12168,'Рыбу выложить на овощи, полить маринадом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12168,'Подать с поджаренным хлебом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12169,'Репчатый лук замариновать в воде с уксусом и сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12169,'Нарезанный овощ заправить лимонным соком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12169,'Всыпать сахар, оставить на полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12169,'Очистить тигровые креветки, панцири не снимать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12169,'Переложить в кипящую воду, еще раз дать закипеть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12169,'Изменившие цвет морепродукты снять с плиты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12169,'Воду перелить в отдельную емкость.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12169,'Креветки откинуть на дуршлаг, облить холодной водой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12169,'Удалить панцири, залить их водой, оставшейся от креветок, время кипения – пять минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12169,'Жидкость отцедить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12169,'Добавить в нее апельсиновый и лаймовый сок, растительное масло, «Кетчуп», соль, перец.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12169,'Готовые креветки смешать с соусом, луком, рубленой зеленью кинзы.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12169,'Закуску поставить в холод на ночь. Подать к столу вместе с заправкой.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12170,'Кофе заливаем горячей кипяченой водой. Размешиваем до полного его растворения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12170,'Готовим тесто: в чашу миксера помещаем размягченное сливочное масло, сахар и взбиваем, добавляем яйца и продолжаем взбивать. В хорошо взбитую массу добавляем муку и разрыхлитель, всыпаем орехи, вливаем кофе и замешиваем тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12170,'В смазанную маслом форму помещаем тесто и выпекаем в разогретой духовке на температуре 180 градусов 25-30 минут. Выпекаем 2 коржа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12170,'Каждый корж разрезаем пополам. В итоге у нас 4 коржа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12170,'Готовим крем, для чего размягченное сливочное масло взбиваем миксером с вареным сгущенным молоком и вливаем кофе, продолжая взбивать. Кофе готовим, как для теста.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12170,'Готовый крем необходимо минут 20 охладить в холодильнике.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12170,'Собираем торт: на блюдо или форму для торта выкладываем один корж, смазываем его кремом. Сверху помещаем следующий корж, пропитываем его сиропом и выкладываем на него крем. Так поступаем со всеми коржами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12170,'Бока торта обсыпаем дроблеными орехами.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12170,'Отправляем торт в холодильник на несколько часов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12170,'Украшаем грибочками (печенье)',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12171,'Сварить в большом количестве соленой воды гнезда (не переваривать). Разделать рыбу. порезать кусочками, сдобрить солью, черным перцем, поджарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12171,'В сотейнике нагреть сливочное масло до полного расплавления, всыпать кубики репчатого лука и муку, постепенно помешивая влить сливки, положить рыбу, протушить минут 6-7.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12171,'Если подливка будет чрезмерно густой, то подлить немного сливок. Порубить мелко укроп и чеснок, всыпать к рыбе, прогреть пару минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12171,'Очень аккуратно переложить гнезда на широкое блюдо, положить в них рыбную начинку, полить соусом от тушения. Форель  в сливочном соусе в гнездах из макарон готова.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12172,'Филе дорадо очистить, удалить внутренности, чешую.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12172,'Первый надрез сделать с верхней стороны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12172,'Филе нарезать кусочками небольшого размера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12172,'Очистить и натереть имбирь, порубить кинзу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12172,'Смешать сок грейпфрута и апельсина, добавить оливковое масло, соль, имбирь, перец чили.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12172,'Рыбу заправить готовым маринадом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12172,'Поставить в холод на десять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12172,'Отделить белки от желтков.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12172,'Желтки охладить и соединить при помощи погружного блендера с укропом и растительным маслом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12172,'Нарезать кусочками авокадо, помидоры черри, свежий огурец без кожуры.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12172,'Влить лимонный сок.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12172,'Выложить на блюдо рыбу, зелень и овощи.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12172,'Заправить яичным соусом.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12173,'Ягоды перебрать, плодоножки удалить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12173,'Смородину вымыть, обсушить, пропустить через мясорубку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12173,'Варить в эмалированной кастрюле с сахаром, огонь – средний.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12173,'Варенье помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12173,'Довести до кипения, огонь уменьшить, варить еще пять или семь минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12173,'Остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12173,'Снова поставить на плиту, довести до кипения, варить несколько минут, остудить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12173,'Весь процесс повторить еще раз.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12173,'Готовый продукт разложить в чистые и сухие банки, закрыть крышками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12174,'Ягоды подготовить: перебрать, промыть, воду слить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12174,'Пропустить через мясорубку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12174,'В массу добавить сахар, размешать и поставить на средний огонь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12174,'Довести варенье до кипения, пенку снять, помешивать, варить пять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12174,'Стерилизовать банки в микроволновой печи или над паром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12174,'Отдельно прокипятить крышки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12174,'Горячее варенье разлить в тару, закатать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12174,'Укутать тканью, оставить до остывания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12174,'Хранить в темном месте.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12175,'Нужно мелко порешать петрушку и пересыпать в тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12175,'Раздавить чеснок и добавить масло, сыр. Все перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12175,'Сделаем надрезы на хлебе и наполним их смесью. Поставим уже разогретую духовку до 200 градусов на 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12176,'Разрезать пополам стручок ванили, положить в кастрюлю, залить молоком, нагреть практически до кипения, дать остыть под крышкой минут 20, чтобы молоко стало ароматным (не забудьте вынуть кусочки стручка ванили).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12176,'Взбить сахарную пудру с желтками, залить молоком, поставить на огонь, добавить кубики  масла. Варить, помешивая (кипеть не давать!) при среднем нагреве четверть часа. Крем должен загустеть, процедить его, дать постоять и остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12176,'После приобретения комнатной температуры универсальный заварной крем с ванилью убрать в холодильник, хранить не более 2 дней.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12177,'Тщательно разделить белки и желтки, добавить в белки чуть соли, взбить до устойчивых пиков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12177,'Выстлать противень пергаментом или фольгой, чуть сбрызнуть маслом, выложить белки в виде небольших гнездышек, присыпать сырной стружкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12177,'Аккуратно в центр каждого поместить по желтку. Задвинуть противень с яичными гнездышками с сыром минут на 6 в прогретую примерно до 220 градусов духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12178,'Нарезать пару охлажденных плавленых сырков на тонкие полоски, взбить яйца, порубить укроп, чеснок раздавить прессом, порезать лаваш на 8-10 сантиметровые полосы шириной примерно по 12 сантиметров.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12178,'Уложить на каждую полоску по паре полосок сыра по всей длине, присыпать чесночком и укропом, свернуть в трубочку. Разогреть сливочное масло, обмакнуть палочку в яйцо, обжарить сырные палочки из лаваша с чесноком до золотистости, подать горячими с кетчупом или сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12179,'Смородину перебрать, промыть, откинуть на сито.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12179,'Подготовленный продукт пропустить через мясорубку, всыпать сахар, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12179,'Подержать при комнатной температуре до растворения сахара.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12179,'Помешивать массу деревянной ложкой движениями снизу вверх.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12179,'Джем разложить в небольшие сухие чистые банки, укупорить полиэтиленовыми крышками, поставить в холод.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12180,'Ягоды перебрать от мусора, промыть, переложить на кухонное полотенце.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12180,'Пропустить продукт через мясорубку, дополнительно протереть через сито.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12180,'Массу перелить в кастрюлю, готовить на тихом огне, добавлять сахар порциями через каждые три минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12180,'Банки стерилизовать, разложить желе, укупорить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12181,'Всыпать в эмалированную посуду сахарный песок, влить воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12181,'Прогреть на тихом огне до растворения, довести до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12181,'Опустить чистые ягоды на пять секунд в горячую воду, а затем – в сироп.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12181,'Такой прием поможет сохранить продукт в целости, кожица не полопается.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12181,'Довести до кипения, подержать ровно пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12181,'Варенье остудить, разлить в чистые, стерилизованные банки. Закрыть плотными крышками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12182,'Замесить из всех ингредиентов тесто, дать «отдохнуть» полчаса в холодильнике. Порезать луковицу на кубики и обжарить, раздавить чеснок, переложить все в фарш, перемешать, добавить томат, сдобрить специями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12182,'Пласт теста уложить в форму, закрыть не только дно, но и бока, отправить в духовку минут на 10. Порезать помидоры на 2 равные части, обжарить кусочки грибов, приготовить заливку из сыра, яиц сливок либо сметаны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12182,'Достать готовую основу пирога, выложить на нее начинку в следующем порядке: фарш, шампиньоны, брокколи или оливки, завершить слои половинками помидоров. Равномерно залить все яичной смесью, присыпать сырной стружкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12182,'Отправить пирог с мясным фаршем по-гречески на треть часа в прогретую до 200 градусов духовку до образования корочки золотисто-соломенного цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12183,'Всыпать чистые ягоды в воду, прогреть до закипания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12183,'Кипятить две или три минуты, огонь убавить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12183,'Всыпать сахар, помешивать до полного растворения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12183,'Все вместе кипятить десять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12183,'Разложить в чистые банки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12183,'Укутать в плед до остывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12183,'Другой вариант: прогретые с водой ягоды протереть через сито.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12183,'Всыпать сахарный песок, долить немного воды.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12183,'Варить желе до тех пор, пока масса не уварится на треть от первоначального объема.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12183,'Готовый продукт разлить в банки, закрыть чистыми крышками.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12183,'Тару перевернуть на полчаса.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12184,'Ягоду пропустить через мясорубку или измельчить в блендере.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12184,'Всыпать сахар, пропустить массу через мясорубку еще раз.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12184,'Оставить на сутки под полотенцем при комнатной температуре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12184,'Варенье периодически помешивать, готовый продукт разлить в банки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12185,'Ягоды обработать, промыть, обсушить и засыпать сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12185,'Дать постоять семь или восемь часов до появления сока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12185,'Пропустить через мясорубку или использовать блендер.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12185,'Апельсин вымыть, измельчить вместе с цедрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12185,'Добавить массу в ягоды, перемешать, дать постоять полтора часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12185,'В чистые банки влить по несколько капель лимона, затем – варенье.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12185,'Сверху также влить немного лимонного сока, всыпать дополнительную порцию сахара толщиной в один сантиметр.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12185,'Закрыть варенье крышками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12186,'Влить в кастрюлю воду, всыпать сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12186,'Прогреть, добавить в сироп часть ягод.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12186,'Смородину и сахар добавлять частями через каждые пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12186,'Огонь – тихий, массу постоянно помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12186,'Готовое варенье немного остудить, разлить в банки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12187,'Перебрать и промыть шпинат, обсушить, бланшировать около минуты в кипятке, переложить в дуршлаг, дать хорошо стечь, остудить, перемолоть в блендере до состояния пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12187,'Смешать блендером сметану, шпинатное пюре, яйца, масло, соль, добавить соду с мукой, перемешать до однородного состояния. Противень застелить бумагой для выпечки, вылить на него смесь (толщиной около 5 мм), поместить в прогретую чуть ниже 200 градусов духовку минут на 10.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12187,'Замочить  в сливках желатин для приготовления начинки. Растереть со сливками фету, творог в однородную массу. Все продукты брать комнатной температуры. Перемешать полученную смесь с прогретым до растворения желатином, всыпать крошку укропа, добавить кусочки семги.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12187,'Разрезать уже холодный корж на 2 части, одну промазать сантиметровым слоем начинки, прикрыть второй половинкой, чуть-чуть сдавить, отправить закуску с соленой семгой   и творожным муссом в холодильник. Достать, порезать небольшими кусочками прямоугольной формы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12188,'Малину перебрать, засыпать сахарным песком на восемь часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12188,'Промыть черную смородину.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12188,'Малину, давшую сок, нагреть до кипения, варить пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12188,'Продукт немного остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12188,'Еще раз нагреть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12188,'После третьего кипячения оба продукта соединить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12188,'Кипятить вместе десять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12188,'Разлить в банки, закатать крышками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12189,'Всыпать в чашу мультиварки ягоды, сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12189,'Выставить режим «Тушение».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12189,'Готовый продукт разлить в банки, закатать или закрыть полиэтиленовыми крышками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12190,'Черную смородину перебрать, промыть, откинуть на дуршлаг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12190,'В кастрюле перемешать воду с сахарным песком, поставить на плиту, довести до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12190,'Ягоды всыпать в сироп порциями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12190,'Варить все вместе пять минут, если появится пенка – ее лучше снять.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12190,'Готовое варенье закатать в стерильные банки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12191,'Плоды вымыть, выложить в емкость, всыпать сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12191,'Оставить массу на двенадцать или четырнадцать часов, должен появиться сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12191,'Поставить кастрюлю на огонь, довести до кипения и снять пену.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12191,'Время варки продукта – от пяти до десяти минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12191,'Подготовить банки, разлить варенье, продукт закатать, закрыть одеялом или пледом на два дня.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12192,'Ягоды отсортировать, промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12192,'Сложить в емкость, влить воду, поставить на тихий огонь, варить до мягкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12192,'Отжать выделившийся сок, уварить на половину объема, пенку снимать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12192,'Всыпать сахар, варить до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12192,'Варенье разлить в сухие стерилизованные банки, укупорить металлическими крышками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12193,'Измельчить на мясорубке филе рыбы вместе с луком  и картофелем. Добавить к фаршу яйцо, много рубленой зелени, перемешать, подсолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12193,'Сформовать небольшие котлетки, готовить рыбные котлеты с картофелем на пару минут 20.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12194,'Смородину высушить, цитрусовые с кожурой нарезать дольками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12194,'Ингредиенты перемолоть при помощи кухонного комбайна или пропустить через мясорубку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12194,'По желанию можно добавить сладкое яблоко.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12194,'Массу перемешать, выложить в банки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12194,'Закрыть полиэтиленовыми крышками, хранить в холоде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12195,'Ягоды промыть и засыпать сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12195,'Оставить на шесть часов при комнатной температуре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12195,'Переложить в мультиварку, выставить режим «Мультиповар», температура – 120 градусов, время – 10 минут. Варить без крышки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12195,'Готовый продукт разлить в банки, закатать, перевернуть до остывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12196,'Ягоды промыть, убрать мусор.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12196,'Выложить в емкость, пересыпать сахаром, оставить на четыре часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12196,'Массу довести до кипения, варить в течение пяти минут, пену снимать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12196,'Огонь выключить, оставить на ночь под крышкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12196,'Утром довести до кипения еще раз, варить еще пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12196,'Горячий продукт разлить в стерильные банки, закатать металлическими крышками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12197,'Тыкву очистить, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12197,'Добавить сахар, сливочное масло, ягоды красной смородины, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12197,'Варить 20 минут на среднем огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12197,'После закипания варенья плиту выключить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12197,'Охладить и подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12198,'Сварить сладкий сироп из сахарного песка и воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12198,'В кипящую жидкость добавить тертый корень имбиря, ягоды красной смородины, щепотку корицы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12198,'Варить на тихом огне пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12198,'Ягоды не должны развалиться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12198,'Разложить варенье в стерильные банки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12199,'Как следует смешать все ингредиенты для приготовления пышек, дать выстояться в теплом месте не менее трех часов. Раскатать из хорошо подошедшего теста сантиметровой толщины пласт. Подобрать соответствующую по диаметру высечку, например банку или кружку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12199,'Вырезать кругляшки, надрезать края, чтобы получился цветочек, центр рассечь двумя надрезами. Обжарить пышки на кефире без дрожжей  в сильно разогретом масле. На масло не скупитесь, и через короткое время стол украсит тарелка с горкой аппетитных булочек!',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12200,'Очищенную воду довести до кипения, всыпать сахарный песок, поварить до растворения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12200,'Добавить ягоды, варить пять минут, помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12200,'Разлить продукт в стерильные банки и плотно закрыть крышками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12201,'Ягоды красной смородины перебрать, обсушить, измельчить при помощи блендера или мясорубки, сита.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12201,'Отжать жмых.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12201,'В сок всыпать сахар, перемешивать деревянной ложкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12201,'Пюре из ягод разложить в банки, закатать чистыми крышками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12202,'Ягоды перебрать, промыть, выложить в эмалированную кастрюлю, подлить воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12202,'Массу довести до кипения, варить две минуты, протереть через сито.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12202,'Всыпать сахарный песок, варить полчаса на тихом огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12202,'Банки стерилизовать, разлить варенье, закатать. Хранить в прохладе.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12203,'Ягоды промыть, очистить от плодоножек, пересыпать в эмалированную емкость, влить воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12203,'Варить полчаса, при этом разминать ягоды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12203,'Довести до кипения, огонь уменьшить, всыпать сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12203,'Варить, помешивая, до полного растворения сахара.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12203,'Продукт разлить в банки, закатать, хранить в прохладном месте.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12204,'Плоды промыть, перебрать, выложить на полотенце для сушки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12204,'Банки промыть с содой, затем подержать над паром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12204,'Ягоды пересыпать в горячую тару на треть объема.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12204,'В кастрюлю влить воду, всыпать сахар, поварить, пенку снимать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12204,'Сироп влить в банки небольшими порциями, чтобы не лопнуло стекло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12204,'Накрыть горячими стерильными крышками, укупорить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12204,'Перевернуть, подержать банки под пледом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12205,'Включить для прогрева духовку до температуры чуть выше 170 градусов, противень установить в середину духового шкафа. Все составляющие части для основания пирога перемешать, переложить в форму, слегка прижать к дну и стенкам, выпекать четверть часа до появления корочки темно соломенного цвета. Корж хорошо охладить, приготовить за это время шоколадный крем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12205,'Подсушить и слегка поджарить миндальные орехи (хватит 5 минут, температуру надо выдерживать не выше 170-165 градусов), должен появиться характерный аромат жареного ореха, дать остыть, порубить, но сильно не мельчить. Поломать шоколад на маленькие кусочки, ссыпать в объемную миску. Подогреть почти до кипения сливки, залить шоколад, дать постоять пару минут, аккуратно взбить до полного расплавления шоколада и однородности смеси.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12205,'Подсолить и взбить яйцо, объединить со сливочно-шоколадной массой, добавить орехи и шоколадные чипсы, крем перемешать. Залить охлажденный корж кремом, прикрыть края формы фольгой, выпекать примерно 25 минут, остудить до затвердения начинки (примерно час), приготовить за это время зефирную начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12205,'Высыпать желатин в глубокую миску, залить четвертью стакана холодной воды, дать чуть постоять. Смешать сахар, чуть соли, кукурузный сироп и четверть стакана воды в сотейнике с толстым дном, нагреть до растворения сахара (не забывайте помешивать), проварить после этого еще 5-6 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12205,'Миксером (на средней скорости) взбить смесь желатина, перелить очень аккуратно к горячему сиропу, размешать. Выставить на миксере максимальную скорость, продолжить взбивать до увеличения объема и сгущения зефирного наполнителя, всыпать ванилин и еще раз взбить. Распределить полученный «зефир» по поверхности шоколадного покрытия коржа равномерным слоем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12205,'Убрать в холодильник примерно на час. После этого обернуть форму промасленной пленкой (маслом внутрь) и оставить еще на 3 часа в холодильнике. Переложить сладкий пирог с шоколадно-зефирной начинкой на противень, прикрыть края фольгой, выпекать около 4 минут до смены цвета зефирного слоя на золотистый. Дать пирогу остыть, порезать на сегменты очень острым ножом, смоченным в кипятке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12206,'Фрукты и ягоды промыть, обсушить на полотенце.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12206,'Яблоки очистить от плодоножки, семечек, кожуры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12206,'Мякоть нарезать кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12206,'Банки стерилизовать, уложить ягоды и яблоки слоями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12206,'В кастрюлю всыпать сахар, влить воду, довести до кипения, сироп помешивать, пенку снимать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12206,'Влить жидкость в банки, делать это осторожно, чтобы не треснуло стекло.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12206,'В кастрюлю влить воду на дно, поместить банки, подержать под крышками полчаса, укупорить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12206,'Банки перевернуть, подержать под одеялом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12207,'Ягоды перебрать, промыть, откинуть на дуршлаг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12207,'Воду довести до кипения, всыпать сахар, варить пять минут, помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12207,'Ягоды разложить в чистые, стерильные банки на треть объема.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12207,'Положить по две или три дольки апельсина.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12207,'Влить горячий сироп.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12207,'Накрыть заготовки крышками, стерилизовать в кипящей воде пятнадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12207,'Напиток закатать стерильными крышками, перевернуть и укутать теплой тканью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12208,'Урожай перебрать, часть ягод можно оставить на веточках.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12208,'Промыть холодной водой, откинуть на сито.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12208,'Банки промыть с содой, ополоснуть горячей водой, стерилизовать в духовке или над паром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12208,'Всыпать ягоды на треть объема, влить кипяток, через полчаса слить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12208,'В слитую воду всыпать сахар, довести сироп до кипения, помешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12208,'Перелить жидкость обратно в банки, закатать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12208,'Банки перевернуть, накрыть пледом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12209,'Промыть ягоды, удалить мусор.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12209,'Продукт обсушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12209,'Ягоды засыпать сахарным песком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12209,'Перемолоть массу при помощи мясорубки или блендера, можно использовать толкушку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12209,'Оставить ягоды на два дня для растворения сахара, массу перемешивать',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12209,'Разлить в чистые банки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12209,'Закрыть прокипяченными полиэтиленовыми крышками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12210,'Ягоды хорошо промыть, обсушить, убрать веточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12210,'Опустить в кипяток на две минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12210,'Ягоды растереть в пюре при помощи ступки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12210,'Выложить в кастрюлю, варить на тихом огне, воду подливать порциями, подсыпать сахарный песок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12210,'Выпарить до половины объема, снять с плиты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12210,'Разлить джем в небольшие банки, накрыть чистыми крышками. Время стерилизации – десять минут, закатать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12211,'Пропустить картофель сквозь крупную терку, отжать, дать хорошо стечь соку, подсолить, вбить яйца, всыпать муку, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12211,'Из картофельного «теста» приготовить клецки, расплющить каждую и положить на середину небольшое количество фарша (говяжий фарш смешать с луком, сдобрить перцем и солью), скатать, сварить в подсоленной кипящей воде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12211,'Как только картофельные клецки с фаршем из говядины всплывут еще немного проварить, выловить небольшим ситечком, подать к столу горячими вместе со сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12212,'Ягоды перебрать, промыть, выложить в чашу мультиварки, влить воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12212,'Выставить режим «Тушение» до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12212,'Массу протереть через сито.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12212,'Сок еще раз влить в мультиварку, добавить сахар, выставить тот же режим на полчаса, крышку не закрывать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12212,'Джем помешивать, пенку снять.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12212,'Разлить продукт в стерильные банки, закатать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12213,'Красную смородину перебрать, промыть, обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12213,'Превратить в пюре при помощи мелкого сита, блендера, мясорубки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12213,'Добавить сахарный песок, перемешивать до растворения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12213,'Банки стерилизовать, разложить джем, накрыть крышками. Хранить в холоде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12214,'Желатин растворить в небольшом количестве подогретой воды, так, как написано на упаковке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12214,'Оставить для набухания на 20 или 25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12214,'Ягоды перебрать, обсушить, протереть через сито. Залить водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12214,'Довести до кипения, использовать эмалированную кастрюлю.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12214,'Огонь убавить, варить сок 10 минут, помешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12214,'Массу процедить через несколько слоев марли.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12214,'Влить лимонный сок, всыпать сахар.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12214,'Довести до кипения еще раз, снять пену, влить желатиновую массу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12214,'Варить до полного растворения.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12214,'Сироп разлить в банки, закатать крышками.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12214,'Остудить, поставить в холодильник.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12215,'Порезать хлеб, порубить укроп, смешать молоко и яйцо, подсолить, всыпать зелень, поперчить, хорошо перемешать вилкой, но лучше венчиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12215,'Положить хлеб во взбитую смесь, дать немного полежать для пропитки, разогреть сковороду с маслом, обжарить гренки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12215,'Снять гренки со сковороды, положить на каждый кусочек по колечку мясистого помидора и присыпать перчиком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12215,'Посыпать сырной стружкой, поставить аппетитные гренки с помидором и сыром под гриль, подождать до расплавления сыра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12216,'Смородину перебрать и вымыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12216,'Апельсины очистить, удалить перепонки, мякоть измельчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12216,'Переложить ягоды в кастрюлю, добавить сахар, желатин, лимонную кислоту.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12216,'Массу довести до кипения, протереть через сито.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12216,'Джем перелить в кастрюлю, добавить сахарный песок, время кипения – три минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12216,'Добавить апельсины, перемешать, убрать варенье с плиты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12216,'Разлить в банки, закатать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12217,'Спелые ягоды красной смородины промыть и перетереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12217,'Отжать сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12217,'Вылить в кастрюлю, всыпать сахар, прогреть на плите.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12217,'Арбуз очистить от семян и кожуры, измельчить блендером.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12217,'Влить в смородиновую массу, варить пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12217,'Растворить в холодной воде крахмал, ввести в кипящий джем тонкой струйкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12217,'Стерилизовать небольшие банки, разлить варенье, закрыть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12217,'Остудить и убрать в холод.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12218,'Ягоды двух сортов промыть, из вишни удалить косточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12218,'Превратить в пюре при помощи блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12218,'Всыпать сахар, хорошо размешать и поставить на плиту.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12218,'Довести до кипения, варить на среднем огне полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12218,'Разлить продукт в стерильные банки, закатать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12219,'Подготовить ягоды, перетереть через сито.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12219,'Перелить пюре в кастрюлю, всыпать сахар, прогревать до кипения на тихом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12219,'Варить десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12219,'Натереть имбирь, добавить в основную массу, всыпать корицу, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12219,'Джем варить еще десять минут, убрать с огня, разлить в небольшие банки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12220,'Добавить в мясной или рыбный фарш маленькие кубики лука, яйцо, сдобрить солью, перцем, хорошо вымешать. Положить на стол корж, распределить ровным слоем начинку, закрыть другим коржом, аккуратно сжать, на четверть часа оставить в покое, чтобы вафли слегка намокли от сока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12220,'Порезать «торт» на треугольные сегменты очень острым ножом, обмакнуть во взбитое яйцо, обжарить в разогретом масле. Время готовки треугольных котлет в вафельном корже будут зависеть от размера слоя фарша, обжаривать можно под крышкой. Вафельные слои заменяют панировку и придают котлеткам необычный клетчатый вид.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12221,'Ягоды крыжовника и смородины промыть, удалить черенки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12221,'Крыжовник растолочь, красную смородину протереть через сито и перемешать с сахарным песком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12221,'Поставить на огонь средней мощности, довести до кипения, помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12221,'Добавить крыжовник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12221,'Варить 20 минут при постоянном помешивании на тихом огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12221,'Пенку снимать по мере образования.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12221,'Снять емкость с огня, разлить варенье в банки, закатать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12222,'Ягоды всыпать в кастрюлю, влить воду, подержать на огне пять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12222,'Плоды должны дать сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12222,'Размять смородину пестиком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12222,'В кастрюлю влить немного воды, добавить ягодную массу, варить на тихом огне, помешивать деревянной ложкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12222,'Через десять минут после начала варки начинать добавлять сахар небольшими порциями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12222,'Помешивать сахар ложкой, довести до кипения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12222,'Убавить нагрев, подержать варенье на огне еще полчаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12222,'Стерилизовать банки над паром, прокипятить крышки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12222,'Разлить варенье, закатать. Банки перевернуть и укутать одеялом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12223,'Начнём разогревать масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12223,'Тем временем обваляем креветки крахмалом и обжарим в масле. Обжарим в течение минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12223,'Теперь приготовим соус, смешаем майонез, сладкий Чили соус и острый соус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12223,'Смешаем креветки с соусом. Перед подачей можно посыпать зелёным луком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12224,'Обработать ягоды: удалить мусор, хвостики, промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12224,'Превратить урожай в пюре при помощи блендера или мясорубки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12224,'Массу протереть через ситечко.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12224,'Пюре без косточек соединить с сахарным песком, варить на слабом огне семь минут, оставить на ночь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12224,'Затем прогреть в течение десяти минут, оставить на двенадцать часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12224,'Прогреть еще раз, в течение пятнадцати минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12224,'Джем разложить в стерильные банки, укупорить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12225,'Ягоды перебрать, промыть, перемолоть с частью сахара при помощи блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12225,'Можно перетереть массу через сито, это поможет избавиться от косточек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12225,'Перелить будущий джем в чашу мультиварки, добавить пектин, варить пять минут, режим «Тушение» или «Суп».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12225,'Досыпать оставшийся сахар, перемешать, варить еще двадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12225,'Готовый джем разлить в стерильные банки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12226,'Плоды перебрать, удалить плодоножки, промыть, пропустить через мясорубку или перебить блендером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12226,'Всыпать сахар, размешать, поставить на огонь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12226,'Довести массу до кипения, варить десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12347,'Еще раз проварить пять-семь минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12226,'Джем остудить, еще раз довести до кипения, подержать на огне пятнадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12226,'Банки стерилизовать, разложить лакомство, укупорить крышками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12227,'Смешать подсоленное яйцо с сахаром и молоком, добавить растопленное (не горячее) масло, перемешать, всыпать муку, вымесить тесто, дать ему постоять около получаса. Размять картофель с молоком, всыпать обжаренный до изменения цвета лук, перемешать, прикрыть начинку крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12227,'Постоявшее тесто поделить на кусочки (получится примерно 10-12 кусочков), раскатать каждый в тонкую лепешку, проколоть в нескольких местах вилкой, обжарить на прогретой СУХОЙ сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12227,'Смазать каждую лепешку после обжаривания растопленным маслом, сложить в стопку, прикрыть полотенцем. Разложить пару ложек начинки на половинку лепешки, прикрыть другой половиной. Разогревать хрустящий кыстыбый с начинкой из картофеля на сковороде с маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12228,'Плоды жимолости промыть холодной водой, перебрать, обсушить на полотенце.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12228,'Влить в кастрюлю воду, всыпать сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12228,'Довести сироп до кипения, поварить десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12228,'Ягоды всыпать в чистые банки, залить кипящим сиропом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12228,'Закрыть крышкой, пастеризовать в горячей воде, затем консервы закатать. Хранить в прохладе.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12229,'Ягоды вымыть, перебрать и всыпать в банки до «плечиков».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12229,'Влить кипяток, дать постоять десять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12229,'Жидкость слить, добавить сахарный песок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12229,'Поставить на огонь, довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12229,'Сахар должен полностью раствориться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12229,'Сироп повторно влить в банки, закатать, перевернуть, укутать пледом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12230,'анки и крышки стерилизовать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12230,'Всыпать плоды на треть объема.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12230,'Влить кипяток до краев, дать постоять двадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12230,'Жидкость слить в кастрюлю, всыпать сахарный песок, сварить сироп.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12230,'Напиток закатать, перевернуть, укрыть одеялом, оставить до остывания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12231,'Ягоды промыть, перебрать, удалить косточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12231,'Вишню пропустить через мясорубку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12231,'Переложить в кастрюлю, долить воду, всыпать сахарный песок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12231,'Варить повидло на среднем огне, время – два часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12231,'Всыпать лимонную кислоту, продолжать варить до густоты, в конце приготовления огонь увеличить на пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12231,'Разложить массу в банки, закатать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12232,'Залить необходимое количество дрожжей теплым сладким молоком, дождаться вспенивания, замесить из всех ингредиентов тесто, которое не будет прилипать к рукам, оставить в покое на пару часов в теплом месте, за это время два раза обмять и можно начинать делать пирожки (начинка может быть любой).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12232,'Подготовить противень, разложить домашние пирожки из нежнейшего теста, верх промазать яйцом, поставить в прогретый до 200 градусов духовой шкаф, выпекать до аппетитного золотистого колера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12233,'Измельчить в блендере белую смородину, вишню и абрикосы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12233,'Отдельно довести воду до кипения и всыпать сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12233,'Варить сироп пятнадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12233,'Желатин из пакетика залить холодной водой для набухания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12233,'Порциями добавить в негорячий сироп, влить ягодную массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12233,'Варить все вместе один час.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12233,'Разложить в банки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12234,'Влить воду в большую кастрюлю.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12234,'В меньшую – измельченные блендером ягоды, половину нужного объема.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12234,'Варить в течение часа на водяной бане.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12234,'Добавить оставшуюся вишню, молотую корицу, гвоздику, нарезанные желтые яблоки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12234,'Все вместе варить до загустения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12234,'Стерилизовать банки над паром или в микроволновой печи, наполнить повидлом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12234,'Поставить в духовой шкаф на нижнюю полку, температура приготовления – 80 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12234,'При появлении пленки духовку выключить, открыть дверцу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12234,'Банки остудить, закатать, убрать повидло в прохладное место.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12235,'Вишню и смородину измельчить при помощи блендера, переложить в мультиварку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12235,'Выставить режим «Мультиповар», дождаться закипания, пенку убирать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12235,'Выставить режим «Томление» на 60 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12235,'Всыпать сахарный песок через час, варить полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12235,'Разложить готовый продукт в банки, закатать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12236,'Ягоды освободить от косточек, измельчить, смешать с яблочным соком и яблочным же уксусом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12236,'Варить до густоты в течение часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12236,'Всыпать сахарный песок, варить до готовности, масса должна получиться плотной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12236,'Массу разлить в чистые банки, закатать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12237,'Вишню вымыть, перемолоть при помощи мясорубки, переложить в кастрюлю большого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12237,'Всыпать сахар, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12237,'Поставить на огонь, прогревать до закипания, оставить на сорок минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12237,'Добавить пектин, кипятить две минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12237,'Повидло снять с огня, разлить в банки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12237,'Время стерилизации – десять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12237,'Закатать, охладить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12238,'Плоды вишни вымыть, удалить косточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12238,'Массу протереть через крупное сито или пропустить через мясорубку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12238,'Выложить в таз, влить воду, варить на сильном огне в течение получаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12238,'Влить сок крыжовника, довести до кипения, помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12238,'Всыпать сахар, подержать на тихом огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12238,'Массу помешивать до закипания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12238,'После того, как в джеме появятся пузырьки, оставить его на плите еще на десять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12238,'Продукт разлить в банки, укупорить крышками, охладить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12239,'Вишню вымыть, косточки удалить, мякоть перемолоть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12239,'Выложить в емкость, поставить на сильный огонь, довести до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12239,'После появления пузырей огонь сбавить, всыпать пищевую соду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12239,'Подержать продукт на тихом огне в течение сорока минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12239,'Добавить сахар, дольки лимона и сок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12239,'Варить все вместе еще сорок минут, массу помешивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12239,'Джем разлить в банки, закатать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12240,'Нарезаем лук полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12240,'Обжариваем в смеси растительного и сливочного масла лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12240,'Как только лук закарамелизируется: солим, перчим и добавляем чабрец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12240,'Тесто раскатываем в прямоугольник размером примерно 23-25 см на 19-20 см',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12240,'На тесто выкладываем лук отступая от краев 1 см.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12240,'На лук выкладываем измельченную брынзу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12240,'Помещаем пирог в разогретую духовку на 200 градусов примерно на 20 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12241,'Картофель разрезать на 4 части.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12241,'Вешенки нарезать кубиками.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12241,'В разогретую сковороду добавить 1 ст.л. масла.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12241,'Переложить грибы в тарелку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12241,'Добавить в сковороду масло.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12241,'Добавить к картошке грибы.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12242,'Тщательно перемешать муку, яйцо, песто, молоко до однородной массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12242,'Нажарить обычных блинов (жарить с 2-х сторон), уложить начинку из авокадо,стружки сыра и ветчины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12242,'Завернуть блины песто с ветчиной и авокадо в трубочку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12243,'Нарезать картофель и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12243,'Приготовить специи для фри: смешать парику, соль, масло и чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12243,'Нарезанный картофель хорошо перемешать со специями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12243,'Выложить картофель на противень и отправить в духовку на 20 мин. При температуре 200 градусов. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12244,'Сыр натираем на мелкой терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12244,'Туда где вы будете замешивать тесто поочередно добавляем муку 2 стакана, сахар 8 ч.л., рассол 8 ст.л., подсолнечное масло 8 ст.л., 0,5 ч.л. соды и ее нужно погасить уксусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12244,'После этого замешиваем тесто, не забываем добавлять муки что бы тесто было более упругим.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12244,'Как только замешали тесто, делим его на два колобка, и раскатываем один из них, посыпаем сыром и нарезаем на печенки, и и как показано в ролике заворачиваем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12244,'Отправляем в духовке на 10-20 минут при 200 С.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12245,'Поставить варить филе курицы, нарезать молодые шампиньоны, обжарить с небольшим количеством масла. Яйца порезать кубиками, мясо – небольшими кусочками, добавить грибы, всыпать кукурузу. Все перемешать подсолить, сдобрить майонезом, еще раз перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12245,'Переложить салат с куриным филе «Солнышко мое» на широкое блюдо, украсить по кругу четвертинками помидора (чередовать их с веточками кудрявой петрушки), как лучиками солнца, верх оформить маслинами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12246,'В помидорах делаем надрез и заливаем кипятком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12246,'Измельчаем все овощи и сосиски',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12246,'Обжариваем сосиски.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12246,'Обжариваем овощи в следующей последовательности: лук, перец, добавляем помидоры и тушим.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12246,'Овощи солим, перчим, добавляем томатную пасту, чеснок и сосиски.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12246,'Добавляем рис, перемешиваем и заливаем горячей водой. Вода должна быть выше содержимого сковороды или сотейника примерно на 1,5 -2 см.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12246,'Накрываем сковороду крышкой и доводим рис до готовности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12246,'Готовое блюдо посыпаем зеленью петрушки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12247,'Приготовление любого блюда обычно начинается с похода в магазин. Главные ингридиенты в нашем блюде это салат и морепродукты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12247,'Для начала нам необходимо нарезать помидоры черри на 4 части, а кусочки сыра моцарелла на 2 части.','https://vkuso.ru/data/cache/data/75/21b497085188875_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12247,'Салат очищаем от верхних листов и нарезаем поперек полосками 1 см шириной. При этом оставляем большой хороший лист для украшения.','https://vkuso.ru/data/cache/data/ff/247593cbe5017ff_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12247,'Морепродукты в нашем случае уже готовы, что существенно экономит нам время, поэтому их остается только открыть. Поскольку мы используем кальмары и мидии в масле, то при выкладывании старайтесь чтобы масло с них стекло. Почему опять же мы выбрали именно "Лунское море", потому что масло в котором плавают наши "гады" не встает потом в горле "несмываемым вкусом", как у некоторых других производителей.','https://vkuso.ru/data/cache/data/92/8c1ba3a9c913792_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12247,'Салат мы будем собирать порционно. Выкладываем наш красивый лист салата с одной стороны тарелки и на него (как на фото) слоями начинаем выкладывать остальные ингредиенты, создаем небольшую подушку из полосок салата, аккуратно укладываем помидоры черри, сыр и наши морепродукты. Морепродукты я лично не режу, потому что считаю, что если их рвать, то получается вкуснее и красивее и проще украшать. Не забываем немножко солить и перчить каждый слой (без фанатизма)!','https://vkuso.ru/data/cache/data/64/21297437adeca64_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12247,'После того как мы выложили 3 слоя, необходимо заправить наш получившийся салат оливковым маслом и посыпать кунжутом. С маслом важно не переборщить. Это не каша, поэтому масло можно испортить запросто. Поскольку наши морепродукты и там были в масле, нам нужно буквально столовую ложку. Чипсы красиво укладываем со свободного края тарелки, таким образом они не промокнут от остальных продуктов, сохранят свой хруст и очень красиво впишутся в дизайн нашего готового блюда.','https://vkuso.ru/data/cache/data/30/4828eb6d0007430_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12347,'Еще раз выстоять продукт двенадцать часов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12247,'Для любителей пикантных и острых блюд можно применить перец чили или отдельно насыпать его на чистый край тарелки под чипсы, чтобы можно было при желании "играться" со вкусом. Чили в свою очередь очень хорошо сочетается со всеми ингредиентами нашего салата. Данный салат богат витаминами и микроэлементами, при этом содержит достаточное количества белка, чтобы быть диетическим, но в то же время питательным.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12248,'Нашинковать тоненькими кольцами лук, обжарить, добавить порезанные на пластинки шампиньоны (или любые другие грибы), жарить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12248,'В другую сухую сковороду всыпать ложку муки, слегка подогреть без изменения окраски, добавить сливочное масло, объединить с грибами, подсолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12248,'Прогреть пару минут, влить сметану, перемешать, дать закипеть. Домашний соус из шампиньонов готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12249,'Чернику разморозить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12249,'Перетереть при помощи блендера, мясорубки или вручную ложкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12249,'Переложить массу в чашу мультиварки или в кастрюлю.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12249,'Всыпать сахар, выставить режим «Тушение».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12249,'Каждые пятнадцать или двадцать минут варенье помешивать, пенку снимать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12249,'Общее время варки – полтора часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12249,'Разлить массу в банки, укупорить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12250,'Яблоки очищаем, разрезаем пополам, удаляем семечки, делаем несколько продольных разрезов не до конца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12250,'Слоеное тесто раскатываем и вырезаем 10 одинаковых квадратиков, чуть больше половинки яблока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12250,'Каждую половинку яблока укладываем на тесто, приподнимаем и загибаем края.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12250,'Тесто смазываем желтком, а яблоки подогретым абрикосовым повидлом или джемом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12250,'Выкладываем слойки на лист, выстеленный бумагой для выпечки и слегка смазанный маслом. Отправляем в разогретую духовку на 200 градусов на 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12250,'Готовые слойки еще раз смазываем джемом или повидлом и посыпаем миндальными хлопьями.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12251,'Дать бульону закипеть, прикрутить огонь. За это время порезать соленые огурцы на кубики, нашинковать тоненько лук, потушить их с маслом при среднем нагреве минут 5, до тех пор, пока не станут мягкими.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12251,'Добавить в сковороду томатную пасту, прогреть около минуты и вылить в бульон, приправить лавровым листом и горошками перца. Все мясные продукты, которые есть мелко порезать и отправить в суп, варить 6-7 минут. Подготовить и порезать зелень, оливки, каперсы, по ломтику лимона на каждую порцию.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12251,'Все это добавить перед снятием кастрюли с плиты, зелень можно добавить непосредственно в тарелки. Дать классической сборной солянке с каперсами постоять под крышкой, разлить по тарелкам, положить в каждую лимончик.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12252,'Натираем на крупной терке тыкву',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12252,'Яйца размешиваем с сахаром, добавляем сметану, соду, погашенную апельсиновым соком и муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12252,'Очень тщательно отжимаем тыкву от лишней жидкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12252,'Добавляем тыкву, корицу в тесто и тщательно перемешиваем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12252,'Форму смазываем маслом и отправляем в нее приготовленное тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12252,'Запеканку отправляем в духовку на 60 мин.при температуре 190 градусов.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12253,'Добавить к растопленному маслу яйцо, сахар, сметану, чуть соли, перемешать, соединить с мукой и разрыхлителем, вымесить песочное тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12253,'Разрезать яблоки на четвертинки, удалить сердцевину с косточками, порезать тонкими ломтиками, переложить в сковороду, пересыпать сахаром, добавить сливочное масло, тушить около 10 минут, присыпать корицей, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12253,'Для приготовления заливки пару яиц взбить, всыпать сахар, муку с ванилином, добавить сметану, тщательно перемешать. Для присыпки верха руками смешать сахар с мукой, разрыхлителем и размягченным маслом до состояния маслянистой крошки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12253,'Переложить тесто в форму с разъемными стенками, сформовать бортики, заполнить полученное основание начинкой, залить яичной смесью, присыпать масляной крошки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12253,'Выпекать царский ',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12254,'Вымыть и измельчить курагу, порубить (не очень мелко) любые орехи, перемешать. Добавить к этой смеси мед с хлопьями и масло, очень хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12254,'Сделать из массы небольшие шарики, разложить на противень, задвинуть его в прогретую чуть ниже 200 градусов духовку примерно на  треть часа. Диетические фитнес-конфеты готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12255,'Плоды промыть, удалить мусор.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12255,'Ягоды выложить в банку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12255,'Влить кипящую воду, оставить на пятнадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12255,'Перелить жидкость в кастрюлю через дуршлаг.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12255,'Всыпать сахар, довести сироп до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12255,'Влить в банки, закрыть крышками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12255,'Перевернуть, оставить на несколько часов, хранить в погребе.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12256,'Ягоды промыть, удалить плодоножки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12256,'Плоды откинуть на дуршлаг, жидкость должна стечь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12256,'Довести воду до кипения, всыпать сахар, варить в течение пяти или шести минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12256,'Всыпать лимонную кислоту.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12256,'Добавить ягоды.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12256,'Перелить компот в банки, закатать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12256,'Оставить до утра под пледом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12257,'Очистить от пленки поджаренные грецкие орехи, измельчить в блендере до состояния муки. Миндаль положить в холодную воду примерно на треть часа, освободить от кожицы, приготовить из фиников пюре. Если плоды попались суховатые, то минут на 10 залить их кипятком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12257,'Все перемешать в однородную массу и всыпать порошок какао, смешать до однородного состояния. Увлажнить руки, скатать шарики, вложить в середину каждого по миндальному орешку. Обвалять каждый шарик в какао, разложить трюфели из орехов и фиников на плоском блюде, пусть немного постоят.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12258,'Приготовить сироп из сахара и воды, всыпать мороженые ягоды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12258,'Довести до кипения еще раз, варить пятнадцать или двадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12258,'Кастрюлю снять с огня, дать напитку постоять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12258,'Разлить в чистые банки, хранить в подвале.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12259,'В мультиварку влить воду, положить ягоды, всыпать сахарный песок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12259,'Выставить режим «Мультповар» на двадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12259,'В середине приготовления компот перемешать, прибор поставить на паузу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12259,'После отключения напиток должен постоять еще двадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12259,'Напиток разлить в стерильные банки, закатать крышками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12260,'Сгущенное молоко и сливочное масло комнатной температуры взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12260,'Готовое магазинное печенье выложить на блюдо или поднос, каждое окунать в обычное молоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12260,'Получившийся корж смазать кремом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12260,'Чередовать слои до тех пор, пока не закончатся продукты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12260,'Верх торта смазать кремом, поставить на полчаса в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12260,'Часть печенья измельчить в крошку, посыпать сверху.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12260,'Нарезать пластинками яркий мармелад.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12260,'Украсить торт на свой вкус.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12260,'Поставить десерт в холодильник для пропитывания.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12261,'Сырые куриные яйца взбить в пену, ввести сгущенное и обычное молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12261,'Массу варить на тихом огне, довести до кипения и остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12261,'Добавить мягкое сливочное масло, крем взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12261,'Приготовить глазурь из сахара, какао-порошка, молока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12261,'Массу проварить до полужидкой консистенции.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12261,'В форму выложить слой печенья, полить кремом, чередовать печенье и крем несколько раз.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12261,'Готовый торт залить глазурью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12261,'Украсить нарезанной клубникой, поставить в холод для пропитывания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12262,'Песочное печенье размолоть при помощи мясорубки или блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12262,'Перемешать с растопленным сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12262,'Массу утрамбовать в емкости для выпекания, сформовать стенки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12262,'Поставить в холод на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12262,'Перетереть творог, перемешать с ванилином, сгущенным молоком, молотой корицей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12262,'Выложить готовый крем на корж, вернуть в холодильник и дать торту постоять.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12263,'Отварить рис, чтобы он оставался чуть сыроватым. Крупную луковицу порезать, но не крупно, обжарить, перемешать с рисом и фаршем, заправить солью и черным перцем. Если фарш получился чересчур сухим, то можно влить чуть-чуть воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12263,'Кочанчик пекинской капусты разделить на листья, подержать в кипящей воде порядка 3 минут, достать, обсушить, удалить грубые утолщения. Положить на каждый листик примерно по паре ложек фарша (зависит от размеров листьев), аккуратно свернуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12263,'Морковь порезать тоненькой соломкой, вторую крупную луковицу – средними по толщине полукольцами, обжарить примерно до полной готовности. Добавить кусочки двух крупных, мясистых помидоров без кожицы, все протушить минут 5, влить воду, всыпать половину нашинкованной зелени, заправить солью, сахаром, перцем, дать закипеть, снять с плиты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12263,'Переложить голубцы из пекинской капусты с говяжьим фаршем в гусятницу, на дно которой предварительно выложить половину зажарки, залить другой половиной, прикрыть крышкой, поставить тушить еще на 40 минут при слабом нагреве. Подавать готовое блюдо с мелко порубленной зеленью и густой сметаной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12264,'Песочное печенье поломать руками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12264,'Грецкие орехи измельчить скалкой, продукт накрыть пергаментом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12264,'Орехи обжарить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12264,'Добавить сгущенку, мягкое сливочное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12264,'Ингредиенты перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12264,'Ввести печенье.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12264,'Массу выложить горкой на блюдо, уплотнить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12264,'Отдельно перемешать кефир с какао-порошком, сахаром, сливочным маслом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12264,'Все вместе прогреть на тихом огне, крем должен получиться однородным.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12264,'Поставить в холодильник на пятнадцать минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12264,'Залить торт, посыпать маковым семенем.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12264,'Вернуть в холод для пропитывания.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12265,'Перемешать жирные сливки и сгущенное молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12265,'Лимоны вымыть, сок отжать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12265,'Влить сок в крем, перемешать и взбить при помощи венчика.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12265,'Галеты поломать пополам и выложить на дно формы, она должна быть герметичной, емкость лучше застелить пищевой пленкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12265,'Сверху вылить часть крема, разровнять.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12265,'Слои галет и крема повторить несколько раз, сверху должен быть крем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12265,'Посыпать массу кокосовой стружкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12265,'Поставить в холод, дать пропитаться несколько часов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12265,'Перед подачей торта на стол форму снять.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12266,'Печенье покрошить руками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12266,'Грецкие орехи очистить, измельчить, обжарить на заранее разогретой сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12266,'Продукт перемешать с печеньем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12266,'Вареную сгущенку перемешать с мягким сливочным маслом, взбить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12266,'Влить жирные сливки, крем растереть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12266,'Залить смесью печенье, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12266,'Массу выложить в разъемную форму, выстланную пищевой пленкой, утрамбовать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12266,'Поставить торт в холод, дать хорошо пропитаться.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12266,'Перед подачей форму снять.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12267,'Яйца взбить с сахарным песком на водяной бане.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12267,'Загустевшую массу снять с огня и остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12267,'Перемешать с мягким сливочным маслом и сгущенным молоком, перебить миксером.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12267,'Форму смазать маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12267,'Песочное печенье выложить слоями, каждое окунать в крепкий свежезаваренный кофе и в крем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12267,'Торт поставить в холодильник, дать пропитаться.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12267,'Перед подачей десерт вынуть из формы, выложить на широкое блюдо.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12268,'Залейте желатин водой: пусть набухнет. Разделить апельсины на дольки, удалить пленочки, порезать небольшими кусочками, несколько долек оставить для оформления десерта. Залить часть разбухшего желатина частью апельсинового сока, размешать, подогреть (кипятить нельзя!) до растворения, жидкость должна стать однородной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12278,'Обжарить на заранее разогретом масле с веточкой розмарина до корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12278,'Закрыть сковороду крышкой, довести мясо до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12268,'Добавить к сливкам остальной сок, желатин, подогреть, добавить апельсины. Заполнить выбранные формочки на треть объема сливочной массой, дать застыть на холоде. Добавить до 2/3 объема апельсиновую массу, остудить, заполнить до верха оставшейся массой из сливок, дать окончательно застыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12268,'Достаточно аккуратно погрузить формочки на пару секунд в кипяток. Переложить  формочки с апельсиновым легким десертом на красивое блюдо, украсить листочками мяты, либо мелисы с дольками апельсина.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12269,'Сметану взбить с сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12269,'Влить сгущенное молоко, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12269,'Застелить форму пергаментом, выложить часть песочного печенья, поломанного на кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12269,'Сверху распределить крем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12269,'Коржи и крем чередовать несколько раз.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12269,'Торт убрать в холодильник, дать постоять.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12270,'Свежие ягоды перебрать, промыть и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12270,'Приготовить сироп из воды и сахарного песка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12270,'Ягоды выложить в банки, залить горячим сиропом, оставить на час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12270,'Жидкость слить в кастрюлю, довести еще раз до кипения, всыпать лимонную кислоту.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12270,'Сироп разлить в банки, время стерилизации – двадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12270,'Закатать банки крышками, перевернуть, укутать пледом и оставить до остывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12271,'Удалить плодоножки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12271,'Быстро вымыть ягоды, не замачивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12271,'Положить в кастрюлю, засыпать сахарным песком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12271,'Оставить на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12271,'Влить воду, довести до кипения, переложить в остуженные банки, закрыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12272,'Ягоды вымыть, всыпать в банки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12272,'Растворить сахарный песок в кипящей воде, прогреть пять или семь минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12272,'Всыпать лимонную кислоту.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12272,'Влить сироп, банки закатать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12273,'Ягоды засыпать сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12273,'Дать постоять два или три часа, продукт периодически встряхивать, но не перемешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12273,'Добавить кусочки яблок без кожицы, влить воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12273,'Компот прокипятить, разлить в банки, закатать крышками и остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12274,'Воду вскипятить вместе с половиной нормы клубники, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12274,'Перебрать вишню, косточки удалить, ягоды ссыпать в банку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12274,'Добавить оставшуюся клубнику, залить доведенным до кипения соком с водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12274,'Добавить листочки мяты, закрыть, дать постоять под пледом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12275,'Ягоды вымыть и загрузить в чашу мультиварки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12275,'Всыпать сахарный песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12275,'Влить воду до верха, выставить режим «Тушение» на час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12275,'Компот перелить в тару, закатать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12276,'Расплавить в сковороде мелкозернистый сахар до изменения цвета, перелить в керамическую форму, дать остыть. Теперь нужно приготовить молочное суфле. Взбить блендером сахар с молоком и яйцами, добавить ванильный сахар, перелить суфле к карамели. Смешать все ингредиенты для теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12276,'Распределить тесто равномерным слоем по форме сверху суфле, оно начнет тонуть, не пугайтесь, так и должно быть. Налить в противень воду, поставить форму в духовой шкаф с температурой 200 градусов, пирог будет готов примерно через полтора часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12276,'Тесто в форме будет находиться сверху, готовый сладкий пирог с карамелью и молочным суфле остудить, прикрыть плоской тарелкой форму и резко, но аккуратно перевернуть ее. Желательно для полного остывания поставить в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12277,'Ломтики хлеба для тостов подсушить или обжарить на сухой сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12277,'Остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12277,'Куриное филе отварить, нарезать толстыми кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12277,'Свежие огурцы и помидоры нашинковать кружками, кончики удалить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12277,'Хлеб намазать майонезом «Провансаль», выложить хорошо промытый и обсушенный салат.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12277,'Следующие слои – курица, овощи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12277,'Далее – второй ломтик хлеба, намазанный майонезом с двух сторон, помидоры, курица, салат.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12277,'Накрыть третьим кусочком хлеба, смазанным майонезом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12278,'Нарезать огурцы и помидоры, крымский лук нашинковать кольцами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12278,'Намазать хлеб для тостов неострой пряной аджикой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12278,'Присыпать рубленой зеленью, выложить куриное мясо.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12278,'Сверху поместить томаты, лук и огурцы.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12278,'Накрыть пластинками сливочного сыра.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12278,'Закрыть бутерброд вторым ломтиком хлеба, намазанным аджикой с внутренней стороны.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12278,'Бутерброды по желанию можно прогреть.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12279,'Куриное филе посолить, молотым перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12279,'Разогреть масло на сковороде, обжарить курятину.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12279,'Обжарить хлеб для тостов на сковороде-гриль или подсушить на обычной сковороде с маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12279,'Обжарить бекон до хруста, грудку нарезать ломтиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12279,'Нашинковать сладкий крымский лук тонкими кольцами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12279,'Отварить яйца, нарезать кольцами, так же нарезать помидоры.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12279,'Хлеб для тостов намазать майонезом, выложить листья салата «Айсберг», куриное мясо, яйца.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12279,'Накрыть бутерброд вторым ломтиком хлеба, так же намазать майонезом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12279,'Положить салат, бекон, лук и помидоры.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12279,'Накрыть сэндвич третьим кусочком хлеба, смазанным майонезом с внутренней стороны.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12279,'Бутерброд разрезать на две части, каждую проколоть шпажкой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12280,'Ржаные булочки разрезать на две части, обжарить половинки на гриле или на сухой сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12280,'Репчатый лук очистить и нарезать кольцами, обжарить на растительном масле, добавить сахар, соль, винный уксус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12280,'Крупные шляпки грибов нарезать пластинками, обжарить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12280,'Куриную грудку замариновать в смеси из подсолнечного масла, лимонного сока, перца и соли, прованских трав.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12280,'Время пропитывания – полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12280,'Мясо обжарить на разогретом масле до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12280,'Булочки смазать французской горчицей, накрыть ломтиками сыра «Бри» или «Камамбер».',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12280,'На мясо выложить грибы, посыпать рубленым укропом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12280,'Накрыть бутерброд второй половиной булочки, прижать, уплотнить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12280,'Прогреть закуску на гриле и подать к столу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12281,'Всыпать в эмалированную миску сахар, добавить мягкое масло и мед, прогреть треть часа на водяной бане, положить соду (погасить), продолжать мешать. Убрать с плиты, всыпать просеянную муку, вымесить тесто, если надо, то подсыпать еще порцию муки, убрать колобок теста в теплое место.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12281,'Поделить колобок теста на 7-9 одинаковых частей, раскатать каждый довольно тонко, но очень аккуратно, чтобы не порвать. Навернуть каждый по очереди на скалку и перенести на подготовленный противень, выпекать при температуре в 200 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12281,'Смешать сливочное масло с половинкой стакана сахара.  В другой миске смешать пару яиц со стаканом молока, ванилином и парой ст.л. муки, размешать, постепенно прогреть пока смесь не начнет густеть, дать ей остыть. Добавить в крем масло и сахар, очень хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12281,'Холодные коржи промазать кремом, оформить торт с медом и заварным кремом «Рыжик»',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12281,'дробленым орехом и крошками от коржей, поставить в холодильник, желательно на целую ночь. Чем лучше пропитается тортик, тем будет вкуснее и нежнее.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12282,'Приготовить соус из кремового сыра и зернистой горчицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12282,'По желанию использовать острую горчицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12282,'Мелко порубить чеснок, укроп, соленые огурцы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12282,'Добавить в соус, перемешать, пасту посолить и поперчить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12282,'Черный хлеб нарезать ломтиками, смазать полученным соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12282,'Помидоры нарезать кружками, выложить на хлеб.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12282,'Куриное филе порвать на волокна, выложить поверх помидоров.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12282,'Бутерброд накрыть второй частью хлеба, подать на стол.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12283,'На водяной бане довести до кипения сливки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12283,'Уменьшить огонь, всыпать разломанную на кусочки плитку темного шоколада.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12283,'Помешивать до растаивания, снять с плиты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12283,'Влить ликер, перемешать еще раз.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12284,'Желатин залить водой так, как написано на упаковке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12284,'Ввести в полуостывшую глазурь, температура продукта – от 55 до 60 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12284,'Массу перемешать, процедить через марлю.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12284,'Покрыть торт, температура – 35 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12285,'Сливочное масло растопить вместе со сгущенным молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12285,'Всыпать какао, массу взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12285,'Залить торт умеренно горячей глазурью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12286,'Начинать приготовление энчилада удобнее всего с соуса. Подготовить лук, чеснок, перец, тщательно удалить у перца все семена (они дают чрезмерную остроту), все мелко нашинковать, обжарить минут 5 в хорошо разогретом масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12286,'Затем добавить нарезанные консервированные (лучше в собственном соку) помидоры, сдобрить черным перцем, сахаром и солью. Аккуратно смесь размешать, тушить еще минут 7 до полной готовки соуса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12286,'Прогреть в другой сковороде растительное масло, положить фарш из курицы, жарить пока не исчезнет вся жидкость, а мясо не начнет изменять цвет и подрумяниваться. Приправить фарш красным молотым острым перцем, орегано, зирой, солью, кориандром, жарить мясо со специями еще 5 минут. Включить для прогрева до 180 градусов духовку, нарубить зелень кинзы, измельчить на терке сыр твердого сорта.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12286,'Готовые тортильи чуть прогреть в микроволновке, чтобы они потеряли некоторую часть жесткости и слали более податливыми при сворачивании. На половинку лепешки уложить пару-тройку столовых ложек обжаренного фарша из курицы, на него – сырную стружку, присыпать зеленью кинзы, аккуратно свернуть в трубочку, поступить так со всеми лепешками. Часть сыра и кинзы надо оставить для присыпания верха энчилада с куриным фаршем после выкладывания лепешек в форму.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12286,'В подготовленную для запекания форму налить половину приготовленного острого соуса, уложить вниз швом трубочки лепешек, полить оставленной частью соуса, присыпать сырной крошкой и рубленой зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12286,'Форму отправить в прогретую духовку на треть часа, за это время сыр должен полностью расплавиться и даже начать слегка кипеть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12287,'Сахарную пудру несколько раз просеять, сформовать горку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12287,'Влить горячую воду в центр, взбить массу венчиком. Если масса получилась жидкой – добавить крахмал или еще немного сахарной пудры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12287,'Влить лимонный сок, взбивать глазурь до воздушности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12288,'Охладить белки, взбить, сахарную пудру подсыпать порциями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12288,'Однородную массу поставить на конфорку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12288,'Продолжать взбивать, глазурь должна загустеть и побелеть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12288,'Снять с огня, остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12288,'Мягкое сливочное масло взбить отдельно, влить лимонный сок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12288,'Обе массы соединить при помощи миксера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12289,'Перемешать в небольшой емкости ягодный сироп с медом и сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12289,'Прогреть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12289,'Влить воду, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12289,'Залить кипятком агар-агар, как написано в инструкции.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12289,'Поломать белый шоколад, прогреть со сливками, снять с огня.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12289,'Массу взбить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12289,'Ввести в нее ягодный сироп.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12289,'Ввести желатин, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12289,'Цвет можно усилить кондитерским красителем.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12289,'Залить торт, температура глазури – 45 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12290,'Баклажаны мою, отрезаю хвостики и делаю надрез вдоль баклажана в ввиде кармашка. Кладу баклажаны в кипящую, подсоленную воду и провариваю около пяти минут, затем баклажаны достаю и даю им остыть.','https://vkuso.ru/data/cache/data/b9/29fc31a8887d2b9_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12290,'Готовлю рассол: в оду добавляю соль и ставлю на огонь давая воде закипеть чтоб растворилась вся соль, затем рассол остужаю.','https://vkuso.ru/data/cache/data/03/256dfae335d3503_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12290,'Морковь тру на крупной терке, тру чеснок, нарезаю зелень и сладкий перец все смешиваю и добавляю кариандр и черный молотый перец.','https://vkuso.ru/data/cache/data/ae/b116016edebc8ae_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12290,'Фарширую остывшие баклажаны овощной начинкой, заливаю остывшим рассолом, накрываю тарелкой и ставлю сверху гнет.','https://vkuso.ru/data/cache/data/01/7dc6691aa561501_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12347,'В третий прием добавить в варенье ядрышки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12290,'Оставляю на столе на несколько часов, затем убираю гнет и отправляю в холодильник на трое суток.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12291,'Средние по размеру картофелины порезать дольками, если использовать специальный круглый резак (обычно применяют для нарезки на дольки яблок), то дольки получаются красивого и одинакового размера, а еще и время на нарезку экономится.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12291,'Уложить дольки картофеля, обсыпанные специями, в форму, переложить ломтиками бекона, поставить в духовой шкаф, готовить пряный картофель с беконом при температуре 180 градусов. Примерно через треть часа или чуть больше благоухающее  и вкусное блюдо будет готово.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12292,'Приготовим спагетти. И начнём готовить соус.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12292,'На сковородке разогреем оливковое масло, раздавим чеснок и добавим хлопья перца, цедру лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12292,'Добавим спагетти и выловим сок лимона. Посыпаем пармезан, кинзу и перемешаем',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12293,'Куриное филе нарезаю кусочками, отбиваю с двух сторон, солю, перчу и обжариваю слегка с двух сторон.','https://vkuso.ru/data/cache/data/55/2f347d705bdbe55_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12293,'На помидорах делаю надрезы крест на крест и заливаю кипятком на две минуты, затем воду сливаю и с помидор снимаю кожицу.','https://vkuso.ru/data/cache/data/f6/6921c10a95f21f6_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12293,'Помидоры нарезаю не большими кусочками, так же нарезаю перец и грибы. Мелко рублю петрушку, зеленый лук, натираю сыр на крупной терке и смешиваю все ингредиенты, хорошо перемешиваю.','https://vkuso.ru/data/cache/data/41/bc24f36d5175541_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12293,'Филе выкладываю на противень, на каждый кусочек выкладываю овощную шубку, сверху еще натертый на терке твердый сыр и отправляю в духовку на 20 минут. Горячими подаю на стол.','https://vkuso.ru/data/cache/data/50/2d43dc9c1db2250_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12294,'В миску разбиваем 2 кур. яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12294,'Вливаем молоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12294,'Вливаем растопленное сливочное масло',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12294,'Добавляем 2 ст.л. сметаны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12294,'Добавляем 3-4 ч.л. сахара и 1 щепотку соли. И все это хорошо взбиваем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12294,'После того как взбили, постепенно добавляем муку, и замешиваем тесто.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12294,'Как только замешали тесто, делим его на равные колобки, и каждый колобок поочередно раскатываем. Далее тонкий пласт теста нарезаем на прямоугольники, и в каждым прямоугольнике проделываем отверстие!',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12294,'Как только все подготовили, в каждое проделанное отверстие продеваем один край. У вас должна получится спираль.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12294,'И уже в конце, каждую заготовку хвороста отпускаем в разогретое подсолнечное масло. и жарим до корочки.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12295,'Измельчаем все ингредиенты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12295,'Обжариваем лук и грибы, солим и перчим их.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12295,'Собираем салат в разъемной форме: дно и бока смазываем майонезом. Слои: 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12295,'Салат помещаем в холодильник минут на 30, чтобы настоялся. Приятного аппетита!',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12296,'Порезать картофель тоненькими кружочками, лук и крупные помидоры – на полукольца, а рыбу – небольшими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12296,'Для этой вкусной запеканки с рыбкой сыр не натирается, как во многих рецептах, а нарезается на тонкие пластиночки, как для приготовления бутербродов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12296,'Всыпать в сливки перец, соль, можно и готовую смесь приправ для рыбы, перемешать, а подготовленную зелень порубить на мелкие кусочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12296,'Выложить в форму с достаточно высокими бортиками картофельный слой кружков, затем полукольца лука, завершить слоем из рыбы, чуть присолить, присыпать зеленью, полить частью сливок, выложить помидоры, опять полить сливками, завершить пласты сырным слоем, осторожно полить остатками сливок по краям формы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12296,'Отправить на полчаса запеканку в духовку с температурой чуть выше 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12306,'Всыпать крахмал и сахарную пудру, смесь взбить. Немного остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12297,'Подготовить печень, зачистить, снять верхнюю пленку, порезать на плоские куски, можно слегка отбить, обжарить до образования корочки вместе с полукольцами лука.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12297,'Добавить в сковороду стакан воды, закрыть крышкой, тушить до мягкого состояния печени. Порезать три плавленых сырка на кусочки, высыпать в сковороду, дать им растворится.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12297,'Нарубить укроп, смешать с раздавленным чесноком, высыпать в пол-литра йогурта, вылить в сковороду, тушить еще 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12298,'Сварить до полной готовности рис, перемешать с зеленым горошком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12298,'Поставить сковороду с маслом разогреваться, мясо порезать, обжарить минут 5, перемешать. Разболтать с водой пару столовых ложек томатной пасты, вылить к курице, добавить соль, лимонный сок, перец и мед, перемешать, тушить рис с куриной грудкой в кисло-сладком соусе 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12298,'Разложить по тарелкам рис горкой, положить поверх мясо грудки курицы, полить соусом из сковороды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12299,'Подготовьте и обработайте мясо куриных грудок, нарежьте на средние кубики. Смазать слегка противень маслом, разложить мясо, задвинуть в духовой шкаф на полчаса. Нарезать лук средними полукольцами, чеснок – пластинками, добавить к мясу, запекать еще четверть часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12299,'Измельчить консервированные помидоры, зелень базилика и орегано, перемешать, полить равномерно мясо пастой и отправить еще на полчаса в духовой шкаф, достать, присыпать измельченным зеленым луком. На гарнир к куриным грудкам по-итальянски (Каччиаторе) подать овощи, но можно и молодой картофель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12300,'Развернуть пласт готового слоеного теста, раскатать и промазать горчицей. Порезать огурцы, помидор и ветчину на маленькие кубики, натереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12300,'Выложить на раскатанный пласт сырную стружку, а на нее огурец с ветчиной, далее опять сыр, присыпать перцем и слегка смесью трав.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12300,'Свернуть пласт в рулет и переложить на противень, смазать взбитым яйцом, чтобы при запекании образовалась красивая корочка, присыпать травами, отправить голландский рулет с ветчиной и помидорами в духовой шкаф, выпекать до полной готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12301,'Промыть рис в холодной воде. Выложить рис в кастрюльку залить водой 1/1. Поставить на сильный огонь. Как только вода закипит, убавить огонь до минимума, накрыть крышкой и варить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12301,'Смешать томатную пасту, сметану и майонез.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12301,'Булочку замочить в молоке, отжать немного и добавить в фарш.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12301,'Добавить рис, соль, перец. Перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12301,'Сформировать шарики.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12301,'Залить мясные шарики соусом. Выпекать 40-45 мин при 180 С',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12302,'Растопить шоколад.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12302,'Смешать хлопья с шоколадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12302,'Разложить по формам и в холодильник для застывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12303,'Сложить кусочки хлеба внахлест на пищевую пленку, но можно разложить и на циновке для суши, так потом будет легче сворачивать. Прикрыть все кусочки слоем пищевой пленки и прокатать с нажимом скалкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12303,'Нанести на тонкий хлебный пласт слой сливочного сыра, выложить сверху пластинки рыбы, присыпать порубленными перьями зеленого лука, свернуть с нажимом в трубочку, как сворачивают роллы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12303,'Полученный рулет обернуть фольгой и отправить в холодильник на час. Достать хлебную закуску с копченой форелью, порезать на кусочки, украсить сеточкой из майонеза, присыпать зернами кунжута.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12304,'Желатин замочить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12304,'Приготовить сахарный сироп, прокипятить его с водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12304,'Ввести набухший желатин, ввести лимонную кислоту.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12304,'Массу перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12304,'Белок взбить миксером до увеличения объема.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12304,'Всыпать сахарную пудру, продолжать взбивать массу до пышности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12304,'Перемешать с желатиновой смесью, сформовать мягкий колобок.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12305,'Шоколад растопить вместе с какао-маслом, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12305,'Остудить до сорока градусов, распылить при помощи краскопульта.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12306,'Молоко прогреть, всыпать в него кофейные зерна, варить пятнадцать минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12306,'Зерна вынуть и выбросить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12347,'Далее варить по той же схеме.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12307,'Разрезать куриные грудки вдоль на тонкие пласты, разделить куски мяса на 4 части, поперчить, присолить каждый кусочек с двух сторон. Добавить к фаршу сухари, мелко порезанный лук, петрушку, сдобрить перцем, солью, перемешать, поделить на три части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12307,'Подготовить форму, смазать маслом, выложить дно бумагой для выпечки. Уложить на дно один пласт мяса, распределить на нем равномерным слоем одну часть фарша, посыпать молотой паприкой. Прикрыть другим пластом мяса с фаршем и паприкой, повторить слои еще раз, накрыть бумагой для выпечки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12307,'Установить форму в глубокую сковороду, залить горячей водой так, чтобы форма была погружена на 2/3 в жидкость. Сковороду прикрыть крышкой, установить в духовой шкаф, после закипания воды держать при слабом кипении еще 2 часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12307,'Отключить нагрев, голландский пудинг из курицы не доставать из духовки еще полчаса. Вынуть форму, остудить, прикрыть крышкой, дать переночевать в холодильнике, достать нарезать кусками, подать с маринованными овощами и подходящим соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12308,'Желатин замочить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12308,'Крахмал просеять два раза, залить холодными сливками, перемешать. В смеси не должно быть комочков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12308,'Сахар прогреть на сковороде, дать потемнеть. Огонь – максимальный.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12308,'Влить теплую воду, огонь усилить, масса должна закипеть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12308,'Добавить крахмал со сливками, снять с плиты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12308,'В немного остывшую массу ввести желатин, хорошо перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12308,'При заливке торта температура глазури – 27 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12309,'Плоды промыть, обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12309,'Сварить сироп из воды с сахарным песком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12309,'Довести до кипения, положить плоды, оставить на шесть или восемь часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12309,'Довести до кипения еще раз.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12309,'Остудить и разлить в стерильные банки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12310,'Для приготовления смузи взять пару стаканов кефира с малой жирностью. Порезать крупный банан на мелкие кусочки, поместить в чашу блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12310,'Влить чайную ложку сока лимона, добавить мед, взбить до однородности около 3-4 минут. Разлить смузи «Банановая нежность» с кефиром по бокалам, украсить листочками мяты, пить охлажденным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12311,'Нарезать лук и грибы, обжарить на масле, добавить измельченную зелень и сметану, перемешать, прогреть все вместе пару минут, снять сковороду  с начинкой с плиты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12311,'Раскатать пласт теста, порезать на квадраты, а далее – треугольниками. Разболтать желток с небольшим количеством воды, смазать края треугольников,',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12311,'Положить на середину каждого треугольного сочня по чайной ложечке начинки, прикрыть пластинкой сыра. Острые углы сочня загнуть внахлест к прямому углу, защипать по бокам. Середину пирожка не защипывать: сыр расплавится и плотно «запечатает» просвет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12311,'Разложить на противне, смазать верхушки желтком, отправить в духовой шкаф с температурой в 190 градусов, выпекать закусочные пирожки с сыром и грибами до  готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12312,'Залить дрожжи небольшим количеством теплой воды, всыпать сахар и муку, добавить чуть соли, перемешать, дать постоять около часа в тепле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12312,'Выложить тесто столовой ложкой на хорошо разогретую сковороду с маслом, обжарить с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12312,'Подать постные оладушки на воде с вареньем, сладкими фруктами или медом, а в скоромные дни со сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12313,'Накрошить мелко половинку красной луковицы, влить сок лайма и масло, присолить и поперчить. Разморозить вареные креветки, удалить панцири, порезать на кусочки, высыпать к луку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12313,'Разрезать плод авокадо пополам, удалить косточку, порезать мелкими кусочками, соединить с креветками, добавить порезанный болгарский перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12313,'Аккуратно перемешать мексиканский салат из креветок и авокадо, порубить очень мелко кинзу, присыпать верх салата, полить еще раз соком лайма.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12314,'Нарезать на полукольца лук, болгарский перец разных цветов – широкими полосами, морковь – тоненькой соломкой. Сало порезать кубиками, вытопить в казане с толстым дном до образования шкварок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12321,'Апельсины можно использовать вместе с цедрой, пропустить продукт через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12314,'Всыпать лук, жарить до тех пор, пока он не станет прозрачным, добавить соломку моркови и порошок паприки, размешать. Добавить в казан через пару минут сладкий перец, размешать, прогреть около минуты, добавить порезанные крупными кусками помидоры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12314,'Тушить под крышкой еще минут 40 при слабом кипении. Порубить чеснок, добавить в венгерское лечо из болгарских перцев, влить уксус, приправить сахаром и солью, хорошо перемешать, крышку закрыть и тушить еще минут 10. Закуску остудить, разложить по банкам, убрать в прохладное место.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12315,'Нарезать бекон кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12315,'Раздавить чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12315,'Нарезать кинзу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12315,'Натереть сыр на мелкой терке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12315,'В кипящую воду добавить соль и спагетти.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12315,'Затем добавить замороженный горошек и варить 1 минуту.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12315,'Обжарить бекон в масле.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12315,'Добавить чеснок, жарить еще 3 минуты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12315,'Убрать чеснок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12315,'Выложить спагетти с горошком на сковороду.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12315,'Добавить 2 половника воды.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12315,'Готовить 5 минут на средне-сильном огне.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12315,'Добавить соль, перец, кинзу, сыр, хорошо перемешать.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12316,'В каждой рыбине делаем разрез через спинку, оставляя брюшко целым, вычищаем все пленочки. Удаляем хребет и кости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12316,'Подготовленное филе сбрызгиваем лимонным соком и соевым соусом, оставляем мариноваться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12316,'Обжариваем на растительном масле нарезанный лук, сладкий перец и натертую на крупной терке морковь, солим, добавляем зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12316,'На замаринованное филе скумбрии выкладываем сверху обжаренные овощи. Распределяем их равномерно по рыбе и сворачиваем рулетом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12316,'Рулет переносим на сложенную вдвое фольгу, которая предварительно смазана растительным маслом. Плотно закручиваем и отправляем в духовку на 40 минут при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12316,'После запекания даем рулету остыть и помещаем в холодильник на 3-4 часа.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12317,'Плоды вымыть, разрезать пополам или на четыре части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12317,'Косточки расколоть, вынуть ядра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12317,'Приготовить сахарный сироп, залить абрикосы с ядрами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12317,'Пенку снять, дать постоять восемь часов, довести до кипения еще раз.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12317,'Варенье остудить, разлить в чистые банки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12318,'Плоды вымыть и обсушить, косточки удалить при помощи шила.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12318,'Косточки расколоть, вынуть ядра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12318,'Поместить ядра внутрь абрикосов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12318,'Сварить сироп, залить плоды, довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12318,'Пенку снять.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12318,'Варенье остудить, процедуру повторить два или три раза.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12318,'Для варки лучше всего использовать таз или большую кастрюлю с эмалевым покрытием.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12318,'Продукт уварить по объему в два раза.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12318,'Довести до готовности, остудить, разлить в небольшие банки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12319,'Абрикосы вымыть, обсушить, разрезать пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12319,'Из косточек вынуть ядра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12319,'Пропустить через мясорубку лимоны, можно использовать только мякоть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12319,'Сварить сироп, в кипящую воду добавить лимонную смесь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12319,'Подержать пять минут под крышкой, затем положить ядрышки и плоды.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12319,'Еще раз довести до кипения, пену снять.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12319,'Уварить массу в два раза.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12319,'Продукт остудить, разлить в банки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12320,'Приготовить картофельное пюре с молоком и маслом. Разогреть в сковороде масло, положить мелко нарезанный репчатый лук, жарить до изменения цвета на золотистый, добавить фарш, жарить до его готовности, но можно и чуть дольше до коричневатого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12320,'Приправить черным перцем, солью, соевым соусом и томатной пастой, добавить овощи, перемешать, переложить в форму. На фарш уложить слой картофельного пюре, разровнять, присыпать сырной стружкой, прикрыть фольгой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12320,'Отправить форму в духовку, выпекать шепардский (коттеджный) пирог полчаса при 180 градусах, осторожно удалить фольгу, выпекать еще 10 минут до зарумянивания верха.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12321,'Абрикосы разрезать пополам, часть плодов заменить персиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12321,'Приготовить сироп, массу варить до уменьшения в два раза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12321,'Разлить в банки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12322,'Плоды вымыть, отделить косточки, вынуть ядра и уложить их обратно в мякоть абрикосов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12322,'Выложить в чашу мультиварки, всыпать сахарный песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12322,'Дать постоять три часа, чтобы выделился сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12322,'Влить воду, выставить подходящий режим.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12322,'Варенье остудить и оставить на сутки. Затем разлить в банки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12323,'Абрикосы промыть под струей воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12323,'Обсушить, удалить косточки и кожицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12323,'Положить в емкость.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12323,'Отдельно сварить сироп из воды и сахара на огне средней мощности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12323,'Залить абрикосы, остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12323,'Довести до кипения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12323,'Процесс повторить три раза.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12323,'Горячее варенье разлить в банки и закрыть крышками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12324,'Фрукты вымыть и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12324,'Удалить косточки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12324,'Плоды уложить в кастрюлю, всыпать сахарный песок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12324,'Выложить второй слой фруктов, всыпать оставшийся сахар.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12324,'Оставить плоды на сутки в прохладе.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12324,'Кастрюлю поставить на средний огонь, довести до кипения. Абрикосы станут прозрачными.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12324,'Всыпать лимонную кислоту, пену снимать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12324,'Содержимое кастрюли варить от десяти до пятнадцати минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12324,'Стерилизовать банки, разложить варенье. Закрыть десерт крышками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12325,'Плоды вымыть, удалить косточки так, чтобы не повредить абрикосы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12325,'Ядрышки удалить, пленки удалить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12325,'Вложить косточки обратно в плоды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12325,'Сахар всыпать в воду, варить до растворения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12325,'Всыпать плоды, варить пять минут, не перемешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12325,'Пену снять, заготовку оставить на двенадцать часов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12325,'Процесс варки и последующего настаивания повторить несколько раз.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12325,'Варенье должно получиться густым.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12325,'Заготовку разлить в стерильные банки, закрыть крышками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12326,'Включить на разогрев до 160 градусов духовку, подготовить форму для выпекания пирога: смазать маслом, притрусить мукой или манкой (излишки стряхнуть).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12326,'К желткам яиц прибавить сахар и около столовой ложки воды, все взбить на большой скорости до образования смеси кремового цвета. Влить распущенное сливочное масло, сдобрить солью и ванилином, слегка взбить еще раз.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12326,'Хорошо перемешать какао с мукой и по частям добавить к желтковой массе, влить чуть подогретое молоко, взбить в однородную массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12326,'Отмыть и высушить венчик, вставить в миксер, взбить хорошо белки с добавлением уксуса (пена должна быть устойчивой и не терять форму). Добавить постепенно белки к тесту (после каждого добавления размешивать), полученную массу поместить в форму.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12326,'Шоколадный пирог «Волшебный» будет готов примерно через час. Не пугайтесь, что центр у него будет чуть жидковатым – это нормально. Дать десерту хорошо остыть, порезать очень острым ножом на куски и подать к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12327,'Фрукты промыть, разрезать на половинки, удалить косточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12327,'В кастрюлю всыпать сахар, влить воду, прогревать на тихом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12327,'В закипевший сироп положить фрукты и орехи, варить пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12327,'Снять с огня, оставить на ночь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12327,'Прогревать варенье на тихом огне пятнадцать или двадцать минут до загустения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12327,'Разлить в банки, закатать, перевернуть, укрыть одеялом до остывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12328,'Плоды наколоть деревянными зубочистками, промыть, откинуть на дуршлаг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12328,'В воду всыпать сахарный песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12328,'Варить до растворения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12328,'Фрукты выложить в сироп, влить лимонный сок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12328,'Варить до полной готовности, пену снимать периодически.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12328,'Горячую массу разлить в банки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12329,'Смешиваем мясной бульон с томатной пастой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12329,'Готовим мясную начинку: измельчаем лук и обжариваем до мягкости, добавляем фарш, солим, перчим, добавляем томатную пасту, смешанную с бульоном, обжариваем все минут десять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12329,'Готовим соус Бешамель: растапливаем сливочное масло, добавляем просеянную муку, непрерывно помешивая венчиком, вливаем тонкой струйкой молоко, продолжая помешивать. Как только соус начнет густеть, добавляем соль и мускатный орех. Как только соус начнет кипеть - выключаем огонь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12329,'Натираем сыр на терке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12329,'Собираем лазанью, на дно формы выкладываем слой соуса Бешамель, затем слой листов лазаньи, сверху мясную начинку, на мясную начинку снова соус Бешамель и посыпаем сыром. Все слои выкладываем в том же порядке. Последним слоем должен быть сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12329,'Форму с лазаньей отправляем в разогретую духовку на 200 градусов примерно на 30 минут, ориентируйтесь на свою духовку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12330,'Порезать готовое магазинное тесто полосками, выпечь трубочки, дать остыть, снять с конусов, заполнить рыбной смесью. Для приготовления начинки открыть консервы, удалить сок, размять вилкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12330,'Крутые яйца порубить, сыр натереть, маслины разрезать на колечки, все всыпать к рыбе, добавить майонез, зелень, осторожно и очень хорошо перемешать, заполнить слоеные заготовки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12330,'Вот и все, вкусный салат с рыбными консервами в трубочках готов. Осталось только перед подачей присыпать семенем кунжута.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12331,'Сначала взбиваем яйца с помощью миксера, затем добавляем йогурт и сахар. Мы также добавляем масло и просеянную муку, все размешиваем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12331,'В этот момент добавляем цедру лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12331,'Порежьте яблоко на кубики и добавьте в тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12331,'Хорошо перемешайте тесто, затем нарезаем яблоко кольцами не толще 0,5 см, удаляем сердцевину. Оставляем колечки в миске с лимонным соком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12331,'Варим сахарный сироп, выливаем в форму для запекания, у меня форма разъемная, я застелила ее тефлоновым ковриком. И сразу же выкладываем колечки яблок, затем вылейте тесто в форму с яблоками. Выпекаем при 180 40-50 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12331,'Даем немного остыть в форме, затем форму разбираем, пирог переворачиваем с помощью тарелки, аккуратно снимаем коврик, порог готов.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12332,'Разрезать яблоки на четвертинки, удалить семечки и сердцевину, нарезать довольно мелкими кубиками. Подготовить противень: застлать пекарской бумагой, слегка смазать маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12332,'Добавить к яблокам остальные смешанные ингредиенты, тщательно еще раз перемешать, выложить тесто ложкой на противень. Вплотную выкладывать булочки нельзя, т.к. во время выпечки они увеличиваются в объеме.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12332,'Готовить вкусные домашние булочки с яблоком около 15 минут при температуре в духовке порядка 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12333,'В чаше соедините растительное масло, пюре тыквы, желтки и сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12333,'Пюре можно взять совершенно любое, сделать самостоятельно или купить готовое.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12333,'Тыкву варить (или запекать), а потом уже пюрировать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12333,'Хорошо взбейте массу до однородности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12333,'Добавьте разрыхлитель, соду и специи (любые на 1 ч.л.).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12333,'Далее добавляем муку, все перемешиваем, взбиваем белки до мягких пиков и вводим порционно в тыквенное тесто.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12333,'Выпекайте при 180 градусах до фактической готовности, примерно 50-60 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12334,'Включить и прогреть духовку до 180 градусов, подготовить противень для выпекания печенья. Шоколад (половину) поломать на кусочки, растопить с добавлением масла на водяной бане, но можно и в микроволновке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12334,'Сахар высыпать в чашу миксера, добавить яйца, ванильный сахар, перемешать все вместе около 4 минут, влить жидкий шоколад, понизить скорость и перемешать до однородного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12334,'Добавить к тесту остатки кусочков шоколада (150 гр) и перемешать. Смешать в отдельной емкости разрыхлитель с мукой и солью, вылить в шоколадную смесь, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12334,'Зачерпнуть массу столовой ложкой и выложить горками на противень с расстоянием в 5-6 см. Задвинуть противень в прогретую  духовку, готово домашнее печенье «Шоколадка» будет через четверть часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12335,'Для начало разогреем масло в сковородке, раздавим чеснок, добавим имбирь и острый перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12335,'Теперь добавим сладкий перец, фасоль, горох и зелёный лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12335,'Далее зальём соевый соус, кунжутное масло и рисовый уксус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12335,'Добавим лапшу и зальём куриным бульоном, теперь посолим и чайную ложку карри. Готовить до приготовления лапши.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12336,'Мелко нашинковать луковицу, обжарить с одной столовой ложкой масла, желательно сливочного, всыпать кусочки вешенки, прожарить все вместе минут 5, чуть присолить. Порезать спаржу под углом на длинные кусочки, проварить минуты 3 в подсоленной воде, откинуть на дуршлаг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12336,'Разогреть в сковороде столовую ложку сливочного масла, всыпать кубики ветчины, жарить пару минут, добавить обсушенную спаржу, горошек, влить сливки, все вместе варить 3 минуты. К смеси добавить обжаренные грибы, дать прокипеть пару минут. Убрать с плиты, положить половинки черри.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12336,'Сварить пасту, согласно описанию на упаковке, отцедить, оставить чашку для разбавления соуса. Переложить в соус, осторожно перемешать. Если сливочные мафальдине с вешенками, спаржей и ветчиной получились чрезмерно густыми, то добавить оставленный отвар от пасты. Присыпать блюдо стружкой пармезана и мелко нарезанной петрушкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12337,'Сварить курица и овощи, хорошо остудить. Обжарить мелко порезанные грибы с кубиками лука. Очистить яблоко, удалить сердцевину, натереть на терке. По отдельности натереть картофель, огурец, морковь, сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12337,'Собрать салат «Старый мельник» с шампиньонами в следующем порядке: грибы и лук, картофель, майонез, курица, треть сыра, огурец, морковь, яблоко, майонез. Верх салата посыпать остатками тертого сыра, убрать на пару часов в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12338,'Огурцы разрезать вдоль на несколько частей, надрезать каждую сосиску вдоль, но не до конца. Пласт теста раскатать до 5 мм, порезать на полосы примерно по 2 см шириной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12338,'Вложить по паре кусочков огурца в надрез на сосиске, завернуть в тонкую пластинку сыра и все аккуратно обмотать  полоской теста.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12338,'Смазать каждую сосиску с корнишонами в слойке яйцом, присыпать семенем кунжута, печь в духовке, прогретой до 200 градусов до полной готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12339,'Отделить белки от желтков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12339,'Размешать желтки, добавить молоко и масло, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12339,'Взбить белки до пышной пены. Продолжая взбивать добавить постепенно сахар.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12339,'В белки добавить просеянную муку, какао и разрыхлитель, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12339,'Влить желтковую смесь, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12339,'Вылить готовое тесто в форму (у меня форма 18 см).
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12340,'Бисквит разрезать на части. Растереть в крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12340,'Взбить сгущенное молоко с мягким сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12340,'Добавить в крошку крем, так чтобы можно было придавать форму (у меня ушло 3 ст.л.)',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12340,'Сформировать из массы фигурки. Убрать в холодильник минут на 5-10.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12340,'Шоколад нарезать и растопить в микроволновке или на водяной бане.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12340,'В растопленный шоколад окунуть палочку и вставить в фигурку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12340,'Обмакнуть фигурки в шоколад, излишки стряхнуть.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12340,'Украсить рисунком из шоколада.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12341,'Для приготовления теста поставить опару, растворив в теплом молоке дрожжи с сахаром, очень хорошо перемешать, дать постоять 5-7 минут. Перелить в большую емкость, вбить яйцо, влить сметану с кефиром, подсолить, замесить тягучее тесто, постепенно вмешивая муку, прикрыть тканью, убрать в тепло часа на полтора.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12341,'Из фарша с обжаренным луком приготовить мясную начинку, приправить перцем, подсолить, добавить чуть воды, очень хорошо вымешать. Приготовить из толченого со сливочным маслом картофеля и сыра с добавлением перца и соли вторую начинку. Созревшее тесто обмять, слегка смазать руки подсолнечным маслом, вымесить тесто с небольшим добавлением муки, разделить на 3 равных колобка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12341,'Растянуть кусочек теста в лепешку, уложить по центру начинку (довольно большое количество) из мяса. Осторожно края теста подтянуть к центру, притрусить мукой, осторожно придавить ладонью, для равномерного распределения начинки по всему пирогу. В идеале надо получить лепешку в диаметре примерно около 35 см. Повторить операцию для пирога с начинкой из картофеля. По центру каждого пирога проделать небольшое отверстие для выхода при выпечке пара.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12341,'Начинать печь осетинские пироги с мясом, с картофелем и сулугуни 5 минут на нижней полке духовки с температурой в 180 градусов. Затем переставить противень на среднюю полку и выпекать еще треть часа. Достать пироги, смазать (щедро) верхушки сливочным маслом, положить в стопку, разрезать все сразу, подать горячими.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12342,'Фрукты помыть, разрезать пополам, вынуть косточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12342,'Переложить в емкость, всыпать сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12342,'Оставить для настаивания на ночь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12342,'Плоды должны дать сок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12342,'Поставить на огонь, варить пять минут, помешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12342,'Разлить в банки и закатать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12343,'Абрикосы и апельсины вымыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12343,'Из абрикосов достать косточки, засыпать сахарным песком, оставить на ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12343,'Апельсины пропустить через мясорубку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12343,'Перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12343,'Варенье довести до кипения, огонь убавить, варить пять минут, помешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12343,'Варенье остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12343,'Процесс повторить еще два раза.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12343,'Горячую массу разлить в банки и закатать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12344,'Фрукты перебрать, вымыть, разрезать пополам, удалить косточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12344,'Плоды нарезать дольками, выложить в чашу мультиварки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12344,'Влить лимонный сок, всыпать сахарный песок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12344,'Выставить режим «Тушение» на 50 – 60 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12344,'Варенье помешивать сначала периодически, затем – постоянно.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12344,'Не допустить пригорания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12344,'Разложить в банки, закатать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12345,'Фрукты небольшого размера вымыть, обсушить на полотенце.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12345,'Сделать надрезы, удалить косточки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12345,'В таз налить воду, всыпать сахарный песок, довести до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12345,'Плоды выложить в сироп, подержать под крышкой около одиннадцати часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12345,'Довести варенье до кипения, варить 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12345,'Огонь погасить, продукт оставить для настаивания еще на одиннадцать часов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12345,'Весь процесс повторить несколько раз.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12345,'Образующуюся пену снимать ложкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12345,'Готовое варенье переложить в стерильные банки, закатать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12346,'Взбить яйцо и растопленное сливочное масло, добавить растворенные в теплой воде дрожжи, постепенно вмешать по частям муку, оставить полученное тесто на пару часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12346,'Из слегка обжаренных и измельченных орехов с добавлением сахара, кардамона и корицы приготовить начинку. Созревшее тесто поделить на 2 части и каждую раскатать: одну до толщины 2 мм, другую – 3 мм.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12346,'Подготовить противень, промазать маслом, выложить трехмиллиметровый пласт теста, положить на него слоем в 4 мм начинку из орехов с пряностями, прикрыть вторым пластом, края обоих защипать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12346,'Дать 10 минут постоять, промазать верх взболтанным желтком, разметить ножом на небольшие одинаковые ромбы. Поставить десерт в заранее прогретую чуть выше 200 градусов духовку, печь около трети часа или чуть больше.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12346,'Достать противень с готовой армянской пахлавой с орехами, полить верх медом. Дать постоять, чтобы пропитались все слои вместе с начинкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12347,'Сварить сироп из сахарного песка, воды, лимонного сока. Огонь – минимальный.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12347,'Снять с огня.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12347,'Абрикосы вымыть и обсушить, вынуть косточки, разбить, достать ядрышки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12347,'Половинки абрикосов переложить в кастрюлю, влить горячий сироп.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12347,'Смесь поставить на огонь, довести до кипения, пену снять.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12347,'Время варки: от пяти до семи минут. Снять с плиты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12347,'Дать варенью постоять, время: от десяти до двенадцати часов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12347,'Готовый продукт разлить в банки, закатать, остудить в перевернутом виде.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12348,'Фрукты промыть и просушить, разрезать на дольки, удалить косточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12348,'Плоды пересыпать сахарным песком, оставить для настаивания на двенадцать часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12348,'Довести варенье до кипения на плите, варить пять минут, убрать с огня, охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12348,'Повторить процесс три раза с промежутком в пять часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12348,'Варенье остудить, разлить в стерильные банки, перевернуть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12349,'Вымыть фрукты, разрезать на дольки, вынуть и выбросить косточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12349,'Сложить плоды в чашу мультиварки, всыпать сахар, влить лимонный сок, оставить на два часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12349,'Миндальные орехи залить кипящей водой, оставить на пятнадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12349,'Снять шелуху, добавить ядрышки в варенье.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12349,'Выставить режим «Тушение» на час, готовить при закрытой крышке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12349,'Варенье можно сделать более густым, если выставить режим «Выпечка», крышку оставить открытой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12349,'В конце приготовления влить несколько столовых ложек водки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12349,'Готовое варенье разлить в банки, закатать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12350,'Ягоды перебрать, отделить мусор.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12350,'Четверть ягод размять толкушкой до состояния пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12350,'Добавить остальные ягоды и сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12350,'Емкость с вареньем поместить на тихий огонь, варить пять минут, пенку удалять.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12350,'Массу остудить, расфасовать в банки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12351,'Чернику промыть, засыпать сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12351,'Довести воду до кипения, добавить чернику.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12351,'Поварить пятнадцать минут, всыпать остатки сахара, варить до загустения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12351,'Желатин залить небольшим количеством воды, дать постоять.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12351,'Ввести в варенье, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12352,'Присолить стейки, поперчить, переложить на противень, побрызгать лимонным соком, присыпать сырной стружкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12352,'Запекать стейк семги под сыром в духовке четверть часа с температурой 200 градусов. Подать с соусом из тертых соленых огурцов с добавлением чеснока, майонеза и соевого соуса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12353,'Ягоды промыть, удалить мусор.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12353,'Банки и крышки стерилизовать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12353,'Разложить продукт в банки, поставить в большую кастрюлю с водой, накрыть крышками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12353,'Прогревать на тихом огне полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12353,'По мере выпаривания жидкости ягоды добавлять.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12353,'Через час огонь погасить, банки закатать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12354,'Шпинат промыть, нарезать мелко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12354,'Разогреть сковороду с 2 ст.л. масла.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12354,'Натереть сыр на мелкой терке.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12354,'Рабочую поверхность присыпать мукой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12354,'Выложить начинку на круг из теста, накрыть вторым кружочком, закрепить края вилкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12354,'Выложить на противень. Взбить яйцо и смазать им поверхность пирожков.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12355,'Грибы нарезаю пластинами, лук нарезааю кубиками и обжариваю вместе грибы и лук до полного исчезновения жидкости которая выделяется при жарке грибов.','https://vkuso.ru/data/cache/data/ff/d17f5ba85c1beff_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12355,'Куриное филе отвариваю, охлаждаю и нарезаю не большими кубиками.','https://vkuso.ru/data/cache/data/e3/fdb81e4f06d8be3_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12355,'Перец сладкий нарезаю соломкой, так же нарезаю огурец.','https://vkuso.ru/data/cache/data/a0/31739caa6092fa0_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12355,'Нарезаю зеленый лук, петрушку, все ингредиенты смешиваю с тонко нарезанной пекинской капустой, добавляю черный молотый перец, солю по вкусу и добавляю майонез, перемешиваю и сразу подаю к столу.','https://vkuso.ru/data/cache/data/cb/f128278976593cb_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12356,'Ягоды промыть и откинуть на дуршлаг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12356,'Всыпать в кастрюлю, размять толкушкой до появления сока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12356,'Прогреть, ввести мед небольшими порциями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12356,'Варить полчаса, пенку снимать, массу помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12356,'Варенье снять с огня, влить ром и расфасовать готовый продукт в банки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12357,'Белую черешню промыть, удалить веточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12357,'Вынуть косточки при помощи специального приспособления.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12357,'Налить немного воды в кастрюлю, всыпать ягоды и сахарный песок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12357,'Варенье поставить на плиту, довести массу до кипения на среднем огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12357,'Огонь убавить до минимальной величины, варить две минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12357,'Варенье остудить, процесс повторить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12357,'Разлить в банки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12358,'Всыпать в кастрюлю сахар, добавить апельсиновый сок и тонко нарезанную цедру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12358,'Смесь довести до кипения, помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12358,'Черешню перебрать, добавить в сироп после того, как он закипит.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12358,'Огонь выключить, массу полностью остудить, довести до кипения еще раз.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12358,'Процесс повторить несколько раз, уварив продукт до необходимой густоты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12359,'Сахарный песок всыпать в кастрюлю с водой, варить на тихом огне до растворения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12359,'Черешню вымыть, положить в сироп, продолжать варить, пенку снимать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12359,'Довести до кипения, огонь погасить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12359,'Оставить массу на сутки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12359,'Цитрус вымыть, обсушить, нарезать небольшими кусочками вместе с цедрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12359,'Добавить в основную массу, варить пять минут, дать постоять в течение суток.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12359,'Прокипятить варенье еще пятнадцать минут, разлить варенье в банки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12360,'Ягоды промыть, вынуть косточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12360,'Грецкие орехи нарезать небольшими кусочками. Поместить внутрь черешен.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12360,'Приготовить сахарный сироп, довести до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12360,'Залить черешню, оставить на несколько часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12360,'Варенье поставить на средний огонь, прогревать до густоты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12360,'Готовый продукт расфасовать в банки, закатать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12361,'Мелко нашинковать луковицу, обжарить, переложить в миску с творогом и яйцом, хорошо перемешать, можно комбайном.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12361,'Объединить с куриным фаршем, перемешать, сдобрить свежемолотым перчиком, мускатным орехом, подсолить, дать постоять. По вкусу можно добавить еще мелко порубленную зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12361,'Вылепить домашние котлеты из куриного фарша с творогом, панировать не нужно, обжарить на хорошо прогретом подсолнечном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12362,'Налить в кастрюлю воду, развести сахар, сварить сироп.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12362,'Погрузить ягоды, варить до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12362,'Далее прогревать еще полчаса, масса должна загустеть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12362,'Пену снимать деревянной ложкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12362,'Варенье закатать в банки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12363,'Грудку нарезать на кусочки, посолить и поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12363,'Кусочки курицы обернуть беконом и заколоть шпажками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12363,'Рулетики обжарить на оливковом масло до золотистого цвета с двух сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12363,'Выдавить сок апельсина и натереть цедру. Чеснок пропустить через пресс, выложить оливки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12363,'Ставим в духовку на 15 минут при температуре 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12364,'Для начала оставьте бананы замораживаться на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12364,'Когда бананы полностью заморозятся, взблендерить их со сливками, добавляя по частям.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12364,'Мусс готов! Есть его нужно сразу, потом будет уже не то. Приятного аппетита!!!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12365,'Взбиваем яйца с сахаром и постепенно вводим масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12365,'Смешиваем муку с разрыхлителем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12365,'Вводим муку в жидкую составляющую.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12365,'Добавляем изюм, цедру апельсина и тыкву, нарезанную кубиком. Перемешиваем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12365,'Отправляем выпекать на 180 градусов примерно на 30 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12366,'В блендере взбить базилик, кинзу и молоко. Потом добавить два яйца и ещё раз взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12366,'Теперь можно разогреть масло в сковородке и залить готовую массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12366,'Когда омлет схватиться можно выкладывать на одну половину сыр моцарелла, томаты, орехи, авокадо и накрыть второй.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12367,'Порезать батон на кусочки примерно сантиметровой толщины, поджарить обе стороны, слегка натереть кашицей из чеснока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12367,'Натереть на мелкой терке сырую морковь и сыр, добавить майонез с небольшим количеством чеснока, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12367,'Выложить начинку на закусочные бутерброды с сырой морковью достаточно толстым слоем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12368,'Сахар взбить с парой яиц, кефиром и мягким маргарином, всыпать муку, влить уксус с содой, подсолить, добавить ваниль, перемешать. По густоте смесь будет похожа на тесто для оладий. Если есть, то для вкуса можно добавить орехи, изюм, цукаты или курагу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12368,'Выпекать простой кекс на кефире и маргарине необходимо при 190-200 градусах. Верх кекса оформить по вкусу: сахарной пудрой с какао, глазурью или орешками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12369,'Достать масло заранее из холодильника, растопить, добавить яйца, сгущенку и муку, влить сок лимона с содой, замесить тесто, разделать на три части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12369,'Одну часть смешать с какао, две других оставить светлым, из каждой выпечь по коржу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12369,'Еще горячие коржи промазать сметаной (лить на корж частями), взбитой с сахаром. Коржи сложить в стопку: белый-коричневый-белый.  Верх торта со сгущенным молоком и сметанным кремомукрасить стружкой или крошкой шоколада с ягодами, убрать на ночевку в холодильник. Но если уж очень неймется, то хоть пару часиков пусть постоит и можно пить чай.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12370,'Натираем на терке отваренную свеклу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12370,'Добавляем яйцо, соль, перец, нарезанный чеснок, перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12370,'Добавляем муку и замешиваем тесто на деруны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12370,'Столовой ложкой выкладываем деруны на раскалённую сковороду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12370,'Обжариваем деруны по несколько минут с каждой стороны.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12371,'Порезать овощи и крабовые палочки на небольшие кубики, сыр измельчить на терке с мелкими отверстиями. Яйца порубить, смешать с крабовыми палочками и майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12371,'Выложить на блюдо слоями: крабовые палочки и яйцо – огурцы – палочки – помидоры –сыр. Верх слоеного салата «Безумный» оформить по своему вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12372,'Растереть муку с маслом, добавить оставшиеся ингредиенты, вымешиваем тесто (должно быть мягким). Переложить в пластиковый пакет, оставить на столе в покое на час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12372,'Прогреть духовку чуть ниже 200 градусов, подготовить лист для выпечки, застелить пергаментом, чуть смазать маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12372,'Из теста скатать небольшие шарики, как средний грецкий орех, сжать между ладонная, уложить на лист, задвинуть в духовку. Рассыпчатое, мягкое медовое печенье будет готово через четверть часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12373,'Облепиху перебрать, удалить мусор, ягоды промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12373,'Ягоды шелковицы промыть, откинуть на дуршлаг.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12373,'Выложить на дно банки шелковицу, сверху – облепиха.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12373,'Залить кипятком, делать это нужно осторожно, чтобы емкость не лопнула.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12373,'Подержать ягоды под крышкой полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12373,'До начала приготовления ягоды можно наколоть иглой во избежание растрескивания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12373,'Воду слить, довести до кипения еще раз, всыпать сахар, перемешать, огонь убавить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12373,'Яблоки вымыть, разрезать на дольки, всыпать в банку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12373,'Залить сиропом, закатать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12373,'Компот перевернуть, закрыть одеялом до остывания.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12374,'Вишню и шелковицу перебрать, всыпать в банки, добавить лимонную кислоту и сахарный песок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12374,'Влить кипяток, закатать крышками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12374,'Банки перевернуть, укутать, оставить до остывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12375,'Ягоды промыть, удалить по половине плодоножки при помощи ножниц.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12375,'Откинуть на дуршлаг.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12375,'Отдельно приготовить сироп из кипящей воды и сахарного песка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12375,'Плоды выложить в банки, залить сиропом, поставить в кастрюлю большого размера, время пастеризации – двадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12376,'Протереть отварной картофель на терке с мелкими отверстиями, сдобрить солью и черным перцем,  для цвета можно добавить куркуму, перемешать. Взбить вручную яйца, порезать на брусочки твердый сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12385,'Плоды раздавить деревянной ложкой или пестиком, постепенно всыпать сахарный песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12385,'Массу прогреть до температуры семьдесят градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12376,'Смочить слегка руки водой, взять немного картофельного теста, сформовать  ладонями лепешку. Положить в центр брусочек сыра, тщательно залепить со всех сторон, «искупать» в яйце, обмакнуть в сухари, подрумянить аппетитные палочки из картофеля с сыром в хорошо прогретом масле, подавать горячими.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12377,'Удалить мусор, фрукты вымыть и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12377,'Удалить кожуру и косточки, разрезать на дольки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12377,'В кастрюлю налить воду, всыпать сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12377,'Сироп прогреть, варить три или четыре минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12377,'Добавить плоды, варенье довести до кипения, огонь уменьшить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12377,'Тушить пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12377,'Разлить горячее варенье в стерильные банки, остудить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12378,'Плоды вымыть и наколоть зубочисткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12378,'Залить кипятком на несколько минут, воду слить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12378,'Плоды ополоснуть холодной водой, обсушить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12378,'Приготовить сироп из сахара и воды.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12378,'Залить фрукты, варить пятнадцать минут на тихом огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12378,'Огонь прибавить, варенье должно закипеть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12378,'Пену удалить шумовкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12378,'Десерт варить еще пятнадцать минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12378,'Остудить в течение пяти или восьми часов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12378,'Варенье прогреть еще раз, довести до кипения, огонь уменьшить до тихого кипения.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12378,'Прогревать еще пятнадцать минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12378,'Процесс повторить пять раз.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12378,'Влить разведенную в воде лимонную кислоту, варенье кипятить несколько минут.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12378,'Десерт выложить в банки, остудить.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12379,'Плоды промыть и разрезать пополам, косточки убрать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12379,'Приготовить сироп из воды, сахарного песка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12379,'Абрикосы поместить в пластиковые контейнеры, залить сиропом на треть высоты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12379,'Фрукты накрыть крышкой и хранить в морозилке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12380,'Чернику перебрать и засыпать сахаром, дать постоять двенадцать часов в холодильнике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12380,'Поставить на плиту, отдельно развести желатин или желфикс.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12380,'Варенье кипятить пять минут, затем ввести желатин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12380,'Разлить в небольшие банки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12381,'Ягоды перебрать, промыть, удалить черенки, наколоть плоды зубочисткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12381,'Вишню пересыпать сахарным песком, оставить на два часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12381,'Довести до кипения, огонь убавить до минимума, варить пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12381,'Массу помешивать деревянной ложкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12381,'Быстро разлить в банки, закатать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12382,'Почистить отварные яйца, обрезать на треть высоты, осторожно вынуть желтки. Переложить их в блендер, добавить оставшиеся ингредиенты, смешать до однородности в достаточно густую массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12382,'Заполнить этой массой нижнюю часть белка (для устойчивости закругленную часть слегка подрезать), придать форму шарика, прикрыть оставшейся верхушкой белка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12382,'Из кусочков маслины сделать глазки, из морковки – клювы. Подавать оригинальную закуску «Цыплята из яиц» желательно сразу, иначе блюдо заветрится и будет смотреться не так красиво.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12383,'Ягоды хорошо промыть, удалить косточки, плоды сложить в кастрюлю.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12383,'Всыпать сахар, перемешать и оставить на пятнадцать минут до выделения сока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12383,'Поставить на плиту, довести до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12383,'Варить пять минут на тихом огне, настаивать полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12383,'Банки и крышки стерилизовать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12383,'Массу еще раз довести до кипения, процесс повторить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12383,'Десерт разлить в банки, закатать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12383,'Банки перевернуть и укутать одеялом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12384,'Приготовить сироп из сахара и воды, выставить режим «Пароварка» на пятнадцать минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12384,'Вишню перебрать, вынуть косточки, плоды всыпать в чашу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12384,'Выставить режим «Суп» на час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12384,'Варенье помешивать, пенку снимать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12384,'Десерт разлить в банки, закатать, перевернуть и укутать пледом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12385,'Ягоды перебрать, промыть, пересыпать в эмалированную емкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12386,'Ягоды промыть, высушить, поставить на огонь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12386,'Через три минуты ввести пектин и натуральный мед.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12386,'Довести до кипения, варить пять минут, огонь погасить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12386,'Влить ром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12386,'Готовый продукт разложить в небольшие банки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12387,'Желатин замочить в холодной воде для набухания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12387,'Приготовить сироп из воды и сахарного песка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12387,'Влить желатин, прогреть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12387,'Добавить сок из голубики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12387,'Готовый продукт процедить и разлить в банки небольшого размера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12388,'Подготовить лук и яблоки, порезать очень мелко, выложить в сковороду со сливочным маслом, жарить до мягкого состояния обоих продуктов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12388,'Объединить с фаршем, всыпать соль, перец, хорошо все смешать. Брать небольшими порциями, скатать с небольшим надавливанием в шарики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12388,'Разогреть в сковороде немного масла, обжарить фрикадельки из куриного фарша с яблоком до готовности, подать с любимым гарниром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12389,'Ягоды промыть, мусор убрать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12389,'Обсушить на бумажном полотенце.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12389,'Отдельно сварить сироп из воды и сахара.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12389,'Плоды переложить в сотейник, залить теплым сиропом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12389,'Дать постоять, затем отправить варенье на слабый огонь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12389,'Варить до упаривания, продукт помешивать ложкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12389,'Десерт остудить, разлить в банки, закатать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12390,'Ягоды перебрать, промыть, откинуть на дуршлаг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12390,'Пересыпать в кастрюлю, долить воду, всыпать сахарный песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12390,'Поставить варенье на средний огонь, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12390,'Пенку снимать по мере необходимости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12390,'Яблоки промыть, очистить от сердцевины и кожуры, нарезать кусочками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12390,'Добавить в основную массу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12390,'Варить в течение часа, помешивать, продукт должен загустеть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12390,'Банки и крышки стерилизовать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12390,'Разлить варенье и закатать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12391,'Плоды вымыть, снять кожуру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12391,'Мякоть нарезать кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12391,'Цедру измельчить при помощи блендера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12391,'Выложить продукты в кастрюлю, добавить воду, сахар.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12391,'Довести до кипения, огонь – средний, пенку снимать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12391,'Снять с огня, массу остудить и еще раз довести до кипения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12391,'Процесс повторить еще два раза.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12391,'Горячую массу разлить в банки, закрыть, поставить в прохладное темное место.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12392,'Фрукты вымыть, варить в воде до закипания, оставить на десять минут, снять, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12392,'Нарезать плоды на кружки, кожуру не снимать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12392,'Положить в кастрюлю, всыпать сахарный песок и влить воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12392,'Довести до кипения, помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12392,'Остудить, влить бренди.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12392,'Еще немного поварить, разлить в чистые банки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12393,'Фрукты промыть, варить в кастрюле целиком в течение десяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12393,'Остудить, нарезать ломтиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12393,'Переложить в кастрюлю, всыпать сахар, влить воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12393,'Варить до загустения на тихом огне, помешивать лопаткой или деревянной ложкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12393,'Горячий продукт разлить в банки, закатать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12394,'Измельчить на терке твердый сыр, отделить у всех яиц белки. Взбить белки, добавляя порциями сырную стружку, все сдобрить перцем и слегка присолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12394,'Взять массу ложкой, сформовать шарики и обвалять в муке, переложить в разогретое масло. Дождаться увеличения объема, вынуть из сковороды, дать подсохнуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12394,'Подать закуску из сыра «Французская» на подогретом большом блюде, верх присыпать измельченной зеленью петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12395,'С тыквы срезать толстую шкурку, крупно натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12395,'Молоко подогреть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12395,'Положить тыкву, посолить, проварить минут 5.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12395,'Крупу тщательно промыть, высыпать в кастрюлю, варить под крышкой около получаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12395,'Заполнить кашей горшочки, добавить в каждый по ложке масла.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12395,'Поместить молочную пшенную кашу с тыквой в духовку минут на 20-30, готовить на малом огне (150 градусов).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12396,'Пшенную крупу перебрать, промыть под проточной водой, высыпать в чашу мультиварки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12396,'Добавить остальные ингредиенты (масло оставить).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12396,'Выставить режим «Каша» или другой подобный, зависит от модели устройства, задать время – час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12396,'Дождаться сигнала окончания и добавить масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12396,'Дать постоять еще четверть часа, чтобы пшенная каша в мультиварке хорошо разопрела.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12397,'Крупу, которая не должна иметь прогорклого запаха, хорошо промыть в дуршлаке под струей воды, дать ей стечь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12397,'Довести до кипения в одной кастрюле воду, а в другой –подсоленное молоко с сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12397,'Начинать варить крупу в воде, когда она начнет разваливаться, пересыпать ее в дуршлаг, дать стечь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12397,'Переложить пшено в молоко, варить на малом огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12397,'Как только впитается всё молоко, разложить кусочки масла по поверхности, присыпать его сухофруктами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12397,'Держать пшенную кашу на молоке с любимыми сухофруктами еще минут семь-восемь под крышкой на плите.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12397,'Снять с огня, тепло укутать, дать постоять минут 30-40.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12398,'Подготовить и отварить курицу, порезать на куски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12398,'Сложить в кастрюлю, залить водой, добавить морковь с луком, проварить полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12398,'Взять литр процеженного бульона, вылить в кастрюлю, всыпать пшено, варить около трети часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12398,'Положить отварную курицу, нарезанную на маленькие кусочки, добавить масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12398,'Варить пшенную кашу с вареной курицей на воде ещё треть часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12398,'Снять с плиты, укутать чем-нибудь теплым, дать постоять примерно 20 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12399,'Влить в хлопья йогурт (можно кефир), соединить с бананово-черничным пюре, приготовленным в блендере, взбить еще раз все вместе, всыпать корицу, ванилин, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12399,'Разложить овсянку с черникой и бананом на завтрак по широким стаканам или креманкам, оформить кружочками банана и ягодками черники. Подать можно сразу, а можно, если есть время, дать застыть до состояния желе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12400,'Тщательно промыть пшено, чтобы стекала прозрачная вода.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12400,'Проварить около 5 минут при большом нагреве, после того как вода начнет кипеть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12400,'Аккуратно слить воду, влить молоко, подсолить, положить сахар, проварить пару минут на большом огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12400,'Положить в кастрюлю творог.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12400,'Варить пшенную кашу с творогом на молоке к завтраку еще пару-тройку минут при среднем нагреве.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12400,'Дать настояться минут 10-15 под крышкой, убрав с плиты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12401,'В дуршлаг высыпать перебранную крупу, под струей воды промыть до появления чистой воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12401,'Налить в кастрюлю воды довести до кипения, положить крупу, подсолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12401,'Когда появятся пенка, удалить ее.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12401,'Кашу помешивать, варить до исчезновение жидкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12401,'Влить молоко, по вкусу досолить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12401,'Варить рассыпчатую пшенную кашу на молоке и воде до почти полного исчезновения молока.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12401,'Закрыть крышкой, убрать с плиты, дать постоять.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12401,'Разложить кашу по тарелкам, добавить по кусочку масла.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12402,'Грибы отварить (минут 10).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12402,'Соус поставить на огонь, поварить минут 5-8. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12402,'Нарезать ветчину, лук, грибы, маслины. Натереть сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12402,'Рабочую поверхность присыпать мукой. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12402,'Смазать тесто соусом. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12402,'Выпекать в разогретой до 200 С духовке 18-20 мин.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12403,'Разогреть в мультиварке жир, выставить режим «Жарка».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12403,'Измельчить овощи, обжарить их 8 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12403,'Добавить тушенку, готовить 5-6 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12403,'Всыпать промытую крупу, приправить солью и специями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12403,'Готовить блюдо на режиме «Каша» полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12403,'Оставить кашу под крышкой ещё на 15 минут, чтобы она настоялась и впитала всю воду.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12404,'В теплой воде развести соль.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12404,'Затем взять одну часть теста сформировать ровный шар и раскатать в тонкий пласт толщиной 2 мм и смазать его жиром или маслом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12404,'Далее каждую “улитку” раскатать слегка скалкой в лепешку, толщиной в 2 см.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12405,'Порезать рыбу кубиками, слегка присолить и чуть обжарить с добавлением масла. Отварить спагетти, как написано на упаковке (разная мука — разное время варки) в подсоленной воде с небольшим добавлением масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12405,'Сыр измельчить в крупную крошку, используя блендер. Вылить все вино в сковороду, выпарить половину, пересыпать пармезан, размешать, налить сливки, добавить листики розмарина.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12405,'Дать смеси закипеть, варить до приобретения консистенции жидковатой сметаны. На большие прогретые тарелки выложить пасту, полить соусом, уложить сверху кусочки рыбы. Подавать спагетти с семгой под сливочно-сырным соусом пока блюдо горячее.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12406,'Распустить в сотейнике масло, влить молоко, подсолить, перемешать. Влить полученную смесь в просеянную и смешанную с разрыхлителем и сахаром муку, вымесить мягкое тесто, обернуть в пакет, убрать в холодильник (хватит часа).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12406,'Положить в дуршлаг ягоды (замороженные — разморозить), присыпать сахаром с корицей и крахмалом, который не даст вытекать соку, влить коньяк, осторожно, но тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12406,'Достать тесто, разделить на кусочки, достаточные по размеру для одного сочня пирожка. По центру каждого сочня поместить около чайной ложки вишневой начинки, очень хорошо залепить, чтобы пирожки остались после выпечки сочными.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12406,'Подготовить противень, разложить домашние пирожки с вишней и корицей, промазать верх каждому разболтанным яйцом, притрусить сахарной пудрой, печь минут 25 при температуре около 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12407,'Уложить в салатник с широким дном мелко порезанные маринованные грибы, положить на них обжаренные и остывшие кубики лука (предварительно дать стечь маслу), именно они придают грибам и всему салату особый вкус, промазать сметаной с майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12407,'Положить следующий слой из крупно натертого картофеля, сваренного в мундире, промазать такой же смесью. Далее уложить слой из такой же по размеру свежей тертой моркови, а на нее кубики вареного мяса, промазать соусом из сметаны и майонеза.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12407,'Прикрыть последним слоем из крупной стружки сыра. Верх салата с мясом «Белая ночь»  оформить дольками лимона и веточками зелени.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12408,'На тостовом хлебе нужно обрезать корки со всех сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12408,'При помощи скалки тостовый хлеб нужно приплюснуть, что бы он стал тоньше.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12408,'Яблоки чистим, и нарезаем на небольшие кубики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12408,'Банан чистим, и нарезаем на полукольца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12408,'В тарелку разбиваем 2 кур. яйца и добавляем 100 мл воды, все хорошо взбиваем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12408,'На подготовленный тостовый хлеб намазываем с одной стороны нутеллой, на нутеллу укладываем банан и яблоко, все заворачиваем и кроя зашипевшем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12408,'Каждую заготовку десерта макаем в смесь из кур. яиц и воды, и после этого обжариваем на сковороде до корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12409,'Очень тщательно, до прозрачной воды, промыть крупу под горячей проточной струей, а потом – под холодной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12409,'Засыпать ее в казанок, залить водой, дать закипеть при сильном нагреве.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12409,'Убавить огонь, томить кашу на малом огне около 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12409,'Периодически помешивать, а в конце подсолить, дать блюду настояться, закрыв крышкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12410,'Очистить и порезать на кубики тыкву, проварить около 8-10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12410,'Всыпать хорошо промытую пшенку, посолить, влить остатки молока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12410,'Когда молоко закипит, варить еще порядка 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12410,'Приправить кашу маслом, добавить сахар или мед, дать настояться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12411,'Порезать болгарский красный сладкий перец, репчатый лук и сыр на небольшие кубики, хлеб залить небольшим количеством воды. Разогреть в сковороде масло, порезать кабачки на тонкие полоски с помощью ножа для чистки картофеля и др. овощей, переложить в сковороду, жарить около 5 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12411,'Смешать яйца с готовым мясным фаршем и отжатым хлебом, добавить лук, приправить перцем, горчицей, тимьяном, солью, вымесить, как следует. Добавить к фаршу кубики «Феты» и перца, перемешать еще раз, поделить на две части одинаковые по объему.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12411,'Выстелить форму бумагой для выпечки, положить половину подготовленного фарша, разложить по его поверхности равномерным слоем пластинки обжаренного кабачка, накрыть второй половиной фарша. Включить для прогрева до 200 градусов духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12411,'Натереть крупно картофель, присолить, отжать выделившийся сок, выложить ровным слоем поверх фарша, слегка аккуратно придавить ладонью. Поставить форму с запеканкой из мясного фарша с начинкой из цуккини в разогретую духовку примерно на час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12412,'Перебрать сухофрукты, залить горячей водой, прокипятить пару-тройку минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12412,'Отвар перелить в кастрюлю, дать ему закипеть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12412,'Посолить, всыпать вымытую крупу, варить порядка 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12412,'Добавить порезанные сухофрукты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12412,'Готовить еще четверть часа, добавив сахар.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12412,'Отключить нагрев, кастрюлю прикрыть крышкой, настоять кашу 15-20 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12413,'Разложить промытую крупу по горшочком, залить кипятком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12413,'Морковку натереть, лук тонко нашинковать, приготовить на сливочном масле зажарку, лук должен стать лишь прозрачным, снять с плиты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12413,'Положить на крупу обжаренные овощи, залить небольшим количеством воды, можно чуть посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12413,'Поставить горшочки в холодную духовку, нагреть до 190 градусов, готовить порядка 40 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12413,'Дать постоять еще 20 минут в закрытой духовке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12414,'Залить водой и проварить около 10 минут промытую крупу, подсолить, добавить молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12414,'Когда жидкости станет меньше, положить творог, добавить сахар, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12414,'Держать кашу пару-тройку минут на слабом огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12415,'Мясо нарезать на кусочки, отварить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12415,'В небольшом количестве растительного масла обжарить пшено, залить его водой (надо на 1 часть крупы брать 3 части воды), сварить кашу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12415,'Морковку крупно натереть, лук порезать на кубики, обжарить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12415,'Добавить кусочки мяса, перемешать, посолить, поперчить, перемешать с кашей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12415,'Разложить смесь по горшочкам, в каждый добавить мускатный орех, тертый сыр и масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12415,'Готовить кашу в духовке, прогретой до 190 градусов, около 25 минут, закрыв крышками, а потом ещё 5-8 минут без них.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12415,'Минуты за 2 до окончания запекания присыпать нарубленной зеленью, подать к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12416,'Порезать на кубики помидоры и крабовые палочки яйца натереть кусочки, чипсы поломать на кусочки, сыр мелко натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12416,'Выложить порционный салат с чипсами и крабовыми палочками слоями, промазывая каждый майонезом: палочки – помидоры – яйца – чипсы – сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12417,'Очистить грибы, снять пленку со шляпок, ножки очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12417,'Порезать всё на маленькие кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12417,'Обжарить их на сливочном масле, тушить около четверти часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12417,'Влить в сковороду молоко, тушить еще минут 10.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12425,'Мягкий сыр натереть на крупной терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12417,'Перелить содержимое сковороды в кастрюлю, влить бульон, добавить муку, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12418,'Вымыть, очистить, нарезать на средние кубики картошку, отварить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12418,'За это время подготовить и нарезать грибы, обжарить их с добавлением лука на сливочном масле, посолить, поперчить, можно добавить щепотку молотой гвоздики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12418,'Грибную зажарку переложить к готовому картофелю, измельчить блендером до состояния пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12418,'Добавить сметану, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12418,'Дать крем-супу закипеть, убрать с плиты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12419,'Дать белым грибам набухнуть в кипятке 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12419,'Свежие грибы очистить и нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12419,'Лук тоже измельчить кубиками, у тимьяна оборвать листики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12419,'В сотейнике нагреть масло, приготовить из свежих грибов зажарку с луком и тимьяном.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12419,'В воду, где замачивались грибы, влить бульон, довести до кипения, проварить с размоченными грибами на малом огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12419,'Превратить с помощью блендера, добавив зажарку, в пюре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12419,'Добавить в крем-суп пару ложек сливок и лимонного сока.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12419,'Хорошо перемешать, довести ещё раз до кипения, дать немного постоять.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12420,'Овощи вымыть, очистить, нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12420,'Лук протушить с маслом, добавить морковь, перемешать, обжарить пару-тройку минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12420,'Добавить кубики картофеля, тушить еще около 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12420,'Долить в кастрюлю воды, варить до размягчения овощей, добавив лавровый лист.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12420,'За это время очистить и порезать грибы, тушить шампиньоны минут 6-7, жидкость должна испариться вся, посолить, поперчить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12420,'Из кастрюли с овощами убрать лавровый лист, блендером превратить содержимое в пюре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12420,'Добавить грибную обжарку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12420,'Влить сливки, хорошо перемешать, дать закипеть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12421,'Шампиньоны вымыть, очистить, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12421,'Положить в сотейник, обжарить с растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12421,'Добавить кубики картофеля, обжарить минут 5.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12421,'Залить водой, всё перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12421,'Варить суп до готовности, прикрыв крышкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12421,'Нарезать лук маленькими кубиками, положить в суп за 5 минут до его готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12421,'Содержимое сотейника измельчить блендером до состояния пюре.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12422,'Редис очистить от кожуры, потереть на терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12422,'Приготовить рассол: довести до кипения воду, всыпать соль, сахарный песок, молотый перец, влить растительное масло и уксус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12422,'Перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12422,'Залить дайкон, жидкость должна его полностью покрыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12422,'Положить гвоздику и острый красный перец.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12422,'Оставить для настаивания на четыре часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12422,'Отцедить жидкость через дуршлаг.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12423,'Очень хорошо растереть сахар с творогом, вбить яйца, тщательно перемешать, добавить муку с разрыхлителем, должно получиться тесто мягкой консистенции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12423,'Включить для прогрева до 180 градусов духовку. Разделить «отдохнувшее» тесто  на 16 одинаковых шариков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12423,'Выложить домашние сдобные булочки из творога на противень, выпекать треть часа или чуть больше.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12424,'Отварить и остудить куриное мясо, замороженный зеленый горошек, яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12424,'Дайкон очистить от кожуры, мякоть потереть, промыть проточной холодной водой, дать жидкости стечь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12424,'Натереть свежий огурец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12424,'Куриное филе и яйца нарезать кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12424,'Чтобы яйца нарезать аккуратно, нож лучше смочить в холодной воде.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12424,'Репчатый лук, очистить, нарезать полукольцами и обжарить на заранее разогретом растительном масле.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12424,'Все ингредиенты перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12424,'Приготовить заправку из сметаны, молотого черного перца.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12424,'Салат посолить по вкусу, заправить поперченной сметаной.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12425,'Дайкон почистить, мякоть натереть на крупной терке, соль – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12425,'Отварить и охладить куриное мясо, разобрать на волокна.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12425,'Для соуса соединить давленый чеснок, тертый имбирь, соль, итальянские травы, молотый мускатный орех, кардамон, лимонный сок, винный уксус, сливки или сметану.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12425,'Смесь оставить на несколько минут и заправить салат.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12425,'Посыпать рубленой зеленью петрушки, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12426,'Натереть на терке морковь и очищенный дайкон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12426,'Отварить куриное филе, разобрать на волокна.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12426,'Отварить куриные яйца, нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12426,'Нашинковать зеленый лук, зелень кинзы, петрушку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12426,'Соль и перец молотый – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12426,'Заправить салат майонезом или сметаной, хорошо перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12427,'Грибы нашинковать на пластинки, курицу нарезать на куски, все положить в глубокую сковороду с растопленным сливочным маслом и обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12427,'Смешать за это время натертый сыр, раздавленный чеснок, нашинкованную зелень петрушки, залить сливками, всыпать пару-тройку щепоток смеси прованских трав, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12427,'Слить из сковороды сок от тушения мяса и грибов (немного оставить), залить сливочно-сырную смесь. Тушить филе куриное с грибами и сливочно-сырном соусе минут 10-15 при слабом нагреве, дать чуть настояться и подать к столу с любым гарниром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12428,'Дайкон очистить и натереть на терке для моркови по-корейски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12428,'Потереть морковь и кислое яблоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12428,'Ингредиенты смешать, через пять или десять минут лишнюю жидкость отцедить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12428,'Это можно проделать при помощи дуршлага, продукты немного размять руками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12428,'Смесь посолить, заправить майонезом, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12428,'Готовый салат посыпать рубленым зеленым луком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12429,'Очистить яблоко, морковь и дайкон, натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12429,'Продукты перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12429,'Полить растительным маслом, винным уксусом, посолить и поперчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12429,'Еще раз перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12429,'Посыпать очищенными рублеными грецкими орехами, зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12430,'Натереть дайкон, морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12430,'Если есть лишняя жидкость – ее лучше отцедить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12430,'Натереть твердый сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12430,'Пропустить чеснок через пресс.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12430,'Продукты перемешать, посолить, поперчить, заправить майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12431,'Репчатый лук нарезать тонкими полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12431,'Морковь и дайкон натереть, зеленый салат – покрошить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12431,'Ингредиенты перемешать, полить оливковым маслом, лимонным соком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12431,'Посолить, перец – по вкусу, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12431,'Посыпать готовый салат рублеными грецкими орехами и кунжутом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12432,'Сырое филе нарезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12432,'Будет удобнее, если мясо перед этим на полчаса положить в морозильную камеру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12432,'Разогреть сковороду, налить растительное масло, выложить свинину, жарить до появления корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12432,'Отдельно обжарить лук до золотистого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12432,'Ингредиенты перемешать, посолить, поперчить, подлить столовый уксус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12432,'Перемешать и оставить для пропитывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12432,'Редьку дайкон очистить, нарезать ножом на маленькие кусочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12432,'Смешать с мясом, всыпать рубленую зелень.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12433,'Взбить пару яиц с сахаром блендером, но можно воспользоваться и венчиком. Растереть творог, чтобы не было комочков, чуть-чуть подсолить, добавить ванильный сахар, гашеную уксусом соду, всыпать муку, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12433,'Объединить полученную смесь с яйцами, тщательно перемешать до однородности, дать чуть постоять, прикрыв тканью, чтобы тесто не заветривалось. Притрусить  стол мукой раскатать колобок теста в пласт толщиной не более 0,5 см.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12433,'Вырезать печенье небольшими формочками, для быстроты можно нарезать по типу хвороста на полоски диском с зубчиками. Раскалить, желательно в чугунной емкости, масло, обжарить до готовности. Переложить постряпушки из творога к чаю на блюдо присыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12434,'Нарезать репчатый лук, жарить на растительном масле до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12484,'Готовый соус перелить в центр тарелки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12434,'Говядину или свинину отварить, покрошить кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12434,'Очистить и порубить грецкие орехи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12434,'Дайкон натереть на мелкой терке, лишний сок отжать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12434,'Ингредиенты перемешать, добавить давленый чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12434,'Соль – по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12434,'Заправить салат майонезом. Другой вариант – растительное масло и лимонный сок.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12435,'Слить жидкость от консервированных кальмаров, нарезать их полосками, сложить в миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12435,'Добавить йогурт или нежирную сметану, перец молотый и соль по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12435,'Авокадо очистить от косточки и кожуры, мякоть нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12435,'Свежие шампиньоны промыть проточной водой, порезать кусочками небольшого размера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12435,'Ингредиенты перемешать, заправить растительным маслом и винным уксусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12435,'Блюдо выложить листьями хорошо промытого зеленого салата, в центр выложить кальмаров, вокруг – авокадо и грибы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12436,'Отварить куриные яйца, остудить и очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12436,'Свежие грибы хорошо промыть, нарезать кусочками, жарить на сковороде с растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12436,'Кальмары отварить в кипящей воде в течение нескольких минут, подсолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12436,'Морепродукт остудить и нарезать тонкой соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12436,'Продукты сложить в салатницу и заправить майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12437,'Латук промыть, обсушить и порвать руками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12437,'Положить продукт в салатницу, полить маслом и лимонным соком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12437,'Свежий огурец и репчатый лук нарезать кольцами, выложить поверх латука.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12437,'Шампиньоны хорошо промыть, нарезать кусочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12437,'Филе кальмаров промыть в воде, нарезать кусочками среднего размера, запанировать в муке и жарить на сковороде в течение двух минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12437,'Выложить в салатницу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12437,'Залить заправкой из соевого соуса, растительного масла, лимонного сока.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12438,'Отварить шампиньоны в подсоленной воде, так же поступить с кальмарами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12438,'Продукты остудить и нашинковать соломкой, компоненты соединить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12438,'Натереть твердый сыр, измельчить грецкие орехи, раздавить прессом чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12438,'Добавить сметану и майонез, растереть до однородности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12438,'Заправить смесью салат, хорошо перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12439,'Слегка подогреть молоко, положить дрожжи, половину муки, перемешать, прикрыть тканью (предпочтение – льняной), поставить в тепло. Получаса (может чуть больше) должно хватить до увеличения объема опары примерно в два раза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12439,'Добавить к опаре сахар и мягкое масло, хорошо вымешать, вбить яйцо и еще раз хорошо перемешать. Всыпать остальную муку, размешать до однородного состояния, должно получиться тесто, которое не будет прилипать к рукам, убрать его примерно на час в тепло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12439,'Подготовить начинку для булочек для этого нагреть молоко, как только оно закипит всыпать толченый мак и сахар, проварить минут 10 при слабом нагреве.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12439,'Разделить «созревшее» тесто на 3 равные колобка, раскатать в не очень толстый пласт (до 3 мм), промазать его начинкой, скатать в трубочку, защипать края. Порезать полученный рулет на кусочки длиной по 3-4 см.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12439,'Переложить булочки на противень, застеленный бумагой для выпечки, раскладывать друг от друга со значительным зазором, прикрыть тканью, дать треть часа постоять, чтобы они хорошо поднялись.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12439,'Печь вкусные булочки из дрожжевого теста с маком в духовке с температурой в 180 градусов примерно полчаса, присыпать готовую выпечку сахаром и корицей.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12440,'Филе кальмара отварить в подсоленной воде, остудить, нарезать длинными кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12440,'То же самое проделать со свежими шампиньонами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12440,'Репчатый лук нарезать полукольцами, замочить на десять минут в холодной воде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12440,'Жидкость слить, лук промыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12440,'Сыр натереть на мелкой терке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12440,'Слить жидкость из-под кукурузы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12440,'Компоненты перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12440,'Заправить майонезом и посолить по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12441,'Сварить куриные яйца, очистить, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12441,'Измельчить консервированный ананас.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12441,'Филе кальмара отварить в подсоленной воде, нарезать мелкой соломкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12441,'Отварить креветки, очистить и разрезать пополам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12441,'Измельчить крабовые палочки и шампиньоны, порубить зелень петрушки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12441,'Ингредиенты соединить, заправить майонезом, посолить по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12442,'Шампиньоны вымыть, разрезать пополам, если они крупные, отварить в подсоленной воде в течение десяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12442,'Жидкость слить через дуршлаг, грибы остудить, нарезать небольшими кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12442,'Репчатый лук очистить, вымыть, нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12442,'Отварить в подсоленной воде кальмаров, нарезать соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12442,'Отварить куриные яйца, мелко нарезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12442,'Нарезать полукружочками оливки, огурец – мелкими кубиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12442,'Заправить смесью майонеза и лимонного сока.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12442,'Украсить зеленью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12443,'Нарезать мелкими кусочками консервированные кальмары, шампиньоны, крабовые палочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12443,'Отваренные яйца и твердый сыр натереть на терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12443,'Выложить салат на блюдо слоями: кальмары, шампиньоны, крабовые палочки, консервированная и отцеженная кукуруза, куриные яйца, сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12443,'Каждый слой промазывать майонезом, лучше делать сеточку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12444,'Шампиньоны отварить до готовности, нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12444,'То же самое проделать с кальмарами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12444,'Натереть твердый сыр, порубить очищенные грецкие орехи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12444,'Измельчить чеснок, добавить в майонез, перемешать и заправить салат.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12444,'Соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12445,'Порвать на куски листья салата, курятину и огурец порезать на кубики. Почистить от шкурки мясистые помидоры, разрезать, удалить семена и тоже порезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12445,'Протереть сыр, яйца разрезать пополам, все ингредиенты сложить в довольно глубокий салатник осторожно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12445,'Приправить салат с курицей «Свежесть» соусом по вашему вкусу, чуть поперчить (лучше прямо из мельнички) и присолить. Приятного аппетита!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12446,'Кальмары и шампиньоны отварить, нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12446,'Так же поступить с куриными яйцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12446,'Нарезать помидоры, натереть сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12446,'Для заправки можно использовать два варианта: майонез, перемешанный с рубленой зеленью петрушки, укропа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12446,'Второй – растительное масло с молотым перцем. Посолить по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12447,'Отварить грибы и кальмары, нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12447,'Нарезать репчатый лук, потереть твердый сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12447,'Компоненты перемешать и заправить сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12448,'Отварить курицу, нарезанные грибы обжарить с луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12448,'Отварить куриные яйца, белки и желтки натереть отдельно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12448,'Выложить продукты слоями: куриное мясо, грибы, ананасы, белки, желтки, маслины, нарезанные колечками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12448,'Ингредиенты промазывать майонезом, кроме ананасов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12448,'Готовый салат поставить в холод для пропитывания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12448,'Затем украсить чипсами в виде лепестков.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12449,'Нарезать кубиками свежие огурцы и ветчину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12449,'Открыть банки с горошком и кукурузой, жидкость слить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12449,'Отварить яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12449,'Продукты перемешать, заправить майонезом, посыпать сверху тертыми яйцами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12449,'Нанести сеточку из майонеза, в ячейки выложить половинки маслин.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12449,'Разложить чипсы по кругу в виде лепестков.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12449,'Дать салату пропитаться и подать к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12450,'Репчатый лук мелко нарезать и залить уксусом с сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12450,'Мясо срезать с куриного копченого окорочка, нарезать, заправить майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12450,'Выложить продукты в следующем порядке: курица, маринованный лук, сладкая кукуруза, майонез, раскрошенные белки, майонез, желтки, маслины.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12450,'Украсить в виде цветка подсолнуха: лепестки – чипсы, семечки – маслины.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12451,'Влить в чашу блендера молоко, вбить яйца, положить фарш, сдобрить молотым перцем, подсолить, влить масло, перемешать в однородную массу. Разогреть в сковороде немного масла, вылить смесь, прикрыть крышкой, уменьшить нагрев, обжарить с одной стороны и перевернуть на другую, жарить еще пару минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12451,'Пока есть время порезать шампиньоны и тоже обжарить, дать им остыть и переложить в объемную миску. Огурец и сыр нарезать тонкими брусочками, пересыпать к грибам, добавить мелко нашинкованный чеснок, горчицу, сметану, перемешать полученную начинку. Если есть ветчина, то можно и ее положить, но и без нее будет вкусно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12451,'По половине почти готового омлета  разложить равномерно начинку, осторожно поддеть вторую половинку омлета и прикрыть начинку. Теперь закрыть крышкой и прогреть бризоль из мясного фарша с шампиньонами около минуты, снять с плиты, осторожно переложить в тарелку присыпать порубленными перьями зеленого лука и петрушкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12452,'Отварить говядину, яйца, очистить грецкие орехи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12452,'Продукты измельчить, нарезать соленые огурцы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12452,'Выложить продукты слоями, каждый намазать майонезом и сделать сеточку из готовой столовой горчицы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12452,'Первый слой – мясной, второй – огуречный, третий – из тертых яиц, последний из обжаренных грецких орехов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12452,'Тарелку поставить в холод на полчаса, затем подать на стол.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12453,'Говяжье филе нарезать тонкими полосками и прожарить на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12453,'Измельчить перец чили.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12453,'Нарезать полосками огурцы, помидоры, болгарский перец и лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12453,'Продукты перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12453,'Заправить смесью соевого соуса и растительного масла.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12454,'Грибы нарезать и обжарить на растительном масле вместе с луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12454,'Нарезать кубиками отварную свинину, яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12454,'Натереть на терке отварную морковь, маринованные огурцы, сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12454,'Последовательность слоев: говядина, огурцы, тертая морковь, грибная обжарка, сыр, консервированный горошек, яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12454,'Все продукты промазывать майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12454,'Салат можно выложить в виде кольца, в центр поставить стакан, а затем его удалить. Украсить веточками укропа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12455,'Отварить куриное филе, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12455,'Замочить, а затем измельчить чернослив.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12455,'Порубить очищенные грецкие орехи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12455,'Перемешать орехи со сметаной и черносливом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12455,'Натереть отваренные яйца и морковь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12455,'Репчатый лук залить водой с уксусом на сорок минут, жидкость слить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12455,'Выложить продукты послойно: куриное мясо, маринованный лук, отваренная морковь, ореховая смесь, яйца.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12455,'Каждый слой промазать сметаной.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12455,'Курицу можно посолить по вкусу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12456,'Натереть слегка подмороженные плавленые сырки, следом остывшие вареные яйца, перемешать до однородного состояния. Сдобрить массу майонезом, черным перцем, рубленой зеленью укропа, слегка присолить, добавить мелко посеченный чеснок, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12456,'Перцы освободить от семенной коробки, начинить полученной массой, затем порезать на колечки. Подавать закуску из болгарского перца с сыром и яйцом с большим количеством рубленой зелени укропа и петрушки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12457,'Взбить вилкой в однородную массу пасту томатную, соль, сахар, залить порезанную на кусочки куриную грудку, дать постоять минимум треть часа. Обжарить в масле пластинки чеснока и кубики лука, всыпать мясо, жарить минут пять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12457,'Покрошить молодые кабачки (чистить не нужно) на кубики, переложить в кастрюлю с небольшим количеством воды, добавить мясо с чесноком и луком, кусочки грибов и фасоль, протушить рагу с куриной грудкой и белыми грибами примерно треть часа до полной готовности на среднем огне, присыпать порубленной зеленью с любимыми специями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12458,'Сложить печенье в пакет, прокатать скалкой до образования мелких крошек, смешать с размягченным маслом. Переложить смесь в подготовленную форму, разровнять и утрамбовать, определить на полчаса в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12458,'Вылить в миску сгущенку, добавить сметану, хорошо перемешать. Растопить разбухший желатин на водяной бане до полного растворения, соединить его со смесью сгущенки и сметаны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12458,'Залить все в форму с основанием из печенья и убрать на холод на пару-тройку часов до полного застывания. Во время застывания, в чизкейк из сгущенного молока без выпечки можно добавить ягодки клюквы, тертый шоколад и обжаренные измельченные орехи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12459,'Порезать бананы и киви на кружочки, хорошо перемешать банку сгущенки с густой сметаной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12459,'Промазать корж кремом, выложить на него слой кружочков банана, прикрыть другим коржом и т.д. пока коржи не закончатся.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12459,'Верх торта без выпечки «Тропиканка» украсить кусочками киви. Можно подавать к столу, но если есть немного времени, то лучше дать чуть постоять для пропитки коржей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12460,'Густую сметану взбить с добавлением сахара, положить в смесь кружки бананов. Вымочить в молоке (буквально несколько секунд) печенье. Взять подходящее плоское блюдо, выложить слой печенья, далее – слой сметаны с бананами, повторить все с остальным печеньем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12460,'Оформить верх стружкой шоколада, кусочками фруктов или присыпать дробленым жареным орехом. Дать торту из сахарного печенья с бананом постоять полчаса в холодильнике и подать к столу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12461,'Растапливаем сливочное масло с медом и добавляем соду, гашеную 2 ст.л. кипятка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12461,'Отдельно смешиваем все сухие ингредиенты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12461,'В сухие ингредиенты добавляем жидкую составляющую и перемешиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12461,'Формируем печенье руками или выкладываем ложкой, располагая на расстоянии друг от друга',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12461,'Отправляем в разогретую духовку на 180 градусов примерно на 10 минут. Печенье должно стать красивого красновато-золотистого цвета. При остывании оно твердеет и становится хрустящим и рассыпчатым.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12462,'Просеять в глубокую миску муку, положить дрожжи, размешать, добавить мягкое масло и свежую сметану, вымесить тесто, которое не будет прилипать к рукам. Смазать миску маслом, переложить в нее шар теста, прикрыть пленкой и оставить ночевать в холодильнике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12462,'Для начинки перемешать сахар, муку, масло, перетереть руками до получения маслянистой крошки, можно воспользоваться для этой цели блендером. Добавить в начинку дробленый грецкий орех и ванилин, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12462,'Достать тесто, поделить на две части, чуть присыпать стол мукой, раскатать одну часть в прямоугольный пласт, равномерно смазать его частью начинки, свернуть в трубочку. Полученный рулет порезать на 10 частей очень острым ножом. Со вторым куском теста поступить также.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12462,'Подготовить лист для выпечки, промазать маслом, переложить на него рулетики, смазать их разболтанным желтком. Выпекать армянский назук с ореховой начинкой около получаса в прогретой до 300 градусов духовке, достать и дать остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12463,'Начнём варить спагетти.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12463,'Тем временем начнём готовить соус. На разогретой масло на сковородке и раздавим чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12463,'После добавим анчоусы, оливки, каперсы, хлопья перца и перемешаем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12463,'И зальём томаты и по готовности спагетти добавим в соус. Можно ещё добавить кинзу и посыпать пармезаном.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12464,'Мясное филе обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12464,'Нарезать кубиками огурцы, отваренные морковь и картофель, колбасу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12464,'Натереть яблоко на крупной терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12464,'Салат посолить, заправить сметаной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12465,'Лук нарезать, залить водой с уксусом и сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12465,'Отварить картофель, морковь, яйца, натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12465,'Выложить на блюдо картофель, далее – консервированные сардины в масле, отцеженный от жидкости лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12465,'Далее – майонез, колбаса, слой моркови.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12465,'Сформовать мордочку щенка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12465,'Посыпать тертыми яйцами, голова – из раскрошенного желтка, уши – из белка. Язычок сделать из моркови, нос, усы, глаза – из маслин.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12466,'Отварить фрукты до мягкости, приготовить пюре, всыпать сахар, хорошо перемешать. Уварить на маленьком огне до густоты, переложить мармелад на плоское блюдо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12466,'Когда домашний мармелад из натуральных продуктов остынет, порезать его на кубики, обсыпать сахарной пудрой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12467,'Отварить свинину или говядину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12467,'Нарезать дольками помидоры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12467,'Измельчить бекон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12467,'Порвать руками листья зеленого салата.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12467,'Потереть или нарезать имбирь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12467,'Ингредиенты перемешать, заправить оливковым маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12468,'Нарезать полосками сыр, сырокопченую колбасу, огурцы, помидоры, яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12468,'Выложить на тарелку отдельными блоками, между ними – майонез.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12469,'Отварить язык, нарезать произвольными кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12469,'Залить лук водой с уксусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12469,'Обжарить брусочки картофеля на растительном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12469,'Порубить зелень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12469,'Продукты перемешать и заправить сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12470,'Куриное филе отварить и нарезать полосками, сыр «Фета» - кубиками, нашинковать пекинскую капусту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12470,'Измельчить помидоры и болгарский перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12470,'Приготовить заправку из горчицы, отваренных куриных желтков, растительного масла и кетчупа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12470,'Продукты соединить, добавить сухарики, заправить соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12471,'Куриное филе отварить до готовности в подсоленной воде, нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12471,'Отварить куриные яйца, отдельно натереть белки и желтки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12471,'Натереть сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12471,'Консервированные маслины разрезать пополам вдоль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12471,'Выкладывать салат слоями: отварное мясо, нарезанные консервированные шампиньоны, белки, желтки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12471,'Каждый слой промазать майонезом, соль – по вкусу и желанию.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12471,'Украсить салат половинками маслин, выложить чипсы в виде лепестков подсолнуха.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12472,'Просеять муку, взбить сахар и яйца в белую пену, всыпать муку, добавить соду (погасить сметаной), распущенное сливочное масло, сметану, очень хорошо перемешать (удобнее и быстрее миксером). Включить для прогрева до 200 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12472,'Массу разделить пополам, добавить в одну пару столовых ложек какао, а в другую — пару столовых ложек муки. Круглую форму смазать маслом, поочередно выливать в центр по столовой ложке белого и коричневого теста (перемешивать не надо).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12472,'Выпекать сладкий пирог на сметане «Зебра» в уже прогретой духовке около получаса. Если верх уже почти пропечется, а середина нет, то прикрыть форму фольгой и уменьшить нагрев до 180 градусов.  Можно есть просто так, а можно пропитать смесью сахара, сметаны и ванильным сахаром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12473,'Нарезать репчатый лук, заранее отваренную свеклу, свежую морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12473,'Нашинковать белокочанную капусту, нарезать соломкой колбасу, свежие огурцы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12473,'Порубить зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12473,'Картофель обжарить во фритюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12473,'Выложить ингредиенты на тарелку по кругу, соль и молотый перец – по вкусу и желанию.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12473,'В центр налить майонез, вокруг – рубленая зелень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12474,'Шиитаке замочить в теплой воде на 2-3 часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12474,'Креветки очистить от панциря, сделать надрез по центру и удалить коричневую "нить". 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12474,'Нарезать галангл, лемонграсс, чили перец, лук и грибы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12474,'В кипящий куриный бульон положить галангал, лемонграсс, чили перец, листья лайма, шиитаке.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12474,'Затем добавить креветки, лук и выжать сок половины лимона, варить 5 мин.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12474,'Влить кокосовое молоко, перемешать, дать повариться еще 5 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12474,'Подавать с нарубленной кинзой и рисом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12475,'Всыпать муку, предварительно ее просеяв, в достаточно глубокую миску, добавить соль, разрыхлитель и ванильный сахар, смесь тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12475,'Размешать сахар, мягкое масло и мелко порезанный банан (оставить немного кружочков для оформления), вбить яйца, влить молоко, хорошо перемешать, частями добавить муку, смешать до однородности  массы. Поместить полученную массу в мультиварку, запустить режим «Выпечка» минут на 50-60.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12475,'Готовый очень вкусный пирог с бананом в мультиварке выложить из чаши на просторное блюдо, оформить верх пирога кружками банана, стружкой шоколада или сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12476,'Измельчаем лук и маринуем его, добавив сахар и лимонный сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12476,'Готовим заправку: смешиваем майонез, сметану, измельченный чеснок, соль, паприку и горчицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12476,'Нарезаем по диагонали крабовые палочки, болгарский перец и помидоры (помидоры предварительно освобождаем от лишней жидкости и семян)',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12476,'Натираем на терке сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12476,'Смешиваем все ингредиенты и заправляем салат.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12476,'Готовим чипс: смешиваем масло, воду и муку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12476,'На раскаленную сковороду вливаем частями тесто для чипса и ждем, когда жидкость испарится.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12476,'Подаем салат порционно, украшая перцем и приготовленным чипсом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12477,'Порезать курятину соломкой, у мясистых помидоров удалить семена и шкурку, порезать такой же соломкой, отжать морковку от маринада. Разрезать луковицу пополам, нашинковать на полукольца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12477,'Все смешать, приправить майонезом, переложить салат с морковью по-корейски и копченым окороком в салатник, присыпать верх зеленью укропа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12478,'Начнём отваривать спагетти и тем временем начнём в отдельной посуде начнём натирать сыр и добавим перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12478,'По готовности спагетти переложим их к сыр и добавим немного воды из кастрюли. Нужно тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12479,'В чашу блендера кладу отварное куриное мясо и чеснок, перебиваю.','https://vkuso.ru/data/cache/data/b1/41685db4ee0ffb1_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12479,'Затем добавляю мягкое сливочное масло ( не маргарин!!!) перец, соль и еще раз хорошо перебиваю блендером до однородной конститенции.','https://vkuso.ru/data/cache/data/87/7e378173a233887_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12480,'Печенье и орехи измельчаем любым удобным способом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12480,'Шоколад растапливаем вместе со сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12480,'Смешиваем орехи и печенье с растопленным с маслом шоколадом, добавляем коньяк (по желанию).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12480,'Массу выкладываем на фольгу в виде прямоугольника, в небольшое углубление вкладываем банан.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12480,'Поднимаем края фольги и сворачиваем, помогая руками, придавая треугольную форму.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12480,'Помещаем в холодильник на 2 часа. Затем разворачиваем, посыпаем кокосовой стружкой и разрезаем на отдельные пирожные.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12481,'Полукопченую колбасу и свежую белокочанную капусту, отваренную свеклу измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12481,'Ингредиенты выложить горками на блюдо, включая морковь по-корейски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12481,'В центр налить майонез.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12481,'Чтобы соус не растекался, его можно обложить чипсами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12481,'Отдельная горка – сами чипсы, любые и в любом количестве.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12482,'Перемешать с фаршем пропущенный через пресс чеснок, мелко порубленный лук и базилик, измельченную цедру лимона. Влить в смесь сок лимона, всыпать крошки хлеба, приправить солью и перцем, очень хорошо все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12482,'Увлажнить водой руки, скатать из фарша колбаски, обмакнуть их в муку, а затем обжарить в хорошо прогретом масле со всех сторон. Перед подачей дать аппетитным палочкам из куриного фарша полежать на бумажном полотенце для впитывания остатков масла. Блюдо хорошо дополнит томатный соус или кетчуп.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12483,'Свежую морковь очистить и натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12483,'Порвать листья зеленого салата руками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12483,'Крабовые палочки нарезать брусками или ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12483,'В центр большой тарелки налить майонез.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12483,'Продукты разложить горками, блюдо украсить веточками укропа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12484,'Краснокочанную капусту нашинковать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12484,'Натереть морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12484,'Сладкий болгарский перец, свежие огурцы, отваренную говядину нарезать брусками или небольшими ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12484,'Выложить продукты на тарелку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12484,'Взбить при помощи блендера сметану с очищенными грецкими орехами, кунжутом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12484,'Должна получиться однородная масса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12484,'Соль – по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12485,'Курицу отварить в подсоленной воде с лавровым листом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12485,'Филе охладить и нарезать брусками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12485,'Белокочанную капусту нашинковать, помять руками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12485,'Отваренную свеклу очистить, порезать тонкой соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12485,'Яблоко очистить, удалить сердцевину, нарезать соломкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12485,'Продукт полить лимонным соком, чтобы не почернел.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12485,'Ингредиенты выложить по краям, в центре – мясо, политое майонезом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12486,'Залить кипятком чернослив, оставить на десять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12486,'Размягченные плоды порезать тонкой соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12486,'Отварить куриное мясо с солью и специями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12486,'Филе остудить, измельчить кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12486,'Натереть морковь и твердый сыр, ячейки – крупные или средние.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12486,'Налить майонез на середину тарелки, вокруг выложить нарезанные ингредиенты горками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12487,'Сладкие болгарские перцы вымыть, удалить семенные камеры, мякоть нарезать тонкой соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12487,'Нарезать пекинскую капусту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12487,'Нарезать дольками томаты, ветчину и свежие огурцы также соломкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12487,'Выложить продукты по кругу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12487,'Свежую зелень порубить, соединить со сметаной и майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12487,'Соус вылить в центр тарелки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12488,'Нарезать морковку и картофель на одинаковые кубики, сварить в отдельной посуде, отварить зеленый горошек. Все овощи варить в подсоленной воде, а готовые сразу отбросить на сито и остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12488,'Яйца проварить после закипания 10 минут, переложить в холодную воду,  дать хорошо остыть, а затем почистить. Если у яблока плотная и жесткая шкурка, то ее лучше удалить, а плоды порезать на маленькие кубики и во избежание потемнения — побрызгать',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12488,'Приготовить из сметаны, горчицы, майонеза, перца и соли соус, вылить к яблочно-овощной смеси, размешать. Залить бульоном желатин, подогреть, но не до закипания, а только до «распускания» желатина, дать раствору полностью остыть, соединить с салатом, осторожно и тщательно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12488,'Выстелить глубокую форму полностью пленкой (края должны свисать), распределить ровным слоем половину салата. Уложить на него в один ряд целые яйца, а поверх — вторую половину салата, завернуть края пленки внутрь формы. Утрамбовать легким постукиванием дна формы по столу, чтобы в салате не осталось пустот, отправить ночевать в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12488,'Достать форму, отогнуть края пленки, прикрыть блюдом, быстро, но осторожно перевернуть, удалить пленку, верх салата-желе с ветчиной, яйцом и овощами оформить кусочками болгарского перца и веточками петрушки по своему вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12489,'Приготовить маринад из лимонного сока, рубленой зелени, соли, сахарного песка, свежей зелени.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12489,'Лук-шалот нарезать полукольцами, положить его в мисочку с маринадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12489,'Разрезать гранат пополам, вынуть семена.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12489,'Нашинковать свежую белокочанную капусту, нарезать соломкой балык и вареную свеклу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12489,'Продукты выложить на блюдо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12489,'Майонез подать отдельно.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12490,'Очистить киви, аккуратно нарезать кружками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12490,'Очистить и разобрать мандарины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12490,'Апельсины хорошо вымыть и нарезать кружками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12490,'Выложить продукты на тарелку в произвольном порядке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12490,'Можно добавить небольшие кисточки винограда, белого или черного.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12490,'Заправка не требуется.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12491,'Зеленый лук и петрушку - нарезать. Чеснок нарезать тонкими пластинками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12491,'В глубокой сковороде разогреть оливковое масло и отправить туда чеснок и зеленый лук. Обжаривать 2 минуты на среднем огне - перемешивая. Добавить креветки и обжаривать еще 2 минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12491,'Выдавить лимонный сок, добавить листья веточки базилики, сметану, петрушку - перемешать.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12491,'В сковородку натереть сыр и добавить горячие спагетти, тщательно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12492,'Распустить сливочное масло или маргарин при слабом нагреве. За это врем взбить в миксере сахар и яйца, влить  масло, еще раз взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12492,'Смешать небольшое количество муки с яично-масляной смеси, влить гашеную (лимонным соком или уксусом) соду, перемешать. Всыпать по частям остальную муку, вымесить такое тесто, чтобы оно не липло к рукам, отрезать небольшую часть, обернуть в пленку и положить в морозилку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12492,'Оставшееся тесто переложить на противень, придавить руками и растянуть в пласт толщиной примерно в полсантиметра, убрать на полчаса в холодильник, включить для прогрева до 180 градусов духовой шкаф. Достать противень, промазать верх теста густым вареньем или джемом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12492,'Натереть малую часть теста, присыпать полученной стружкой слой из варенья, задвинуть противень в прогретый духовой шкаф на треть часа, чтобы печенье успело подрумяниться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12492,'Вынуть противень, дать коржу постоять минут 10, нарезать его острым ножом на прямоугольники, когда печенье с джемом «Гость на пороге» полностью остынет переложить его на блюдо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12493,'Кастрюлю залить водой и положить в нее морковь, картофель, очищенный от кожицы кабачок, мякоть тыквы. Можно крупно нарезанные, а можно целиком, но тогда придется варить дольше. Содержимое кастрюли довести до кипения и варить 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12493,'В чашу блендера сложить отваренные овощи - измельчить. Выложить в отдельную кастрюльку и разбавить бульоном в котором варились овощи до нужной консистенции, посолить и поперчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12493,'Ветчину (или заменить её на куриный рулет) нарезать соломкой. Лук - кубиками. Сложить все в сковороду и обжаривать 10 минут на среднем огне - перемешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12493,'Содержимое сковороды высыпать в кастрюлю с супом, добавить сметану - перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12494,'Удаляем кости и внутренности скумбрии разрезав по хребту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12494,'Кабачок, баклажан, болгарский перец, картофель режем кубиками и обжариваем на растительном масле 20 минут, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12494,'Режем кубиками помидор и добавляем в сковороду, жарим еще 10 минут, перемешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12494,'На фольгу выкладываем скумбрию, солим и добавляем внутрь овощную смесь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12494,'Запекаем 40 минут при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12495,'Курицу нарезать крупными кусочками, базилик (5 гр) мелко нарезать. На растительном масле обжарить 7 минут, перемешивая, добавив соль, перец и орегано (сушеный).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12495,'В отдельной сковородке обжарить помидорки черри разрезанный на пополам и чеснок пропущенный через пресс, 5 минут, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12495,'Помидоры соединить с курицей и добавить отваренные спагетти, добавить немного воды в которой варились спагетти.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12495,'Мелко нарезать оставшийся базилик, потереть сыр и перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12496,'Шампиньоны разрезать пополам и нарезать тонкими пластинками. Болгарский перец нарезать крупными квадратиками. Лук нарезать тонкими полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12496,'На растительном масле обжарить грибы на сильном огне 3 минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12496,'Добавить перец и обжарить 3 минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12496,'Добавить лук и чеснок через пресс, готовить на среднем огне 10 минут, перемешивая.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12496,'Влить соевый соус, мелко нарезанный укроп, добавить отваренные макароны, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12497,'Яйцо смешать с ванилином. Добавить сахарную пудру и растопленное сливочное масло - перемешать. Влить молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12497,'Муку перемешать с разрыхлителем и просеять к яичной смеси - замесить, а потом положить на 1 час в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12497,'Раскатать тесто и вырезать пончики. Выпекаем в разогретой духовке при 180 градусах 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12497,'Готовим глазурь. Белки взбить до устойчивой пены и добавить сахарную пудру продолжая взбивать, выжать лимонный сок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12497,'Остывшие пончики макаем в глазурь',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12498,'В 2 литрах воды отварить курицу с лаврушкой. (10 минут в кипящей воде).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12498,'Крупно нарезать морковь, лук и картофель, добавить к курице. Варить 20 минут в кипящей воде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12498,'В чашу блендера сложить все овощи, курицу (отделить от костей), сыр плавленный. Измельчить.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12499,'Шампиньоны тонко нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12499,'Кусочки курицы посолить и поперчить, обжарить на растительном масле 10 минут (на сильном огне).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12499,'В отдельной сковороде прокалить муку (обжарить до золотистого цвета). Добавить сливочное масло, перемешать, влить молоко и сливки, перемешать. Добавить грибы и готовить 15 минут на среднем огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12500,'Сахар (150 гр) залить водой и поставить на огонь, пока сахар не растворится.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12500,'Апельсин нарезать колечками, удалить косточки. Добавит в сироп и варить 15 минут на медленном огне. Края апельсинов НЕ выкидывать!',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12500,'Форму застелить пекарской бумагой. Выложить дольки апельсина.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12500,'Натереть цедру со срезанных краев апельсинов, вбить яйца - перемешать.Добавить сахар (30 гр), кефир, растопленное сливочное масло - перемешать.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12500,'Этим тестом залить апельсины и поставить в духовку на 30 минут при температуре 160 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12500,'Вынимаем пирог из формы, апельсинами вверх. Снимаем бумагу и поливаем сиропом в котором варились апельсины.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12501,'Разбираем брокколи на соцветия',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12501,'Бланшируем капусту в кипящей воде не более 3 минут и сразу опускаем в холодную воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12501,'Готовим заливку: смешиваем яйца с молоком, сливками, горчицей и мукой. Добавляем мускатный орех, соль, перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12501,'В форму для запекания, смазанную маслом выкладываем брокколи и заливаем ее приготовленной заливкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12501,'Сверху натираем сыр на крупной терке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12501,'Отправляем в духовку на 190-200 градусов примерно на 15-20 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12502,'Для начала приготовим пасту. В блендере смешаем лук шалот, зелёный лук, перец, паприку, куркуму, томатную пасту, острый перец, чеснок и все тщательно сбить до однородной массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12502,'Перейдём к супу. Разогреем масло в кастрюле и обжарим лук, чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12502,'После добавим пасту и зальём кокосовое молоко и как только начнёт кипеть добавим бульон, картофель и оставим на 10-15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12502,'Выключим плиту и взобьём блендером.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12502,'Включим и добавим курицу и оставим ещё на 10 минут. И можно подавать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12503,'Промыть сухофрукты, залить очень горячей водой минут на 5, вынуть шумовкой,      переложить для обсушивания на полотенце, сложить в миску, присыпать щепоткой муки. Включить для прогрева до 180 градусов духовку, подготовить форму, смазать ее маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12503,'Отделить желтки, взбить до изменения цвета с сахаром, солью, ванилью. Не прекращая взбивать влить масло, йогурт, перемешать, добавить смесь просеянной муки с разрыхлителем, перемешать до однородности, добавить сухофрукты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12503,'Белки довести в миксере до состояния крепкой пены, смешать с тестом до получения однородного состояния, перелить тесто в подготовленную форму.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12503,'Убрать форму в прогретую духовку, выпекать до красивого золотисто соломенного цвета, периодически проверять готовность зубочисткой. Готовому кексу на йогурте с черносливом и изюмом дать чуть остыть, вынуть из формы, остудить полностью, порезать на куски, подать к чаю.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12504,'Разломать печенье на кусочки, порубить орехи. Растопить размягченное масло, всыпать сахар, добавить мед, перемешать, нагреть почти до кипения, убрать с плиты, дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12504,'Все смешать, сформовать небольшие шарики, окунуть в шоколад, убрать готовые конфеты с грецким орехом «Метеорит» в холодильник примерно на час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12505,'В чашу блендера вбить яйца, всыпать сахар, взбивать до тех пор, пока весь сахар не  растворится, должна получиться  пышная смесь. В муку всыпать какао, перемешать, соединить с сахарно-яичной массой, осторожно перемешать, влить остывшее жидкое сливочное масло, еще раз перемешать. Чересчур долго мешать не стоит, иначе яйца осядут, и в результате пышного бисквита получить не удастся.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12505,'Выпекать бисквитную основу для торта около получаса в духовке с температурой 180 градусов. Дать бисквиту остыть, разрезать вдоль на три равные части. Из сгущенного молока, желтков, воды и ванильного сахара приготовить на водяной бане заварную смесь, после закипания проварить минуты 3-4, выключить нагрев, остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12510,'Груши вымыть, вырезать у плодов сердцевину, мякоть нарезать мелкими кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12510,'Вымыть, просушить, нашинковать зелень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12505,'Взбить размягченное масло, часть его смешать с какао и растопить, соединить со взбитым маслом, взбить все вместе в однородную массу. Смешать с заварной смесью, взбить, подготовленный крем убрать в холодильник. Взять 250 граммов воды и столько же сахара, сварить сироп, влить немного коньяка, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12505,'Разложить коржи на столе, пропитать сиропом, смазать кремом, сложить в стопку, облить глазурью, дать застыть, верх торта оформить по вкусу. Праздничный торт «Прага» в домашних условиях готов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12506,'Бульон:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12506,'Свинина Чашу:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12506,'Рамен:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12506,'Сборка:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12507,'Яйца и сахар взбиваем в пышную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12507,'Соду и соль добавляем в сметану и перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12507,'Смешиваем все ингредиенты, добавляем манку и муку. Замешиваем тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12507,'Даем тесту постоять 20 минут, чтобы набухла манка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12507,'Отправляем в разогретую духовку на температуру 180 градусов примерно на 40 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12507,'После того как манник остыл, посыпаем сахарной пудрой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12508,'В просеянную муку всыпать соду, сахар, ванилин, добавить размягченное масло, порубить до образования  маслянистой крошки, влить охлажденный кефир и добавить желток яйца, замесить тесто, которое чуть-чуть будет липнуть к рукам, положить его на час в морозильную камеру холодильника.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12508,'Достать тесто, разделить на две равные части, одну раскатать, переложить на подготовленный противень. Смазать пласт любым густым вареньем, сгущенкой или джемом, прикрыть начинку вторым раскатанным пластом. Верх помазать слегка разболтанным белком или молоком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12508,'Выпекать домашнее печенье на кефире с вареньем около получаса при температуре 180 градусов. Дать чуть остыть, разрезать на ромбы или квадраты, присыпать сахарной пудрой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12509,'Помидоры вымыть, нарезать дольками, сыр «Моцарелла» – кружками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12509,'На плоское круглое блюдо выложить кружки сыра и дольки помидоров.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12509,'Украсить закуску веточками базилика, сбрызнуть хорошим оливковым маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12510,'Куриную грудку очистить от шкурки, вымыть, отварить, нарезать мелкими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12510,'Белую консервированную фасоль откинуть на дуршлаг.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12510,'Перемешать куриное мясо, фасоль, зелень, грушу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12510,'Заправить ингредиенты майонезом, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12510,'Выложить массу на красивую тарелку, украсить дольками груши.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12511,'Соленые грибы хорошо промыть и нарезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12511,'Репчатый лук очистить, вымыть, нарезать полукольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12511,'Перемешать, заправить растительным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12511,'Черный молотый перец – по вкусу и желанию.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12512,'Отварить, очистить, остудить и порубить куриные яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12512,'Твердый сыр натереть на мелкой терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12512,'Открыть банку с кукурузой, жидкость слить, можно откинуть на дуршлаг.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12512,'Филе курицы очистить, вымыть, отварить в подсоленной воде и мелко нарезать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12512,'Грецкие орехи почистить, измельчить при помощи скалки и тканевого пакета.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12512,'Поставить на блюдо стакан, вокруг выложить слоями куриное мясо с майонезом, морковь по-корейски, майонез, кукурузу, яйца, майонез, сыр и грецкие орехи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12512,'Украсить салат зеленью, убрать стакан.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12512,'Блюдо поставить на полчаса в холодильник.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12513,'Сполоснуть и обсушить веточки мяты, отделить листочки и измельчить, горошки черного перца раздавить в ступке, порезать зубчики чеснока вдоль на 4-5 тонких пластинок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12513,'Всыпать в миску перец, соль, карри, мяту, чеснок, перемешать, обмазать этой смесью сало, присыпать смесью «прованские травы»',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12513,'Обернуть мятное сало с приправой карри тканью и положить на пару суток в холодильник, а затем переложить в морозилку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12514,'Вымыть, отварить, измельчить куриное мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12514,'В горячей воде на два часа замочить чернослив.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12514,'Продукт вынуть, просушить, удалить косточки, мякоть нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12514,'Почистить, вымыть, нарезать полукольцами лук, ошпарить для удаления лишней горечи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12514,'Укроп вымыть и просушить, нарезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12514,'Ингредиенты перемешать, добавить соль, майонез, укроп и перец.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12514,'Подать к столу на красивом блюде с широкими краями.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12515,'Куриную грудку очистить, вымыть, отварить, нарезать небольшими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12515,'Открыть банку с консервированными ананасами, слить жидкость, мякоть нарезать крупнее, чем куриное мясо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12515,'Отварить и очистить морковь, натереть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12515,'Измельчить грецкие орехи, чеснок, натереть твердый сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12515,'Продукты соединить, перемешать, заправить сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12516,'Лимон вымыть и нарезать тонкими дольками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12516,'Почистить, вымыть, нарезать полукольцами репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12516,'Перемешать продукты с маслинами и любой зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12516,'Заправить оливковым маслом и яблочным уксусом, острый красный перец и соль – по вкусу, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12516,'Подать к столу сразу, чтобы продукты не успели потечь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12517,'Репчатый лук очистить, вымыть, мелко нарезать, обжарить до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12517,'Вымыть и покрошить кубиками шампиньоны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12517,'Добавить к луку, посолить, довести до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12517,'Остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12517,'Приготовить соус из майонеза и чеснока.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12517,'Довести до кипения овощной бульон, всыпать желатин.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12517,'Сразу снять с огня, остудить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12517,'Желатин должен полностью раствориться.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12517,'В небольшие пиалы выложить грибную обжарку, посыпать нарезанной зеленью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12517,'Поверх налить майонез с чесноком.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12517,'Залить бульоном, делать это осторожно, чтобы ингредиенты не перемешались.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12517,'Поставить в холод до застывания.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12518,'Слегка подогреть молоко, добавить сахар, перемешать до полного его растворения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12518,'Раскрошить в миску дрожжи, дать постоять пару минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12518,'Перемешать, всыпать чуть муки, прикрыть тканью, оставить опару в тепле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12518,'В высокую кастрюлю разбить пару яиц, добавить ещё один желток, белки убрать в холодильник для приготовления глазури.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12518,'В яйца всыпать сахар и ванилин, взбить миксером до получения белой пены.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12518,'Установить на кастрюлю сито, протереть сквозь него творог, добавить растопленное и остывшая масло, осторожно перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12518,'Для красивого цвета всыпать куркуму, добавить тертую цедру апельсина.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12518,'Соединить опару с творожной основой, подсолить, порциями добавить муку, хорошо перемешать, добавить распаренный и обсушенный изюм с кусочками цукатов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12518,'Убрать творожное тесто в тепло, чтобы объем увеличился в 2 раза.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12518,'Подготовить формы, выслать пергаментной бумагой, смазать маслом, при желании можно использовать силиконовые формы или магазинные заготовки из бумаги (смазать маслом).',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12518,'Разложить по формам тесто, заполняя их лишь на треть, прикрыть полотенцем, оставить на полчаса в тёплом месте.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12518,'Выпекать творожный кулич с цукатами на дрожжах порядка 40 минут, проверяя готовность деревянной зубочисткой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12518,'Готовую выпечку остудить на решетке, вынуть из формочек, если они выпекались в бумажных «стаканах», то их можно оставить.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12518,'Достать охлажденный белок, взбить до белой пены, частями всыпать сахарную пудру, взбить до получения густой пены, влить лимонный сок, еще раз взбить.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12518,'Оформить верх выпечки глазурью с присыпкой, дать высохнуть.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12519,'Для начала нарежем тыкву большими кубиками и поместим в форму для запекания, посыпем тимьяном, положим чеснок и отправим в духовку разогретую до 190 градусов на 35-40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12519,'Готовую тыкву переложим в блендер, натрем имбирь и зальём бульоном. Взбивать до однородной массы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12519,'Залить в кастрюлю на среднем огне. Добавим молоко или сливки, мускатный орех, паприку и по желанию сыр и куриную грудку нарезанную кубиком. Подавать с гренками или тыквенными семечками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12520,'Отварить и остудить рис, порубить блендером лук и грибы на средние кусочки, хорошо «отбить» фарш. Соединить фарш, лук, грибы, рис, стружку сыра, зелень укропа, подсолить, поперчить, тщательно перемешать. Включить на разогрев духовку (примерно до 180 градусов).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12520,'Увлажнить руки, скатать из фарша тефтели, переложить их в форму. Кусочки помидоров смешать с сахаром и сметаной перемешать. Разболтать в 2\3 стаканах воды муку до исчезновения комочков, вылить ее в томатную смесь перемешать и залить тефтели.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12520,'Прикрыть форму листом фольги, обмять вокруг краев, отправить тефтели из мясного фарша с грибами примерно на час в прогретую духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12521,'Шляпки грибов порезать на пластинки, ножки измельчить, лук нашинковать, как больше нравится, обжарить на хорошо прогретом масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12521,'Помидоры очистить от кожицы, нарезать на кружки по полсантиметра толщиной, сыр натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12521,'Форель, разделанную на стейки присолить, посыпать черным перчиком, разложить на дне формы, промазанной маслом, прикрыть луково-грибной зажаркой, потом кружочками помидоров, сверху присыпать сыром, отправить в духовку, прогретую чуть ниже 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12521,'Форель, запеченная с грибами и помидорами, будет готова примерно через полчаса. Чтобы верхняя корочка оставалась мягкой, форму можно прикрыть в середине готовки фольгой. Готовое блюдо присыпать любой измельченной зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12522,'Подготовить изюм, перебрать и тщательно его вымыть, залить на треть часа теплой водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12522,'Откинуть на сито, переложить на бумажное полотенце, чтобы он хорошо обсох.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12522,'Размягченное масло порезать на кусочки и сложить в кастрюльку, растопить на очень маленьком огне, убрать с плиты, дать полностью остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12522,'В небольшой посуде взбить до пышного состояния яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12522,'Смешать протертый сквозь сито творог с сахаром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12522,'Перемешать смесь с яйцами и остывшим маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12522,'Погасить соду соком лимона, вылить в творожную основу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12522,'Перемешать, добавить маленькими порциями муку, каждый раз тщательно перемешивая.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12522,'Добавить к тесту кусочки цукатов с изюмом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12522,'Заполнить творожным тестом на 1/3 формочки, накрыть их кухонным полотенцем, оставить на полчаса для поднятия в тёплом месте.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12522,'Установить формы на противень, поместить в заранее прогретую духовку и выпекать порядка 45 минут, время зависит от величины формочек.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12522,'Верх охлажденного кулича оформить взбитым с сахарной пудрой белком.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12522,'Дать ему высохнуть.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12523,'Порубить орехи на кусочки, измельчить цукаты, замочить и обсушить изюм, растопить и остудить масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12523,'Творог взбить блендером до пастообразного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12523,'Развести молоко с водой, прогреть примерно до 40 градусов (не больше) на слабом огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12523,'Перемешать прогретую смесь с сахаром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12523,'Добавить яйца, масло и творог, хорошо всё перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12523,'В просторную миску просеять муку, подсолить, добавить ваниль, перемешать с дрожжами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12523,'Объединить мучную смесь с творожной основой, хорошо вымесить руками или миксером со специальной насадкой до состояния чуть липнущего к рукам теста.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12523,'Перемешать тесто с цукатами, орехами и изюмом, дать постоять в тепле около часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12523,'Подготовить формочки, обмять тесто, разложить по формочкам, дать постоять, включить для разогрева духовку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12523,'Когда тесто поднимется, поставить формы в духовку, выпекать кулич до готовности.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12523,'Выпечку достать, остудить на решетке, оформить по своему вкусу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12524,'Накануне приготовления залить вишню коньяком, дать постоять ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12524,'Все продукты для приготовления теста достать заранее, чтобы они приобрели комнатную температуру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12524,'Подготовить формочки, включить для прогрева на 180 градусов духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12524,'Взбить миксером яйца с добавлением сахара, чтобы получить плотную массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12524,'Добавить кусочки масла, продолжить взбивать до однородной смеси.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12524,'Положить в масляную смесь творог, перемешать до однородности миксером или блендером.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12524,'Добавить к творожной массе соду, муку, обсушенную вишню, хорошо перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12524,'Заполнить формы полученной массой на 1/2, поверхность разровнять, поставить в духовку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12524,'Выпекать кулич до готовности.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12524,'Дать выпечке остыть, в это время приготовить меренгу, залив сахар 40 мл воды, прогрев всё до получения прозрачного сиропа.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12524,'Взбить в крепкую пену белки и дополнительные 50 граммов сахара.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12524,'Медленно влить в полученную массу горячий сироп, взбить меренгу в воздушную и плотную массу (около 5 минут).',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12524,'Холодные куличи смазать толстым слоем меренги, украсить любым покупным декором.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12525,'Смесь дрожжей с сахаром растворить в чуть теплом молоке, добавив пару ложек муки, хорошо все перемешать, чтобы исчезли комочки, оставить в тепле на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12525,'Перебрать и помыть изюм, залить водой, дать постоять 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12525,'Выложить в дуршлаг, дать хорошо стечь воде, пересыпать на полотенце, дать ему обсохнуть, вместо изюма можно брать курагу или вяленую вишню.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12525,'Масло растопить, слегка остудить, смешать с дрожжами, протертым через сито творогом, хорошо размешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12525,'В творожную основу добавить ваниль с сахаром, вбить яйца, добавить шоколадную крошку и обваленный в муке изюм.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12525,'Всё тщательно вымесить с просеянной мукой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12525,'Тесту дать постоять пару часов в тепле.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12525,'Тесто обмять, разложить в формочки, накрыть тканью, поместить на 45 минут в теплое место.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12525,'Выпекать творожный кулич с белым шоколадом и изюмом до готовности около получаса, вынуть из форм, дать куличам остыть.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12525,'Для меренги сварить прозрачный сироп, постепенно перемешать его со взбитыми в крепкую пену чуть подсоленными белками, в результате должна получиться воздушная масса.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12525,'Верхушки куличей покрыть меренгой, дать им подсохнуть.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12526,'Куриное филе смазать пропущенным через пресс чесноком, горчицей и любыми специями для птицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12526,'Жарить на оливковом масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12526,'Натереть сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12526,'Нарезать кусочками помидоры, отваренные куриные яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12526,'Для приготовления соуса перемешать сырое яйцо с соком лимона, горчицей, оливковым маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12526,'Ингредиенты соединить, полить заправкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12527,'Отварить кальмары и картофель, яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12527,'Морепродукты нарезать полосками, картофель, яйца, сыр натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12527,'Репчатый лук измельчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12527,'Выложить продукты слоями: картошка, кальмары, репчатый лук, яйца, сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12527,'Все слои промазывать майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12528,'Спаржу отварить в кипятке, время – две минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12528,'Продукт остудить и разрезать пополам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12528,'Морковь по-корейски измельчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12528,'Мелко нарезать лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12528,'Обжарить кусочки бекона.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12528,'Открыть банку с консервированной фасолью, жидкость слить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12528,'Приготовить заправку из майонеза и соевого соуса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12528,'Продукты соединить, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12528,'Украсить картофельными чипсами перед подачей.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12529,'Отварить картофель, крупно нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12529,'Измельчить копченую колбасу и яйца, нарезать маринованные огурцы пластинками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12529,'Натереть сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12529,'Открыть банку с зеленым горошком и слить жидкость.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12529,'Продукты соединить, посолить по вкусу и заправить майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12530,'Нарезать огурцы, помидоры, сладкий болгарский перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12530,'Заправить растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12530,'Растолочь сыр «Фета», перемешать с рубленой зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12530,'Слепить небольшие шарики, выложить их на овощную смесь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12531,'Салатницу смазать растительным маслом и выложить продукты в несколько слоев.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12531,'Первый слой – тертый сыр белого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12531,'Второй – отваренная и нарезанная морковь, майонез.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12531,'Далее – отваренный и натертый картофель, полукольца репчатого лука, обжаренные на сковороде до мягкого состояния.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12531,'Пятый слой – отваренные тертые желтки с чесноком и майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12531,'Шестой и седьмой слои – ломтики вареной колбасы, тертый белок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12531,'Украсить блюдо помидорами черри и листочками зелени в виде новогодней игрушки на ветке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12532,'Отварить куриное филе, вынуть из отвара и сразу нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12532,'Пропустить чеснок через чеснокодавку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12532,'Помидоры нарезать мелкими кубиками, выложить на блюдо, добавить чеснок, майонез.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12532,'Нарезать небольшими кубиками сладкий болгарский перец, добавить чеснок и тоже выложить на блюдо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12532,'Натереть сыр, посыпать салат.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12532,'Для украшения использовать листья зеленого салата, лепестки цветка вырезать из отваренной моркови, листочки – из свежего огурца.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12532,'Вырезать кожуру помидора, скрутить, сформовать маленький цветок.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12532,'Поставить салат в холодильник на два часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12533,'Песочное тесто раскатать (стол чуть притрусить мукой) в тонкий прямоугольник. Очень осторожно переложить его в приготовленную форму, придавить аккуратно к бортикам, углам и дну. Очень острым ножом срезать лишнее тесто, с небольшими интервалами проколоть вилкой, отправить в холодильник примерно на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12533,'Достать основу, прикрыть пекарской бумагой, засыпать горохом (сухим) либо фасолью, чтобы после выпечки получить корж с бортиками. Отправить в прогретую до 180 градусов духовку примерно на треть часа, достать снять бумагу вместе с содержимым, выпекать основу еще минут 10 или чуть больше, пока цвет не изменится на золотистый. Дать основе для сладкого тарта полностью остыть и выложить на блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12533,'Сахар (использовать лучше мелкокристаллический) объединить с желтками, взбить в желтоватую пену, подсыпать порциями муку и взбить все вместе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12538,'Перемешать продукты с консервированным горошком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12538,'Для приготовления соуса смешать майонез со сметаной, заправить салат.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12538,'Отварить яйца и разрезать пополам, желтки достать, обмакнуть в сметанный соус и положить обратно.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12538,'Выложить на салат, посыпать тертым сыром, украсить веточкой укропа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12533,'Налить молоко в маленькую кастрюльку, вскрыть ванильный стручок, кончиком ножа переложить «начинку» в молоко, дать ему закипеть, соединить с желтковым кремом и сразу взбить. Поставить полученную смесь  на небольшой огонь, дать закипеть, чуть проварить (хватит пары минут) помешивая, чтобы мука схватилась, осторожно процедить в миску сквозь сито, комочки протереть. Заполнить хорошо остывшую основу кремом, дать постоять и застыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12533,'Подготовить фрукты, осторожно оторвать ягоды смородины от кисточек, порезать ананас и киви на пластинки, клубнику – на четвертинки. Разложить все фрукты на поверхность крема по своему усмотрению, смазать кипящим абрикосовым джемом, протертым сквозь сито, дать тарту постоять и застыть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12534,'Куриное филе нарезаем на небольшие кубики, или же произвольно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12534,'Помидор нарезаем на дольки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12534,'Лук репчатый нарезаем полукольцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12534,'Красный болгарский перец нарезаем небольшими кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12534,'Сыр натираем на мелкой терке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12534,'Тонкий лаваш обрезаем по кругу, при помощи тарелки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12534,'На разогретой сковороде, для начала обжариваем лук. Примерно минут 5. Как только лук обжарился до золотистости, туда же добавляем помидор, и красный болгарский перец. И все это ещё обжариваем минут 5 - 7, солим и перчим по вкусу. Спустя это время, перекладываем начинку на тарелку, и убираем с строну.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12534,'На той же, сковороде обжариваем подготовленное куриное филе. Обжариваем до готовности. так же солим и перчим по вкусу. Как только готово, так же перекладываем в тарелку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12534,'Обе начинки надо перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12534,'На подготовленный тонкий лаваш, на одну его сторону посыпаем сыром, на сыр добавляем начинку, и снова посыпаем сыром.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12534,'На разогретой сковороде, обжариваем каждую сторону кесадильи, по несколько минут до корочке.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12535,'Куриное филе нарезать и обжарить на растительном масле, соль и молотый перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12535,'Переложить в салатницу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12535,'Нарезать репчатый лук полукольцами, залить кипятком, влит уксус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12535,'Мариновать в течение получаса, жидкость слить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12535,'Массу выложить в салатницу, смазать майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12535,'Шампиньоны обжарить в течение шести минут, посолить, переложить на лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12535,'Отварить картофель, натереть, добавить в салатницу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12535,'Отварить яйца, очистить, разрезать пополам, желтки отложить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12535,'Чеснок покрошить, добавить в желтки вместе с майонезом, перемешать, нафаршировать белки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12535,'Посыпать салат между фаршированными и перевернутыми яйцами тертым сыром.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12535,'Украсить зернами граната.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12536,'Картофель нарезать ломтиками, обжарить и выложить на блюдо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12536,'Намазать майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12536,'Отварное куриное филе нарезать кубиками, также выложить на блюдо и смазать майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12536,'Натереть отваренные яйца, выложить на салат горкой, соль – по вкусу и желанию.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12536,'Полить майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12536,'Посыпать салат тертым «Российским» сыром.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12536,'Поставить блюдо в холодильник на полчаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12537,'Отварить и натереть картофель, выложить на блюдо, намазать майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12537,'Отварить и натереть морковь, выложить на блюдо, также смазать майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12537,'Репчатый лук перемолоть в блендере вместе с консервами из рыбы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12537,'Этот слой также смазать майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12537,'Мелко нарезать красный сладкий болгарский перец, выложить на блюдо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12537,'Отварить яйца, разрезать пополам, желтки вынуть, перемешать с майонезом и давленым чесноком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12537,'Нафаршировать белки, выложить их на салат в перевернутом виде, намазать майонезом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12537,'Посыпать блюдо тертым сыром.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12538,'Отварить кальмары до готовности в подсоленной воде, для этого понадобится три минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12538,'Кальмары нарезать кольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12538,'Отварить рис до рассыпчатого состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12539,'Сварить картофель, снять «мундир» с картофеля, протереть холодным на крупной терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12539,'Подготовить маринад из воды и уксуса, положить в него кольца лука, разрезанные на четыре части, дать постоять, отбросить на дуршлаг, промыть под проточной водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12539,'Ветчину нарезать на кубики, яйца протереть и твердый сыр. Положить  на тарелку картофель, разровнять, покрыть майонезом, уложить на него ветчинные кубики, опять наложить слой майонеза, прикрыть луком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12539,'Теперь уложить яичный слой, далее майонез, завершить слои сыром. Верх салата оформить смесью зелени петрушки с укропом, можно и чем-нибудь одним и половинками небольших шампиньонов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12540,'Говядину отварить, порезать кусочками, переложить в салатницу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12540,'Обжарить морковь и репчатый лук, намазать слой майонезом, посыпать рублеными грецкими орехами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12540,'Вареные яйца разрезать, желтки растереть, добавить в них грецкие орехи, майонез, соль и перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12540,'Нафаршировать белки, выложить яйца в центр и по кругу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12540,'Посыпать тертым сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12541,'Отварить до готовности куриную печень, соль добавить в конце приготовления.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12541,'Выложить на блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12541,'Шампиньоны нарезать пластинками, обжарить на растительном масле, соль – по вкусу, выложить на блюдо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12541,'Нарезать лук полукольцами, обжарить, посолить и выложить поверх грибов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12541,'Смазать майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12541,'Отварить яйца, разрезать пополам, выложить на блюдо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12541,'Готовый салат посыпать тертым сыром.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12542,'Куриные окорочка посолить и посыпать карри, обжарить до готовности на масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12542,'Залить сухим вином, тушить до тех пор, пока жидкость не испарится.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12542,'Мясо от костей освободить, нарезать небольшими кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12542,'Разрезать пополам отваренные куриные яйца, желтки вынуть, растереть их с чесноком, столовой горчицей, солью и майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12542,'Готовой смесью начинить половинки яиц.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12542,'Очистить морковь, яблоко, продукты натереть на терке, полить лимонным соком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12542,'Выложить салат слоями: отваренный рис, куриное мясо, морковь с яблоками, майонез, фаршированные яйца.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12542,'Половинки намазать майонезом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12542,'Блюдо щедро посыпать тертым сыром.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12543,'Нагреть масло до комнатной температуры, положить его, когда размякнет в чашку миксера, добавить около чайной ложки сока лимона, вареную сгущенку, взбить все на большой скорости до однородности и изменения цвета (примерно 3 минуты).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12543,'На плоское блюдо положить вафельный корж, промазать его кремом, накрыть вторым и т.д. Верх последнего коржа смазывать кремом не нужно, положить на него разделочную досочку, а на нее поставить не очень тяжелый груз, дать постоять так пару часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12543,'Оформить верх домашнего вафельного торта с вареной сгущенкой — шоколадной стружкой, фруктами, глазурью или присыпать рублеными орехами с кокосовой стружкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12544,'Нарезать соломкой копченое мясо, выложить в салатницу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12544,'Свежие огурцы нарезать соломкой, намазать майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12544,'Отварить и натереть картофель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12544,'Грибы нарезать и обжарить, также смазать слой майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12544,'Отварить и разрезать пополам куриные яйца, разложить поверх салата.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12544,'Натереть сыр, посыпать блюдо и поставить его в холод на полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12545,'Натереть отваренный картофель, сделать сеточку из майонеза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12545,'Грибы мелко нарезать, приготовить обжарку вместе с репчатым луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12545,'Выложить на блюдо, смазать майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12545,'Отварить куриное филе, выложить на блюдо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12545,'Маринованные огурцы нарезать кубиками, выложить на блюдо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12545,'Пятый слой – разрезанные вареные яйца.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12545,'Посыпать массу тертым сыром.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12546,'Первый слой – консервированная, отцеженная от жидкости, кукуруза, майонез.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12546,'Второй – свежие огурцы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12598,'Грецкие орехи очистить и порубить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12546,'Мелко накрошенный репчатый лук и болгарский перец, майонез.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12546,'Нарезанные крабовые палочки, отваренные яйца, майонез.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12546,'Следующий слой – тертый сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12546,'Верх салата украсить зеленым горошком, консервированной кукурузой, зернами граната.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12547,'Репчатый лук нарезать, полить яблочным уксусом, добавить сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12547,'Овощ немного помять и оставить для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12547,'Выложить на плоскую тарелку тертый картофель, намазать майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12547,'Далее – маринованный лук, малосольная форель, тертая вареная морковь, майонез.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12547,'Следующий слой – тертое яблоко, натертое замороженное сливочное масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12547,'Выложить яичный белок, смазать майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12547,'Сверху – раскрошенный желток и сыр «Пармезан».',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12547,'Время пропитывания – полчаса.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12548,'Отварить говядину, нарезать кубиками, смазать майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12548,'Отварить картофель, натереть, насыпать на мясо, смазать майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12548,'Нарезать полукольцами белый репчатый лук, ошпарить кипящей водой, долить уксус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12548,'Отжать через пятнадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12548,'Белокочанную капусту тонко нарезать, посолить, побрызгать уксусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12548,'Отварить, очистить и разрезать пополам куриные яйца, выложить на блюдо, смазать майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12548,'Потереть любой твердый сыр.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12549,'Взять куриное филе без кожицы, отварить его до готовности — после закипания варить филе примерно 20 минут. Остудить мясо, разобрать на волокнистые кусочки. Порезать кубиками белый батон, пожарить до золотистой корочки в небольшом количестве растительного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12549,'Порезать соломкой огурцы, лук — полукольцами. Если лук горький, его нужно залить кипятком на 10 минут, потом слить водичку, лук промыть — эта процедура избавит его от горечи. Потереть сыр на мелкой терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12549,'Далее необходимо сделать заправку: смешать растительное масло с уксусом, поперчить и посолить. Добавить измельченный чеснок — его можно порезать помельче или пропустить через чеснокодавилку. Салат порвать руками. Добавить огурчики, лук, куриное филе, тертый сыр, сухарики, заправить. Салат с куриным филе и сухариками «Хрустящий» готов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12550,'Открыть банку с тунцом, филе размять, добавить лимонный сок и майонез.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12550,'Обжарить предварительно замаринованный в уксусе репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12550,'Слой смазать майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12550,'Выложить нарезанный кубиками сладкий болгарский перец, консервированную кукурузу, намазать майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12550,'Свежие огурцы нарезать кружками, выложить на блюдо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12550,'Яйца отварить и очистить, разрезать вдоль.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12550,'Желтки вынуть, перемешать с рыбой, добавить красную икру.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12550,'Полученной массой начинить белки, выложить на огурцы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12550,'Обмазать все майонезом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12550,'Посыпать тертым сыром.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12551,'Сыр нарезаю на тонкие квадраты и по размеру сыра нарезаю лаваш на полоски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12551,'На край лаваша кладу кусочек сыра и заворачиваю лаваш.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12551,'Яйца солю и взбиваю венчиком, каждый конверт из лаваша хорошо обмакиваю в яйце и обжариваю с двух сторон.','https://vkuso.ru/data/cache/data/90/6190682e9768390_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12552,'Баклажан, кабачок и помидор нарезать кружочками.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12552,'Баклажан и кабачок выложить в миску, посолить, поперчить, полить маслом и хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12552,'Выложить в форму для выпечки поочередно баклажан, кабачок, помидор.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12552,'Болгарский перец, лук нарезать крупно.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12552,'Влить смесь в кастрюлю, поставить на средне-слабый огонь, варить 10-15 мин.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12552,'Залить соусом овощи, поставить обратно в духовку и выпекать 25-30 мин. при температуре 190-200 градусов. При подаче посыпать чесноком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12553,'Порезать ветчину тонкой соломкой, потереть сыр твердых сортов на терке, мелко порубить петрушку, зеленый лук, базилик. Все перемешать, добавить соль по вкусу. Яйца взбить со щепоткой соли, часть смеси оставить для обмазки пирога, в оставшуюся часть добавить измельченную зелень, поперчить и посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12553,'Влить немного масла на раскаленную сковородку, вылить в нее треть яичной смеси, которая будет напоминать блинное тесто. Жарить не более 2 минут под крышкой. Аналогичным способом нужно приготовить еще 2 омлета. Далее раскатать тесто толщиной 1 см, чтобы получилось два круглых коржа, одну часть теста положить на противень, проколоть вилкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12553,'Выложить по центру теста омлет, присыпать сыром с ветчиной. Со следующими двумя омлетами поступить аналогичным образом — получится слоеный пирог. Накрыть начинку вторым куском теста, подвернуть, защипнуть края,  промазать яйцом, верхний корж обязательно наколоть вилкой. Сделать пальцем по центру небольшую дырочку, вставить трубочку, сделанную из обрезков теста. Выпекать слоеный пирог «Галета» с ветчиной нужно в течение 20-30 минут в духовке, прогретой до 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12554,'В дрожжи влить слегка подогретую воду, перемешать, дать постоять треть часа, чтобы они стали активными.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12554,'Просеять муку конусом, сделать на вершине углубление, осторожно влить в него дрожжевую смесь, подсолить, добавить майонез и сахар, тщательно вымесить, до получения мягкого теста.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12554,'Колобок теста раскатать в лепешку, выложить дрожжевое тесто на майонезе для пиццы в форму или на сковороду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12554,'Распределить по поверхности начинку, выпекать до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12555,'В миске разболтать майонез с яйцом, подсолить, добавить погашенную уксусом соду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12555,'Порциями всыпать в смесь муку, хорошо вымешать, чтобы получилось тесто похожее для оладий.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12555,'Основу из бездрожжевого теста на майонезе для пиццы выпекать отдельно около нескольких минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12555,'Потом выкладывать на нее начинку и выпекать до полной готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12556,'Муку дважды просеять, сделать на вершине горки углубление, влить туда воду, перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12556,'Добавить к жидкому тесту смесь метаны с майонезом, чуть подсолить, хорошо вымешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12556,'Дать «созреть», оставив на треть часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12556,'Вылить бездрожжевое тесто для пиццы со сметаной и майонезом на сковороду, выпечь основу пиццы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12557,'Половину порции творога выкладываю по всей поверхности лаваша, сверху накрываю другим листом лаваша и хорошо промазываю его вареньем, сверху снова выкладываю вторую половину творога и заварачиваю в тугой рулет.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12557,'Края рулета брезаю, они мне уже не понадобятся, рулет нарезаю на кучочки в три сантиметра и обжариваю с двух сторон на сливочном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12558,'Подогреть молоко, залить дрожжи, перемешать, дать набухнуть, поместив их в тёплое место.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12558,'Дрожжевую смесь посолить, влить масло, добавить оставшиеся ингредиенты и немного муки, хорошо вымешать, дать постоять минут 10-15.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12558,'В дрожжевое тесто для пиццы на молоке с майонезом добавить остаток муки, вымесить тесто, похоже по консистенции на жидкую сметану, выпекать на сковороде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12559,'Смесь с майонеза с яйцами разболтать венчиком, всыпать муку, перемешать до однородности, чтобы исчезли все комочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12559,'На большую сковороду вылить тесто, распределить равномерно кетчуп по поверхности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12559,'Подготовить начинку, колбасу нарезать соломкой или кружочками, помидор и огурец – тонкими кружочками, лук –   полукольцами, чеснок – на тонкие слайсы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12559,'Разложить начинку равномерно на основу, натереть крупно сыр, присыпать пиццу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12559,'Запекать бездрожжевую пиццу на майонезе с колбасой на малом огне, накрыв сковороду крышкой, около 10 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12560,'Нарезать подготовленное филе лосося на мелкие кубики, побрызгать свежеотжатым соком лимона, всыпать порубленную петрушку и часть зеленого лука, сдобрить солью, перемешать. Творожный сыр перемешать с взбитыми яйцами, объединить с кусочками рыбы и панировочными сухарями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12560,'Смочить руки, сделать котлеты, обмакнуть со всех сторон в крошку из кукурузных хлопьев, обжарить в разогретом масле. Для соуса нарезать мелко помидоры, перемешать со сметаной и майонезом, добавить лук, присолить. Котлеты из филе лосося с томатным соусом готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12561,'Взбить венчиком смесь из яиц, майонеза и сметаны, постепенно всыпать муку, продолжая перемешивать, должно получиться тесто, похожее на хорошую сметану.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12561,'Большую сковороду смазать маслом, вылить тесто, смазать поверхность кетчупом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12561,'Нашинковать на тонкие полукольца лук, выложить на тесто, грибы порезать на пластины, уложить поверх лука.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12561,'Колбасу порезать на кубики, присыпать лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12561,'Начинку прикрыть тонкими колечками помидора, посолить, поперчить, присыпать сырной стружкой и нашинкованной мелко зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12561,'Выпекать пиццу на майонезе и сметане с колбасой и грибами при слабом нагреве, прикрыв сковороду крышкой, около 10 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12562,'В глубокой миске перемешать яйцо, сметану, майонез, добавить погашенную уксусом соду, размешать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12562,'Подсыпать частями муку, вымесить тесто, чтобы оно не прилипало к рукам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12562,'Полученное тесто раскатать в пласт, переложить его на противень с помощью скалки, выложить на основу начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12562,'Смешать до однородности томатную пасту и майонез, смазать этим соусом пиццу, присыпать половиной сыра, крупно натертого.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12562,'Выложить на него тонкие полоски отварной куриной грудки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12562,'Присыпать мясо оставшимся сыром.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12562,'Уложить на него кружочки колбасы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12562,'Выпекать пиццу на майонезе и сметане с курицей и колбасой в духовке треть часа при температуре 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12563,'Приготовить основу, используя один из вышеприведенных рецептов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12563,'Смазать ее смесью майонеза с кетчупом, разложить по поверхности тонкие кружочки помидоров, присыпать крупной сырной стружкой, приправить прованскими травами с тимьяном и соусом «Сальса».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12563,'Присыпать соус второй половиной сыра, разложить на нем соцветия брокколи, запекать пиццу с брокколи и соусом «Сальса» четверть часа в духовке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12564,'Замесить тесто по одному из вышеприведенных рецептов, оно должно быть крутым.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12564,'Для начинки нашинковать колечками луковицу, помидоры и яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12564,'А крабовое мясо порвать на мелкие кусочки, перемешать его со сметаной и мелко нашинкованным зелёным луком с небольшим количеством теплой воды, подсолить, поперчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12564,'Тесто раскатать в пласт, переложить на смазанный маслом противень, его поверхность смазать кетчупом, присыпать небольшим количеством сахара, выложить колечки лука, на него яйца, далее – кукурузные зерна, прикрыть всё кружочками помидоров, залить соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12564,'Выпекать пиццу с крабовыми палочками, кукурузой и яйцами при 180 градусах порядка 40 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12565,'Сварить и измельчить кальмары, всыпать тертый сыр, вбить пару яиц, сдобрить перчиком, мускатным орехом и солью, перемешать. Нагреть духовку (достаточно будет 200 градусов). Постелить на противень бумагу для выпечки, чуть смазать маслом, выложить массу из кальмаров, разровнять, задвинуть противень на 10 минут в духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12565,'Измельчить 3 вареных яйца, нарезать зелень и огурцы, достать основу рулета, дать слегка остыть, нанести слой творожного сыра, сверху —  зелень с огурцами, затем опять сыр, присыпать порубленными яйцами. Аккуратно свернуть пласт, упаковать закусочный рулет из кальмаров в фольгу, дать остыть и можно подавать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12566,'Отварить яйца, куриную грудку, картофель и морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12566,'Сладкий болгарский перец нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12566,'Выложить слоями овощи, разобранное на волокна мясо, перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12566,'Все слои промазать сеточками из майонеза.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12566,'Куриные яйца разрезать пополам, желтки вынуть, размять вилкой, перемешать с рубленым чесноком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12566,'Массой нафаршировать белки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12566,'Выложить на слой перца, смазать майонезом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12566,'Натереть сыр, посыпать салат.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12567,'Отварить курицу, филе нарезать полосками, перец и помидоры – кубиками, натереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12567,'В майонез добавить специи и чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12567,'Выложить продукты слоями: курица, нарезанные помидоры, болгарский перец, сухарики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12567,'Промазывать майонезом с чесноком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12567,'Посыпать тертым сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12568,'Куриное мясо посолить, натереть смесью перцев.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12568,'Продукт запечь в духовом шкафу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12568,'В готовом виде нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12568,'Отварить куриную печень, остудить в той же воде, в которой она варилась.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12568,'Репчатый лук нарезать и обжарить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12568,'Отварить яйца, разрезать, вынуть желтки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12568,'Печень, желтки, лук взбить блендером в однородную массу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12568,'Нафаршировать белки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12568,'Соленые огурцы нарезать кубиками, потереть сыр.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12568,'Ингредиенты выложить слоями: курица, огурцы, консервированная фасоль, консервированные грибы, промазать майонезом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12568,'Выложить яйца, полить майонезом и посыпать тертым сыром.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12569,'Отварить куриные яйца, мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12569,'Нарезать кусочками вместе с сыром, покрошить грибы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12569,'Выложить продукты слоями, промазать майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12569,'Посыпать блюдо тертым сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12570,'Репчатый лук нарезать, замариновать в разведенном уксусе с сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12570,'Куриное филе и шампиньоны нарезать полосками, обжарить с солью и специями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12570,'Отварить яйца и картофель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12570,'Картофель натереть, яйца разрезать пополам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12570,'Приготовить начинку из майонеза, чеснока, желтков.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12570,'Заполнить белки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12570,'Выложить продукты слоями: отваренная курица, лук, майонез, нарезанные грибы, тертый картофель, майонез.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12570,'Выложить яйца на основную массу, посыпать тертым сыром, зернами граната.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12571,'Нарезать говядину небольшими кусочками, слегка обвалять в муке, быстро зажарить в сильно прогретом масле до появления темной корочки. Влить в сковороду бульон, всыпать порезанный мелкими кубиками лук, дать закипеть, уменьшить нагрев, прикрыть крышкой, готовить около часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12571,'Подготовить и нарезать морковку, стебель сельдерея, картофель, соединить с мясом, добавить молотый перец, перемешать. Тушеная говядина с картофелем и сельдереем будет готова примерно через полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12572,'Отварить куриную грудку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12572,'Потереть яйца, часть разрезать пополам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12572,'Перемешать растертые желтки с майонезом, наполнить половинки белков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12572,'Нарезать кубиками отваренную курицу и картофель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12572,'Выложить продукты слоями: курица, картофель, свежие огурцы, яйца.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12572,'Ингредиенты промазывать майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12572,'Выложить фаршированные яйца, смазать майонезом, посыпать тертым твердым сыром.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12573,'Измельчаем лук и ножки грибов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12573,'Обжариваем лук и ножки грибов до готовности, солим и перчим.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12573,'Смазываем форму и шляпки шампиньонов растительным маслом. Солим шляпки внутри.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12573,'Готовим начинку: добавляем к фаршу яйцо, обжаренные ножки грибов с луком, добавляем соль и перец. Перемешиваем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12573,'Из фарша формируем фрикадельки по размеру шляпок грибов, немного уплотняя его и вкладываем в шляпки грибов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12573,'Отправляем в разогретую духовку на температуру 190-200 градусов примерно на 30 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12573,'Извлекаем, посыпаем натертым на мелкой терке сыром и отправляем в духовку еще минут на 5-10.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12574,'Отварить картофель, морковь, яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12574,'Все продукты, включая копченую куриную грудку, мелко порезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12574,'Для приготовления соуса понадобится майонез, лимонный сок, розмарин, белый перец, мускат, сахарный песок, давленый чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12574,'Выложить салат слоями на красивое блюдо: курица, соус с майонезом, картофель, соус, тертая морковь, нарезанное яблоко.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12574,'Далее – шампиньоны, соус, половинки яиц и остатки соуса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12574,'Готовое блюдо посыпать тертым сыром.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12575,'Слить из ананасов сок, переложить в блендер, измельчить, переложить в дуршлаг, дать стечь лишнему соку. Залить на треть часа кипятком мелко нарубленный фиолетовый лук, потом процедить. Для заправки хорошо перемешать сметану с майонезом, натереть вареные яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12575,'Салат с ананасом и вареными креветками разложить по порционным салатникам в следующем порядке: яйца, лук, креветки, ананасы, яйца. После каждого слоя добавлять заправку, верх оформить стружкой сыра и крупной ореховой крошкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12576,'Куриное мясо, картофель и яйца отварить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12576,'Продукты очистить и мелко нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12576,'Покрошить маринованные огурцы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12576,'Нарезать репчатый лук и грибы, обжарить на сковороде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12576,'Выложить салат слоями: картофель, маринованные грибы, филе курицы, огурцы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12576,'Продукты промазывать майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12576,'Разрезать пополам яйца, выложить на салат желтками вниз, полить майонезом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12576,'Украсить тертым сыром.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12577,'Отварить яйца и куриное филе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12577,'Мясо нарезать небольшими кубиками, яйца и твердый сыр натереть на терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12577,'Выложить слоями: картофель фри, курицу, майонез, тертые яйца, майонез, сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12577,'Поставить блюдо в холод и дать пропитаться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12578,'Отварить яйца, куриное мясо, картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12578,'Репчатый лук и мясо нарезать длинными тонкими полосками. Обжарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12578,'Натереть картофель, яйца разрезать пополам, огурец нашинковать соломкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12578,'Порубить ножом зелень и чеснок, перемешать с майонезом и желтками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12578,'Половинки белков нафаршировать желтковой массой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12578,'Выложить слоями: мясную обжарку, картофель, огурцы, яйца.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12578,'Слои промазать майонезом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12578,'Салат посыпать тертым сыром.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12579,'Отварить яйца и картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12579,'Нарезать репчатый лук, залить его винным уксусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12579,'Натереть чеснок и картофель, вареные яйца разрезать пополам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12579,'Вынуть желток, раскрошить, перемешать с майонезом, заправить чесноком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12579,'Готовой массой нафаршировать половинки яиц.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12579,'Куриное мясо нарезать, обжарить на сковороде с маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12579,'Салат выложить на тарелку слоями: курица, лук, картофель, яйца, майонез.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12579,'Блюдо посыпать сыром.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12580,'Отварить мясо, нарезать полосками или разобрать руками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12580,'Яйца отварить и разрезать вдоль пополам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12580,'Желтки покрошить, растереть с куркумой и майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12580,'Наполнить смесью белки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12580,'Свежие шампиньоны нарезать пластинками, обжарить с репчатым луком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12580,'Выложить салат слоями: готовая морковь по-корейски, куриное мясо, майонез, грибная обжарка, майонез, яйца.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12580,'Сверху – майонез и сыр.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12581,'Дно формы застелить кружочком пергамента, бока смазывать не надо. Вбить в чашу миксера яйца, всыпать чуть соли, добавить сахар, минут за 5 взбить в белоснежную пену (сахар должен раствориться весь).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12581,'В миску насыпать какао с кофе, влить сметану с маслом, хорошо все смешать с яичной массой. Добавить к полученному составу муку, просеянную и смешанную с ванилью и разрыхлителем, с тщательностью вымешать до получения жидкого теста.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12581,'Вылить в форму в 14 см диаметром, отправить в духовой шкаф с температурой 160 градусов примерно минут на 40,  временами проверяя готовность коржа тоненькой, как зубочистка,  палочкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12581,'Достать форму, вынуть, проведя острым ножом по окружности формы, бисквитную основу для очень вкусного шоколадного торта, прикрыть проволочной решеткой и перевернуть на нее корж, дать остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12581,'Разрезать бисквит вдоль на 4-5 коржей. Это сделать будет довольно просто, поскольку бисквит хорошо поднимается за счет сухих несмазанных стенок формы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12598,'Перемешать ингредиенты в салатнице, по вкусу заправить майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12581,'Приготовить из взбитой 20% сметаны и сахара крем. Измельчить снятый корж-верхушку до состояния крошки, отложить в сторону.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12581,'Оставшиеся коржи промазать джемом из смородины (лучше черной), а поверх – кремом из сметаны, сложить их стопкой, обсыпать бока крошкой от коржа, оформить верх по своему усмотрению.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12582,'Отварить яйца и куриное мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12582,'Курицу нарезать тонкой соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12582,'Вареные яйца разрезать вдоль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12582,'Из майонеза и желтков приготовить начинку, наполнить белки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12582,'Выложить слоями: куриное мясо, майонез, тертое яблоко, консервированная кукуруза, половинки яиц, майонез, тертый сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12582,'Готовый салат поставить в холод для пропитывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12583,'Отварить морковь, яйца, картофель, куриное мясо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12583,'Нарезать репчатый лук, замариновать в разведенном водой яблочном уксусе с сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12583,'Натереть на терке морковь, картофель, яблоко, желтки и белки – отдельно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12583,'Выложить продукты на блюдо в следующем порядке: измельченный картофель, майонез, лук, отцеженный от маринада, курицу, майонез, тертую морковь, майонез, тертое яблоко, желтки, белки, майонез.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12583,'Посыпать блюдо сыром «Пармезан».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12584,'Отваренное куриное мясо, соленые огурцы и чернослив измельчить соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12584,'Натереть репчатый лук, сырую морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12584,'Разрезать на две части вареные яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12584,'Желтки отделить, добавить майонез, нафаршировать белки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12584,'Собрать салат: на дно тарелки выложить мясо курицы, затем нарезанные соленые огурцы, репчатый лук, морковь, консервированный зеленый горошек, чернослив и яйца.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12584,'Все слои промазать майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12584,'Блюдо посыпать тертым сыром.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12585,'Разрезать куриное мясо на небольшие полоски, поперчить, посолить, оставить для пропитывания на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12585,'Продукт промыть и отварить до готовности в подсоленной воде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12585,'Свежую морковь натереть на терке длинными полосками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12585,'Белокочанную или пекинскую капусту нарезать, посыпать солью и перцем, помять руками до появления сока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12585,'Натереть плавленый сыр, перемешать с майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12585,'Ингредиенты соединить, добавить консервированную кукурузу, заправить майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12585,'Готовый салат украсить сверху сырно-майонезной смесью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12585,'Поставить в холодильник на два часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12586,'Чеснок пропустить через пресс, добавить растительное масло (2 ст. л.), прованские травы, приправу, филе кролика и перемешать. Оставить на 1 час',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12586,'Лук и морковь нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12586,'Филе кролика обжарить на среднем огне 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12586,'На растительном масле обжарить лук и морковь на среднем огне 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12586,'Соединить с мясом, добавить сметану, молоко,соль и тушить под крышкой 30 минут на медленном огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12587,'Картофель натереть на мелкой терке и отжать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12587,'Добавить яйцо, муку, мелко нарезанный укроп и петрушку, чеснок пропущенный через пресс, лук натереть на терке - перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12587,'Куски свинины посолить и поперчить с двух сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12587,'Выложить картофель на мясо с двух сторон и обжарить куски на растительном масле с двух сторон на среднем огне до золотистого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12587,'Выложить на мясо на противень, смазать верх сметаной и отправить в духовку на 30 минут при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12588,'Расстелить пластинку лаваша, промазать плавленым сырком (толщину выбрать по вкусу), присыпать натертыми или порубленными яйцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12588,'Завершить все слоем из раскатанных крабовых палочек, покрытых майонезом и присыпанных поверх зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12588,'Аккуратно все свернуть в рулет и отправить ночевать рулет с крабовыми палочками и плавленым сыром в холодильник. Можно конечно приступить к дегустации и через пару-тройку часов, но вкус не будет таким нежным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12599,'Разрезать помидоры на несколько частей, разложить в тарелке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12599,'Продукт побрызгать яблочным уксусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12589,'Смешать: яйца, молоко, соль и перец. Хлеб обмакнуть в яично-молочную смесь и обжарить хлеб на растительном масле до золотистого цвета с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12589,'В форму для запекания выложить половину готового хлеба в 1 ряд. На хлеб выложить по ломтику плавленного сыра для сэндвичей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12589,'На сыр выложить нарезанные кусочки болгарского перца и ветчины. Слегка посолить и поперчить. Выложить еще слой сыра и накрыть оставшимся хлебом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12589,'Смазать верх майонезом и посыпать твердым тертым сыром. Запекаем в духовке 20 минут при температуре 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12590,'Лук нарезать кубиками и обжаривать 5 минут на растительном масле на сильном огне - перемешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12590,'Шампиньоны нарезать соломкой, добавить к грибам и жарить 15 минут на среднем огне - перемешивая. Остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12590,'Куриное филе измельчить в блендере. Соединить с грибами - посолить и поперчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12590,'Белки отделить от желтков. Желтки взбить в легкую пену. Сливки и белки добавить к курице.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12590,'Формы смазываем сливочным маслом, посыпать панировочные сухари. Наполнить формы куриным суфле.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12590,'Формочки поставить в воду, чтобы вода была закрыта половиной воды. Ставим в духовку на 35 минут при температуре 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12591,'Бананы очистить от кожуры, измельчить погружным блендером. Добавить кокосовую стружку, кунжут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12591,'Яйца взбить и добавить к бананам - перемешать. Добавить растительное масло - перемешать, оставить на 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12591,'Оладьи выпекать на сковороде на медленном огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12592,'В кастрюле смешать муку и сливки. Добавить ванилин, крупные куски цедры, сахарную пудру и перемешать. Ввести желтки яиц - перемешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12592,'Поставить на огонь и варить до загустения, постоянно помешивая, чтобы не пригорело! Потом вынуть цедру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12592,'Слоеное тесто свернутое в рулет нарезать и выложить в формочки для кексов распределив тесто по стенкам. Внутрь теста выложить крем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12592,'Ставим в разогретую до 200 градусов духовку на 30 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12593,'Курицу нарезать кубиками. Обжарить на растительном масле и обжаривать 7 минут на среднем огне, перемешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12593,'Лук нарезать кубиками, добавить к курице и обжаривать еще 7 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12593,'Пропустить через пресс чеснок, готовить еще 2 минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12593,'Добавить муку - перемешать. Влить томаты перекрученные через мясорубку, добавить кукурузу - перемешать. Готовим 7 минут, периодически перемешивая, чтобы соус не пригорел.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12594,'Для начало приготовим соус. В блендер добавим подогретый мёд, устричный соус, сладкий Чили соус, имбирь натёртый, чеснок, цедру и сок лайма, паприки и взобьём до однородной массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12594,'После начнём разогревать сковородку и добавим масло. Пожарим курицу и за 2-3 минуты до готовности залить соус и жарить ещё минуты 2-3 и посыпать кунжутом .',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12595,'Отварить куриные яйца, мелко порезать вместе с маринованными огурцами и репчатым луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12595,'Добавить консервированный зеленый горошек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12595,'Заправить растительным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12596,'Ялтинский лук замариновать в уксусе, посолить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12596,'Морковь, свеклу и картофель отварить и нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12596,'Любую рыбу запечь в фольге, остудить и нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12596,'Для соуса перемешать натуральный йогурт, сметану, зернистую горчицу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12596,'Массу взбить при помощи венчика.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12596,'Продукты перемешать, добавить соленые огурцы, заправить соусом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12596,'Готовый салат охладить и подать к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12597,'Отварить свеклу, натереть и перемешать с квашеной капустой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12597,'Яблоко любого сорта порезать кубиками небольшого размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12597,'Порубить чеснок и зелень петрушки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12597,'Все ингредиенты перемешать, заправить оливковым маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12597,'Украсить блюдо кубиками сыра «Фета».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12598,'Куриное мясо отварить, руками разобрать на волокна.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12598,'Нарезать кубиками сыр, сладкий перец и помидоры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12598,'Мелко покрошить петрушку и чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12599,'Порезать очищенный чеснок, порубить зелень петрушки, кинзы, укропа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12599,'Чеснок, зелень и сыр перемешать отдельно, украсить помидоры.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12599,'Закуску сразу подать к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12600,'Огурцы-корнишоны, сладкий болгарский перец, помидоры нарезать небольшими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12600,'Оливки без косточек – кружками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12600,'Открыть банку с консервированной фасолью, слить жидкость.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12600,'Крупно порезать любую зелень и листья салата.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12600,'Очищенный чеснок пропустить через пресс.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12600,'Салат побрызгать яблочным уксусом, полить растительным маслом и перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12600,'Выложить на тарелку целые листья зеленого салата, выложить основную массу, посыпать семечками льна, обжаренным кунжутом и ароматными травами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12601,'Отварить рис, куриные бедра и яйца',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12601,'Уложить на плоское блюдо кольцо, а в него положить первый слой: рис, заправленный смесью майонеза со сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12601,'Далее выложить слой из кубиков крабовых палочек с одним майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12601,'Положить следующий слой из консервированной кукурузы и майонеза.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12601,'Уложить мясной слой из кубиков курятины, заправленной смесью сметаны и майонеза.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12601,'Курицу накрыть слоем маринованных грибов и сметаны. На них выложить заключительный слой тертых яиц и пару оставить для  присыпки салата по бокам.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12601,'Убрать полученное сооружение в холодильник, чтобы за ночь, как следует, пропитался.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12601,'Достать салат, снять кольцо, оформить верхушку кусочками ананаса и яйцами, при желании композиции можно придать завершенность веточками зелени.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12602,'Нарезать соломкой ветчину, огурцы, помидоры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12602,'Сыр по желанию можно натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12602,'Все ингредиенты перемешать в салатнице.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12602,'Посолить, поперчить, посыпать зеленью и любимыми специями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12602,'Массу заправить сметаной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12603,'Картофель отварить, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12603,'Покрошить свежий огурец, репчатый лук, шампиньоны, твердый сыр, буженину.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12603,'Продукты перемешать, побрызгать лимонным соком, всыпать много рубленой зелени, рубленые грецкие орехи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12603,'Блюдо заправить майонезом, перемешать и оставить на полчаса для пропитывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12604,'Апельсины хорошо вымыть, сделать надрезы по кругу в виде зубчиков, аккуратно снять чашечки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12604,'Мякоть нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12604,'Отварить и остудить брокколи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12604,'Нарезать кусочками отваренное мясо, огурцы, капусту.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12604,'Добавить апельсин, зелень, майонез.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12604,'Массой нафаршировать кожуру апельсинов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12605,'Нарезать кубиками одного размера филе сельди, яблоко, соленые огурцы, отваренные картофель и морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12605,'Яблоко очистить от семенных камер и кожуры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12605,'Продукты выложить в салатницу, полить майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12606,'Репчатый лук нарезать, залить кипятком, добавить сахарный песок, соль, уксус.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12606,'Оставить до остывания и для пропитывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12606,'Отцедить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12606,'Отварить куриное филе, остудить в бульоне, разобрать на волокна руками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12606,'Натереть маринованные огурцы, плавленый сыр, вареный картофель.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12606,'Отварить куриные яйца, разобрать на желтки и белки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12606,'Белки натереть, желтки размять или натереть на мелкой терке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12606,'Выложить салат слоями: картофель, майонез, маринованный лук, огурцы, майонез, курица, майонез, желтки, майонез.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12606,'Соус лучше выкладывать в виде сеточки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12606,'Сверху – тертый плавленый сыр и белки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12606,'Поставить на два часа в холодильник.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12607,'Очистить от кожуры яблоки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12607,'Нарезать кубиками вместе с бананами, киви, консервированными или свежими ананасами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12607,'Пересыпать в салатницу, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12607,'Смесь можно разместить в фужерах, полить натуральным йогуртом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12608,'Отварить картофель и морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12608,'Маринованные грибы порубить небольшими кусочками, свежие огурцы нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12608,'Покрошить репчатый лук. Этот продукт можно заранее замариновать в кипящей воде с перцем и солью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12608,'Все ингредиенты перемешать, добавить зеленый горошек, заправить по вкусу майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12609,'Отварить морковь и картофель, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12609,'Соленые огурцы и вареную колбасу покрошить, то же самое сделать с отваренными яйцами, луком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12609,'Добавить зеленый горошек из банки, заправить майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12609,'Соль и молотый перец – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12609,'Массу выложить в форму, оставить на двадцать минут для пропитывания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12609,'Форму осторожно снять.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12610,'Сварить рис, опираясь на инструкцию на упаковке, залить смесью уксуса, соли и сахара, осторожно размешать, как бы многократно разрезая смесь деревянной лопаточкой, дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12610,'Взбить с солью и перцем яйца, пожарить тоненькие блинчики, порезать длинной соломкой. Для остроты можно добавить смесь майонеза с васаби 4  ст.л на 1 ч.л..',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12610,'Сварить и почистить креветки, очищенное авокадо нарезать тонкими пластинками. Рыбу порезать на тонкие ломтики, если в наличии свежая семга, то добавить перец, соль и сахар, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12610,'Нори порезать на круги по размеру формы, в которой будет формироваться суши-торт «Три икринки»',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12610,'Разделить холодный рис на 4 горки. В смазанную маслом форму уложить послойно: креветки, рис, майонез, кружок нории, пластинки авокадо, опять рис с майонезом,',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12610,'нории, рыба, снова рис и майонез, третий кружок нори, соломку из омлета, рис и майонез, последний кружок нори. Каждый слой выкладывать и прижимать, верх формы прикрыть пленкой, на час  (не меньше) отправить в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12610,'Охлажденный торт накрыть блюдом и перевернуть, удалить форму, оформить икрой, петрушкой, по краю выложить нори, присыпать семенем кунжута. При подаче кусочки в каждой тарелке сдобрить соевым соусом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12611,'Измельчить помидоры, репчатый лук, красный болгарский перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12611,'Потушить овощную стружку с маслом на сковороде в течение десяти минут, остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12611,'Открыть банку с консервами, слить жидкость, рыбу нарезать ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12611,'Из готового размороженного теста раскатать лепешки, положить начинку из рыбы и овощей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12611,'Расстегаи переложить на противень, смазать взбитым яйцом, печь при температуре 200 градусов до образования золотистой хрустящей корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12612,'Разморозить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12612,'Клубни картофеля очистить, отварить в подсоленной воде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12612,'Репчатый лук нарезать и спассеровать до золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12612,'Из картофеля приготовить пюре, перемешать с обжаркой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12612,'Рыбное филе нарезать кубиками, перемешать с начинкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12612,'Тесто нарезать квадратами, выложить смесь с рыбой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12612,'Сформовать пирожки с открытой начинкой, положить по кусочку сливочного масла на расстегай.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12612,'Изделия смазать яйцом, печь при температуре 200 градусов до полной готовности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12613,'Для теста перемешать муку, дрожжи, сахарный песок, соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12613,'Влить теплую воду, растительное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12613,'Тесто вымесить, скатать в шар, оставить в тепле на час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12613,'Отварить щуку, мясо отделить от костей, обжарить на сковороде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12613,'Нарезать репчатый лук, спассеровать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12613,'Семгу нарезать кусочками, по штуке на изделие.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12613,'Ингредиенты, кроме семги, перемешать, посолить, поперчить, добавить рыбные специи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12613,'Тесто раскатать на лепешки, выложить начинку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12613,'Сформовать полуоткрытые пирожки, положить по кусочку семги.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12613,'Изделия смазать яйцом, печь при температуре 200 градусов, время – 20 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12614,'Твердый сыр и лосось нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12614,'Вбить сырые желтки, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12614,'Из готового слоеного теста нарезать квадраты, в центр выложить начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12614,'Пирожки защипнуть в виде расстегаев, выложить на противень и смазать яйцом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12614,'Печь в духовке при температуре 200 градусов до появления корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12615,'Несоленое сало нарезать брусками или кубиками, обжарить на тихом огне до появления шкварок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12615,'Кастрюлю с толстым дном поставить на огонь, можно использовать чугунок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12615,'Влить воду, положить поварскую соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12615,'Часть жира перелить в кастрюлю.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12615,'Жидкость нагреть, всыпать белую кукурузную муку грубого помола.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12615,'Если используется крупа, то ее нужно несколько раз промыть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12615,'Продукты перемешать, крупинки должны набухнуть, масса получится густой и вязкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12615,'Если каша не готова, то в нее можно подлить воду и еще немного потушить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12615,'За две-три минуты до готовности нагрев увеличить до максимума.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12615,'Емкость перевернуть резким движением, выложить кашу на большое плоское блюдо, придать руками любую форму.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12615,'Готовое блюдо украсить кусочками сыра «Сулугуни» или «Адыгейский».',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12616,'В казан влить воду, нагреть до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12616,'Посолить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12616,'В кипящую воду всыпать кукурузную муку, помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12616,'Всыпать продукт в несколько приемов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12616,'Продолжать помешивать, каша не должна подгореть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12616,'Нагрев снизить, прогревать до тех пор, пока мамалыга не перестанет отставать от стенок посуды.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12616,'Время приготовления – от 10 до 15 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12616,'Казанок встряхнуть, опрокинуть на тарелку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12616,'Выложить продукт в чашки, залить горячим молоком и подать на стол.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12617,'Влить в толстостенную кастрюлю или казан воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12617,'Посолить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12617,'Довести до кипения, всыпать тонкой струйкой кукурузную крупу, состав перемешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12617,'Продукт не должен подгореть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12617,'Огонь уменьшить, прогревать 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12617,'Вместо крупы можно использовать муку, время приготовления сократится вдвое.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12617,'Мамалыгу разложить в тарелки, положить по кусочку сливочного масла.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12617,'Подавать с сыром сулугуни.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12618,'Всыпать крупу в чашу, влить кипящую воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12618,'Посолить, положить сливочный жир.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12618,'Молотый перец – по вкусу и желанию.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12618,'Мультиварку закрыть, выставить режим «Каша» на 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12618,'Грибы обжарить в масле отдельно, жидкость должна испариться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12618,'Кашу выложить на большую тарелку, украсить грибами, посыпать тертой брынзой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12619,'Отварить кукурузную муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12619,'Противень смазать сливочным или оливковым маслом, выложить кашу, разровнять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12619,'Отдельно протереть творог через сито, вбить яйцо, перемешать, выложить вторым слоем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12619,'Продукты посыпать сахарным песком, полить густой домашней сметаной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12619,'Поставить блюдо в духовой шкаф на 20 минут, температура приготовления – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12620,'Подсушить булку, можно подержать в духовке. На терке с мелкими отверстиями протереть булку, с более крупными отверстиями – сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12620,'Подготовить грибы, порезать на средние пластинки, обжарить на сливочном масле,  помидоры нарезать ломтиками, лук – на мелкие кубики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12620,'Уложить в смазанную форму с высокими бортиками помидоры, присыпать черным перцем и солью, прикрыть грибами с луком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12620,'В высокую миску влить молоко, добавить топленое масло, хорошо взбить, равномерно полить вкусную закуску «Помидоры с грибами и сыром», присыпать сырной стружкой и измельченной булкой. Отправить в духовку, подавать к столу прямо в форме.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12621,'Толстостенную кастрюлю наполнить водой, добавить соль, сливочное масло, нагреть до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12621,'Всыпать муку или крупу, массу постоянно помешивать. Время прогревания – 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12621,'Кушанье переложить на доску или полотенце.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12621,'Нарезать на порции суровой ниткой или деревянным ножом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12621,'Подать блюдо к столу со свиными шкварками, козьим молоком, тушеным мясом или чесночным соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12622,'Клубни картофеля промыть, очистить, натереть на терке с мелкой решеткой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12622,'Массу переложить в дуршлаг, лишняя жидкость должна стечь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12622,'Разогреть на сковороде оливковое масло, выложить картофель в виде котлет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12622,'Соль и молотый перец – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12622,'Обжарить с двух сторон до получения румяной корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12623,'Клубни картофеля очистить и натереть, проварить две или три минуты, отбросить на дуршлаг, затем выложить на бумажное полотенце для удаления лишней жидкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12623,'Натереть репчатый лук, переложить в картофельную массу, вбить яичный белок, добавить муку и соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12623,'Вымесить тесто, сформовать небольшие котлеты, обвалять в панировке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12623,'Обжарить хашбраун во фритюре по шесть минут с каждой стороны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12624,'Натереть лук и очищенные клубни картофеля, посолить, приправить, влить растительное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12624,'Массу отжать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12624,'Смесь выложить на заранее прогретую сковороду с остатками масла, разровнять, жарить по три минуты с двух сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12624,'Вбить яйца сверху, поставить емкость в духовой шкаф. Температура приготовления – 250 градусов, время – 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12624,'На тарелку положить бекон, прикрыть бумажным полотенцем, поставить в СВЧ-печь. Время прогревания – три минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12624,'Выложить жареный бекон на яйца, посыпать тростниковым сахаром.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12624,'Подержать блюдо под крышкой в течение двух минут, сахар должен растопиться.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12625,'В кастрюлю налить воду, положить очищенный картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12625,'Варить клубни в течение получаса до мягкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12625,'Воду слить, картофель охладить и на ночь поставить в холодное место.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12625,'Клубни натереть, посолить, поперчить, сформовать котлеты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12625,'Жарить с двух сторон до румянца.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12626,'Взять кусочек хлеба, из которого обычно делают тосты, но если его нет, то можно использовать обычный, тонко порезанный, белый хлеб. Смазать его равномерно любой шоколадной пастой и накрыть кружочками желтого банана (зеленый может быть немного терпким на вкус).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12626,'Прикрыть все вторым кусочком хлеба и обжарить шоколадный бутерброд с бананом со сливочным маслом. Обжаривание размягчит банан, он лучше смешается с пастой, что и придаст бутербродному десерту неповторимый вкус.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12627,'Картофель очистить и натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12627,'Воду довести до кипения, положить картофель на две минуты, откинуть на дуршлаг.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12627,'Сладкий перец нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12627,'Картофель отжать, перемешать с перцем, солью, специями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12627,'Отдельно взбить яйца, вмесить муку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12627,'Из картофельной массы сформовать шарики, выложить на прогретую сковороду с горячим сливочным маслом, полить кляром.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12627,'Через шесть минут изделия перевернуть на другую строну.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12627,'Это нужно делать аккуратно, изделия не должны распасться.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12628,'Отличный десерт для поддержания иммунной системы взрослых и малышей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12628,'Плоды среднего или крупного размера хорошо промыть, удалить семенные камеры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12628,'Сливочное масло нарезать кусочками, положить внутрь плодов, добавить по ложке сахарного песка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12628,'Каждый фрукт аккуратно завернуть в фольгу, положить в духовой шкаф. Время запекания – 25 минут, температура – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12629,'Фрукты одного размера с зеленой плотной кожицей промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12629,'Плоды обсушить бумажным полотенцем, сердцевину вымыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12629,'Яблоки расположить на противне или в форме для запекания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12629,'В получившиеся после удаления сердцевины лунки всыпать ванилин из пакетика, положить по ложке меда, поставить в духовку на полчаса или 45 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12629,'Время запекания зависит напрямую от величины плодов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12629,'Готовые плоды переложить на блюдо, вытекший сок с противня подлить к яблокам.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12630,'Плоды промыть и обсушить полотенцем, разрезать пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12630,'Семена с перегородками удалить острым ножом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12630,'Получившиеся лодочки посыпать корицей, наполнить медом, цветочным или гречишным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12630,'Плоды выложить на противень, застеленный фольгой, поставить в духовку. Время выпекания – 20 минут, температура – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12630,'Блюдо подать горячим.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12631,'Кисло-сладкие яблоки сорта «Гольден» или «Гренни Смит» сбрызнуть лимонным соком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12631,'Выложить в форму для запекания, влить немного воды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12631,'Поставить десерт в духовку на 15 минут, температура – 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12631,'Плоды должны стать мягкими, время запекания может быть дольше, это зависит от размера и сорта.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12631,'Десерт вынуть из духовки и присыпать сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12632,'Очистить и обжарить любые грибы с добавлением, для подчеркивания вкуса, щепотки молотой гвоздики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12632,'Сварить курицу и яйца, остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12632,'Хорошо охлажденное мясо порезать на небольшие ровные кубики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12632,'Яйца и огурец измельчить на терке, лучше с крупными отверстиями, сыр – с мелкими. Для окончательно оформления часть сыра нарезать на небольшие одинаковые прямоугольнички – это будущие клавиши рояля.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12632,'На сервировочное блюдо салат «Белый рояль» выкладывают слоями, промазывая каждый майонезом, придерживаться необходимо следующего порядка: курятина, обжаренные грибы, огурцы, яйца, сыр. Слой из курицы и огурцов можно по желанию чуть подсолить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12632,'Дальше оформить салат в виде рояля, добавив десяток маслин, розочки из тонких ломтиков салями и вырезанные ранее сырные клавиши.  Но можно, повинуясь полету фантазии, оформить и как-нибудь по-своему.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12633,'Плоды вымыть и обсушить, удалить сердцевину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12633,'Зернистый творог протереть через сито или взбить при помощи блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12633,'Добавить желток, корицу, сухофрукты, ванилин из пакетика.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12633,'Перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12633,'Вместо сахара можно положить мед или светлый изюм без косточек.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12633,'Нафаршировать плоды, выложить в форму небольшого размера, поставить в духовку. Температура запекания – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12634,'Прокрутить через мясорубку помидоры, варить на тихом огне полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12634,'Всыпать горчичный порошок, добавить гвоздику, красный и черный молотый перец – по вкусу и желанию.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12634,'Натереть хрен, добавить в общую массу вместе с солью, сахарным песком, кипятить десять минут, влить столовый уксус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12634,'Стерилизовать банки, влить приправу, закатать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12634,'Хранить при комнатной температуре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12635,'Корни хрена очистить, натереть на терке, прокрутить через мясорубку или воспользоваться кухонным комбайном.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12635,'Приготовить маринад из воды, соли и сахара.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12635,'Довести раствор до кипения, влить уксус, перемешать, снять с огня.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12635,'Маринад остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12635,'Хрен залить полученной жидкостью, разложить в банки, закрыть крышками, поставить в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12636,'Приготовить маринад из соли, сахара, укуса и воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12636,'Довести жидкость до кипения, затем остудить до комнатной температуры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12636,'Хрен подержать в холодной воде, очистить, перебить в блендере.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12636,'Отварить и измельчить таким же образом свеклу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12636,'Компоненты соединить, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12636,'По желанию ингредиенты можно еще раз пропустить через блендер.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12636,'Разложить массу в стерильные банки, закрыть крышками, хранить до зимы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12637,'Хрен превратить в пюре любым доступным способом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12637,'Добавить по вкусу соль и сахарный песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12637,'Довести воду до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12637,'Массу разложить в небольшие банки, сверху всыпать лимонную кислоту, влить воду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12637,'Закатать до остывания, перевернуть и укутать на ночь пледом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12638,'Вымыть томаты, разрезать, пропустить через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12638,'Очистить чеснок, натереть или пропустить через чеснокодавку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12638,'Очистить хрен, пропустить через мясорубку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12638,'Продукты перемешать, соль – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12638,'Разложить хреновину в сухие стерильные банки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12638,'Сверху налить растительное масло слоем в 1 см, закрыть крышками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12638,'Поставить емкости в прохладное место.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12639,'Хрен пропустить через мясорубку, перемешать с солью и сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12639,'Разложить кашицу в банки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12639,'Плоды лимона вымыть, обсушить полотенцем, нарезать кружками вместе с кожурой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12639,'Положить по кусочку в каждую банку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12639,'Воду вскипятить, разлить в емкости.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12639,'Поставить банки в кастрюлю с кипятком, прогревать пять или десять минут, закатать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12640,'Растереть в глубокой миске сметану и яйца с творогом, всыпать муку, замесить однородную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12640,'Растопить в небольшом сотейнике на водяной бане масло и кусочки шоколада, дать остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12640,'Взбить блендером яйца, добавить сахар и ванильный сахар, перемешать, объединить с шоколадным маслом, всыпать муку, перемешать до получения шоколадного теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12640,'Выложить на дно смазанной формы шоколадное тесто, а на него – творожное, нарисовать зубочисткой  на поверхности творожно-шоколадной запеканки сеточку разводов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12640,'Поставить форму в прогретую примерно до 180 градусов духовку на 50-60 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12641,'Зеленые яблоки нарезать дольками, удалить семена.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12641,'Продукт запечь в микроволновой печи в течение трех минут. Кожицу снять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12641,'На мелкой терке натереть хрен и чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12641,'Добавить в яблоки, перебить массу при помощи погружного блендера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12641,'Соус посолить по вкусу, добавить сахар, уксус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12641,'Разложить продукт в стерильные небольшие банки, закрыть крышками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12641,'Хранить в прохладе.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12642,'Помидоры вымыть и нарезать, удалить семена.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12642,'Чеснок очистить, зубчики разрезать пополам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12642,'Хрен замочить в холодной воде, очистить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12642,'Пропустить продукты через мясорубку, разложить в чистые банки, закрыть прокипяченными крышками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12642,'Хранить в холодильнике.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12643,'В емкость мультиварки всыпать сухую манную крупу, добавить по вкусу сахарный песок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12643,'Положить кусочек сливочного масла, соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12643,'Влить молоко, смесь хорошо перемешать так, чтобы не было комочков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12643,'Выставить режим «Тушение», кашу помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12643,'Время приготовления – полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12644,'Изюм без косточек, курагу или чернослив хорошо промыть, замочить в теплой воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12644,'Влить в мультиварку молоко, выставить режим «Тушение» на пятнадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12644,'Отдельно, в небольшой емкости, перемешать манку и сахар, соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12644,'В закипевшее молоко всыпать крупу, массу постоянно помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12644,'Добавить изюм или другие сухофрукты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12644,'Крышку закрыть, через две минуты прогревания кашу перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12645,'Крупу просеять и обжарить две минуты до легкого золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12645,'Тыкву очистить от семян, мякоть натереть на крупной терке или нарезать кубиками небольшого размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12645,'Смазать чашу мультиварки сливочным маслом, влить воду и молоко.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12645,'Всыпать манку, соль, сахар, тыкву.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12645,'Выставить режим «Каша» на полчаса. Блюдо помешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12646,'Подготовить форму,  включить прогреваться духовку до температуры чуть ниже 190 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12646,'Разбить в миску с высокими бортиками яйца, взбить до появления крепкой пены около 5 минут, всыпать по частям сахар, после каждой порции продолжать взбивать до растворения сахара и образования густой массы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12646,'В другой миске смешать крахмал с просеянной мукой, добавить смесь из яиц, осторожно и тщательно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12646,'Взболтать растопленное масло с водой, добавить к полученному тесту, перемешать, вылить в форму, убрать в духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12674,'Готовую кашу перемешать, выложить в тарелки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12702,'Печь при температуре 200 градусов, время – три четверти часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12646,'Через треть часа пышный бисквит будет готов. Порезать готовый и полностью охлажденный десерт на куски, а можно разрезать на коржи и промазать по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12647,'Смазать чашу маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12647,'Всыпать сухое молоко и манную крупу, соль и сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12647,'Влить воду, хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12647,'Закрыть крышку, выставить режим «Тушение» на тридцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12648,'Емкость промазать сливочным маслом, влить воду и молоко, выставить режим «Молочная каша» на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12648,'Манку перемешать с сахаром и через десять минут после начала приготовления всыпать в молочную смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12648,'Блюдо помешивать, оно будет готово через двадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12649,'Поломать вафли, порубить (часть оставить целиком) орехи, добавить нутеллу,  хорошо перемешать до густой однородной массы, убрать миску с начинкой в холодильник, чтобы она затвердела.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12649,'Из хорошо охлажденной массы скатать шарики, вставить внутрь по цельному ореху и опять поставить их в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12649,'Поломать плитку шоколада, растопить на водяной бане, достать затвердевшие шарики',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12649,'Насаживать на тонкую деревянную палочку и погружать в шоколад. Разложить шарики для схватывания шоколадного покрытия (удобнее это сделать на решетке), отправить для застывания в холодильник. При желании, пока шоколадное покрытие не застыло, конфеты можно еще обвалять в мелкой крошке из орехов.  Вот такой простой рецепт конфет Ferrero Rocher по-домашнему',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12650,'В емкость мультиварки всыпать манку, сахар, соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12650,'Влить молоко, добавить часть нормы сливочного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12650,'Массу перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12650,'Прибор закрыть, выставить режим «Молочная каша» на десять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12650,'Прибор открыть, добавить оставшееся масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12651,'Смазать маслом внутреннюю часть мультиварки, всыпать крупу, влить смесь воды и молока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12651,'Продукты перемешать, готовить десять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12651,'Яблоко очистить от кожуры, удалить сердцевину, мякоть взбить блендером в пюре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12651,'Другой вариант: мелкая терка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12651,'После того, как прозвучит сигнал, добавить фрукты, кашу перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12651,'Прогревать блюдо еще пять или шесть минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12652,'В чашу мультиварки влить молоко, выставить режим «Тушение», время – десять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12652,'Изюм промыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12652,'В отдельной емкости перемешать манку с солью и сахарным песком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12652,'Всыпать смесь в закипевшее молоко, массу помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12652,'Добавить изюм.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12652,'Готовить кашу в том же режиме под крышкой две минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12652,'Кашу перемешать и варить еще две минуты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12652,'В готовую кашу добавить масло.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12653,'Тыкву очистить от семян и кожуры, мякоть превратить в пюре при помощи блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12653,'Массу положить в емкость мультиварки, влить воду, тушить сорок минут, режим «Овощи».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12653,'Влить молоко, всыпать сахарный песок, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12653,'Выставить режим «Каша» на десять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12653,'Всыпать манную крупу, прогревать еще пятнадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12654,'В чашу мультиварки поместить манную крупу, соль, сахар, влить воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12654,'Выставить режим «Каша» на двадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12655,'Замочить в кипятке сухие грибы, держать до остывания, жидкость сцедить, но не выливать, можно использовать для приготовления соуса или супа, а грибы порезать соломкой. Шляпки шампиньонов протереть сухой тряпочкой, нашинковать пластинками, ножки – соломкой. Лук нарезать на полукольца (не толсто), чеснок порубить, обжарить на масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12655,'Добавить свежие грибы, жарить до полного испарения жидкости, следом добавить белые грибы, жарить все вместе еще минут 7 при среднем нагреве. Всыпать в сметану муку, перемешать, вылить в грибы, подсолить, поперчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12661,'Блюдо слегка смазываю майонезом и первым слоем выкладываю отварной картофель тертый на крупной терке. Майонез.','https://vkuso.ru/data/cache/data/e8/64097b7164288e8_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12661,'Вторым слоем шпроты которые предварительно измельчила вилкой,','https://vkuso.ru/data/cache/data/17/bbe8947f7a8c317_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12655,'Порезать картофель на тонкие шайбочки, треть его выложить на дно смазанной формы, присолить и промазать маслом. На картофель уложить половину грибов, прикрыть третью картофеля, промазать маслом, присолить, выложить остаток грибов, накрыть картофелем, присыпать порошком папарики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12655,'Верх круглой формы тщательно «запаковать» фольгой, отправить в прогретую духовку примерно на час, удалить фольгу за 10 минут до готовности, чтобы запеканка из картофеля и шампиньонов и белых грибов зарумянилась.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12655,'Перед подачей к столу оформить верх мелко посеченной зеленью, в качестве соуса подойдет сметана или острый кетчуп для любителей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12656,'К яйцу добавляю соль, воду, размешиваю и постепенно ввожу просеяную муку, замешиваю тугое тесто, кладу в пакет и на 15 минут отправляю в холодильник.','https://vkuso.ru/data/cache/data/99/5725ebe9e930099_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12656,'В фарш добавляю 50 мл. воды, соль, перец, приправы и хорошо размешиваю.','https://vkuso.ru/data/cache/data/6e/61fed7c74d8cc6e_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12656,'Сырой картофель натираю на крупной терке, отжимаю и сбрызгиваю соком лимона.','https://vkuso.ru/data/cache/data/30/737a0673dff3a30_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12656,'Лук нарезаю, морковь натираю на крупной терке и обжариваю до прозрачности лука.','https://vkuso.ru/data/cache/data/3d/9997fa6cd67253d_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12656,'Тесто делю на две части, одну часть раскатываю очень тонко, вторую часть теста отправляю в морозилку, для следующего раза. На тесто выкладываю фарш, зелень, картофель и сворачиваю в рулет.','https://vkuso.ru/data/cache/data/19/c52fe3ca7389019_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12656,'Нарезаю на кусочки около 4 см, выкладываю в сковороду на обжаренные лук с морковью.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12657,'Папоротник разрезать на части и замочить в холодной воде на 8-10 часов (за это время нужно поменять воду 3-4 раза).
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12657,'Говядину вымочить в холодной воде 10 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12657,'Нарезать говядину и лук, опустить в кипящую воду. Варить 1 час на среднем огне под крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12657,'Нарезать шиитаке, зеленый лук и измельчить чеснок.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12657,'В отдельной миске смешать красный перец, соль, соевый соус, кунжутное масло, растительное масло и черный перец.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12657,'Через час вытащить мясо и лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12657,'Овощи смешать с соусом, выложить в кастрюлю, накрыть крышкой и готовить 20 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12657,'Мясо нарезать соломкой, добавить в суп, варить 10 минут под крышкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12658,'В миску перекладываем творог, добавляем сахар, и ломаем туда банан, все измельчаем и перемешиваем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12658,'Как только довели до однородной массы, добавляем сироп. (или же повидло или варенье по вкусу) Снова перемешиваем. Убираем с сторону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12658,'Тонкий лаваш нарезаем на полоски шириной 7 см.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12658,'На 1 углов лаваша укладываем начинку, и все заворачиваем в виде треугольного конвертика, как показана на ролике.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12658,'Это действия не обязательно, но лично я обжарил заготовки десерта на разогретой сковороде до корочки, вы можете поступить точно так же. Обжаривать совершено не обязательно, данный десерт можно сразу подавать к чаю, или кофе, если вы это приготовите не на новый год.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12659,'Отвариваем овощи. Нарезаем кубиком горячие морковь и картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12659,'Солим овощи и перчим, заправляем подсолнечным маслом и отставляем остывать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12659,'Измельчаем зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12659,'Измельчаем лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12659,'Смешиваем все ингредиенты салата и он готов!
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12660,'Нарезаем грибы пластинками и обжариваем, даем остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12660,'Нарезаем отваренную курицу и ананас.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12660,'Добавляем к курице ананасы, грибы, зелень, черный молотый перец и майонез.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12660,'Украшаем салат зеленью и зернами граната!
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12661,'Затем маринованный лук ( 50 гр воды, 30 гр уксуса 9%, 1 ч.л сахара, 1 ч.л соли, мариновался лук 15 мин.) сверху отварные яйца тертые на мелкой терке. Майонез.','https://vkuso.ru/data/cache/data/b3/75fa66a8986f5b3_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12661,'Затем отварная морковь так же тертая на мелкой терке, в центр выкладываю кукурузу. Отправляю на час в холодильник.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12662,'Положить в кастрюлю тертую морковь, залить молоком, добавить масло, тушить до мягкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12662,'Всыпать маленькими порциями, помешивая манную крупу, проварить при слабом нагреве минут 5, дать остыть. Вбить в морковную массу яйцо, сдобрить солью, хорошо вымешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12662,'Сформовать котлетки, обвалять в сухарях, но можно и в муке. Обжарить морковные котлеты с молоком на сковороде или запечь в духовке до образования зажаристой корочки, подать теплыми со сметаной. Приятного аппетита!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12663,'Для приготовления соуса нужно добавить в блендер петрушку, базилик, каперсы, оливки, орегано, вяленые томаты, оливковое масло и все измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12664,'Поломать на кусочки шоколад, растопить (удобнее это сделать на водяной бане) до жидкого состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12664,'Нанести слой шоколада кисточкой на стенки формочек, например для кексов, убрать минут на 5 в морозилку, повторить операцию еще раз.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12664,'Переложить творог в блендер, всыпать сахарную пудру, добавить масло, все перемешать, разделить пополам. Всыпать в одну часть порошок какао, размешать. Наполнить формочки чередуя одну и другую массу, залить жидким шоколадом. Можно каждый шоколадный творожок по-домашнему присыпать сверху цветной стружкой кокоса и поставить окончательно застыть в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12665,'Порезать на длинные полоски молодые плоды цукини, чуть присолить, сбрызнуть растительным маслом. Зарумянить в масле на сковороде (можно на гриле) с двух сторон, переложить на лист бумажного полотенца для удаления остатков масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12665,'Смешать творог с тертым чесноком и прованскими травами (или любой другой пряной смесью). Положить немного творожной начинки на край полоски, свернуть в трубочку, закрепить зубочисткой, проделать такую операцию со всеми полосками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12665,'Сложить рулетики из цукини с творогом и прованскими травами на широкое блюдо и убрать в холодильник, если готовите дома, но и без охлаждения блюдо получается тоже вкусное.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12666,'Смешать комбайном яйца с холодным маслом, мукой и лимонной цедрой, полученное тесто скатать в колобок и размять в руках до эластичности, обернуть пленкой, убрать на полчаса в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12666,'Прогреть духовку чуть ниже 200 градусов, подготовить форму для выпечки. Вынуть тесто, раскатать в пласт небольшой толщины, выложить в форму, прижать к стенкам и дну, проколоть вилкой, застелить бумагой для выпечки, засыпать слоем сухой фасоли или риса, выпекать примерно четверть часа. Достать основу тарта, убрать фасоль, подержать при 150 градусах еще 5 минут в духовке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12666,'Приготовить начинку из яиц, сахарной пудры (оставить немного пудры для посыпки тарта), сгущенки, сливок, цедры и сока 3 лимонов, процедить ее, залить в испеченную основу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12666,'Выпекать лимонный тарт со сгущенным молоком около получаса до легкого прихватывания начинки. Перед подачей присыпать поверхность тремя ложками сахарной пудры.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12667,'Перед тем как приступить приготовлению котлеток, сначала я запекла сладкий перец в предварительно разогретой до 200° духовке. Перчик укутала в фольгу и пекла до готовности. Затем положила на несколько минут в кастрюлю, плотно накрыв крышкой (так кожура лучше снимается). Пока перчик остывает, приступила к приготовлению котлет.','https://vkuso.ru/data/cache/data/d9/625fe3a0ef32fd9_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12667,'Поломанный на кусочки белый хлеб замочила в небольшом количестве воды.','https://vkuso.ru/data/cache/data/a6/81a4dfd3a406ea6_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12667,'Из филе индейки сделала фарш с помощью блендера (мясорубки). Зеленый лук мелко порубила. Соединила фарш, яйцо, кукурузу, отжатый хлеб и зеленый лук. Все посолила, поперчила и хорошо перемешала.','https://vkuso.ru/data/cache/data/5a/773b16d60dc225a_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12674,'В кастрюлю умного прибора всыпать сахар и манку, влить воду и молоко, добавить сливочное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12674,'Ингредиенты перемешать, использовать ручной венчик.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12667,'Сделала небольшие котлетки и обжарила их слегка с обеих сторон в небольшом количестве растительного масла, затем накрыла фольгой и отправила сковороду в духовку на 5−7 минут.','https://vkuso.ru/data/cache/data/00/460e87181d35d00_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12667,'Пока котлеты стояли в духовке, приступила к приготовлению соуса.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12667,'Готовые котлетки полила горячим соусом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12668,'Для маринада смешать: йогурт, специи, соль, сок лимона, оливковое масло, измельченный чеснок, мелко нарезанную петрушку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12668,'Курицу промыть, немного обсушить, выложить в глубокую миску, добавить маринад и тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12668,'Рукав для запекания завязать с одной стороны, выложить в него курицу, выпустить воздух, плотно завязать с другой стороны и убрать на 30 минут в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12668,'Выложить рукав с курицей на противень и наколоть в нескольких местах зубочисткой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12668,'Выпекать в духовке при 180 градусах 40-50 мин. Через 20-30 мин (по желанию) достать из духовки и разрезать рукав, чтобы курица подрумянилась. Ароматная курица по-гречески готова. Подавать с любимым гарниром!',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12669,'Яйца с солью взбить до легкой пены, затем продолжить взбивать до образования пышной массы, постепенно добавляя сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12669,'Во взбитую яичную массу добавить размягченное сливочное масло, еще немного взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12669,'В масляно-яичную смесь в несколько этапов добавить просеянную муку с разрыхлителем, аккуратно перемешать до однородного состояния. Возможно, понадобится больше или меньше муки. Тесто получается довольно густым и вязким.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12669,'Яблоки помыть, почистить, удалить сердцевину и нарезать мелкими кубиками, орехи измельчить ножом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12669,'В тесто добавить яблоки и измельченные орехи, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12669,'На противень, выстеленный пергаментной бумагой, аккуратно выложить столовой ложкой (с горкой) тесто, формируя печенье.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12669,'Выпекать при температуре 180 градусов примерно 20 мин. до подрумянивания. Вкусное, ароматное печенье готово!',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12670,'Для начала надо приготовить соус для промазки основы пиццы. Нарезать чеснок и мясистый помидор, размешать томатную пасту с парой ст.л. воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12670,'Зарумянить чеснок на оливковом масле, добавить кусочки помидора, а через пару минут томатную пасту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12670,'Теперь основу соуса поперчить, присолить, всыпать сахар, базилик и орегано, дать закипеть, переложить в чашу блендера, измельчить и еще раз прогреть, вот теперь соус готов. Такой ароматный соус подойдет не только к пицце, но и к пасте, его можно хранить несколько дней в холодильнике в простерилизованной банке без потери вкуса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12670,'Порезать все овощи вместе с сыром на тонкие ломтики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12670,'Промазать противень маслом, положить готовую основу, промазать, не скупясь соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12670,'Уложить пластинки грибов, кружочки помидоров и присыпать большим-большим количеством сыра.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12670,'А теперь отправить пиццу с сыром моцарелла и вкусным соусом на треть часа в духовку, достать готовую, присыпать смесью зелени.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12671,'Молоко, крупу, соль и сахар по вкусу загрузить в чашу мультиварки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12671,'Прибор закрыть, выставить режим «Молочная каша».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12671,'Готовое кушанье перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12672,'В чашу мультиварки влить молоко, всыпать крупу и сахарный песок, положить половину нормы сливочного масла, какао-порошка, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12672,'Выставить режим «Рис» или «Каша» на десять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12672,'В кашу добавить оставшееся масло, хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12673,'Довести молоко до кипения, всыпать манку с сахарным песком тонкой струйкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12673,'Варить кашу при постоянном помешивании.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12674,'Выставить режим «Тушение» или «Каша», время – двадцати до тридцати пяти минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12675,'В небольшую кастрюлю всыпать манную крупу, сухое молоко, соль и сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12675,'Все компоненты перемешать, долить воду, перемешать массу при помощи погружного блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12675,'Довести кашу до кипения на плите, варить от трех до пяти минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12675,'Блюдо снять с огня, дать постоять пятнадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12676,'Взбить миксером банку сгущенного молока с яйцами, добавить гашеную соду, перемешать, всыпать какао с мукой, замесить мягкое тесто. Раскатать пять коржей под размер сковороды, толщиной около 5 сантиметров, но не выше.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12676,'Прогреть, как следует чугунную сковороду (сухую), положить корж, выпекать под крышкой примерно 3 минуты, он должен подняться в 2 раза, приобрести румяный цвет, но не пригореть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12676,'Оригинальный крем из батончиков Марс и сливок можно приготовить заранее. Нагреть сливки, практически до кипения, покрошить батончики, мешать до полного растворения, дать остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12676,'Холодную смесь взбить, добавляя постепенно размягченное сливочное масло, должен получиться густой крем, теперь можно собрать торт.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12676,'Пропитать коржи каким-либо сиропом, или жидким мороженым с добавлением пары ложек любого ликера, или коньяка, можно даже на крайний случай и водки. А если зубровки, то будет просто супер!',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12676,'Теперь промазать кремом каждый коржи, присыпать орехом, собрать в стопку, верх торта из батончиков Марс со сливками оформить, как подскажет фантазия, убрать в холодильник для хорошей пропитки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12677,'В подходящую емкость всыпать манную крупу, соль и сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12677,'Влить молоко, продукты перемешать, поставить в микроволновку на полторы минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12677,'В кашу добавить сливочное масло, перемешать, готовить еще полторы минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12678,'Влить воду в подходящую емкость, довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12678,'Всыпать крупу, варить четыре минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12678,'Добавить молоко, ванилин, сахарный песок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12678,'Массу перемешать до однородного состояния, варить еще четыре минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12678,'Готовое блюдо оставить под крышкой на десять или пятнадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12678,'В готовую кашу можно добавить мед.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12679,'Из печени удалить желчные протоки, продукт замочить в молоке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12679,'Через два часа печень пропустить через мясорубку вместе с репчатым луком, можно использовать блендер.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12679,'Всыпать муку, вбить сырые куриные яйца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12679,'Готовую смесь посолить и поперчить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12679,'Выпечь блинчики средней толщины.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12679,'Отварить морковь, натереть, добавить майонез и рубленую зелень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12679,'Сформовать торт из коржей и морковного крема.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12679,'Закуску охладить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12680,'Просеять муку горкой на стол, сделать углубление, влить оливковое масло, вымесить, добавить частями молоко столько, чтобы тесто стало эластичным (если нет молоко, можно использовать воду), замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12680,'Раскатать простое тесто для пиццы на молоке скалкой до требуемой толщины и уложить на него подготовленную начинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12681,'Основной продукт очистить от пленок, порезать кусочками, замочить на час в молоке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12681,'Перемолоть печень при помощи блендера, перемешать со сметаной, солью, яйцами, специями. Масса должна получиться однородной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12681,'Выпечь коржи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12681,'Измельчить лук, потереть морковь, продукты пассеровать, затем перемешать с рубленой зеленью, давленым чесноком, майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12681,'Сформовать закуску в виде торта, поставить на три часа в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12682,'Шампиньоны нарезать пластинками, обжарить на сковороде до испарения жидкости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12682,'Добавить репчатый лук, жарить продукты вместе до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12682,'Подготовить печень, вымочить в молоке 1 час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12682,'Приготовить тесто перемолотой печени, молока, соли, яиц, муки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12682,'Выпечь коржи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12682,'Прослоить грибной массой и майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12682,'Верхний корж также смазать майонезом, посыпать вареным тертым яйцом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12715,'Кальмары отварить, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12683,'Печень промыть, очистить от протоков и пленок, залить молоком на три или четыре часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12683,'Измельчить подготовленный субпродукт при помощи блендера или пропустить через мясорубку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12683,'Добавить муку, яйца, молоко, специи, соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12683,'Тесто по консистенции должно напоминать густую сметану.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12683,'Выпечь блины.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12683,'Измельчить лук и морковь, спассеровать до румяного цвета.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12683,'Собрать торт в таком порядке: корж, майонез, обжарка, второй корж, майонез, плавленый сыр «Дружба».',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12683,'Процесс повторить несколько раз, пока не закончатся продукты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12683,'Торт поставить в холод на шесть часов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12684,'Свиную печень вымочить в молоке, измельчить вместе с частью репчатого лука.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12684,'Всыпать муку, влить молоко, вбить сырые яйца, добавить соль, перец, разрыхлитель для кулинарных изделий.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12684,'Тесто перелить в смазанную маслом чашу мультиварки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12684,'Выставить режим «Выпечка» на сорок минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12684,'Готовить с открытой крышкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12684,'Корж разрезать по горизонтали на три коржа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12684,'Отдельно спассеровать нарезанный кубиками репчатый лук и тертую морковь.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12684,'Массу посолить, поперчить по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12684,'Коржи промазать майонезом, выложить начинку из овощей.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12684,'Блюдо охладить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12685,'Свиную печень и лук пропустить через мясорубку, добавить молоко, яйца, муку, разрыхлитель и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12685,'Выпечь блинчики, тесто должно быть похожим на сметану.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12685,'Запечь в духовом шкафу баклажаны, измельчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12685,'Добавить нарезанные кубиками томаты без кожицы, начинку заправить майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12685,'Коржи промазать овощным соусом, собрать торт.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12685,'Поставить в холод на два часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12686,'Приготовить жидкую заправку из растительного масла, кленового сиропа, натурального меда, ванили и корицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12686,'Смесь прогреть на тихом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12686,'Отдельно перемешать кокосовую стружку с изюмом, орехами, овсяными хлопьями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12686,'Обе смеси перемешать, перелить в форму, разровнять.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12686,'Поставить в духовой шкаф, печь в течение 20 минут, температура – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12687,'Перемешать рисовые и овсяные хлопья, семена льна, продукты растолочь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12687,'Смазать сливочным маслом форму для запекания, всыпать сухую смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12687,'Отдельно перемешать кленовый сироп с растительным маслом, перелить в форму.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12687,'Прогреть духовой шкаф до 170 градусов, время выпекания продукта – 25 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12687,'Запеканку вынуть, остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12687,'Шоколад охладить в морозильной камере и натереть на мелкой терке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12687,'Посыпать запеканку, украсить ягодами вишни.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12687,'Блюдо разрезать на порции.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12688,'Миндальные орехи измельчить при помощи кофемолки или блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12688,'Форму для выпекания смазать сливочным маслом, всыпать орехи, семечки, сахар, овсяные хлопья, молотую корицу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12688,'Отдельно перемешать мед с яблочным пюре и растительным маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12688,'Сухие и жидкие ингредиенты перемешать, переложить в форму, разровнять.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12688,'Печь в течение 15 минут, оптимальная температура – от 160 до 170 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12689,'Подготовить мясо: тщательно помыть, зачистить от пленок, порционно нарезать и немного отбить с двух сторон. Каждый кусочек «запеленать» в полоски бекона и закрепить прочным шнуром, присолить и присыпать молотым перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12689,'Прогреть сковороду, влить масло, когда оно хорошо нагреется положить медальоны из говядины, придавить лопаточкой, обжарить минуты по 3 с каждой стороны. Но любители «кровавого» мяса могут сократить время жарки до 2 минут с каждой стороны. Бока медальонов желательно тоже обжарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12689,'Добавить на сковороду сливочное масло, раздавленные зубчики чеснока и полукольца лука жарить до размягчения лука, поливать в это время мясо смесью мясного сока и масла из сковороды. Облить мясо коньяком, поджечь и дождаться пока погаснет пламя.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12689,'Выложить мясо на решетку, а для приготовления соуса в сковороду влить  немножко сливок и красное вино, нагреть до кипения и продолжать нагревать до сгущения соуса. Подавать медальоны с овощным салатом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12690,'Перемешать яблочный сок с оливковым маслом и медом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12690,'Размять бананы в кашу, раздробить орехи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12690,'Ингредиенты перемешать, смесь выложить на смазанный противень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12690,'Время запекания – 20 минут, температура – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12690,'Гранолу поломать на кусочки и подать, как закуску.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12691,'Смазать сливочным маслом форму для запекания, высыпать мюсли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12691,'Орехи размолоть при помощи кофемолки в мелкую крошку вместе с сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12691,'Отдельно смешать натуральный йогурт и орехи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12691,'Смесью полить мюсли, поставить в горячую духовку. Температура выпекания – 200 градусов, время – 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12691,'Гранолу остудить, посыпать сахарной пудрой, украсить ягодами малины или ежевики.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12692,'Продукты пропустить через мясорубку и добавить сырое яйцо, муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12692,'Приготовить коржи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12692,'Теплые коржи смазать кремом, приготовленным из любого соуса и плавленого сыра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12692,'Слои пересыпать рубленой зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12692,'Верх торта смазать соусом, посыпать тертым твердым сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12692,'Поставить закуску в холод на несколько часов для пропитывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12693,'Выпечь коржи из куриной печени, хлебного мякиша, предварительного замоченного в молоке и отжатого.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12693,'Приготовить крем из натурального йогурта с чесноком, солью, травами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12693,'Готовые коржи прослоить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12693,'Поставить закуску в холод на два или три часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12694,'Смешать мягкий маргарин с мукой в маслянистую крошку, добавить сметану, вымесить тесто, убрать на час в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12694,'Разделить охлажденное тесто на 15 частей, притрусить стол мукой, раскатать каждую часть в тонкий прямоугольник, выложить на него ягоды вишни из варенья, сформовать цилиндр, повторить процедуру с остальными кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12694,'Переложить все на противень, выпекать торт «Монастырская изба» до золотисто соломенного цвета при 200 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12694,'Для крема взбить сметану с сахаром. Собрать из готовых «бревнышек» избушку в следующем порядке. Положить 5 штук в один ряд, прижав одно к другому, полить сметанным кремом. Уложить на них сверху еще 4 штуки, полить кремом, далее – 3 штуки  и опять крем и т.д.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12694,'Верх торта оформить по своему усмотрению, например, обсыпать стружкой из шоколада или орехами, поставить на ночь для пропитки в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12695,'Говяжью печень замочить в молоке на несколько часов, снять пленки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12695,'Субпродукт и очищенную морковь пропустить через мясорубку, перемешать с манной крупой, яйцами, специями и солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12695,'Половину массы перелить в форму для запекания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12695,'Готовить семь минут, температура – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12695,'Приготовить обжарку из шампиньонов и репчатого лука, продукты измельчить, соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12695,'Масса должна приобрести золотистый оттенок, влить сметану, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12695,'Выложить начинку на печеночный слой, залить остатками печеночной массы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12695,'Вернуть блюдо в духовой шкаф на 15 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12696,'Печень пропустить через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12696,'Репчатый лук и морковь очистить, нарезать кубиками небольшого размера, спассеровать овощи на сковороде в течение семи минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12696,'Перемешать обжарку с яйцами, манной крупой, солью, приправами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12696,'Форму для выпекания смазать растительным маслом, перелить печеночную массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12696,'Время выпекания – от 50 до 60 минут, температура – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12697,'Картофель, цветную капусту, морковь промыть, очистить, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12697,'Говяжью печень подготовить, нарезать кусочками небольшого размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12697,'Ингредиенты перемешать, пропустить через мясорубку с крупной решеткой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12722,'Хвост, лапы, уши сделать из колбасы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12697,'Массу посолить по вкусу, переложить в смазанную маслом чашу мультиварки. Время выпекания – сорок минут, программа – «Выпечка».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12698,'Готовить блюдо я начала с маринования лука. Среднюю луковицу порезала полукольцами, посолила, поперчила, добавила сахар, уксус и воду. Все хорошо перемешала и отставила пока готовила курицу.','https://vkuso.ru/data/cache/data/ba/45c4bec99e564ba_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12698,'Куриное филе промыла под проточной водой и порезала на порционные кусочки. Слегка отбила. Посолила и посыпала специями по вкусу. Жарила при сильном огне на разогретой сковороде до золотистого цвета (так мясо остается сочным внутри).','https://vkuso.ru/data/cache/data/13/92bd66cacc81d13_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12698,'На готовое куриное мясо положила маринованный  лук, затем консервированный ананас и все присыпала твердым сыром. Выпекала в разогретой духовке (200°) до расплавления сыра, примерно, пять минут.','https://vkuso.ru/data/cache/data/8a/6064574e425db8a_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12698,'Надеюсь Вам понравиться. Приятного аппетита!','https://vkuso.ru/data/cache/data/ee/dab8f57fc66d9ee_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12699,'Удалить с грудки кожу разрезать вдоль, положить в чуть подсоленное молоко примерно на полчаса-час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12699,'Тщательно обтереть кусочки  полотенцем из бумаги, обжарить до корочки с двух сторон в смеси сливочного и растительного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12699,'Нагреть сливки, сыр порезать на маленькие кусочки, растопить его в сливках, дать соусу постоять, чтобы стал гуще.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12699,'Налить на плоскую тарелку пару столовых ложек соуса, положить готовую куриную грудку, полить ее щедро соусом, подать с рисом или пастой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12700,'Готовим тесто: взбиваем сливочное масло и сахар, затем добавляем яйцо и сметану. Добавляем соду гашеную уксусом и постепенно вводим муку. Замешиваем тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12700,'Отправляем форму с тестом в духовку на 180 градусов примерно на 35 минут. Форму нужно брать диаметром от 26 см. И прежде, чем выкладывать тесто, смазать форму маслом. Выпекаем до легкой золотистости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12700,'Готовим крем: разводим крахмал в небольшом количестве молока.  Молоко смешиваем с сахаром и доводим до кипения. После закипания тонкой струйкой вливаем крахмал и непрерывно помешивая варим, пока крем не загустеет. Даем крему остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12700,'Разрезаем корж на кусочки примерно 2х2 см. Крошки оставляем для обсыпки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12700,'В размягченное сливочное масло постепенно вводим заваренное молоко. По желанию можно добавить ванилин или цедру лимона.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12700,'Кусочки коржа перемешиваем с кремом. Немного крема оставляем на обмазку боков торта.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12700,'Собираем торт: Устанавливаем форму на блюдо (у меня форма 20 см), на дно формы помешаем часть крошек от коржа и выкладываем кусочки коржа с кремом постепенно утрамбовывая. Верх торта смазываем кремом, накрываем пищевой пленкой и отправляем в холодильник на ночь.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12700,'Смазываем бока торта кремом, посыпаем крошками от коржа и украшаем торт верх торта по желанию. Я украсила миндальными лепестками и кондитерскими жемчужинами.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12701,'Говядину нарезать брусками, обжарить до румянца на сильном огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12701,'Добавить нарезанные соленые огурцы, репчатый лук, подержать на огне две минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12701,'Разложить массу в два керамических горшочка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12701,'Нарезать картофель, выложить поверх мяса, посолить и поперчить по вкусу и желанию.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12701,'Добавить измельченный чеснок, нарезанные крупные и мясистые помидоры, влить воду или бульон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12701,'Горшочки прикрыть, поставить в духовой шкаф. Время приготовления – от 45 до 50 минут, температура – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12702,'Мясо нарезать небольшими брусками, обжарить до румянца, соль и перец молотый – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12702,'Выложить в форму для запекания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12702,'Сверху – нарезанные или натертые соленые огурцы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12702,'Отдельно приготовить обжарку из шампиньонов, репчатого лука и моркови, выложить поверх огурцов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12702,'Приготовить заправку из соуса «Кетчуп» и майонеза. Добавить в азу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12702,'Томатную пасту развести в бульоне или в воде, залить общую массу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12702,'Емкость затянуть фольгой, оставить отверстие для выхода пара.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12703,'Говядину нарезать продолговатыми кусочками, добавить измельченный лук, морковь, нарезанные маринованные огурцы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12703,'Тушить все вместе пятнадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12703,'Томатную пасту развести водой или бульоном, влить в азу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12703,'Нашинковать чесночные дольки, добавить к мясу. Специи – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12703,'Подержать блюдо на огне в течение десяти минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12703,'Отдельно отварить до полуготовности рис, выложить к мясу с подливой, тушить пятнадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12704,'Мякоть нарезать кусочками, обжарить на сливочном масле, огонь – слабый.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12704,'Накрыть сковороду крышкой, прогревать сорок пять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12704,'При необходимости добавить воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12704,'Соус «Ткемали» перемешать со сметаной, вылить на мясо, держать на огне семь минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12704,'Плавленый сыр натереть или нарезать, добавить в азу вместе с рубленой зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12704,'Перемешать, огонь выключить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12704,'Блюдо немного остудить, гарнир – любой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12705,'Подготовить грудки, помыть, снять кожу, зачистить от пленочек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12705,'Приготовить из вина, специй, меда, раздавленного чеснока, соли и перца смесь для маринования. Положить мясо в маринад, накрыть лоток пленкой, отправить в холодильник на сутки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12705,'Прогреть до 250 градусов духовку, каждый кусочек грудки свернуть в трубочку, закрепить шпагатом либо зубочистками. Выложить мясо на противень, отправить минут на 25 в прогретую духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12705,'Отключить нагрев, оставить запеченный рулет из куриной грудки со специями остывать в духовке примерно на 4 часа, достать, разрезать очень острым ножом на порции.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12706,'Нарезать филе брусками, огонь – сильный.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12706,'Добавить репчатый лук, соленый или маринованный огурец, морковь, чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12706,'Продукты потушить в течение получаса, специи, соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12706,'Отварить брюссельскую капусту в течение пятнадцати минут, головки разрезать пополам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12706,'Добавить к мясу вместе с мясистыми нарезанными помидорами, сладким перцем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12706,'Тушить все вместе в течение пятнадцати минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12706,'Азу подать теплым.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12707,'Нарезаем пекинскую капусту, грушу и копченую курицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12707,'Готовим заправку: смешиваем горчицу, растительное масло и перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12707,'Смешиваем все измельченные ингредиенты салата с заправкой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12708,'M&M’s нарезаем на 2 половинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12708,'В миску где будете замешивать тесто, перекладываем масло и добавляем сахар, все хорошо взбиваем до кремовой основы. Как только взбили, вбиваем туда 1 куриное яйцо и снова все взбиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12708,'Далее, как только все взбили, постепенно добавляем муку и замешиваем тесто. Как только замешали тесто, перекладываем его в тарелку на 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12708,'Далее делим тесто пополам, и одну половину раскатываем до 5-7 мм, и после чего вырезаем формочками',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12708,'Далее, перекладываем на протвинь, укрощаем M&M’s и кунжутом, и отправляем в разогретою духовку на 25 30 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12709,'Уложить кусок окорока в подходящую по размеру кастрюлю, налить такое количество воды, чтобы она покрывала мясо полностью, добавить сельдерей и лавровый лист, дать закипеть, варить при слабом нагреве примерно 2,5 часа, дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12709,'Срезать ножом с окорока шкурку, оставить на мясе маленький слой жира, нанести на нем концом ножа сеточку, уложить окорок на противень. Смазать мясо горчицей, нашпиговать кусочками имбиря, обмазать глазурью, запечь cвиной окорок в медовой глазури с имбирем на среднем огне примерно в течение 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12709,'Глазурь приготовить из меда, коньяка и сахара, нагрев все ингредиенты до полного растворения последнего.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12715,'Отдельно отварить яйца, очистить от скорлупы, желтки отделить от белков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12715,'Часть белков натереть на мелкой терке, часть – нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12715,'Измельчить чеснок, натереть на крупной терке сыр, порубить зелень петрушки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12715,'Ингредиенты перемешать, заправить майонезом, соль – по вкусу и желанию.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12710,'Подходим к выбору продуктов с умом. Мы можем приготовить мидии в томате самостоятельно, для этого нам необходимо будем серьезно поколдовать с томатной пастой, оливковым маслом и специями. Мы же с Вами используем готовые мидии в томатном соусе. На данный момент только один производитель выпускает пресервы: мидии в томатном соусе. Из консервированного продукта настоящего вкуса не получится. В данном случае мы ещё существенно экономим время, которого обычно не хватает.','https://vkuso.ru/data/cache/data/ab/835a7499eacb2ab_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12710,'Рисовую лапшу замачиваем в воде на 20 мин. Наливаем оливковое масло в сковороду и нагреваем. Крупно нарезаем чеснок и отправляем обжариваться, нам необходимо передать вкус чеснока маслу. После того как чеснок достаточно сильно обжарится, мы его убираем из сковороды.','https://vkuso.ru/data/cache/data/85/d0ba01ed4e0c285_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12710,'Отправляем на сковороду лапшу и на медленном огне дожидаемся пока она не станет эластичной. Обычно это происходит в течении пары-тройки минут, не забываем помешивать, чтобы наша лапша стала золотистого цвета и пропиталась чесночным вкусом.','https://vkuso.ru/data/cache/data/99/e2d67f139c27699_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12710,'Отправляем наши мидии в томатном соусе к лапше. Заливаем 1/3 томатной пасты и солим перчим. Делаем это аккуратно, т.к. томатный соус уже пряный и обладает насыщенным вкусом. Важно не перебить вкус наших морепродуктов. Но в тоже время блюдо это традиционное азиатское и если есть желание насладиться вкусами Китая, Тайланда, Кореи, Вьетнама и т.д. то делайте острее и используйте перцы халапеньо и кайенский, желательно дробленые, так они полностью передадут восточные вкусы.','https://vkuso.ru/data/cache/data/6e/094033bb9cdd66e_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12710,'Аккуратно выкладываем на тарелку. Присыпаем сверху сыром, тоже по вкусу. Сыр желательно брать выдержаный, он так же придаст пикантности блюду, хотя и это зависит от ваших предпочтений - сыром не испортите.','https://vkuso.ru/data/cache/data/d1/9523d03249899d1_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12711,'Поставить разогреваться сковороду с маслом, взбить вместе яйца, перец и соль. Вылить смесь на сковороду, обжарить омлет до красивой корочки с каждой стороны при среднем нагреве, дать ему остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12711,'Холодный омлет промазать сыром, разложить на всей поверхности листья зеленого салата и слой из сладкого перца, порезанного тонкой соломкой. Свернуть аккуратно в трубочку, убрать в холодильник на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12711,'Достать Рулет из омлета, перца и сливочного сыра, вставить через равные промежутки 7-8 зубочисток, разрезать под углом между ними омлет на  порции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12712,'Отварить яйца, очистить, нарезать кубиками. Часть яиц не крошить – они пойдут на украшение.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12712,'Красный болгарский перец нарезать кубиками, копченую куриную грудку – соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12712,'Кисло-сладкое яблоко потереть на мелкой терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12712,'Покрошить ядра грецких орехов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12712,'Продукты перемешать, посолить по вкусу, заправить майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12712,'Готовый салат выложить на красивое блюдо, украсить мышками из яиц.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12712,'Для глаз, ушек, ртов и хвостов использовать «Голландский» сыр и перец.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12713,'Курицу отварить, мясо нарезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12713,'Шампиньоны нарезать кусочками, репчатый лук – полукольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12713,'Грибы обжарить вместе с луком и охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12713,'Потереть твердый сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12713,'Ингредиенты перемешать, сыр оставить для украшения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12713,'Смесь заправить майонезом, выложить на большое блюдо.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12713,'Посыпать тертым сыром, из яиц сделать несколько мышат.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12713,'Хвостик, уши, глаза и усы можно сделать из перца, сыра, моркови по-корейски.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12714,'Твердый сыр потереть на мелкой терке, перемешать его со сливочным сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12714,'Чеснок измельчить, добавить в сырную смесь вместе с майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12714,'Перемешать, поставить на полчаса в холодильник для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12714,'Замороженное крабовое мясо или палочки натереть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12714,'Сформовать из сырной массы несколько колбасок, обвалять их в тертых крабовых палочках.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12714,'Придать заготовкам подобие мышек: ушки – из отваренной моркови, глаза – из перца-горошка.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12714,'Выложить на блюдо, украсить кусочками сыра, зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12715,'Выложить массу на блюдо в виде мыши, посыпать тертыми белками, украсить маслинами и колбасой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12716,'Подготовим форму для салата (у меня 14х15 см). Форму застелим пищевой пленкой, т.к. это салат-перевертыш.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12716,'Выкладываем слои в следующем порядке:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12716,'Все слои уплотняем, заворачиваем краями пищевой пленки и отправляем в холодильник на 30 мин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12716,'По истечению этого времени, выкладываем форму на тарелку и переворачиваем. Освобождаем салат от пленки и формы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12716,'Смазываем верх майонезом и посыпаем натертым твердым сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12716,'Украшаем на свое усмотрение, я сделала еловую веточку из укропа и игрушками елочки у меня выступили помидоры черри. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12717,'Отварить картофель, очистить, натереть, размер решетки – средний.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12717,'То же самое проделать с морковью, продукт натереть на мелкой терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12717,'Отварить яйца, белки отделить и натереть в отдельной мисочке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12717,'Репчатый лук измельчить, ошпарить для удаления лишней горечи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12717,'Любые рыбные консервы в масле размять вилкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12717,'Продукты выложить слоями: картофель, рыбные консервы, репчатый лук, морковь, тертые белки. Каждый слой промазывать майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12717,'Приготовить мышек из отваренных перепелиных яиц, выложить на поверхность салата.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12717,'Посыпать блюдо тертыми желтками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12717,'Поставить в холод для настаивания на два часа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12718,'Отварить картофель и морковь, натереть продукты на средней терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12718,'Соленые огурцы нарезать соломкой, чеснок и репчатый лук измельчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12718,'Консервированного тунца или горбушу размять вилкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12718,'Выложить салат слоями: картофель, консервы, морковь, смесь сыра с чесноком, огурцы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12718,'Готовое блюдо посыпать тертым сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12718,'Выложить фигурки мышек, сделанных из редиса или яиц.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12718,'Поставить салат в холодильник на час или два, затем подать на стол.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12719,'Налить в кастрюлю воду, нагреть до кипения, всыпать сахар, удалить пену, влить сок лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12719,'Разболтать в небольшом количестве холодной воды крахмал, влить, помешивая тонкой струйкой в сироп, варить пока не загустеет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12719,'Половину дробленых фисташек высыпать в форму с плоским дном, залить сиропом, присыпать оставшимися фисташками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12719,'После остывания домашний рахат-лукум с фисташками порезать на кубики, обсыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12720,'Картофель и морковь отварить, нарезать одинаковыми кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12720,'Отварить куриные яйца вкрутую и так же нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12720,'Измельчить соленые огурцы, колбасу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12720,'Все ингредиенты перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12720,'Добавить консервированный зеленый горошек, рассол отцедить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12720,'Готовый салат заправить по вкусу майонезом, посолить, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12720,'Сформовать мышку. Ножки, хвост, уши, усы сделать из колбасы. Для глаз использовать маслины, зеленый горошек или перец.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12721,'Отварить морковь и картофель, овощи нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12721,'Любые орехи измельчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12721,'Слить рассол от маринованных грибов, так же нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12721,'Яйца отварить, желтки и белки натереть отдельно.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12721,'Все продукты перемешать, белки оставить для украшения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12721,'Сформовать мышку, посыпать туловище тертым белком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12721,'Сделать нос и лапки из отваренной моркови, уши и хвост – из яичного белка, глаза – из маслин.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12722,'Свиной язык отварить, охладить, нарезать брусками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12722,'Консервированный ананас и сладкий болгарский перец нарезать небольшими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12722,'Ингредиенты перемешать, всыпать зерна спелого граната, заправить сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12722,'Натереть сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12722,'Из основной массы сформовать мышку, посыпать тертым сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12722,'Из маслин сделать глаза, усы – из молодого зеленого лука.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12723,'Мелко нашинковать репчатый лук, обжарить на масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12723,'Говядину нарезать кусочками, размер – два на пять сантиметров.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12723,'Жарить на оливковом или кукурузном масле до появления корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12723,'Добавить луковую обжарку, влить стакан заранее приготовленного говяжьего бульона, томатную пасту, смесь тушить в течение двадцати минут на тихом огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12723,'Соленые огурцы натереть или мелко нарезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12723,'Добавить к мясу, посолить, поперчить и перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12723,'Приправить толченым чесноком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12723,'Оставшийся бульон влить в муку порциями, перемешать, подлива должна быть жидкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12723,'Залить продукты, тушить все вместе на сковороде до загустения.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12724,'Лук и морковь измельчить, обжарить на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12724,'Продукты можно натереть или нашинковать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12724,'Говядину нарезать брусками, обжарить на сковороде в масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12724,'Добавить обжарку, помидоры измельченные, без кожуры, чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12724,'Смесь тушить в течение пятнадцати минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12724,'Воду в соус лучше не добавлять – он и так будет жидким.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12724,'Нарезать соленые или маринованные огурцы, выложить в соус.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12724,'Муку перемешать с бульоном или водой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12724,'Смесь влить на сковороду порциями, массу помешивать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12724,'Подлива должна загустеть.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12724,'Азу посолить и поперчить по вкусу, добавить любимые приправы, потушить пятнадцать минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12725,'Для получения душистого напитка необходимы сухари из черного хлеба, подсушить их можно в духовке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12725,'Все ингредиенты для кваса смешать и дать сутки постоять в комнате. Затем застелить дуршлаг марлей, процедить содержимое кастрюли и убрать в прохладное место примерно на сутки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12726,'Говядину нарезать длинными брусками, обжарить с маслом в течение пяти или семи минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12726,'Всыпать нашинкованный полукольцами репчатый лук, жарить до тех пор, пока лук не станет мягким.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12726,'Консервированные огурцы нарезать мелкими кубиками или натереть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12726,'Добавить продукт к мясу, влить томатную пасту, воду или говяжий бульон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12726,'Соль и перец – по вкусу, добавить лавровый лист, чеснок. Время тушения – от сорока пяти минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12726,'Картофельные клубни очистить и нарезать, обжарить в масле на другой сковороде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12726,'Кусочки картофеля выложить к мясу, тушить все вместе десять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12727,'Залить дрожжи слегка подогретой водой, дать постоять минут 10, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12727,'Просеять муку горкой на стол, порубить или размять руками с маслом. Добавить яйцо, всыпать сахар с солью, перемешать, соединить с дрожжами, вымесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12727,'Подсыпать стол мукой, раскатать тесто в пласт, смазать 2/3 поверхности маслом, отступив от краев на 3 сантиметра, прикрыть с одной и другой стороны несмазанной частью. Края теста тщательно залепить руками, иначе при раскатывании масло может вылезти.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12727,'Раскатать тесто в пласт, повторить процедуру складывания-раскатывания три раза, после каждого складывания убирать тесто в холодильник на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12727,'Раскатать охлажденное тесто в прямоугольник, прикрыть полотенцем и дать постоять 10 минут. Разрезать пласт пополам, а затем каждый – на 8 треугольников с основанием чуть больше 10 сантиметров.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12727,'Свернуть треугольники в форме круассана, переложить на подготовленный противень (кончик должен быть внизу), слегка загнуть концы рогалика к центру, раскладывать на расстоянии 5 см друг от друга, смазать верх слегка разболтанным яйцом, прикрыть, чтобы не заветрелись полотенцем, дать постоять минут 40.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12727,'Выпекать круассаны по-домашнему в заранее прогретой до 220 градусов духовке треть часа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12728,'Из мягкого масла, сахарной пудры, муки, взбитого яйца и соли замесить тесто. Обернуть его пленкой, убрать на полчаса или чуть больше в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12763,'Измельчить чеснок, добавить к мясу вместе с огурцами и лавровым листом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12728,'Притрусить стол мукой, достать тесто, раскатать в круг чуть больше чем диаметр формы, чтобы можно было сформовать бортик. Накрутить тесто на скалку, перенести в форму, застеленную пергаментом, слегка придавить ладонями, сделать бортик, проколоть несколько раз вилкой, поставить в холодильник минимум на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12728,'Включить для прогрева до 220 градусов духовку, засыпать форму с основой фасолью или горохом, поставить в прогретую духовку минут на 10. Достать форму осторожно удалить засыпку, нагрев снизить на 40 градусов, поставить еще на 10 минут в духовку, дать основе остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12728,'Приготовить для чизкейка «Даниэль» крем. Вбить в миску яйцо, всыпать сахар, взбить, всыпать крахмал с мукой, хорошо перемешать. Закипятить молоко, убрать с плиты, добавить половину яичной смеси, вливать тоненькой струйкой при постоянном перемешивании. Всю полученную массу соединить с оставшимся молоком, размешать и поставить на плиту, помешивая добиться загущения крема. Сазу после этого убрать с плиты, перелить в глубокую миску, накрыть пленкой, дать крему остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12728,'После полного остывания крема приготовить с ним сырную начинку. Для этого соединить его с рикоттой и сахаром, тщательно все смешать, вбить яйца и еще раз перемешать. Добавить крахмал, влить молоко, сок 1 лимона, добавить измельченную цедру лимона, размешать, влить сливки и окончательно перемешать до образования жидкой массы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12728,'Заполнить полученной сырной начинкой остывшую основу, выпекать при температуре чуть ниже 190 градусов около полутора часов или чуть меньше, готовность необходимо постоянно контролировать. Начинка должна быть по центру чуть-чуть жидковатой. Дать чизкейку полностью остыть, желательно подержать ночь в холодильнике.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12728,'Для оформления смешать воду с абрикосовым джемом, нагреть, помешивая до образования карамели, промазать горячим составом верх чизкейка, оформить дроблеными фисташками или ягодами с кусочками фруктов по сезону.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12729,'Бананы очистить, нарезать кусочками, переложить в чашу блендера, добавить яйца, молоко и сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12729,'Взбить все в однородную массу, всыпать в нее муку и быстро перемешать тесто, но не до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12729,'Получившееся тесто выложить на горячую сковородку с маслом и жарить банановые оладьи со всех сторон, пока они не станут коричневого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12729,'Разложить готовые оладушки по тарелкам и украсить кружочками бананов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12730,'Мелко нарезать огурцы (можно взять соленые или свежие), репчатый лук, вареную колбасу и вареные яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12730,'Твердый сыр и отварной картофель натереть на крупной терке, очищенную сырую морковь – на мелкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12730,'Собрать салат, выкладывая подготовленные продукты слоями: огурцы, картофель, майонез, лук, сыр, майонез, морковь, сыр, майонез, колбаса, яйца, сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12730,'Последний слой салата (тертый сыр) промазать смешанным с хреном или измельченным чесноком  и майонезом и посыпать перемолотыми грецкими орехами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12731,'Для коржа: отделенные от желтков белки взбить в стойкую пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12731,'Желтки взбить с маслом, сахаром и ванильным сахаром добела, всыпать муку и тщательно перемешать, чтобы не было комков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12731,'В тесто аккуратно подмешать взбитые белки, добавить измельченную лимонную цедру и хорошо все перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12731,'Круглую форму смазать сливочным маслом и равномерно распределить по ней приготовленное тесто тонким слоем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12731,'Выпекать бисквит 10-15 минут при 160 градусах: после прокалывания изделия зубочистка должна остаться чистой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12731,'Готовый корж достать из духовки и оставить в форме до полного остывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12731,'Для сырной массы: сливочный сыр взбить до однородности, добавить 3 яйца по одному и желтки 2-х яиц, подмешать сметану и сахарную пудру.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12731,'В конце добавить в сырную массу муку, сок и измельченную цедру лимона, тщательно все перемешать (комков быть не должно).',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12731,'Распределить получившуюся массу по остывшему коржу, сразу же убрать в духовку, разогретую до 200 градусов (с конвенцией) или 240 градусов (без конвенции), и запекать чизкейк 40-50 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12763,'Соль, приправы – по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12731,'Для крема: сметану взбить с сахаром и лимонным соком и смазать кремом поверхность и бока готового изделия, заделывая появившиеся трещинки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12731,'Посыпать верх чизкейка половиной кокосовой стружки, оставшуюся стружку распределить по бокам.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12731,'Клубнику помыть и оторвать плодоножки, ягоды разрезать пополам и разложить на поверхности чизкейка в виде любого узора.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12731,'На медленном огне подогреть абрикосовый джем, протереть его через сито и аккуратно смазать сиропом клубнику.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12731,'Готовый лимонный чизкейк с клубникой и кокосовой стружкой украсить свежей мятой и подать к столу, нарезав порционными кусками.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12732,'Куриную печень хорошо промыть и нарезать средними кусочками, репчатый лук очистить и измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12732,'На разогретую сковородку выложить лук и печень, добавить сахар и специи, влить вино и быстро все обжарить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12732,'Очищенную морковь и порей нарезать тонкими кружочками и припустить в небольшом количестве подсолнечного масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12732,'Картофель и сельдерей очистить, помыть и нарезать небольшими кубиками или кусочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12732,'Сыр натереть на любой терке, помидоры помыть и нарезать толстыми кружками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12732,'Разложить приготовленные продукты слоями по горшочкам: картофель и сельдерей, печень, лук и морковь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12732,'Каждый горшочек залить на 2/3 бульоном или горячей водой, слегка поперчить, посолить и добавить немного желаемых специй.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12732,'Посыпать морковно-луковый слой тертым сыром, поверх сыра положить по 1 ст. л. сметаны и по кружку помидора.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12732,'Накрыть каждый горшочек крышкой и запекать блюдо в прогретой до 200 С духовке 40-50 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12732,'Подавать готовую куриную печень с овощами в горшочках, присыпав каждую порцию рубленой зеленью.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12733,'Подогреваем молоко до 35-37 градусов и растворяем в нем сахар, соль, дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12733,'Добавляем просеянную муку и замешиваем тесто, которое должно иметь консистенцию сметаны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12733,'Оставляем тесто в теплом месте на 1,5 часа, чтобы оно увеличилось в объеме в 2 раза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12733,'Хорошо разогреваем масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12733,'Выкладываем тесто в ложку, предварительно разогретую в масле.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12733,'Опускаем ложку с тестом в раскаленное масло, когда пончик начинает золотится, он сам отстает от ложки и всплывает.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12733,'Готовые пончики выкладываем на бумажное полотенце для удаления лишнего жира.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12733,'По желанию посыпаем сахарной пудрой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12734,'Для начала промаринуем лук, поскольку для гармоничного вкуса в салате не должны присутствовать очень резкие вкусы. Для этого нарезанный полукольцами красный лук переложить в небольшую миску и ошпарить кипятком. Для того чтобы лук не стал вареным и мягким, горячую воду сразу слить, а лук сбрызнуть винным или яблочным уксусом и оставить мариноваться на10 минут, после чего повторно промыть лук, но уже холодной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12734,'Пока лук маринуется, займемся куриным филе, его можно отварить в подсоленной воде, запечь в духовке, но особенно вкусным получается салат с использованием куриного филе обжаренного на сковородке гриль. Для этого промытое под проточной водой мясо обсушить бумажным полотенцем. Натереть смесью соли с перцем и растительным маслом и переложить на раскаленную сковороду гриль с толстым рифленым дном.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12734,'В первые две минуты мясо приобретает золотистую корочку и запечатывается, это необходимо для того, чтобы из него не выходил сок при дальнейшей обработке, и оно получилось нежным и сочным. После того как филе поджарилось со всех сторон, уменьшить огонь и довести до готовности еще 7-10 минут. Готовое филе остудить и разрезать небольшими порционными кусочками поперек волокон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12734,'Подготовить апельсин. В салате мы используем только мякоть апельсина, поэтому заранее очищаем его от кожуры и разбираем на дольки. Для того чтобы избавиться от прозрачных перепонок можно каждую дольку надрезать ножницами и освободить мякоть, но если очистить цитрусовый за полчаса до готовки, то прозрачная пленка подсохнет и ее легко можно снять руками. Очищенную дольку разрезать на 3-4 части.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12734,'Сыр фета нарезать кубиками. Поскольку сыр имеет нежную структуру, лучше применить острый нож с тонким лезвием, предварительно намочив его в холодной воде. Некоторые производители выпускают свою продукцию в уже порезанном виде в рассоле, это очень облегчает готовку, но сыр в этом случае имеет более соленый вкус. Для придания салату оригинальности можно обвалять кубики мягкого сыра в семенах сезама и льна.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12734,'Промытые листья салата порвать руками и разложить по порционным тарелкам. Затем, выложить куриное филе, апельсины, сыр Фета и маринованный лук. Чтобы приготовить заправку, требуется соединить в отдельной емкости оливковое масло, горчицу в зернах, виноградный уксус и давленый чеснок в указанных пропорциях. Хорошенько взболтать содержимое и заправить салат. Подать к столу яркий и полезный салат с куриным филе, сыром фета и апельсинами, сразу после приготовления. Приятного аппетита!',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12735,'Репчатый лук и говядину обжарить на растительном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12735,'Продукты соединить, добавить чеснок, соленые огурцы, разведенную водой томатную пасту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12735,'Потушить все вместе сорок минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12735,'Макароны отварить отдельно, откинуть на сито или дуршлаг, промыть холодной водой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12735,'Пасту перемешать с мясом, довести до кипения, подержать на огне, время – от трех до пяти минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12736,'Говяжье филе нарезать брусками, жарить на масле сорок минут, огонь – тихий.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12736,'Перемешать сметану с соусом «Ткемали», добавить в мясо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12736,'Прогревать продукты пять минут, добавить тертый плавленый сыр, соль, рубленую зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12736,'Отдельно отварить гречку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12737,'Нарезать полосками свинину, обжарить до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12737,'Репчатый лук порезать полукольцами, обжарить до прозрачности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12737,'Нарезать брусками картофель, жарить на отдельной сковороде до корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12737,'Подготовленные продукты перемешать, добавить тертый соленый огурец.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12737,'Влить воду с разведенной томатной пастой. Приправы и соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12737,'Прогревать до готовности картофеля.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12738,'Для начала готовим тесто на шоколадные блины. Шоколад разломать на кусочки и растопить на водяной бане, постоянно помешивая. Отставить шоколад  для того чтобы он немного остыл, подогреть молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12738,'В растопленный шоколад при непрерывном помешивании влить небольшими порциями растопленное масло и теплое молоко в количестве 300мл. Отдельно взбить яйца миксером в течение 5-7 минут в стойкую пену.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12738,'В просеянную муку всыпать какао-порошок и сахарную пудру и перемешать до однородности. Порционно всыпать сухую смесь муки и какао в оставшиеся 450мл. теплого молока при непрерывном помешивании. Соединить жидкую мучную смесь с шоколадной и постепенно ввести взбитые яйца. Оставить тесто настаиваться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12738,'Для приготовления начинки взбить сливки с сахаром в плотную пену и поставить в холодильник, при взбивании можно добавить немного загустителя и ванилина. Апельсины и киви очистить от кожуры и нарезать мелкой соломкой, клюкву промыть и обсушить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12738,'Соединять фрукты со сливками необходимо непосредственно перед начинкой, так как сок, выделяемый фруктами, нарушит густоту сливок, и они поплывут. Пожарить тонкие блины с обеих сторон, при этом смазывать дополнительно сковороду не нужно, в тесте уже содержится жир, который при жарке выделяется на поверхность.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12738,'Соединить сливки с фруктами и начинить остывшие блины, просто скрутив их трубочкой. Шоколадные блинчики с фруктами и сливками оставить в холодильнике на пару часов, а перед подачей нарезать. Приятного аппетита!',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12739,'Мак нужно залить кипятком, чтобы мак набух, и убрать в сторону на 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12739,'Раскатываем 1-й пласт теста, слегка посыпаем его корицей, нарезаем на равные полоски.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12739,'Сливаем воду, которой заливали мак, в набухший мак добавляем сахар. И далее перетираем мак с сахаром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12763,'Азу тушить под крышкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12739,'Раскатываем 2-ой пласт теста, максимально распространяем мак по тесту, и снова нарезаем на полоски. И убираем сторону.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12739,'Спустя 15 минут достаем слоеные палочки с корицей, и перекладываем их на тарелку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12739,'На этот же протвинь, перекладываем слоеные палочки с маком, точно так же делаем косичку и отправляем в духовку на 15 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12740,'Обжарить фарш на растительном масле в сковороде, для того, чтобы он приготовился и не подгорел необходимо накрыть сковороду крышкой. Для говяжьего фарша время приготовления 1 час, свино-говяжий готовиться чуть быстрее. В конце жарки добавить соль и черный молотый перец и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12740,'На отдельной сковороде обжарить порезанный мелко лук, до карамельного цвета. Когда лук почти готов прибавить в сковороду нашинкованный ножом чеснок и после того, как пойдет ощутимый запах чеснока выключить огонь под сковородой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12740,'Томаты обдать кипятком и снять с них шкуру, если этого не сделать, то тонкая пленка сама отделиться в процессе приготовления и испортит блюдо. Очищенные помидоры нарезать кусочками. В сковороду с жареным фаршем прибавить готовый лук с чесноком, резаные помидоры, хорошенько перемешать и тушить под крышкой 7-10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12740,'Добавить томатный сок и готовить до того момента пока жидкость не выпариться и фарш не загустеет. Свежую зелень базилика, орегано и майорана промыть и мелко нашинковать. Добавить к соусу Болоньезе и перемешать. Спагетти отварить и откинуть на дуршлаг. Смазать сливочным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12740,'Спагетти разложить порционно на тарелки и густо укрыть мясным соусом Болоньезе, сверху которого присыпать блюдо тертым сыром Пармезан. Спагетти «А-ля Болоньезе» в домашних условиях подавать горячими. Приятного аппетита!',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12741,'Куриные грудки промыть, и разрезаем на куски толщиной в 2,5-3см. Пока подготавливаем мясо, не забываем предварительно включить духовку, она понадобиться в скором времени разогретая до 180  градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12741,'Яйца взбить до однородности с одной чайной ложкой чесночной соли и каплей острого соуса. Переложить мясо в яичный кляр. Просеять муку на плоское блюдо, посолить чесночной солью и поперчить черным перцем, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12741,'Куриное мясо панировать в муке и переложить в жаростойкое блюдо выстеленное фольгой для запекания, края фольги прикрыть над филе. Поставить блюдо в разогретую духовку и выпекать 15 минут. После этого развернуть фольгу для образования золотистой корочки и продолжать выпекание 5-7 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12741,'Пока мясо в духовке можно приготовить соус: натереть цедру половины крупного апельсина из него же выдавить фреш. Отцедить фреш через ситечко и отмерять пол чашки.  В отдельной посуде смешать 100 мл майонеза 30% жирности и пятью ложками кисло-сладкого соуса, прибавить цедру и апельсиновый сок и хорошо размешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12741,'Перелить соус в сковороду с высокими бортами и на маленьком огне довести до кипения. Готовое куриное филе переложить в сковороду с кипящим соусом и перемешать. Убавить огонь до минимума и томить до тех пор, пока соус не загустеет до нужной консистенции. Филе куриное в апельсиновом соке присыпать рубленой зеленью лука и подавать на стол.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12742,'В кипяченую горячую воду влить подсолнечное масло и добавляя небольшими порциями муку заварить тесто. Когда его консистенция будет густой прибавить остальное количество муки и замесить тесто руками. Отставить в сторону для остывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12742,'Овощи – лук и морковь, промыть и почистить. Нарезать и обжарить на сковороде до прозрачности лука. В сковороду добавить фарш, и хорошо размешав лопаткой, продолжать готовку',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12742,'Добавить резаный чеснок и специи и продолжить готовку на слабом огне под крышкой. Дать начинке остыть. Остывшее тесто, дополнительно вымесить и разрезав порционно на 5-6 кусков, раскатать тонкие листы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12742,'На каждый лист теста положить начинку и распределив равномерно свернуть рулетом. Края рулета, защипнуть и подвернуть. Деко для запекания смазать маслом и выложить в него наши рулеты плотно.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12742,'Яйца немного взбить со сметаной. Прибавить рубленую зелень и тертый сыр. Залить форму с рулетами соусом, и поставить в заранее разогретую до 200о духовку выпекаться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12742,'Подавать очень нежные, вкусные рулеты горячими, нарезав их порционными кусками. Однако хороши они и в холодном виде. Приятного аппетита!',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12743,'Разогреем масло на сковороде и обжарим целый чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12743,'Добавим уже нарезанные кубиками баклажаны и обжарим до того момента когда баклажан станет мягким.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12743,'После зальём томатами в собственном соку и воды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12743,'Тем временем варим Пенне. Теперь посолим, поперчим и добавим базилик, тимьян. Размешать с готовыми Пенне. Перед подачей добавить рикотта и пекорино .',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12744,'Печень промыть и освободив от прожилок измельчить в мясорубке или использовать для этих целей блендер. В измельченную печень вбить яйцо, добавить ложку майонеза и посолив и поперчив, вымешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12744,'Постоянно вымешивая добавить просеянную муку небольшими порциями. Получилось тесто консистенции густой сметаны. На разогретом масле пожарить печеночные оладушки, зачерпывая тесто, смоченной в холодной воде ложкой и выкладывая на сковороду. Обжарить с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12744,'Лук нарезать полукольцами, сладкий перец полосками. Обжарить овощи на растительном масле. Зелень нашинковать, смешать с рубленым чесноком. Промытые помидоры салатного сорта нарезать кружочками 0,5см толщиной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12744,'Сыр Моцарелла, так же нарезать кружками. Можно заменить Моцареллу твердым сыром или брынзой, натерев их на терке. Готовые оладьи выложить на смазанный противень. На каждый печеночный оладушек выложить жареные лук с перцем, присыпать зеленью с чесноком. Сделать сетку из майонеза.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12744,'Сверху на каждый оладушек выложить по кружку помидора, сверху сыр Моцарелла. Поставить противень в разогретую предварительно до 220 градусов духовку, на 10-15 минут до образования золотистой корочки. Готовые оладушки из печени с луком и болгарским перцем украсить зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12745,'В кипяченой воде (холодной) замочить желатин и оставить его на полчаса, чтобы разбух.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12745,'При помощи блендера или миксера превратить творог, сметану и сахар в однородную массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12745,'Набухший желатин развести в теплом молоке, поставить смесь на небольшой огонь и дать желатину полностью раствориться (важно чтобы он не кипел!).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12745,'Получившуюся желатиновую смесь влить в творожную массу, хорошо все перемешать и разделить получившуюся массу на три части.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12745,'В первую часть ввести какао, во вторую – несильно измельченное печенье, в третью ничего не добавлять.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12745,'Глубокую форму или порционные формочки застелить пленкой и наполнить творожными массами, выкладывая их по очереди.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12745,'Убрать творожно-шоколадный десерт с печеньем «Юбилейное» в холодильник минимум на 6 часов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12745,'Перед подачей перевернуть застывший десерт на блюдо или тарелки, снять пищевую пленку  и украсить по желанию.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12746,'Небольшими кубиками или тонкой соломкой нарезать отваренные кальмары и очищенные яйца, измельчить креветки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12746,'В салатник выложить кальмары, креветки, яйца и икру. Заправить салат майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12747,'Отделить желтки от белков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12747,'Белки взбить, всыпать сахар, добавить желтки, продолжать взбивать миксером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12747,'Всыпать муку, соду, оставшийся сахар, довести массу до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12747,'Время выпекания – полчаса, температура – 160 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12748,'Взбить яйца при помощи миксера в глубокой миске.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12748,'Ввести сахар в несколько приемов, масса должна стать пышной и густой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12748,'Всыпать ванилин, муку, взбить тесто до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12748,'Температура выпекания – 180 градусов, время – 25 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12749,'Перемешать муку с охлажденным и нарезанным маслом или маргарином, сахаром, яйцом, разрыхлителем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12749,'Массу помять руками, затем разделить на две части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12749,'Половину выложить на дно формы для выпекания, вторую охладить, но не замораживать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12749,'Порвать холодное тесто руками и насыпать в виде крошки на пирог.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12749,'Время выпекания – 40 минут, температура – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12965,'Следующий слой – тертый сыр «Пармезан», майонез.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12750,'Лук очистить и нарезать полукольцами, выложить на горячую сковородку, смазанную подсолнечным маслом, и слегка обжарить на среднем огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12750,'Морковь очистить, нарезать небольшими кубиками и добавить к луку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12750,'Перец промыть, вырезать семенную коробочку, нарезать овощ соломкой и добавить к луку с морковкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12750,'Помидоры промыть, нарезать кольцами, которые затем разрезать на 4 части и добавить в сковородку с овощами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12750,'Далее добавить к овощам кукурузу и фасоль (перед добавлением жидкость нужно слить), соль, молотую корицу и перец чили, сушеный чеснок, паприку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12750,'Куриное мясо промыть, нарезать небольшими кусочками, добавить к овощам и хорошенько все перемешать: филе должно покрыться овощным соусом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12750,'Тушить рагу по-мексикански в районе – 10 минут, затем разложить готовое блюдо по тарелкам и подать, присыпав при желании зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12751,'Взбить яйца со сметаной и сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12751,'Всыпать молотую корицу или ванилин из пакетика, соду, муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12751,'Массу взбить еще раз.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12751,'Температура выпекания – 180 градусов, время – 45 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12752,'В глубокую посуду влить уксус, яйцо, всыпать соль. Перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12752,'Влить холодную воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12752,'Натереть на терке охлажденное сливочное масло или маргарин, соединить с мукой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12752,'Влить воду с уксусом и яйцами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12752,'Быстро перемешать, края теста зажимать в середину, чтобы масса стала слоеной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12752,'Получившийся прямоугольник обернуть пищевой пленкой, положить в холод на десять или двенадцать часов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12753,'Сырые куриные яйца взбить, всыпать сахарный песок и соду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12753,'Взбить еще раз.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12753,'Влить кефир, ввести муку порциями, добавить разрыхлитель.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12753,'Время выпекания – 45 минут, температура – 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12754,'Взбить яйца с сахарным песком в пену, использовать венчик или миксер.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12754,'Добавить ванилин, муку, соду и растительное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12754,'Перемешать до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12754,'Время выпекания шарлотки – 40 минут, температура – 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12755,'Сахар смешать с яйцами, взбить, добавить муку, ванилин или корицу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12755,'Специи – по желанию.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12755,'Время выпекания – 25 минут, температура – 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12756,'Всыпать в обезжиренный творог сахарную пудру, влить сметану, перемешать до состояния однородной пасты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12756,'Порубить фундук ножом (штук 8-10 оставить целиком для оформления), убрать из фиников косточки, порезать тонкой соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12756,'Посыпать пленку смесью из кунжутного семени и стружки кокоса, уложить сверху слой творожной сладкой смеси, а на него разложить равномерно орехи и финики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12756,'Аккуратно свернуть в плотную трубочку, положить творожный рулетик на треть часа в холодильник. За это время на водяной бане приготовить жидкий шоколад, достать десерт, порезать влажным ножом на кусочки, посыпать сахарной пудрой, облить шоколадом, верх оформить целыми орешками фундука.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12757,'Свинину порезать ломтиками, посолить и поперчить, дать полежать полчаса для пропитывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12757,'Филе не должно быть мокрым, излишки влаги убрать бумажным полотенцем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12757,'Нарезать мелко лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12757,'Мясо жарить на заранее разогретом масле до румянца, добавить лук, процесс продолжить до полуготовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12757,'Всыпать немного муки, перемешать, прожарить еще раз.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12757,'Влить бульон, добавить лавровый лист, потушить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12757,'Положить жирную сметану и томатную пасту.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12757,'Блюдо довести до кипения, огонь уменьшить, тушить кушанье в течение часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12758,'Свежую свинину промыть и нарезать пластинками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12758,'Налить на сковороду масло, филе обжарить до получения румяной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12758,'Морковь нарезать кубиками, лук – порубить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12758,'Промыть консервированные огурцы холодной водой, нарезать полосками и добавить к мясу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12758,'Томатную пасту развести водой, посолить, соус влить в мясо с огурцами, добавить лук и морковь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12758,'Соль, молотый перец, другие приправы – по вкусу, всыпать рубленый или давленый чеснок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12758,'Прогревать азу двадцать минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12758,'Нарезать тонкой соломкой картофель, добавить в основную массу, влить теплую воду.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12758,'Емкость снять с огня еще через двадцать минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12759,'Соленые или маринованные огурцы очистить, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12759,'Свинину промыть и нарезать брусками, жарить в течение семи минут на заранее прогретой сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12759,'Добавить соль и душистый перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12759,'Нашинковать репчатый лук, натереть морковь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12759,'Овощи обжаривать отдельно от мяса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12759,'Очистить и нарезать картофель, жарить до румянца отдельно и от мяса, и от остальных овощей.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12759,'Добавить рубленый перец чили.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12759,'Приготовить смесь из соуса «Кетчуп» и майонеза.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12759,'Порционные горшочки прогреть в духовом шкафу, выложить огурцы.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12759,'Следующий слой – мясо, полить соусом, приправить лавровым листом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12759,'Далее – овощи и остатки соуса.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12759,'Поставить емкости в горячую духовку на полчаса.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12760,'Свинину нарезать полосками, маслины и соленые огурцы – кружками, репчатый лук – кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12760,'Ингредиенты переложить в чашу мультиварки, режим «Выпечка».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12760,'Приготовить подливу: перемешать муку и сливки, добавить воду и томатный сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12760,'Соус подлить к свинине и овощам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12760,'Томить азу полчаса в том же режиме.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12760,'Добавить молотую паприку, перец, соль, давленый чеснок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12760,'Выставить режим «Подогрев» на двадцать минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12761,'Разрезать капусту на 4 части. Промыть в холодной воде. Затем дать лишней воде стечь.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12761,'В кастрюлю с холодной водой всыпать рисовую муку, перемешать.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12761,'Нарезать тонкой соломкой дайкон, морковь, нарезать крупно зеленый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12761,'Нарезать крупно лук, имбирь. В блендере измельчить лук, имбирь, чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12761,'В рисовый "кисель" добавить рыбный соус, красный перец, овощи, хорошо перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12761,'Засоленную капусту хорошо промыть в холодной воде, чтобы избавиться от лишней соли, дать лишней воде стечь',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12761,'Намазать каждый лист кимчи пастой, уложить капусту в контейнер. Оставить при комнатной температуре на 24 часа, затем убрать в холодильник на 2-3 дня.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12762,'Рис отварить, остудить до теплого состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12762,'Свинину нарезать длинными кусочками, репчатый лук покрошить кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12762,'Помидоры ошпарить и снять кожицу, мякоть мелко порезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12762,'Консервированные огурцы очистить от кожицы, мякоть нарезать маленькими дольками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12762,'Раскалить жаровню, обжарить мясо с луком до золотистого цвета.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12762,'Добавить помидоры и огурцы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12762,'Влить воду, посолить и поперчить по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12762,'Азу тушить около двадцати пяти минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12762,'Добавить отваренный и полуостывший рис, блюдо оставить на огне для прогревания еще на шесть минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12762,'Готовое кушанье посыпать рубленой зеленью, подержать под крышкой пятнадцать минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12763,'Свинину вымыть и обсушить, мясо мелко нарезать, обжарить на раскаленном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12763,'Быстро появившаяся корочка не даст продукту пересохнуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12763,'Нашинковать репчатый лук полукольцами, обжарить на другой сковороде до золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12763,'В конце приготовления добавить томатный соус.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12763,'Очистить картофель, нарезать кубиками и отправить к свинине.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12763,'Отцедить огурцы от рассола или маринада, нарезать, жарить две минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12965,'Далее – нарезанные крабовые палочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12764,'Подержать вилок цветной капусты в подсоленной воде, разделить на небольшие веточки. Приготовить из молока, чесночного порошка и муки смесь для кляра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12764,'Подготовить противень с бортиками, застелить пергаментом, но можно и просто смазать маслом. Окунуть каждую веточку в кляр и разложить на противне, готовить цветную капусту в кляре треть часа в духовке с температурой 220 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12764,'В это время приготовить соус для заливки капусты из взбитого растопленного сливочного масла и острого соуса. Достать капусту, залить полученной смесью, осторожно размешать для равномерного распределения соуса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12764,'Подавать к столу можно с сырным соусом, морковью, нарезанной соломкой и сельдереем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12765,'Свинину нарезать полосками, положить в чашу, режим «Мультиповар».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12765,'Маринованный огурец натереть вместе с морковью, овощи добавить к мясу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12765,'Репчатый лук нарезать поперек дольками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12765,'С консервированных томатов снять кожицу, мякоть добавить в основную массу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12765,'Ингредиенты перемешать, потушить под крышкой почти до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12765,'В конце приготовления добавить зелень, лавровый лист, молотый перец.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12766,'Филе вымыть, нарезать кубиками или брусками, обжарить в чаше мультиварки в течение пятнадцати минут, режим «Выпечка» или «Жарка».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12766,'Очистить и нарезать морковь, репчатый лук, нарезать овощи кубиками и добавить к мясу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12766,'Приправить азу лавровым листом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12766,'Все вместе жарить десять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12766,'Нарезать соленые огурцы, добавить к основной массе вместе с нарезанным картофелем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12766,'Ингредиенты перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12766,'Разбавить водой густую томатную пасту, влить в чашу мультиварки, соль и перец – по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12766,'Выставить режим «Тушение» на час.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12767,'Соленые огурцы нарезать мелкими брусками, выложить в сотейник, влить воду, довести до кипения, тушить пятнадцать минут, температура приготовления – 160 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12767,'Нарезать репчатый лук полукольцами, мясо птицы – полосками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12767,'Раздавить и нашинковать чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12767,'Индейку жарить на сковороде в течение пяти минут, добавить лук, прогревать продукты вместе еще три минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12767,'Влить воду с томатной пастой, тушить две минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12767,'Всыпать укроп, петрушку, добавить чеснок и соленые огурцы, соль и перец.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12767,'Азу тушить от трех до пяти минут, затем подать на стол.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12768,'Мясо промыть и обсушить, нарезать кусочками среднего размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12768,'Налить масло на сковороду, птицу жарить до золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12768,'Переложить в огнеупорную форму для запекания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12768,'Очистить и нарезать кубиками морковь и лук, жарить до золотого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12768,'Влить разведенную водой томатную пасту.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12768,'Овощи тушить пять минут, добавить к мясу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12768,'Очистить и нарезать кубиками картофельные клубни.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12768,'Обжарить до полуготовности на масле, добавить в форму.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12768,'Влить воду.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12768,'Тушить азу под крышкой в течение получаса, температура – 180 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12768,'В конце приготовления добавить зелень, соленые огурцы, чеснок, перец и соль.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12768,'Азу перемешать, дать постоять.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12769,'Репчатый лук и морковь очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12769,'Говяжью печень промыть, освободить от пленок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12769,'Субпродукт и овощи нарезать кусочками, пропустить через мясорубку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12769,'Сырые куриные яйца взбить вилкой и добавить к печеночной массе.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12769,'Влить сливки, ввести муку, приправы, соль – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12769,'Готовую смесь перелить в форму для выпекания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12769,'Время приготовления – 45 минут, температура – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12770,'Нагреть молоко, растворить сахар с ванилью, дать закипеть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12770,'Взбить крахмал с яйцами и кофе, кипящее молоко влить очень тонкой струйкой, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12777,'Яйца перемешать с сахаром. Добавить растопленное сливочное масло - перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12770,'Перелить все в кастрюлю, проварить при очень слабом нагреве до получения густой массы. Убрать с плиты, вмешать мягкое сливочное масло, дать остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12770,'Приготовить из масла, сахара, какао, молока и шоколада смесь для прослойки. Для этого все ингредиенты, кроме последнего, смешать, подогреть, когда смесь станет однородной, поломать на кусочки шоколад и всыпать в нее, продолжить нагрев с помешиванием до получения густой красивой блестящей массы, дать остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12770,'Выложить кофейно-шоколадный пудинг на плоское блюдо, чередуя слои пудинга и шоколадной прослойки. Прежде чем подать к столу десерт надо минимум на 3 часа поставить в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12771,'Субпродукт промыть, удалить пленки, протоки, нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12771,'Печень перемолоть блендером.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12771,'Промыть рис, залить водой, отварить до полной готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12771,'Натереть сырую морковь, потолочь чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12771,'Репчатый лук измельчить и спассеровать до румяного цвета.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12771,'Ингредиенты перемешать, посолить, всыпать специи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12771,'Выложить в форму для выпекания.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12771,'Время приготовления – полчаса, температура – 180 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12772,'Картофельные клубни очистить, отварить, превратить в пюре, перемешать со сметаной и яйцом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12772,'Говяжью печень, лук, морковь нарезать кусочками, затем перемолоть в блендере.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12772,'Массу перемешать с еще одним яйцом, молоком, мукой, солью, чесноком, зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12772,'Выложить в огнеупорную форму слоями печеночную массу и картофель.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12772,'Температура выпекания – 180 градусов, время – 50 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12773,'Высыпать в кастрюлю гречку, залить подсоленной водой, отварить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12773,'Половину нормы репчатого лука измельчить, обжарить до золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12773,'Говяжью печень очистить и нарезать кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12773,'Оставшийся лук, печень и гречку пропустить через мясорубку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12773,'Мелко порубить зелень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12773,'Готовую печеночную массу перемешать с яйцами, обжаркой, манкой, зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12773,'Массу перелить в форму для запекания, температура приготовления блюда – 180 градусов, время – сорок минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12773,'Запекать блюдо до получения аппетитной корочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12774,'Печень промыть, отварить, пропустить через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12774,'Влить три четверти от общего количества молока, соль и молотый перец – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12774,'Натереть кабачок на терке, перемешать с остатками молока, яйцом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12774,'Форму для выпекания смазать маслом, посыпать манкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12774,'Выложить в форму две трети кабачковой массы, сверху – печень и оставшиеся кабачки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12774,'Посыпать запеканку манной крупой, поставить в заранее прогретую духовку на 25 минут. Температура приготовления – 180 °C.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12775,'Яйца взбить с сахаром, добавить растительное масло - перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12775,'Муку смешать с корицей, содой, разрыхлителем. Добавить к яйцам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12775,'Морковь натереть на терке и добавить в тесто - перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12775,'Форму смазать сливочным маслом и присыпать мукой, лишнюю муку высыпать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12775,'Выложить тесто в форму, выпекать 35 минут при температуре 180 градусов. Остудить и разрезать поперек на 2 части.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12775,'Сметану смешать с медом и сахарной пудрой. Смазать торт.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12776,'Разогреть сковороду (масла добавлять не надо), положить нарезанный на тонкие полоски бекон, обжарить до появления хрустящей корочки, осторожно переложить на полотенце из бумаги, через некоторое время кусочки перевернуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12776,'Порезать соломкой твердый сыр, отварную курицу и ветчину. Приготовить из сока лимона, хорошей сметаны (можно заменить йогуртом) и майонеза с добавлением мелко нашинкованного зеленого лука заправку для салата.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12776,'Хорошо промыть листья салата, нарвать на куски руками, выложить на дно салатницы. Выложить на него сыр, ветчину и курятину, присыпать «хрустиками» из бекона, подать без промедления к столу. Заправку перелить в соусник, поставить его рядом с салатом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12777,'Влить мед - перемешать. Добавить гашеную соду - перемешать. Всыпать муку и замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12777,'Раскатать тесто и вырезать круги. Их обжарить на сухой сковороде до румяного цвета с двух сторон на медленном огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12777,'Смешать сметану с сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12777,'Неудавшиеся коржи измельчить в крошку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12777,'Собрать торт: выложить коржи друг на друга, промазывая слои сметаной. Верхний слой тоже промазать кремом и посыпать по всех сторон крошкой от коржей.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12778,'Горох залить водой на 2 часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12778,'В кастрюлю положить курицу, залить 2 литрами воды, добавить лаврушку, довести до кипения и варить 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12778,'Переложить горох в кастрюлю и варить еще 30 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12778,'Картофель и лук нарезать квадратиками. Морковь - натереть на терке. В сковороде на растительном масле обжарить лук и морковь, перемешивая в течении 15 минут на среднем огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12778,'В отдельной сковороде обжаривать охотничьи колбаски (нарезанные колечками) 5 минут на среднем огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12778,'В кастрюлю добавить картофель и морковно-луковую смесь. Варить 10 минут в кипящей воде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12778,'Добавить охотничьи колбаски, мелко нарезанный укроп, посолить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12779,'На сильном огне обжарить бекон до золотистой корочки. Вынуть из сковородки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12779,'Лук нарезать крупными квадратиками и обжарить 20 минут на среднем огне в масле от бекона. Вынуть из сковородки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12779,'Груши крупно нарезать на квадраты и отправить в туже сковородку, залить медом и жарить 4 минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12779,'Отвариваем макароны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12779,'Сливочное масло растопить, добавить муку - перемешать. Влить молоко - перемешать. Натереть сыр. Варим пока сыр не расплавится. В готовые макароны всыпаем обжаренные лук, грушу и бекон, заливаем соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12780,'Лук нарезать тонко полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12780,'На сковороде разогреть оливковое масло, высыпать лук и пропустить чеснок через пресс. Обжариваем 7 минут на среднем огне, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12780,'Малосольные помидоры очистить от кожуры и добавить к луку. Посолить и добавить перец чили (1/2 ч. л.). Помидоры размять, добавить воды (60 мл). Готовим 15 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12780,'Содержимое сковородки измельчить в блендере.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12780,'В эту сковородку добавить нарезанный соломкой картофель. Добавить перец чили (1/2 ч. л.), готовим 7 минут, перемешивая.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12780,'Содержимое блендера влить к картофелю и готовить еще 7 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12780,'Вбить яйца, сверху посыпать тертым сыром и мелко нарезанным укропом, накрыть крышкой и готовить 7 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12781,'Хлеб обжарить на сильном огне до золотистого цвета с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12781,'На оливковом масле обжарить тонко нарезанные шампиньоны в течении 5 минут на сильном огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12781,'К грибам добавить бальзамический уксус, сахар - перемешать и поставить на 0.5 минуты на сильный огонь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12781,'Обжаренные ломтики хлеба обмазать чесноком пропущенным через пресс. Сверху выложить начинку из грибов, а на грибы выложить листики базилика.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12782,'Приготовить картофельное пюре с добавлением яйца, сливок и зелени, тщательно перемешать, добавить манную крупу и тщательно вымешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12782,'Слегка смазать руки маслом, скатать из полученной массы небольшие шарики, чуть обвалять в муке, а затем в молотых сухарях.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12782,'Разогреть в сковороде большое количество масла, обжарить картофельные крокеты с манкой и зеленью до образования красивой плотной корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12782,'Достать крокеты, положить на полотенце из бумаги. Для лучшего впитывания можно аккуратно прокатать шарики по бумаге.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12782,'Разложить на тарелки и подать к столу вместе со сметаной. Приятного аппетита!',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12783,'В блендер положить печенье типа «Юбилейного», измельчить в крошку, но не в кашу. Если нет блендера, то можно сложить печенье в пакет и прокатать скалкой, добавить яблочный сок, перемешать до получения пластичной массы. Выложить в подготовленную форму полученную массу, утрамбовать руками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12788,'Как только замешали, заворачиваем тесто в пакет, или пищевую плёнку, и убираем в холодильник на 15 минут..',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12783,'Положить в чашу блендера творог, цедру лимона, сахар, влить лимонный сок, йогурт, взбить до получения однородной гладкой массы. Добавить крахмал, яйца, тщательно взбить в однородную массу, залить в форму.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12783,'Форму с чизкейком тщательно обернуть фольгой, чтобы внутрь не попала вода, поскольку готовиться чизкейк из печенья «Юбилейное» с творогом и йогуртом будет далее на водяной бане.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12783,'Поставить форму, прикрытую фольгой в сковороду с водой и поставить в прогретую чуть ниже 190 градусов духовку, готовить чизкейк 50 минут. Нагрев отключить, оставить форму остывать на 2 часа прямо в духовке, потом поместить блюдо для окончательного охлаждения в холодильник, после этого можно приглашать домашних к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12784,'Очистить, порезать на небольшие кубики и сварить в кипящей подсоленной воде  картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12784,'Слить часть отвара, сделать пюре с яйцом и сливочным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12784,'Разрезать вафельный лист на прямоугольные пласты размером примерно 7х15см., промазать пюре из картофеля, уложить сосиску, свернуть в трубочку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12784,'Полученный рулет обмакнуть в смесь яйца и специй далее обжарить каждый рулетик в хорошо прогретом масле до образования красивой румяной корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12784,'Подавать сосиски с картофельным пюре в вафельных листах с любыми овощами по сезону.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12785,'Смешать молоко, сахар и яйца, взбить в однородную смесь, батон порезать на одинаковые по толщине ломти примерно по 1,5-2 см, поставить разогреваться на плиту сковороду с маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12785,'Кусочки батона обмакнуть в яичную смесь и сразу обжарить с одной и другой стороны до появления красивой и аппетитной корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12785,'Приготовить из сахара, воды и масла карамель.  Для этого смесь прогреть до кипения и продолжать нагрев еще 3-4 минуты до появления густоты, снять смесь с плиты, добавить кусочки банана, перемешать, закрыть крышкой, дать постоять пару минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12785,'Готовые тосты облить карамелью и сразу подать к столу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12786,'Подготовить грудки курицы, убрать кожу, зачистить от пленочек, слегка отбить, сдобрить крупно помолотым перцем с обеих сторон, уложить на смазанный противень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12786,'Положить на мясо по несколько кусочков ананаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12786,'Смешать майонез, крупную стружку сыра и сметану, покрыть каждый кусочек мяса, чтобы не было видно колечек ананаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12786,'Выпекать куриные грудки с ананасом, сыром и сметаной примерно около часа при температуре духовки 180-190 градусов. На гарнир подать можно овощной салат с рисом или пюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12787,'Измельчим лук полукольцами, добавим соль, карри и зальем кипятком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12787,'Подготовим форму для салата. Устанавливаем кулинарное кольцо на блюдо, на котором будет подаваться салат. Смазываем форму и дно блюда майонезом. Если у вас нет кулинарного кольца или разъемной формы, можно, любую подходящую форму выстелить пищевой пленкой, смазать ее майонезом и выкладывать слои в обратном порядке, а потом готовый салат перевернуть и украсить зеленью и клюквой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12787,'Измельчаем вареный картофель – 1 слой салата и делаем сеточку из майонеза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12787,'Вторым слоем салата выкладываем лук, отжатый от жидкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12787,'Измельчаем крабовые палочки (нарезаем соломкой) – 3 слой салата и делаем сеточку из майонеза.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12787,'Измельчаем яйца – 4 слой салата и делаем сеточку из майонеза.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12787,'Измельчаем грибы. Я использую маринованные маслята, можно брать любые – 5 слой салата. Салат отправляем в холодильник минут на 20.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12787,'Измельчаем зелень.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12787,'Освобождаем салат от кулинарного кольца, посыпаем верх и бока зеленью, украшаем салат клюквой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12788,'Тесто:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12788,'Далее, добавляем сметану, и куриное яйцо, и хорошо это взбиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12788,'В муку добавляем 1/4 ч. л разрыхлителя для теста, и слегка перемешиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12788,'Как только взбили, постепенно добавляем муку, и замешиваем тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12792,'Подать к столу в горячем или холодном виде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12788,'Начинка.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12788,'Спустя 15 достаем тесто, катаем из него колбаску, и далее нарезаем на равные части, из них катаем шарик.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12788,'Перекладываем на противень смазываем остававшимся желтком и отправляем в духовку до готовности. ( у меня это заняло 40 мин)',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12788,'Достаем, охлаждаем и посыпаем сахарной пудрой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12789,'Взбить яйца, замесить с ними эластичное тесто, раскатать в прямоугольник, порезать на сантиметровые ленты, а потом на небольшие прямоугольнички, обжарить в сильно прогретом топленом масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12789,'Из сахара и воды с добавлением  меда сварить довольно густой и тягучий сироп, дать остыть градусов до 65-70.  Залить заготовки сиропом, осторожно размешать, выложить печенье «Чак-чак» с медом на плоскую тарелку, дать застыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12790,'Замесить из просеянной муки с разрыхлителем, соли и яйца мягкое тесто, добавить  сметану и мягкое сливочное масло, вымесить окончательно тесто, обернуть в пленку, положить примерно на полчаса в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12790,'Для начинки сварить филе в подсоленной воде (при желании можно добавить и специи), дать чуть остыть, порезать на небольшие кубики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12790,'Разрезать луковицу пополам, а потом нашинковать на тонкие полукольца. В сковороде хорошо разогреть растительное масло с добавление сливочного, обжарить лук, подсолить, приправить тимьяном и перцем, перемешать, прогреть еще несколько минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12790,'Холодный шар теста раскатать по размеру подготовленной формы, но только с небольшим запасом, перенести в форму, уложить на него мясо и лук, присыпать крупной сырной стружкой, красиво защипать края. Выпекать пирог с начинкой из курицы и сыра минут 35-40 пока не образуется красивая корочка соломенного цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12791,'Первым делом я включила греться духовку на 180°. Затем подготовила форму для запекания, дно формы застелила пергаментом, бока ничем не смазывала(у меня антипригарная форма)',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12791,'Отделила белки от желтков. Желтки взбила добела с 2-мя стаканами сахара, а белки взбила до устойчивых пиков со щепоткой соли.','https://vkuso.ru/data/cache/data/88/cbfc338c8ffd188_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12791,'В миску ко взбитым желткам постепенно добавила взбитые белки.','https://vkuso.ru/data/cache/data/65/c03b5c9d4d6e765_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12791,'Просеяла муку с крахмалом. В мучную смесь добавила яичную смесь небольшими порциями, аккуратно перемешивая тесто снизу вверх. Масса должна остаться воздушной, долго вымешивать бисквитное тесто не нужно.','https://vkuso.ru/data/cache/data/df/954d9b19c3fbfdf_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12791,'Выложила тесто в форму для выпечки диаметром 28 сантиметров. Выпекала примерно 30-40 минут. Во время выпекания духовку не открывала! 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12791,'Пока бисквит остывал, приготовила сметанный крем. Миксером смешала сметану с сахаром, добавила ванильный сахар и загуститель сметаны.','https://vkuso.ru/data/cache/data/2d/e83f4f069b7272d_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12791,'Остывший бисквит разрезала на две части. Нижний корж намазала кремом, на него выложила замороженную вишню, затем накрыла вторым коржом и перемазала весь торт кремом. Бока торта посыпала измельченной бисквитной крошкой, а верх засыпала измельченными орехами.','https://vkuso.ru/data/cache/data/9a/6e2ea5179460c9a_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12792,'Молодой кабачок порезать кружками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12792,'Если продукт жестковат – кожицу лучше снять, удалить семена, мякоть нарезать кусочками небольшого размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12792,'В отдельную мисочку насыпать пшеничную муку, посолить и поперчить, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12792,'Кусочки кабачка обвалять в панировке и жарить на предварительно нагретом растительном масле. Масла должно быть достаточно, иначе овощ подгорит.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12792,'Пропустить через пресс чеснок, смазать готовые кабачки, полить сметаной или майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12793,'Овощи очистить от кожуры и семечек, нарезать, обвалять в мучной панировке с солью и перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12793,'Жарить на сливочном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12793,'Белые грибы положить в кипяток, через несколько минут вынуть, нарезать кусочками, полить сметаной и посолить, потушить до готовности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12793,'Томаты ошпарить кипящей водой, снять кожицу, нарезать кусочками, посолить и поперчить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12793,'Жарить на сковороде.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12793,'На общее блюдо выложить грибы, затем кабачки и помидоры.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12793,'Кушанье посыпать рубленой зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12794,'Смешать муку, разрыхлитель и какао. В отдельной тарелке взбить яйца с сахаром (100 гр). Добавить молоко (160 мл) и растительное масло - перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12794,'Яичную смесь добавить к мучной смеси и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12794,'Форму смазать растительным маслом и залить тестом. Выпекаем в разогретой духовке 30 минут при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12794,'Вынимаем из формы и полностью остужаем. Затем вырезаем середину оставив при этом дно и бока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12794,'В ковш высыпаем желатин и заливаем молоком (200 мл). Оставляем на 30 минут. Затем ставим на медленный огонь пока не растворится желатин (!до кипения не доводить!)',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12794,'Сахар (80 гр) смешать с творогом. Затем влить содержимое ковша (желатин + молоко) и все тщательно перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12794,'В вырезанный торт сложить целиковые бананы на дно и залить творожной смесью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12794,'Остатки торта (те что вырезали) сложить в блендер и перемолоть в крошку. Посыпать ею торт и оставить в холоде на 3 часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12795,'Мелко нарезать петрушку и укроп. Нарезанную зелень соединить с зернами граната и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12795,'Говяжий фарш соединить с чесноком пропущенным через пресс, красным и черным перцем, солью и мелко нарубленным луком. Добавить яйцо и все тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12795,'Из фарша сформировать котлетки положив внутрь начинку из смеси граната и зелени. Готовую котлетку обвалять в панировочных сухарях.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12795,'Котлеты обжарить с двух сторон на растительном масле на среднем огне по 10 минут с каждой стороны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12796,'В миску высыпать муку и кусочки сливочного масла. Перетереть в крошку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12796,'Рабочую поверхность посыпать мукой и раскатать (не очень тонко). Стаканом вырезать круги.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12796,'Круг макнуть одной стороной в сахар, сложить пополам сахаром внутрь, и снова сложить пополам, а потом обмакнуть в сахар со всех сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12796,'Разогреть духовку до 200 градусов. Противень застелить пекарской бумагой и выложить печенье. Выпекаем 25 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12797,'В тарелку выложить консервированную кукурузу без сока, немного раздавить вилкой. Добавить творог.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12797,'Креветки очистить и мелко нарезать. Добавить в тарелку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12797,'Белки отделить от желтков. Желтки добавить в тарелку, высыпать кокосовую стружку, посолить и поперчить (по 1/2 ч. л.), добавить муку и все тщательно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12797,'Формируем оладьи и обжариваем на разогретом растительном масле с двух сторон по 15 минут на среднем огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12798,'Смешиваем муку, сахарную пудру, ванильный сахар и тертую лимонную цедру.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12798,'Тесто обмотать пленкой и убрать в холодильник на 1 час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12798,'Противень застелить бумагой для выпечки. Тесто раскатать, вырезать фигуры и выложить на противень.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12799,'Баклажаны и лук мелко нарезать кубиками. Чеснок дольками. Обжарить все на растительном масле в течении 15 минут на среднем огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12799,'У помидоров срезать шляпки и ложкой удалить мякоть. Эту мякоть отправить в сковородку к другим овощам - готовить 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12799,'Помидоры поставить на противень засыпать их начинкой из приготовленных овощей, сверху посыпать натертым сыром. Запекать в духовке 20 минут при температуре 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12800,'Смешиваем муку с разрыхлителем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12806,'Готовое филе выложить на блюдо, вокруг – очищенные дольки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12800,'Растворяем сахар в воде, добавляем растительное масло и постепенно вводим муку, замешивая тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12800,'Измельчаем яблоки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12800,'Посыпаем яблоки корицей и добавляем в тесто, перемешиваем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12800,'Тесто раскладываем по формочкам заполняя их на 2/3.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12800,'Отправляем в разогретую духовку на 190 градусов примерно на 25-30 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12801,'Для приготовления заправки перемешать соевый соус и рисовый уксус, немного кунжутного масла, подлить воду, добавить рубленый острый перец и зеленый лук, семена кунжута.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12801,'Смесь хорошо перемешать, оставить полтора часа для настаивания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12801,'Кабачок почистить, нарезать кусочками, посолить, обвалять в пшеничной муке и обжарить в растительном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12801,'Соус налить в небольшую емкость и поставить посередине большого блюда, вокруг выложить кабачки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12802,'Овощи очистить, нарезать небольшими кусочками по полтора сантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12802,'Обвалять в муке с солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12802,'Обжарить на растительном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12802,'Истолочь очищенные грецкие орехи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12802,'Нарезать зелень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12802,'Посыпать кабачки и заправить сметаной.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12803,'Свиные стейки хорошо промыть, промокнуть салфетками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12803,'Натереть мясо смесью перцев и солью, намазать готовой горчицей, лучше это сделать руками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12803,'Измельчить чеснок, перемешать со сметаной, намазать и этой смесью филе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12803,'Уложить куски друг на друга и оставить на четыре часа для пропитывания, во время маринования мясо переворачивать и менять местами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12803,'Выставить в мультиварке режим жарки, налить немного оливкового масла.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12803,'Стейки отжать от влаги, выложить на разогретое масло.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12803,'Сверху также сбрызнуть маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12803,'Закрыть крышку, готовить десять минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12803,'Затем перевернуть и прогревать еще десять минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12803,'Проверить готовность проколом, сок выделяться не должен.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12803,'Выложить мясо на тарелки, красиво сервировать свежими нарезанными овощами и зеленью.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12804,'Прежде чем готовить нужно на ночь замочить перловку в 500 мл кипятке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12804,'После слить воду, налить в кастрюлю 400 мл воды и перловку. На сильном огне довести до кипения и посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12804,'Убавить огонь до среднего и готовить 15-20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12804,'Тем временем начнём готовить соус. Разогреем масло в сковороде и обжарим мелко нарезанный лук и чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12804,'Залить томаты в собственном, томатную пасту, тимьян, орегано, соль, перец, паприку и перемешать. Готовить минут 5 на среднем огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12804,'По готовности перловки, слить воду и добавить к соусу. После добавить базилик, пармезан и все перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12805,'Мясо немного отбить кухонным молотком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12805,'Кефир перемешать со смесью итальянских трав, добавить перец и соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12805,'На дно емкости выложить лавровый лист.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12805,'Куски мяса обмазать кефиром со специями, выложить на лавровый лист.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12805,'Залить остатками кефира, накрыть крышкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12805,'Поставить в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12805,'Пропитавшееся мясо отжать, выложить на решетку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12805,'В мультиварку налить растительное масло, раскалить в режиме жарки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12805,'Выложить стейки, готовить под крышкой до появления корочки, перевернуть и дожарить с другой стороны.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12806,'Грейпфрут разобрать, шкурку удалить, дольки очистить от пленок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12806,'Из половины мякоти отжать сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12806,'Куски лосося промыть и подсушить, натереть подходящими специями, поперчить, посолить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12806,'Отжатый сок перемешать с растительным маслом, смесью полить рыбу и оставить для маринования на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12806,'Можно поставить в холодильник, в этом случае процесс займет больше времени.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12806,'Чашу мультиварки смазать оставшимся маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12806,'Рыбу отжать, выложить в разогретую емкость, режим «Выпечка».',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12806,'Закрыть, готовить блюдо полчаса. В конце приготовления рыбу перевернуть и допечь.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12807,'Лимон вымыть, разрезать пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12807,'Из половины выжать сок, подсолить и поперчить, можно добавить приправы для рыбы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12807,'Полученным соусом натереть рыбу, оставить на полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12807,'Оставшийся цитрус нарезать кружками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12807,'Переложить филе в корзину мультиварки, сверху – кружки лимона.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12807,'Налить кипящую воду в чашу, положить перец-горошек, корочки лимона, оставшиеся от выжатого сока.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12807,'Выставить режим варки на пару, готовить блюдо в течение двадцати минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12807,'Приготовить соус: взбить в блендере смесь майонеза, горчицы и кусочки соленого огурца, в конце положить зелень.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12807,'Масса не должна превратиться в пюре.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12807,'Стейки выложить на тарелки, полить соусом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12807,'Еще один соленый огурец нарезать пластинками и украсить кушанье.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12808,'Куски свинины промыть, очистить чеснок и нарезать пластинками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12808,'Перемешать с приправами для мяса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12808,'Сделать в филе поперечные проколы с боков острым ножом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12808,'Вставить в них кусочки чеснока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12808,'Мясо посолить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12808,'На дно чаши мультиварки налить немного масла, включить режим жарки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12808,'Выложить мясо с чесноком, жарить по пятнадцать минут с каждой стороны.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12808,'Мясо вынуть, подать к столу в горячем виде.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12808,'Чеснок можно не вынимать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12809,'Стейки хорошо промыть, обсушить при помощи салфеток и намазать горчицей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12809,'Посолить, поперчить, посыпать приправами для рыбных блюд.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12809,'Сбрызнуть лимонным соком, посыпать розмарином.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12809,'Оставить филе на 15 или 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12809,'Влить воду в чашу мультиварки, поставить корзинку для приготовления блюд на пару.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12809,'Выложить рыбу, сбрызнуть оливковым маслом, посыпать зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12809,'Выставить режим «Варка на пару» на полчаса или чуть меньше.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12809,'Положить несколько молодых картофелин в мундире.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12810,'Лососевое филе промыть, обсушить, нарезать полосками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12810,'Обычные помидоры или черри нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12810,'Небольшие очищенные креветки разморозить, откинуть на дуршлаг.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12810,'Выложить томаты, креветки и рыбу в миски, перемешать, добавить любые приправы, посолить и поперчить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12810,'Фольгу сложить вдвое, выложить в середину рыбу и креветки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12810,'Края подвернуть, сверток поместить в чашу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12810,'Выставить режим «Выпечка» на 40 или 45 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12811,'Сыр «Дор Блю» выложить в миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12811,'Влить натуральный йогурт, перемешать до однородного состояния вилкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12811,'Мелко порубить зелень, добавить в соус, влить лимонный сок, поперчить. Лучше использовать смесь перцев.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12811,'Все хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12811,'Нарезанное кусочками филе поместить в соус, оставить на два часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12811,'Очистить и нарезать небольшими кубиками морковь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12811,'Выложить в чашу мультиварки морковь, рис, замороженный зеленый горошек.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12811,'Всыпать куркуму, немного сушеных томатов, соль.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12811,'Влить воду.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12811,'Смесь осторожно перемешать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12811,'Сверху поставить емкость для приготовления на пару, застелить фольгой, выложить рыбу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12811,'Выставить режим «Плов».',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12812,'Брокколи переложить в дуршлаг и разморозить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12812,'Лососевое филе промыть, нарезать толстыми длинными кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12812,'Переложить рыбу в емкость для мультиварки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12812,'Готовить в режиме «Жарка» около получаса, крышку не закрывать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12812,'Рыбу несколько раз перевернуть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12812,'Через десять минут после начала готовки всыпать брокколи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12812,'Посолить и поперчить по вкусу, влить воду.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12812,'Продукты осторожно перемешать. Закрыть крышку, выставить подходящий режим.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12813,'Почистить и порезать мелкой соломкой чесночок, имбирь, перец чили.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12813,'Почистить стебли сельдерея от верхнего, волокнистого слоя, оставить сочную часть стебелька.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12813,'Порезать его тоненькой соломкой, чтобы она была толщиной четыре на один сантиметр. Листики оставить – они пригодятся.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12813,'Разогреть в сковороде масло, положить чили, чесночок, имбирь, насыпать сахар.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12813,'Обжаривать минуту, налить воду, добавить мисо пасту.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12813,'Позволить соусу покипеть несколько минут на небольшом огне.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12813,'Положить в соус орешки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12813,'Размешать все, накрыть крышкой, подождать, пока орехи пропитаются вкусом и влагой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12813,'Орешки должны стать мягкими, остаться упругими.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12813,'Когда орешки приготовятся, положить сельдерей.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12813,'Перемешать соус с сельдереем и кешью, обжаривать на большом огне минуты две.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12813,'Важно не передержать – сельдерей должен быть хрустящим и упругим.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12813,'За полминуты до конца готовки положить в сковороду листики сельдерея.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12813,'Перемешать, готовить еще полминуты.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12813,'Выложить горячий салат из стеблей сельдерея с кешью на блюдо.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12814,'Сварить кофе, охладить и процедить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12814,'В сотейник налить сливки, молоко, нагреть до теплого состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12814,'Положить в сотейник шоколад, поломанный на кусочки, растопить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12814,'Налить кофе, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12814,'Отдельно взбить чуть-чуть яйца, сахар, желток, соль.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12814,'Помешивать, не переставая.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12814,'В молочную смесь ввести яичную.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12814,'Налить молочно-яичную смесь в огнеупорные формочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12814,'Накрыть фольгой, поставить в глубокий противень, на ½ наполненный водой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12814,'Отправить противень на 35 минут в духовку, соблюдать температуру 160 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12814,'Достать кофейно-шоколадный мусс, позволить остыть, отправить часа на три в холодильник.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12815,'Соединить сахар, муку, яйца, кефир, мед.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12815,'Насыпать разрыхлитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12815,'Взбить с помощью миксера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12815,'Разделить тесто пополам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12815,'Выпекать оба коржа в духовке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12815,'Остудить коржи, разрезать на несколько частей вдоль.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12815,'Во время готовки коржей прокрутить через мясорубку курагу, чернослив, изюм. Перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12815,'Измельчить миндаль.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12815,'Сделать крем: соединить сметану с сахаром.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12815,'Взбить, позволить сахару растаять, перемешать.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12815,'Вместо сахара можно использовать сахарную пудру, сметаны можно использовать меньше.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12815,'Можно использовать ½ сметаны и сливки.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12815,'Намазать остывшие коржи кремом, посыпать орешками и перекрученными сухофруктами.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12815,'Обмазать бока.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12815,'Украсить тортик на свой вкус.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12815,'Бока посыпать крошкой, обложить сухофруктами и орешками.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12815,'Поставить ненадолго в тепло, а потом в холодильник.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12816,'Произвольно порезать курицу на кусочки, отбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12816,'Посыпать специями, перцем, солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12816,'Положить кусочки на противень, застеленный специальной бумагой и смазанный маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12816,'Мясо намазать майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12816,'Положить на кусочки курицы ананасы, посыпать сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12816,'Готовить минут 35, соблюдать температуру 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12817,'Нагреть духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12817,'Соединить в посуде просеянную муку с солью, сахаром, содой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12817,'Перемешать в кастрюльке на медленном огне сливочное масло, просеянное какао, кока-колу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12817,'Держать на огне до расплавления масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12817,'Налить масляную смесь в посуду с мукой, перемешать до однородности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12817,'Отдельно соединить яйцо, кефир, ванильную эссенцию.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12817,'Вылить в мучную смесь, размешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12817,'Перелить тесто в формочку, застеленную специальной бумагой, отправить в духовку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12817,'Готовность проверять зубочисткой, если она остается сухой, то готово.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12817,'Сделать глазурь.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12817,'Довести сливки до кипения, налить шоколад.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12817,'Отставить на пару минут, потом мешать до образования гладкой, блестящей, густой глазури.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12817,'Намазать глазурью бока и верх торта.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12818,'В кастрюльке среднего размера растопить масло сливочное.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12818,'Насыпать муку, размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12818,'Готовить несколько минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12818,'Насыпать соль, паприку, чесночный порошок, молотый черный перчик, красный перец.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12818,'Взбить до однородности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12818,'Медленно влить бульон и пиво.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12818,'Перемешать, чтобы исчезли комочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12818,'Добавить сливки, тертый сыр, вустерский соус.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12818,'Готовить дымчатый соус из пива с сыром на медленном огне до однородности, помешивать время от времени.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12819,'Обжарить орехи или семечки на сухой сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12819,'Растопить сахар и мед в кастрюльке с толстым дном, помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12819,'Следить, чтобы сахар растворился.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12819,'Высыпать в горячий сироп семечки, орехи, быстро и хорошо размешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12819,'Пока сироп не остыл, выложить в плоскую формочку, застеленную пергаментом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12819,'Приплюснуть руками, сформировать форму прямоугольника или квадрата.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12819,'Желательно разрезать сразу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12819,'Отставить, чтобы полностью застыл.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12819,'Пергамент удобно отделять при помощи лопатки и перенести гозинах (армянскую сладость) на блюдо.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12820,'Нагреть духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12820,'Подготовить картофель: выбрать картофель одного размера, помыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12820,'В полиэтиленовом пакетике соединить муку и соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12820,'Выложить чистый, еще влажный картофель в пакетик, встряхнуть, чтобы клубни облепились смесью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12820,'Выложить картофель на противень, отправить на шестьдесят минут в духовку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12820,'Готовность проверять зубочисткой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12820,'Выложить горячий картофель на тарелку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12820,'Разрезать, положить начинку: творожок с чесночком или зелень с маслом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12821,'Сварить 1-1,5 литра куриного бульона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12821,'Обжарить в кастрюльке лук и сосиски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12821,'Положить измельченный чесночок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12821,'Переложить содержимое банки с помидорами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12821,'Перемешать, если возможно, убрать шкурки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12821,'Залить куриным бульоном.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12821,'Уменьшить огонь, готовить под крышечкой минут тридцать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12821,'Положить в суп оставшиеся ингредиенты: куриные ножки, фасоль, «звездочки», базилик.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12821,'Посыпать перцем, солью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12821,'«Звездочки» во время варки превращаются в настоящие звезды, поэтому нужно не переборщить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12821,'Налить Итальянский томатный суп с сосисками и вермишелью в тарелки, посыпать тертым пармезаном и петрушкой.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12822,'Подготовим ингредиенты.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12822,'Тонкий лаваш нарезаем на равные полоски, по 5-7 см шириной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12822,'Далее, где у вас вся начинка, добавляем 3 ч.л. сметаны, столько же майонеза, по вкусу соль, перец. И все перемешиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12822,'На подготовленную полоску тонкого лаваша укладываем начинку, и все это заворачиваем в рулет.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12823,'Отварит в слегка подсоленной воде картофель, порезанный на небольшие дольки в течении 5 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12823,'Удалить у перца плодоножку и все семена, нарезать соломкой, кабачки с баклажанами – одинаковыми дольками, мясистые помидоры – на небольшие кубики, чеснок мелко порубить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12828,'Добавить томатную пасту, консервированные помидоры целиком, влить воду.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12965,'Яичный, сырный и майонезный слой повторить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12823,'В подготовленную форму выложить дольки картофеля, затем кабачки, слегка присолить, теперь положить баклажаны, присолить и поперчить, последним слоем уложить сладкий перец и присыпать чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12823,'Залить нежное и ароматное блюдо сметаной, затем помидорной массой и убрать на полчаса запекаться в духовку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12824,'Нарезать грудинку индейки поперек волокон, толщина кусочков – около двух сантиметров.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12824,'Приправить любыми специями для птицы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12824,'В мультиварку налить масло, прогреть, выставить режим выпечки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12824,'Выложить птицу, жарить по пять минут с каждой стороны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12824,'Нарезать репчатый лук и натереть морковь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12824,'Добавить смесь овощей к индейке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12824,'Закрыть мультиварку на двадцать минут, режим – тот же.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12825,'Нарезать индейку в виде стейков, толщина кусков – полтора сантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12825,'В соевый соус добавить молотый перец, полить птицу, втереть смесь руками и оставить на час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12825,'Разогреть масло в режиме выпечки, выложить птицу, жарить по десять-пятнадцать минут с каждой стороны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12825,'Влить вино, готовить далее по той же программе, но без крышки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12825,'В процессе приготовления вино должно выпариться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12826,'Порубить или пропустить через пресс зубчик чеснока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12826,'Перемешать в небольшой емкости горчицу с соевым соусом и апельсиновым фрешем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12826,'Добавить рубленую зелень и чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12826,'Ингредиенты перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12826,'Нарезать кусочками филе лосося, промыть, обсушить, посолить и переложить в маринад.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12826,'Время для пропитывания – час или полтора.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12826,'Выложить продукт в чашу мультиварки, влить воду, выставить режим «Выпечка» на полчаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12827,'Для приготовления теста зернистый творог протереть через сито или взять обычный, кремообразный продукт.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12827,'Перемешать с сахарным песком, солью, размягченным сливочным маслом, добавить немного взбитое сырое яйцо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12827,'В массу всыпать просеянную пшеничную муку, перемешанную с разрыхлителем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12827,'Тесто должно получиться мягким, при необходимости муку можно добавить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12827,'Колобок накрыть миской и дать постоять для набухания клейковины.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12827,'Крупные яблоки очистить от кожуры и семенных камер, мякоть нарезать небольшими кубиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12827,'Отдельно в сотейнике растопить еще одну порцию сливочного масла, добавить яблоки и сахар.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12827,'Начинку потушить до мягкости и выпаривания жидкости.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12827,'В конце приготовления добавить молотую корицу или ванилин из пакетика, изюм без косточек, массу перемешать и остудить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12827,'Застелить противень пергаментом, смазать маслом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12827,'Готовое тесто разделить на десять частей, раскатать в лепешки, выложить начинку и сформовать небольшие пирожки.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12827,'Выложить изделия на противень, смазать яйцом или только желтком.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12827,'Печь в заранее разогретой до 200 градусов духовке, до золотистого цвета.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12828,'Очистить зубчики чеснока, пропустить через чеснокодавку или мелко порезать острым ножом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12828,'В глубокую кастрюлю налить оливковое масло, добавить кусочек сливочного, поставить на огонь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12828,'Помешивать ложкой из дерева в течение двух минут, пока сливочное масло не растает.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12828,'Мелко нарезать репчатый лук, морковь, стебель сельдерея.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12828,'Всыпать овощную смесь в масло вместе с чесноком, жарить до десяти минут, помешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12828,'Овощи должны стать мягкими, но не подгореть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12828,'Добавить готовый фарш из говядины и свинины в равных пропорциях.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12828,'Перемешать все ингредиенты, размять ложкой, чтобы не было комочков, прогревать пять минут, до готовности фарша.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12828,'Влить молоко, перемешать, огонь увеличить, довести до кипения, прогревать 10 – 15 минут, пока молоко не впитается.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12828,'Влить сухое белое или красное вино, процесс повторить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12828,'Всыпать смесь сухих итальянских трав, соль и черный молотый перец.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12828,'Огонь увеличить, довести соус до кипения, продолжать помешивать и разминать помидоры ложкой.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12828,'Поставить кастрюлю на тихий огонь, тушить под крышкой, оставив небольшое отверстие для выхода пара.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12828,'Прогревать в течение часа, приподнимать крышку и перемешивать Болонезе каждые 15 минут.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12828,'В конце приготовления смесь должна стать густой и блестящей.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12828,'Огонь выключить, кастрюлю плотно закрыть, дать соусу постоять, пока отваривается лапша.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12828,'Паста должна остаться полутвердой.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12828,'Подать к столу, соус должен быть сверху.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12828,'По желанию блюдо можно посыпать тертым сыром Пармезан.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12829,'Для приготовления медовых коржей растопить на тихом огне натуральный мёд с коричневым сахаром и сливочным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12829,'Смесь снять с огня, остудить до комнатной температуры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12829,'Отдельно перемешать пшеничную муку с пищевой содой, всыпать какао-порошок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12829,'Сухие ингредиенты добавить в жидкие, вбить сырые куриные яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12829,'Добавить немного молока, если масса получилась слишком рыхлой и рассыпается.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12829,'Замесить эластичное тесто, разделить его на шесть частей, раскатать в тонкие лепешки диаметром 18 сантиметров.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12829,'Каждый корж выпекать в духовке по десять минут, температура приготовления – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12829,'Из вишен удалить косточки, выложить в миску, посыпать сахарным песком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12829,'Когда выделится сок, добавить воду, поставить на тихий огонь, тушить в течение 10 – 15 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12829,'Полученный сироп остудить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12829,'Для приготовления крема с помощью блендера взбить заранее охлажденные сливки в густую и плотную пену.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12829,'Сыр Маскарпоне перемешать с семечками из стручка ванили, всыпать сахарную пудру, ингредиенты взбить в однородный крем.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12829,'Ввести сливки, аккуратно перемешать кондитерским шпателем.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12829,'На каждый медовый корж нанести вишневый сироп, дать постоять, затем намазать слой крема.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12829,'Слои повторять.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12829,'Готовый торт должен охладиться и пропитаться, его нужно поставить в холодильник на два часа или на ночь.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12829,'Перед подачей на стол торт должен согреться при комнатной температуре в течение десяти минут.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12830,'Сыр натираем на мелкой терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12830,'Масло сливочное нужно растопить в микроволновке. По вкусу добавляем соль перец, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12830,'Тонкий лаваш нарезаем на равные полоски по 5-7 см.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12830,'Берем 1 ломтик лаваша смазываем его сливочным маслом. слегка посыпаем паприкой и посыпаем сыром, берем другой ломтик лаваша, так же его смазываем и слегка посыпаем гранулированным чесноком. Этот ломтик укладываем на тот которые вы посыпали сыром и паприкой. Должно быть так, то что между двух ломтиков лаваша, прослойка сыры ( и приправы которые вы добавили ранее)',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12830,'После чего, смазываем 1 строну заготовки чипсов из лаваша, и слегка посыпаем паприкой. И снова нарезаем уже на равные кусочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12830,'Перекладываем на противинь и отправляем в духовку на 15 минут. До тех пор, пока сыр не подплавляться, а лаваш не подрумянится. Все готово.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12831,'Лосось освобождаем от жидкости и разминаем вилочкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12831,'Натираем к лососю яйца, добавляем соевый соус и хрен, перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12831,'Готовим панировку: натираем твердый сыр и смешиваем с измельчёнными орехами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12831,'Формируем небольшие шарики, обваливаем их в панировке и выкладываем на шайбу из огурца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12832,'Пекинскую капусту шинкуем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12832,'Мелко нарезаем яйца и лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12832,'С банки тунца сливаем лишнее масло (но не все) и при необходимости разминаем. Смешиваем все ингредиенты с кукурузой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12832,'Для заправки: смешиваем сметану, горчицу, выдавливаем половину лимона, добавляем чуть-чуть соль и перец. Размешиваем и добавляем к салату. И наш потрясающе вкусный и легкий салат готов) всём приятного аппетита друзья)',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12833,'В чаше блендера взбить сахар и яйца, всыпать муку с гашеной содой, взбить до однородности, вылить тесто в смазанную форму, запечь в прогретой духовке до полной готовности, дать полностью остыть и разрезать на два коржа. Верхнюю часть порезать на кусочки, нижнюю оставить без изменения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12833,'Сварить из молока, муки, сахара и яйца однородный и густой крем, дать остыть, вмешать полпачки мягкого сливочного масла с ванилином.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12833,'Из белков и сахара выпечь безе, дать подсохнуть в течение часа при температуре 100 градусов, а потом отключить нагрев и оставить в духовке (дверцу не открывать) еще на час, удобнее это сделать заранее.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12833,'Промазать корж равномерным слоем остывшего крема, по кругу разложить по поверхности готовое безе. Обмакнуть оставшееся безе в крем и выложить вторым слоем. Шоколад поломать, растопить с добавление молока и хорошего сливочного масла на водяной бане, всыпать кусочки резаного бисквита, тщательно, но осторожно размешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12833,'Разложить глазурованные шоколадом кусочки по центру торта «Графские развалины», а сверху безе, смазанное снизу кремом. Последний штрих: залить торт  растопленным шоколадом с добавлением ст.л. растительного масла и убрать в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12834,'Готовое тесто для пиццы раскатать в лепешку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12834,'Нагреть гриль до температуры 200 – 210 градусов и сделать огонь минимальным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12834,'Основу обжарить до золотистой корочки с одной стороны в течение двух-пяти минут, корж перевернуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12834,'На обжаренную сторону выложить любую начинку: колбасу Пепперони, помидоры или томатную пасту, тертый сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12834,'Подержать пиццу на гриле до тех пор, пока не расплавится сыр, и корж не обжарится снизу до золотисто-коричневой корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12835,'Разрезать небольшую луковицу пополам, а затем на тонкие полукольца, перец и капусту нашинковать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12835,'Курицу отварить, порезать на кубики, огурцы – не слишком тонкой соломкой, помидоры – равными дольками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12835,'Для приготовления заправки смешать сметану с горчицей, солью и перцем, чеснок пропустить через пресс',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12835,'Переложить салат с курицей, перцем и пекинской капустой в салатницу, аккуратно размешать, приправить соусом, оформить верх блюда порезанным мелко перьями зеленого лука.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12836,'Печенье измельчить в крошку, перемешать с мягким, несоленым сливочным маслом и пастой Нутелла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12836,'Форму диаметром 20 – 23 сантиметра застелить бумагой для выпекания, выложить массу на дно, хорошо утрамбовать, сформовать высокие бортики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12836,'Поставить заготовку в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12836,'Для приготовления начинки перемешать свежее молоко, размягченное сливочное масло, сахарный песок, экстракт ванили.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12836,'Смесь довести до кипения и остудить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12836,'Охлажденную массу взбить с помощью блендера вместе с сухим молоком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12836,'Должен получиться крем без комочков.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12836,'Для карамели закрытую, нераспечатанную банку сгущенки поставить вариться на три часа в кипящую воду.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12836,'Мелко нарубить очищенный фундук.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12836,'Растопить в микроволновой печи шоколад со сливками в течение двух минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12836,'Перемешать с рублеными орехами.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12836,'На охлажденную основу вылить половину приготовленного молочного крема, выложить слой вареной сгущенки, затем остальной крем.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12836,'Форму поставить в холодильник.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12836,'Когда начинка застынет – полить торт шоколадно-ореховой глазурью, вернуть десерт в холодильник еще на два или три часа.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12837,'Подготовить куриное филе, замариновать в смеси чесночной кашицы, соевого соуса и рубленой зелени петрушки, дать постоять с полчаса или чуть больше в маринаде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12837,'Порезать на ломтики сыр, а помидоры на полукольца, смешать чеснок со сметаной. Надрезать филе, чтобы образовались пару кармашков, вложить помидоры и сыр, обмазать «чесночной» сметаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12837,'Противень смазать маслом, положить куриное филе с помидорами, сыром и сметаной, задвинуть его на полчаса в духовку с температурой 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12838,'Печенье перемолоть в муку при помощи блендера, добавить сахарный песок и растопленное сливочное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12838,'Тесто вымесить, выложить в разъемную форму и отправить в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12838,'Желатин в пластинках или сыпучий из пакетика положить в холодную воду на десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12838,'Из очищенных и промытых ягод клубники приготовить пюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12838,'Поставить на огонь кастрюлю небольшого размера, выложить пюре, желатин и сахар.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12838,'Массу перемешивать до тех пор, пока желатин не растворится.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12838,'Отдельно взбить сливки с сахаром.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12838,'Перемешать сметану, сливки, сырный крем до однородности, добавить пюре из клубники.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12838,'Выложить полученную смесь на охлажденный нижний слой, поставить в холодильник на два-три часа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12838,'Торт украсить клубникой и залить клубничным желе, приготовленным так, как написано на упаковке.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12838,'Десерт будет готов через полчаса, верхний слой должен застыть.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12839,'Для приготовления теста необходимо растопить сливочное масло на водяной бане.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12839,'Сырые куриные яйца взбить с сахаром в пышную пену в течение пяти-семи минут, влить масло и еще раз взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12839,'Просеянную пшеничную муку добавлять частями, каждый раз взбивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12839,'Должно получиться тесто, похожее на густую сметану.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12839,'Разогреть вафельницу в течение пяти минут, смазать растительным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12839,'Выливать на нижнюю середину формы по полторы столовые ложки готового теста, печь в течение двух минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12839,'Вафли скручивать в горячем виде, дать остыть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12839,'Для крема выложить в небольшую емкость сливочное масло комнатной температуры.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12839,'Взбить продукт с помощью миксера до пышности.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12839,'Вареную сгущенку добавлять порциями, в четыре-пять приемов, продолжать взбивать крем, пока он не станет однородным.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12839,'Наполнить трубочки с помощью шприца.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12839,'Дополнительно их можно глазировать растопленным на водяной бане шоколадом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12840,'Разморозить креветки.','https:https://st.vkuso.ru/data/cache/thumb/e6/00d9a828de877e6_434x295.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12840,'Авокадо очистить, мякоть нарезать кубиками и сбрызнуть свежим соком лайма.','https:https://st.vkuso.ru/data/cache/thumb/21/40b5c15f5a43d21_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12840,'Куриные яйца отварить, остудить, очистить и нарезать соломкой.','https:https://st.vkuso.ru/data/cache/thumb/0a/f6745e93efa760a_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12840,'Все ингредиенты перемешать, заправить майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12841,'Для теста перемешать сырое куриное яйцо с кефиром, добавить смесь из цельнозерновой и пшеничной муки с содой, всыпать соль и сахарный песок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12841,'Форму для выпекания в мультиварке смазать растительным маслом, тесто вылить, разровнять, выложить сверху тушеную капусту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12841,'Выставить режим «Выпечка» на полтора часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12841,'Блюдо можно приготовить в обычной духовке, время приготовления – 40 минут, температура – 200 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12842,'Подготовить мясо: обмыть, обсушить, зачистить от лишних пленочек, порезать на брусочки примерно по полтора сантиметра толщиной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12842,'Лук порезать тонкой соломкой, выставить режим «Обжарка» (на некоторых моделях мультиварок это будет режим «Выпечка»), сложить в чашу лук, готовить 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12842,'Открыть мультиварку, положить мясо, влить немного воды, сметаны, томатной пасты, приправить специями, подсолить, размешать, защелкнуть крышку. Поставить мультиварку на «Тушение», а время установить 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12842,'Идеальным классическим гарниром к бефстроганов в мультиварке по-домашнему будет пюре, но можно подать и с любой пастой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12843,'В емкости среднего размера перемешать сухое молоко и какао-порошок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12843,'Отдельно приготовить сироп из сахара и воды, довести его до кипения, огонь убавить и варить до полного растворения сахара.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12843,'Кипятить еще десять минут, потом добавить сливочное масло и вновь довести до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12843,'Снять с плиты, добавить молочно-шоколадную массу, ванильный экстракт и перемешать до однородного состояния.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12843,'Лоток прямоугольной формы смазать сливочным маслом, перелить смесь и остудить до комнатной температуры.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12843,'Разрезать массу на небольшие квадратики и подать к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12844,'Замочить сушки в молоке на тридцать минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12844,'Порезать сосиски на кружки, лук на полукольца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12844,'Потереть сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12844,'Положить сушки на противень, застеленный пергаментом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12844,'Положить на сушки по колечку сосиски, накапать кетчуп.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12844,'Положить сверху лучок, накапать майонез.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12844,'Посыпать сырком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12844,'Готовить сушки с сосисками на завтрак минут пятнадцать, соблюдать температуру 180 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Сварить бульон, не солить его.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Довести до кипения, слить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Снова налить воду, варить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Положить целую луковицу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Готовить на среднем огне часа полтора. Снимать пенку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Минут за тридцать до конца готовки положить лавровый листик, несколько горошинок перца.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Готовое мясо вытащить, чуть-чуть остудить, порезать на маленькие кусочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Процедить бульон.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Обжарить минуты три измельченный лук и морковь на растительном масле.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Порезать на кубики огурцы, положить к моркови и луку.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Обжаривать минуты четыре.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Положить томатную пасту, тушить минут семь.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Порезать копчености на кусочки или кубики.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Подогреть бульон.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Отдельно чуть-чуть обжарить конечности.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Положить копчености и порезанное мясо в кипящий бульон, варить минут семь.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Положить каперсы.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Сразу добавить морковь и лук, половину стакана рассола от маслин или огурцов, варить минут семь.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Положить перец, лавровый листик, зелень.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Насыпать соль.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Позволить настояться под крышкой минут двадцать.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'Убрать лавровый лист.',NULL,23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'В конце добавить в ароматную солянку из говядины с копченостями',NULL,24);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12845,'маслины и лимон, порезанный на тоненькие ломтики.',NULL,25);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12846,'Перемешать молотый красный перец и половину цедры лимона, добавить порубленную зелень, подсолить, поперчить, перемешать все с креветками, дать постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12846,'Обжарить чеснок в разогретом масле, добавить оставшуюся цедру и помидоры, протушить все вместе пару минут, отдельно слегка обжарить креветки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12846,'Сварить лапшу, отбросить на дуршлаг, стакан жидкости оставить и влить его к креветкам, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12846,'Выложить пасту на большую прогретую тарелку, добавить листья шпината, полить соком лимона, подсолить, поперчить, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12846,'Подавать пасту с креветками, помидорами, шпинатом и лимоном с натертым пармезаном и свежим хрустящим хлебом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12847,'Сахар и яйца взбиваем до белой массы. Добавляем сметану и продолжаем взбивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12847,'Добавляем цедру, разрыхлитель и просеянную муку. Замешиваем тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12847,'Выкладываем в форму тесто (дно формы выстилаем пергаментом и смазываем маслом дно и бока), на тесто выкладываем дольки мандаринов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12847,'Сверху на мандарины выкладываем кусочки сливочного масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12847,'Отправляем пирог в разогретую духовку на 180 градусов примерно на 30 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12848,'Нарезать подготовленное филе лосося на мелкие кубики, побрызгать свежевыжатым соком лимона, всыпать порубленную петрушку и часть зеленого лука, сдобрить солью, перемешать. Творожный сыр перемешать с взбитыми яйцами, объединить с кусочками рыбы и панировочными сухарями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12848,'Смочить руки, сделать котлеты, обмакнуть со всех сторон в крошку из кукурузных хлопьев, обжарить котлеты в разогретом масле. Нарезать мелко помидоры, перемешать со сметаной и майонезом, добавить лук, посолить, подавать соус с горячими домашними котлетами из лосося.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12849,'Порезать огурец и морковь соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12849,'С бедрышек удалить кожу и вырезать кости, посолить, присыпать паприкой, обжарить в разогретом масле с обеих сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12849,'Выложить на тарелку, прикрыть другой, чтобы остались теплыми.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12849,'В оставшемся в сковороде масле обжарить соломку сладкого перца до слегка хрустящего состояния.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12849,'Мясо порезать на кусочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12849,'Лист лаваша промазать айоли, положить салат и другие ингредиенты, край листа оставить не промазанным.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12849,'Завернуть на начинку и свернуть рулетом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12850,'Разморозить вишню, при желании присыпать сахаром, оставить на час для выделения сока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12850,'Соус приготовить заранее, перемешать в кастрюльке все ингредиенты, прогреть на среднем огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12850,'Дать сахару полностью раствориться, прокипятить все еще пару минут и снять с плиты, дать остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12850,'Для приготовления теста взбить с подсоленным молоком яйца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12850,'В достаточно глубокую миску просеять муку, тщательно перемешать с молочно-яичной смесью, добавить воду до образования эластичной однородной массы, не липнувшей к рукам.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12850,'Колобок теста разделить на 4 части, из каждой раскатать пласт не тоще 0,5 см.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12850,'Подходящей по диаметру формой вырезать сочни для вишневых вареников с соусом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12850,'Положить на каждую заготовку по 3-4 вишенки, перегнуть пополам, тщательно защипать края.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12850,'Переложить вареники на доску, присыпанную небольшим количеством муки, прикрыть тканью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12850,'Опустить, помешивая вареники в подсоленный кипяток, варить пока все не окажутся на поверхности, варить еще пару минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12850,'Выловить, переложить на блюдо, полить растопленным маслом, присыпать сахарной пудрой, подать с ягодным соусом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12851,'Влить в чашу миксера молоко, всыпать сахар, добавить пудинг, взбить все до состояния крема около 3-5 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12851,'Соединить с мягким творогом, осторожно перемешать, используя лопаточку, до однородности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12851,'Форму (прямоугольную) промазать маслом, заполнить творожной массой, часть ее оставить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12851,'Обмакнуть печенье в молоко, вставить в крем, прикрыть оставшимся кремом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12851,'Затянуть форму пленкой, убрать на ночь в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12851,'Вынуть из формы, присыпать стружкой шоколада.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12852,'Сварить очищенный картофель до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12852,'Луковицу нашинковать кубиками, обжарить на масле до золотистого оттенка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12852,'Отдельно обжарить другую – до прозрачности, добавить нарезанные грибы, жарить, помешивая четверть часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12852,'Добавить перец и соль, сметану, перемешать, протушить 10 минут, снять с плиты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12852,'Слить с картофеля воду, часть оставить для приготовления пюре, вбить яйцо, положить обжаренный лук, поперчить, подсолить всыпать муку, тщательно перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12852,'Из полученной массы скатать палочки, обвалять со всех сторон в сухарях с мукой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12852,'Обжарить в хорошо разогретом масле до появления золотистого цвета.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12852,'Переложить картофельные палочки с грибами в панировке на несколько слоев бумажных салфеток, осторожно промокнуть каждую от излишков масла.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12853,'Включить для прогревания до 175 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12853,'Горький шоколад растопить на водяной бане, либо в микроволновке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12853,'Перемешать и взбить четверть стакана сахара и желтки в пышную массу примерно 5 минут, смешать с помощью миксера (скорость малая) с охлажденным шоколадом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12853,'Белки комнатной температуры взбить до получения пены, всыпать пару столовых ложек сахара, продолжить взбивать до получения устойчивых пиков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12853,'Объединить желтковую массу с четвертью белковой, очень осторожно перемешать лопаточкой, добавить остатки взбитого белка, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12853,'Подготовить противень, чуть смазать маслом, застелить пергаментом, вылить на него массу, выпекать корж для шоколадного торта со сливочным кремом без муки примерно 15-18 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12883,'На луковицы, как на подушку, выкладываем грудинку шкуркой вверх.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12853,'Достать противень, аккуратно перевернуть на лист бумаги для выпечки, осторожно удалить пергамент, дать остыть, убрать в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12853,'Приготовить из взбитых до пиков сливок и сахарной пудры крем.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12853,'Хорошо охлажденный корж порезать очень острым ножом на три равные полосы.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12853,'С помощью кондитерского мешка высадить на них крем, сложить их друг на друга, верх десерта присыпать тертым шоколадом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12854,'Сварить яйца, крупно натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12854,'Крабовые палочки и сыр – мелко натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12854,'Чеснок пропустить через пресс.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12854,'Половину измельченных палочек оставить, все перемешать с небольшим количеством майонеза.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12854,'Сформовать из массы крабовые рафаэлки с чесноком, обвалять в оставленной крабовой стружке.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12855,'Сварить и измельчить кальмары, всыпать тертый сыр, добавить пару яиц, сдобрить перчиком, мускатным орехом и солью, перемешать. Нагреть духовку (достаточно будет 200 градусов). Постелить на противень бумагу для выпечки, чуть смазать маслом, выложить массу из кальмаров, разровнять, задвинуть противень на 10 минут в духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12855,'Измельчить вареные яйца, нарезать зелень и огурцы, достать основу рулета, дать слегка остыть, нанести слой творожного сыра, сверху —  зелень с огурцами, затем опять сыр, присыпать порубленными яйцами. Аккуратно свернуть пласт, упаковать вкусный рулет для любителей кальмаров в фольгу, дать остыть и можно подавать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12856,'Прогреть до 180 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12856,'Нарезать на сантиметровые кубики сыр и ветчину.','https:https://st.vkuso.ru/data/cache/thumb/6a/faa2984576a966a_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12856,'Также нарезать сыр.','https:https://st.vkuso.ru/data/cache/thumb/fc/b9fe783f9be05fc_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12856,'Взбить вилкой яйца с кефиром и солью.','https:https://st.vkuso.ru/data/cache/thumb/b1/eafd697086e11b1_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12856,'Частями всыпать просеянную муку, смешанную с разрыхлителем.','https:https://st.vkuso.ru/data/cache/thumb/01/4ae4c274e38a601_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12856,'Хорошо вымесить, добавить измельченные ветчину и сыр, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/49/acaa61f5ab44c49_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12856,'Заполнить полученной массой форму, смазанную маслом.','https:https://st.vkuso.ru/data/cache/thumb/da/aaf24ba76b5cada_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12856,'Пирог с сыром и ветчиной на кефире в духовке будет готов через 35-40 минут.','https:https://st.vkuso.ru/data/cache/thumb/83/1d6c90fb322cf83_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12857,'Перемешать сливки с яйцом, солью, ванилином, сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12857,'Всыпать частями муку с разрыхлителем, вымесить тесто до исчезновения комочков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12857,'Два белка взбить до образования пены, объединить с тестом, влить пару ложек растопленного сливочного масла, тщательно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12857,'Выпекать бисквитные оладьи на сливках на разогретой сковороде в небольшом количестве растопленного масла с двух сторон до золотистости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12858,'Нужно испечь три коржа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12858,'Взбить белки в пену, всыпать сахар, продолжить взбивать до глянцевой массы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12858,'Всыпать муку и орехи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12858,'Перемешать до однородного состояния, застелить противень пергаментом, вылить тесто, выпекать в прогретой духовке треть часа при температуре 170 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12858,'Из сахара, желтков, молока, муки и ванильного сахара приготовить крем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12858,'Для этого все смешать, мешая довести практически до кипения и убрать с плиты, продолжая пару минут еще мешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12858,'Дать крему остыть, добавить кусочки масла, взбить в однородную массу, используя миксер.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12858,'Для хрустящего наполнителя сахар растопить до изменения цвета, вылить его на пергамент, дать остыть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12858,'Прикрыть вторым листом, раздавить в крошку, прокатав скалкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12858,'Перемешать сахарные кусочки с хорошо взбитыми сливками и измельченными орехами.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12858,'На остывший корж выложить треть крема, прикрыть хрустящим наполнителем, повторить все с остальными коржами.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12858,'Смазать готовый египетский торт с молочным кремом со всех сторон хрустящим наполнителем, оформить орехами.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12864,'На подготовленный пласт теста, укладываем начинку, заворачиваем к конвертик, кроя зажимаем, и сверху делаем небольшой надрез.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12965,'Украсить блюдо отваренными морепродуктами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12859,'Нарезать говядину небольшими кусочками, слегка обвалять в муке, быстро зажарить в сильно прогретом масле до появления темной корочки. Влить в сковороду бульон, всыпать порезанный мелкими кубиками лук, дать закипеть, уменьшить нагрев, прикрыть крышкой, готовить около часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12859,'Подготовить и нарезать морковку, стебель сельдерея, картофель, соединить с мясом, добавить молотый перец, перемешать. Говядина тушеная с картофелем и сельдереем будет готова примерно через полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12859,'Довести до готовности мясо с овощами можно в духовке, разложив по порционным горшочкам, добавить перед подачей в каждый ложечку сметаны и зелень.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12860,'Приготовление салата я начала с маринования лука. Нарезала его полукольцами, добавила уксус, воду, соль, сахар. Перемешала, оставила мариноваться и приступила к нарезке остальных ингредиентов.','https://vkuso.ru/data/cache/data/b3/9fcda8f4625d4b3_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12860,'Нарезала соломкой куриное филе и сладкий перец. Мелко порезала петрушку, чеснок и орехи.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12860,'Надеюсь, Вам понравится. Приятного аппетита и хорошего дня!','https://vkuso.ru/data/cache/data/0b/2a9bd75342ccf0b_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12861,'Положила филе, почищенную морковь, лук, чеснок в кастрюлю.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12861,'Залила желатин горячим бульоном и размешала до полного растворения. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12861,'Белки отделила от желтков и нарезала их кубиками (желтки нам не понадобятся).
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12861,'Бульон процедила (всего необходимо 500 мл бульона).
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12861,'Выложила на дно формочки зелень. На зелень выложила смесь из мяса и овощей.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12861,'Надеюсь, Вам понравится. Приятного аппетита!','https://vkuso.ru/data/cache/data/e8/180c268d3fa01e8_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12862,'Слить из ананасов сок, переложить в блендер, измельчить, переложить в дуршлаг, дать стечь лишнему соку. Залить на треть часа кипятком мелко нарубленный фиолетовый лук, потом процедить. Для заправки хорошо перемешать сметану с майонезом, натереть вареные яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12862,'Салат с вареными креветками и ананасом разложить по порционным салатникам в следующем порядке: яйца, лук, креветки, ананасы, яйца. После каждого слоя добавлять заправку, верх оформить стружкой сыра и крупной ореховой крошкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12863,'Просеять отдельно сахарную пудру и муку, смешать в миске с мягким маслом, ванильным сахаром и щепоткой соли до однородности. Добавить в половину полученного теста какао, вторую оставить светлой. Обернуть оба куска в пергамент, убрать на пару часов в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12863,'Присыпать стол мукой, достать тесто, раскатать в два тонких пласта. Отделить белок яйца, взбить, смазать темный корж, сверху уложить светлый, осторожно свернуть в рулет, отправить застыть в холодильник. Вынуть рулет, порезать поперек на «шайбочки».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12863,'Нагреть духовой шкаф (будет достаточно 190 градусов), выложить кусочки на противень, промазанный небольшим количеством масла, задвинуть его в духовку. Десертный рулет «День и ночь» будет готов примерно через четверть часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12864,'Для начала, нужно очистить яблоки от кожицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12864,'Далее мелко нарезаем яблоки на кубики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12864,'Перекладываем в миску, добавляем сахар и корицу, и перемешиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12864,'Раскатываем тесто. Нарезаем его на равные части. Снова слегка раскатываем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12883,'Грудинку натираем смесью соли и перца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12864,'Вбиваем куриное яйцо, и смазываем им поверхность слоек. Отправляем в духовку при 180 С, на 15-20 минут. Все готово.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12865,'Сперва смешала желтки с коричневым сахаром (150 гр), апельсиновым соком, ванилью, цедрой и маслом и тщательно взбила до получения однородной массы. Затем в получившуюся смесь просеяла муку с разрыхлителем и перемешала до получения однородной массы.','https://vkuso.ru/data/cache/data/c7/63f71b195ad4cc7_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12865,'В отдельной емкости взбила белки с солью до получения воздушной массы, постепенно добавила туда сахар.','https://vkuso.ru/data/cache/data/b7/87953ce4fd3f3b7_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12865,'В апельсиновое тесто добавила примерно треть белковой смеси и перемешала до получения однородной смеси. Затем добавила оставшиеся белки и аккуратно перемешала до однородного состояния. Залила получившееся тесто в подготовленную форму для выпечки (смазанную маслом), слегка перемешала, чтобы выпустить случайные пузырьки воздуха.','https://vkuso.ru/data/cache/data/d6/0f4d884ca875fd6_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12865,'Поместила форму в духовку, разогретую до 180°, и выпекала примерно 40-45 минут. Готовность пирога проверяла шпажкой, когда она вышла сухой и чистой – пирог был готов.','https://vkuso.ru/data/cache/data/2d/119cf25b43fbe2d_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12865,'Надеюсь, Вам понравится. Приятного аппетита!','https://vkuso.ru/data/cache/data/1b/f740faae08f811b_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12866,'Капкейки:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12866,'Продолжая взбивать добавить одно яйцо, затем второе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12866,'Постепенно ввести просеянную муку с содой, затем добавить ванильный сахар и молоко, продолжать взбивать до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12866,'Заполнить на 2/3 формочки для кексов. Выпекать при 170 С 22 мин.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12866,'Крем:
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12866,'Небольшими частями ввести просеянную сахарную пудру.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12866,'В конце добавить молоко и взбить до однородности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12866,'Разделить крем на части, добавить пищевой краситель, перемешать. Украсить капкейки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12867,'Измельчаем шоколад в крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12867,'Смешиваем муку, шоколад и сахарную пудру.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12867,'Добавляем желтки и размягченное сливочное масло. Быстро замешиваем тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12867,'Помещаем тесто в пакет и отправляем в холодильник на 60 мин.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12867,'Делим тесто на 8 частей, а затем каждую часть еще на 3.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12867,'Каждый кусочек теста делим пополам и раскатываем 2 жгутика по 15 см длиной и переплетаем их в веночек, защипываем концы и выкладываем на лист для выпечки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12867,'Смазываем каждое печенье желтком, разведенным 1 ст. ложкой воды и посыпаем разноцветной кокосовой стружкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12867,'Отправляем в разогретую духовку на температуру 170 градусов примерно на 12-15 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12868,'Приготовить из банана пюре, смешать с лимонным соком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12868,'Творог без крупинок, протертый через сито, смешать с манкой, сухарями и фруктовым пюре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12868,'Яйцо комнатной температуры с добавлением щепотки соли взбить, объединить с творожной массой, хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12868,'Заполнить пастообразной массой формочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12868,'Выпекать творожно-банановое суфле с манкой 20-25 минут в духовке при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12869,'Мясо курицы порезать на средние кусочки, подсолить, поперчить, добавить желатин, чеснок, раздавленный прессом, специи, перемешать, дать постоять треть часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12869,'Взять пакет для запекания, завязать один конец, поместить в жестяную банку (примерно на 600 мл), заполнить мясом, утрамбовать, завязать верх пакета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12869,'Поставить куриную ветчину с итальянскими травами в банке на час в духовку с температурой 190 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12869,'Остудить прямо в банке, поставить в холодильник, утром достать и удалить пакет.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12870,'Из просеянной муки и сухих дрожжей с добавлением оливкового масла, соли и сахара приготовить на воде тесто, дать постоять в тепле около часа, чтобы увеличилось в объеме.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12870,'Для начинки нарезать на тонкие пластинки шампиньоны, помидоры – на полукольца, измельчить на терке сыр, подготовить куриный фарш. Дать прогреться до 200 градусов духовке. Раскатать в полсантиметра тесто для основания пиццы, уложить на смазанный маслом противень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12870,'Смазать основу тонким слоем томатного соуса, равномерно разложить куриный фарш, пластинки грибов, помидоры, побрызгать оливковым маслом, сдобрить приправой для пиццы, задвинуть противень в духовку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12870,'Для начала подержать пиццу с шампиньонами и куриным фаршем около 6 минут, достать, присыпать сырной стружкой, отправить еще на четверть часа допекаться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12871,'Перемешать йогурт (сметану), сахар, яйца, какао, муку до получения однородной массы без комочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12871,'Влить соду, погашенную уксусом, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12871,'Вылить сразу в смазанную форму, выпекать 30-40 минут при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12871,'Дать остыть, вынуть из формы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12871,'Приготовить из смеси вареной сгущенки, масла и теплого какао на молоке крем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12871,'Разрезать струной или длинным острым ножом вдоль корж на три части.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12871,'Пропитать корж смесью крепкой заварки с сахаром и добавлением любого алкоголя.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12871,'Смазать кремом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12871,'Разложить по поверхности ягоды вишни (можно из варенья или компота), прикрыть другим коржом и все повторить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12871,'Верх торта смазать кремом и оформить ягодами и натертым шоколадом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12872,'Смешать дрожжи и муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12872,'Влить, перемешивая теплую воду с добавлением оливкового масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12872,'Тщательно вымесить тесто, накрыть полотенцем, оставить созревать в тепле на 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12872,'Сыр натереть, перец нашинковать, помидоры порезать на кольца, фарш обжарить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12872,'Тесто обмять, сформовать в шар, раскатать в круг диаметром 30 см, а толщиной не превышающий 5 мм, смазать ровным слоем томатного соуса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12872,'Разложить по поверхности кружочки помидора, фарш, посыпать зеленью и перцем, а последним слоем – тертый сыр.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12872,'Поставить пиццу с фаршем, помидорами и болгарским перцем в духовку с температурой 220 градусов на четверть часа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12873,'Порубить масло с мукой до образования крошки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12873,'Добавить яйца, сахар, муку, соль, гашеную соду, вымесить быстро песочное тесто, обернуть пленкой, положить на полчаса в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12873,'Тесто достать, раскатать в 3 мм пласт, вырезать круги, заполнить ими формочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12873,'Застелить кусочками пергамента, заполнить горохом, выпекать при 200 градусах 8 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12873,'Достать корзиночки, удалить горох вместе с бумагой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12873,'Для заливки сливки взбить с яйцом, подсолить, поперчить, всыпать цедру лимона и порубленный укроп.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12873,'Разложить по тарталеткам рыбу, заполнить заливкой, выпекать треть часа в прогретой до 170 градусов духовке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12874,'Залить дрожжи сладкой теплой водой, всыпать полстакана муки, размешать, накрыть емкость тканью, дать созреть опаре примерно полчаса в теплом месте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12874,'Добавить остальную муку, теплое молоко, желтки, ванильный сахар, соль, вымесить, влить масло, перемешать, поставить в тепло на 3 часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12874,'Через час-полтора обмять и дать опять подняться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12874,'Сформовать булочки, начинить кусочками конфет.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12874,'Выложить в промасленную форму, смазать верх разболтанным яйцом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12874,'Печь четверть часа при 200 градусах.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12875,'Просеять муку, смешать с дрожжами, маслом, сахаром, яйцом, солью и молоком, вымесить до однородного гладкого и нежного теста, накрыть его тканью, дать постоять минут 45.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12875,'Раскатать тесто в пласт, присыпать смесью корицы с сахаром, завернуть в рулет. Порезать поперек на куски шириной не более 2 сантиметров, разложить на выстланный бумагой и смазанный маслом противень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12875,'Взбить яйцо с добавлением щепотки соли, смазать булочки. Противень прикрыть полотенцем, оставить на час-полтора в сторону. Выпекать аппетитные сдобные булочки с корицей в прогретой чуть ниже 190 градусов духовке примерно четверть часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12883,'На шкурке делаем неглубокие надрезы на расстоянии 2 см друг от друга.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12883,'Смазываем маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12883,'Разрезаем крупные луковицы пополам и выкладываем в форму (Заранее в форму добавляем пару столовых ложек воды).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12876,'Просеять муку, сахар и соль, перемешать, соединить с сыром. Положить в муку холодное масло, порубить до состояния маслянистой крошки, добавить лимонный сок и по частям охлажденную воду, тщательно перемешать. Полученное тесто раскатать в пласт, переложить в подготовленную форму, сформовать бортики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12876,'Обдать помидоры крутым кипятком, окатить холодной водой, снять кожицу, мелко порезать, добавить нашинкованный лук-порей, выложить слоями на основу из теста, чередуя с приправами. Прикрыть помидоры смесью майонеза с сыром. Отправить домашний томатный пирог на 40-45 минут выпекаться в прогретую до 175 градусов духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12877,'Натереть сыр, соединить с яйцами, хорошо перемешать до однородного состояния. Полученную массу вылить на застланный пергаментом противень, отправить в прогретую до 185 градусов духовку, запечь до золотистого цвета, дать остыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12877,'Смешать для начинки свинину с говядиной, влить вино, добавить имбирь, сдобрить солью и черным перцем, перемешать. Порубить зелень, красный болгарский перец нарезать на небольшие кубики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12877,'Выложить на остывший сырный пласт фарш, присыпать кубиками перца и зеленью, свернуть в рулет, упаковать в фольгу. Убрать рулет из сырного теста с мясным фаршем на 40 минут в прогретый до 200 градусов духовой шкаф. Готовое блюдо вынуть, дать остыть прямо в фольге, нарезать и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12878,'Протереть творог через мелкое сито, объединить с корицей, бананами, яйцами, взбить блендером.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12878,'Вылить полученную смесь в силиконовую форму, задвинуть творожную запеканку с бананом для детей на 35 минут в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12879,'Мелко порезать чеснок, пожарить в разогретом масле (примерно минуту), добавить томатную пасту, перемешать, прогреть пару минут, всыпать рис, размешать, влить порциями бульон, после каждого добавления содержимое сковороды перемешивать, готовить полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12879,'Отключить нагрев, убрать с плиты, переложить рис на блюдо, дать остыть. Нарезать баклажан на тонкие длинные полоски, присолить, положить в дуршлаг, опустить его на час в воду, вынуть баклажаны, обсушить, побрызгать маслом, зажарить на гриле.На полоски разложить рис, свернуть в рулеты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12879,'Выложить на дно керамической формы соус маринара, на него – рулетики, залить верх соусом маринара, прикрыть крышкой, подержать треть часа в духовке, прогретой чуть выше 170 градусов. Форму открыть, рулеты из баклажанов с ризотто запекать еще 10 минут, вынуть, сразу присыпать сырной стружкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12880,'Подготовить кролика: помыть, обсушить, нарубить на порционные куски. Переложить мясо в мультиварку (чашу смазать маслом), выставить режим «Выпечка», готовить полчаса (пару раз перевернуть).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12880,'Нашинковать лук, мелко нарезать морковь, выложить на мясо, влить небольшое количество воды, поменять режим на «Тушение», тушить 35 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12880,'Смешать горчицу, сметану, перец, соль, залить мясо с овощами, режим не менять, готовить кролика тушеного с морковью в мультиварке еще полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12881,'Порубить кролика на куски, натереть морковь (лучше на терке для корейской морковки), нарезать лук-порей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12881,'Переложить куски в мультиварку, засыпать луком с морковью, залить водой, чтобы чуть покрыла блюдо, приправить любимыми специями, молотым черным перцем, солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12881,'Готовить кролика в мультиварке по-деревенски  15 минут в режиме «Варка на пару», переключить на «Тушение» и через 2 часа диетическое блюдо готово.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12882,'До готовности отварить яйца, а после того, как они остынут, очистить и нарезать соломкой. Помидорки черри промыть под водой, обсушить и разрезать каждый плод на четвертинки. С консервированных кальмаров слить жидкость и нарезать тушки небольшими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12882,'С кукурузы и оливок также слить жидкость и разрезать последние пополам. Капусту помыть, обсушить и нашинковать соломкой. Петрушку промыть, обсушить и мелко порубить. Смешать все подготовленные продукты (кроме петрушки) в салатнике или большой миске и добавить отварные креветки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12882,'Заправить салат с креветками, кукурузой и кальмарами майонезом и хорошо перемешать. Получившийся салат непосредственно перед подачей украсить измельченной петрушкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12883,'Отправляем в духовку на 160 градусов примерно на 2 часа. Приятного аппетита!',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12884,'Для основы: к свиному фаршу добавить яйцо, измельченный репчатый лук, молок, муку, черный перец и соль и тщательно перемешать все до однородности. Для начинки: плавленый сырок и ветчину нарезать небольшими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12884,'На пищевую пленку выложить мясную массу таким образом, чтобы получился ровный прямоугольник высотой 1-1,5 см и размером 25х30 см. На середину по высоте уложить кубики сыра и ветчины и с помощью пленки свернуть фарш в рулет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12884,'Затем приподнять пленку с обеих сторон и склеить края мясного рулета. Швом вниз аккуратно переложить мясной рулет с начинкой из сыра и ветчины в форму для запекания, предварительно смазанную маслом. Запекать в духовке в районе 40-50 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12885,'Залить водой комнатной температурой желатин, дать ему разбухнуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12885,'Крупно натереть яблоки без кожуры, переложить в кастрюлю, засыпать сахаром, подогреть почти до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12885,'Нагрев сделать минимальным, тушить, помешивая полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12885,'Разболтать крахмал в воде.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12885,'Влить к яблокам, перемешать, дать закипеть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12885,'Немного остудить пюре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12885,'Взбить блендером, влить раствор желатина (растворить на водяной бане), хорошо перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12885,'Застелить любую форму пищевой пленкой, заполнить яблочным пюре.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12885,'Поставить Мармелад из яблок с крахмалом и желатином  в холодильник, дать хорошо застыть.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12886,'Вымыть помидоры черри, разрезать на четвертинки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12886,'Свежий огурец нарезать полукружьями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12886,'Сладкий болгарский перец очистить от семян, нарезать соломкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12886,'Маслины разрезать пополам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12886,'Стебли петрушки нашинковать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12886,'Репчатый лук нарезать полукольцами, сыр «Фета» – кубиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12886,'Ингредиенты перемешать, залить оливковым маслом, посолить, поперчить, посыпать льняными семечками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12887,'Свежие помидоры, огурцы, болгарский перец вымыть, нарезать треугольниками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12887,'Красный лук очистить, нашинковать полукольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12887,'Вымыть зелень тимьяна, петрушки, базилика, просушить, измельчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12887,'В небольшой мисочке перемешать лимонный сок с оливковым маслом, солью, перцем, зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12887,'В полученную заправку выложить лук, перемешать, дать постоять для пропитывания от десяти до пятнадцати минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12887,'Добавить лук с маслом в овощи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12887,'Нарезать брынзу, оливки, все осторожно перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12888,'Свеклу хорошо вымыть, отварить, остудить, очистить и потереть на мелкой терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12888,'Соленые огурцы вымыть, нарезать небольшими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12888,'Вымыть, обсушить и нарезать кусочками чернослив.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12888,'Очистить и натереть чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12888,'Все составляющие перемешать, салат посолить, полить сметаной и перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12889,'Пекинскую капусту вымыть, мелко нашинковать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12889,'Очистить и нарезать полукружьями огурец и морковь, зеленое яблоко – треугольниками, репчатый лук – кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12889,'Все ингредиенты перемешать, посолить и поперчить по вкусу, заправить оливковым маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12890,'Отварить яйца и свеклу до готовности, остудить, очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12890,'Свеклу натереть на крупной терке, яйца и сыр – на мелкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12890,'Очистить грецкие орехи, порубить ножом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12890,'Измельчить чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12890,'Продукты перемешать, добавить соль и молотый перец, майонез.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12890,'При подаче на стол салат украсить листочками петрушки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12891,'Рыбу разморозить под водой (проточной), промыть, отрезать голову и очистить тушки от внутренностей. Затем обе скумбрии еще раз тщательно промыть и обсушить бумажными салфетками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12898,'Блюдо поставить на пару часов в холодильник для пропитывания.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12899,'Свежие помидоры вымыть, обсушить, нарезать кубиками вместе с твердым сыром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12899,'Слить жидкость от кукурузы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12899,'Чеснок пропустить через пресс.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12891,'Для рассола: залить заварку кипятком и дать чаю полностью остыть, после чего добавить в него соль и сахар и хорошенько все размешать. Положить в получившийся рассол подготовленную рыбу и убрать миску в холодильник, где держать домашнюю соленую скумбрию в чайном рассоле 4 дня.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12891,'По прошествии отведенного времени достать рыбу из рассола, подвесить ее над умывальником и держать так всю ночь. Готовую соленую скумбрию положить в бумажный пакет и убрать в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12892,'Слить жидкость из банок с кукурузой, с грибами, белой фасоли, корейской моркови.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12892,'Ингредиенты соединить, посолить, заправить майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12892,'Блюдо украсить половинками помидоров черри, зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12892,'На помидоры нанести точки из майонеза, имитируя мухоморы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12893,'Хлеб порезать кубиками, посолить, поперчить, сбрызнуть растительным маслом, насыпать на противень, сушить в духовом шкафу в течение двадцати минут, температура – 140 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12893,'Вымыть малосольные огурцы, удалить кончики, мякоть нарезать прямоугольниками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12893,'Отцедить кукурузу из банки, добавить в огурцы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12893,'Пекинскую капусту вымыть, нарезать тонкой соломкой, перемешать с остальными ингредиентами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12893,'Пропустить через пресс чеснок, добавить в основную массу вместе с сухариками, молотым перцем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12893,'Заправить майонезом, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12894,'Морковь и картофель вымыть, отварить до полной готовности, очистить, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12894,'Маринованные грибы вымыть и также нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12894,'Вымыть и обсушить бруснику и клюкву.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12894,'Нашинковать укроп, петрушку, отцедить консервированный зеленый горошек.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12894,'Продукты перемешать, посолить, заправить майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12895,'Свеклу, морковь, корневище сельдерея вымыть, натереть на крупной терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12895,'На широкое блюдо выложить первый слой из картофеля «фри».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12895,'Сверху – овощи, поочередно, поверх свеклы – кукуруза из банки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12895,'Последний слой – зеленый консервированный горошек.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12895,'Вымыть помидоры, порезать дольками небольшого размера, болгарский перец освободить от семян, нарезать соломкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12895,'Овощи насыпать поверх салата вместе с зеленым луком и петрушкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12895,'Блюдо украсить сеткой из майонеза и кетчупа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12896,'Морковь очистить, вымыть, натереть на крупной терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12896,'Нашинковать репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12896,'Шампиньоны нарезать пластинками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12896,'Грецкие орехи очистить и порубить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12896,'Налить в сковороду растительное масло, прогреть, обжарить грибы и часть лука в течение пяти-семи минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12896,'На другой сковороде жарить морковь с остатками лука в течение трех минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12896,'Залить чернослив кипятком на 15 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12896,'Продукт вынуть, обсушить, нарезать кубиками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12896,'Морковную обжарку переложить в миску, добавить чернослив и рубленые орехи, перемешать, посолить и поперчить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12896,'Отцедить от лишнего масло грибную обжарку, также посолить и поперчить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12896,'Выложить в пиалы грибную смесь, затем – майонез, морковь, сверху – майонез.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12896,'Посыпать блюдо грецкими орехами и черносливом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12897,'Банан очистить и нарезать кружочками. Морковь очистить, промыть и нарезать ломтиками. Сложить подготовленные ингредиенты в чашу блендера, залить их соком и йогуртом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12897,'Взбивать содержимое чаши, пока не получиться густой напиток. Разлить получившийся смузи из моркови и банана по стаканам и сразу же подать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12898,'Морковь и картофель отварить в подсоленной воде до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12898,'Отварить яйца, отделить белки от желтков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12898,'Все продукты по отдельности натереть на крупной терке, куриный желток – на мелкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12898,'На широкое неглубокое блюдо выложить свеклу, картофель, морковь, нарезанный соленый огурец, тертый белок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12898,'Посыпать желтком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12898,'Каждый слой промазать майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12899,'Все ингредиенты соединить, посолить, поперчить, заправить сметаной, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12899,'Перед подачей блюдо посыпать сухариками, купленными в магазине или приготовленными самостоятельно.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12899,'Их можно подсушить в духовом шкафу или обжарить на сковороде с небольшим количеством растительного масла.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12900,'Отцедить квашеную капусту, консервированный горошек и фасоль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12900,'Репчатый лук очистить от кожуры и вымыть, нашинковать, спассеровать на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12900,'Нарезать кубиками соленый огурец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12900,'Вымыть и отварить морковь, картофель, свеклу, воду подсолить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12900,'Овощи нарезать мелкими кубиками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12900,'В небольшой миске перемешать свеклу с луковой обжаркой и маслом со сковороды.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12900,'Добавить остальные ингредиенты, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12900,'Выложить массу на блюдо башенкой при помощи стакана или разъемной формы, украсить зеленью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12901,'Овощи хорошо промыть и обсушить бумажным полотенцем. Помидор разрезать на четыре части, огурец порезать кружочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12901,'Сложить овощи в чашу блендера, добавить йогурт и взбивать до получения смузи. Разлить смузи из томатов и огурцов по стаканам и тут же подать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12902,'Измельчаем крекер любым способом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12902,'Смешиваем измельченный крекер с дроблеными грецкими орехами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12902,'В охлажденные белки добавляем щепотку соли и взбиваем до устойчивых белых пиков. В процессе добавляем сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12902,'В белки с сахаром добавляем крекер и орехи. На этом этапе, по желанию, можно добавить ванилин.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12902,'Форму смазываем маслом и посыпаем панировочными сухарями, выкладываем приготовленную массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12902,'Отправляем в разогретую духовку на температуру 180 градусов примерно на 40 - 45 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12902,'Когда торт остынет извлекаем из формы и украшаем по своему усмотрению. Я для украшения использовала молочный шоколад и кокосовую стружку. Приятного аппетита!',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12903,'Свежий огурец вымыть, нарезать небольшими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12903,'Из авокадо удалить косточку, мякоть нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12903,'Яйца отварить, очистить, также нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12903,'Пропустить чеснок через пресс.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12903,'Продукты перемешать, посолить по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12903,'Заправить оливковым маслом, сбрызнуть лимонным соком, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12904,'Сладкий болгарский перец очистить от семенных камер, нарезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12904,'Свежий огурец вымыть, удалить кончики, нарезать соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12904,'Свежие помидоры вымыть и нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12904,'Нашинковать любую зелень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12904,'Брынзу протереть через сито, смешать с зеленью и сформовать небольшие шарики.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12904,'Для заправки соединить лимонный сок с растительным маслом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12904,'Полить маслом овощную смесь, поперчить и посолить по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12904,'Поверх выложить шарики из зелени и брынзы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12905,'Отварить курицу, филе разобрать на волокна.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12905,'Перемешать крахмал, сырое куриное яйцо, растительное масло и молоко.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12905,'Продукты взбить при помощи венчика, выпечь блины.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12905,'Нарезать пластинками шампиньоны или небольшими кубиками, обжарить на растительном масле.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12905,'Нарезать помидоры пластинками, поперек.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12905,'Натереть на крупной терке морковь, обжарить вместе с луком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12905,'Перемешать майонез с рубленой зеленью и чесноком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12905,'На тарелку положить первый блин, намазать кремом из майонеза с зеленью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12905,'Сверху – второй блин, на него – томаты, блин с куриным мясом и грибами, блин с луком и морковью.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12905,'Далее еще один блин с кремом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12905,'Чередовать слои до тех пор, пока не закончатся блины и начинка.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12905,'Украсить блюдо тертым сыром и зеленью.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12906,'В кастрюлю сложить крупно нарезанные (можно и не резать) куски лука, моркови и картофеля, курицу. Залить 2 литрами воды. Поставить на огонь, довести до кипения и варить 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12906,'Вынуть курицу и отправить к овощам крабовые палочки, базилик, кукурузу, сыр - варим 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12906,'У курицы удалить шкурку и отделить от костей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12906,'Содержимое кастрюлю оправляем в блендер вместе с курицей и петрушкой, затем разбавляем бульоном в котором это все варилось. Посыпаем приправой, вливаем сливки и варим 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12907,'В тарелку сложить творог, сахар, вбить яйцо. Все тщательно перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12907,'Добавить соду гашеную уксусом и муку - перемешать. Сырники будут липнуть к рукам, муки больше не добавляйте, смочите руки водой и слепите сырники.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12907,'На растительном масле обжариваем сырники с каждой стороны по 7 минут на медленном огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12908,'У хлеба отрезать корочки. Обжарить на сковороде гриль (но не обязательно) на оливковом масле до золотистого цвета с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12908,'Креветки залить кипятком на 2 минуты, затем очистить. Выложить на сковороду и жарить с двух сторон по 2 минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12908,'Переложить креветки в тарелку добавить к ним майонез и горчицу и нарезанный укроп - перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12908,'Выложить на тосты начинку из креветок, а сверху выложить по чайной ложке икры минтая.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12909,'Шпинат промыть и обсушить, персики и манго разморозить и порезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12909,'С банана снять кожуру и нарезать плод кружочками. Сложить фрукты в чашу, добавить шпинат, влить воду и взбить все так, чтобы получился смузи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12909,'Разлить по стаканам получившийся смузи из фруктов со шпинатом и сразу подать или выпить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12910,'В чашу блендера поместить куриную печень, лук репчатый, соль (1/2 ч.л.), перец (1/3 ч.л.) - измельчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12910,'Перелить содержимое блендера в тарелку. Вбить яйцо и муку - перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12910,'Смазать сковороду растительным маслом 1 раз! Выпекаем из печени блинчики на медленном огне с двух сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12910,'Огурец натереть на терке, добавить творог, мелко нарезанный укроп, сушеный чеснок, морскую капусту и все тщательно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12910,'На каждый блинчик выложить творожную начинку с краю и свернуть блинчик в рулет.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12911,'Лук и морковь тонко нарезать и обжарить на растительном масле на среднем огне перемешивая в течении 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12911,'Яйца отварить вкрутую, остудить и очистить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12911,'В чашу блендера сложить яйца, печень трески (1 банка) и лук с морковью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12912,'Перемешать яйцо с газированной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12912,'Добавить соль, сахар и растительное масле - перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12912,'Всыпать 2 стакана муки - перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12912,'Всыпать еще 1 стакан муки и замесить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12913,'На водяной бане растопить шоколад и сливочное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12913,'Отдельно взбить яйца (2 шт.) с сахаром (50 гр). Добавить ванилин еще раз взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12913,'Отдельно соединить творог, яйцо (1 шт.) и сахар (70 гр). Взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12913,'В смесь яиц и сахара, добавить разрыхлитель, растопленный шоколад и муку, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12913,'Форму застелить пергаментом, смазать сливочным маслом и выложить половину шоколадной смеси, на нее выложить половину творожной смеси и вишни без косточек (свежую или замороженную).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12913,'Вишню залить второй половиной творожной смеси, а сверху шоколадной.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12913,'Ставим в разогретую духовку до 180 градусов на 40 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12914,'Баклажаны нарезать квадратиками, посолить и оставить на 30 минут. Затем обжарить их на растительном масле 20 минут, перемешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12914,'Лук разрезать на 4 части и нарезать полукольцами. На отдельной сковороде обжарить на растительном масле 10 минут, перемешивая с перцем чили (Чили не нарезать!).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12914,'Помидоры нарезать квадратиками и добавить к луку, добавить сахар и соль. Обжарить 10 минут на среднем огне, перемешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12914,'Половину базилика мелко порубить, чеснок мелко нарезать и добавить их к помидорам с луком. Вынимаем перец чили и обжариваем 5 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12914,'Эту смесь добавляем к баклажанам нарезать оставшийся базилик, добавить отваренные спагетти.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12966,'Сырое яйцо подержать в кипятке две или три минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12915,'Курицу залить водой, отварить до готовности. Вынуть курицу, остудить. Бульон не выливать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12915,'В новую кастрюлю залить 1 литр воды, посолить и довести до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12915,'Засыпать в кипящую воду вермишель. Варить 3 минуты',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12915,'Курицу отделить от костей и нарезать небольшими кусочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12915,'В кастрюлю вылить бульон, добавить нарезанную курицу, сливки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12915,'Кукурузный крахмал смешать с молоком, влить в кастрюлю с бульоном и курицей. Довести до кипения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12915,'Вермишель откинуть на дуршлаг, чтобы стекла лишняя вода. Добавить вермишель к супу. Так же добавить соль, кукурузу все перемешать. Варим 2 минуты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12916,'Берем 2 яйца и отделяем желтки от белков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12916,'В тарелке соединить желтки и размягченное сливочное масло. Тщательно перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12916,'Вбить 1 яйцо - перемешать. Добавить муку - перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12916,'На водяной бане растопить шоколад и влить в тесто, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12916,'Разлить тесто по формочкам и выпекать в разогретой духовке до 180 градусов 10 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12917,'Яйца (4 шт.) отварить, остудить и очистить. Нарезать на кубики. Зеленый лук мелко нарезать и перемешать с яйцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12917,'Готовим тесто. Масло растопить. Добавить сахар, соль, кефир - перемешать. Вбить 2 яйца - перемешать. Всыпать муку и разрыхлитель - перемешать, чтобы не было комочков.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12917,'В форму для запекания выложить бумагу. Залить половиной теста, выложить начинку и залить второй половиной теста. Выпекать 40 минут при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12918,'Тыкву очистить от семян и кожуры. Мякоть нарезать крупными кубиками. Чеснок раздавить ножом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12918,'В глубокой сковороде разогреть оливковое масло и добавить в него чеснок. Жарим чеснок до золотистого цвета, затем выкидываем его.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12918,'В это масло выкладываем тыкву, жарим 8 минут на среднем огне - перемешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12918,'Помидоры черри разрезать пополам, добавить к тыкве, также добавить очищенные креветки. Обжариваем 3 минуты на среднем огне - перемешивая.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12918,'Мелко нарезать петрушку и добавить в сковороду и выложить отваренные спагетти и 1/2 черпака воды в которой варились спагетти. Все тщательно перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12919,'В миску высыпать муку, добавить к ней кусочки сливочного масла комнатной температуры - перемешать. Добавить воды и снова перемешать. Завернуть тесто пленку и убрать в холодильник на 1 час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12919,'Копченый сыр разделить на 2 части, одну часть нарезать соломкой, вторую мелко натереть. Ту что нарезана соломкой смешать с окороком и вбить 2 яйца. Добавить сметану и молоко - перемешать. Укроп мелко нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12919,'Тесто обильно посыпать мукой и раскатать. Выложить в форму для запекания формируя бортики. Тесто наколоть вилкой, залить начинкой, посыпать укропом и сверху тертым сыром. Ставим в духовку на 50 минут при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12920,'Промытую печенку освободить от имеющихся пленок и некрупно порезать. Лук очистить и вместе с печенкой измельчить блендером в однородную массу или пропустить все через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12920,'В печеночную массу добавить соль и перец, сметану, яйца и муку и хорошенько все перемешать – должно получиться похожее на густую сметану тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12920,'На сковородке разогреть немного растительного масла и выложить ложкой приготовленное тесто в виде оладий. Печь домашние печеночные оладушки на небольшом огне, пока с каждой стороны не появится золотистая корочка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12921,'Отварить мясо в подсоленной воде до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12921,'Перемешать молоко с крахмалом и яйцом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12921,'Взбить венчиком, испечь блины.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12921,'Говядину и блины нарезать тонкими брусками или соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12921,'Свежий огурец также порезать на брусочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12921,'Продукты перемешать, заправить по вкусу майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12922,'Взбить яйцо с сахаром, добавить творог с мукой и тщательно перемешать ингредиенты до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12922,'Из получившегося теста сформовать небольшие лепешки и обжарить их на сковородке со всех сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12966,'Натереть твердый сыр «Российский» или «Пармезан».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12922,'Подать готовые классические творожные сырники горячими или холодными, дополнив их вареньем или йогуртом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12923,'Редис вымыть, нарезать полукольцами, помидоры – кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12923,'Отварить куриную грудку, порвать на волокна.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12923,'Для блинного теста перемешать яйца, молоко и крахмал.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12923,'Взбить, испечь тонкие блинчики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12923,'Салатные листья порвать руками, ингредиенты перемешать, заправить растительным маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12924,'Для блинов перемешать молоко, яйца, крахмал.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12924,'Взбить миксером на небольшой скорости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12924,'Можно добавить растительное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12924,'Отварить куриную грудку, разобрать на волокна.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12924,'Нарезать блины полосками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12924,'Порубить репчатый лук.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12924,'Слить сок с кукурузы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12924,'Перемешать ингредиенты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12924,'Готовый салат заправить майонезом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12925,'Замесить тесто, испечь блины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12925,'Готовые изделия скрутить рулетами и нарезать тонкими полосками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12925,'Нарезать мелкими кусочками корнишоны.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12925,'Слить жидкость из банки, тунца размять вилкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12925,'Натереть плавленый сыр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12925,'Очистить и порубить ножом грецкие орехи. Для измельчения можно использовать миксер.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12925,'Перемешать майонез с давленым чесноком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12925,'Ингредиенты перемешать, заправить майонезом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12925,'Украсить блюдо маслинами, тертым сыром, веточками укропа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12926,'Для теста: яйца взбивать с сахаром, пока первоначальный объем не увеличится в три раза. В небольшой мисочке муку смешать с разрыхлителем и какао-порошком, добавить молотый фундук. Постепенно в три подхода ввести в яичную массу мучную смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12926,'Круглую форму (силиконовую или разъемную) смазать сливочным маслом и распределить по ней приготовленное тесто. Убрать форму в разогретую до 175 градусов духовку и выпекать бисквит в районе 40-45 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12926,'Для крема: любым удобным способом растопить шоколад и остудить его до комнатной температуры. Масло сливочное (комнатной температуры) взбить с ореховой пастой, добавить к смеси растопленный шоколад и взбить все в однородный крем. Готовый бисквит слегка остудить и аккуратно разрезать вдоль на 2-3 коржа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12926,'Смазать каждый корж шоколадным кремом и присыпать предварительно накрошенными вафлями, уложить коржи друг на друга. Обмазать весь торт «Ferrero Rocher» оставшимся кремом и посыпать вафельной крошкой и молотым фундуком (если есть).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12926,'Разрезать каждую конфету пополам и выложить кругом по верху торта. Убрать готовый торт в холодильник и дать ему хорошо охладиться. Незадолго до подачи достать безумно вкусный торт «Ferrero Rocher» из холодильника, чтобы крем стал немного мягче.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12927,'Рыбное филе нарезать кусочками небольшого размера, посолить, посыпать сахаром, полить уксусом, перемешать и поставить в холод на два часа для пропитывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12927,'Нашинковать репчатый лук, чеснок, морковь, перемешать отдельно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12927,'Заправить уксусом, кориандром, молотым черным и красным перцем, сахаром, посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12927,'Накрыть тканью и поставить в холодильник на полтора часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12927,'Продукты соединить, перемешать, лишнюю жидкость слить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12927,'Нагреть растительное масло до кипения, залить салат, посуду закрыть и поставить в холод на ночь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12928,'Кальмары отварить в течение нескольких минут, очистить, охладить, нарезать тонкой соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12928,'Обжарить семя кунжута на сухой сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12928,'Влить растительное масло, уксус, соевый соус, добавить давленый чеснок, молотый кориандр, красный и черный перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12928,'Готовым маринадом залить морепродукт, оставить в холоде на два часа или на ночь для пропитывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12928,'При подаче украсить полукольцами репчатого лука и любой зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12929,'Щучье филе нарезать, посолить, залить маринадом из разбавленного уксуса, положить груз.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12942,'На широкую и плоскую тарелку выложить листья зеленого салата, на них – перемешанные ингредиенты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12929,'Разбавить водой томатную пасту, прогреть на сковороде до кипения, добавить рубленый лук и морковь, все вместе потушить в течение пяти – десяти минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12929,'Заправить рыбу сахарным песком, измельченным чесноком, обжаркой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12929,'Перемешать и подать на стол.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12930,'Говядину нарезать соломкой, посолить по вкусу и полить уксусом, положить небольшой груз и оставить мариноваться, время – от пяти до шести часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12930,'Нашинковать свежие огурцы, помидоры, морковь, репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12930,'Перемешать, добавить мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12930,'Всыпать перец и кориандр, рубленый чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12930,'Растительное масло раскалить на сковороде, посолить и перелить в салат.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12931,'Картофель, морковь и горошек отварить до готовности, очистить и нарезать кубиками (за исключением горошка). Ветчину мелко нарезать, яблоки очистить, мелко порезать и сбрызнуть соком лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12931,'Сложить все подготовленные ингредиенты в миску и хорошо все перемешать. Яйца отварить, охладить, очистить и отложить для дальнейшего использования.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12931,'Для соуса: майонез перемешать со сметаной и горчицей, посолить и поперчить смесь по вкусу. Желатин замочить в овощном бульоне и дать ему полностью раствориться. Влить бульон в соус и хорошо перемешать, дать смеси остыть и залить им подготовленный салат.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12931,'Форму (лучше прямоугольную) застелить пленкой так, чтобы края свисали. На дно формы выложить ровным слоем половину салата, распределить сверху подготовленные целые яйца и закрыть их оставшимся салатом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12931,'Накрыть яркий овощной салат-желе свисающей пленкой и убрать форму в холодильник на 8 часов до полного застывания. Застывшее желе аккуратно переложить на сервировочное блюдо и украсить по собственному желанию.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12932,'Вырезку очистить от жира и пленок, нарезать тонкой соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12932,'Чтобы это было легче сделать – мясо лучше заранее подморозить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12932,'Добавить уксус, соль, хорошо перемешать, подержать в холодильнике четыре или шесть часов, периодически помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12932,'Репчатый лук нарезать и обжарить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12932,'Отцедить от мяса лишнюю жидкость.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12932,'Добавить кунжут, соевый соус, нарезанный чеснок, черный и красный перец, нашинкованную кинзу и молотый кориандр, пассерованный лук, готовую морковь по-корейски.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12932,'Ингредиенты перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12933,'Куриное филе нарезать кусочками небольшого размера, репчатый лук нашинковать полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12933,'Продукты перемешать с морковью по-корейски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12933,'Разогреть растительное масло на сковороде, переложить продукты, тушить пять минут, огонь – средний, помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12933,'Добавить корейскую приправу для моркови, столовый уксус, тушить все вместе еще пять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12934,'Свежий огурец и болгарские перцы красного и зеленого цвета нашинковать максимально тонкой соломкой, репчатый лук – полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12934,'Обжарить на сковороде острую корейскую приправу для моркови, лук, куриную грудку, также нарезанную соломкой, в конце добавить рубленый чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12934,'Огонь убавить, влить томатную пасту, уксус, соевый соус, посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12934,'Продукты потушить в течение семи или восьми минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12934,'Переложить в салатницу, добавить огурцы и перцы, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12935,'Мороженых осьминогов отварить в течение десяти или пятнадцати минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12935,'Всыпать кальмаров, через две минуты кастрюлю снять с огня.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12935,'Через десять минут воду слить, морепродукты промыть и нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12935,'Измельчить морковь, посолить и посыпать сахарным песком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12935,'Дать постоять, чтобы она дала сок, лишнюю жидкость слить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12935,'Готовые морепродукты переложить в салатницу, добавить сахар и соль, кунжутное масло и перец, подлить соевый соус, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12935,'Сверху выложить измельченный лук, морковь, посыпать черным и красным перцем, молотым кориандром и семенами кунжута, рубленым чесноком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12942,'Украсить половинками помидоров черри, каперсами, маслинами.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12935,'Салат полить раскаленным растительным маслом, хорошо перемешать и поставить в холод на четыре часа или на ночь.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12936,'Вешенки нарезать, варить пять-семь минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12936,'Перемешать репчатый лук, нарезанный полукольцами, с измельченным чесноком, морковью, сахаром, томатной пастой и соевым соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12936,'Отваренные грибы промыть в дуршлаге, отцедить жидкость, переложить в салатницу, полить столовым уксусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12936,'Раскалить растительное масло, полить салат.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12936,'Накрыть посуду крышкой, оставить смесь для пропитывания на пять или шесть часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12937,'Яйца отварить, остудить, почистить, нарезать кружочками и отложить столько кружков, сколько гренок. Оставшиеся яйца измельчить и перемешать с майонезом. Ветчину и сыр нарезать тонкими пластинками, огурец – кружочками, перец – кольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12937,'Смазать каждую гренку майонезно-яичной смесью и собрать бутерброды следующим образом: ломтик ветчины, ломтик сыра, пару кружков огурца и кольцо перца. Каждый вкусный сочный бутерброд с ветчиной украсить свежей зеленью и подать к столу или убрать в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12938,'Говяжью вырезку отварить и нарезать тонкими брусками по полсантиметра толщиной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12938,'Добавить молотый перец, измельченный репчатый лук и чеснок, сахарный песок, подсоленное кунжутное семя, ингредиенты перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12938,'Очистить и нарезать дольками груши, окунуть в соленую воду и аккуратно разложить по периметру плоской тарелки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12938,'В центр поместить салат, полить смесью кунжутного или оливкового масла с соевым соусом, посыпать очищенными кедровыми орехами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12939,'Баклажаны выложить в подсоленный кипяток, время варки – десять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12939,'Остудить, нарезать брусками и переложить в салатницу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12939,'Посолить, полить уксусом, положить часть нашинкованного репчатого лука, сладкий болгарский перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12939,'Уплотнить и оставить для пропитывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12939,'Нарезать оставшийся лук, порубить чеснок, добавить чили.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12939,'Лук обжарить на масле, добавить сахар.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12939,'При готовности обжарку снять с плиты, посыпать семенами кинзы, добавить чили и чеснок, хорошо перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12939,'Смесь перелить в баклажаны, добавить соевый соус.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12939,'Закуску поставить в холодильник на три часа или на сутки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12940,'Баклажаны нарезать полосками, посолить, оставить на полчаса, чтобы отошла горечь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12940,'Промыть холодной водой, хорошо отжать, обсушить на бумажном полотенце.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12940,'Жарить на кунжутном масле до появления золотистой корочки, для этого потребуется от семи до восьми минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12940,'Переложить в миску.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12940,'Нарезать соломкой сладкий и острый перец, морковь, полукольцами красный лук, измельчить чеснок, кинзу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12940,'Добавить сахар, соль, укус.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12940,'Ингредиенты перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12940,'Посыпать смесь обжаренным кунжутом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12940,'Поставить в холодильник для пропитывания на два часа или на ночь.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12941,'Все ингредиенты (кроме маслин и горошка) нарезать кубиками, сложить в глубокий салатник и перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12941,'Добавить в салат соль и перец по вкусу, сбрызнуть все небольшим количеством лимонного сока и заправить майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12941,'Украсить мясной салат с маринованным огурцом маслинами и горошком и убрать блюдо на 1 час в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12942,'Картофель отварить и нарезать кубиками. Лучше использовать молодую картошку, для ее приготовления понадобится не больше десяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12942,'Стручковую фасоль нарезать кусочками по три или четыре сантиметра, переложить в кипяток на три минуты, охладить, смешать с картофелем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12942,'Филе тунца прожарить на сковороде на горячем масле, через несколько минут должна появиться румяная корочка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12942,'Добавить продукт к картофелю и фасоли.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12942,'Отварить, очистить и нарезать кубиками куриные яйца.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12942,'Приготовить соус из дижонской горчицы, оливкового масла, уксуса, рубленого чеснока, соли.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12942,'Полить готовый салат горчичным соусом, выложить половинки яиц, анчоусы.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12943,'Крупно нарезать отварную грудку и зеленую фасоль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12943,'Добавить огурец, помидоры, шампиньоны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12943,'Полить соусом и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12944,'Промыть крупу, всыпать в мультиварку, залить водой 1:2, крышку закрыть, установить режим «Молочная каша», через 20 минут долить молока (чуть больше первоначального объема), подсолить, добавить сливочное масло с сахаром, размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12944,'Подержать кукурузную ',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12945,'Яйца отварить, охладить, почистить, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12945,'Фасоль вымыть, нарезать кусочками, отварить в течение пяти минут в подсоленной воде и охладить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12945,'Продукт можно дополнительно обжарить на сливочном масле, вкус будет ярче.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12945,'Яйца и фасоль перемешать, добавить давленый чеснок и майонез по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12946,'Нарезать маринованные огурцы, измельчить морковь, добавить отваренную фасоль, яйца, давленый чеснок, соль и перец молотый – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12946,'Заправить салат майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12947,'Отварить фасоль, макароны, яйца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12947,'Фасоль и яйца нарезать, ингредиенты перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12947,'Добавить помидоры черри, нарезанные половинками, оливки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12947,'Разложить в тарелки порционно, украсить тертым яйцом, кусочками консервированного тунца.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12948,'Для начала приготовим соус. Укроп мелко нарезаем, и перекладываем в глубокую тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12948,'Туда же, добавляем ряженку, сметану, выдавливаем чеснок через чеснокодавилку, соль перец по вкусу. и все это перемешиваем. Убираем с торону, что бы соус настоялся.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12948,'Отрезаем верхний край хлеба, и избавляемся от мякиша хлеба. Убираем с торону.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12948,'Помидор нарезаем тонкими ломтиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12948,'Малосоленый огурец нарезаем кольцами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12948,'Пекинскую капусту нарезаем тонкой соломкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12948,'Сыр натираем на большой терке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12948,'Куриную грудку, нарезаем небольшим кубиком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12948,'Обжариваем куриную грудку до готовности, и во время жарки грудки солим и перчим по вкусу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12948,'Как только грудка приготовилась перекладываем на тарелку.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12948,'Во внутрь батона укладываем подготовленные ингредиенты, такие как, капуста пекинская, малосоленый огурец, чуть-чуть сыра, грудку, поливаем немного соусом, и сверху укладываем помидор и посыпаем сыром. Отправляем в духовку при 120°С на 5-7 минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12949,'Отварить курицу и фасоль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12949,'Нарезать сладкий болгарский перец, его можно немного обжарить для размягчения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12949,'Продукты перемешать, залить смесью бальзамического уксуса, соевого соуса, оливкового масла, соль и перец добавить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12949,'Перемешать, посыпать очищенными подсолнечными семечками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12950,'Развести в теплом молоке с 1 ст.л. сахара дрожжи, оставить на треть часа в теплом месте. Отделить белки от желтков у 3 яиц, взбить белки с подошедшими дрожжами, сахаром и стаканом муки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12950,'Полученную опару оставить на время в тепле, чтобы подошла. Через несколько часов сливочное масло растереть с желтками и добавить к поднявшейся опаре, всыпать муку, подсолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12950,'Замесить тесто, постепенно добавляя муку (пока масса не перестанет липнуть к стенкам посуды), оставить примерно на 3 часа для подъема. Промыть тщательно изюм и замочить в воде, но для дополнительной мягкости и аромата можно и в коньяке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12950,'Когда тесто увеличиться в объеме почти в три раза, всыпать изюм, добавить ванилин, смазать верх маслом и тщательно вымесить в течение четверти часа. Прогреть мультиварку 10 минут на режиме «Подогрев», положить тесто (1/3 чаши), нагрев не отключать еще 10 минут, отключить подогрев, оставить тесто на час под закрытой крышкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12950,'Изменить режим на «Выпечку», выдержать тесто час, добавить 25 минут. Достать готовый кулич, обернуть его полотенцем и дать остыть. Взбить глазурь из сахара (пудры) и белка 1 яйца на быстрых оборотах миксера, смазать глазурью, украсить цветной присыпкой. Накрыть сдобный кулич в мультиварке  тканью после полного высыхания глазури',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12951,'Обжарить на сковороде тыквенные семечки, на это потребуется от пяти до шести минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12951,'Остудить, перемолоть продукт в блендере, оставить несколько штук для украшения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12951,'Добавить соль, свежую кинзу, давленый чеснок, лимонный сок, кумин молотый, превратить смесь в пюреобразную массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12951,'Отварить стручковую фасоль в подсоленной воде в течение пяти минут, охладить, чтобы продукт остался хрустящим.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12951,'Выложить на блюдо, полить соусом, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12951,'Украсить основную смесь полосками томатов, оставшимися семечками, рубленой кинзой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12951,'Сверху вылить соус «Песто».',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12952,'Измельчить блендером филе курицы (грудку), добавить взбитые на миксере яйца, муку (манку), влить сливки, посолить, перемешать и еще раз взбить для однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12952,'Разложить по формочкам, налить в мультиварку пару стаканов воды, установить контейнер для варки на пару, поставить в него формочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12952,'Задать режим «Варка на пару» и время 20 минут. Через треть часа нежное диетическое куриное суфле в мультиварке будет готово, блюдо в таком исполнении хорошо подходит для детского питания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12953,'Прогреть на сковороде оливковое масло, обжарить на нем давленый чеснок, потом выбросить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12953,'Выложить кубики белого хлеба, подсушить и выложить на салфетку, чтобы удалить лишний жир.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12953,'Перепелиные яйца отварить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12953,'Готовые креветки очистить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12953,'Яйца и помидоры черри разрезать пополам или на четвертинки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12953,'Листья салата ромэн порвать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12953,'Выложить на блюдо зелень, затем сухари, посыпать тертым сыром «Пармезан».',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12953,'Оставшиеся сухари и морепродукты выложить горкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12953,'Украсить блюдо помидорами и яйцами, посыпать оставшимся сыром.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12954,'Нарезать грудку курицы на полоски, посыпать половиной тимьяна, дать чуть постоять. Разогреть масло в режиме «Выпечка» минут 5-7, обжарить в течение 10 минут соцветия брокколи, чеснок и грибы, чуть подсолить, вынуть на тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12954,'Обжарить мясо до красивого цвета  треть часа (режим не менять), влить к куриным грудкам в мультиварке воду, ворчестерский (или подобный) соус, херес, всыпать остаток тимьяна.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12954,'Переключить режим мультиварки на «Тушение», задать  время готовки полчаса. Добавить через 10 минут грибы с капустой, гарнир к куриному филе с брокколи и грибами выбрать по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12955,'Креветки отварить со свежей петрушкой, лавровым листом и душистым перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12955,'Оставить кастрюлю на десять минут, затем морепродукты очистить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12955,'Латук порвать кусочками, сверху выложить готовые сухарики из магазина.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12955,'Посыпать тертым сыром «Пармезан» или «Российским».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12956,'Листья салата ромэн порвать, выложить в салатницу с высокими бортиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12956,'Добавить нарезанные помидоры черри.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12956,'Нарезать батон, приправить прованскими травами, подсушить в духовом шкафу при температуре 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12956,'Креветки выложить в кипящую воду на две или три минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12956,'Морепродукты очистить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12956,'Отварить курицу, снять кожицу, филе порезать тонкой соломкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12956,'Можно использовать окорочка.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12956,'Продукты выложить в миску, натереть сыр «Чеддер».',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12956,'Сбрызнуть салат соком лайма.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12957,'Мякиш батона натереть чесноком, порезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12957,'Высыпать на противень, подсушить в духовке в течение семи или десяти минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12957,'Листья салата ромэн замочить в воде со льдом, а затем порвать руками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12957,'Сыр пармезан натереть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12957,'Сырые куриные яйца опустить в кипящую воду на две минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12957,'Разбить в миску, добавить чеснок и «Вустерский» соус.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12957,'Заправку перелить в салатные листья, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12957,'Всыпать тертый сыр, еще раз перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12957,'Крупные креветки очистить от головы, панциря, жилок на спине.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12957,'Обжарить до розового цвета.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12957,'Листья салата с соусом выложить в центр блюда, морепродукты – по краям.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12957,'Блюдо посыпать еще одной порцией сыра.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12958,'Рыбу очистить, филе нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12958,'Креветки разморозить, отварить в подсоленной воде со специями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12958,'Листья салата «Латук» замочить в воде, обсушить полотенцем и порвать руками на части.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12958,'Помидоры черри нарезать дольками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12958,'Посыпать салат тертым сыром «Пармезан», полить любым сливочным соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12959,'Для начала приготовить соус. В масло оливковое добавить горчицу и уксус винный. Лук измельчить при помощи ножа, чеснок выдавить через пресс. Добавить лук и чеснок в смесь масла, уксуса и горчицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12959,'Все составляющие хорошо перемешать и добавить черный перец молотый. Соус убрать на некоторое время в холодильник. Подготовить овощи. Помидоры и огурцы помыть и нарезать некрупными кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12959,'Хлеб подсушить в духовке или при помощи тостера. Нарезать некрупными кубиками. Брынзу мелко покрошить. Все ингредиенты перемешать, добавить маслины и зелень (предварительно мелко ее нарезав).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12959,'Достать из холодильника соус и в него выложить салат. Осторожно перемешать. По желанию, в легкий овощной салат «Панзанелла» можно добавить соль и сок лимона. Перед тем, как подать к столу, его нужно подержать на холоде несколько минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12960,'Перемешать растительное масло с солью, перцем, майонезом, чесноком и соком лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12960,'Креветки замариновать в полученной смеси на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12960,'Сладкий болгарский перец очистить от плодоножки и семян, мякоть нарезать кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12960,'Помидоры черри нарезать дольками, листья пекинской капусты порвать руками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12960,'Пропитавшиеся специями морепродукты обжарить на сковороде без масла.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12960,'Все продукты перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12960,'Заправить салат оливковым маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12961,'Тигровые или королевские креветки очистить, залить смесью лимонного сока, растительного масла и меда.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12961,'Время маринования – 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12961,'Морепродукты обсушить бумажным полотенцем и обжарить на сковороде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12961,'Отдельно, на другой сковороде, прогреть чесночное масло и обжарить на нем белые гренки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12961,'Хлеб присыпать прованскими травами и посушить в духовом шкафу десять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12961,'Салат ромэн порвать руками на кусочки, высыпать в тарелку, натертую зубчиком чеснока.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12961,'Сверху – жареные сухарики, сбоку – креветки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12962,'Яйца отварить, помидоры черри порезать дольками, листья салата ромэн порвать руками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12962,'На сухой сковороде обжарить очищенные кедровые орехи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12962,'Отварить креветки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12962,'Все продукты перемешать, добавить сухарики с чесноком, посыпать тертым сыром «Пармезан» или аналогичным.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12963,'Приготовить креветки на сковороде-гриль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12963,'Тушки кальмаров разрезать кольцами и опустить в кипящую воду на две или три минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12963,'Салат порвать руками, перемешать с белыми гренками и морепродуктами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12963,'Посыпать сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12963,'Салат украсить кружками заранее отваренных яиц.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12964,'Взбиваем мягкое сливочное масло, добавляем яйцо и сахар, продолжаем взбивать до белой пышной массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12964,'Натираем к приготовленной массе цедру апельсина.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12964,'Выжимаем апельсиновый сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12964,'Готовим тесто. Смешиваем муку с разрыхлителем и солью. Добавляем к сливочной смеси сок апельсина и постепенно вводим мучную смесь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12964,'Раскатываем тесто в пласт толщиной 0,5 см и вырезаем формочками печенье произвольной формы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12964,'Печенье выкладываем на лист для выпечки, предварительно застеленный бумагой для выпечки, посыпаем дробленным миндалем и отправляем в разогретую духовку на температуру 240 градусов примерно на 20 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12965,'На большую круглую тарелку выложить порванные руками салатные листья.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12965,'Сверху – свежие тертые огурцы, нарезанные кольцами отваренные яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12966,'Перемешать в ручном комбайне яйцо, дижонскую горчицу, вустерский соус, анчоусы, лимонный сок и чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12966,'Ингредиенты перебить до однородного состояния.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12966,'Добавить оливковое масло, тертый сыр, еще раз перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12967,'Солод размешать в теплой воде, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12967,'Насыпать дрожжи в хлебопечку, затем добавить пшеничную и ржаную муку, соль – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12967,'Влить масло, солодовую смесь, добавить молотый кориандр и натуральный мед.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12967,'Время выпекания – три с половиной часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12968,'Дрожжи и сахарный песок развести в небольшом количестве воды, оставить на десять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12968,'Дрожжи должны полностью раствориться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12968,'Всыпать муку пшеничную и ржаную, солод, влить еще немного воды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12968,'Массу перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12968,'Добавить соль, тмин и кориандр.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12968,'Тесто вымесить и поставить в теплое место на полтора или два часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12968,'Подошедший продукт обмять, сформовать булку и оставить еще на полтора часа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12968,'Время выпекания – полчаса, температура – 180 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12969,'Для приготовления теста для пирога, нужно измельчить масло с мукой, чтобы получилась крошка. Вбить яйцо и замесить тесто. Филе куриное порезать некрупными кусочками. Кусочки обжарить в масле до зарумянивания. К кусочкам курицы положить грибы и влить немного воды. Добавить соль по вкусу и тушить под крышкой, пока грибы не приготовятся.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12969,'Духовку нагреть до 200 градусов. Форму для пирога намазать маслом. Выложить тесто в форму, сформировать небольшие бортики будущего пирога. Основу пирога выпекать приблизительно десять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12969,'Пока тесто печется, взбить оставшиеся яйца с солью и сливками. Вынуть форму из духовки, выложить начинку на тесто. Начинку залить взбитыми яйцами со сливками. Сверху высыпать натертый сыр и измельченную зелень. Пирог выпекать еще в течение получаса. Киш по-французски с курицей и грибами подавать к столу теплым.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12970,'Приготовить закваску из ржаной муки, солода, молотого кориандра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12970,'Продукты залить кипящей водой, емкость укутать в шарф и поставить в тепло на два часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12970,'В теплой воде развести сахар, мед и соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12970,'Перемешать с закваской, пшеничной и ржаной мукой и водой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12970,'Вымесить тесто до густого состояния.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12970,'Миску смазать маслом, выложить тесто, накрыть крышкой и оставить на два или четыре часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12970,'Смазать маслом форму для выпекания, выложить тесто, обмять, накрыть листом фольги и оставить еще на два часа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12970,'Готовый продукт смазать водой и посыпать зернами кориандра.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12970,'Поставить в прогретую до 220 градусов духовку, время выпекания – от пятнадцати до двадцати минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12970,'Далее температуру снизить на двадцать градусов, печь еще час или чуть больше.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12970,'Продукт накрыть полотенцем, оставить для дозревания еще на час.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12971,'В кастрюлю налить полтора литра воды и вскипятить. В кипящую воду добавить чеснок, предварительно выдавленный через пресс и травы: петрушку, тимьян и лавровый лист.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12971,'Травы нужно перевязать, сформировав из них пучок. В воду со специями добавить оливковое масло. Убавить огонь и готовить суп в течение пятнадцати минут, после чего травы вынуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12971,'В прогретую тарелку налить суп и туда же добавить яичный желток. Хорошо перемешать желток с супом. Насыпать в тарелку, мелкорубленую зелень петрушки и положить подсушенный хлеб. Суп французский «Кипяченая вода» можно подавать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12972,'Целую курицу разделать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12972,'Лук нарезать полукольцами, чеснок кольцами и положить между кусочками курицы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12972,'Лимон, удалить "попки", нарезать кольцами. Выложить поверх курицы. Посолить, посыпать сушеным тимьяном, залить вином.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12972,'Ставим в духовку на 1 час при температуре 200 градусов, при этом каждые 20 минут доставать курицу и переворачивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12973,'Шампиньоны нарезать соломкой и обжарить на растительном масле на среднем огне 8 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12973,'К шампиньонам вбить яйца и перемешать. Готовим 3 минуты на среднем огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12973,'Укроп мелко нарезать. Добавить к яично-грибной смеси, также натереть сыр, перемешать и готовить до готовности яиц.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12973,'Тушку кальмара заколоть шпажкой снизу, начинить яично-грибной смесью и заколоть тушку кальмара сверху.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12973,'Противень застелить фольгой, смазать растительным маслом. Выложить кальмар. Кальмара смазать маслом. Ставим в разогретую духовку до 200 градусов на 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12974,'Кусочки курицы залить соевым соусом и винным уксусом. Перемешать и убрать в холодильник на 1 час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12974,'Чили нарезать крупными колечками. Болгарский перец - тонкими полукольцами, имбирь - соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12974,'На оливковом масле обжарить чили в течении 3 минут при сильном огне. Добавить болгарский перец и имбирь и жарить еще 5 минут. Переложить тарелку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12974,'В эту же сковородку выложить кусочки курицы (порционно, чтобы они свободно лежали друг от друга). Обжарить по 2 минуты с каждой стороны, добавить к овощам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12974,'В сковороду выложить арахис, залить кипятком (100 мл) и варим 5 минут. Посыпать кунжутом и переложить курицу и овощи. Готовить все вместе 3 минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12975,'Если нет готовых конусов, то делаем из при помощи бумаги и фольги. Бумагу свернуть в кулек и обматать полностью фольгой (снаружи и внутри).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12975,'Рабочую поверхность посыпать мукой и немного раскатать слоеное тесто. Нарезать тесто на полосы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12975,'Тестом обматываем конус, немного внахлест. Выкладываем на противень, выпекаем 15 минут при температуре 200 градусов. Вынимаем конусы и остужаем трубочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12975,'Белки отделить от желтков. В глубокую миску влить белки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12975,'Сахар залить водой (40 мл), НЕ ПЕРЕМЕШИВАТЬ! Ставим на сильный огонь, доводим до кипения, варим 4 минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12975,'Взбиваем белки 5 минут на максимальных оборотах, затем тонкой струйкой влить сахарный сироп, который варили, не прекращаю взбивать. Взбивать еще 5 минут (или больше).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12975,'В кондитерский мешок переложить начинку. Трубочки заполнить кремом и посыпать сахарной пудрой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12976,'В миску поместить яйцо, растопленное сливочное масло, сахар, молоко - перемешать. Добавить соль и муку и снова перемешать',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12976,'Яблоки нарезать колечками, удалить семена.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12976,'На сковороде разогреть растительное масло. Яблоки макаем в тесто со всех сторон и выкладываем на сковороду. Готовим 7 минут на медленном огне, затем переворачиваем и готовим еще 7 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12977,'Лук нарезать на кубики, бекон соломкой. Кладем в кастрюлю и жарим 10 минут на среднем огне, перемешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12977,'Картофель и помидоры очистить от кожуры и нарезать кубиками. Добавить в кастрюлю и залить куриным бульоном. Довести до кипения, затем варим 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12977,'Капусту нашинковать, добавить в кастрюлю, посолить и поперчить. Довести до кипения и варим 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12978,'Бананы очистить от кожуры, поместить в чашу и измельчить до состояния пюре погружным блендером. Добавить мюсли и семечки, перемешать. Оставить на 20 минут',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12978,'Противень застелить бумагой, выложить печенье ложкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12978,'Выпекаем 15 минут при температуре 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12979,'Лук и картофель нарезать кубиками. Обжарить на растительном масло 15 минут на среднем огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12979,'Курицу нарезать небольшими кусочками, добавить в сковороду к луку с картофелем, обжариваем на среднем огне 10 минут. Посолить, поперчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12979,'Готовим тесто. Сливочное масло соединить с мукой и разрыхлителем перетереть в крошку. Добавить сметану и кефир - перемешать. Тесто завернуть в пленку и отправить в холод на 1 час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12979,'Тесто разделить на 2 части. раскатать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12979,'Форму застелить бумагой, смазать растительным маслом. На дно уложить 1 слой теста, выложить начинку и застелить вторым слоем теста, края склеить между собой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12979,'Смазать наш курник желтком и выпекаем 50 минут при температуре 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12989,'Мелко нарезаем укроп, и перекладываем его в тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12989,'Мелко нарезаем лук зеленый и перекладываем в ту же тарелку. Убираем в сторону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12980,'Филе телятины хорошо промыть холодной проточной водой, обмакнуть салфеткой и нарезать кусочками, как на бефстроганов. Кусочки мяса обмакнуть в муку, положить на сковороду с оливковым маслом и обжарить со всех сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12980,'Влить в мясо вино и тушить еще двадцать минут, после чего положить орех мускатный, соль и перец молотый, а также сливки. Все тщательно перемешать и томить на слабом огне, накрыв крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12980,'Добавить к мясу чеснок и зелень. Через пять минут, снять мясо с огня. Хлеб для тостов обжарить на сковороде в масле сливочном, до зарумянивания корочки. Выложить кусочки хлеба в жаропрочную форму, на них выложить мясо. Поставить форму в духовку для запекания. Через пятнадцать минут крут по-французски с телятиной  можно подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12981,'Миндаль залить кипящей водой и оставить на недолгое время. После этого, удалить с него кожицу и нарезать вдоль полосками. Сыр размять или натереть при помощи терки. Отдельно взбить желтки. Смешать желтки с сыром и мукой. Белки взбить до образования густой устойчивой пены. Аккуратно соединить их с сырной массой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12981,'Противень выстелить пергаментной бумагой. Тесто переместить в кондитерский мешочек или шприц. Выкладывать тесто маленькими порциями на противень, оставляя между печеньями промежуток. Каждое печенье украсить миндалем. Выпекать французское взбитое печенье в горячей духовке, приблизительно 20-25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12982,'Говяжий фарш размять руками. Лук очистить и мелко нарубить ножом. Орехи измельчить, оливки мелко нарезать. Яйцо взбить. Смешать фарш с рубленым луком, орехами, оливками, яйцом и частью томат-пасты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12982,'Добавить горчицу, специи и пряности. Из готового фарша сформировать котлеты небольшого размера. Обвалять котлеты в панировочных сухарях и обжарить в масле. Котлеты должны жариться до зарумянивания, а не до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12982,'Приготовить соус «Охотничий». В том же масле, в котором жарились котлеты, обжарить и грибы с чесноком и небольшим количеством лука-шалот. Добавить к грибам оставшуюся томат-пасту. Через пару минут осторожно влить в сковороду вино, добавить соль и перец. Тушить на слабом огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12982,'Смешать кукурузную муку с малым количеством воды. Добавить измельченную петрушку. Эту смесь выложить в соус и перемешать. Котлеты выложить в сковороду с соусом и прокипятить пару минут. Котлетки из говядины с соусом «Охотничий» готовы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12983,'Масло сливочное предварительно подержать в холодильнике или в морозильной камере. Холодное масло натереть при помощи терки. Соединить масло с мукой, смешанной с разрыхлителем. Добавить творог, сметану, сахар и взбитое яйцо. Замесить мягкое эластичное тесто. Положить его в холодильник на некоторое время.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12983,'Сливы хорошо вымыть и разрезать пополам. Масло сливочное для карамели выложить на сковородку и растопить на слабом огне. Добавить в масло сахар, и помешивая, довести смесь до состояния карамели. Смесь должна стать коричневой с пузырьками. Снять сковороду с огня и положить в эту смесь нарезанные сливы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12983,'Тесто для пирога достать из холодильника и раскатать по форме сковороды, в которой готовилась карамель. Накрыть тестом карамель, края теста опустить вниз, так чтобы начинка была полностью накрыта тестом. Слегка вдавить пальцами тесто в начинку. Французский карамельный пирог со сливами выпекать в горячей духовке, чуть больше получаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12984,'Свиные ребрышки нарезать на кусочки и выложить в сотейник (казан, утятницу). Добавить к ребрышкам специи. Мякоть свинины нарезать некрупными кусочками. Выложить кусочки мяса на ребрышки. Добавить соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12984,'Вырезать из пергаментной бумаги круг, по форме сотейника. Этим пергаментным кругом накрыть сотейник. Сверху положить крышку, так чтобы она плотно прилегала к кастрюле. Тушить ребрышки с мясом и специями в течение четырех часов. Мясо нельзя перемешивать. Также, необходимо следить, чтобы в сотейнике всегда была жидкость в достаточном количестве.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12984,'По истечении четырех часов, ребрышки достать из сотейника. Снять мясо с костей и оставить его в кастрюле. Перемешать содержимое сотейника вилкой. Если в мясе слишком много воды, проварить его еще некоторое время. Мясо должно быть мягким, при касании, оно должно разделяться на волокна.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12984,'Готовый паштет «Рийет» из свинины разложить по стеклянным баночкам, предварительно подвергнутым стерилизации. Баночки плотно закрыть крышками и убрать в холодильник. Через две – три недели паштет будет полностью готов к употреблению.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12985,'Изюм высыпать в миску или другую емкость, залить его коньяком и добавить мускатный орех. Дать смеси настояться в течение получаса. После этого, измельчить смесь при помощи блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12985,'Бульон вскипятить. Влить в бульон изюмно — коньячную смесь и еще немного целого изюма. Прокипятить еще минут десять. Снять соус с огня и накрыть крышкой. Черный хлеб измельчить до крошки. Хлебную крошку обжарить на сковороде без масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12985,'Натертый сыр, хлебную крошку, специи, соль и перец черный вместе с оливковым маслом перемешать при помощи блендера. Зубчики чеснока разрезать вдоль на половинки. Выложить зубчики чеснока в разогретое на сковороде масло оливковое и обжарить на сильном огне. Прожаренный чеснок вынуть из масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12985,'Антрекот промыть и обсушить при помощи салфетки. Мясо посолить и поперчить. Выложить антрекот на сковороду с чесночным маслом и жарить до готовности мяса. Прожаренный антрекот выложить в жаропрочную посуду. Сверху на мясо выложить хлебную крошку и запечь все вместе в духовке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12985,'Запекать приблизительно пять минут в горячей духовке, пока не зарумяниться хлебная корочка. Подавать антрекот под хлебной корочкой с соусом «Коньячный», можно без гарнира, с прожаренным чесноком и черным хлебом, на листиках базилика.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12986,'Взять яйца, хорошо промыть, разбить при помощи ножа и поместить в разные миски белок и желток.  До мелких пиков взбить белки. Желтки растереть с сахарным песком до получения однородной консистенции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12986,'Муку просеять через сито, добавить к белку и тщательно перемешать. Добавить желтки и аккуратно перемешать. Включить разогреваться духовку до температуры 190 градусов. Приготовить противень, застелить пергаментом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12986,'Выложить ровным слоем на пергамент приготовленную массу. Поместить в заранее подогретую духовку и выпекать в течение 12 мин. По истечении указанного времени достать и свернуть в рулет, дать остыть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12986,'Приступить к приготовлению крема. Взять миску, добавить сахарный песок, какао и сливки, взбить в крутую пену. Раскатать рулет, обильно помазать кремом и завернуть рулет обратно. Поместить в холодильник на 15-20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12986,'Приготовить глазурь. Перемешать все ингредиенты до получения однородность, поставить на огонь до совершенного растворения, остудить массу. Помазать рулет полученной глазурью и убрать в холодильник. Белый шоколад растопить на паровой бане и красиво украсить приготовленный рулет. Подавайте шоколадный рулет в глазури «Лакомка» к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12987,'Сахарный песок, творог и яйца перемешать и растереть до однородности. Добавить цедру лимона, крахмал и тщательно смешать. На выходе должна получиться кремообразная масса. Добавить клюкву и помешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12987,'Приготовить штрейзель. Сливочное масло мелко порезать или натереть замороженное на терке, добавить сахарный песок и муку. Руками помешать, до образования мелкой крошки. Всыпать какао и растереть до однородной консистенции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12987,'Взять форму для выпекания и на дно поместить ½ часть приготовленного шоколадного штрейзеля. Сверху положить творожную массу. Разровнять при помощи кондитерской лопатки, чтобы не было пустоты. Накрыть оставшейся ½ частью штрейзеля.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12987,'Поставить в разогретый духовой шкаф и выпекать при температуре 190 градусов в течение 45 минут. Готовый львовский сырник классический должен отстать от стенок и увеличится в объеме. По истечении 45 минут достать и остудить, не вынимая из формы. Оставить на несколько часов настояться, чтобы он стал плотный.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12988,'Нужно порезать курицу, перец и лук дольками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12988,'Помести все в форму для запекания, добавим паприку, специи для тако или фахитос, оливковое масло и все перемешаем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12988,'Разогреем духовку до 200 градусов и отправим форму на 25 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12988,'После готовности, разогреем тортилью и порежем авокадо кубиками. В тортилью добавим курицу, перец, лук, авокадо, кинзу, сок лайма и польём соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12989,'К заранее отварному картофелю добавляем чуть-чуть молока и 1 яйцо. И доводим картофель до картофельного пюре. Далее, к пюре добавляем лук зеленый, укроп (который вы убрали в сторону), соль, перец, паприку по вкусу, все перемешиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12989,'Из полученной массы картофельного пюре с луком и укропом катаем шарик, панируем его в муке, далее опускаем его в куриные взбитые яйца, и далее панируем его в панировочных сухарях, перекладываем на тарелку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12989,'В хорошо разогретое растительное масло опускаем (поочередно) картофельный шарики и жарим их до корочки около 10-15 сек. Перекладываем на тарелку с салфеткой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12989,'Приготовим соус. В тарелку добавляем 4 ч.л. сметаны, 2 стебля нарезанного укропа, выдавливаем чеснок, и выдавливаем сок половинки лимона. Все перемешиваем. Убираем в сторону, чтобы соус настоялся. Все готово.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12990,'Изюм темного цвета без косточек растолочь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12990,'Добавить сахарный песок, часть воды, по две ложки пшеничной и ржаной муки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12990,'Оставить опару на сутки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12990,'Смесь процедить, досыпать еще немного муки, долить воду (380 мл), добавить сахар и оставить еще на 24 часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12990,'Ложку опары перемешать с пшеничной мукой и оставить на час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12990,'В кипящую воду добавить солод, оставить на полчаса под крышкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12990,'Приготовить тесто: перемешать опару с солодом, натуральным медом, уксусом и растительным маслом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12990,'Всыпать оставшуюся ржаную муку, оставить в теплом месте на четыре часа под крышкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12990,'Форму для выпекания смазать маслом, выложить тесто, оставить на 35 или 40 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12990,'Обмять мокрыми руками, посыпать зернами кориандра.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12990,'Время выпекания – один час, температура – 200 градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12991,'Перемешать соль с мукой, влить йогурт.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12991,'Оставить смесь на три или четыре дня под крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12991,'Готовую опару развести с подогретым молоком, всыпать обычную пшеничную и цельно-зерновую муку, соль. Должно получиться жидкое тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12991,'Накрыть продукт полотенцем, оставить на 12 часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12991,'Полученное тесто растворить в теплом молоке, добавить ржаную муку грубого помола.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12991,'Булку обмять, сформовать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12991,'Время выпекания – от полутора до двух часов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12992,'Отваренные вкрутую яйца пропустить через яйцерезку, твердый сыр натереть на крупной терке, слить с консервы масло, сайру размять вилкой. Промытую зелень укропа и лука мелко изрубить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12992,'Расстелить на столе листы лаваша и каждый полить майонезной сеткой. Один из лавашей присыпаем яйцами и сверху зеленью. Следующий лаваш притрусить сыром и так же рубленой зеленью. Размятую сайру разложить на третьем лаваше и присыпать зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12992,'Свернуть лаваш с яичной начинкой рулетом и положить на начало второго, сырного лаваша. Продолжить сворачивать. Переложить образованный рулет на лаваш с рыбной начинкой и свернуть рулетом большого диаметра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12992,'Для того чтобы дать рулету из тонкого лаваша «Мимоза» хорошо пропитаться, необходимо завернуть холодную закуску в фольгу и дать настояться в прохладном месте пару часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12993,'Мягкое сливочное масло комнатной температуры выложить в миску, размять при помощи вилки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12993,'Всыпать сахарный песок, компоненты перетереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12993,'Добавить муку и соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12993,'Продукты размять руками, должна получиться мелкая крошка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12993,'Вмесить сметану в несколько приемов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12993,'Тесто должно получиться однородным.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12993,'Продукт накрыть пленкой, поставить в холод на сорок минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12993,'Сформовать печенье любой формы, выпечь.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12994,'Взбить мягкий маргарин с солью и сахаром до получения пышной массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12994,'Вбить сырое куриное яйцо, массу взбить еще раз при помощи погружного миксера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12994,'В муку всыпать разрыхлитель, смесь в несколько приемов добавить в жидкую массу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12994,'Однородное тесто накрыть пленкой, поставить в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12994,'Через полчаса тесто раскатать, вырезать печенье с помощью формочек.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12994,'Другой способ: пропустить тесто через мясорубку. Выпечь до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12995,'Мясо нарезаем небольшими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12995,'Нарезаем полукольцами лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12995,'Измельчаем чеснок',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12995,'Смешиваем все ингредиенты, добавляем соль, перец, горчицу и хрен, перемешиваем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12995,'Накрываем и отправляем в холодильник мариноваться на 5-6 часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12995,'Помещаем мясо в рукав для запекания и отправляем в духовку на 200 градусов на 50-60 мин.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12996,'Выложить на плоском блюде порезанное вдоль волокон куриное мясо, смазать майонезом. Яйца, нарезанные брусочками выложить поверх курицы и сделать сетку из майонеза. Орехи перетереть в блендере или размять с помощью скалки. Присыпать яичный слой дроблеными орехами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12996,'Твердый сыр натереть на терке и выложить половину сырной стружки четвертым слоем, после чего смазать майонезом. Повторить все слои в той же очередности. Сверху нанести майонез и украсить разрезанными вдоль и очищенными от косточек ягодами винограда. Виноград необходимо выкладывать, начиная с центра салата и по спирали.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12996,'Оформляем края салата с копченой курицей «Тиффани» промытыми и отделенными от веточек листиками петрушки. Настаиваем блюдо пару часов и наслаждаемся прекрасным сочетанием вкуса и эстетики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12997,'Яйцо перемешать с сахаром, смесь взбить при помощи венчика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12997,'Маргарин из холодильника нарезать мелкими кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12997,'Ингредиенты соединить, размять вилкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12997,'Всыпать пищевую соду и муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12997,'Руки смазать растительным маслом, тесто вымешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12997,'Сформовать шар, положить его в холодильник на полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12997,'Раскатать продукт в пласт толщиной в один сантиметр.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12997,'Вырезать печенье.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12997,'Противень застелить пергаментом, вырезать печенье формочками, время выпекания – от десяти до пятнадцати минут, температура приготовления – 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12998,'Перемешать пшеничную муку с солью и растительным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12998,'Отдельно взбить сырые куриные яйца с сахарным песком, добавить сметану и гашеную пищевую соду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12998,'Ингредиенты соединить, всыпать муку порциями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12998,'Тесто вымесить до эластичного состояния.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12998,'Присыпать рабочую поверхность мукой, раскатать тесто, вырезать печенье.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12998,'Смазать противень маслом, выложить заготовки, печь при температуре 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12999,'Порезать помидоры на небольшие кусочки и измельчить в блендере вместе с соком. Посыпать солью, перцем, паприкой. Нарезать мелко лук, слегка обжарить его на растительном масле. В сковороду добавить фарш и продолжать жарить до готовности. Добавить перец и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12999,'Положить в кастрюлю пюре, полученное из помидоров, приготовленную зажарку из лука и фарша, налить четыре стакана питьевой воды. По желанию можно добавить сахар, бальзамин и какие-нибудь другие приправы. Пока суп закипает мелко порезать зелень. После закипания поварить суп несколько минут, затем добавить измельченную зелень и выключить суп.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (12999,'Заранее приготовить макароны, натереть сыр. Перед тем как подать на стол лазанья-суп с мясным фаршем, положить несколько ложек макарон в тарелки, налить суп, сверху хорошо посыпать сыром и мелко нарезанной зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13000,'На сковороде разогреть растительное масло. Выложить кусочки мяса и посыпать мукой - перемешать. Обжариваем на сильном огне до румяности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13000,'Лук, картофель, огурцы - нарезать кубиками.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13000,'В глинянные горшочки выкладываем картофель, затем огурцы, лук и мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13000,'Сметану залить водой и перемешать. А потом разлить эту смесь в горшочки. Сверху посыпать мелко нарезанным укропом и петрушкой, накрыть горшочки крышка. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13001,'Яблоки очистить от кожуры и семечек. Нарезать кубиками. Добавить 1.5 ст.л. лимонного сока и перемешать (чтобы яблоки не почернели), убрать в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13033,'Поставить в холод на четыре часа для пропитывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13001,'Яйца взбить с сахаром. Добавить корицу, соду гашеную лимонным соком, муку просеять и все перемешать. В тесто добавить яблоки - перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13001,'Форму смазать сливочным маслом и присыпать мукой. Излишки муки высыпать. Залить форму тестом. Духовку разогреть до 180 градусов. Выпекаем 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13001,'Шарлотку полностью остудить и посыпать сахарной пудрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13002,'Корень имбиря и чеснок очистить, нарезать мелкими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13002,'В сковороду налить немного оливкового масла для обжарки. Добавить корень имбиря и чеснок, красный острый перец (1/5 ч.л.). Обжариваем на сильном огне 4 минуты - перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13002,'Болгарский перец очистить от семян, нарезать на кубики, добавить к содержимому сковороды и обжаривать 10 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13002,'Целый ананас разрезать вдоль, вынуть начинку и слить 80 мл сока. Вынутую мякоть нарезать кубиками и добавить в сковородку, добавить очищенные креветки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13002,'В ананасовый сок влить соевый соус, воду, яблочный уксус. Добавить кукурузный крахмал и все тщательно перемешать. Вылить в сковороду - перемешать. Готовим 10 минут на сильном огне, перемешивая. Вся жидкость должна выпариться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13002,'Добавить орешки кешью, перемешать и готовить еще 3 минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13002,'В вырезанный ананас выложить содержимое сковороды.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13003,'Белый хлеб или батон залить водой на 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13003,'В чашу блендера положить лук. Батон отжать от лишней воды, добавить к луку. Туда же поместить филе минтая. Измельчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13003,'Переложить содержимое блендера в глубокую тарелку, вбить яйцо, соль (1 ч.л.), перец(1/2 ч.л.), мускатный орех (1/3 ч.л.), влить сливки - перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13003,'В сковороду налить растительного масла и разогреть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13003,'Формируем из фарша котлетки, обваливаем котлетку со всех сторон в панировочных сухарях. Готовим на среднем огне 7 минут с каждой стороны под крышкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13004,'Багет нарезать, выложить на противень, сбрызнуть оливковым маслом и отправить в духовку на 10 минут при температуре 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13004,'Бальзамический уксус смешать с сахаром и варить на сильном огне 5 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13004,'Черри разрезать на 4 части, авокадо очистить и нарезать на кубики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13004,'На багет выложить по чайной ложке рикотты, посыпать авокадо и черри, выложить петрушку и полить бальзамическим уксусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13005,'Курицу нарезать крупными кусочками. Обжарить на разогретом растительном масле при среднем огне до золотистой корочки с двух сторон (кусочки курицы должны лежать на сковороде свободно друг от друга). Готовую курицу сложить в тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13005,'Лук нарезать кубиками (мелко). Обжарить 12 минут (перемешивая) на сковороде, где готовилась курица. Готовый лук посолить (1/2 ч.л.), сложить в тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13005,'Шампиньоны нарезать тонкой соломкой. На той же сковороде готовим до золотистого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13005,'Чистую сковороду ставим на средний огонь сыпем муку, прокаливаем (довести до слегка золотистого цвета). Затем добавляем сливочное масло - перемешиваем, вливаем сливки и готовим до загустения, постоянно перемешивая.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13005,'Курицу нарезаем соломкой, пересыпаем в соус, добавляем грибы и лук, все перемешиваем и раскладываем по кокотницам, сверху посыпаем тертым сыром. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13006,'Разморозить тесто при комнатной температуре, нарезать его полосками, таким образом, чтобы полоску с ягодой можно было свернуть трубочкой. Выложить вишни на полоски теста рядами, если ягоды кислые, то можно посыпать сахаром. Свернуть тесто трубочками и хорошо защипать края.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13006,'Смазать противень растительным маслом или застелить промасленным пергаментом (если из трубочек будет вытекать сок, то они не пригорят). Выложить трубочки на противень швом вниз. Выпекать при температуре 200–220 градусов, пока трубочки не станут золотистыми и пышными. Пока трубочки остывают, делать крем. Взбить стакан сметаны с несколькими столовыми ложками сахара.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13013,'Лук нарезать мелко, морковь натереть, сырки нарезать кубиками. Хлеб нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13034,'Сырые куриные яйца взбить с сахарным песком, влить подогретое молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13006,'Выложить на блюдо пять трубочек в ряд. Смазать их кремом. Выложить сверху четыре трубочки, затем крем, три трубочки, крем и так далее. Должна получиться пирамидка. Залить ее кремом, украсить вишней и тертым шоколадом. Простой тортик «Дрова под снегом» должен пропитаться, после этого его можно кушать. Его можно разрезать или разбирать «по поленцу».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13007,'В чаше для миксера взбить яйца, влить молоко, растительное масло, добавить соль и муку. Перемешать получившуюся смесь. Крабовые палочки нарезать мелкими кубиками или натереть на терке. Высыпать их в чашу, добавить 2 столовых ложки мелко порезанного укропа. Тщательно перемешать массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13007,'Противень накрыть бумагой для выпечки, предварительно смазав её растительным маслом. Равномерно по поверхности бумаги распределить вылитую яично – молочно – крабовую смесь. Выпекать омлет при температуре около 180 градусов в течение 15 минут. Самое время приготовить начинку. На мелкой терке натереть сыр и вареные яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13007,'Добавить размельченный чеснок и укроп, залить майонезом, перемешать. Ингредиенты начинки можно изменить по своему вкусу, например, добавить перец. Слегка остывший омлет освободить от бумаги, распределить по его поверхности начинку, свернуть. Получившийся закусочный рулет из омлета с крабовыми палочками завернуть в пищевую пленку и оставить в холодильнике на 6 часов. Подавать на стол в порезанном виде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13008,'В пшеничную муку добавить сливочное масло, нарезанное кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13008,'Вымесить массу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13008,'В получившуюся крошку добавить погашенную уксусом или лимонным соком соду, сахарный песок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13008,'По желанию можно подсыпать еще немного муки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13008,'Скатать колобок, положить его в холод на 20 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13008,'Раскатать тесто в пласт толщиной один сантиметр, вырезать печенье произвольной формы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13008,'Выложить на противень, печь до золотистой корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13009,'Маргарин растопить на тихом огне, влить кефир, вбить яйцо, добавить соду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13009,'Продукты перемешать при помощи миксера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13009,'Всыпать муку, замесить тесто. Оно не должно липнуть к рукам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13009,'Поставить в холод на полчаса, затем сформовать печенья.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13009,'Температура приготовления – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13010,'Перемешать сахарный песок с яйцами и майонезом средней жирности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13010,'Добавить соду, погашенную лимонным соком, ванилин из пакетика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13010,'Муку всыпать небольшими порциями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13010,'Вымесить тесто, добавить нарезанное небольшими кусочками мягкое сливочное масло. Масса не должна получиться тугой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13010,'Вылепить шарики небольшого размера, выложить на противень, смазанный маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13010,'Кружки прижать вилкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13010,'Время выпекания – 15 минут, температура – 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13010,'Готовое печенье посыпать какао-порошком или сахарной пудрой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13011,'Сливочное масло перемешать с солью, перетереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13011,'Сырой желток взбить с сахарным песком, добавить холодную воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13011,'В яичную смесь порциями всыпать муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13011,'Мучную массу перемешать с масляной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13011,'Стол присыпать мукой, раскатать тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13011,'Сформовать печенье любой формы, печь в духовом шкафу при температуре 220 градусов, время – от десяти до пятнадцати минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13012,'Небольшими кубиками нарезать лук. Обжарить его в течение нескольких минут на разогретой сковороде до появления золотистой корочки. В отдельной кастрюльке приготовить смесь из взбитых куриных яиц с добавлением соли, перца, майонеза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13012,'В духовку поместить на 1–2 минуты предварительно смазанную маслом форму. В подогретую форму аккуратным слоем выложить пельмени. По вкусу поперчить, посолить. Поверх распределить равномерным слоем обжаренный лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13012,'Залить лук и пельмени яичной смесью. Натереть на крупной терке сыр. Посыпать им залитые смесью пельмени. Блюдо выпекать при температуре 220 градусов в течение 40 минут. Слегка остывшую запеканку «Ленивая жена» из пельменей украсить зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13013,'Нарезать картофель кубиками, промыть, залить холодной водой. Варить 15 мин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13013,'В разогретую сковороду влить немного масла и выложить хлеб. Жарить до тех пор, пока сухарики не станут хрустящими и золотистыми.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13013,'В сковороду влить растительное масло, добавить сливочное масло, выложить лук, обжарить в течении 2 мин, добавить морковь, жарить 1 мин.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13013,'Выложить зажарку в кастрюлю, добавить сливочный сыр, перемешать до полного растворения сыра.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13013,'Добавить соль, перец, поварить еще 3 мин, выключить огонь и дать постоять под крышкой минут 5.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13014,'Вливаем кефир в миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13014,'Добавляем соль и сахар, перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13014,'Вливаем масло (1 ст.л.). Добавляем соду, просеиваем муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13014,'Замешиваем тесто, выкладываем его в пакет и оставляем на час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13014,'Через час выкладываем тесто на силиконовый коврик, еще раз его вымешиваем, раскатываем колбаской, нарезаем на куски.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13014,'Каждый кусок придавливаем рукой. Выкладываем пышки в разогретое масло и жарим их на умеренном огне до красивой и золотистой корочки с двух сторон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13014,'Горячие пышки смазываем медом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13015,'Творог перемешать с мягким сливочным маслом, тертой лимонной цедрой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13015,'Отдельно муку перемешать с разрыхлителем и солью, просеять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13015,'Мучную смесь порциями добавить в творог.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13015,'Вымесить тесто, в нем не должно быть крупных комков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13015,'Тесто поделить на три части, раскатать, вырезать фигурки, выложить на противень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13015,'Время выпекания – 20 минут, температура – 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13016,'Бородинский хлеб нарезать крупной или мелкой соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13016,'Налить в сковороду рафинированное масло, продукт прогреть при средней температуре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13016,'Огонь уменьшить, выложить хлеб, жарить до румяной корочки, кусочки переворачивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13016,'Через пять или восемь минут гренки переложить на блюдо, натереть чесноком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13016,'Закуску украсить зеленью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13017,'Французский батон нарезать острым ножом брусками или кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13017,'Продукт переложить в небольшую емкость с майонезом и оливковым маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13017,'Раздавить очищенный чеснок, добавить к хлебу с соусом, всыпать сухой молотый перец, петрушку, майоран, соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13017,'Сыр «Пармезан» или «Российский» натереть или мелко нарезать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13017,'Прогреть духовой шкаф до 180 градусов, противень застелить пергаментом или фольгой, выложить гренки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13017,'Сбрызнуть закуску оливковым маслом, поставить в духовку на пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13017,'Хлеб перевернуть лопаткой, печь еще пять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13017,'Золотистые гренки смазать пряной смесью при помощи кисти и посыпать сыром.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13017,'Печь еще пять минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13017,'Закуску остудить, подать на стол к пиву.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13018,'Приготовление начинки.  Лук — репку аккуратно почистить и мелко нарезать. Грибы промыть, очистить, также  мелко порезать кусочками. Картошку почистить от шкурки, порезать лучше всего кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13018,'Обжарить овощи до момента готовности. Время обжаривания составляет, примерно, 6 минут. После этого необходимо добавить заранее нарезанный картофель и не забыть про  специи, посолить и жарить еще около 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13018,'Утку подготовить к фаршированию овощами, выложить приготовленную начинку. После того, как начинка полностью окажется внутри, необходимо зашить утку, затем посалить и поперчить ее.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13018,'Готовить блюдо удобнее всего  в  специальном рукаве для выпекания. Время полного  приготовления составляет около 120 минут, после истечения которых, праздничная утка фаршированная овощами готова украсить собою стол.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13019,'Пшеничный батон нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13019,'Прогреть на сковороде любое растительное масло, обжарить гренки с обеих сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13019,'Чеснок пропустить через пресс, перемешать с солью, натереть гренки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13019,'Закуску посыпать рубленой зеленью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13020,'Хлеб нарезать ломтиками, обжарить на тихом огне в течение четырех минут, продукт несколько раз перевернуть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13020,'Чеснок натереть или пропустить через пресс, соединить со специями, солью, сбрызнуть растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13020,'Пряную смесь нанести на сухарики при помощи кисти.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13021,'Фарш выложить в чистую,  тарелку с широкими краями или лучше взять для этого миску, добавить измельченный чеснок.  Специи добавить и хорошо перемешать, посолить и опять перемешать. В фарш также положить  куриное яйцо полностью и четверть стакана хорошей сметаны средней жирности, а также муку, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13021,'Картошку и лук — репку очистить от кожуры, мелко порезать или для упрощения работы натереть на терке. Содержимое переложить в дуршлаг и деть постоять, чтобы ушел лишний сок. Переложить смесь в миску, добавить яйца,  соль и все необходимые  приправы, перемешать. Затем всыпать аккуратно муку и опять смесь хорошо и тщательно размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13021,'Духовку заранее подогреть до температуры в 180  градусов. Форму, где будет готовиться вкуснейшая запеканка, смазать маргарином или маслом и выложить овощную смесь, сформировать порционные биточки. В серединку каждой сформированной  порции положить подготовленный  фарш и распределить по всей поверхности биточка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13021,'Процесс полного запекания длится около 45-50 минут, после чего из духовки форму необходимо вынуть, затем следует добавить сверху заранее натертый твердый сыр, посыпать блюдо, поставить запекаться еще на 12-15 минут. Запеканка из картофеля с фаршем из индейки полностью готова. Подавать ее  лучше всего сразу и горячей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13022,'Необходимо аккуратно всыпать в молоко сахар и дрожжи. Взбить яйца вместе с маслом. Затем объединить две смеси в одну и хорошо перемешать. Добавить муку. Замесить тесто и поставить его в теплое место, чтобы оно подошло примерно на 1-1,5 часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13022,'Раскатать готовое тесто на пласт толщиной в 1-1,5 см. Вырезать из него пончики при помощи двух стаканов, которые различны по диаметру. Выпекать следует в течении 15-20 минут в предварительно разогретой до 200 градусов духовке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13022,'Далее нужно приготовить из смеси молока, масла и пудры глазурь. Ранее испеченные аппетитные пончики аккуратно обмакнуть в шоколадную глазурь. При желании сверху обсыпать сахарной крошкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13023,'Перекрутите на мясорубке очищенные грецкие орешки и печенье.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13023,'Добавьте сгущенку вареную, хорошо все перемешайте.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13023,'Выложите массу в форму, которую застелите пищевой пленкой. Утрамбуйте хорошо массу толкушкой. Отправьте торт на 30 минут в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13024,'Сначала я приготовила начинку. Картофель отварила в подсоленной воде. Лук порезала и обжарила до мягкости на растительном масле.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13024,'Затем приступила к приготовлению теста. В глубокую миску налила теплый картофельный отвар, затем добавила соль, сахар, свежие дрожжи, растительное масло, перемешала ложкой ингредиенты между собой. В подготовленную жидкую смесь постепенно добавила просеянную муку. И вымешивала до состояния мягкого, немного липкого теста. Готовое тесто еще вымесила с помощью подсолнечного  масла и поставила в теплое место для поднятия. Когда тесто вдвое увеличилось в объеме, приступила к формированию пирожков.','https://vkuso.ru/data/cache/data/84/488b3ab9a854a84_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13024,'Готовое тесто разделила пополам, каждую половину скатала в жгут, затем разделила на кусочки, каждый кусочек подкатала в шарик.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13024,'Жарила пирожки в хорошо разогретом растительном масле на умеренном огне с двух сторон до золотистой румяной корочки. Уровень масла в сковороде должен доходить до середины высоты пирожка. Перед жаркой пирожков проверила разогрев масла, с помощью маленького кусочка теста. Когда кусочек зарумянился, можно приступать к жарке.','https://vkuso.ru/data/cache/data/7e/d60009452562c7e_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13033,'Отдельно взбить сгущенное молоко с сыром «Маскарпоне».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13033,'Выложить трубочки на блюдо в виде поленницы, прослоить кремом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13034,'Ввести муку порциями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13024,'Готовые пирожки по желанию можно выложить на бумажное полотенце, чтобы убрать излишки масла (я так не делала), затем переложить на блюдо и можно подавать горячими к столу.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13025,'Чеснок очистить, пропустить через пресс, перемешать с солью, довести массу до однородного состояния при помощи пестика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13025,'Пасту разбавить растительным маслом, перемешать с нарезанным брусками бородинского хлеба.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13025,'Отправить закуску в духовой шкаф, температура приготовления – 190 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13025,'Противень застелить пергаментом или фольгой, смазать маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13025,'Сухарики посыпать тмином.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13026,'Для начала взбить в крепкую пену яйца с добавлением соли и сахара. Помешивая добавить кипяток. Яйца при этом не свернутся, но объем сильно увеличится, поэтому следует взять сразу большую посуду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13026,'Погасить соду, погашенную в кефире. Влить в смесь и постепенно добавить муку. При этом тесто получается похожее на консистенцию подсолнечного масла. Если получилось гуще, то следует добавить кипяток. После чего в тесто влить растительное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13026,'Блинчики необходимо выпекать на большом огне, каждый раз тщательно промазывая сковородку маслом. Тесто нужно наливать на хорошо разогретую сковородку тонким слоем. Блины смазать творожным сыром и свернуть в рулетики. Блинчики на кефире с творожным сыром готовы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13027,'Ржаной хлеб нарезать ломтиками толщиной в один сантиметр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13027,'Обжарить на растительном масле с двух сторон до корочки, посыпать специями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13027,'Отварить куриное яйцо, очистить, натереть на терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13027,'Перемешать с давленым чесноком и майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13027,'Выложить ломтики на блюдо, остудить в течение двух минут, выложить сверху яичную пасту.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13028,'Ржаной хлеб нарезать брусками, подсушить в духовом шкафу в течение десяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13028,'Чеснок раздавить, перемешать с растительным маслом и сырым взбитым желтком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13028,'Смесь приправить солью и специями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13028,'Массу вылить на сухари, перемешать, закуску отправить в духовку на семь минут, температура – средняя.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13029,'Пшеничный батон разрезать на кусочки небольшого размера, обжарить с одной стороны на масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13029,'Обжаренную сторону натереть чесноком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13029,'Отваренные куриные яйца и охлажденный плавленый сыр натереть на терке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13029,'Массу посолить по вкусу, добавить специи, майонез.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13029,'Пасту выложить на обжаренную сторону гренок, украсить веточками зелени.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13030,'Бородинский хлеб нарезать тонкой соломкой, разложить на застеленном бумагой противне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13030,'Продукт посолить, посыпать сушеным чесноком, полить оливковым маслом, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13030,'Запекать закуску при температуре около двухсот градусов, время – восемь или девять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13031,'Сырые куриные яйца взбить с майонезом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13031,'Белый хлеб нарезать и обмакнуть в смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13031,'Продукт обжарить на прогретой сковороде с маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13031,'Раздавить чеснок, порубить зелень петрушки, перемешать компоненты с майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13031,'Полученной массой смазать гренки, посыпать блюдо измельченным сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13032,'Домашнее молоко довести до кипения, а затем остудить до сорока градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13032,'Если продукт приобретен в магазине, его нужно прогреть в мультиварке до указанной температуры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13032,'Теплое молоко перемешать с закваской в нужной пропорции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13032,'Выставить режим «Йогурт» на восемь часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13032,'Можно выбрать температуру в сорок градусов на это же время.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13032,'Молоко сквасится, далее выставить режим «Подогрев» на два часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13032,'Сыворотка должна отойти.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13032,'Дуршлаг застелить марлей, творог отжать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13033,'Тесто раскатать и нарезать полосками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13033,'Выложить ягоды вишни, завернуть трубочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13033,'Время выпекания в духовом шкафу – 20 минут, температура – 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13034,'Смазать сковороду маслом, выпечь румяные блинчики.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13034,'Свернуть трубочки, начинка – ягоды вишни.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13034,'Жирные сливки перемешать с сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13034,'Выложить изделия горкой на поднос, промазать кремом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13034,'Поставить в холодильник на три часа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13035,'Основой этого пирога является капуста, которую необходимо нашинковать соломкой или порезать мелкими квадратиками. Сложить ее в подготовленную форму. Растопить маргарин на медленном огне, не допуская закипания. Залить им капусту, тщательно перемешав.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13035,'Для приготовления теста необходимо взбить миксером яйца, добавить сметану и майонез. В муку всыпать соль и разрыхлитель, добавить в нее яичную смесь и взбить миксером. Залить капусту жидким тестом и поставить в горячую духовку на полчаса. Домашний пирог с капустой для ленивых приобретает красивый золотистый цвет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13036,'Просеять ржаную и пшеничную муку, добавить дрожжи, сахарный песок, соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13036,'Влить подогретую воду, замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13036,'Оставить на час в тепле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13036,'Подошедшую массу обмять и оставить еще на некоторое время.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13036,'Готовое тесто выложить на противень в виде круглой булки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13036,'Изделие смазать взболтанным яйцом, присыпать мукой и кунжутным семенем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13036,'Время выпекания – от получаса до тридцати пяти минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13037,'Выложите творог в миску, добавьте сахар и яйцо. Блендером все хорошо перемешайте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13037,'Добавьте соду и муку. Замесите тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13037,'Раскатайте его колбаской, нарежьте на куски, каждый раскатайте.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13037,'Разогрейте масло растительное. Выложите палочки и обжарьте их на умеренном огне до красивого и золотистого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13037,'Готовые палочки посыпьте сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13038,'Помидор нарезаем тонким ломтиком, и перекладываем в отдельную тарелку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13038,'Крабовые палочки нарезаем мелко-тонко. и перекладываем в ту миску, где будете замешивать салат.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13038,'Укроп нарезаем мелко-мелко и перекладываем в туже миску.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13038,'Лук зелёный нарезаем так же мелко.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13038,'Вареную колбасу, или можно использовать ветчину, нарезаем мелким кубиком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13038,'Красный болгарский перец, нарезаем так же мелким кубиком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13038,'Сыр натираем на мелкой терке. и все в туже миску.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13038,'Далее, нужно замешать салат. В миску, где у вас все подготовленные ингредиенты, добавляем сметану 3 ч.л. и майонез 2 ч.л., соль перец по вкусу, и все перемешиваемым, и даем минут 10 настояться салату.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13038,'На мини тостовый хлеб наносим салат, и укладываем ломтик помидора. Снова на тостовый хлеб наносим салат, но уже не укладываем ломтик помидора. И так далее...
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13039,'Молоко довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13039,'При постоянном помешивании всыпать манную крупу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13039,'Добавить сахар и соль. Добавить сливочное масло 20 гр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13039,'Варить до густого состояния каши.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13039,'Большой ложкой, смачивая в воде, набираем манку и на противень, присыпанные мукой выкидываем заготовки. Делаем всё очень быстро. Так как манка остывает и потом трудно с ней будет работать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13039,'Формируем биточек. Обваливаем во взбитом яйце и обжариваем на маленьком огне до румяности с обеих сторон.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13039,'Готовые манники смазать сливочным маслом 10 гр. Подавать с натуральным йогуртом или сметаной.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13040,'В муку добавить соль, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13040,'Добавить яйцо и перемешать. Добавить воды и замесить тесто. Переложить в пакет и оставить пока займёмся начинкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13040,'Берём любой фарш. Мелко нарезаем лук и картофель, очень мелкими кубиками. Добавляем к фаршу. Добавляем специи и соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13040,'Отдельно порезать 2 луковицы , обжарить, добавить морковь, протушить ещё 2 минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13040,'Тесто разделить на 2 части.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13040,'Поверхность присвоить мукой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13040,'Раскатать тонкий пласт и выложить на него половину начинки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13040,'Свернуть рулетом и нарезать на кусочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13040,'Выложить рулетики на зажарку , залить горячей водой почти до верху, но немного не доходя.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13040,'Посолить водичку , накрыть крышкой и готовить на умеренном огне около 30 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13040,'Подавать со сметаной или натуральным йогуртом . Посыпать зеленью.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13041,'Картошку нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13041,'В кипящую воду опустить картофель и варить 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13041,'Лук порезать кубиками, морковь соломкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13041,'Отправить обжарится на растительном масле 5 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13041,'Добавить болгарский перец, порезанный кубиками и тушить ещё 2 минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13041,'Сыр натереть на мелкой тёрке. Смешать его со сливочным маслом. Добавить яйцо, куркуму и паприку. Перемешать. Добавить муки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13041,'Тесто разделить на 2 части и раскатать в тонкую колбаску, как толстый карандаш. Порезать кубиками и сформировать горошинки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13041,'Когда картофель сварился, добавить клецки и зажарку. Варить ещё 5 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13041,'Выключить и добавить зелень. Накрыть крышкой и дать супу настояться 30 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Желтки отделить от белков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Взбить с сахарным песком в течение пяти минут.','https:https://st.vkuso.ru/data/cache/thumb/45/bca7baa91b9e745_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Белки взбить отдельно, сахар всыпать порциями. Масса должна получиться пышной и плотной.','https:https://st.vkuso.ru/data/cache/thumb/76/5daf8909085e776_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Белковую массу ввести в желтковую.','https:https://st.vkuso.ru/data/cache/thumb/3c/593f365ee7aa73c_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Каждый раз смесь осторожно перемешивать движениями снизу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Всыпать порциями просеянную муку. Тесто должно получиться мягким и без комочков.','https:https://st.vkuso.ru/data/cache/thumb/57/ad86b62facbeb57_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Застелить противень листом пергамента, нарисовать на нем ровные круги диаметром четыре или пять сантиметров.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Отсадить лепешки при помощи кондитерского мешка. Тесто не должно растекаться.','https:https://st.vkuso.ru/data/cache/thumb/4f/dc6d8441c54754f_434x295.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Время выпекания – от десяти до двадцати минут, температура приготовления – 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Готовность проверить зубочисткой.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Лепешки остудить.','https:https://st.vkuso.ru/data/cache/thumb/14/af50e0599f60114_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Приготовить пропитку из кипящей воды и сахара.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Сироп остудить, добавить коньяк или любой ликер.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Полить пропиткой лепешки, дать пропитаться.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Темный шоколад поломать кусочками, добавить сливочное масло.','https:https://st.vkuso.ru/data/cache/thumb/5a/cf627231cfc375a_434x295.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Прогреть массу на водяной бане, помешивать. Глазурь должна получиться однородной, без комков.','https:https://st.vkuso.ru/data/cache/thumb/1e/468758ae46be51e_434x295.jpg',16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Половину лепешек окунуть одной стороной в растопленный шоколад с маслом.','https:https://st.vkuso.ru/data/cache/thumb/62/f8447c70f8fc362_434x295.jpg',17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Дать заготовкам застыть в холодильнике.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'По желанию пирожное можно украсить узорами из растопленного белого шоколада.','https:https://st.vkuso.ru/data/cache/thumb/c7/f9e4edb3b4e80c7_434x295.jpg',19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Приготовить крем из сахарного песка и воды, массу прогреть до кипения и варить пять минут, затем влить сгущенное молоко.','https:https://st.vkuso.ru/data/cache/thumb/01/336d4387555b601_434x295.jpg',20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Продукты перемешать, еще раз довести до кипения, снять с огня и остудить.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Сливочное масло комнатной температуры взбить до пышности.','https:https://st.vkuso.ru/data/cache/thumb/d3/b82211eff6975d3_434x295.jpg',22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Постепенно ввести сгущенное молоко и сироп, продолжать взбивать массу миксером.','https:https://st.vkuso.ru/data/cache/thumb/85/2d5c84769f85a85_434x295.jpg',23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Половину лепешек намазать абрикосовым джемом, второй слой – крем из кондитерского пакета','https:https://st.vkuso.ru/data/cache/thumb/0a/cf6ec03e66c3c0a_434x295.jpg',24);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Сверху – лепешки с шоколадной глазурью.','https:https://st.vkuso.ru/data/cache/thumb/dc/3c6df98481d2ddc_434x295.jpg',25);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13042,'Поставить пирожные в холодильник на два или три часа.',NULL,26);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13053,'Для начинки кузикмяк необходимо сварить картофель, растолочь его в пюре и добавить 50 г сливочного масла, молоко, мелко нарезанный укроп и обжаренный до золотистого цвета лук. Тесто готовится легко, оно должно быть мягким и эластичным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13067,'Желтки вбить по одному, продолжать взбивать.','https:https://st.vkuso.ru/data/cache/thumb/f5/93c377b91a3b4f5_434x295.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13043,'Для начинки необходимо обжарить мелко нарезанные грибы и смешать их с ветчиной, предварительно нарезанной кубиками. Для мягкости фарша, его необходимо немного отбить. Для этого фарш кидают о стол, чтобы из молотого мяса выделился сок. Добавить в фарш молотый лук, размягченный в молоке хлеб и яйцо. Все тщательно перемешать. Натереть картофель на мелкой терке и добавить в фарш.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13043,'Посолить, поперчить по вкусу. Тщательно перемешав фарш, разбить его на порционные шарики. Распластав мясной шарик, положить в середину начинку и хорошо скрепить фарш по бокам, чтобы начинка оказалась внутри. Обжарить котлеты на раскаленной сковороде в масле, обмокнув сначала в яйцо, потом в муку и в сухари. Это создаст своеобразную «шубу» и мясные зразы с начинкой из ветчины и грибов будут очень сочные.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13044,'Разделить сырые куриные яйца на желтки и белки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13044,'Желтки растереть с частью сахара, масса должна увеличиться в объеме в несколько раз.','https:https://st.vkuso.ru/data/cache/thumb/df/bbe999dc8924ddf_434x295.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13044,'Белки охладить и взбить с сахаром также до увеличения объема.','https:https://st.vkuso.ru/data/cache/thumb/56/8e2f268a9f7d856_434x295.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13044,'Желтки перемешать с третьей частью белковой массы.','https:https://st.vkuso.ru/data/cache/thumb/98/867a1ba7e761e98_434x295.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13044,'Всыпать муку, еще раз перемешать.','https:https://st.vkuso.ru/data/cache/thumb/be/5bc39846c64aebe_434x295.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13044,'Влить остатки белков, продукты осторожно соединить движениями снизу-вверх.','https:https://st.vkuso.ru/data/cache/thumb/34/979f72a37b2fc34_434x295.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13044,'Отсадить тесто на противень в виде лепешек с помощью столовой ложки или кондитерского мешка. Время выпекания – от пятнадцати до двадцати минут, температура – от 190 до 200 градусов.','https:https://st.vkuso.ru/data/cache/thumb/e8/67af69245957ae8_434x295.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13044,'Приготовить крем из сливочного мягкого масла, сахара, сгущенного молока и коньяка.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13044,'Массу взбить при помощи миксера в течение трех или пяти минут.','https:https://st.vkuso.ru/data/cache/thumb/ce/75d4d08285530ce_434x295.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13044,'Для приготовления глазури перемешать сахарный песок с какао-порошком.','https:https://st.vkuso.ru/data/cache/thumb/37/b4a665758fcad37_434x295.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13044,'Добавить сгущенное и обычное молоко.','https:https://st.vkuso.ru/data/cache/thumb/92/8376b6df76fa592_434x295.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13044,'Прогреть на тихом огне. Должна получиться коричневая масса без комочков.','https:https://st.vkuso.ru/data/cache/thumb/1b/957744e66e7e01b_434x295.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13044,'Половину выпеченных бисквитных лепешек намазать кремом.','https:https://st.vkuso.ru/data/cache/thumb/34/921d38147dad534_434x295.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13044,'Вторую – обмакнуть одной стороной в глазурь.','https:https://st.vkuso.ru/data/cache/thumb/d8/9777481834712d8_434x295.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13044,'Заготовки соединить попарно.','https:https://st.vkuso.ru/data/cache/thumb/33/00c305a9cf16e33_434x295.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13045,'Сухие дрожжи всыпать в теплую воду, добавить сахар и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13045,'Оставить смесь на пятнадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13045,'Влить подсолнечное масло, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13045,'Добавить муку двух сортов, заранее просеянную.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13045,'Замесить тесто, накрыть пищевой пленкой, оставить на час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13045,'Тесто вымесить, оставить на сорок минут для выстойки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13045,'Духовой шкаф прогреть до 220 градусов, печь хлеб в форме, время – от сорока до пятидесяти минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13046,'Солод залить кипящей водой, перемешать и подержать под крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13046,'Добавить мускатный орех и другие пряности, соль, еще раз перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13046,'Развести в теплой воде натуральный мед и сахарный песок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13046,'Жидкую смесь влить в мучную, добавить теплый солод.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13046,'Продукты перемешать до однородного состояния.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13046,'Форму для выпекания смазать растительным маслом, выложить тесто, оставить в тепле на некоторое время.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13046,'Сверху сделать несколько надрезов, печь в течение пятидесяти минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13047,'Яблоко очистить от кожуры, семян и нарезать на тонкие полоски, сбрызнуть их лимонным соком, чтобы не потемнели. Болгарский перец очистить от семян и нарезать такими же полосками, как яблоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13053,'В теплое молоко вбить яйца, соль, хорошо перемешать. Добавить муку и вымесить тесто. Раскатать из теста очень тонкий пласт. По форме тарелки, вырезать кружочки из теста, присыпая постоянно мукой, чтобы не слиплись.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13074,'Добавить остатки муки, замесить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13047,'Листья салата просушить и порезать соломкой. Иногда предпочтительнее листья салата рвать руками, чтобы в блюде чувствовался вкус зелени, это на вкус каждого. Сырое куриное филе нарезать соломкой и обжарить до золотистой корочки на растительном масле, ароматизированном чесноком. Для этого пару минут чеснок обжаривают на сковороде в масле, затем зубки выбрасывают, а масло получается ароматным.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13047,'Смешать в миске листья салата, перец, яблоки, заправку, довести до вкуса специями. Жареные кусочки курицы добавить в последнюю очередь, чтобы придать аромат и пикантность диетическому салату с куриной грудкой и сладким перцем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13048,'Обдирную муку залить кипятком и перемешать, оставить продукт на сутки для набухания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13048,'На второй день добавить квасную гущу, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13048,'Всыпать сахарный песок, еще немного грубой муки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13048,'На третьи сутки массу посолить, влить растительное масло, всыпать еще немного сахара, давленые семена кориандра, оставшуюся муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13048,'Форму для выпекания смазать маслом, сформовать буханку, оставить на три или четыре часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13048,'Время выпекания – полтора часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13049,'Маринованные грибочки уложить в миску вверх ножками, хорошо притрусив их порезанным зеленым луком. Смазать слой майонезом. Нарезать мелкими кубиками ветчину и уложить следующим слоем. Промазать майонезом. Вареный картофель нарезать кубиками и уложить следующим слоем, майонез. Вареные яйца, нарезанные кубиками, завершают последний слой. Майонез.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13049,'Перед подачей на стол, миску с салатом необходимо перевернуть и выложить салат на плоскую тарелку, чтобы грибы получились шляпками вверху. Для того, чтобы салат с ветчиной, картофелем и опятами легко вынимался, перед укладкой слоев, миску следует смазать растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13050,'Для эклеров необходимо подготовить заварное тесто. Для этого воду посолить, добавить масло и довести до кипения. В кипящую на медленном огне воду добавлять понемногу муку, постоянно помешивая тесто. Когда начнет масса отставать от кастрюли, тесто снять с огня и охладить. Помешивая тесто, вбивать в него яйца по одному.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13050,'Противень застелить пергаментом, выкладывать тесто при помощи кондитерского мешка на противень. Формы эклеров могут быть продолговатые или круглые. Для выпекания необходимо следить за температурой в духовке. Первые 15 минут тесто находится при температуре 200 градусов, затем уменьшить температуру до 150. Через 15 минут выключить печь и открыть дверцу духовки, чтобы пирожные остывали медленно.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13050,'Для приготовления крема необходимо взбить миксером сливки и сгущенку. Сначала охлажденные сливки взбивать 10 минут, затем в пышную массу добавить сгущенное молоко, взбить. Наполнить домашние эклеры сливочной начинкой при помощи кондитерского шприца или мешка, охладить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13051,'Для начала необходимо снять кожуру с помидор, для этого обдайте овощи кипятком и легко снимите кожуру. Помидоры порежьте кольцами, толщиной не больше 1 сантиметра. Посолите, поперчите, добавьте любимых специй.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13051,'Для приготовления кляра, необходимо взбить охлажденные яйца и добавить сметану или майонез, еще раз хорошо взбить. В массу всыпать мелко натертый сыр, перемешать ложкой. На раскаленную сковороду налить растительного масла, чтобы наполовину покрыло помидоры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13051,'Когда масло прогреется, выкладывайте помидоры, окуная их в кляр. Обжаривайте с двух сторон до золотистой корочки. Обжаренные закусочные помидоры в сырном кляре выложите на бумажные салфетки, чтобы впитать лишнее масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13052,'Для чипсов выбрать картофель без изъянов, вымыть и очистить от кожуры. Нарезать картофель тонкими слайсами через овощерезку или специальную терку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13052,'Картофельные слайсы выложить ровно на пергаментную бумагу одним слоем. Соль и специи добавьте по вкусу и предпочтениям. Чипсы можно готовить без соли, вкус получается отличный.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13052,'Поставьте картофель на бумаге в микроволновку и включите печь на мощность 700 Вт. Через 3-5 минут картофель начнет приобретать коричневый цвет, домашние чипсы без масла в микроволновке готовы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13066,'Масса должна получиться мягкой, но не липкой. Использовать сразу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13053,'На огонь поставить сковороду, раскалить ее и обжарить на ней лепешки без добавления жира. Когда тесто покроется вздутыми пузырьками, значит, лепешка готова. Горячую лепешку смазать топленым маслом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13053,'Выложить начинку на половину лепешки, пустой половиной накрыть начинку. Смазать маслом. Когда лепешка пропитается маслом и начинкой, вкусный татарский кузикмяк «Аниса» готов к употреблению. Начинка не обязательно должна быть обычная, можно начинять лепешки кашами или тушеными овощами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13054,'Баклажаны вымыть и нарезать кружочками наискосок, чтобы удлинить кружок.  Посыпать солью баклажаны и дать стечь соку, чтобы убрать горечь.  Промыв баклажаны, просушить бумажным полотенцем, посолить и окунуть кружок одной стороной в муку. На раскаленной сковороде, смазанной маслом, обжарить баклажаны с двух сторон до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13054,'Обжаренные баклажаны выложить на бумажное полотенце, чтобы стек весь жир. Для начинки потрите сыр на мелкой терке, добавьте чеснок и майонез. Тщательно перемешайте. Свежие огурцы нарезать тонкими ломтиками. Маслины тонко нарезать кружочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13054,'На баклажаны выложить сырную намазку, украсить огурцом и маслиной. Выложить закуску на блюдо в форме павлиньего хвоста. Кабачками можно заменить баклажаны, а начинку попробовать с другими ингредиентами, главное сочетание вкуса и формы. Аппетитная закуска «Павлиний хвост» готова.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13055,'Взбить миксером сгущенное молоко, яйца и сметану. В муку добавить разрыхлитель, сахар и какао. Соединить муку с жидкой массой, хорошо взбить миксером на маленьких оборотах. Тесто вылить в подготовленную форму и выпекать в духовке при 180 градусах. В остывшем корже необходимо выбрать середину и уложить пространство разрезанными пополам бананами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13055,'Охлажденные сливки взбить с сахарной пудрой в пышную массу. Выложить сливки ложкой на бананы, чтобы получилась горка. На сливки покрошить крошки из коржа, которые выбрали из середины. Домашний торт «Норка крота» должен настояться, тогда он приобретет свою сочность. Бананы можно заменить на кисло-сладкие фрукты, например, клубнику, мандарины, апельсины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13056,'В чашу вложить продукты в той очередности, которая положена по инструкции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13056,'Использовать пшеничную муку, молотую рожь, сухое молоко, сливочное масло, немного меда, соль, солод, тмин и пекарские дрожжи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13056,'Выбрать нужный режим, печь до получения корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13057,'Перемешать цельнозерновую и ржаную муку с солью, дрожжами, сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13057,'Влить подогретую воду и оливковое масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13057,'Тесто вымешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13057,'Добавить светлый изюм, еще раз перемешать, добавка должна распределиться равномерно.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13057,'Миску смазать растительным маслом, положить тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13057,'Емкость накрыть пленкой, оставить на два часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13057,'Выложить тесто на стол, разделить на части, сформовать изделия.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13057,'Накрыть булки полотенцем, оставить в тепле на час.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13057,'Время выпекания – полчаса.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13058,'Креветки в панцире разогреть на сковороде, смазанной маслом. Добавьте немного воды, чтобы креветки пропарились. Готовить по 2 минуты с одной и другой стороны. Выложить креветки на тарелку, когда остынут почистить, оставив хвостики для красоты.  В сковороде осталась жидкость, в которой готовились креветки, оставьте ее для дальнейших действий.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13058,'Спагетти отварить в подсоленной воде. Спагетти лучше оставить немного недоваренными, чем переваренными. Растительное масло ароматизировать чесноком. Для этого поджарить чеснок на раскаленном масле 2 минуты, после чего чеснок выкинуть. На сковороду с маслом высыпать порубленные грибы, обжарить. В грибы добавить шпинат. Готовить на медленном огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13058,'В грибы и шпинат влить молоко, затем ввести муку. Для того чтобы не было комочков муки, ее следует развести в чашке с небольшим количеством молока, затем влить в сковороду. Доведите смесь в сковороде до кипения, чтобы молоко загустело. Если масса недостаточно густая, добавьте муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13067,'Мягкое сливочное масло взбить с сахарной пудрой при помощи миксера.','https:https://st.vkuso.ru/data/cache/thumb/e6/3685eebefc151e6_434x295.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13165,'Влить лимонный сок, варить продукт еще полчаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13058,'Добавьте в сковороду жидкость с креветок, тщательно перемешайте и доведите до кипения. Креветки в соусе доведите до вкуса специями. В сковороду с креветками высыпать спагетти и перемешать. Спагетти с грибами и креветками в сливочном соусе готовы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13059,'Две ложки солода перемешать с пшеничной мукой и залить кипящей водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13059,'Массу перемешать вилкой, оставить до остывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13059,'Отдельно развести сухие дрожжи в стакане воды, добавить соль и сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13059,'Добавить заварное тесто, перемешать, оставить на два с половиной или три часа под полотенцем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13059,'Массу вымесить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13059,'Сформовать булку, выложить в форму для выпекания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13059,'Отправить в духовой шкаф на час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13060,'Перемешать пшеничную и ржаную муку в равных количествах.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13060,'Другой вариант: пшеничной муки должно быть в три раза больше, чем ржаной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13060,'Добавить дрожжи, соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13060,'Массу перемешать, влить теплую воду и кефир.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13060,'Сформовать шар, накрыть полотенцем, оставить на двадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13060,'Массу еще раз вымешать, оставить под тканью на десять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13060,'Тесто обмять, сформовать шар, выложить н противень, сделать несколько надрезов, оставить на час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13060,'Время выпекания в духовом шкафу – тридцать минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13061,'Изюм промыть, обсушить, измельчить, залить водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13061,'Перемешать ржаную муку с сахарным песком, пищевой содой, разрыхлителем, добавить кефир и кусочек мягкого сливочного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13061,'Массу перемешать ложкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13061,'Влить воду, добавить изюм, тесто перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13061,'Выложить продукт на стол, вымесить, масса должна получиться эластичной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13061,'Сформовать, положить в форму.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13061,'Время выпекания – 45 минут, температура – 220 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13062,'В пшеничную муку всыпать разрыхлитель, перемешать, просеять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13062,'Добавить соль, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/f6/4d0da97da1b93f6_434x295.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13062,'Мягкое сливочное масло взбить при помощи миксера.','https:https://st.vkuso.ru/data/cache/thumb/60/f83dd87167c6060_434x295.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13062,'Сахарный песок ввести небольшими порциями, продолжать взбивать.','https:https://st.vkuso.ru/data/cache/thumb/d7/79d02d88e84fdd7_434x295.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13062,'Ввести сырой куриный желток, а затем муку. Скорость работы миксера увеличить, должна получиться маслянистая крошка.','https:https://st.vkuso.ru/data/cache/thumb/f7/d341e8672fe21f7_434x295.png',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13062,'Перемешать массу руками, завернуть в пищевую пленку, поставить в холодильник на полчаса.','https:https://st.vkuso.ru/data/cache/thumb/70/2ef572af4637170_434x295.png',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13063,'Перемешать жирный творог, яйца, сахар, соль, манку, сметану, добавить соду и ванилин. Бананы нарезать кубиками со стороной в один сантиметр вместе с кожурой. Кожура должна быть плотной, светлой, без признаков гниения. Вмешать в основную творожную массу, осторожно, чтобы не превратить бананы в кашу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13063,'Смазать форму для запекания сливочным маслом, печь около часа при температуре 180 градусов, до золотистой корочки.  Остудить сытную творожно-банановую запеканку в форме, вынуть, подать, порезав на порционные куски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13064,'В емкость с мягким сливочным маслом всыпать сахар и соль, взбить массу на небольшой скорости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13064,'Вбить сырое куриное яйцо и дополнительный желток, продолжать взбивать до тех пор, пока не получится однородная, пышная масса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13064,'Муку всыпать постепенно, порциями, замесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13064,'Выложить его на рабочую поверхность, продолжать месить руками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13064,'Готовый продукт можно использовать для выпечки сразу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13065,'Сырые куриные желтки перетереть с сахаром, солью и маргарином хорошего качества.','https:https://st.vkuso.ru/data/cache/thumb/79/1b9996e064b5e79_434x295.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13065,'В массу влить сметану, взбить вилкой до однородности.','https:https://st.vkuso.ru/data/cache/thumb/85/a051f38ef895185_434x295.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13065,'Всыпать разрыхлитель, ввести муку порциями, замесить тесто.','https:https://st.vkuso.ru/data/cache/thumb/49/76a4b9a0e6dcf49_434x295.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13066,'Мягкое сливочное масло перемешать с яйцом и сметаной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13066,'Пшеничную муку всыпать порциями, тесто замесить руками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13067,'Пшеничную муку всыпать через сито, перемешать до получения однородной мягкой массы.','https:https://st.vkuso.ru/data/cache/thumb/37/cde19029da13a37_434x295.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13067,'Завернуть тесто в пленку и положить в холодильник.','https:https://st.vkuso.ru/data/cache/thumb/ae/fac60b0fddd4cae_434x295.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13068,'Содержимое банки с горбушей размять вилкой (жидкость слить). Обжарить на растительном масле рубленый репчатый лук, соломку моркови (отдельно), отварить вкрутую куриные яйца. Порезать маринованные грибы. Если они очень острые – предварительно промыть водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13068,'Выкладывать на блюдо слоями, сначала рыба, затем лук, грибы, натертые белки яиц с рубленым чесноком, обжаренную морковь. Каждый слой промазывать майонезом, слои повторять.  Верх слоеного салата с горбушей и грибами украсить размятыми желтками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13069,'Пшеничную муку просеять, перемешать с пищевой содой и специями: имбирем, гвоздикой, корицей, анисом, мускатным орехом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13069,'Сливочное масло комнатной температуры взбить с сахарным песком. Масса должна получиться пышной.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13069,'Вбить яйцо, добавить теплый мед, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13069,'Муку со специями всыпать постепенно, порциями, замесить тесто руками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13069,'Мягкое тесто на несколько часов положить в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13070,'Мягкое сливочное масло нарезать кубиками.','https:https://st.vkuso.ru/data/cache/thumb/26/4a10032278aa826_434x295.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13070,'Всыпать сахар, взбить массу лопаткой или миксером.','https:https://st.vkuso.ru/data/cache/thumb/b6/c452d9339c6bbb6_434x295.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13070,'Добавить сырые куриные яйца, продолжать взбивать.','https:https://st.vkuso.ru/data/cache/thumb/ba/2768fb1385ba9ba_434x295.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13070,'Всыпать муку и быстро замесить тесто.','https:https://st.vkuso.ru/data/cache/thumb/8a/25496643885548a_434x295.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13070,'Выдержать в холодильнике в течение часа, завернуть в пленку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13071,'Нарезать очищенную, помытую и обсшенную картошку крупными дольками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13071,'Добавить нарезанный зелёный лук и выдавить чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13071,'Посыпать любыми сухими травами и посолить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13071,'Полить растительным маслом и все тщательно перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13071,'Посыпать панировочными сухарями и еще раз перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13071,'Запекать в заранее разогретой духовке при 200 С 30-40 мин до готовности и желаемой румяности. Кулинарный канал Розовый баклажан желает Вам Приятного аппетита!',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13072,'Картофель вымыть. Нарезать тонкими кольцами, переложить в миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13072,'Добавить соль, перец, чесночный порошок, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13072,'Влить сливки и растопленное сливочное масло, добавить сыр, хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13072,'Форму смажьте растительным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13072,'Сформируйте "башенки" из картофеля и выложите в форму. Полейте сверху сливками, которые остались на дне миски.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13072,'Выпекать в предварительно разогретой до 190-200°С духовке 45-50 мин. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13073,'Подготовить вырезку молодого барашка: промыть, просушить, убрать пленки и сухожилия. Нарезать мясо квадратными кусочками примерно по 40 гр, переложить в глубокую миску, добавить молотый черный перец, посолить, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13073,'Нарезать мелко репчатый лук, высыпать в мясо, побрызгать  сухим вином (красным), хорошо перемешать, дать чуть постоять. Нанизать не очень плотно на шампуры, обжарить на мангале до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13073,'Этот рецепт сочного шашлыка из баранины по-кавказки рассчитан на мясо молодого барашка. Если не удалось купить такое, то используйте несколько другой вариант рецепта.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13073,'Подготовить баранину для жарки также, но сбрызнуть не вином, а смесью растительного масла с винным уксусом, перемешать, накрыть, мариновать часов 6, а лучше ночь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13073,'Нанизать на шампуры, обжарить над углями, поливая в процессе маринадом. Подавать сочный шашлык из баранины по-кавказски с мясистыми помидорами, большим количеством зелени, перьями зеленого лука, кусочками лимона и красным соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13074,'Просеять пшеничную муку, перемешать с растительным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13074,'Отдельно взбить яйца, влить кефир, добавить пищевую соду, погашенную уксусом, перемешать и всыпать ванильный сахар из пакетика.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13074,'Мучную смесь перемешать с яичной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13074,'Раскатать массу в пласт толщиной полтора сантиметра, вырезать печенье, выпечь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13075,'Муку просеять и посолить.','https:https://st.vkuso.ru/data/cache/thumb/46/da91cf178401c46_434x295.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13075,'Ввести маргарин, порубить ножом на мелкие кусочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13075,'Массу перетереть вилкой.','https:https://st.vkuso.ru/data/cache/thumb/f7/3a74db88a71a3f7_434x295.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13075,'Влить воду, добавить желток.','https:https://st.vkuso.ru/data/cache/thumb/a0/acc93513c2635a0_434x295.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13075,'Тесто должно получиться эластичным.','https:https://st.vkuso.ru/data/cache/thumb/24/f0173cbd3959924_434x295.png',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13076,'Яйца перетереть с сахарным песком, добавить сметану, соль, сливочное масло комнатной температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13076,'Ингредиенты перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13076,'Всыпать пшеничную муку с разрыхлителем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13076,'Замесить тесто при помощи венчика, затем руками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13076,'Масса должна получиться мягкой и не прилипать к рукам.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13077,'Поместить в блендер подмороженное масло.','https:https://st.vkuso.ru/data/cache/thumb/8e/43254085db9e48e_434x295.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13077,'Всыпать пшеничную муку, соль, лимонную кислоту, продукты измельчить в крошку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13077,'Влить ледяную воду, перемешать.','https:https://st.vkuso.ru/data/cache/thumb/55/ea1d0f3429ea155_434x295.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13077,'Готовое тесто завернуть в пленку и положить в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13078,'В ледяную воду всыпать соль, влить растительное масло.','https:https://st.vkuso.ru/data/cache/thumb/38/ec28dc5d646df38_434x295.png',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13078,'Взбить массу при помощи миксера до получения жидкой белой массы.','https:https://st.vkuso.ru/data/cache/thumb/ae/9fb929ecfedabae_434x295.png',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13078,'Всыпать муку.','https:https://st.vkuso.ru/data/cache/thumb/2d/5dd02348cbc7d2d_434x295.png',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13078,'Замесить тесто.','https:https://st.vkuso.ru/data/cache/thumb/c6/a9417043a6676c6_434x295.png',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13079,'Семена льна измельчить при помощи кофемолки или в ступке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13079,'Масса должна выделить масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13079,'Добавить соль и мед, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13079,'Пасту разложить в небольшие банки и убрать в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13079,'Употреблять в пищу можно сразу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13080,'Подготовить рыбу: вымыть, почистить, обсушить, нарезать на куски около 5 см толщиной. Разрезать небольшие луковицы на четвертинки, сложить в глубокую миску, влить растительное масло, добавить чуть приправ, замариновать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13080,'Приготовить из трав, специй и кореньев смесь для маринования. Добавить к смеси лимонный сок, перемешать, натереть куски рыбы. Нашинковать пару луковиц широкими кольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13080,'Переложить стейки в кастрюлю, добавить сметану, нашинкованный лук и маринованный лук, перемешать, закрыть крышкой и на 40 минут оставить в холодильнике промариноваться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13080,'Разложить стейки на решетке, жарить над чуть остывших углях. Блюдо готовится очень быстро. Аппетитный шашлык из сома можно приготовить и на шампурах. Только насаживать рыбу надо сразу на пару шампуров, чтобы не прокручивалась.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13081,'Воду довести до кипения, замочить финики на десять минут, откинуть на дуршлаг и обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13081,'Фундук очистить и раздавить в ступке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13081,'Из фиников вынуть косточки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13081,'Продукт перемолоть блендером или очень мелко нарезать ножом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13081,'Перемешать с орехами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13081,'Всыпать какао-порошок, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13081,'Выложить пасту в чистые емкости, хранить в холодильнике.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13082,'Сырые кунжутные семена всыпать в кофемолку или блендер, добавить растопленное сливочное или оливковое масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13082,'Молоть массу в течение двух или трех минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13082,'Готовый продукт можно посолить, добавить сахар, лимонный сок, мед.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13083,'Тыквенные семена подсушить на сковороде, превратить в муку при помощи блендера или кофемолки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13083,'Влить оливковое масло, перемолоть все вместе в течение минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13083,'В конце приготовления всыпать соль или сахарный песок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13083,'Массу перемешать, разложить в небольшие стеклянные банки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13084,'Орехи очистить, высыпать на сухой противень, поставить в духовой шкаф на десять минут. Температура подсушивания – 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13084,'Высыпать продукт в блендер, добавить соль и натуральный мед.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13084,'Взбивать массу в течение двух минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13165,'Массу разлить в банки, закатать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13084,'В полученную крошку добавить оливковое масло, продолжать измельчать продукты блендером до получения тягучей пасты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13085,'Перемолоть в чаше блендера миндаль и кокосовую стружку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13085,'В пасту добавить сироп агавы, продукты перемешать ложкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13085,'Хранить массу в чистой и сухой банке под крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13086,'Подготовить мясо: промыть, обсушить, порезать на средние (большие не прожарятся, маленькие – пересохнут) куски. Сложить мясо в подходящую посуду, добавить полукольца лука, мелко нашинкованную зелень, поперчить, посолить, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13086,'Почистить киви от кожуры, измельчить на терке или мелко нарезать, добавить к мясу. Тщательно перемешать руками, закрыть крышкой, ждем всего полчаса (не больше).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13086,'Нанизать мясо плотно на шампуры, поджарить на углях. Жарить  шашлык из свинины с луком, зеленью и киви минут  20-30 периодически переворачивая шампуры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13087,'Чашу мультиварки хорошо вымыть, налить кефир, выставить программу «Молочная каша», температура – 80 градусов, время приготовления – десять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13087,'После завершения программы поднять крышку, творог отцедить через марлю или сито.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13088,'Чтобы получить нежный творог кислое молоко в мультиварке нужно подержать в течение часа в режиме подогрева.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13088,'Сыворотку отцедить через марлю.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13088,'Для получения зернистого продукта молоко прогреть в режиме «Каша» или «Мультиповар» в течение десяти минут, температура – 80 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13088,'Полученные хлопья отжать в марле или в тканевом мешочке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13089,'Подготовить мясо: промыть, обсушить, нарезать на средние (с грецкий орех) куски. Переложить мясо в кастрюлю, добавить нашинкованный полукольцами лук, сметану или майонез, пару раздавленных зубков чеснока, приправу к мясу, зелень, влить оливковое масло, всыпать цедру лимона, посолить. Все тщательно перемешать руками, оставить на пару часов, а можно на ночь. Только если мясо будет мариноваться всю ночь, то не надо добавлять цедру лимона.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13089,'Насадить кусочки на деревянные шпажки, сложить шашлычки в трехлитровую банку, предварительно налить на дно жидкий дым и положить 4 зубчика чеснока. Прикрыть банку несколькими слоями фольги и отправить в холодную духовку. Когда духовка разогреется до 200 градусов выдержать 20 минут, а потом увеличить до 250 градусов и готовить шашлык из свинины в духовке в банке еще час. Готовое блюдо переложить на блюдо, подавать с овощами и кетчупом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13090,'Подготовить мясо курицы: вымыть, просушить, нарезать кубиками 3х3. Переложить в кастрюлю, добавить кольца лука, колечки помидора, майонез, немного соевого соуса, специи для шашлыка, жидкий дым, оставить на 2 часа под крышкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13090,'Мясо подсолить, нанизать на шампуры: мясо-помидор-лук и т.д. Установить в аэрогриль чашу с маринадом, сверху положить решетку, а на нее шампуры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13090,'Выставить температурный режим 260 градусов, готовить шашлык из куриного филе в аэрогриле на этом режиме 5 минут. Поменять режим на средний, готовить треть часа. Шашлык подать с овощами и большим количеством зелени.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13091,'Вымыть и обсушить кусок мяса, нарезать на квадратные кусочки, переложить в глубокую миску, добавить базилик, перец, эстрагон, соль, перемешать. Добавить нашинкованный кольцами лук и ломти помидоров, перемешать еще раз. Накрыть миску и отправить ночевать в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13091,'Смешать раздавленный чеснок, выдавить сок из половинки лимона, всыпать чуть перца, перемешать. Когда мясо примет комнатную температуру, нанизать на шампуры перемежая кусочками помидора и лука.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13091,'Заранее подготовить мангал с углями, разложить шампуры и поджарить. Во время жарки шашлык из свинины с луком по-грузински периодически поливать смесью лимонного сока. Подавать блюдо с большим количеством зелени, овощами, красным вином и соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13092,'Помыть крупные шампиньоны, нарезать сало по размеру грибов. Замариновать грибы в масле с соком лимона, приправами, черным перцем, солью, небольшим количеством соевого соуса. Дать постоять несколько часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13100,'Кефир комнатной температуры перемешать с молоком, накрыть мультиварку крышкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13092,'Нанизать грибы на шампуры, чередуя с салом, обжарить шашлык их шампиньонов с салом над углями, как и мясной, степень зажарки смотреть по салу. Готовые грибы можно смазать сливочным маслом. Это блюдо прекрасно дополняет шашлык из мяса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13093,'Нарезать филе курицы на длинные полосы, гармошкой нанизать на вымоченные в воде (30 мин.) шпажки, замариновать в смеси растительного масла, раздавленного чеснока, соевого соуса, кориандра, сахара, перца чили и соли. Миску накрыть и отправить на холод минимум на пару часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13093,'Разогреть духовку до 200 градусов, шашлычки переложить в форму для запекания, блюдо шашлык из куриного филе с чесноком в духовке будет готово через треть часа. За это время шпажки перевернуть один раз на другой бок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13094,'Подготовить печень: помыть, зачистить от пленки, нарезать кусочками по полтора сантиметра, посыпать каждый смесью соли и черного перца, нарезать сало чуть меньшими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13094,'Обжарить чуть-чуть печень в смеси подсолнечного и сливочного масла, нанизать вместе с салом на шампуры',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13094,'Довести шашлык из говяжьей печени с салом до готовности на углях (примерно четверть часа). Подавать блюдо с овощами, красным вином или пивом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13095,'Помыть и почистить рыбу, обсушить, нарезать на стейки, лук нашинковать кольцами. Переложить все в глубокую миску, добавить приправы, поперчить, посолить, залить соком лимона, влить майонез, тщательно перемешать руками, накрыть и убрать на холод на 3 часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13095,'Переложить рыбу на сетку, обжарить шашлык из форели с лимоном и специями над углями около трети часа с обеих сторон. Сочная, золотистая рыбка станет украшением любого пикника, подавать к белому вину и пиву.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13096,'Перемешать в чаше мультиварки ряженку, молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13096,'Прогреть смесь до 80 или 95 градусов, режимы: «Тушение», «Молочная каша», «Подогрев».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13096,'Крышку держать откинутой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13096,'В процессе створаживания добавить соевый соус, корицу, мед, анис.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13096,'Перемешать смесь до растворения меда.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13096,'Мультиварку выключить, подержать продукты под крышкой до остывания.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13096,'Корицу и анис вынуть, творог отжать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13097,'Прогреть простоквашу в мультиварке в режиме «Молочная каша» или «Тушение» в течение десяти или пятнадцати минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13097,'Продукт остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13097,'Нарубить свежую зелень, положить мелко нарезанный свежий или сушеный чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13097,'Соль и перец молотый – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13097,'Готовый продукт перелить в мешочек для отцеживания сыворотки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13098,'Вымыть мясо, обсушить, зачистить от пленок и сухожилий, нарезать одинаковыми кусочками, порезать мелко сало. Кусочков сала должно быть столько же сколько и мяса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13098,'В глубокую миску натереть лук, можно измельчить в блендере, поперчить, посолить, всыпать куркуму, зиру, кориандр, молотый перец, мускатный орех, влить лимонный сок и  буквально чуть-чуть яблочного уксуса, все перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13098,'Переложить в маринад мясо и сало еще раз хорошенько перемешать, прикрыть и убрать на час-два в холодное место.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13098,'Включить на разогрев духовку до 250 градусов. Нанизать кусочки на деревянные шпажки: мясо-сало-мясо и т.д., выстлать на противень пару слоев фольги (матовой стороной вниз), положить несколько кусочков сала.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13098,'Вниз духовки поставить противень с салом, наверх – решетку с шампурами (один раз во время готовки перевернуть). Когда от сала пойдет дымок, то шашлык из свинины можно считать готовым.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13098,'Пока жарится мясо приготовить соус к шашлыку. Нашинковать полукольцами лук, измельчить зелень и лук-порей, всыпать приправы, влить сок лимона и добавить чуть яблочного уксуса. Шашлык из свинины в лимонном соусе в духовке готов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13099,'Перемешать в чаше мультиварки жирное молоко с йогуртом, солью и сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13099,'Выставить режим «Молочная каша» на тридцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13099,'Дуршлаг застелить марлей в несколько слоев, выложить массу, подождать, пока отделится сыворотка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13100,'Влить молоко в емкость мультиварки, выставить режим «Выпечка», прогреть три или четыре минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13100,'Оставить продукт для созревания, время – от десяти до двенадцати часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13100,'Выставить режим «Подогрев» на 120 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13100,'Чашу вынуть из мультиварки и поместить в большой емкости с ледяной водой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13100,'Творог отжать через марлю.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13101,'Рис отварить в течение восьми минут, остудить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13101,'Выложить в емкость фарш из говядины и свинины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13101,'Вбить сырое куриное яйцо, всыпать полуотваренный рис.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13101,'Натереть репчатый лук, пропустить через пресс чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13101,'Продукты соединить, посолить по вкусу, поперчить, еще раз перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13101,'Сформовать шарики, обвалять в муке, обжарить до румянца.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13101,'Еще одну луковицу мелко нарезать, морковь натереть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13101,'Перемешать, заправить сметаной.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13101,'Если масса получилась слишком густой, разбавить водой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13101,'Всыпать специи и соль.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13101,'Поместить тефтели в глубокую сковороду, сотейник.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13101,'Залить овощным соусом, тушить под закрытой крышкой в течение двадцати минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13102,'В глубокую миску налила теплый картофельный отвар, затем добавила соль, сахар, свежие дрожжи, растительное масло, перемешала ложкой ингредиенты между собой. В подготовленную жидкую смесь постепенно добавила просеянную муку. И вымешивала до состояния мягкого, немного липкого теста. Готовое тесто еще вымесила с помощью подсолнечного  масла и поставила в теплое место до увеличения его вдвое.','https://vkuso.ru/data/cache/data/7a/5d3def632ad207a_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13102,'Пока тесто поднималось, сделала начинку. Нарезала не жирную свинину, тонкими полосками. Не крупный репчатый лук порезала тонко, полукольцами. Картофель порезала соломкой. Для удобства смешала только мясо с луком, вместе с картофелем не смешивала специально, так количество картошки и мясо в одинаковых пропорциях проще регулировать. Добавила соль и перец по вкусу. Начинка готова.','https://vkuso.ru/data/cache/data/54/34ce6156e7ade54_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13102,'Когда тесто вдвое увеличилось в объеме, приступила к формированию пирожков.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13102,'Треугольники перед выпечкой ничем не смазывала. Выпекала в предварительно разогретой до 180° духовке приблизительно минут 40 до готовности.','https://vkuso.ru/data/cache/data/ae/b06b1b8b8defaae_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13102,'После выпечки, еще горячие эчпочмаки смазала сливочным маслом. Когда пирожки немного остыли, мы благополучно их всей семьей съели.','https://vkuso.ru/data/cache/data/04/0218ff91521f104_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13102,'Надеюсь, Вам понравятся. Приятного аппетита!','https://vkuso.ru/data/cache/data/4d/b5d250f930bba4d_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13103,'Подготовить и нарезать мясо на одинаковые куски, лук нарезать на полукольца. Переложить мясо в хорошо нагретый на сковороде жир или растительное масло, прикрыть крышкой, чтобы мясо дало сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13103,'Тушить 5 минут на среднем огне, убавить нагрев, прикрыть крышкой и тушить еще около 10 минут, посолить, добавить молотый перец, если мясо жестковатое, то влить  чуть воды и дотушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13103,'После выпаривания всей воды добавить жир и довести кусочки до золотистой корочки. Залить мясо белым вином, тушить 10 минут, прикрыть крышкой, убавить огонь и готовить пока вино полностью не выпариться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13103,'Всыпать в сковороду лук, размешать, добавить приправы, посолить, поперчить, добавить нагрев, тушить пока лук не зарумянится.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13103,'Готовый шашлык из свинины в белом вине на сковороде дополнить порезанными помидорами и огурцами, украсить веточками петрушки и кольцами лука.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13104,'В куриный фарш добавить очень мелко нарезанный репчатый лук, яйцо, панировочные сухари , посолить и поперчить по вкусу, все хорошо перемешать. Сформировать из фарша шарики, выложить в смазанную растительным маслом форму для запекания, сделать в фарше углубления донышком обычного стакана.','https://vkuso.ru/data/cache/data/95/2fd38820153a295_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13116,'Помидоры превратить в пюре, перемешать со сливами и довести массу до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13104,'На растительном масле обжарить мелко нарезанные шампиньоны с репчатым луком. Жарить на сильном огне около 2 мин. помешивая. Добавить в грибы сметану, посолить и поперчить по вкусу, хорошо перемешать и снять с огня.','https://vkuso.ru/data/cache/data/45/3fcba7b3c989445_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13104,'В углубления в фарше разложить 1/3 от всего количества мелко натертого сыра.','https://vkuso.ru/data/cache/data/ca/86eea267c35d4ca_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13104,'Затем сверху выложить грибную начинку.','https://vkuso.ru/data/cache/data/a4/bce7decb31368a4_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13104,'Поставить гнезда в заранее разогретую духовку на 30-35 мин. Запекать при 200 С.','https://vkuso.ru/data/cache/data/09/d85c3f2eb39f709_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13104,'Вынуть гнезда из духовки, посыпать каждую котлетку сверху оставшимся сыром','https://vkuso.ru/data/cache/data/bb/0b1b4160085debb_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13104,'Запекать еще 5-10 мин до расплавления и легкого подрумянивания сыра.','https://vkuso.ru/data/cache/data/1a/add104acaaf6e1a_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13104,'На готовые еще горячие гнезда выдавить чеснок (по желанию).','https://vkuso.ru/data/cache/data/2f/9b9024f9655a52f_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13104,'Посыпать зеленым луком (по желанию).','https://vkuso.ru/data/cache/data/1a/7d781701996081a_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13104,'Подавать как теплую закуску или как самостоятельное горячее блюдо.','https://vkuso.ru/data/cache/data/02/afc64488cfdf502_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13105,'Нарезать подготовленную печень на куски, замочить в молоке, посолить, добавить специи, поперчить, шпик нарезать на кусочки, лук нашинковать на кольца.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13105,'Нанизать печень на шампуры, чередуя с луком и шпиком. Обжарить шашлык из свиной печени со шпиком над углями до готовности и сразу в горячем виде подать к столу со свежей зеленью, овощами и холодным светлым пивом (для любителей).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13106,'Отварить рис в течение десяти минут, остудить. Продукт должен быть полуготовым.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13106,'Вымешать фарш и свинины и говядины, добавить рис, соль, приправы, мелко нарезанную луковицу, вбить сырое куриное яйцо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13106,'Слепить шарики, обвалять в пшеничной муке и обжарить на сковороде до появления корочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13106,'Снять с огня.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13106,'Спассеровать натертую морковь с нарезанным репчатым луком до золотого оттенка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13106,'Влить томатную пасту, давленый чеснок, любые специи, можно использовать сушеный базилик.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13106,'Влить немного воды и посолить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13106,'Время приготовления подливы – двенадцать минут, огонь – небольшой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13106,'Поставить сковороду с тефтелями на плиту, полить томатным соусом, потушить на небольшом огне в течение двадцати минут под крышкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13106,'Горячее блюдо украсить листочками свежей петрушки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13107,'Отварить рис в течение двенадцати минут. Продукт должен получиться полусырым.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13107,'Измельчить при помощи блендера шампиньоны.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13107,'Сыр мелко натереть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13107,'Пропустить через мясорубку лук и куриное мясо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13107,'Добавить давленый чеснок, вбить сырое яйцо, положить рис, грибы, сыр, рубленую зелень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13107,'Ингредиенты хорошо перемешать, посолить, всыпать специи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13107,'Отдельно приготовить подливу из сметаны, томатной пасты, воды.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13107,'Смесь посолить и поперчить, хорошо перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13107,'Форму для запекания застелить бумагой для выпекания или смазать маслом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13107,'Сформовать шарики из основной массы, выложить в форму, влить соус.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13107,'Емкость затянуть фольгой или закрыть крышкой, подержать в духовом шкафу в течение часа.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13107,'Температура приготовления – 180 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13108,'Фарш из говядины перемешать с полуотваренным рисом, сырым яйцом, перцем, солью, тертым луком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13108,'Массу вымесить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13108,'Сформовать мясные шарики, обвалять в муке, обжарить на сковороде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13108,'Растопить на другой сковороде сливочное масло, всыпать муку, смесь непрерывно помешивать в течение пятнадцати секунд.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13108,'Влить любой мясной бульон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13108,'Смесь довести до кипения, добавить сливки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13108,'Подержать на огне, посолить, поперчить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13108,'Поставить емкость с тефтелями на тихий огонь, влить сливочный соус, тушить двадцать минут под крышкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13109,'Выбрать свежую (иначе шашлык будет жесткий) печень, промыть, нарезать на большие ломти, переложить в глубокую миску, посолить и залить сметаной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13109,'Дать настояться минут 40, выложить на сетку или насадить на шампуры, держать над углями (без открытого огня) по 3-4 минуты с каждой стороны. Нельзя передерживать, иначе шашлык из свежей говяжьей печени будет безвозвратно испорчен.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13110,'Пропустить через мясорубку мясо, лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13110,'Вбить сырое яйцо, добавить сырой рис, приправы, соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13110,'Ингредиенты перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13110,'Вторую луковицу мелко нарезать, морковь натереть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13110,'Влить растительное масло в чашу мультиварки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13110,'Выложить овощи, выставить режим «Жарка» на пятнадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13110,'Перемешать томатную пасту с овощами, жарить три минуты, добавить сметану.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13110,'Продукты перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13110,'Сформовать из фарша небольшие тефтели, выложить в чашу мультиварки, влить подливу на половину высоты шариков.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13110,'Соль и перец – по вкусу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13110,'Выставить режим «Тушение» на сорок минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13111,'Рис отварить в течение двенадцати минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13111,'Пропустить через мясорубку лук и морскую рыбу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13111,'В массу вбить сырое яйцо, выложить рис, посолить и поперчить, добавить приправы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13111,'Фарш вымесить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13111,'Сформовать шарики, выложить на сковороду, обжарить до получения корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13111,'Вторую луковицу нарезать, натереть морковь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13111,'К овощам влить немного воды, добавить томатную пасту и сметану, специи, соль.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13111,'Соус хорошо перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13111,'Поместить тефтели в кастрюлю, влить соус, потушить в течение десяти или двенадцати минут под крышкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13112,'Плоды разморозить, перебрать, удалить хвостики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13112,'Промыть продукт теплой водой, откинуть ягоды на дуршлаг.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13112,'Измельчить плоды толкушкой или при помощи блендера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13112,'Протереть массу через сито или отжать через несколько слоев марли.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13112,'Жмых выложить в кастрюлю, влить воду, поставить на плиту, огонь – сильный.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13112,'Довести до кипения, через минуту кастрюлю снять с огня.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13112,'Пюре еще раз процедить, добавить сахарный песок, хорошо перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13112,'В остывший отвар добавить клюквенный сок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13113,'Ягоды хорошо промыть, размять миксером или вручную.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13113,'Отжать сок через марлю или сито.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13113,'Мезгу залить водой, поставить на огонь и довести до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13113,'Время варки – три минуты, огонь погасить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13113,'Отвар процедить, остудить, влить сок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13113,'Мед перемешать, он должен раствориться полностью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13114,'Свежие или размороженные ягоды перебрать, размять до состояния пюре при помощи блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13114,'Кашицу процедить, слить сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13114,'Протереть мезгу через марлю.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13114,'Всыпать сахарный песок, влить воду, прогреть на огне до кипения, варить две минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13114,'Отвар остудить, влить сок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13115,'Промыть тушку, обсушить, нарубить на куски, переложить в подходящую емкость, всыпать приправы для шашлыка, соль и перец, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13115,'Порезать лук на полукольца, добавить к мясу, хорошо, сжимая пальцами содержимое, перемешать руками, оставить мариноваться не менее 4 часов, а лучше дать переночевать в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13115,'Подготовить угли, нанизать куски кролика на шампуры, обжарить в течение получаса до приятной глазу корочки. Переложить шашлык из кролика с луком на блюдо и подать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13116,'У спелых томатов удалить плодоножки, плод разрезать на четыре части, залить водой, поставить на плиту.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13116,'Довести до кипения, огонь убавить, время тушения – полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13116,'Чеснок очистить и пропустить через мясорубку вместе с перцем чили, сливами без косточек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13116,'Добавить соль, винный, яблочный или виноградный уксус, кориандр, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13166,'Ягоды разморозить, удалить косточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13116,'Стерилизовать небольшие банки, разложить соус, закатать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13117,'Сливы очистить от косточек, перемешать с кориандром, хмели-сунели, солью, сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13117,'Варить до нужной густоты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13117,'Добавить давленый чеснок, гранатовый сок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13117,'Массу перемешать, тушить пять минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13117,'Разлить в стерильные банки, укупорить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13118,'Чернослив без косточек промыть, залить водой, поставить на плиту, довести до кипения, варить пять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13118,'Массу остудить, три четверти отвара отлить в другую емкость.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13118,'Оставшуюся массу превратить в пюре при помощи блендера, протереть через сито.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13118,'Отвар добавить по необходимости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13118,'Всыпать хмели-сунели, соль, давленый чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13118,'Соус перемешать, кипятить десять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13118,'Разлить в чистые, стерильные банки, закатать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13119,'Говяжьи кости и мясо вымыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13119,'Мякоть нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13119,'Кости выложить на противень, печь при температуре в двести градусов, время – один час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13119,'Продукт вынуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13119,'Поставить в духовой шкаф мясо в миске на пятнадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13119,'Вынуть, сок слить, мясо положить в холод.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13119,'Вымыть овощи, очистить и нарезать крупными кусочками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13119,'Репчатый лук и морковь обжарить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13119,'В другую сковороду влить мясной сок, положить нарезанный баклажан, кабачок, сельдерей, болгарский перец.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13119,'Кости выложить на противень с бортиками, сверху – все овощи, влить красное вино.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13119,'Тушить полчаса.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13119,'Переложить продукты в кастрюлю.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13119,'Поставить емкость с крышкой на тихий огонь на сутки.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13119,'Снять с огня, кости вынуть, соус процедить.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13119,'Мясо из холодильника обжарить и положить в основную массу.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13119,'Добавить специи: гвоздику, лавровый лист, душистый и черный перец, укроп, чеснок, петрушку, розмарин, тимьян.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13119,'Томить соус еще два часа.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13119,'Влить томатный соус с вином.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13119,'Лавровый лист вынуть.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13119,'Посолить по вкусу, всыпать сахарный песок.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13119,'Массу тушить еще два с половиной часа.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13120,'Подготовить кусок свинины (лучше шейную часть), обмыть, обсушить, нарезать на средние куски, переложить в подходящую по объему кастрюлю, добавить толстые кольца лука.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13120,'Всыпать любимые специи, молотый черный перец, соль, лист лаврушки, перемешать, залить чуть кисловатым кефиром, накрыть мясо тарелкой и поставить на нее груз, оставить до утра в холодильнике (можно и на 4 часа).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13120,'Подготовить угли, насадить маринованный куски мяса на шампуры, обжаривать шашлык из свинины с луком в кефире полчаса над раскаленными углями. Маринованный лук для блюда можно обжарить отдельно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13121,'Крепкий говяжий бульон разделить пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13121,'Очистить лук, морковь и сельдерей, мелко нарезать, обжарить на растительном масле.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13121,'Влить томатный соус, все вместе тушить пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13121,'Овощи залить частью бульона, всыпать специи, травы, их лучше поместить в мешочке из марли.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13121,'Варить полчаса на тихом огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13121,'Мешочек выбросить, массу тушить еще полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13121,'Готовый соус процедить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13121,'Растопить сливочное масло, обжарить муку, влить еще часть бульона, растереть, прогревать соус до густоты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13121,'Перелить в кастрюлю с бульоном.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13121,'Влить красное вино, можно использовать домашний продукт.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13121,'Поставить кастрюлю на огонь, варить массу до густоты, помешивать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13121,'Соль и сахарный песок добавить в конце варки.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13122,'Крылышки, спинку шейку промыть, обвалять в сухом молоке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13122,'Крупно нарезать лук и морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13122,'Сложить крылья на противень в один слой, добавить овощи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13122,'Поставить продукты на час в духовой шкаф.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13122,'В конце приготовления можно включить функцию гриля.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13122,'Ингредиенты переложить в большую кастрюлю, влить воду.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13122,'Довести до кипения, тушить под крышкой четыре часа, огонь – минимальный.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13122,'Кости вынуть из бульона, жидкость процедить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13122,'Бульон выпарить до нужного объема и охладить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13123,'Репчатый лук мелко нарезать, натереть морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13123,'Овощи переложить в чашу мультиварки, влить растительное масло.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13123,'Выставить режим тушения на десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13123,'Субпродукт промыть, удалить пленку, печенки разрезать пополам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13123,'Добавить к овощной смеси, влить воду, перемешать, тушить под крышкой в течение получаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13123,'Соль и перец всыпать за десять минут до окончания приготовления, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13123,'Дать блюду постоять, разложить в тарелки и украсить любой зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13124,'Печень вымочить, удалить пленки, нарезать кусочками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13124,'Субпродукт обвалять в муке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13124,'Репчатый лук очистить и нарезать четвертинками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13124,'Выложить на дно чаши, выставить режим «Жарка», пассеровать на растительном масле в течение пяти минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13124,'Обжарку помешивать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13124,'Добавить печень, перемешать, жарить четыре или пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13124,'Влить теплую воду, всыпать молотый черный перец, соль.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13124,'Перемешать и блюдо тушить под крышкой в течение двадцати минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13125,'Подготовить рыбу, разделать семгу на филе, нарезать на небольшие квадратики (2х2 см), посолить, поперчить. Лимон порезать на колечки, а потом каждое разрезать на 4 части. Включить на разогрев духовку до 200 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13125,'Кусочки рыбы нанизать на шпажки чередуя с четвертинками лимона, побрызгать маслом, переложить в лоток для запекания, поставить запекаться. Домашний шашлык из семги с лимоном будет готов через треть часа. Выложить широкое блюдо листьями салата, переложить шпажки на блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13125,'Если жарить шашлык на углях, то шпажки надо сначала замочить на полчаса в воде. А к нарезанной семге добавить кольца репчатого лука, овощей (болгарский перец) и лимонный сок, обжарить на сетке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13126,'Репчатый лук мелко нарезать, переложить в чашу с растительным маслом, выставить режим «Жарка» на двадцать пять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13126,'Говяжью печень нарезать кусочками, добавить в обжарку, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13126,'Время приготовления – двадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13126,'Всыпать перец, влить воду и сметану.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13126,'Перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13126,'Всыпать муку, еще раз перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13126,'Можно обойтись без муки, если сметана достаточно густая.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13126,'Выставить режим тушения на сорок минут, готовить под крышкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13126,'Готовое блюдо посолить, перемешать, дать постоять.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13127,'Перебрать гречневую крупу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13127,'Выставить режим «Жарка», подержать крупу в сухой чаше мультиварки в течение пяти минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13127,'Пересыпать продукт в отдельную емкость.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13127,'Говяжью или телячью печень вымочить, удалить пленки, желчные протоки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13127,'Продукт нарезать кусочками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13127,'Прогреть в мультиварке растительное масло, добавить лук, печень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13127,'Продукты перемешать, готовить под крышкой в режиме «Жарка» в течение пятнадцати минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13127,'Всыпать перец и соль, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13127,'Добавить сметану и опять перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13127,'Крупу промыть несколько раз, пересыпать к основной массе в мультиварке.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13127,'Выставить режим «Рис», «Гречка» или «Плов». Если таких режимов нет – просто потушить блюдо в течение сорока минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13128,'Куриную печень и морковь перемолоть с помощью блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13128,'Добавить в массу зелень, сырые яйца, соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13128,'Массу взбить при помощи вилки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13128,'Добавить овсяные хлопья, влить молоко, хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13128,'Перелить смесь в смазанные маслом силиконовые формы небольшого размера, запечь на пару.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13128,'Влить воду в чашу мультиварки, выставить режим «Пароварка» на полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13128,'Вынуть суфле из форм, полить сметаной и посыпать зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13129,'Свиную печень промыть, нарезать длинными кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13129,'Репчатый лук очистить и нарезать полукольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13129,'Выставить таймер на двадцать минут в режим «Жарка».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13129,'Влить масло в чашу мультиварки, прогревать лук до прозрачного состояния четыре минуты, без крышки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13129,'Кусочки печени обвалять в муке, переложить в луковую массу, перемешать, жарить в течение пяти минут без крышки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13129,'Всыпать кунжутное семя, тмин, перемешать еще раз и потушить под крышкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13129,'Раздавить чеснок при помощи пресса, перемешать с густой сметаной.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13129,'За несколько минут до готовности блюда всыпать перец и соль, влить сметану с чесноком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13129,'Ингредиенты перемешать, кушанье подержать под крышкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13130,'Печень вымочить в воде или в молоке, снять пленки, разрезать на небольшие кусочки и выложить в емкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13130,'Нарезать репчатый лук кольцами, добавить в мясо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13130,'Влить оливковое масло, всыпать паприку, орегано, майоран, лавровый лист, черный перец-горошек, соль, хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13130,'Выставить режим тушения на полтора часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13131,'Мякоть баранины промыть, обсушить, нарезать на кусочки (примерно3х3 см), насадить без зазоров на шампур, присыпать черным перцем и солью, включить на разогрев духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13131,'Когда температура будет 170-180 градусов можно закладывать мясо. Шампуры упаковать в рукав так, чтобы они лежали на расстоянии друг от друга. Готовить в таком режиме минут 10, мясо должно побелеть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13131,'Рукав развязать и снять, выставить нагрев в духовке в режим гриля и разложить шампуры на самую верхнюю полочку, установить под ними противень черного цвета, готовить около трети часа, за это время мясо перевернуть 2-3 раза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13131,'Шашлык из баранины в духовке в рукаве должен покрыться румяной, радующей глаз корочкой. Подавать к столу с салом, ломтиками лимона, петрушкой, базиликом и овощами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13132,'Куриную печень вымочить и переложить в чашу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13132,'Нарезать мелкими кубиками болгарский перец и лук, натереть или нарезать соломкой морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13132,'Влить растительное масло, выставить режим «Жарка» на пятнадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13132,'Очистить картофель, нарезать кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13132,'После окончания приготовления содержимое чаши перемешать, всыпать картофель.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13132,'Добавить по вкусу соль, перец, лавровый лист.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13132,'Влить немного горячей воды, выставить режим «Тушение» на пятьдесят минут, готовить под крышкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13133,'Репчатый лук нарезать кубиками, морковь натереть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13133,'Влить растительное масло, выставить режим «Жарка», всыпать овощи, готовить десять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13133,'Переложить в миску.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13133,'Говяжью печень очистить, нарезать кубиками, посолить и поперчить, выложить в чашу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13133,'Сверху – овощная обжарка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13133,'Влить немного воды, поставить силиконовую чашу с продуктами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13133,'Выставить режим «Пароварка» на сорок минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13133,'Готовить под крышкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13134,'Печень вымыть, нарезать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13134,'В чашу влить масло, выложить субпродукт, жарить десять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13134,'Нарезать любые грибы, выложить на сухую сковороду, тушить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13134,'Репчатый лук нарезать полукольцами, добавить к грибам после того, как из них выпарится лишняя влага.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13134,'Влить масло, спассеровать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13134,'Обжарку переложить к печени.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13134,'Приготовить соус из сметаны с мукой, томатной пасты, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13134,'Соус перелить в мультиварку, влить воду, соль – по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13134,'Тушить под крышкой в течение получаса.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13135,'Кишки очистить, промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13135,'Замочить в соленой воде на час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13135,'Удалить шкурку, сало нарезать кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13135,'Свиное мясо очистить от прожилок, нарезать кубиками два на два сантиметра.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13180,'Вымыть и пропарить банки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13135,'Перемешать мясо с салом, чесноком, кориандром, сушеным базиликом, тимьяном, молотым перцем, солью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13135,'Влить коньяк.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13135,'Начинить кишки столовой ложкой, концы завязать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13135,'Положить в морозилку на четыре часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13135,'Проколоть колбасу в нескольких местах.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13135,'Довести воду в кастрюле до кипения, всыпать соль.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13135,'Варить колбасу в течение часа, огонь – слабый.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13135,'Продукт отправить в духовой шкаф, противень смазать растительным маслом. Время запекания – сорок минут, колбасу несколько раз перевернуть.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13136,'Подготовит кусок свинины: вымыть, зачистить от пленок, промокнуть бумажным полотенцем, нарезать одинаковыми кусочками. Засыпать зерна граната в пакет, выпустить воздух, тщательно завязать пакет и прокатать скалкой, процедить полученный сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13136,'Сложить мясо в кастрюлю, залить соком и как следует перемешать, всыпать черный перец, смесь итальянских трав, мускатный орех, порубленный чеснок. Тщательно перемешать руками, прикрыть крышкой и отправить на час в холодильник. Замочить деревянные шпажки в воде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13136,'Мясо насадить (не плотно) на шпажки, обжарить на сковороде в сильно разогретом масле со всех сторон до всеми любимой корочки. Включить на разогрев духовку (200 градусов).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13136,'Застелить противень фольгой, положить шпажки, аккуратно свернуть в герметичный пакет, поставить на полчаса в духовку, разрезать пакет сверху и осторожно снять фольгу, запекать шашлык из свинины с гранатовым соком в духовке еще минут 10 в режиме гриль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13137,'Выпотрошить тушку нутрии, удалить подкожный жир. Обязательно убрать в районе 4 шейного и 6 грудного позвонков спинные железы. Иначе у мяса будет стойкий мускусный запах, но некоторым гурманам он нравится.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13137,'Нарезать мясо на куски (молодую нутрию можно резать более крупными кусками), промыть, переложить в подходящую кастрюлю. Нарезать довольно крупно лук, слегка подавить руками и засыпать в мясо, перемешать. Чем больше будет лука, тем сочнее получится мясо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13137,'Взбить вино и растительное масло, всыпать специи (соль добавлять не надо), размешать и вылить в мясо, еще раз перемешать, накрыть и убрать на холод минимум на 3, а можно и на 12 часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13137,'Достать мясо, перемешать, сцедить маринад, подогреть его до 50 градусов, посолить. Вид у жидкости не очень презентабельный, но если при жарке этим маринадом поливать шашлык из нутрии со специями, то мясо будет с хрустящей, но не сухой корочкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13137,'Нанизать куски нутрии на шампуры, между ними разместить небольшие помидоры, жарить до готовности над углями. Если подбрасывать периодически сырые веточки от фруктовых деревьев, то блюдо приобретет аромат копченого мяса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13138,'Нарезать репчатый лук полукольцами, переложить в глубокую посуду, влить коньяк, растительное масло, боржоми, лимонный сок, всыпать смесь пряных трав, все перемешать, положить в маринад целый кусок мяса, отправить ночевать в холодильник. Если нет времени, то выдержать в маринаде можно только 4 часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13138,'Насадить кусок на шампур вместе с овощами, завернуть в сетку из внутреннего жира. Жарить шашлык по-карски из свинины в мангале над углями минут 25-30. Блюдо можно готовить из любого мяса и птицы, соблюдая главное условие: мариновать и жарить мясо надо одним куском.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13139,'Вымыть говяжий язык, отварить в чуть подсоленной воде, дать чуть остыть, очистить от кожи, нарезать на средние кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13139,'Переложить язык в глубокую миску, добавить порезанный дольками лимон, специи, соль, влить масло, перемешать, накрыть миску пленкой, отставить на час. Помыть и нарезать сладкий перец и помидоры, лук нашинковать кольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13139,'Язык нанизать поочередно с овощами на шампуры. Жарить домашний шашлык из говяжьего языка до готовности над углями в мангале, но можно готовить блюдо и в разогретой до 200 градусов духовке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13140,'Нашинковать капусту, натереть морковь на крупной терке, нарезать репчатый лук. Все обжарить на растительном масле на среднем огне около 10 мин помешивая. Посолить и поперчить по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13140,'Нарезать сосиски кружочками и добавить к капусте. Все перемешать, через 1 мин снять с огня и дать немного остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13140,'В отдельной посуде смешать яйца, сметану, майонез, разрыхлитель, соль и перец. Взбить до однородности около 1 мин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13140,'Просеять в смесь муку и еще раз слегка взбить до однородности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13140,'В тесто выложить начинку и хорошо перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13140,'Смазать форму для запекания (диаметр 20 см) растительным маслом, выложить в нее готовое тесто, смешанное с начинкой. Потрясти форму, чтобы выровнять поверхность.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13140,'Запекать пирог в разогретой до 180 градусов духовке 40 минут до готовности и подрумянивания. Готовность проверить зубочисткой. При протыкании пирога зубочистка должна оставаться сухой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13140,'Вынимать пирог из формы после легкого остывания, способом переворачивания на 2 тарелки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13141,'Разрубить перепелов на куски (можно готовить и целыми), сложить в глубокую посуду. Приготовить маринад из апельсинового и лимонного соков, соевого соуса с добавлением цедры лимона, красного и душистого перцев, тертого корня имбиря и меда.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13141,'Залить маринадом перепелов, оставить на пару часов. Нанизать куски тушки на шампуры, присыпать зирой или тмином. Обжарить оригинальный шашлык из перепелов в мангале над углями, блюдо будет готово примерно через полчаса. Во время жарки шампура несколько раз перевернуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13142,'Заварить крепкий чай, дать остыть. Подготовить печень: очистить, помыть, порезать на равные кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13142,'Переложить печень в подходящую по объему посуду, поперчить, всыпать зиру, соль, кориандр (часть зерен раздавить), перемешать, залить заваркой, отставить на час в сторону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13142,'Насадить печень на деревянные шпажки, обжарить 15 минут на гриле. Если шашлык из куриной печени в чайном маринаде будет жариться на углях, то шпажки нужно будет подержать около часа в воде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13143,'Подогреем молоко до 35-37 градусов и выльем его в емкость, в которой будем замешивать тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13143,'Раскрошим в него дрожжи и добавим сахар, примерно 70-80 г. Хорошо перемешаем венчиком и добавим просеянную муку, доводим до состояния редкой сметаны. Перемешаем и поставим опару в теплое место.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13143,'Она должна подняться и начать оседать, тогда замешиваем дрожжевое тесто. Вливаем в опару чуть теплое растопленное масло, размешиваем венчиком яйца с оставшимся сахаром и также вводим в опару.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13143,'Частями начинаем добавлять просеянную муку и замешивать тесто, вначале ложкой, а затем руками, смазанными растительным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13143,'Тесто накрываем сухим полотенцем и ставим в теплое место на расстойку, примерно на 1 час. Затем тесто обминаем и снова даем ему подойти минут 30-40.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13143,'После этого формируем шарики и выкладываем их на лист для выпечки на расстоянии друг от друга. Даем им постоять в теплом месте минут 20 и делаем рюмочкой или любым другим способом углубления в центре для начинки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13143,'Готовим начинку: в емкость помещаем творог, сахар, яйцо, муку и измельчаем блендером до однородного состояния.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13143,'В каждое углубление помещаем творожную начинку и смазываем ватрушки взбитым яйцом и снова даем ватрушкам постоять минут 15-20.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13143,'Помещаем в разогретую духовку на 190 градусов примерно на 20-25 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13144,'Нарезать картошку и лук кубиками и слегка поджарить на растительном масле на сильном огне около 2 мин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13144,'Куриный фарш также слегка поджарить на растительном масле около 1 мин и добавить к картошке. Посолить и поперчить по вкусу, все перемешать и дать немного остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13144,'В отдельной посуде смешать яйца, кефир, разрыхлитель, соль и перец. Взбить венчиком до однородности около 1 мин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13144,'Просеять в жидкую смесь яиц и кефира муку и еще раз слегка взбить венчиком до однородности и растворения комочков около 1 мин.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13144,'В тесто выложить всю начинку и перемешать ложкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13144,'Смазать форму для запекания растительным маслом (в рецепте используется две прямоугольных формы, можно использовать любую форму по желанию), залить тестом с начинкой, розровнять ложкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13151,'На середину подготовленного слоеного теста укладываем 1 ч.л джема и сверху укладываем банан.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13144,'Запекать пирог 45-50 мин при 180 С до готовности и желаемой румяности. При желании за 1 мин. до готовности можно включить режим верхнего гриля, чтобы получить поджаристую корочку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13144,'Пироги слегка остудить и извлечь из формы любым способом (в рецепте показан способ переворачивания с двумя тарелками).',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13145,'Соединим фарш со специями. Добавим 3 столовых ложки панировочных сухарей, 2 яйца. Можно добавить зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13145,'Сформируйте на ладони лепёшку из фарша, в центр положите перепелиное яйцо отварное.  А затем скатайте шар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13145,'Каждое яйцо по-шотландски обваляйте сначала в панировочных сухарях, а затем окуните во взбитое  яйцо. Обваляйте в муке, снова окуните в яйцо. Снова обваляйте в панировочных сухарях. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13145,'Жарьте яйца по-шотландски во фритюре до золотистой корочки, а затем выложите на бумажное полотенце.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13146,'Смешать для маринада масло, с раздавленным чесноком, базиликом, розмарином, майораном, солью и петрушкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13146,'Куриные ножки проколоть вилкой в нескольких местах, залить маринадом, оставить на ночь в холоде (минимум на 2 часа).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13146,'Установить в микроволновку высокую решетку, а под нее миску с водой в которую всыпать розмарин. Переложить на решетку ножки, выставить режим гриль шашлык из куриных ножек в микроволновке будет готов через 25 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13147,'Помыть и обсушить крылышки, переложить в глубокий лоток. Мелко порезать помидоры (шкурку снять), болгарский сладкий перец, лук, зелень, всыпать к овощам корицу и кориандр, влить соевый соус и майонез, все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13147,'Попробовать маринад, если не достаточно соленого вкуса соевого соуса, то еще чуть подсолить, вылить в крылышки, смешать руками, закрыть лоток, оставить мариноваться на 2 часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13147,'Разложить крылышки на решетке, поджарить над углями, решетку периодически переворачивать. Пикантный шашлык из куриных крылышек будет готов через полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13148,'Куриное мясо пропустить через мясорубку или перемолоть в блендере.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13148,'Вбить сырое яйцо, влить молоко, посолить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13148,'Отварить морковь, нарезать кубиками небольшого размера, покрошить чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13148,'Использовать формы для колбасы или упаковку из-под молока.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13148,'Выложить фарш, второй слой – чеснок и морковь, третий – фарш.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13148,'Наполнить форму доверху, обернуть пленкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13148,'Налить воду в кастрюлю, поставить на газ, довести до кипения, поставить форму, если она картонная – в нее не должна попасть вода.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13148,'Варить в течение часа под крышкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13148,'Остудить, снять форму.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13149,'Говядину промыть, удалить кости.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13149,'Мясо нарезать кубиками и пропустить через мясорубку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13149,'Мелко нарезать свиное сало, соединить оба продукта в мясорубке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13149,'Всыпать пряности: базилик, кориандр, красный перец, имбирь, соль – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13149,'Добавить давленый чеснок, молотый мускатный орех.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13149,'Ингредиенты перемешать, по желанию подлить молоко или воду.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13149,'Кишки промыть, набить фаршем, перевязать веревочкой концы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13149,'Положить колбасу в холодильник на пять часов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13149,'Затем запечь продукт в духовом шкафу, в оболочке сделать несколько отверстий иглой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13150,'Свинину очистить от костей и пленок, перемолоть в блендере вместе с луком и чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13150,'Вбить сырое яйцо, добавить желатин и специи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13150,'Массу перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13150,'Наполнить фаршем пакет для запекания или специальные формочки, натуральные кишки, хорошо промытые и обработанные.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13150,'Концы перевязать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13150,'Варить колбасу на среднем огне в течение двух часов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13151,'Банан чистим и нарезаем, перекладываем на тарелку и убираем в сторону.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13151,'Яйцо взбиваем с добавлением воды, также убираем в сторону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13151,'Слоеное тесто раскатываем тонко, нарезаем на равные части (квадраты).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13165,'Выставить режим «Тушение» на час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13151,'По краям смазываем взбитым куриным яйцом с водой, заворачиваем и защиплем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13151,'Перекладываем на противень и отправляем в духовке при 180С до готовности 15-25 минут. Все готово)',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13152,'Легкие, печень, сердце промыть проточной водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13152,'Нарезать субпродукты кусочками, положить в кастрюлю, варить в течение часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13152,'Нашинковать печень и сало, пропустить через мясорубку вместе с чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13152,'Другой вариант: лук с салом и растительным маслом обжарить на сковороде. Оставшиеся субпродукты также пропустить через мясорубку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13152,'Ингредиенты соединить, влить сливки, всыпать пряности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13152,'Начинить кишку готовым фаршем, концы перевязать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13152,'Варить сорок минут, оболочку наколоть иглой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13153,'Куриное филе нарезать тонкими ломтиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13153,'Посыпать перцем, кориандром, перцем, нарезанным чесноком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13153,'Продукты перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13153,'Обработать кишки, начинить их фаршем, связать колбасу кольцами, положить в морозилку на два часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13153,'Для вяления развесить продукт в проветриваемом прохладном помещении.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13153,'На ночь колбасу лучше перекладывать в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13153,'Время сушки – две недели.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13154,'Свиное мясо и сало вымыть, нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13154,'Отдельно взбить сырые куриные яйца, всыпать соль, крахмал, чеснок и перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13154,'Массу перемешать, в ней не должно быть комочков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13154,'Фарш выложить на фольгу, свернуть в виде колбасы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13154,'Выложить колбаски на противень, время приготовления – один час, температура – 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13154,'Готовую колбасу освободить от фольги, нарезать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13155,'Говядину нарезать крупными кусками по сто грамм, засыпать солью, оставить на сутки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13155,'Продукт вымочить в течение двух часов, воду менять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13155,'Куски повесить на нитках для просушки на два или три часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13155,'Пропустить мясо через мясорубку вместе с чесноком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13155,'Всыпать зиру, острый черный молотый перец, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13155,'Чистые бараньи кишки начинить фаршем, через тридцать сантиметров перекручивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13155,'Положить кишку под пресс на сутки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13155,'Пресс снять, наколоть кишки иглой там, где образовались пузыри.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13155,'Подвесить суджук в тени, в проветриваемом помещении.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13155,'Температура сушки – до 25 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13155,'Перед подачей суджук нарезать, оболочку снять.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13156,'Подготовить горбушу весом в 1-1,5 кг: помыть, почистить, отрезать голову, удалить внутренности, снять кожу, разделать на филе и нарезать кубиками (должно получиться около 50 шт.), переложить в глубокую миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13156,'Добавить к паре ложек подсолнечного масла соль, готовую горчицу, паприку, все взбить и залить рыбу, всыпать кольца лука, перемешать, оставить на пару часов (или на ночь) в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13156,'Насадить 4 кусочка рыбы на шампуры: рыба-лук- рыба и т.д. Поджарить шашлык из горбуши в горчичном маринаде над углями, но не более 25 минут. Если дольше, то шашлык будет сухим. Подавать блюдо горячим с белым соусом и овощным гарниром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13157,'Курятину и свинину пропустить через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13157,'Фарш посолить, влить воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13157,'Массу поместить в подготовленные кишки, перевязать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13157,'Колбасу варить на среднем огне в течение часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13157,'Блюдо остудить, хранить в холодильнике.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13158,'Свинину и говядину порубить кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13158,'Нарезать чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13158,'Ингредиенты перемешать, добавить специи, соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13158,'По необходимости добавить воду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13158,'Готовый фарш добавить в чистые кишки, запечь до готовности в духовом шкафу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13159,'Вымыть телятину, свинину, баранину, освободить от пленок и сухожилий, нарезать на полосы в пару сантиметров толщиной и около шести длинной, разложить сорта по разным мискам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13165,'Готовое варенье остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13159,'Для баранины сделать маринад из зиры, соли, красного перца. Для свинины – из лука, соли, рубленой петрушки, перца и небольшого количества сока  граната. Для телятины – из лимонного сока, соли, репчатого лука, перца. Оставить мясо в покое на пару часов мариноваться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13159,'Взять из каждой миски по куску мяса, проложить кусочками сала и нанизать всю стопку одним концом на шампур, переплести концы косичкой и закрепить на шампуре ее конец. Если не хочется возиться, то можно просто нанизать полоски гармошкой, но косичкой эффектней.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13159,'Обжарить сочный шашлык из трех видов мяса классическим способом: над очень горячими углями, 8-10 минут должно хватить. Подать блюдо прямо с жару на шампурах в компании с разнообразной зеленью и свежими овощами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13160,'В кастрюлю влить воду, всыпать соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13160,'Выложить куски говядины, немного придавить: продукт должен быть под водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13160,'Поставить кастрюлю в холод на два дня.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13160,'Мясо вынуть, положить под гнет на двенадцать часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13160,'Специи для бастурмы перемешать, натереть мясо.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13160,'Продеть веревочки через куски, обернуть продукты марлей, повесить в проветриваемом помещении на две недели.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13161,'Говяжью вырезку разрезать вдоль пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13161,'Посыпать продукт солью крупного помола и сахарным песком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13161,'Куски накрыть марлей, оставить на двенадцать часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13161,'Положить мясо в форму, поставить в холод еще на двенадцать часов, перевернуть, подержать еще столько же.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13161,'Куски промыть водой, обсушить, обмотать марлей и обвязать веревочкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13161,'Положить продукт под пресс на пятнадцать часов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13161,'Бастурму развязать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13161,'Пропустить чеснок через пресс, добавить ягоды можжевельника, перец чили, лавровый лист, чаман, гвоздику, кориандр.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13161,'Влить немного воды, массу перемешать миксером.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13161,'Смазать мясо полученной смесью, оставить для пропитывания на три часа.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13161,'Процедуру повторить еще два раза.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13161,'Продукт подвесить для просушивания, для этого подойдет балкон. Время – две недели.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13162,'Небольшие банки стерилизовать вместе с металлическими крышками в мультиварке в режиме «Пар», можно использовать духовой шкаф.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13162,'Приготовить сироп из воды и сахарного песка, выставить режим «Варка» на десять или двенадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13162,'Вишню очистить от косточек, ягоды пересыпать в сироп, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13162,'Поставить варенье в режим «Тушение» на час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13162,'Важно, чтобы продукт не «убежал».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13162,'При появлении пенки ее нужно удалить и добавить лимонную кислоту.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13162,'Время приготовления – один час, если нужен густой продукт, то время можно увеличить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13162,'Разлить варенье в банки, закрыть и остудить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13163,'Ягоды вишни и смородины промыть, удалить косточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13163,'Массу перемолоть при помощи блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13163,'Смесь переложить в мультиварку, всыпать сахар, оставить на полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13163,'Выставить режим «Мультиповар», время – один час, температура – 130 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13163,'Открыть клапан для выхода пара.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13163,'Варенье разложить в банки горячим.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13164,'Выставить режим «Тушение», влить воду и всыпать сахарный песок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13164,'Дать сиропу закипеть, варить три или четыре минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13164,'Добавить ягоды без косточек, варить в режиме «Мультиповар» пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13164,'Оставить продукт для настаивания на пять или шесть часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13164,'Добавить ванилин и апельсиновую цедру, варить в том же режиме пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13164,'Всыпать лимонную кислоту, перемешать и разлить варенье в банки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13165,'Ягоды промыть, удалить косточки, начинить кусочками грецких орехов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13165,'Выложить продукт на дно чаши мультиварки, всыпать сахар.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13165,'Оставить на два часа для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13165,'Ягоды не перемешивать, но массу встряхнуть несколько раз.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13166,'Всыпать сахарный песок, выставить мультиварку в режим «Скороварка».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13166,'После закипания ягод влить воду, поставить режим «Тушение» на час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13166,'Всыпать пищевую соду, тертый имбирь, варить еще полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13167,'Влить кипяченую воду в глубокую емкость, добавить сахар, соль, уксус, черный перец-горошек, гвоздику и лавровый лист.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13167,'Рыбу очистить от черной пленки, внутренностей, хорошо промыть и обсушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13167,'Залить продукт маринадом, оставить на два или три часа для пропитывания при комнатной температуре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13167,'Поставить на нижнюю полку в холодильник на сутки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13168,'Осетра помыть под проточной водой, почистить, отрезать голову, аккуратно выпотрошить. Обдать тушку кипятком, потом окатить холодной водой, снять кожу и разделать на филе, нарезать на одинаковые кубики примерно 3х3 см.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13168,'Приготовить из лимонного сока, масла, приправ и сухого белого вина маринад, залить рыбу и полчаса (не больше) выдержать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13168,'Насадить плотно на шампуры кусочки рыбы, чередуя их со сладким болгарским перцем. Обжарить аппетитный шашлык из осетра над углями до готовности, подать с белым соусом из смеси вина и свежих сливок, а на гарнир отварной рис и салат из свежих овощей с зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13169,'Скумбрию разморозить при комнатной температуре, очистить от костей и внутренностей, филе разрезать на куски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13169,'Недоваренную морковь натереть или пропустить через мясорубку, добавить к рыбе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13169,'Всыпать консервированный зеленый горошек, репчатый лук, нарезанный полукольцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13169,'Приготовить маринад: молотый черный перец, татарский кетчуп и уксус, растительное масло, соль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13169,'Залить рыбу, оставить для пропитывания на сорок минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13169,'Настоять в течение суток в прохладном месте.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13170,'Промыла ножки курицы, просушила их сухой салфеткой. Срезала излишки кожицы и жира. Сложила все в глубокую миску',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13170,'Затем очистила картофель, взяла одинаковый некрупный. Можно и большой, только тогда нужно его разрезать на половинки. Очистила и хорошо вымыла','https://vkuso.ru/data/cache/data/7b/f0026c31a7c9b7b_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13170,'Соединила картофель вместе с курицей. Добавила чеснок, специи, аджику, майонез и посолила по вкусу. Все ингредиенты между собой хорошо перемешала, как бы втирая специи в курицу и картофель.','https://vkuso.ru/data/cache/data/ac/56676f4c357c6ac_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13170,'Выложила на противень и отправила в духовку, разогретую до 200°C , выпекала до готовности картофеля и курицы. Ингредиенты накрыла фольгой. Из курицы должна вытекать прозрачная жидкость, а картофель быть мягким. Запекала примерно 1.20 час.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13170,'Через час достала противень из духовки, сняла фольгу и поставила противень в духовку еще минут на 10-15. За это время ножки подрумянились. Надеюсь, Вам понравится. Приятного аппетита!','https://vkuso.ru/data/cache/data/3c/4b4db002a33f53c_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13171,'Муку просеиваем в глубокую миску, добавляем соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13171,'Воду доводим до кипения, заливаем в муку. Сразу же перемешиваем ложкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13171,'Когда мука впитает всю воду и тесто немного остынет, продолжаем вымешивать его руками. Готовое тесто накрываем и отставляем до охлаждения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13171,'Сырок натираем на мелкой терке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13171,'Зелень промываем и мелко нарезаем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13171,'Смешиваем ингредиенты для начинки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13171,'Небольшие шарики теста раскатываем в лепешки, часто переворачивая и обильно посыпая стол мукой. Тесто получается немного липким, поэтому нужно следить, чтобы оно не прилипало к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13171,'На одну половину лепешки кладем немного начинки. Накрываем второй половиной, края плотно защипываем.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13171,'В глубокой сковороде разогреваем растительное масло. На среднем огне быстро обжариваем пироги с двух сторон до золотистого цвета.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13172,'Печенку зачищаем и отвариваем в подсоленной воде до готовности. Даем остыть и нарезаем маленькими кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13172,'Лук нарезаем кубиком и обжариваем на растительном масле до золотистости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13172,'В отдельной емкости соединяем печенку, лук, морковь по-корейски и мелко измельченный укроп. Перемешиваем и добавляем майонез, еще раз перемешиваем и даем настояться 1-1,5 часа в холодильнике.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13172,'Подаем порционно, выкладывая в кулинарное кольцо и украшая сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13173,'Брокколи бланшировать в кипящей воде 1 минуту. Остудить в ледяной воде, воду слить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13173,'Цукини нарезать небольшими кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13173,'Чеснок мелко нарубить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13173,'Филе анчоусов нарезать мелкими кусочками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13173,'Обжарить чеснок и анчоус в течении 5 минут на разогретой сковороде с маслом, помешивая.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13173,'Пасту отварить в подсоленной воде как указано на упаковке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13173,'Добавить в сковороду с анчоусами брокколи, цукини и зелёный горошек. Обжаривать, помешивая, до мягкости овощей, около 7 минут. Поперчить и если не хватает соли, то досолить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13173,'Выложить овощи с анчоусами к пасте и перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13174,'Смешать для маринада апельсиновый сок, кетчуп, сахар, тертый имбирь, соевый соус, размешать и дать настояться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13174,'Промыть филе и нарезать на куски, соединить с маринадом и оставить в покое на полчаса. Включить на разогрев до 200 градусов духовку. Нанизать мясо на шпажки: мясо-ананас-мясо и т.д.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13174,'Отправить шашлык из курицы с ананасом в духовку примерно на полчаса, подать на шпажках с красным вином, зеленью, нарезкой из свежих овощей и лимоном..',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13175,'Охлажденное сливочное масло натереть на терке','https://vkuso.ru/data/cache/data/9c/e2d7e381685999c_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13175,'Просеять в него муку','https://vkuso.ru/data/cache/data/20/1d2946947dee620_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13175,'Тщательно перетереть смесь пальцами (саблировать)','https://vkuso.ru/data/cache/data/09/5cd8b217274ce09_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13175,'В процессе смешивания всыпать соль и соду','https://vkuso.ru/data/cache/data/7b/5b77d69866c037b_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13175,'Творог размять толкушкой или вилкой, чтобы убрать крупную зернистость. Можно также использовать для этого блендер или мясорубку','https://vkuso.ru/data/cache/data/6f/a8868b9a2ece46f_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13175,'Добавить творог к тесту','https://vkuso.ru/data/cache/data/0a/d0990b6023c430a_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13175,'Быстро вымесить тесто до однородности. Тесто вымешивать не слишком долго, всего около 1-2 мин','https://vkuso.ru/data/cache/data/27/6f8c7da80dd0027_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13175,'Замешанное тесто убрать в пакет и положить в холодильник на 30 мин','https://vkuso.ru/data/cache/data/5a/ee61944a770135a_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13175,'Охлажденное тесто вынуть из пакета, присыпать мукой, слегка промять еще немного, чтобы выпустить из него лишний воздух и раскатать из него пласт толщиной около 3 мм','https://vkuso.ru/data/cache/data/f9/3021fdfef63a3f9_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13175,'Вырезать круглой формочкой или стаканом диаметром около 8 см заготовки для печенья','https://vkuso.ru/data/cache/data/95/2b6e37891f9b095_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13175,'Обрезки теста слепить, снова раскатать и нарезать кружочки еще
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13175,'Заготовки для печенья отложить в сторону','https://vkuso.ru/data/cache/data/a3/265d749d161a6a3_434x295_notrise.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13175,'В отдельной ёмкости смешать обычный сахар с ванильным сахаром','https://vkuso.ru/data/cache/data/54/5a724025e92e054_434x295_notrise.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13175,'Опустить каждый кружочек теста одной стороной в сахар, слегка придавить, сложить пополам сахарной стороной внутрь, еще раз опустить в сахар и еще раз сложить пополам, также сахарной стороной внутрь. Затем опустить сложенное вчетверо печенье в сахар только одной стороной. Это будет верхняя часть печенья','https://vkuso.ru/data/cache/data/66/77c063d10298d66_434x295_notrise.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13175,'Можно сделать два надреза по краю или оставить в виде сложенных четвертинок','https://vkuso.ru/data/cache/data/fa/bc759164470eafa_434x295_notrise.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13175,'Выложить печенье на противень, застеленный ковриком или обычной пекарской бумагой. По желанию присыпать печень сверху корицей
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13175,'Выпекать печень в заранее разогретой до 180 С духовке около 20 мин до легкого подрумянивания, учитывая особенности своей плиты','https://vkuso.ru/data/cache/data/72/91d95a005102372_434x295_notrise.jpg',17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13175,'Переложить печенье на блюдо после остывания','https://vkuso.ru/data/cache/data/a7/3d9d6091cf7e7a7_434x295_notrise.jpg',18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13180,'Выложить рыбу, репчатый лук, нарезанный полукольцами, влить растительное масло с уксусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13180,'Слои повторить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13176,'Просеять муку и влить в нее теплую воду, заранее смешанную с растительным маслом и солью. Вливать воду постепенно, постоянно перемешивая муку. Далее вымесить тесто руками около 2 мин. Тесто должно быть эластичным, не должно липнуть к рукам и быть не слишком крутым. Убрать тесто в пакет и оставить на 30 мин при комнатной температуре, чтобы оно отдохнуло.','https://vkuso.ru/data/cache/data/c4/a6e9c9c0901dfc4_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13176,'Приготовить начинку из творога и любой зелени, посолить и поперчить ее по своему вкусу.','https://vkuso.ru/data/cache/data/52/adbf54689198952_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13176,'Отдохнувшее тесто разделить на 8 частей, сформировать шарики и убрать в пакет от заветривания.','https://vkuso.ru/data/cache/data/fe/6137c0623ce5bfe_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13176,'Из каждого шарика раскатать тонкую полу-прозрачную круглую лепешку. Тесто раскатывается очень легко. Раскатывать лепешки нужно на хорошо присыпанной мукой поверхности, чтобы оно не прилипло к столу.','https://vkuso.ru/data/cache/data/ab/bb917547bf3c8ab_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13176,'На половину лепешки выложить начинку тонким слоем, натереть всерху сливочное масло (по желанию) и накрыть второй половиной теста.','https://vkuso.ru/data/cache/data/0a/bd2cc555e74e30a_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13176,'Осторожно придавить лепешку с начинкой руками сверху, чтобы выдавить весь оставшийся воздух, закрепить край и по желанию подровнять его фигурным или любым ножом.','https://vkuso.ru/data/cache/data/6e/6a430c2c0ac916e_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13176,'Сразу же после лепки лепешки нужно жарить на разогретой сковороде без масла на огне чуть выше среднего (сила огня 6 из 10) по 3 мин с каждой стороны до равномерного подрумянивая. Пока жарятся две первых лепешки нужно слепить еще две следующих. Заготавливать лепешки заранее и жарить потом все сразу все рекомендуется.','https://vkuso.ru/data/cache/data/35/1b1c404273f6335_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13176,'Готовые лепешки сразу обильно смазать с двух сторон сливочным маслом и сложить в ёмкость с хорошо закрывающейся крышкой. Дать им настояться, пропитаться маслом и стать более нежными и мягкими примерно 20-30 мин.','https://vkuso.ru/data/cache/data/32/da3eb58c1da5332_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13176,'Выложить пропитанные маслом отдохнувшие под крышкой лепешки на блюдо.','https://vkuso.ru/data/cache/data/70/4d5ba2d8ddd5370_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13176,'При подаче на стол можно по желанию посыпать лепешки зеленью и зернышками граната. Также можно разрезать из пополам и подавать таким образом.','https://vkuso.ru/data/cache/data/38/b56b4b087b7ea38_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13177,'Подготовить куриное филе: помыть, нарезать на одинаковые куски. Переложить мясо в глубокий лоток, добавить порезанную зелень, масло, мелко порубленный чеснок, смесь меда с соевым соусом, полить соком лайма или лимона, перемешать и оставить в покое минимум на пару часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13177,'Замочить деревянные шпажки в воде, ананас почистить нарезать крупными кубиками. Нанизать на шпажки мясо чередуя с ананасом и ломтиками бекона. Включить на разогрев до 200 градусов духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13177,'Уложить шпажки с экзотическим шашлыком из куриного филе в жаропрочную форму, но так, чтобы шашлычки не доставали до дна и висели, как на мангале. Налить на дно немного воды и установить форму в духовку, через треть часа необычное блюдо можно подавать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13178,'Рыбу разморозить и промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13178,'Отрезать головы, тушку нарезать на порции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13178,'Репчатый лук нашинковать полукольцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13178,'Вскипятить воду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13178,'Добавить сахарный песок, соль, лавровый лист, растительное масло, молотый перец и перец-горошек, кориандр, гвоздику.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13178,'Поставить маринад на тихий огонь, прогревать в течение минуты, затем влить яблочный уксус.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13178,'Смесь снять с огня и остудить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13178,'Подготовленную рыбу сложить в емкость, залить маринадом, оставить для пропитывания на сутки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13179,'Рыбу очистить, вымыть, выложить в емкость.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13179,'Очистить и нарезать пластинками чеснок и лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13179,'Ингредиенты добавить к рыбе, всыпать соль, душистый перец, сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13179,'Залить продукты яблочным уксусом и растительным маслом, оставить в холоде на сутки в холодильнике.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13180,'Скумбрию вымыть, удалить голову и внутренности, брюшко не вспарывать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13180,'Тушки нарезать кусками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13180,'Приготовить маринад из воды и соли, сахарного песка, залить рыбу на полтора часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13180,'Заполненную банку закрыть крышкой, убрать в холод на час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13181,'Курицу солим, перчим и обжариваем с двух сторон до золотистой корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13181,'Вынимаем на тарелку и отставляем в сторону.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13181,'Готовим соус: муку с паприкой растираем с водой до однородного состояния и добавляем сметану и соль. Тщательно перемешиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13181,'Выливаем соус в сковороду, где обжаривались бедрышки, даем загустеть. Регулируем густоту соуса, добавляя воду или сметану и выкладываем курицу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13181,'Накрываем крышкой и тушим в соусе примерно 1 час. За 10 минут до готовности курицы добавляем тимьян и мелко порезанный чеснок. Получается очень вкусно!',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13182,'Нарезать куриное филе на куски, поместить его в маринад из раздавленного через пресс чеснока, соевого соуса, крахмала и тертого имбиря, оставить в покое на полчаса. Нанизать на вымоченные в воде шпажки мясо, чередуя с маслинами без косточек, обсыпать семенами кунжута.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13182,'Запекать шашлык из курицы с маслинами в соевом маринаде около 20-25 минут. Но после  четверти часа жарки (при 180 градусах) лучше не отвлекаться и следить за шашлыком, т.к. можно пересушить и испортить блюдо.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13183,'Рыбу разморозить, вымыть, очистить от внутренностей.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13183,'Для приготовления маринада сложить в   емкость промытую луковую шелуху, всыпать соль и сахарный песок, влить воду и заваренный черный чай.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13183,'Маринад прокипятить на огне, остудить под крышкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13183,'Залить рыбу готовым темным маринадом, оставить на три дня в холодильнике для пропитывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13184,'Рыбу выпотрошить и вымыть, сделать на тушке надрезы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13184,'Отдельно развести холодной кипяченой водой соевый соус, залить рыбу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13184,'Время маринования – одни сутки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13185,'Замороженную рыбу положить в холодную воду и дождаться размораживания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13185,'Удалить голову, плавники, внутренности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13185,'Филе нарезать кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13185,'Измельчить очищенный чеснок, нарезать кольцами репчатый лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13185,'Основной продукт посолить и поперчить, добавить овощи, растительное масло и уксус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13185,'Закуску перемешать и поставить в холодильник на нижнюю полку на десять часов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13186,'Нарезать на средние куски мясо свиной шеи, лук нашинковать полукольцами, сложить в глубокую кастрюлю, вымыть помидоры и нарезать на произвольные кусочки, вылить в мясо, размять содержимое руками и добавить веточки розмарина, разрезанные на несколько кусочков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13186,'Убрать кастрюлю часов на 6-8 в холодное место, сдобрить мясо солью и перцем, нанизать на шампуры. Жарить шашлык из свинины в маринаде из томатов и розмарина на мангале над сильно разогретыми углями периодически меняя положение шампура.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13187,'Скумбрию выпотрошить, нарезать кусочками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13187,'Выложить продукт в емкость, посолить, залить растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13187,'По желанию добавить натертую морковь и перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13187,'Настаивать двадцать четыре часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13188,'Сельдь тщательно очистить от внутренностей и костей, нарезать мелкими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13188,'Овощи предварительно отварить, добавив 0,25-0,5 ч.л. соли, почистить и натереть на крупной терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13188,'Яичный белок измельчить на терке, желток отложить для украшения салата.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13188,'По классическому рецепту Селедки под шубой каждый слой необходимо смешать с майонезом и аккуратно выложить на большое плоское блюдо в последовательности: селедка, картофель, яичный белок, затем морковь и свекла. Слои можно менять местами, повторять несколько раз, но желательно, чтобы последним слоем всегда была свекла. Салату придать круглую либо прямоугольную форму, осторожно выровнять поверхность.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13188,'Яичный желток натереть на мелкой терке и смешать с мелко порезанной свежей зеленью, и украсить смесью готовый салат. Для украшения салата «Селедка под шубой» так же рекомендуют использовать фигурки из вареных овощей и вареного яйца.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13192,'К песочной крошке добавляем сладкую смесь и все хорошо замешиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13353,'Прикрыть плов крышкой, томить двадцать минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13188,'Очень оригинальный вариант оформления: готовому салату придать миндалевидную форм, голову и хвостик сельди тщательно промыть и аккуратно приложить к уголкам салата. Визуально создается впечатление лежащей под «шубой» рыбы. Сверху посыпать измельченным желтком и зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13188,'Яичный белок можно заменить луком, чтобы лук не давал горечь его необходимо мелко порезать и обдать кипятком, либо вымочить в слабом растворе уксуса. Смешивать сельдь с луком не рекомендуется, так как спустя время, у салата может появиться слегка металлический привкус.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13188,'Слой селедки полить лимонным соком (0,5 ч.л.). Кусочки рыбы станут гораздо нежнее и ароматнее.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13189,'Зачистить мякоть говядины от пленок и жилок, порезать на одинаковые средние кусочки, переложить в подходящую емкость, добавить полукольца лука, соль и перец, отставит на 7 часов в покое (лучше в холодильнике).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13189,'Нарезать бекон на полоски, но не очень тонко, т.к. бекон быстро высохнет и начнет гореть. Каждый кусочек мяса «запеленать» в полоску из бекона и насадить на шампур так, чтобы бекон не развернулся.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13189,'Обжарить шашлык из говядины с луком в беконе над раскаленными углями. Мясо получается очень нежное, а сверху покрытое аппетитно зажаренным кусочком бекона.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Песочное печенье растолочь в крошку, добавить мягкое сливочное масло и сгущенное молоко.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Смесь переложить в кулинарное кольцо, утрамбовать, заморозить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Диаметр кольца должен быть на два сантиметра меньше формы для сборки торта.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Сахарный песок перемешать с крахмалом, влить клубничное пюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Массу варить до густоты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Снять с огня, влить заранее приготовленный желатин.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Ягодную массу перелить в форму на два сантиметра меньше формы для торта.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Поставить в морозильную камеру.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Для приготовления мусса ягоды превратить в пюре помощи блендера.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Второй этап – пропустить массу через сито, всыпать сахарный песок и быстрорастворимый желатин.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Массу прогреть до однородного состояния, помешивать, температура нагревания – не выше шестидесяти градусов.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Взбить сливки в пену, ввести клубничный мусс с желатином в несколько приемов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Перемешивать продукты при помощи миксера или лопатки.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Влить в силиконовую форму треть мусса, поставить в морозилку на пять минут.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Выложить слой замороженной ягодной массы, вылить остатки мусса.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Корж из песочного печенья утопить в муссе.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Готовый десерт поставить в морозилку, заморозить, полить зеркальной глазурью.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Для приготовления глазури желатин залить водой так, как написано на пакетике.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Перемешать сахар и сироп из глюкозы с водой, смесь прогревать до кипения.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Растопить шоколад на водяной бане.',NULL,20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Отправить в чашу блендера горячий сироп и растопленный шоколад, сгущенное молоко.',NULL,21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Смесь перемешать лопаткой, остудить до шестидесяти градусов и ввести растворенный желатин.',NULL,22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'По желанию добавить пищевой краситель, массу взбивать блендером, она должна стать абсолютно гладкой.',NULL,23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Получившийся гляссаж процедить через мелкое сито.',NULL,24);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13190,'Массу накрыть пленкой и убрать в холод на шесть часов для созревания.',NULL,25);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13191,'Мягкое сливочное масло взбить с сахарной пудрой и сгущенным молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13191,'Должен получиться воздушный, нежный крем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13191,'Покрыть им бока и верх заранее испеченного торта.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13191,'Поставить в холод на несколько часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13191,'Оформить торт потеками из гляссажа с помощью кондитерского мешка со срезанным кончиком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13192,'Песочное печенье превращаем в крошку и перекладываем в миску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13192,'В другую миску перекладываем сливочное масло, добавляем молоко сгущенное около 180 грамм (или же по вкусу), также добавляем 2 ч.л. какао, все хорошо взбиваем или же перемешиваем,',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13353,'Дать блюду постоять.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13192,'Из подготовленной массы катаем пирожное в виде картошки и посыпаем какао-порошкам. Все готово.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13193,'Для приготовления бисквита протереть на водяной бане яйцо с сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13193,'Массу взбить в пену, всыпать пшеничную и миндальную муку и разрыхлитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13193,'Аккуратно, по краю, влить растопленное сливочное масло, ингредиенты перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13193,'Выпечь бисквит, диаметр коржа – около шестнадцати сантиметров.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13193,'Приготовить хрустящий слой из вафельных хлопьев, кокосовой стружки, растопленного масла, белого шоколада.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13193,'Массу перелить в кольцо того же диаметра, что и корж, поместить в морозильную камеру.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13193,'Мякоть свежих ананасов превратить в пюре при помощи блендера, всыпать крахмал и сахарный песок, варить в течение пяти минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13193,'Пюре остудить до шестидесяти градусов, ввести заранее приготовленный желатин.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13193,'Массу заморозить в кольце.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13193,'Приготовить мусс из кокосового молока.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13193,'Продукт довести до кипения, заварить смесь желтков с сахаром.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13193,'Добавить белый шоколад, продукт должен растаять.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13193,'Влить набухший желатин.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13193,'Крем остудить до двадцати градусов, перемешать со взбитыми сливками.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13193,'Собрать десерт: утопить в форме с муссом поочередно конфи, грильяж и бисквит.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13193,'Поставить торт в морозильную камеру.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13193,'Приготовить зеркальную глазурь, полить десерт.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13194,'Сладкий перец очистить от семян и нарезать на квадраты, молодой кабачок цуккини – такими же по размеру кусочками, мякоть говядины порезать на небольшие куски',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13194,'Насадить мясо на шпажки вместе с кабачком и перцем, чередуя кусочки. Переложить шпажки в подходящий контейнер, засыпать полукольцами лука и мелко нашинкованным базиликом, присолить, поперчить, залить оливковым маслом и перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13194,'Дать мясу промариноваться минимум 2 часа, а лучше пусть переночует в холодильнике. Жарить шашлык из говядины с цуккини и болгарским перцем классическим способом: над углями, периодически поворачивая с боку на бок. Когда мясо покроется приятной корочкой блюдо можно подавать к столу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13195,'Испечь красный бисквит из сахарного песка, сырого куриного яйца, мягкого сливочного масла, растительного масла, муки, какао-порошка, соли, пищевой соды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13195,'Добавить ванилин, белый винный уксус, жирный кефир или пахту, красный пищевой краситель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13195,'Все ингредиенты можно просто перемешать чаше блендера, скорость – средняя.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13195,'Масса должна быть однородной, диаметр коржа – восемнадцать сантиметров.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13195,'Выпечку остудить, обернуть пищевой пленкой, поставить на ночь в холодильник.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13195,'Разрезать на два коржа толщиной по одному сантиметру, диаметр – по шестнадцать сантиметров.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13195,'Приготовить конфи из клюквы: перебить ягоды в блендере в пюре, всыпать крахмал и сахар по вкусу, добавить листовой или порошковый желатин.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13195,'Массу заморозить в кулинарном кольце по размеру коржа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13195,'В небольшом сотейнике прогреть шампанское с лимонным соком и сахаром.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13195,'Немного сахара растереть с сырыми желтками, массу заварить до густоты в горячем шампанском.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13195,'Жирные сливки взбить в пышную пену.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13195,'Поставить в холод.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13195,'Сварить сироп из остатков сахара и воды, ввести взбитые белки тонкой струйкой.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13195,'Половину получившейся меренги перемешать со взбитыми сливками, оставшуюся часть – с заварным кремом, приготовленном на шампанском.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13195,'Обе массы аккуратно перемешать.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13195,'Торт собрать в силиконовой форме или в кольце.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13195,'Влить треть мусса, следующий слой – корж, далее – еще треть мусса, ягодная масса-конфи, сверху – оставшийся мусс и второй корж.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13195,'Верхний корж вдавить в мусс.',NULL,18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13195,'Десерт заморозить и покрыть зеркальной глазурью белого цвета.',NULL,19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13196,'В муку ввести соль и разрыхлитель.','https://vkuso.ru/data/cache/data/dd/1ad5bff2aec9bdd_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13196,'Просеять в отдельную ёмкость.','https://vkuso.ru/data/cache/data/78/5a1f122b04ae878_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13196,'В другой ёмкости соединить растопленное и остывшее сливочное масло, и молоко комнатной температуры и перемешать.','https://vkuso.ru/data/cache/data/74/bcb2b746e001974_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13196,'Еще в одной самой большой основной ёмкости соединить яйца, сахар и ванильный сахар и взбить до полного растворения крупинок сахара.','https://vkuso.ru/data/cache/data/20/8a6e8aa77e8d820_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13196,'Продолжая взбивать яйца с сахаром постепенно струйкой ввести подготовленную масляно-молочную смесь и взбить до однородности.','https://vkuso.ru/data/cache/data/ae/85f32238119e4ae_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13196,'Далее, продолжая взбивать смесь, постепенно по 2-3 ложки ввести муку и взбивать до однородности и растворения мучных комочков. Тесто получается довольно густым и тягучим, как для бисквита.','https://vkuso.ru/data/cache/data/83/0d3f2354c595783_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13196,'Форму для запекания обильно смазать сливочным маслом и выложть половину теста, разравнивая поверхность ложкой.','https://vkuso.ru/data/cache/data/fe/e4e68fd004276fe_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13196,'Нарезать персики на небольшие кусочки.','https://vkuso.ru/data/cache/data/b6/4e6042f2a13cfb6_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13196,'Выложить их на тесто и разровнять.','https://vkuso.ru/data/cache/data/6b/2abdc4f4fca186b_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13196,'Сверху персиков выложить вторую половину теста и также разровнять.','https://vkuso.ru/data/cache/data/68/f5490a6f9925f68_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13196,'Выпекать пирог в заранее разогретой до 160 С духовке 60-70 мин до равномерного подрумянивания верхней корочки и полной готовности, учитывая особенности своей духовки и высоты пирога. Готовность можно проверить зубочисткой. При прокалывании пирога она должна оставаться сухой.','https://vkuso.ru/data/cache/data/c4/63558353d1f5ec4_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13196,'Вынуть пирог из духовки и сразу же, еще горячий пирог, глубоко проколоть зубочисткой по всей поверхности.','https://vkuso.ru/data/cache/data/d2/ed735f56ed5c8d2_434x295_notrise.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13196,'Обильно смазать или полить верх пирога оставшимся от персиков сиропом и оставить остывать и пропитываться. Вынимать пирог из формы после полного остывания.','https://vkuso.ru/data/cache/data/1e/52076aa2f8ed81e_434x295_notrise.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13196,'По желанию растопить в микроволновке несколько квадратиков темного и белого шоколада.','https://vkuso.ru/data/cache/data/3a/94967c5855dd43a_434x295_notrise.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13196,'Украсить шоколадной сеточкой верх остывшего пирога.','https://vkuso.ru/data/cache/data/15/c07fe811b177a15_434x295_notrise.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13196,'Подавать такой пирог можно к чаю, когда застынет шоколадная сеточка.','https://vkuso.ru/data/cache/data/cf/667dca8ca22d0cf_434x295_notrise.jpg',16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13196,'Пирог отлично подходит для любого случая, торжественного или на каждый день, к чаю, кофе и просто со стаканчиком молока','https://vkuso.ru/data/cache/data/63/62e66c492763463_434x295_notrise.jpg',17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13197,'Мягкое сливочное масло взбить с сахарной пудрой, яйца ввести по одному, всыпать муку, разрыхлитель, какао-порошок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13197,'Из полученного теста испечь корж, остудить, верхнюю корочку срезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13197,'Для приготовления мусса растереть желтки с сахарным песком, влить молоко, прогреть до густоты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13197,'В горячую массу положить кусочки горького шоколада, подготовленный желатин.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13197,'Смесь перемешать, остудить до комнатной температуры.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13197,'Перемешать со взбитыми сливками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13197,'Приготовить три мусса с разными видами шоколада: темным, молочным и белым.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13197,'Установить на блюдо сервировочное кольцо подходящего размера.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13197,'Бока застелить пленкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13197,'Выложить бисквит, залить темным муссом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13197,'Поставить десерт в холод до застывания.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13197,'Сверху вылить мусс из молочного шоколада, после повторного застывания вылить мусс с белым шоколадом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13197,'Охлажденный десерт украсить темной зеркальной глазурью.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13198,'Насадить баранину на шампуры вместе с лимоном (по 2 кусочка на шампур), переложить на широкое блюдо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13198,'В небольшой мисочке смешать масло, тертый чеснок и лимонный сок, залить мясо, прикрыть пленкой и отправить ночевать в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13198,'Выложить шампуры на смазанную решетку гриля, зажарить шашлык  до готовности (не забывайте переворачивать).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13206,'Растопить сливочное масло на водяной бане, немного охладить, затем соединить с желтками и жирной сметаной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13198,'Взбить блендером лимонный сок, сыр фета и пару столовых ложек воды, присолить, заправить черным перцем. Шашлык из ягненка с лимонно-сырным соусом готов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13199,'Плоды вымыть теплой водой, затем прополоскать под проточной холодной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13199,'Ягоды протереть через мелкое сито.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13199,'Отжать сок через марлю, выжимки выложить в кастрюлю, залить водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13199,'Довести до кипения, добавить сахарный песок, перемешать, варить пятнадцать минут, огонь – средний.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13199,'Добавить отжатый сок, перемешать еще раз, варить еще шесть или семь минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13200,'Ягоды разморозить при комнатной температуре, промыть, выложить в дуршлаг.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13200,'Перемолоть ягоды в блендере, сок отжать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13200,'Мезгу выложить в кастрюлю, влить воду, довести до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13200,'Огонь убавить, всыпать обычный и ванильный сахар, гвоздику.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13200,'Время варки – от пяти до семи минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13200,'Напиток снять с плиты и немного остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13200,'Процедить через сито, добавить отцеженный сок, хорошо перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13201,'Промытые ягоды протереть вручную ложкой через сито.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13201,'Долить немного воды и повторно продавить жмых ложкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13201,'Влить в полученный сок натуральный жидкий мед или сироп из агавы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13201,'Перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13202,'Бруснику промыть, выложить в стерильную бутылку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13202,'Вскипятить воду, залить ягоды на пятнадцать минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13202,'Процедить напиток через сито.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13202,'Перелить в кастрюлю, добавить сахарный песок, еще раз вскипятить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13202,'Готовым сиропом залить ягоды и закатать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13203,'Подготовить и нарезать шейную часть свиной туши на одинаковые кусочки, лук измельчить блендером в пюре. Переложить мясо в большую эмалированную кастрюлю, добавить лук, посыпать перцем, приправами для шашлыка, присолить, залить разбавленным водой уксусом, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13203,'Дать мясу постоять не менее 4 часов, а идеально всю ночь. Насадить мясо на шампуры, обжарить классический шашлык из свинины в уксусном маринаде минут 30-40 над углями. Подать блюдо горячим прямо на шампурах с петрушкой, кетчупом, маринованным луком и салатом из свежих овощей',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13204,'Ягоды промыть и пропустить через сито.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13204,'Отжать сок и поставить его в холод.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13204,'Мезгу залить водой, добавить сахар, довести до кипения, снять с плиты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13204,'Напиток остудить, отцедить жмых еще раз.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13204,'Жидкость перемешать со свежим охлажденным соком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13205,'Подтаявший маргарин перемешать с ванилином из пакетика, сахарным песком, сметаной, разрыхлителем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13205,'Ингредиенты перемешать, массу взбить, добавить муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13205,'Тугое тесто поместить в холодильник на час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13205,'Разделить массу на три части, раскатать пласты прямоугольной формы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13205,'Нарезать на заготовки размером десять на тридцать сантиметров.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13205,'Выложить свежие или размороженные ягоды вишни без косточек в ряд.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13205,'Тесто аккуратно свернуть трубочкой, края плотно закрыть, чтобы не вытек сок.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13205,'Противень застелить пекарской бумагой, выложить трубочки, выпекать в течение получаса при температуре 180 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13205,'Выпечка должна подрумяниться.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13205,'Трубочки остудить, их должно получиться пятнадцать штук.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13205,'Для приготовления сметанного крема взбить при помощи миксера сливки, добавить сметану и сахарный песок.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13205,'Продукты взбивать при помощи миксера.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13205,'Крем должен получиться густым.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13205,'Выложить на поднос пять трубочек, смазать сметанным кремом, во второй слой выложить четыре трубочки, затем три и одну.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13205,'Все слои промазывать кремом.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13205,'«Избу» убрать в холод на два часа для пропитывания.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13205,'Готовый торт нарезать кусочками и подать.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13206,'Отделить желтки от белков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13206,'Белки охладить, перемешать с сахаром, взбить массу венчиком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13206,'Пищевую соду погасить уксусом, всыпать муку, положить сметану, замесить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13206,'Сформовать двадцать восемь шариков одинакового размера.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13206,'Поставить заготовки в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13206,'Каждый шарик раскатать в лепешку размером три на двадцать сантиметров.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13206,'Выложить ягоды вишни, перемешанные с кусочками грецких орехов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13206,'Тесто свернуть трубочками, печь в течение пятнадцати минут при температуре 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13206,'Сметану взбить с сахаром',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13206,'Полученным кремом смазать дно тарелки.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13206,'Выложить первый слой из семи трубочек, в каждом ряду количество «бревен» уменьшается.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13206,'Торт покрыть сметаной, посыпать тертым шоколадом.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13207,'Нарезать лук, болгарский перец (красный) и стебли сельдерея, поджарить с одной столовой ложкой масла, сдобрить соль и перцем, готовить минут 6-7. Убрать с огня, всыпать горох, влить уксус и оставшееся масло, перемешать. Положить в воду на 20-30 минут деревянные шампуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13207,'Куриные бедрышки обсыпать перцем, орегано, солью, дать чуть постоять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13207,'Прогреть гриль, решетку смазать небольшим количеством масла. Насадить мясо, сосиски, разрезанные на кусочки и лук на шампуры. Обжарить шашлык до готовности минут 20 (за это время пару-тройку раз перевернуть шампуры). Подать шашлык из курицы с гороховым салатом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13208,'Муку перетереть с мягким сливочным маслом, добавить сметану, разрыхлитель, замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13208,'Поставить в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13208,'Сырые куриные желтки соединить с сахаром и молоком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13208,'Остатки молока смешать с мукой и соединить с яичной смесью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13208,'Варить смесь на водяной бане до загустения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13208,'Тесто из холодильника раскатать, нарезать брусками, раскатать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13208,'Начинить заварным кремом, свернуть трубочками, поставить в духовку на десять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13208,'Выложить поленницу, смазывать кремом, поставить торт в холод на три часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13209,'Приготовить тесто из мягкого маргарина, соли, соды, сахара, ванилина, сметаны и муки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13209,'Ингредиенты перемешать и поставить тесто в холод.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13209,'Разделить массу на три части, их разрезать еще на шесть частей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13209,'Раскатать прямоугольники размером семь на тридцать сантиметров.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13209,'Ягоды вишни и сахарный песок перемешать, начинку выложить на длинные лепешки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13209,'Края теста хорошо защипать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13209,'Поместить «бревна» в духовку, выпечь до румяной корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13209,'Для крема соединить сливочное масло и сгущенное молоко.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13209,'Построить «избу» из шести бревен, далее из пяти и т. д.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13209,'Каждый слой промазывать кремом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13209,'Оставить торт на ночь в холоде.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13210,'Мясо хорошо промыть, нарезать кусками среднего размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13210,'Продукт посыпать приправами и солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13210,'Готовить кусочки в режиме «Жарка» в заранее прогретом растительном масле в течение двенадцати минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13210,'Нарезать желтую морковь тонкой соломкой, белый репчатый лук – полукольцами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13210,'Выложить овощи к мясу, все вместе прогревать еще восемь минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13210,'Влить немного воды, посолить еще раз, если есть необходимость.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13210,'Оставить продукты на две минуты в том же режиме.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13210,'Хорошо промыть длиннозерный рис, всыпать в основную массу, поверхность разровнять.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13210,'Головку чеснока вымыть и целиком погрузить в середину блюда.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13210,'Выставить режим «Плов».',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13211,'Подготовить и нарезать рыбу, сильно разогреть гриль. Положить в блендер чеснок, базилик, влить масло, сдобрить соль и черным перцем, смешать до однородного состояния, разделить на две части.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13211,'Нанизать кусочки рыбы и целые помидорки на шампуры. Смазать рыбный шашлык с помидорами черри половиной взбитой смеси, чуть присолить, поперчить. Обжарить около 10 минут, обмакнуть в оставшуюся смесь и сразу подать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13212,'Срезать с костей кусочки куриной грудки, измельчить лук и морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13212,'Продукты выложить в чашу мультиварки, готовить в режиме «Жарка» без масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13212,'Влить немного воды или бульона.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13212,'Всыпать заранее промытый рис, все вместе готовить в том же режиме семь минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13212,'Влить воду, всыпать соль, специи, сушеный барбарис.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13212,'Ингредиенты перемешать, выставить режим «Плов».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13213,'Кусочки куриного филе жарить в течение двенадцати минут с любым растительным маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13213,'Измельчить морковь и белый репчатый лук, добавить к мясу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13213,'Готовить все вместе еще двенадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13213,'Продукты должны приобрести золотистый оттенок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13213,'Промыть изюм без косточек и рис, добавить продукты в основную массу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13213,'Всыпать соль, специи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13213,'Влить воду, она должна полностью покрыть продукты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13213,'Выставить режим «Плов» или «Каша».',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13214,'Основной продукт очистить от пленок, нарезать кусками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13214,'Мясо залить растительным маслом с приправами на два часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13214,'Влить растительное масло в чашу мультиварки, выставить режим «Жарка» на сорок минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13214,'В течение половины этого времени готовить мясо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13214,'Далее всыпать белый лук, нарезанный кубиками, бруски сладкой моркови.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13214,'Все вместе жарить до окончания программы без крышки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13214,'Влить горячую воду, всыпать соль и специи, нарезанный чеснок, выставить режим «Тушение» на пятьдесят минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13214,'В последнюю очередь всыпать промытый рис, влить полтора стакана горячей воды.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13214,'Продукты не перемешивать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13214,'Блюдо тушить еще сорок минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13215,'Куски свинины вымыть и высушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13215,'Насыпать в кастрюлю соль, подойдет морская или поваренная крупного помола.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13215,'Выложить свинину.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13215,'Сверху – оставшийся консервант.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13215,'Поставить в холод на трое суток.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13215,'Мясо вынуть и промыть, залить холодной водой на время от трех до восьми часов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13215,'Воду менять каждый час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13215,'Продукт обсушить бумажными полотенцами.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13215,'Свинину обвалять в красном молотом перце.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13215,'Обернуть мясо марлей, концы завязать, повесить в сухом месте на две или три недели.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13216,'Перемешать ягоды можжевельника с сушеной кинзой, молотой паприкой, черным и красным молотым перцем, сушеным чесноком и коричневым сахаром.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13216,'Ингредиенты перемолоть в ступке или в кофемолке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13216,'Говядину нарезать ломтями толщиной в полсантиметра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13216,'Чтобы мясо легче нарезалось, его лучше подморозить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13216,'Продукт положить в миску, заправить соусом «Табаско», «Вустерским» и соевым.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13216,'Всыпать сухие ингредиенты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13216,'Все хорошо перемешать, оставить на сорок минут для пропитывания в холодильнике.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13216,'Развесить мясо на решетке в духовом шкафу, поставить противень для стекания жидкости.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13216,'Выставить режим конвекции на час, температура – 80 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13216,'Через час снизить температуру до пятидесяти градусов, готовить еще два или три часа, до полной готовности.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13217,'Мяту с сахаром измельчаем в блендере.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13217,'Добавляем яйцо и сливочное масло, снова измельчаем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13217,'В миске смешиваем муку и разрыхлитель. Добавляем к муке смесь из блендера, перемешиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13217,'На противень выстелить пергаментную бумагу, руки смачиваем в воде и выкладывает печенье на бумагу, вилкой примять.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13217,'Выпекаем 20 минут в разогретой духовке до 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13218,'Кабачки очистить и порезать на кольца. Добавить соль, перемешать и оставить на 1 час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13218,'Каждое колечко обвалять в муке и обжарить на растительном масле с двух сторон до золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13218,'В майонез добавить чеснок пропущенный через пресс, мелко нарезанный укроп и перец, перемешать. Этой смесью можно смазать кабачки или подать их по отдельности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13219,'Нужно взять спелый авокадо. Порезать и поместить мякоть в чашу или в ступку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13219,'Туда же нарезать мелко помидор(без семян), кинзу, острый перец, лук, посолить и поперчить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13219,'Выжать сок лайма и смешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13219,'Авокадо нужно превратить в пюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13220,'Нарезаем лук и кольраби.','https://vkuso.ru/data/cache/data/a8/888d9708f5211a8_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13220,'Режем мясо брусочками.','https://vkuso.ru/data/cache/data/b1/c00bfd499152ab1_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13220,'Обжариваем лук и добавляем кольраби.','https://vkuso.ru/data/cache/data/02/feba8e7dd657502_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13220,'Чистим и нарезаем ананас.','https://vkuso.ru/data/cache/data/97/26e9b9c9ba23097_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13220,'Добавляем специи в мясо.','https://vkuso.ru/data/cache/data/f4/43568e222ba3bf4_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13220,'Кладем крахмал.','https://vkuso.ru/data/cache/data/4a/a3c1f51b49f854a_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13220,'Добавляем ананас и кокосовое молоко.','https://vkuso.ru/data/cache/data/7e/4568d2eef8b027e_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13220,'Обжариваем свинину.','https://vkuso.ru/data/cache/data/17/b32d9ecbd3bb317_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13220,'Соединяем ингредиенты.','https://vkuso.ru/data/cache/data/dd/7b2070d2091cfdd_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13220,'Подаем с рисом, пастой или картофелем. Приятного аппетита!.','https://vkuso.ru/data/cache/data/c5/f498ee9651a74c5_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13221,'В миску сложить зелень, клубнику нарезать, кусочки сыра фета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13221,'Арахис измельчить и добавить в салат.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13221,'Сделать заправку: оливковое масло + лимонный сок + соевый соус. Заправить ей салат.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13221,'Посыпать маком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13222,'В миску добавить рукколу, оливковое масло и выжать сок лимона, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13222,'Апельсин очистить от кожуры и нарезать крупными квадратиками, добивать в миску, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13222,'Семгу или лосось нарезать пластинами и выложить на салат.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13222,'Сверху выложить кусочками нарезанный сыр фета и рубленный грецкий орех.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13223,'Подготовить мясо: помыть, удалить пленки, нарезать кусками, залить деревянные шампуры водой и отставить в сторону, включить духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13223,'В глубокой миске до однородности смешать коричневый сахар, соевый соус, пасту карри, мед, уксус (пару ст. л.), масло (ст. л.), разделить на две части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13223,'Насадить кусочки ананасов, мясо и порезанный лук на шампуры. Застелить противень фольгой, переложить шампуры, облить часть соуса. Готовить азиатский шашлык из говядины с ананасом 10 минут, поливая соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13223,'Пока жарится мясо сварить согласно инструкции лапшу, сцедить воду, переложить в подходящую миску. Приправить маслом с уксусом, солью, нарезанной зеленью кинзы, размешать. Готовое мясо посыпать хлопьями красного перца (на любителя), подать вместе с лапшой и соусом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13224,'Кабачки и морковь очистить и натереть на терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13224,'Лук нарезать мелко и добавить к кабачкам с морковью. Перемешать, сложить в дуршлаг и оставить на 1 час, чтобы вышла лишняя вода.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13224,'Спустя час отжать лишнюю воду, сложить с тарелку. Добавить к содержимому яйцо и муку - перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13224,'На растительном масле обжарить оладьи с двух сторон до румяного цвета на среднем огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13225,'Кабачки нарезаем крупными ломтиками и обжариваем на среднем огне 20 минут, перемешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13225,'К кабачкам добавляем сливки и доводим до кипения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13225,'Всыпаем специи, соль и перемешиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13225,'В кастрюле крупно нарезаем картофель, вливаем 1.5 литра воды, добавляем лавровый лист и варим до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13225,'В блендере измельчаем все готовые ингредиенты и сырок. Разбавляем бульоном от картофеля до необходимой консистенции.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13226,'Смешать муку, разрыхлитель и какао.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13226,'В отдельной тарелке взбить яйца с сахаром (100 гр). Добавить молоко (160 мл) и растительное масло - перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13226,'Яичную смесь добавить к мучной смеси и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13226,'Форму смазать растительным маслом и залить тестом. Выпекаем в разогретой духовке 30 минут при температуре 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13226,'Вынимаем из формы и полностью остужаем. Затем вырезаем середину оставив при этом дно и бока.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13230,'Влить в рукав яблочный сок.','https://vkuso.ru/data/cache/data/40/d0de7ae0bb41940_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13354,'Нашинковать морковь и репчатый лук кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13226,'В ковш высыпаем желатин и заливаем молоком (200 мл). Оставляем на 30 минут. Затем ставим на медленный огонь пока не растворится желатин (!до кипения не доводить!)',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13226,'Сахар (80 гр) смешать с творогом. Затем влить содержимое ковша (желатин + молоко) и все тщательно перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13226,'В вырезанный торт сложить целиковые бананы на дно и залить творожной смесью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13226,'Остатки торта (те что вырезали) сложить в блендер и перемолоть в крошку. Посыпать ею торт и оставить в холоде на 3 часа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13227,'Куриную грудку нарезать небольшими кубиками. Болгарский перец освободить от семян и крупно нарезать. Перец чили нарезать кружочками, удалив семена.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13227,'На сковороде разогреть растительное масло, и на сильном огне обжарить курицу до готовности, помешивая. Переложить в миску.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13227,'На том же масле обжарить сладкий перец до мягкости в течении 7 минут. Готовый перец переложить в отдельную миску и накрыть пищевой пленкой и дать постоять так пару минут. Затем выложить на разделочную доску, удалить кожицу и нарезать небольшими кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13227,'Если используете свежие ананасы то их нужно протушить на сковороде с парой ложек воды под закрытой крышкой в течении 5 минут. Консервированные ананасы можно не тушить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13227,'Развести томатную пасту с водой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13227,'Добавить к ананасам остальные ингредиенты: курицу, перец, чили и разведенную томатную пасту (или кетчуп). Довести все до кипения и прогреть все вместе в течении пары минут. Посолить и добавить сахар по желанию',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13228,'Порезать на четвертинки куриные бедрышки, сложить в пластиковый пакет. Добавить кусочки цукини, кольца лука, всыпать орегано, пол-ложки (чайной) соли, ложку (чайную) перца, влить по паре ст.л. уксуса и масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13228,'Хорошо завязать пакет, чуть помять руками для перемешивания, отправить ночевать в холодильник. Если времени нет, то можно ограничиться только часом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13228,'Шампуры из дерева положить в воду минут на 20-30, разогреть гриль. Нанизать кусочки курицы вперемешку с цукини и луком. Поджарить куриный шашлык по-гречески с цуккини до готовности (13-15 минут).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13228,'Во время жарки шашлыка приготовить соус из сыра фета, мяты, йогурта и уксуса. Сложить все в чашу блендера, взбить до однородной  массы, подать к горячему шашлыку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13229,'Отвариваем картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13229,'Готовим соус: измельчаем мелко огурцы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13229,'Смешиваем майонез, сметану, куркуму, черный перец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13229,'Добавляем в соус вареные яйца, натертые на терке и измельченные огурцы. Все перемешиваем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13229,'Остывший вареный картофель нарезаем крупными кусочками, помещаем его в соус и перемешиваем так, чтобы каждый кусочек картофеля покрылся соусом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13229,'Перед подачей посыпаем измельченным зеленым луком и по желанию добавляем перец чили. Всем приятного!',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13230,'Свинину, лучше окорок, надрезать в в толстых местах и разложить, снова надрезать и разложить, формируя таким образом более тонкий и большой мясной лист примерно одинаковой толщины, насколько это возможно.','https://vkuso.ru/data/cache/data/6f/9260ec6095ced6f_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13230,'Накрыть мясо пленкой и хорошо отбить молоточком.','https://vkuso.ru/data/cache/data/78/fc0991077cb1278_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13230,'Посолить и поперчить, посыпать любыми сухими травами по своему вкусу.','https://vkuso.ru/data/cache/data/e8/ecb5345e94486e8_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13230,'Выложить на мясо половину указанного количества горчицы и всё равномерно распределить по верхней поверхности.','https://vkuso.ru/data/cache/data/c9/92e60c9ef993cc9_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13230,'Выложить на мясо разрезанные на несколько частей зубчики чеснока.','https://vkuso.ru/data/cache/data/9f/8d952521c71889f_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13230,'Осторожно свернуть из мяса плотный рулет. Если мясо гдето надрезано или неидеально ровной толщины, это нормално и не страшно.','https://vkuso.ru/data/cache/data/5a/460cc67ed07655a_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13230,'Натереть рулет еще раз оставшейся горчицей.','https://vkuso.ru/data/cache/data/eb/eaa55bdbe0337eb_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13230,'Перевязать рулет в нескольких местах толстой нитью поперек и вдоль, кончики обрезать.','https://vkuso.ru/data/cache/data/93/fdd4ecd3f29e193_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13230,'Перевязанные рулет положить в рукав для запекания, закрепленный с одной стороны.','https://vkuso.ru/data/cache/data/85/f64ce226b206085_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13230,'Скрепить рукав со второй стороны, уложить в любую форму или на противень, сверху сделать несколько проколов зубочисткой.','https://vkuso.ru/data/cache/data/b7/c83f9bb5b24f9b7_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13230,'Запекать рулет в заранее разогретой до 220 С духовке ровно 1 час.','https://vkuso.ru/data/cache/data/af/f94e7c70d87a5af_434x295_notrise.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13230,'Через час вынуть рулет из духовки, срезать верхнюю часть рукава, обильно полить рулет образовавшимся снизу соком.','https://vkuso.ru/data/cache/data/fa/7094a446bcba9fa_434x295_notrise.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13230,'Снова поставить в духовку на 5-7 мин с открытым верхом до легкого подрумянивания.','https://vkuso.ru/data/cache/data/04/cff0b1f2be57c04_434x295_notrise.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13230,'Осторожно срезать и удаоить с готового рулета нитки.','https://vkuso.ru/data/cache/data/95/a327fde38576f95_434x295_notrise.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13230,'Подавать готовый рулет можно как в горячем, так и холодном виде.','https://vkuso.ru/data/cache/data/f8/fee52b8c3176cf8_434x295_notrise.jpg',16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13230,'Мясной рулет из свинины можно подать как основное горячее блюдо с гарниром из овощей или как холодную закуску вместо магазинной нарезки.','https://vkuso.ru/data/cache/data/25/cceeb23e15ae425_434x295_notrise.jpg',17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13231,'Разогреть, как следует гриль, подготовить 16 шампуров, собрать шашлычки. Каждую креветку насаживать сразу на два шампура: хвост на один, а грудку на другой, чередовать с красным болгарским перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13231,'Приготовить из масла, рома, порошка карри, душистого и кайенского перца и соли соус, залить креветки, дать немного постоять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13231,'Слегка смазать грильную решетку маслом, разложить карибские шашлычки из креветок с болгарским перцем, обжарить со всех сторон по 3-4 минуты, сразу подать на стол с соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13232,'Нарезать на кусочки вырезку свинины, смешать мед с парой ложек ананасового сока, сдобрить перцем и соль, приготовить по описанию на упаковке рис, дать постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13232,'Разогреть гриль, чуть смазать маслом решетку, разложить шампуры с мясом и сладким перцем, поджарить. Шашлыки из свинины с ананасом в гриле будут готовы минут через 15. Во время жарки смазывать мясо ананасовым соком с медом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13232,'Нашинковать перья зеленого лука, натереть имбирь, смешать с рисом и кусочками ананаса (предварительно обсушить), добавить масло, сдобрить солью и перцем, перемешать, подать вместе с шашлыком, украсить кусочками лайма.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13233,'Куриную грудку отвариваем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13233,'Ананасы режем небольшими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13233,'Сыр натераем на средней тёрке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13233,'Чеснок давим чесночницей',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13233,'Грудку нарезаем небольшими кубиками или полосочками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13233,'Смешиваем всё в миске. Добавляем майонез и соль по вкусу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13233,'Ну вот и всё. Приятного аппетита!!!',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13234,'Свёклу отвариваем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13234,'Морковь и свелку натераем на средней тёрке',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13234,'Изюм промываем и замачиваем кипятком на 15 минут, чтобы он был мягким',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13234,'Грецкие орехи промываем и измельчаем до среднего размера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13234,'Итак, выкладываем первый слой. Свёклу смешиваем с грецким орехом. Промазываем майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13234,'Второй слой - морковь смешиваем с изюмом. Промазываем майонезом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13234,'Сыр натераем на мелкой тёрке и смешиваем с чесноком, пропущенное через чесночницу. Выкладываем третьим слоем. Промазываем майонезом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13234,'Киви нарезаем небольшими кубиками. Оно придаст салату кислинку и свежесть. Выкладываем четвёртым слоем. Промазываем майонезом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13234,'Салат готов, можно украсить на ваш взгляд. Мой вариант украшения показан на фотографии. Приятного аппетита!!!',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13235,'В теплом молоке растворить дрожжи и 1 чайную ложку сахара. Затем добавить 2 столовые ложки муки. Оставить на 1,5 часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13235,'Взбить яйца, добавить 3 столовые ложки сахара, ванилин, соль и 40 гр растопленного масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13235,'Смешать обе смеси, постепенно добавить муку. Оставить тесто в тепле на 1 час.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13235,'Тесто раскатать, смазать его сливочным маслом, посыпать сахаром и корицей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13235,'Свернуть в рулет, разрезать на порции.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13235,'Выложить на протвинь. Запекать при температуре 200°С до румяной корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13235,'На вкуснейшие булочки готовы. Приятного аппетита!!!',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13236,'Смешать 1 яйцо, муку и 40 мл молока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13236,'В отдельной ёмкости соединить 0.5 стакана сахара, 0.5 стакана молока (100мл). Нагреть полученную смесь на плите до растворения сахара, постепенно помешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13236,'Добавить тонкой струйкой в ёмкость со сладким молоком массу из яиц, муки и молока. Содержимое довести до кипения и про варить 1-2 минуты, не прекращая помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13236,'Снять с огня и остудить до комнатной температуры.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13236,'200г размягченного масла взбить миксером до получения пышной консестенции. Добавляя небольшими порциями в приготовленное заранее массу. По желанию можно добавить какао, коньяк, ванилин и так далее.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13236,'Крем готов к дальнейшему использованию.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13237,'Яйца взбить до бела. ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13237,'Добавить рязмягченное масло, соду, ванилин. Перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13237,'Добавить муку, замесить очень крутое тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13237,'Тесто пропустить через мясорубку. Выходящие из решётки жгутики, разложить небольшими пучками в виде печений на противень.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13237,'Выпекать в духовке около 15 минут при 180°С.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13237,'Готовые печенья можно посыпать сахарной пудрой. Приятного аппетита!!!',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13238,'Слегка бланшировать шпинат на сливочном масле, пока листья не уменьшаться в размере.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13238,'Смешать до однородной массы подготовленный шпинат с сыром Фета, сыром Рикотта, натертым зубчиком чеснока, двумя яйцами и орегано.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13238,'Тесто Фило слой за слоем выложить в форму оставляя края. Каждый слой смазать растопленным сливочным маслом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13238,'Начинку поместить поверх теста, разгладить и прикрыть оставшимися слоями теста. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13238,'Выпекать 30 минут при 180°С.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13238,'Дождаться остывания. Подать с вялеными томатами и черными оливками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13239,'Ржаную муку (100 г) залить теплой водой (100 мл).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13239,'Перемешать, оставить для заквашивания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13239,'Опару прикрыть марлей, оставить в тепле на сутки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13239,'Затем всыпать еще 100 г муки и долить 100 мл воды.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13239,'Через сутки повторить манипуляции.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13239,'Через трое суток операцию повторить, оставить смесь еще на сутки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13239,'Испечь хлеб, в тесто можно добавить тмин, кориандр, сухофрукты, нарезанные кусочками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13240,'Шишки хмеля залить кипящей водой (соотношение 1:2), довести до кипения, оставить на ночь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13240,'Наутро отвар процедить через сито, всыпать муку и сахарный песок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13240,'Ингредиенты перемешать, прогреть на водяной бане.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13240,'Поставить закваску в тепло на двое суток.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13241,'Подготовить свиную вырезку: помыть, зачистить, порезать кусками. Приготовить маринад из сока апельсина, цедры, тимьяна, чайной ложки соли, горчицы, масла, чеснока и половины чайной ложки молотого перца, вылить его в глубокую миску с мясом, прикрыть пленкой, дать полчаса постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13241,'Разогреть гриль, разложить шампуры с кубиками мяса, жарить шашлык из свинины с тимьяном и апельсином около 15 минут. Подать мясо прямо на шампурах, уложив на большое прямоугольное блюдо, сверху положить зеленые веточки тимьяна, а вокруг —  ломтики апельсина.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13242,'Капусту и морковь нашинковать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13242,'Лук нарезать мелко и отправить на сковороду. Жарить без масла.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13242,'Следом в сковороду отправляем капусту и морковь. Жарим также без масла до появления поджаристой корочки и следов на дне сковороды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13242,'Добавить к капусте немного масла и куриный бульон. Все хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13242,'Добавить нарезанные копчености - охотничьи колбаски и сардельки. Добавить тмин. Тушить 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13242,'В конце приготовления добавить мелко нарезанный укроп.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13242,'Подавать со сметаной.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13243,'Сварить рис согласно инструкции на упаковке, всыпать размороженный зеленый горошек, перемешать и убрать в нагретую до 100 гр. духовку, чтобы гарнир остался теплым.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13243,'Поместить в небольшую миску горчицу, мед, сдобрить солью и молотым перцем, тщательно взбить, разделить соус на две части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13265,'Выложить голубцы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13243,'Нарезать мясо и апельсины на куски, насадить на шампуры, присолить и поперчить. Поджарить шашлык на разогретой и смазанной маслом решетке гриля по 6-7 минут со всех сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13243,'Шашлык из свинины с медом и апельсинами полить частью соуса прямо на гриле, оставить па пару-тройку минут. Подать к горячему шашлыку  рис с горошком и оставшийся соус.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13244,'Натереть цедру одного целого лимона.','https://vkuso.ru/data/cache/data/e4/d983e096e99f8e4_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13244,'Лимон нарезать небольшими кубиками.','https://vkuso.ru/data/cache/data/37/0f9277245fa4837_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13244,'Добавить к нарезанному лимону 2 ст л сахара и перемешать.','https://vkuso.ru/data/cache/data/58/af37c096df39858_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13244,'Сливочное масло комнатной температуры хорошо растереть вилкой со всем оставшимся сахаром.','https://vkuso.ru/data/cache/data/b4/61d2a616125ecb4_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13244,'Влить к смеси масла с сахаром яйца и добавить щепотку соли, все хорошо перемешать и слегка взбить вилкой до растворения сахарных крупинок.','https://vkuso.ru/data/cache/data/d3/ca0a0d96ec761d3_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13244,'Добавить сметану и хорошо перемешать венчиком или вилкой.','https://vkuso.ru/data/cache/data/b8/1f8f47a8b91d3b8_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13244,'В муку добавить разрыхлитель и перемешать.','https://vkuso.ru/data/cache/data/6e/29e70a8007bd36e_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13244,'В несколько приемов просеять в жидкую смесь муку, постоянно перемешивая тесто до однородности.','https://vkuso.ru/data/cache/data/c8/69fdb3989475fc8_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13244,'В тесто положить лимоны с сахаром, лимонную цедру и ванильный сахар, все хорошо перемешать ложкой.','https://vkuso.ru/data/cache/data/1d/925ea4a134f531d_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13244,'Вылить тесто в форму для выпечки и разровнять поверхность. Силиконовую форму не смазывать, любую другую форму хорошо смазать сливочным маслом.','https://vkuso.ru/data/cache/data/4b/3359399763c634b_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13244,'Выпекать пирог при 180 С в заранее разогретой духовке 50 мин до выраженной румяности и готовности. Готовность можно проверить зубочисткой. При прокалывании пирога она должна оставаться сухой.','https://vkuso.ru/data/cache/data/59/7435aba01aa2c59_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13244,'Дать пирогу немного остыть и извлечь из формы (удобнее всего это сделать способом переворачивания двух тарелок).','https://vkuso.ru/data/cache/data/f0/e2970ccf47f6ff0_434x295_notrise.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13244,'Посыпать пирог по желанию поджаренным измельченным арахисом и сахарной пудрой.','https://vkuso.ru/data/cache/data/fa/de849f26cc664fa_434x295_notrise.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13244,'Готовый пирог можно сразу подавать к столу.','https://vkuso.ru/data/cache/data/5c/e85d0722ea2e55c_434x295_notrise.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13244,'Лимонный воздушный пирог отлично подходит к любому чаепитию.','https://vkuso.ru/data/cache/data/21/b6415d8d75e9421_434x295_notrise.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13245,'Подготовить свиную вырезку, разогреть гриль, порезать на 8 частей зеленое кислое яблоко и лук. Приготовить пикантный соус из томатной пасты, джема, уксуса и столовой ложки масла, сдобрить солью и черным молотым перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13245,'Насадить на длинные шампуры мясо, кусочки яблока и лук, смазать остатками масла, поместить на смазанную маслом решетку гриля. Обжарить шашлык из свинины и яблок на гриле по 3-4 минуты с каждой стороны. В конце приготовления равномерно полить шампуры соусом и жарить еще 5-7 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13246,'Готовим опару: в теплое молоко добавляем 4 ст. л. сахара и дрожжи, перемешиваем и отставляем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13246,'Размягченное масло нарезаем кубиком и добавляем его в предварительно просеянную муку, добавляем соль и перетираем в крошку.Добавляем в мучную крошку опару и замешиваем тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13246,'Накрываем тесто пищевой пленкой и отправляем в холодильник на 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13246,'Готовим начинку: Лимоны помещаем в кипяток на 10 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13246,'Остывшее тесто делим на 3 части.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13246,'Раскатываем каждую часть теста на пергаменте. Выравниваем края, чтобы получился прямоугольник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13246,'Первый слой на пергаменте перекладываем на лист для выпечки и выкладываем на него половину начинки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13246,'Таким же образом раскатываем второй корж. Выкладываем сверху на первый корж и снимаем пергамент.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13246,'На второй корж выкладываем оставшуюся начинку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13246,'Третий корж раскатываем как второй и выкладываем сверху. Защипываем края.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13246,'Отправляем в разогретую духовку на 170 градусов примерно на 35-40 минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13246,'После выпекания, обрезаем края, разрезаем лимонник на квадратики и посыпаем сахарной пудрой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13247,'В сотейнике растопить сливочное масло, добавить подсолнечное.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13247,'Продукты перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13247,'Всыпать муку порциями, в массе не должно быть комочков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13247,'Влить молоко, смесь продолжать помешивать, довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13247,'Всыпать соль по вкусу, продолжать заваривать массу на тихом огне, время приготовления – десять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13247,'Если соус получился слишком густым – добавить молока, если жидкий – поварить еще немного.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13247,'Подать соус к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13248,'Масло или спред прогреть, добавить муку, жарить в сотейнике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13248,'Влить мясной или овощной бульон в готовую смесь, варить до загустения.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13248,'Соль и перец молотый – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13248,'В конце приготовления соуса добавить в него сырые куриные желтки, продукты перемешать, прогреть на тихом огне две минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13248,'Нарезать каперсы, всыпать в готовый соус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13249,'Нужно поставить бульон и сковородку с масло разогреваться.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13249,'В сковородку добавим мелко нарезаный лук и слегка обжарим.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13249,'Далее добавим рис и тоже обжарим.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13249,'Зальём вино и выпарим, после постепенно нужно добавлять бульон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13249,'В стакане зальём небольшое кол-во бульона, шафран и перемешаем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13249,'За пару минут до готовности вольём шафран.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13249,'По готовности ризотто выключим плиту и засипим сыр.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13250,'Подготовить мясо для шашлыка: помыть, зачистить от пленок, обсушить, порезать кусками. Переложить его в подходящую емкость, подсолить, поперчить (только не увлекайтесь!), тщательно перемешать. Порезать мелко базилик, лук (помять руками до выделения сока), смешать с мясом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13250,'Взять глубокую кастрюлю, уложить на дно довольно толстый слой лука, а на него – мясо и т.к. далее. Последним слоем должен быть лук. Отправить кастрюлю часа на 4 в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13250,'Дальше поступать как обычно: насадить мясо на шампуры и обжарить шашлык из свинины с базиликом в собственном соку над углями костра до готовности. Подать с маринованным луком, зеленью, кетчупом, овощами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13251,'Картофель обмыть, почистить.','https://vkuso.ru/data/cache/data/d4/b9d09e66b9669d4_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13251,'Нарезать не большими кубиками или брусочками, как вам больше нравится.','https://vkuso.ru/data/cache/data/0b/289ca49325a970b_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13251,'Кастрюлю с водой поставить на средний огонь. Воду подсолить. Высыпать картофель. Во время готовки накипь снимать обязательно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13251,'Морковь обмыть, почистить. Далее натереть на средней тёрке. Морковь обжарить в небольшом количестве масла. После высыпать в кастрюлю с картофелем.','https://vkuso.ru/data/cache/data/78/dcf6a927ea64478_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13251,'Займёмся фаршем. В него нужно добавить соль, перец. Можно добавить специи к мясу, но это на ваше усмотрение. Хорошо перемешать.','https://vkuso.ru/data/cache/data/80/d73a9e2e7ea6480_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13251,'Далее формируем небольшие фрикадельки. За 15 минут до окончания готовки (нужно смотреть по готовности картофеля) выкладываем фрикадельки в кастрюлю.','https://vkuso.ru/data/cache/data/80/3c5c1b5d7b87a80_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13251,'Зелень обмываем, шинкуем.','https://vkuso.ru/data/cache/data/00/4e955ba468f8700_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13251,'За 2 минуты до окончания готовки высыпаем зелень. После готовности накрываем крышкой.','https://vkuso.ru/data/cache/data/6d/636b4903094596d_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13252,'Мясо промыть, обсушить и нарезать небольшими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13252,'Морковь обмыть и натереть на средней тёрке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13252,'Лук почистить и мелко нарезать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13252,'В казан или высокую сковороду поставить на средний огонь и наливать туда 1,5 см подсолнечного масла.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13252,'Высыпать туда мясо, постоянно помешивать.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13252,'Когда лук немного обжариться, высыпать морковь. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13265,'Выставить подходящую программу на сорок или сорок пять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13252,'Поставить на медленный огонь.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13252,'Добавить 4 стаканы воды, 2 стакана риса и специи.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13252,'Когда вода впитается и рис будет готов, выключить огонь и оставить под крышкой на 20 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13252,'Вкусный плов готов. Приятного аппетита!',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13253,'Сливочное масло растопить в сотейнике.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13253,'Всыпать муку, помешивать и прогревать массу до тех пор, пока она не станет золотистой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13253,'Время приготовления – не более двух минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13253,'Ввести молоко порциями, комочки разбивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13253,'Соус должен стать однородным, огонь – медленный.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13253,'В густеющую массу всыпать молотый мускатный орех, белый перец.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13254,'В небольшой емкости с антипригарным покрытием соединить репчатый лук и молоко. Лук не резать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13254,'Варить пятнадцать минут на тихом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13254,'Лук вынуть и выбросить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13254,'Отдельно растопить сливочное масло, всыпать муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13254,'Прогреть продукты четыре минуты на тихом огне, помешивать до тех пор, пока продукты не станут золотистыми.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13254,'Массу остудить, ввести молоко.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13254,'Еще раз поставить соус на плиту, варить десять минут, помешивать, до кипения не доводить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13254,'Готовый соус процедить через ситечко, всыпать специи.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13254,'На сковороде спассеровать смесь говяжьего и свиного фарша с добавлением корней петрушки и сельдерея.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13254,'Мясо всыпать в основной соус, варить десять минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13255,'Порезать с вечера мякоть баранины на небольшие куски, пересыпать молотым душистым перцем, хорошо вымешать руками. Добавить к мясу ворчестерский соус, оливковое масло, зелень петрушки, лимонный сок, измельченный чеснок и лук, отправить ночевать в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13255,'Подготовить в мангале угли, нанизать мясо на шампуры, чуть присолить, обжарить шашлык из баранины по-восточному до готовности появления всеми любимой поджаристой корочки. Появляющееся периодически пламя гасить, поливая шампуры пивом или водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13256,'Муку смешать с содой и солью, добавить масло и превратить в крошку, затем добавить сметану и все собрать в один комок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13256,'Далее муку смешиваем с сахаром добавляем масло и делаем более рассыпчатую крошку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13256,'Орехи мелко нарезаем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13256,'Яйцо - отделяем белок от желтка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13256,'Тесто раскатываем, смазываем белком и посыпаем крошку, затем арахис, далее сворачиваем в рулет, смазываем желтком и разрезаем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13256,'Выпекаем при 180 градусах примено 30 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13257,'Мясо и лук пропускаем через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13257,'Добавляем специи и рис и все перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13257,'Далее берем виноградные листья, кладем мясо и заворачиваем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13257,'Перекладываем в кастрюлю, где будем варить, заливаем водой и варим 30 минут на тихом огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13258,'Яйца разбивает в глубокую тарелку, добавляем сахар и все хорошо взбиваем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13258,'Кокосовую стружку пересыпаем в миску, вливаем взбитые яйца с сахаром и все хорошо перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13258,'Из полученной массы делаем средние шарики и перекладываем их на противень.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13259,'Сливочное масло растопить в емкости с антипригарным покрытием.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13259,'Добавить просеянную муку, жарить продукты до получения золотистого оттенка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13259,'Нарезать репчатый лук, добавить в основную массу, прожарить еще немного, влить молоко порциями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13259,'Смесь довести до кипения, немного остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13259,'Протереть продукты через сито.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13259,'Влить мясной бульон, воду или молоко.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13259,'Еще раз довести до кипения.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13259,'Всыпать твердый сыр, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13259,'Варить массу до полного растворения сыра и нужной консистенции.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13259,'Всыпать специи, варить десять минут, дать соусу постоять.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13260,'Белые грибы или шампиньоны очистить, вымыть, нарезать кусочками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13260,'Растопить сливочное масло в сотейнике, всыпать муку, жарить до получения золотистого оттенка, время – от одной до двух минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13260,'Соус постоянно помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13260,'Ввести молоко небольшими порциями, разбить комочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13260,'Сырые куриные желтки размешать в оставшемся молоке, влить массу в основную смесь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13260,'Влить грибной бульон, остатки молока.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13260,'Варить на тихом огне до закипания, помешивать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13260,'В почти готовый соус всыпать грибы, варить все вместе пятнадцать минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13260,'В конце приготовления добавить немного сливочного масла.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13261,'Целые листья белокочанной капусты размягчить в микроволновой печи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13261,'Процедуру можно проделать в кастрюле с кипятком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13261,'Промыть рис горячей водой, отварить почти до готовности, выставить режим «Выпечка».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13261,'Готовый продукт промыть, перемешать с фаршем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13261,'Нарезать лук, натереть морковь, овощи спассеровать на масле.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13261,'Выложить начинку из мяса и крупы на капустные листья, завернуть треугольниками или конвертиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13261,'Изделия выложить в емкость, пересыпать слои овощной обжаркой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13261,'Залить продукты водой, перемешанной с солью и томатной пастой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13261,'Выставить режим «Тушение» на 120 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13262,'Воду посолить по вкусу, отварить рис.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13262,'Готовый продукт промыть холодной водой, перемешать с фаршем, приготовленным из свинины и говядины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13262,'По периметру кочерыжки сделать надрезы, опустить овощ в кипяток на восемь или девять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13262,'Приготовить соус из моркови и лука.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13262,'К продуктам добавить сметану, соль, томатную пасту, сахарный песок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13262,'Потушить смесь в течение десяти или двенадцати минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13262,'Сформовать голубцы из белокочанной капусты и начинки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13262,'Толстые прожилки срезать острым ножом или отбить молоточком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13262,'Изделия положить в соус, полить им же блюдо сверху.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13262,'Время тушения – от сорока пяти до пятидесяти пяти минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13263,'Рис отварить до готовности, перемешать с фаршем, посолить, добавить давленый чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13263,'Белокочанную капусту отварить в кипящей воде до мягкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13263,'Утолщения срезать острым ножом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13263,'На каждый листик выложить начинку, свернуть конвертом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13263,'Мультиварку смазать маслом, выложить голубцы, посыпать нарезанными или натертыми овощами: морковью, репчатым луком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13263,'Приготовить соус из жирной сметаны, воды, соли и «Кетчупа».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13263,'Добавить любые специи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13263,'Полить соусом голубцы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13263,'Выставить режим «Тушение», а затем «Выпечка» на двадцать или двадцать пять минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13264,'Фарш посолить по вкусу, добавить немного соуса «Кетчуп» или обычного томатного и давленый чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13264,'Массу перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13264,'Белокочанную капусту выложить в кастрюлю, кипятить пять или шесть минут, снять листья, варить их еще столько же в той же воде.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13264,'Отварить рис.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13264,'Завернуть начинку из мяса и риса в каждый лист.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13264,'Спассеровать на растительном масле репчатый лук и морковь, залить мясным или овощным бульоном, добавить смесь томатного сока и сметаны.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13264,'Смесь посолить по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13264,'Тушить от двенадцати до четырнадцати минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13264,'Положить в соус голубцы, готовить в режиме «Тушение» от получаса до тридцати пяти минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13265,'Белокочанную капусту погрузить в кипяток на две минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13265,'Чеснок пропустить через пресс, перемешать с говяжьим фаршем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13265,'Посыпать начинку приправами, солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13265,'Выложить массу на подготовленные листья, завернуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13265,'Налить воду в мультиварку, довести до кипения, поставить решетку для варки на пару.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13266,'Приготовить фарш из свинины, смешать с отваренным рисом, массу посолить и поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13266,'Мелко нарезать морковь, белокочанную капусту, сладкий болгарский перец, репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13266,'Овощи обжарить на масле, режим «Выпечка».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13266,'Фарш с рисом отправить к овощам, выставить режим «Тушение» на восемьдесят или девяносто минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13267,'Листья пекинской капусты выложить в горячую воду на несколько минут для размягчения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13267,'Приготовить начинку из любого мясного фарша, вареного риса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13267,'Смесь посолить, поперчить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13267,'Начинку выложить на листья, завернуть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13267,'Измельчить репчатый лук и морковь, обжарить овощи в режиме «Выпечка».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13267,'Поверх обжарки выложить небольшие голубцы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13267,'Полить блюдо соусом, приготовленным из сметаны, томатной пасты, воды.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13267,'Соль – по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13267,'Выставить режим «Тушение» на час или семьдесят минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13268,'Филе горбуши нарезать кусками, переложить в большую кастрюлю с водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13268,'Морковь и репчатый лук, картофель очистить, добавить овощи в суп в цельном виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13268,'Довести до кипения, варить десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13268,'Продукты вынуть, бульон процедить через сито или марлю.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13268,'Влить в уху водку, всыпать промытую пшенку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13268,'Вынуть из рыбного филе кости, мякоть положить обратно в суп.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13268,'Добавить лавровый лист и морковь, нарезанную кружками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13268,'Довести блюдо до кипения еще раз, варить десять минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13268,'Всыпать рубленый свежий укроп, кипятить три минуты.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13268,'Уху разлить в тарелки горячей.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13269,'Очистить клубни картофеля, мякоть нашинковать кубиками, выложить в кастрюлю, залить водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13269,'Довести до кипения, варить около десяти минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13269,'На сковороде растопить сливочное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13269,'Горбушу очистить, филе нарезать кубиками и обжарить в течение минуты вместе с рубленым луком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13269,'Содержимое сковороды переложить в кастрюлю, варить пятнадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13269,'Влить сливки, прогревать еще пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13269,'Всыпать соль и перец, суп перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13269,'Настаивать в течение пяти минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13270,'Филировать скумбрию. ','https://vkuso.ru/data/cache/data/b0/c2bd2865e2095b0_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13270,'Нарезать лук, натереть морковь. ','https://vkuso.ru/data/cache/data/83/ee82870a12dc683_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13270,'Обжарить лук, добавить морковь. ','https://vkuso.ru/data/cache/data/81/18006b6882a1981_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13270,'Растолочь перец. 
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13270,'Филе посолить, поперчить. ','https://vkuso.ru/data/cache/data/91/b841f5438a7aa91_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13270,'Положить начинку и свернуть рулетики. ','https://vkuso.ru/data/cache/data/bd/adb4649eafab9bd_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13270,'Обвязать шпагатом. ','https://vkuso.ru/data/cache/data/a9/b973747c1ea0fa9_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13270,'Положить на противень. ','https://vkuso.ru/data/cache/data/71/f59de9e44876071_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13270,'Добавить сливочное масло. ','https://vkuso.ru/data/cache/data/65/d744169a8ef4265_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13270,'Запекать при температуре 180°C 20 мин.','https://vkuso.ru/data/cache/data/f4/f4dd29db816abf4_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13271,'Для начала необходимо приготовить омлет. Для этого на раскаленной сковороде жарят взбитые яйца и аккуратно перекладывают готовый омлет на тарелку. Свернуть омлет трубочкой и порезать толщиной около 1 см.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13271,'Получаться длинные полоски. На эту же сковороду добавить немного масла и  обжарить горошек, кукурузу и порезанный сладкий перец кубиками. Жарить овощи 2 минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13271,'В обжаренные овощи добавить креветки, жарить 2 минуты. Когда креветки начнут менять цвет на розовый, высыпать в сковороду рис. Всю массу обжарить еще 3 минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13271,'В рис с креветками и болгарским перцем добавить порезанный омлет, порезанный мелко зеленый лук и соевый соус. Накрыть крышкой сковороду и пропарить все около минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13272,'Готовим начинку: измельчаем лук и обжариваем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13272,'Добавляем капусту к луку, предварительно отжав от сока. Тушим до мягкости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13295,'Говяжью грудинку натереть приправами, перцем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13272,'Замешиваем тесто: смешиваем яйца со сметаной, солью, сахаром, разрыхлителем и добавляем муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13272,'Капусту выкладываем в форму для выпечки, смазанную маслом, и сверху выливаем жидкое тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13272,'Помещаем в разогретую духовку на температуру 180 градусов примерно на 25-30 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13273,'Яйца взобьем с щепоткой соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13273,'Далее добавим сахар и взбиваем до получения пышной и белой консистенции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13273,'Далее постепенно добавим муку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13273,'Переложим в форму для выпечки и отправим в разогретую до 180 градусов духовку на 30 минут. Этот бисквит подходит для любого торта.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13274,'Сделайте кляр, смешав яйцо, крахмал, муку, растительное масло и воду. Тесто должно иметь густоту, как на оладьи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13274,'Очищенные от кожуры бананы нарежьте крупными кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13274,'В сковороде с толстым дном прогрейте 1,5 стакана растительного масла. Обмакивая каждый кусок банана в кляре сразу опускайте в разогретый фритюр - готовьте, поворачивая лопаткой, до румяной корочки со всех сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13274,'На другой сковороде приготовьте карамель добавив в разогретое растительное масло сахар и воду. На самом малом огне уваривайте ее до светло-жёлтого цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13274,'Выложите обжаренные бананы в карамель. Переворачивая с помощи лопатки покройте карамелью каждый кусочек.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13274,'Готовые бананы в сладкой карамели перед подачей посыпьте кунжутом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13275,'Приготовить бульон из овощей: нарезать сельдерей и морковь на куски крупного размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13275,'Влить в кастрюлю воду, добавить очищенную от шелухи луковицу, две картофелины, нарезанный репчатый лук и зелень сельдерея.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13275,'Довести бульон до кипения, варить полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13275,'Огонь погасить тогда, когда картофель станет мягким.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13275,'Овощи вынуть, картофель помять вилкой и вернуть в кастрюлю.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13275,'Пшенную крупу промыть холодной водой, оставшийся картофель нарезать небольшими кубиками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13275,'Морковь очистить нарезать половинками кружков.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13275,'Зелень петрушки промыть и порубить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13275,'Выложить в уху картофельные кубики и горбушу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13275,'Варить пять минут, затем добавить перец-горошек, лавровый лист и пшенную крупу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13275,'Спустя четверть часа выложить морковь, подсоленную томатную пасту.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13275,'Через пять минут всыпать зелень, огонь погасить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13275,'Посыпать блюдо черным молотым перцем перед подачей на стол.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13276,'Брюшки положить в кастрюлю, влить большое количество воды, довести до кипения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13276,'Пенку снять ложкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13276,'Добавить очищенный лук, перец-горошек, соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13276,'Все вместе варить около получаса, огонь – минимальный.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13276,'Еще одну луковицу мелко нарезать, порубить картофель кубиками, натереть сырую морковь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13276,'Вынуть горбушу из бульона, уху процедить, жидкость влить обратно в кастрюлю.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13276,'Вынуть из рыбного филе мелкие кости, мякоть оставить до окончания варки супа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13276,'Выложить в кастрюлю овощи, варить все вместе пятнадцать минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13276,'Добавить лавровый лист, нарезанные кубиками помидоры, варить еще десять минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13276,'Всыпать промытую пшенку, варить уху до мягкости крупы.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13276,'Добавить в суп нарезанную зелень петрушки, рыбные брюшки и черный молотый перец.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13276,'Оставить уху для настаивания на пятнадцать минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13277,'Разрезать тушку горбуши на порционные куски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13277,'Покрошить кубиками морковь и картофель. Картофельные кусочки должны быть побольше.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13277,'Довести воду в кастрюле до кипения, всыпать соль и картофель, кипятить пять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13277,'Всыпать морковь, положить целую луковицу без шелухи.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13277,'Добавить рис, варить суп десять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13277,'Добавить рыбу, пряности, кипятить уху пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13277,'Добавить рубленую петрушку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13277,'Настоять блюдо в течение пятнадцати минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13278,'Налить воду в чашу мультиварки, всыпать соль, выставить режим «Суп».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13278,'Картофель нарезать соломкой, всыпать в чашу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13278,'Очистить горбушу, морковь и лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13278,'Морковь натереть, лук нарезать кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13278,'Продукты добавить в мультиварку, варить двадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13278,'Добавить рыбу, лучше, если она будет в цельном виде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13278,'Через пятнадцать минут горбушу вынуть, выложить на тарелку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13278,'Вынуть кости, филе нарезать кусочками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13278,'Переложить обратно в уху.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13279,'Открыть консервы, размять рыбу с помощью вилки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13279,'Репчатый лук очистить и нарезать полукольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13279,'Картофель нарезать кубиками небольшого размера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13279,'Морковь натереть на терке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13279,'Рис промыть через дуршлаг, вода должна стать прозрачной.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13279,'Порубить ножом хорошо промытую зелень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13279,'В посуду налить воду, довести до кипения, всыпать рис.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13279,'Через десять минут всыпать картофель, перец-горошек, положить лавровый лист.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13279,'На небольшой сковороде спассеровать морковь с луком на растительном масле.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13279,'Переложить обжарку в уху, поварить двадцать минут, добавить консервированную рыбу.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13279,'Всыпать большую часть зелени, варить пять минут, посолить по вкусу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13279,'Блюдо настоять под крышкой десять минут, всыпать остатки зелени, подать блюдо на стол горячим.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13280,'Есть два способа приготовления: пельмени сначала отваривают, а затем обжаривают.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13280,'Второй – обжаренные замороженные полуфабрикаты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13280,'В первом случае продукт жарят на сливочном масле, способ более деликатный.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13280,'Можно использовать вчерашние пельмени, постоявшие в холодильнике.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13280,'При варке желательно добавить коренья, лавровый лист, масло хорошо разогреть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13280,'Второй рецепт подразумевает получение аппетитной, хрустящей корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13280,'Продукт нужно хорошо прогреть, чтобы начинка не осталась сырой. Посыпать блюдо травами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13281,'Прогреть сковороду, влить небольшое количество растительного масла.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13281,'Продукт должен закипеть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13281,'Выложить замороженные пельмени, сразу перемешать, пока не слиплись.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13281,'Накрыть сковороду крышкой, жарить до румянца с одной стороны, огонь – сильный.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13281,'Крышку снять, пельмени перевернуть, также обжарить до румяной корочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13281,'Блюдо посолить по вкусу в процессе приготовления, можно поперчить, посыпать приправами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13281,'Прожаренные пельмени залить водой до половины, держать сковороду открытой до тех пор, пока вся вода не выкипит.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13282,'Сырые куриные яйца взбить с молоком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13282,'Пельмени разморозить, смочить в яичном льезоне, обмакнуть в панировочные сухари, выложить на сковороду с разогретым маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13282,'Температура – средняя.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13282,'Жарить в течение десяти минут без крышки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13282,'Подрумяненные с одной стороны пельмени перевернуть и дожарить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13283,'Самый простой вариант – посыпать уже обжаренные с двух сторон пельмени тертым твердым сыром и потомить на открытой сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13283,'Другой вариант блюда: обжарить пельмени обычным способом, а затем залить соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13283,'Для приготовления соуса в пассеровку влить майонез и сметану, довести до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13283,'Смазать противень растительным маслом, выложить готовые обжаренные пельмени, полить сметанным соусом, посыпать сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13283,'Далее блюдо поставить в духовой шкаф на десять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13283,'Готовое блюдо посыпать рубленой зеленью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13284,'Чашу мультиварки смазать растительным маслом, выложить пельмени, готовить в режиме «Выпечка» в течение сорока минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13284,'Сначала обжарить одну сторону, затем изделия перевернуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13285,'На растительном или сливочном масле обжарить репчатый лук, нарезанный полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13285,'Положить в обжарку замороженные пельмени, перемешать, жарить до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13285,'В конце приготовления добавить измельченный зубчик чеснока.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13285,'Второй способ: обжарить пельмени до корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13285,'Отдельно обжарить нарезанное сало с прослойками мяса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13285,'На вытопленном жире приготовить луковую обжарку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13285,'Продукты выложить на готовые пельмени, добавить давленый зубчик чеснока.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13285,'Блюдо потомить несколько минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13286,'Один из вариантов – купить в магазине замороженную овощную смесь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13286,'Более традиционный – использовать отличное сочетание цветной и брюссельской капусты, сладкого болгарского перца, репчатого лука и моркови.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13286,'Самое простое сочетание продуктов – лук, морковь, томатная паста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13286,'Морковь натереть, все остальные овощи нарезать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13286,'Обжарить продукты на растительном или сливочном масле.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13286,'Отдельно обжарить пельмени до готовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13286,'Овощную смесь выложить поверх основного продукта, влить томатную пасту, разведенную в воде, поварить несколько минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13287,'Грудинку вымыть и обсушить, сделать надрезы, нашпиговать чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13287,'Приготовить смесь из сахарного песка, соли, перца черного молотого, имбиря, перца чили.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13287,'Натереть мясо, дать пропитаться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13287,'Выложить продукт на сложенный вдвое лист фольги, сверху – лавровые листочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13287,'Обернуть продукт фольгой так, чтобы не осталось щелей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13287,'Время запекания – двадцать минут, температура – 200 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13287,'Огонь убавить до 170 градусов, готовить полтора часа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13287,'Огонь выключить, продержать мясо в духовке еще двадцать минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13287,'Вынуть, подать на стол.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13288,'Для приготовления теста следует взбить охлажденные яйца и сахар в пышную массу. Постепенно добавить сгущенное молоко, взбить и затем сметану.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13288,'Всю пышную массу тщательно взбить миксером на средних оборотах. Аккуратно в массу добавлять муку, смешанную с какао, мешая венчиком, чтобы пышность не осела.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13288,'Соду погасить уксусом и вмешать в тесто. Подготовленную форму для выпекания застелить пергаментной бумагой и вылить туда тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13288,'Выпекать тесто в разогретой духовке до 180 градусов 25 минут. Готовность проверить спичкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13288,'Охлажденное тесто разрезать на несколько равных частей, чем уже корж, тем сочнее получиться торт. Для приготовления крема взбить сливки, постепенно добавить сахар.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13288,'Если вместо сахара добавить пудру, то пышность крема будет намного больше, а торт с клубникой и сливочно-банановым кремом вкуснее (сахарной пудры потребуется меньше в два раза, чем сахара).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13288,'Порезанные коржи смазать кремом, перекладывая кружочками бананов. Последний слой смазать обильно сливочным кремом и посыпать кокосовой стружкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13288,'Бока торта обильно обсыпать стружкой. Украсить торт свежей ароматной клубникой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13289,'Для приготовления блюда понадобится свежий, качественный продукт.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13289,'Приготовить смесь пряностей: любые специи для мяса, соль, молотый перец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13289,'Натереть мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13289,'Смазать маслом противень, выложить нашинкованный кольцами репчатый лук, сверху – кусок свинины.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13289,'Обложить продукт лавровым листом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13289,'Сделать проколы острым ножом крест-накрест.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13289,'Вложить в них кусочки чеснока.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13289,'Влить немного воды, запекать в духовом шкафу в течение полутора часов, температура – 180 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13289,'Мясо можно прикрыть фольгой, тогда получится грудинка без корочки.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13290,'Перемешать жидкий натуральный мед, растительное масло, соевый соус и лимонный сок с пряностями: семенами и готовой столовой горчицей, прованскими травами, молотым черным перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13290,'Куриную грудку хорошо вымыть, удалить жилки, пленки, разрезать на несколько частей, обсушить салфетками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13360,'Выложить готовые изделия на противень.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13290,'Залить продукт готовым маринадом, поставить для пропитывания в холод на два или три часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13290,'Выложить мясо в форму для запекания, время приготовления – один час, температура – от 180 до 190 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13290,'Важно, чтобы курица не пересохла, поливать мясо выделяющимся соком.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13290,'Блюдо подать горячим.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13291,'Смешать растительное масло с готовой и зерновой горчицей, солью, молотым перцем, сухой аджикой, измельченным чесноком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13291,'Смесью натереть грудинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13291,'Оставить продукт для пропитывания в холодильнике на час или два.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13291,'Морковь очистить и крупно нарезать, разрезать на четыре части репчатый лук.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13291,'Курагу промыть и обсушить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13291,'Вложить мясо в рукав, добавить овощи, курагу, рукав завязать, сделать проколы для выхода пара.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13291,'Время запекания – один час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13291,'Пакет разрезать, грудинку полить соком, запекать еще двадцать минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13291,'Должна получиться румяная корочка.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13291,'Готовый продукт выложить на блюдо, украсить зеленью и овощами.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13292,'Свиную грудинку нарезать крупными кусками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13292,'Посыпать специями, посолить, поперчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13292,'Очистить клубни картофеля, нарезать большими дольками, положить на противень и полить сваренным заранее куриным бульоном.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13292,'Сверху – нарезанный тонкими кольцами очищенный репчатый лук, соль – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13292,'Мясо выложить на луковую подушку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13292,'Затянуть форму листом фольги, печь в течение двух или трех часов, температура – от 170 до 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13292,'За полчаса до готовности снять фольгу, мясо допечь до получения румяной корочки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13293,'Картофель и морковь очистила, варила овощи до готовности.','https://vkuso.ru/data/cache/data/33/b678e2e81d5eb33_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13293,'Пока овощи варились, приготовила  начинку:  нарезала  большую головку репчатого лука, мелко нарезала грибы.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13293,'Когда картофель и морковь сварились, слила жидкость. С помощью картофелемялки сделала пюре, блендер для приготовления пюре не использую, так как он сделает пюре слишком липким. Посолила по вкусу. Дала ему остыть так, чтобы можно было спокойно брать руками.','https://vkuso.ru/data/cache/data/8f/8134200f0dc4a8f_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13293,'Добавила муку и вымесила тесто. Затем отщипнула немного и сделала лепешку величиной с ладонь, положила начинку и защипнула как пирожки. Затем сформировала котлетку.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13293,'Жарила на среднем огне до румяной корочки с каждой стороны.','https://vkuso.ru/data/cache/data/46/628c987362d0346_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13293,'Надеюсь, Вам понравятся. Приятного аппетита!','https://vkuso.ru/data/cache/data/0e/9a6cba8e24fa20e_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13294,'Отделяем белки от желтков. Белки отправляем в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13294,'Желтки взбиваем с сахаром до пышной массы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13294,'В белки добавляем щепотку соли и взбиваем их миксером до устойчивых пиков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13294,'К желткам добавляем манку, ванилин и аккуратно вмешивая белки, добавляя их частями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13294,'Форму для выпечки смазываем кусочком сливочного масла и посыпаем панировочными сухарями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13294,'Отправляем в форму тесто и помещаем в духовку на температуру 175-180 градусов примерно на 40 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13294,'Достаем бисквит, заливаем его теплым молоком и отправляем в духовку еще на 5-7 мин.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13295,'Репчатый лук и морковь нарезать и обжарить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13295,'Добавить томаты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13295,'Овощную массу довести до кипения, всыпать орегано, черный молотый перец, майоран, чеснок, соль – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13295,'Соус уварить и перебить блендером.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13295,'Мясо жарить до румяной корочки на заранее прогретой сковороде, обмазать соусом.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13295,'Нарезать кольцами репчатый лук, обжарить, выложить на него мясо, овощную смесь с чесноком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13295,'Влить красное полусухое вино.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13295,'Жаровню прикрыть фольгой, время приготовления – полтора часа, температура – 170 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13295,'Готовый продукт остудить, нарезать ломтиками поперек, снова положить в жаровню и тушить еще полтора часа.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13296,'Куриное филе порезать на небольшие кубики. Обжарить порезанные шампиньоны до золотистого цвета, выложить их на тарелку, а в этой же сковороде обжарить лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13296,'Яйца взбить, посолить и пожарить омлет. Охлажденный яичный омлет порезать на квадратики, по размеру приблизительно, как курица и грибы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13296,'Для приготовления заправки следует смешать творог, йогурт и выдавить чеснок. Посолить и поперчить по вкусу. Тщательно размешать заправку, размять кусочки творога.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13296,'Все ингредиенты смешать, заправив салат «Всем на зависть» творожным соусом. Блюдо требует пропитки, поэтому его необходимо поставить на холод на пару часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13297,'Говядину промыть, удалить прожилки и лишний жир.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13297,'Натереть продукт солью и специями для мяса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13297,'Нашпиговать кусок чесноком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13297,'Нарезать морковь и лук, порубить чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13297,'Кусок мяса с косточкой положить в пакет для запекания, сверху – лук, морковь и чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13297,'Влить красное вино.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13297,'Время запекания – один час, температура – 140 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13297,'Пакет наколоть для выхода пара. Печь еще полтора или два часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13298,'Свинину хорошо промыть холодной водой, обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13298,'По всей длине сделать глубокие надрезы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13298,'Специи, ароматные травы перемешать, натереть кусок мяса со всех сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13298,'В надрезы вложить чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13298,'Продукт обернуть пищевой пленкой, положить в холодильник на сутки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13298,'Надрезы заполнить нарезанным куриным филе.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13298,'Посыпать рублеными грецкими орехами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13298,'Свернуть кусок мяса в виде рулета, обвязать нитками и обернуть листом фольги.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13298,'Продукт положить на противень, время запекания – полтора часа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13298,'Готовый рулет освободить от ниток и фольги, нарезать ломтиками.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13299,'Репчатый лук и морковь очистить, промыть, лук нашинковать, морковь порезать кружками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13299,'Прогреть на сковороде оливковое масло, обжарить овощи в течение пяти минут, помешивать, посыпать молотыми семенами кориандра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13299,'Переложить обжарку в глубокую кастрюлю, добавить перец и морскую соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13299,'Влить овощной бульон.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13299,'Поставить емкость на огонь, довести содержимое кастрюли до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13299,'Огонь убавить, варить суп до тех пор, пока морковь не станет мягкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13299,'Разлить в тарелки, посыпать нарезанными листьями кориандра.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13300,'Промыть белую фасоль под проточной водой, отварить до готовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13300,'Откинуть продукт на дуршлаг, подождать, пока вся вода стечет.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13300,'Морковь очистить и нарезать кружками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13300,'Выложить овощ в глубокую емкость, влить оливковое масло, добавить давленый чеснок и прованские травы.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13300,'Духовой шкаф прогреть до 200 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13300,'Противень застелить листом фольги, выложить морковь, печь двадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13300,'Выложить отваренную фасоль в чашу блендера, добавить морковь, влить лимонный сок и всыпать куркуму.',NULL,7);
