INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13300,'Массу перебить до однородного состояния.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13300,'Перелить смесь в кастрюлю, довести до кипения на тихом огне.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13300,'Всыпать семена кунжута.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13301,'Морковь и репчатый лук вымыть, очистить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13301,'Часть луковицы нарезать крупными кольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13301,'Морковь нарезать крупными кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13301,'Переложить овощи в сотейник, добавить чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13301,'Влить кипящую воду, посолить по вкусу, довести до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13301,'После закипания добавить несколько листочков лавра, тимьян и корицу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13301,'Оставить суп на плите на полчаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13301,'Ингредиенты измельчить погружным блендером.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13301,'Добавить в кастрюлю сливочное масло, молотый перец, досолить и оставить прогреваться на десять минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13301,'Оставшийся лук накрошить, обжарить на масле с сахарным песком до появления золотистой корочки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13301,'Зелень петрушки вымыть, обсушить, порвать руками.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13301,'Украсить суп зеленью и луковой обжаркой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13302,'Курицу разделать и промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13302,'В кастрюлю выложить шею, крылышки и спинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13302,'Добавить лавровый лист и перец, влить воду, поставить на средний огонь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13302,'Пенку снять, огонь уменьшить, общее время приготовления – полтора часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13302,'Очистить морковь, нарезать ломтиками, добавить в бульон, варить до мягкости.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13302,'Промыть и измельчить зелень петрушки, пропустить через пресс чеснок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13302,'Положить ингредиенты в чашу блендера, размолоть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13302,'Добавить в кастрюлю мелко нарезанный имбирь, лук.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13302,'Размолоть погружным блендером.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13302,'Готовый суп разлить в тарелки и заправить чесночной смесью.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13303,'Морковь, лук репчатый очистить от кожуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13303,'Морковь нарезать маленькими кубиками, лук – кольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13303,'Лук обжарить на масле до румянца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13303,'Добавить на сковороду морковь, прогреть, снять с огня.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13303,'Овощной или куриный бульон налить в кастрюлю, довести до кипения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13303,'Натереть плавленый сыр на крупной терке, добавить в бульон, перемешать.',NULL,6);
