INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13303,'Добавить овощную обжарку, варить суп двадцать минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13303,'Соль, перец, любимые специи – по вкусу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13303,'Суп снять с огня, настаивать в течение десяти минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13303,'Превратить суп в суп-пюре с помощью погружного блендера.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13304,'Морковь очистить, промыть, нарезать кружками средней толщины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13304,'Растопить кусочек сливочного масла в глубокой кастрюле, добавить морковь, жарить под крышкой на среднем огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13304,'Влить воду, довести суп до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13304,'Промыть рисовую крупу несколько раз.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13304,'Залить молоком, довести до кипения, варить на тихом огне пятнадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13304,'Добавить морковь, превратить массу в пюре при помощи погружного блендера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13304,'Добавить молоко к сырым яичным желткам, посолить по вкусу, всыпать сахарный песок.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13304,'Ингредиенты взбить вилкой или венчиком.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13304,'Влить суп, кипятить все вместе десять минут.',NULL,9);
