INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13305,'Куриное филе вымыть и высушить. Каждый кусок тщательно обмазать медом и сложить в противень, смазанный маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13305,'Филе залить маринадом и закрыть противень фольгой. Филе цыпленка в цитрусовом маринаде будет готовиться 30 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13306,'Курицу разморозить, промыть, положить в кастрюлю и залить водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13306,'Добавить лавровый лист и перец-горошек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13306,'Варить все вместе около получаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13306,'Морковь очистить, нарезать кружочками, зелень петрушки промыть и мелко порубить или порвать руками.',NULL,4);
