INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13306,'Бульон процедить, вылить в кастрюлю обратно, добавить петрушку и морковь, варить до мягкости моркови.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13306,'Нарезать репчатый лук полукольцами, обжарить на постном масле на сковороде вместе с нарезанным чесноком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13306,'Овощи добавить в суп, варить десять минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13306,'Вынуть ингредиенты шумовкой, перебить в блендере в пюре.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13306,'Курицу нарезать кусками.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13306,'Разлить суп в тарелки, положить курицу, украсить зеленью.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13307,'Влить воду в кастрюлю, поставить на огонь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13307,'Морковь и картофель очистить нарезать кубиками среднего размера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13307,'Картофель добавить в кастрюлю.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13307,'Раздавить в ступке семена кориандра, обжарить на сковороде с раскаленным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13307,'Семена должны потемнеть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13307,'Добавить тертый корень имбиря и морковь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13307,'Обжарку переложить в кастрюлю, варить до готовности моркови.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13307,'Снять кастрюлю с огня, остудить, превратить в пюре при помощи блендера.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13307,'Вновь поставить кастрюлю на огонь, посолить, добавить по вкусу перец и куркуму.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13308,'Прогреть на плите овощной бульон или чистую воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13308,'Нарезать подготовленную морковь, картофель, лук, чеснок, помидоры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13308,'Положить в бульон картофель, варить под крышкой на тихом огне.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13308,'Разогреть сковороду, влить масло, обжарить чеснок, затем лук и помидоры.',NULL,4);
