INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13308,'Добавить обжарку в кастрюлю, приправить специями – перцем, сушеными травами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13308,'Прогревать суп до готовности, немного остудить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13308,'Перебить блендером, залить частью бульона.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13308,'Доварить суп на тихом огне в течение десяти минут, выключить и дать постоять.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13309,'Репчатый лук нарезать и потушить на масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13309,'Картофель и морковь очистить, нарезать небольшими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13309,'Выложить овощи в овощной же бульон, сваренный заранее.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13309,'Время приготовления – двадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13309,'Соль и приправы – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13309,'Превратить овощи в пюре при помощи погружного блендера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13309,'Влить сливки, поставить на огонь, довести суп до кипения.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13309,'Подавать суп к столу горячим.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13310,'Репчатый лук нарезать полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13310,'Очистить морковь, нарезать кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13310,'Овощи обжарить на сковороде на растительном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13310,'Овощной бульон поставить на плиту, добавить нарезанный кубиками плавленый сыр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13310,'Добавить овощную обжарку, соль и молотый перец – по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13310,'Суп варить до мягкости моркови, всыпать сухой орегано, тимьян.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13310,'Массу превратить в пюре при помощи блендера, подержать суп под крышкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13311,'Замочить нут в большом количестве воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13311,'Дать постоять, затем варить в течение часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13311,'Приготовить бульон из моркови, лука-порея, чеснока, стеблей сельдерея, черного перца и лаврового листа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13311,'Овощи очистить, нарезать, залить водой, довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13311,'Варить три минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13311,'Превратить суп в кашицеобразную массу при помощи блендера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13311,'Довести до кипения, добавить половину нута.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13311,'Время варки – от двадцати до двадцати пяти минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13311,'Обжарить оставшийся нут на оливковом масле на сковороде, посолить, добавить кориандр, куркуму, паприку.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13311,'Суп разлить в тарелки, добавить хрустящий нут со сковороды.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13312,'Репчатый лук нарезать кубиками небольшого размера, обжарить до получения золотистой корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13312,'Нарезать полукольцами морковь, добавить в обжарку, посолить и посыпать тмином.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13312,'Влить в сковороду немного воды, овощи потушить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13312,'Добавить чеснок, заранее отваренный картофель и немного соевого соуса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13312,'Превратить все при помощи блендера в пюре.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13312,'Если суп получился слишком густым, его можно разбавить водой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13312,'Поставить блюдо в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13312,'Приготовить заправку из нарезанного чеснока, соли и тмина, лука, петрушки, базилика.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13312,'Ингредиенты перемешать с йогуртом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13312,'Влить заправку в готовый суп.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13313,'Куриное бедро промыть, залить водой, вскипятить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13313,'Приготовить бульон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13313,'Влить растительное масло на сковороду, выложить мелко нарезанный репчатый лук.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13313,'Обжарить, добавить нарезанную морковь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13313,'Все вместе прогревать три минуты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13313,'Готовую обжарку добавить в кастрюлю, варить суп около получаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13313,'Соль – по вкусу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13313,'Бедро вынуть, суп заправить пряностями, добавить нарезанный кусочками плавленый сыр.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13313,'Суп помешивать до полного растворения сыра.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13313,'Довести массу до состояния пюре при помощи блендера.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13313,'Куриное мясо порвать руками, украсить суп.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13314,'Ягоды можжевельника, кориандр, паприку, сушеный розмарин смешать с сахаром и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13314,'Можжевельник предварительно раздавить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13314,'Натереть обсушенную полотенцем куриную грудку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13314,'В смесь специй можно добавить немного коньяка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13314,'Куриное мясо поместить в хорошо закрывающийся пластиковый контейнер, поставить в холод на сутки для пропитывания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13314,'Через двадцать четыре часа кусочки курицы промыть, обсушить, еще раз обвалять в специях.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13314,'Заготовки держать в подвешенном виде на открытом воздухе 3-7 дней.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13315,'Рыбу разделать, отрезать голову, удалить позвоночник и хвост.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13315,'Филе промыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13315,'Нарезать на куски, натереть солью, выложить в любую нержавеющую емкость слоями, пересыпая солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13315,'Поставить в холод на пять суток.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13315,'Рыбу промыть, замочить в холодной воде на пять часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13315,'Воду менять.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13315,'Продукт подвесить в проветриваемом помещении на три дня.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13315,'Кусочки обернуть пищевой пленкой, хранить в холодильнике.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13316,'Тушку кролика промыть, обсушить, натереть молотой паприкой, а затем солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13316,'Мясо солить трое суток или больше.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13316,'Продукт промыть, вымочить мясо в холодной воде в течение нескольких часов, воду менять.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13316,'Натереть тушку смесью из острого перца и пажитника.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13316,'Повесить сушиться на десять дней или больше, если тушка большая.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13317,'Лосятину промыть, удалить крупные жилы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13317,'Мясо нарезать крупными прямоугольными кусками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13317,'Сложить продукт в контейнер для пищевых продуктов, пересыпать солью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13317,'Накрыть тарелкой, положить груз, поставить холод на четверо суток.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13317,'Мясо промыть, вымочить в течение шести часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13317,'Воду менять каждый час.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13317,'Пажитник перемешать с паприкой, черным и красным молотым перцем, хмели-сунели, сушеным чесноком, душистым перцем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13317,'Залить смесь горячей водой, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13317,'Куски мяса смазать специями, положить в емкость, поставить в холод для пропитывания на четверо суток.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13317,'Мясо подвесить сушиться на период до десяти дней.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13318,'Удалить жилы и лишний жир.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13318,'Нарезать на мелки кусочки размером два на два сантиметра.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13318,'Посолить по вкусу, варить от пятнадцати до двадцати минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13318,'Выложить готовое мясо в сушилку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13318,'Температура приготовления – от семидесяти до восьмидесяти градусов, время – пятнадцать часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13319,'Конину и свиное сало перемолоть при помощи мясорубки или блендера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13319,'Перетереть в ступке паприку с перцем, сушеным кориандром и сушеным тимьяном.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13319,'Добавить сахар и соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13319,'Всыпать смесь в фарш, влить красное вино, массу перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13319,'Поставить продукт в холодильник на двенадцать часов или на сутки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13319,'Подготовленные кишки наполнить фаршем руками или с помощью кухонной машины.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13319,'Завязать концы узлом, придать заготовке форму подковы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13319,'Колбасу повесить в хорошо проветриваемом помещении на четыре или пять дней.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13319,'Ежедневно прокатывать колбаски скалкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13319,'Сушить еще три недели.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13360,'Натереть сыр, посыпать блинчики сверху.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13320,'Перемешать говяжий и свиной фарш, всыпать пряности: черный молотый перец, паприку, тимьян, добавить сахар и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13320,'Влить коньяк.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13320,'Готовый продукт переложить на тарелку, накрыть пищевой пленкой, поставить в холод на сутки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13320,'Подготовить говяжьи или свиные кишки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13320,'Наполнить фаршем.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13320,'Колбасу проткнуть в нескольких местах иглой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13320,'Связать концы, подвесить заготовки в прохладном помещении или положить в холодильник.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13320,'Через два или три дня прокатывать заготовки скалкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13320,'Время сушки – от восьми до девяти дней.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13321,'Баранину пропустить через мясорубку, влить красное вино, всыпать соль, перец, черный молотый перец, паприку, чабрец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13321,'Массу перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13321,'Емкость с фаршем закрыть пищевой пленкой, охлаждать в течение суток.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13321,'Свиные кишки промыть, наполнить фаршем, наколоть иглой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13321,'Завязать концы колбасы, сушить в проветриваемом помещении.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13321,'Через два дня колбасу прокатать скалкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13321,'Операцию повторять каждый день.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13321,'Время вяления – десять суток.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13322,'Как приготовить фарш? Думаю многие знаю, но все же напишу. Мясные продукты пропускаем через мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13322,'Добавляем измельченный лук зеленый и репчатый, соль, перец по вкусу. Все перемешиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13322,'Далее. Слоеное тесто слегка раскатываем и делим на 2 половинки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13322,'Яйца нужно разбить в глубокую тарелку и взбить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13322,'На одну половинку укладываем заранее приготовленный фарш, края смазываем взбитыми куриными яйцами.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13322,'Далее, заворачиваем в виде конвертика и защиплем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13322,'Перекладываем на противень и даем тесту немного подойти.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13322,'Как только слоеное тесто немного подошло, смазываем поверхность взбитыми кур. яйцами и проделываем отверстия при помощи вилки или спички. Отверстия нужны, чтобы пару от фарша было куда выходить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13322,'Отправляем в разогретую духовке при 180 с на 20-30 мин. Также рекомендую следить за приготовлением слоеных конвертиков. У них должна появится золотистая корочка, и фарш должен пропечься. Всем добра)',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13323,'Нарезать небольшими кубиками куриную грудку','https://vkuso.ru/data/cache/data/5e/9d3bc3c86ad1a5e_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13323,'Посолить и поперчить по вкусу, приправить любыми специями (у меня сладкая паприка и итальянские травы) и все хорошо перемешать','https://vkuso.ru/data/cache/data/d4/2e4b3bfc82be2d4_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13323,'Нарезать картошку такими же небольшими кубиками и посолить по вкусу','https://vkuso.ru/data/cache/data/0b/bb785de6386b20b_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13323,'Соединить курицу с картошкой и хорошо перемешать','https://vkuso.ru/data/cache/data/e6/1c9c77fd7574be6_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13323,'Смазать форму для запекания растительным маслом и выложить в нее курицу с картошкой ровным слоем','https://vkuso.ru/data/cache/data/02/3312d55fd22da02_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13323,'В отдельной миске смешать яйца и сметану','https://vkuso.ru/data/cache/data/ff/884350eef36afff_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13323,'Добавить в смесь натертый на средней терке сыр и все хорошо перемешать','https://vkuso.ru/data/cache/data/57/95ff0ea7bfdf557_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13323,'Равномерно покрыть сырной смесью курицу с картошкой','https://vkuso.ru/data/cache/data/d0/4cd75792f92b1d0_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13323,'Сверху сырной смеси слегка вдавливая уложить тонкие кружочки помидоров','https://vkuso.ru/data/cache/data/a4/1e5a1e9b98eeea4_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13323,'Накрыть форму фольгой и поставить в заранее разогретую до 190 С духовку примерно на 1 час. За 10-15 мин до готовности фольгу снять и дать сыру запечься до желаемой румяности. Учитывайте особенности своей духовки','https://vkuso.ru/data/cache/data/9c/c265646c474029c_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13323,'Готовую запеканку посыпать укропом','https://vkuso.ru/data/cache/data/71/c5ea1104b877071_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13323,'Нарезать запеканку на порции и можно подавать','https://vkuso.ru/data/cache/data/97/27b92e881600097_434x295_notrise.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Просеять муку, добавить в нее сахар и соль, перемешать.','https://vkuso.ru/data/cache/data/6a/e5bf454ec53036a_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'В муку ввести сначала 2 яйца, перемешать.','https://vkuso.ru/data/cache/data/bc/6d52cca9391c0bc_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Добавить еще 2 яйца и снова хорошо перемешать.','https://vkuso.ru/data/cache/data/78/633d1feddeefa78_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Налить любое светлое пиво и хорошо перемешать.','https://vkuso.ru/data/cache/data/97/c478c709222bb97_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Затем влить молоко, перемешать.','https://vkuso.ru/data/cache/data/3d/9607a53e975833d_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Добавить растопленное и слегка остывшее сливочное масло, хорошо перемешать, чтобы не осталось комочков муки. Тесто должно быть жидким.','https://vkuso.ru/data/cache/data/35/0abdab03ba12d35_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Поставить тесто для блинов в холодильник на 1 час.','https://vkuso.ru/data/cache/data/dd/03328025463c2dd_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Пока тесто стоит в холодильнике приготовить начинку. Нарезать зеленый лук.','https://vkuso.ru/data/cache/data/c4/65748cc86409bc4_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Слегка припутить лук на сковородке на сливочном масле около 30 сек.','https://vkuso.ru/data/cache/data/20/54b7611d87db620_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Нарезать вареную куриную грудку.','https://vkuso.ru/data/cache/data/30/45f8b351ec68530_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Добавить к ней обжаренный лук.','https://vkuso.ru/data/cache/data/c8/5b26fb54d235dc8_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Добавить натертый сыр.','https://vkuso.ru/data/cache/data/30/9ecb6257b960930_434x295_notrise.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Посолить и поперчить по вкусу, все хорошо перемешать.','https://vkuso.ru/data/cache/data/18/27c0e978fcf8318_434x295_notrise.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Пожарить блины на хорошо разогретой сковороде, смазывая ее перед каждым блином небольшим количеством растительного масла.','https://vkuso.ru/data/cache/data/a1/e63c9d8f97d17a1_434x295_notrise.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Блины не жарить слишком сильно, они должны быть только следка подрумяненные.','https://vkuso.ru/data/cache/data/42/a8bfa8778bb7742_434x295_notrise.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Каждый готовый блин сразу смазывать сливочным маслом.','https://vkuso.ru/data/cache/data/93/2f5ef221bafac93_434x295_notrise.jpg',16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Готовые смазанные блины дерать под плотной крышкой, чтобы они пропитались маслом и стали мягкими и эластичными.','https://vkuso.ru/data/cache/data/d8/5404f4142829fd8_434x295_notrise.jpg',17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Блинчики получаются очень тонкие и гибкие.','https://vkuso.ru/data/cache/data/d4/3fceb3d4d70e5d4_434x295_notrise.jpg',18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Когда все блины будут готовы, на каждый блинчик выложить начинку по столовой ложке с горкой.','https://vkuso.ru/data/cache/data/e4/69cac0d39f57ee4_434x295_notrise.jpg',19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Сложить блинчик мешочком.','https://vkuso.ru/data/cache/data/90/a17bf7177633e90_434x295_notrise.jpg',20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Скрепить верх стрелкой зеленого лука.','https://vkuso.ru/data/cache/data/54/01cb8202cef8954_434x295_notrise.jpg',21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Мешочки хорошо держат форму и не раскрываются.','https://vkuso.ru/data/cache/data/d4/b15a299833119d4_434x295_notrise.jpg',22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Выложить все мешочки в форму для запекания, форму смазывать не нужно.','https://vkuso.ru/data/cache/data/20/d66609367fcdf20_434x295_notrise.jpg',23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Поставить в заранее разогретую до 180 С духовку на 8 мин.','https://vkuso.ru/data/cache/data/97/1ea7b818a09ff97_434x295_notrise.jpg',24);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Вот такие блинчики получились в разрезе.','https://vkuso.ru/data/cache/data/10/f5202ae21cb1410_434x295_notrise.jpg',25);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13324,'Теплый сыр расплавился и приятно тянется.','https://vkuso.ru/data/cache/data/b2/90c6f7cb9c0e3b2_434x295_notrise.jpg',26);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13325,'Очистить картофель и поставить вариться, посолив и добавив лавровый лист. Для приготовления соуса соединить сок лимона, йогурт, давленый чеснок. Соус поперчить и посолить по вкусу. Добавить в соус мелко порезанный укроп.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13325,'Лосось порезать на тонкие полоски. Выложить на блюдо картофель, уложить на него рыбу, притрусить порезанным укропом и залить ароматным соусом. Картофель с копченым лососем под соусом из йогурта готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13326,'Морковь и лук мелко порезать и обжарить на сковороде. Добавить порезанную печень и обжарить до готовности. Горячую печень с овощами следует измельчить в блендере, добавляя сливки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13326,'Нежность мусса регулируйте добавлением сливок, только не переборщите, чтобы мусс не оказался жидким. Печеночный мусс довести до вкуса приправами и зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13326,'Яйца и помидоры разрезать на две половинки. Тарталетки наполнить муссом и украсить яйцами и помидорами, можно дополнить веточкой зелени. Закусочные тарталетки с печеночным муссом готовы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13327,'Приготовим маринад для курицы. В посуде смешаем паприку, кумин, лук, чеснок, хлопья перца, пиво и смешаем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13327,'Добавим грудку нарезанную кубиками. Оставим минимум на 30 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13327,'Теперь разогреем две сковородки и в одну добавим масло. И обжарим красный лук, перец, грибы и паприку. А в другой обжарим грудку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13327,'По готовности начнём собирать фахитос.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13327,'На тортилью нужно добавить соус гуакамоле - 2 ст.л., далее добавить овощи и курицу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13328,'В теплый кефир всыпать соду, подождать пока пройдет реакция, добавить соль и сахар. Потереть сыр на терку и добавить в тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13328,'Всыпать муку и вымесить тесто. Мягкое сырное тесто на кефире готово.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13329,'Яйца взбить с сахаром, соду погасить сметаной, соединить ингредиенты и добавить теплое молоко и растопленный маргарин.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13329,'Добавить просеянную муку и вымесить тесто. Легкое пресное тесто на сметане готово.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13330,'Раскатать тесто.','https://vkuso.ru/data/cache/data/a8/21877cca5fe2ba8_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13330,'Выложить начинку.','https://vkuso.ru/data/cache/data/8d/ac500a934a0fe8d_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13330,'Скатать рулет.','https://vkuso.ru/data/cache/data/38/7f34baea0509e38_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13330,'Порезать на шайбы.','https://vkuso.ru/data/cache/data/f6/0281bc49e1be8f6_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13330,'Взбить яйцо.','https://vkuso.ru/data/cache/data/22/247709713fb8f22_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13330,'Обмакнуть нижнюю часть в яйцо.','https://vkuso.ru/data/cache/data/26/d516ed75eaa4f26_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13330,'Натереть сыр.','https://vkuso.ru/data/cache/data/86/34d532eff9a7186_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13330,'Положить на пирожки.','https://vkuso.ru/data/cache/data/55/10733678edbe755_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13330,'Выпекать при 190°C 20 минут.','https://vkuso.ru/data/cache/data/49/db23006f5df7849_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13330,'Добавить зелень.','https://vkuso.ru/data/cache/data/f2/3f8f0caceec0bf2_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13331,'Дрожжи развести в теплом кефире, дать немного постоять. Добавить соль, сахар, растительное масло, перемешать. Добавить просеянную муку и вымесить тесто, чтобы не приставало к рукам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13331,'Оставить тесто для подъема в теплом месте на час-полтора. Воздушное дрожжевое тесто на кефире готово.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13332,'Сварить картошку до полной готовности, воду слить, слегка охладить и размять толкушкой в пюре.','https://vkuso.ru/data/cache/data/3f/26c51e5b5e5f73f_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13332,'Посолить, добавить крахмал 1 ст л с горкой и 4 ст л муки с горкой, все хорошо перемешать и замесить руками как тесто.','https://vkuso.ru/data/cache/data/aa/432d6a5eccdbeaa_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13332,'Выложить на стол, добавить еще 1-2 ст л муки и вымесить как тесто, чтобы оно почти не прилипало к рукам и столу. Если оно все еще липнет можно добавить муку еще немного.','https://vkuso.ru/data/cache/data/8b/ed459b741f8e98b_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13332,'Разделить тесто на 8 частей.','https://vkuso.ru/data/cache/data/d6/ea6df26e23f25d6_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13332,'Сформировать шарики, накрыть их полотенцем от заветривания и оставить пока готовится начинка.','https://vkuso.ru/data/cache/data/c0/26b1f00ba971fc0_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13332,'Для начинки обжарить на растительном масле мелко нарезанный лук и шампиньоны до готовности, посолить и поперчить по вкусу и дать остыть.','https://vkuso.ru/data/cache/data/27/c302e30381ce027_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13332,'На присыпанную мукой поверхность или тарелку выложить шарик теста, примять руками до формирования лепешки и выложить на нее начинку.','https://vkuso.ru/data/cache/data/88/fc1bb68d450cc88_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13332,'Скрепить края и сформировать ровный пирожок.','https://vkuso.ru/data/cache/data/66/a3bb126a9963366_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13332,'Обжарить пирожки на растительном масле с обеих сторон.','https://vkuso.ru/data/cache/data/45/83ed95634850e45_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13332,'Пирожки жарятся на среднем огне по 3-4 мин с каждой стороны до желаемой румяности.','https://vkuso.ru/data/cache/data/33/3b552960ee9fd33_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13332,'Подавать пирожки можно как в горячем, так и в холодном виде, со сметаной, кетчупом или любым соусом.','https://vkuso.ru/data/cache/data/3f/64fc2413704fb3f_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13333,'В теплом кефире развести соду и добавить соль, яйца и просеянную муку. Наливное тесто «Пятиминутка» на кефире получается, как густая сметана.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13334,'Теплый кефир или сыворотку соединить с дрожжами, пусть постоит пару минут, чтобы дрожжи разбухли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13334,'Яйца взбить с сахаром и ввести в кефир, добавить растопленный маргарин и просеянную муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13334,'Вымесить не крутое тесто и положить в холодильник для застывания. Безопарное дрожжевое сдобное тесто готово.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13335,'Делим яблоко на 2 половинки, вырезаем середину, и нарезаем половинки на тонкие ломтики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13335,'Куриное яйцо разбиваем в глубокую тарелку и хорошо взбиваем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13335,'Слоеное тесто раскатываем до 3-5 мм и делим на равные полоски.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13335,'Далее каждую полоску смазываем взбитым кур.яйцом посыпаем сахаром, и к середине укладываем яблоко (пример на главном фото). Яблоко нужно уложить так, что бы часть его выступала за тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13335,'После чего заворачиваем, немного применяем и смазываем поверхность теста взбитым кур.яйцом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13335,'Отправляем в разогретую духовку до румяной корочки на 20-25 минут. Также, рекомендую следить за приготовлением...',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13335,'Спустя 20-25 минут достаем, и наслаждаемся вкусом)',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13336,'Апельсины очистить от кожуры и порезать на кусочки.','https://vkuso.ru/data/cache/data/76/c545fa5ce4c8176_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13336,'Перемолоть апельсины в блендерном измельчителе.','https://vkuso.ru/data/cache/data/48/e5f49fb62270f48_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13336,'Яйца взбить с сахаром и солью. К взбитым яйцам добавить апельсиновую смесь.','https://vkuso.ru/data/cache/data/33/b3ed077d46ddb33_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13336,'Муку смешать с дрожжами. К муке постепенно добавлять апельсино-яичную смесь и замесить тесто. Тесто оправить на расстойку приблизительно на 2 часа. Через 2 часа тесто должно увеличиться вдвое. К тесту добавить 2 горсти промытого и обсушенного изюма и еще раз вымесить тесто.','https://vkuso.ru/data/cache/data/e3/10da93890881fe3_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13336,'Разделить тесто на 7 частей и скатать из каждой части круглые рулетики.','https://vkuso.ru/data/cache/data/5c/2a3730ef3738d5c_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13336,'Положить заготовки в кексницу, смазать желтком и оставить в теплом месте на 30 минут. Через пол часа отправить сдобу в разогретую духовку. Температура в духовке у меня была 170 градусов, и выпекала апельсиновые булочки или апельсиновый хлеб около 25-30 минут. Ориентируйтесь по своей духовке.','https://vkuso.ru/data/cache/data/71/96d6252dd8e5971_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13337,'В теплом молоке развести дрожжи и добавить сахар. Через пару минут ввести взбитое яйцо, масло и соль. Добавить просеянную муку и вымесить мягкое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13337,'Безопарное дрожжевое тесто на молоке положить в полиэтиленовый пакет и завязать кулек, оставив место для подхода. Пакет положить на холод и через несколько часов можно жарить пирожки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13338,'Смешать сухие ингредиенты: просеянную муку, кокосовую стружку, овсяные хлопья, сахар, разрыхлитель и соль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13338,'Масло растопить, смешать с мёдом, добавить к сухой смеси. Перемешать. Если тесто недостаточно однородно и пластично, можно добавить немного воды или лимонного сока.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13338,'На застеленный пекарской бумагой противень выкладываем небольшие печеньки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13338,'Выпекать печенье при 180°С в течении 15-20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13339,'Салат собираем в кулинарном кольце, установив его на тарелку. Смазываем майонезом дно и бока формы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13339,'Нижний слой – вареный рис, посыпаем черным молотым перцем и смазываем майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13339,'Второй слой - маринованный перец освобождаем от маринада и измельчаем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13339,'Следующий слой – измельченное  куриное филе. Посыпаем слой черным молотым перцем и смазываем майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13339,'Последним слоем выкладываем кукурузу, и смазываем майонезом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13339,'Для украшения используем зелень и кукурузу.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13340,'Дрожжи растворить в небольшом количестве теплой воды, соединить с растопленным маргарином, взбитыми яйцами с сахаром. Соду погасить сметаной (не из холодильника), соединить все ингредиенты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13340,'Вымесить мягкое тесто, которое не липнет к рукам и оставить на время, чтобы подошло. Дрожжевое тесто на сметане с содой готово.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13341,'Отваренный картофель в мундире натерла на мелкой терке. Отваренное куриное филе мелко нарезала.','https://vkuso.ru/data/cache/data/23/8cc4140bc163023_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13341,'Соединила вместе натертый картофель и нарезанное куриное филе. К ним добавила яйца, мускатный орех, соль и муку. Все ингредиенты хорошо перемешала.','https://vkuso.ru/data/cache/data/cd/9567b55866f28cd_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13341,'Смесь выложила на посыпанную мукой поверхность и разделила на части, чтобы с тестом было удобно работать. Из каждого кусочка теста раскатала колбаску и нарезала на небольшие кусочки. Скатала каждый кусочек в шар и сделала пальцем в середине ямку.','https://vkuso.ru/data/cache/data/2c/6cd1195dbcd612c_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13341,'Сварила ньокки в кипящей подсоленной по вкусу воде с добавления растительного масла, чтобы не слиплись. Варила 1,5-2 минуты, пока не всплыли.','https://vkuso.ru/data/cache/data/35/d19ab1d7a23a835_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13346,'Длиннозерный рис промыть, перемешать со специями: кинзой, шафраном, кумином, барбарисом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13346,'Крупу пересыпать в мультиварку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13341,'После того как ньокки сварились, обжарила их на растительном масле в предварительно разогретой сковороде. В процессе жарки добавила немного сливочного масла (оно придает ореховый привкус).
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13341,'После обжарки ньокки готовы. Надеюсь, вам понравятся. Приятного аппетита!','https://vkuso.ru/data/cache/data/10/25064ef211acc10_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13342,'В чаше смешаем яйцо, сахар, ванилин, соль, корицу, соду погашенную кипятком, все хорошо разотрем венчиком и добавим молоко. Еще раз все перемешаем. Постепенно начнем добавлять муку.','https://vkuso.ru/data/cache/data/dc/2af80c6228800dc_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13342,'Теперь можно добавить оливковое масло (можно заменить на подсолнечное). Еще раз все перемешаем.','https://vkuso.ru/data/cache/data/b6/d97dea952c8ccb6_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13342,'Получается тесто как на оладушки.','https://vkuso.ru/data/cache/data/0b/4b4078eaf29ba0b_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13342,'Выкладываем тесто на хорошо разогретую сухую сковороду ложкой и слегка придаем будущим панкейкам круглую форму. Обжариваем с двух сторон на среднем огне.','https://vkuso.ru/data/cache/data/95/da9f5d9a5f00f95_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13342,'Я сварила из какао, сахара и сливочного масла глазурь и полила сверху.','https://vkuso.ru/data/cache/data/68/885ccf1cb14fe68_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13343,'Взбить мягкое масло с сахаром, добавить в него творог и яйцо. Вымесить первую часть теста. Муку соединить с солью и содой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13343,'Смешать две части ингредиентов и вымесить мягкое тесто. Нежное творожное тесто со сливочным маслом готово к выпечке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13344,'Отварить овощи, куриную грудку и яйца, все мелко нарезать. Сложить в миску картошку и морковь.','https://vkuso.ru/data/cache/data/7b/9dafd380c6b2e7b_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13344,'Добавить курицу и яйца.','https://vkuso.ru/data/cache/data/ef/755daa37f5573ef_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13344,'Соленые огурцы и зеленый лук.','https://vkuso.ru/data/cache/data/30/db8b5f06ea1da30_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13344,'Зеленый горошек и натертый на средней терке сыр.','https://vkuso.ru/data/cache/data/1a/c3ce977a206491a_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13344,'Добавить майонез, посолить и поперчить по вкусу.','https://vkuso.ru/data/cache/data/80/25c28a61adbfe80_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13344,'Все перемешать.','https://vkuso.ru/data/cache/data/89/08e7acc622e4389_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13344,'Тонко раскатать предварительно размороженное слоеное бездрожжевое тесто.','https://vkuso.ru/data/cache/data/90/8b29ade60f8b890_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13344,'Разрезать тесто на квадратики.','https://vkuso.ru/data/cache/data/b4/8e93de08090d9b4_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13344,'На каждый квадратик выложить приготовленный салат по большой ложке с горкой.','https://vkuso.ru/data/cache/data/cd/ba7a906a8405acd_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13344,'Накрыть сверху другим квадратиком, придавить края и обработать край вилкой.','https://vkuso.ru/data/cache/data/0f/33159d06f96410f_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13344,'Получаются пирожки размером примерно 12х12 см.','https://vkuso.ru/data/cache/data/8f/a35eadd8085d48f_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13344,'Смазать пирожки взбитым яйцом.','https://vkuso.ru/data/cache/data/0c/89f19c9512a710c_434x295_notrise.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13344,'Посыпать кунжутом.','https://vkuso.ru/data/cache/data/fa/37073bc5d0a12fa_434x295_notrise.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13344,'Выпекать в заранее разогретой духовке 20 мин при 200 градусах до румяности.','https://vkuso.ru/data/cache/data/b8/270a17a34679cb8_434x295_notrise.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13344,'Готовые пирожки остудить.','https://vkuso.ru/data/cache/data/b3/074210aa2f001b3_434x295_notrise.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13344,'Подавать пирожки можно как в слегка теплом, так и в охлажденном виде.','https://vkuso.ru/data/cache/data/84/20491944ae80284_434x295_notrise.jpg',16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13345,'Мясо нарезать кусочками среднего размера, выставить режим «Жарка», готовить на сливочном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13345,'Добавить нарезанный репчатый лук, морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13345,'Все вместе жарить до тех пор, пока овощи не станут полупрозрачными.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13345,'Выложить сверху промытый рис, соль, приправы, рубленый чеснок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13345,'Влить в емкость воду, ее уровень должен быть выше уровня крупы на полтора пальца.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13345,'Добавить еще немного сливочного масла, выставить режим «Плов».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13346,'Сладкий болгарский перец и морковь нарезать крупной соломкой, репчатый лук – полукольцами, чеснок – пластинками минимальной толщины.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13346,'Выставить режим «Жарка», влить растительное масло, потушить овощи до полупрозрачного состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13346,'Добавить шампиньоны, нарезанные крупными кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13346,'Влить воду, выставить режим «Тушение» на двадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13347,'Сердечки разрезать пополам, промыть, удалить прожилки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13347,'Морковь и лук измельчить, готовить в режиме «Жарка» на растительном масле до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13347,'Когда овощи станут золотистыми – добавить сердечки, все вместе готовить десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13347,'Выложить в чашу хорошо промытый рис, специи, соль, влить воду. Жидкость должна на палец покрывать крупу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13347,'Выставить режим «Тушение» на час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13347,'За пятнадцать минут до окончания приготовления крышку мультиварки открыть, выложить очищенный чеснок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13348,'Свинину нарезать кусочками, выставить режим «Жарка» на пятнадцать минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13348,'Далее к мясу добавить нарезанный кубиками репчатый лук, бруски моркови.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13348,'Всыпать специи: кумин, сушеный барбарис, молотую куркуму. Добавить соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13348,'Поверх ингредиентов разложить чернослив.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13348,'Всыпать рис, залить плов водой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13348,'Выставить режим «Тушение» на час.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13348,'Через полчаса в чашу положить не очищенную, но промытую головку чеснока.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13349,'Куски любого мяса вымыть, обсушить бумажным полотенцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13349,'Обжарить в режиме «Жарка».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13349,'Морковь и лук измельчить, добавить к мясу, все вместе жарить еще семь минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13349,'Рис промыть, добавить в мультиварку вместе со специями, чесноком, солью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13349,'Влить воду, уровень – на два сантиметра выше крупы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13349,'Выставить режим «Плов» на час.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13350,'Рис отварить до готовности подсоленной воде. Яйца тоже отварить. Ветчину, яйца и крабовые палочки порезать кубиками. Зелень млко покрошить. Все ингредиенты сложить в один большо салатник.','https://vkuso.ru/data/cache/data/53/3ce0c729718f753_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13350,'Ко всем ингредиентам добавить специи, достаточно 0,5 чайной ложки, у меня была смесь абхазских приправ. Салат подсолить и заправить смесью майонеза со сметаной.','https://vkuso.ru/data/cache/data/87/19c6b3e9ef72387_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13351,'Мясо нарезать произвольными кусочками среднего размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13351,'Морковь нарезать брусочками, лук нашинковать полукольцами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13351,'В казан влить растительное масло на два или три сантиметра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13351,'Прогреть, выложить лук, спассеровать до румяной корочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13351,'Добавить индейку, жарить пять минут, добавить специи и морковь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13351,'Можно использовать сушеный барбарис, острый молотый перец, зиру, черный перец, соль.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13351,'Пересыпать к овощам рис, крупу разровнять, вдавить в массу пару головок чеснока без шелухи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13351,'Налить воду, уровень – на полтора или два сантиметра выше крупы.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13351,'Огонь убавить, тушить плов под крышкой до готовности.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13352,'В муку натираем сливочное масло и перетираем на крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13352,'Добавляем к мучной крошке пиво и замешиваем тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13352,'Разделяем тесто на три части, накрываем пищевой пленкой и отправляем в холодильник на 60 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13352,'Раскатываем каждый кусочек теста в круг (d=25-30 см) и делим на 8 секторов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13352,'На широкую часть каждого сектора выкладываем начинку и сворачиваем рогалик, не забываем защипывать края.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13352,'Рогалика выкладываем на лист, выстланный пекарской бумагой. Смазываем каждый рогалик желтком и присыпаем сахаром.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13352,'Отправляем в разогретую духовку на температуру 200 градусов примерно на 25-30 минут. Всем вкусного чаепития!',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13353,'Блюдо получается насыщенным, но малокалорийным.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13353,'Филе птицы нарезать кубиками небольшого размера, обжарить на растительном масле в казане до золотистой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13353,'В подрумяненный продукт добавить нарезанный репчатый лук, морковь, нарезанную брусками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13353,'Ингредиенты посыпать солью, специями.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13353,'Продукты перемешать, подлить воду, тушить двадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13353,'Промыть рис, переложить к мясу с овощами, добавить еще немного воды, специи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13353,'Уровень жидкости должен быть на два сантиметра выше продуктов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13353,'Положить головку чеснока.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13354,'Налить в казан растительное масло, спассеровать лук, затем добавить морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13354,'Овощи вынуть, переложить в отдельную емкость.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13354,'Индейку порезать кусочками, обжарить до золотистой корочки, добавить овощную обжарку, посолить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13354,'Прогревать все вместе пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13354,'Промыть булгур, выложить в казан к остальным продуктам, влить воду.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13354,'Жидкость должна покрыть продукты на полтора или два сантиметра.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13354,'Плов перемешать, потомить под крышкой в течение двадцати минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13355,'Мясо порезать кусочками, порезать репчатый лук, морковь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13355,'Вид нарезки для овощей – кубики или бруски.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13355,'Промыть рис.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13355,'Выставить режим «Жарка», налить в емкость мультиварки растительное масло, жарить овощи в течение пяти минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13355,'Выложить мясо, посолить и поперчить, перемешать, влить немного воды, тушить пятнадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13355,'Добавить рис, душистый перец, зиру, карри.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13355,'Ингредиенты разровнять, вдавить чеснок, влить воду.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13355,'Выставить режим «Плов» на час.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13356,'Нарезать репчатый лук кубиками, морковь – брусками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13356,'Филе индейки также порезать брусками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13356,'Прогреть в кастрюле растительное масло, выложить лук, а затем морковь и мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13356,'Все вместе жарить на сильном огне шесть или семь минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13356,'Продукты посолить, поперчить, посыпать пряностями для плова.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13356,'Жарить еще две минуты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13356,'Выложить сверху рис, в середину воткнуть головку чеснока, влить воду, тушить блюдо под крышкой в течение часа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13356,'Готовый плов перемешать, подать к столу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13357,'Налить растительное масло на сковороду, прогреть, обжарить кусочки индейки до получения корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13357,'Две или три моркови нарезать соломкой, нашинковать лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13357,'К индейке добавить сначала лук, затем морковь и приправы – куркуму, шафран, зиру, барбарис.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13357,'Всыпать рис, положить дольки чеснока, влить воду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13357,'Блюдо томить под крышкой сорок пять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13358,'Приготовить льезон: в большой емкости взбить сырые куриные яйца с молоком в пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13358,'Смесь посолить и поперчить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13358,'Приготовить омлетные блинчики на сковороде с антипригарным покрытием.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13358,'Масло не добавлять, блины жарить по тридцать секунд с каждой стороны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13358,'Куриное мясо мелко нарубить или пропустить через мясорубку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13358,'Добавить соль и специи.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13358,'Сформовать рулеты: фарш выложить на блин тонким ровным слоем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13358,'Один край смазать сметаной.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13358,'Противень смазать маслом, разместить изделия, сверху – оставшаяся сметана, посыпать молотой паприкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13358,'Печь на гриле в духовом шкафу в течение двадцати минут, температура приготовления – 200 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13359,'Смесь из яиц и молока хорошо взбить, соль и перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13359,'Испечь блинчики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13359,'Творожный сыр перемешать с рубленым чесноком, солью, свежей зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13359,'Сыр можно предварительно взбить, чтобы блюдо было еще нежнее.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13359,'Распределить фарш, сверху сырную массу по блинчику, свернуть рулеты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13359,'Выложить на противень, запечь в духовке, время – от двадцати пяти минут до получаса, температура – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13359,'Другой вариант приготовления: куриное филе нарезать кубиками или приготовить фарш.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13359,'Натереть твердый сыр.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13359,'Сырые куриные яйца взбить со специями и молоком, перемешать с курицей и сыром.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13359,'Обжарить изделия на сковороде в виде котлет.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13360,'Взбить сырые яйца с солью и молоком, испечь тонкие омлетные блинчики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13360,'Куриное мясо пропустить через мясорубку или мелко нарезать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13360,'Соль и перец молотый – по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13360,'Завернуть в каждый блинчик начинку, края омлета смазать густой сметаной.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13360,'Время запекания – от двадцати до двадцати пяти минут, температура – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13361,'Просеять муку, добавить в нее разрыхлитель и перемешать.','https://vkuso.ru/data/cache/data/17/4132fbe296bdf17_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13361,'В муку натереть на терке сливочное масло, предварительно охладив его в морозилке.','https://vkuso.ru/data/cache/data/92/bd09316b6bdc692_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13361,'Перетереть муку с маслом руками до образования однородной маслянистой крошки.','https://vkuso.ru/data/cache/data/5c/8cda5d0f611245c_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13361,'Смешать яйцо, обычный сахар и ванильный сахар хорошо взбить венчиком до изменения цвета с желтого до практически белого и до растворения крупинок сахара.','https://vkuso.ru/data/cache/data/18/2cf671cfe8d8218_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13361,'Хорошо взбить венчиком до изменения цвета с желтого до практически белого и до растворения крупинок сахар.','https://vkuso.ru/data/cache/data/e7/17b908e1fd82ce7_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13361,'Добавить к смеси сметану.','https://vkuso.ru/data/cache/data/d6/dca23affd9527d6_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13361,'Еще раз хорошо взбить венчиком.','https://vkuso.ru/data/cache/data/14/01f55da1ad10814_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13361,'Жидкую смесь влить в мучную.','https://vkuso.ru/data/cache/data/65/e677996ab619d65_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13361,'Перемешать сначала ложкой.','https://vkuso.ru/data/cache/data/2a/4cbd9063bf9442a_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13361,'Затем быстро вымесить тесто руками до однородности.','https://vkuso.ru/data/cache/data/65/f7e672035a55c65_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13361,'Разделить тесто на две части (1/3 и 2/3), меньшую часть убрать в морозилку на 15-20 мин.','https://vkuso.ru/data/cache/data/93/6ed2b09eeec0a93_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13361,'Большую часть выложить в форму для запекания (у меня диаметр 26 см) и равномерно распределить руками, получается слой толщиной примерно 8 мм.','https://vkuso.ru/data/cache/data/64/c5b507f1c019764_434x295_notrise.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13361,'Распределить по поверхности теста любой джем или варенье (у меня малиновый джем).','https://vkuso.ru/data/cache/data/bf/0de5c3e85102ebf_434x295_notrise.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13361,'Сверху джема натереть на крупной терке охлажденное тесто из морозилки.','https://vkuso.ru/data/cache/data/d6/4d4ad5f23aed3d6_434x295_notrise.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13361,'Равномерно распределить руками или вилкой натертое тесто по поверхности джема.','https://vkuso.ru/data/cache/data/27/e99661712c59a27_434x295_notrise.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13361,'Выпекать пирог при 180 С около 30-35 мин в заранее разогретой духовке до подрумянивания и готовности.','https://vkuso.ru/data/cache/data/f8/c15e140044a75f8_434x295_notrise.jpg',16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13361,'Готовый пирог посыпать сахарной пудрой.','https://vkuso.ru/data/cache/data/1c/e511b995bfcc41c_434x295_notrise.jpg',17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13361,'Дать пирогу немного остыть, разрезать на порции и можно подавать.','https://vkuso.ru/data/cache/data/c8/c71022b31762ec8_434x295_notrise.jpg',18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13361,'Больше всего мне нравится этот пирог с молоком, ну а с чаем и кофе это просто бесподобно.','https://vkuso.ru/data/cache/data/e6/ef8ba22407f48e6_434x295_notrise.jpg',19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13362,'Приготовить смесь из яиц и молока с добавлением соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13362,'Обжарить блинчики с двух сторон, изделия должны быть тонкими.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13362,'Приготовить фарш из куриных грудок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13362,'Нарезать репчатый лук полукольцами, покрошить шампиньоны.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13362,'Продукты обжарить на сильном огне в течение пяти или семи минут, далее посолить, поперчить, добавить сушеный чеснок, копченую паприку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13362,'На край омлетного блина выложить куриный фарш в виде полоски, рядом – грибную обжарку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13362,'Блин свернуть в трубочку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13362,'Выложить изделия на смазанный маслом противень.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13362,'Сверху – майонез, посыпать трубочки сыром.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13362,'Время готовки – полчаса, температура – 180 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13363,'Молоко с яйцами взбить до однородного состояния, посолить и поперчить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13363,'Приготовить омлет в мультиварке, режим «Выпечка», время – десять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13363,'Приготовить начинку из куриного фарша, специй, нарезанного маринованного огурца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13363,'Скатать массу в шар, накрыть пищевой пленкой и раскатать скалкой в блин по размеру омлета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13363,'Куриную котлету переложить в мультиварку, сверху – омлет.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13363,'Выставить режим «Выпечка» на пятнадцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13363,'Вынуть бризоль из мультиварки, выложить тонко нарезанные овощи: помидоры или огурцы.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13363,'Омлет свернуть пополам.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13364,'Пшеничную муку перемешать с сухими дрожжами и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13364,'Влить воду, замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13364,'Готовую массу оставить при комнатной температуре на пятнадцать часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13364,'Присыпать рабочую поверхность мукой, выложить тесто, раскатать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13364,'Сформовать «конверт», сложить три или четыре раза, выдержать один час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13364,'Переместить изделие на горячий противень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13364,'Время выпекания – полчаса, температура – 220 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13365,'Для теста яйца взбить с сахаром. Добавить растопленный маргарин/масло (не кипятить). Кефир соединить с содой, всыпать манку и ввести все в яичную смесь. Тщательно размешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13365,'Добавить муку и вымесить тесто, оно получится консистенции густой сметаны. Подготовленный противень смазать маслом и вылить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13365,'В разогретую духовку поставить противень на 30 минут, проверить готовность пирога спичкой. Когда легкий пирог «Манник» на кефире остынет, его можно украсить на любой вкус.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13366,'Перемешать закваску с водой и с горкой муки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13366,'Тесто должно получиться полужидким.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13366,'Массу накрыть пищевой пленкой, поставить в теплое место на полтора часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13366,'В поднявшуюся опару всыпать соль, сахарный песок и муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13366,'Массу перемешать при помощи миксера, воду добавлять частями.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13366,'Полученный продукт еще раз накрыть пленкой, поставить в тепло на тридцать минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13366,'Массу раскатать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13366,'Сложить тесто конвертом, оставить на сорок минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13366,'Процесс повторить четыре или пять раз.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13366,'Противень застелить пергаментом в виде двух «гнезд».',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13366,'Лист должен быть больше по размеру, чем противень.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13366,'Присыпать мукой.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13366,'Тесто разделить пополам, переложить на противень, присыпать изделия мукой сверху.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13366,'Оставить на сорок пять минут.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13366,'Прогреть духовой шкаф до 220 градусов, печь хлеб в течение пятнадцати минут.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13366,'Температуру убавить до 180 градусов, печь еще столько же.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13366,'Выпечку укутать в полотенце, остудить и подать на стол.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13367,'В чашу хлебопечки выложить сухие дрожжи, соль и сахарный песок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13367,'Влить подогретую воду, ингредиенты перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13367,'Всыпать муку, замесить тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13367,'Масса должна быть однородной и не прилипать к стенкам емкости.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13367,'Продукт накрыть полотенцем, оставить для созревания на два с половиной или три часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13367,'Рабочую поверхность посыпать мукой, выложить тесто в виде батона, оставить на полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13367,'Емкость хлебопечки смазать оливковым маслом, выложить тесто, время выпекания – 45 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13368,'В глубокой емкости соединить сухие активные дрожжи с мукой, солью, оливковым маслом, добавить теплую воду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13368,'Замесить липкое, полужидкое тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13368,'Продукт накрыть тканью, поставить в тепло на два часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13368,'Присыпать стол мукой, выложить тесто, поделить на две части.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13368,'Обе отдельно промять руками, придать форму прямоугольника.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13368,'Края наложить друг на друга, тесто замесить еще раз.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13368,'Сформовать две чиабатты, переложить на застеленный пергаментом противень, оставить на полчаса.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13368,'Натереть твердый сыр, измельчить зелень и очищенный чеснок.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13368,'Перемешать с сырной массой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13368,'Смесью посыпать хлеб, время выпекания – полчаса или чуть больше, температура приготовления – 200 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13369,'Болгарский перец нарезаем мелким кубиком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13369,'Сыр натираем на мелкой терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13369,'Лаваш нарезаем на равные части (чуть больше длины соски). И после этого, эту часть делим еще раз на 2 части. Так как длина целой части будет большая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13369,'Сосиски поджариваем на разогретой сковороде, до небольшой корочки. Можно, и не поджаривать, но жареная сосиска будет вкуснее.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13369,'На часть лаваша намазываем немного кетчупа и майонеза, все это размазываем по поверхности лаваша.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13414,'Сахар должен раствориться.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13369,'Далее, добавляем немного сыра, укладываем сосиску, и добавляем болгарского перца. И далее заворачиваем, в виде шавермы, или конвертика.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13369,'Обжариваем с двух сторон на разогретой сковороде до корочки. Все готово.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13370,'Замочить желатин в воде на 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13370,'Влить в кастрюлю сливки и молоко, добавить сахар. Поставить на средний огонь и готовить помешивая до тех пор, пока не начнет закипать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13370,'Снять с огня, добавить желатин и ванильный сахар, хорошо перемешать. Разлить в формы и убрать в холодильник на ночь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13370,'В блендере взбить клубнику с сахаром и лимонным соком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13370,'Пропустить через сито и поставить на средний огонь. Готовить до закипания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13370,'Кукурузный крахмал смешать с 1-2 ст.л. воды.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13370,'Помешивая клубничное пюре влить кукурузный крахмал частями. Как только смесь загустеет снять с огня и дать остыть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13370,'Полить клубничным пюре готовую панна котту.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13371,'Все сухофрукты хорошо промыла под проточной водой и обдала кипятком. Затем измельчила с помощью блендера.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13371,'Подготовленные сухофрукты и грецкие орехи перемешала с сахарной пудрой. Из получившейся массы сформировала небольшие шарики. Можно смочить руки водой, катать шарики будет легче','https://vkuso.ru/data/cache/data/b5/29ad2faddd133b5_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13371,'Часть шариков обваляла в какао, а часть - в кокосовой стружке. После приготовления убрала конфеты в холодильник на 1 час.','https://vkuso.ru/data/cache/data/3a/541bd45d2e9dc3a_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13371,'Надеюсь, Вам понравится. Приятного аппетита!','https://vkuso.ru/data/cache/data/6b/ba5bc66392c0a6b_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13372,'Измельчить ножом квашеную капусту.','https://vkuso.ru/data/cache/data/8c/6ad38f384b1ac8c_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13372,'Измельчить ножом репчатый лук.','https://vkuso.ru/data/cache/data/f4/9c5b91c466944f4_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13372,'Сложить капусту и лук к куриному фаршу.','https://vkuso.ru/data/cache/data/47/ee41a0bc6064a47_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13372,'Вбить яйцо.','https://vkuso.ru/data/cache/data/47/7942bb80a3c7c47_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13372,'Добавить манную крупу.','https://vkuso.ru/data/cache/data/46/a6040fba0d7eb46_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13372,'Посолить и поперчить по вкусу, добавить любые сухие травы.','https://vkuso.ru/data/cache/data/38/f07d4072e3e5c38_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13372,'Хорошо вымесить фарш и оставить на 20 мин.','https://vkuso.ru/data/cache/data/10/c4a5cc1fb618610_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13372,'Сформировать котлеты и обвалять в панировочных сухарях.','https://vkuso.ru/data/cache/data/54/39c3728f7563f54_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13372,'Жарить котлеты на растительном масле на огне чуть менье среднего под крышкой.','https://vkuso.ru/data/cache/data/c0/9154c2d6a1a28c0_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13372,'Примерно через 10 мин перевернуть.','https://vkuso.ru/data/cache/data/38/17f3ff966e27638_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13372,'Жарить еще примерно 10 минут с другой стороны.','https://vkuso.ru/data/cache/data/7a/2086177ee8dca7a_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13373,'Замесить тесто из пшеничной муки и холодной воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13373,'Массу оставить на час для подъема.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13373,'Добавить соль, подсолнечное масло, продукты перемешать, тесто должно быть эластичным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13373,'Посуду для выпекания смазать жиром, выложить тесто на час.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13373,'Поднявшуюся массу обмять, оставить еще час, процесс повторить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13373,'Готовый продукт разрезать на несколько частей по 250 грамм.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13373,'Выложить изделия на противень, поставить в духовой шкаф на три четверти часа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13373,'Температура выпекания – сорок градусов, влажность – тридцать процентов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13373,'За пять минут до окончания приготовления этот показатель повысить до ста процентов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13373,'Прибавить температуру до 260 градусов, готовить хлеб в течение тринадцати минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13373,'Температуру убавить до 180 градусов, дверцу приоткрыть, печь пять минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13374,'Приготовить опару из пшеничной и ржаной муки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13374,'Влить воду, добавить материнскую закваску.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13374,'Ингредиенты перемешать, емкость накрыть пленкой, оставить на полтора часа при комнатной температуре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13374,'Затем поставить продукт в холодильник на 20 часов, температура – восемь или девять градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13374,'Вынуть опару из холодильника, оставить в тепле на час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13374,'Растворить в подогретом молоке сахарный песок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13374,'В отдельной емкости смешать воду и пшеничную муку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13374,'Влить сладкое молоко, опару, всыпать соль.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13374,'Массу перемешать при помощи ложки и миксера.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13374,'Тесто должно постоять два часа.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13374,'Каждые полчаса массу раскатывать, складывать конвертом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13374,'Тесто должно приобрести упругость.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13374,'Массу разделить пополам, сформовать батоны, выложить на присыпанный мукой противень.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13374,'Изделия должны постоять в течение часа. Температура выпекания – 230 градусов, время – пятнадцать минут, влажность – средняя.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13374,'Дверцу приоткрыть, готовить хлеб еще три четверти часа.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13375,'Хлеб для приготовления тостов необходимо разрезать на 2 (4) части, чтобы придать ему вид маленьких треугольников. Каждый из таких кусков смазать майонезом и выложить на него листик салата. Вместо майонеза можно растереть варенный яичный желток с майонезом до однородной консистенции, и уже этой смесью намазать хлеб, уложив сверху листик салата, либо просто намазать хлеб маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13375,'Слегка подкопченную (можно использовать слабосоленую) рыбу нарезать на тонкие ломтики. Каждый из таких ломтиков согнуть пополам и проколоть шпажкой (получается парус, который необходимо воткнуть в бутербродик). Также ломтики рыбы можно свернуть в трубочку и зафиксировать на хлебе благодаря использованию шпажек или зубочисток (тогда бутерброды легко будет брать со стола) или просто ломтик рыбы просто уложить на листик салата.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13375,'Последний штрих: бутерброды украсить веточкой петрушки или укропа. Закуска готова!',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13376,'Солод и молотый кориандр всыпать в емкость хлебопечки, влить немного кипящей воды.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13376,'Оставить настой на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13376,'Добавить еще немного воды, сахарный песок, растительное масло, натуральный мед, соль.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13376,'Всыпать ржаную и пшеничную муку, дрожжи, клейковину.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13376,'Замесить тесто руками или с помощью любого кухонного агрегата.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13376,'Через двадцать минут тесто увеличится втрое.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13376,'Продукт обмять, дать подойти, выставить программу «Бородинский хлеб». Время работы хлебопечки – один час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13376,'Посыпать изделие зернами кориандра, печь до готовности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13377,'Нарезаем лук.','https://vkuso.ru/data/cache/data/68/980227edbb61168_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13377,'Измельчаем чеснок.','https://vkuso.ru/data/cache/data/6d/fdd5adbf662276d_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13377,'Баклажаны – кубиком.','https://vkuso.ru/data/cache/data/0b/ed0b51a7f514e0b_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13377,'Паприку – крупно.','https://vkuso.ru/data/cache/data/8e/cc0283350e5c98e_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13377,'Корень петрушки (опционально).','https://vkuso.ru/data/cache/data/04/1ddeda20d0b6204_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13377,'Морковь – кубиком.','https://vkuso.ru/data/cache/data/9c/0d967c713eacb9c_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13377,'Картофель – крупно.','https://vkuso.ru/data/cache/data/8c/ba9a163e0094d8c_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13377,'Обжарить овощи.','https://vkuso.ru/data/cache/data/20/e5924df40418820_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13377,'С томатом и водой тушить 20 мин.','https://vkuso.ru/data/cache/data/3e/67c1cdaa400df3e_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13377,'Заложить специи и зелень.','https://vkuso.ru/data/cache/data/0c/0ddd2c09ed0d40c_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13378,'Мягкое сливочное масло перемешать с яйцами, взбить в пену вместе с сахарным песком. Использовать миксер.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13378,'Продукт перемешать со сметаной и еще раз взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13378,'Пшеничную муку всыпать порциями, вместе с разрыхлителем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13378,'Подлить коньяк.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13378,'Готовую массу переложить в чашу хлебопечки, всыпать цукаты или изюм без косточек.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13378,'Выставить программу выпечки кекса на полтора часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13379,'Замесить тесто из муки и воды в хлебопечке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13379,'Массу вынуть из контейнера, помять руками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13379,'Подсыпать муку небольшими порциями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13379,'Плотную массу переложить обратно в хлебопечку, включить программу выстойки до нужной кондиции.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13380,'Для крема: смешиваем молоко со сгущенным молоком и добавляем лимонный сок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13380,'Любую форму подходящего размера  с бортиками выстилаем пищевой пленкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13380,'Выкладываем слоями печенье (у меня со вкусом топленого молока) и смазываем кремом. Заполняем форму полностью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13380,'Когда форма заполнится закрываем тортик свисающими концами пленки и отправляем его на ночь в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13380,'Украшать торт можно на свое усмотрение. Я украсила крошкой из печенья и шоколадом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13381,'Ржаную муку развести подогретой водой, поставить в тепло на несколько суток.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13381,'Закваску можно хранить в холодильнике.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13381,'Поместить в емкость хлебопечки ржаную и пшеничную муку, закваску, соль, влить воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13381,'Выставить программу для выпекания бездрожжевого теста.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13382,'В чашу прибора всыпать живые дрожжи, муку, сушеные прованские травы, соль, сушеный чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13382,'Влить воду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13382,'Выставить режим «Тесто» на два часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13382,'Подошедшее тесто вынуть, сформовать два небольших батона.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13382,'Чашу смазать оливковым маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13382,'Поместить тесто, выставить режим «Выпечка» со «Средней» корочкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13382,'Время приготовления – один час.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13383,'Нарезать картошку тонкими полу-кружочками.','https://vkuso.ru/data/cache/data/ee/5834931f4cfebee_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13383,'Пожарить картошку на растительном масле до готовности и посолить по вкусу.','https://vkuso.ru/data/cache/data/27/342d44cb95d1127_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13383,'Выложить жареную картошку в форму для запекания, форму ничем не смазывать.','https://vkuso.ru/data/cache/data/c3/4d4f8db9f3bb7c3_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13383,'Нарезать репчатый лук средними кусочками.','https://vkuso.ru/data/cache/data/ff/81623b6709ae0ff_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13383,'И шампиньоны пластинками.','https://vkuso.ru/data/cache/data/1d/a95a2b2ecdcb61d_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13383,'Обжарить лук на растительном масле до прозрачности около 1 мин.','https://vkuso.ru/data/cache/data/e6/dc99efbc5459de6_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13383,'В лук выложить грибы и жарить на сильном огне до полного выпаривания жидкости, легкой румяности грибов и полной готовности.','https://vkuso.ru/data/cache/data/51/600c8144a1f7651_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13383,'Посолить грибы по вкусу и добавить сметану, все перемешать и снять с огня.','https://vkuso.ru/data/cache/data/0a/242909031fb710a_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13383,'Выложить грибы на картошку.','https://vkuso.ru/data/cache/data/c6/42511e2b1e7d5c6_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13383,'Натереть сыр на крупной терке.','https://vkuso.ru/data/cache/data/57/04be491588ab657_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13383,'Выложить сыр на грибы.','https://vkuso.ru/data/cache/data/fa/cc5fd225c744cfa_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13383,'Разложить сверху разрезанные поперек помидоры, слегка утапливая их в сыр.','https://vkuso.ru/data/cache/data/9d/fbf0748435bd59d_434x295_notrise.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13383,'Запекать в духовке 20 мин при 180 С до подрумянивания сыра, духовку разогреть заранее.','https://vkuso.ru/data/cache/data/6f/48ad90e1aa8976f_434x295_notrise.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13383,'Вот такой жульен-запеканка у нас получился.','https://vkuso.ru/data/cache/data/3e/738c6dabce8a13e_434x295_notrise.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13383,'Мягкая картошка, сочные грибы и богатый слой тягучего сыра.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13384,'В контейнер прибора влить теплое молоко, вбить куриные яйца, далее – ванилин, соль, сахарный песок, сливочное масло. Все продукты – комнатной температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13384,'Подготовить изюм, поместить в емкость, затем насыпать муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13384,'Последний ингредиент – дрожжи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13384,'Перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13384,'Выставить программу приготовления и выпечки для дрожжевого теста. Примерное время – около четырех часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13384,'Крышку не открывать, только в этом случае кулич получится пышным.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13384,'Остывшую выпечку украсить глазурью из сахарного песка, соли, белков.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13384,'Массу хорошо взбить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13384,'Украсить кулич готовой кулинарной посыпкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13385,'В емкость хлебопечки влить теплую воду, всыпать соль, прованские травы, муку, сахарный песок, сухие дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13385,'Выставить основной режим хлебопечения, корочка – «Средняя».',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13385,'Влить растительное масло в конце замеса, все продукты должны быть комнатной температуры.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13386,'Приобрести в аптеке специальную закваску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13386,'Свежее деревенское молоко довести до кипения, остудить до сорока градусов, перелить в емкость хлебопечки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13386,'В небольшом количестве подогретого молока развести порошок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13386,'Вылить закваску в емкость, перемешать, добавить нарезанные фрукты или любимый джем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13386,'Выставить программу «Йогурт» на восемь часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13386,'Если продукт получился жидким, его лучше поставить в холодильник до загустения.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13387,'Влить в емкость хлебопечки кефир, всыпать соль и пищевую соду, сахарный песок, вбить сырое яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13387,'Добавить пшеничную муку, предварительно продукт хорошо просеять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13387,'Выставить режим «Бездрожжевой хлеб» или другой, с быстрой выпечкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13387,'Тесто должно быть замешано за десять минут, время тепловой обработки – около часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13387,'Если продукт плохо пропекся, то выставить режим «Выпекание» еще на пятнадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13387,'Время и режимы по-разному работают в разных хлебопечках, лишь пробы и ошибки помогут кулинару выбрать наиболее правильные пути приготовления тех или иных продуктов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13388,'Влить в емкость хлебопечки теплую воду, рафинированное растительное масло, готовую закваску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13388,'Всыпать сухие ингредиенты – сахарный песок, соль, ржаную и пшеничную муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13388,'Оба вида муки предварительно просеять для насыщения продуктов кислородом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13388,'Время замеса – пятнадцать минут, выстойка – четыре с половиной часа, выпечка – полтора часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13389,'Соль, ржаную и пшеничную муку перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13389,'Отдельно перемешать закваску с водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13389,'Обе смеси соединить, вымесить с помощью деревянной ложки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13389,'Готовый продукт переложить в форму, оставить в тепле на пять или шесть часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13389,'Прогреть духовой шкаф до 240 градусов, печь хлеб в течение десяти минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13389,'Нагрев уменьшить до 200 градусов, печь девяносто минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13390,'Хлеб готовится точно так же, как и в духовом шкафу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13390,'Перемешать два вида муки, пшеничную и ржаную, с солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13390,'Развести водой закваску.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13390,'Смеси соединить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13390,'Тесто положить в емкость для расстойки на пять или шесть часов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13390,'Выставить температуру для выпечки в 130 градусов, время – один час.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13390,'Далее мультиварку открыть, хлеб перевернуть, печь еще час, температура – та же.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13391,'Поставим кастрюлю на огонь. Зальем масло и добавим лук, томатную пасту, немного обжарим и добавим паприку, кумин, чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13391,'Зальем бульоном. В бульон добавим чечевицу, морковь, зеленый лук и оставим на 40- 45 минут на среднем огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13391,'Тем временем приготовим крем. В ступку добавим мяту и хорошо раздавим до однородной массы, туда же добавим цедру, сок лимона и пару ложек йогурта. Все хорошо перемешаем и отложим в сторону до готовности супа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13391,'Далее выключим суп и взобьем блендером. Перед подачей в суп добавить ложку крем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13392,'Развести дрожжи в теплом молоке (можно в воде для постного стола), добавить сахар, перемешать и оставить подходить на 15 мин в теплом месте до вспенивания.','https://vkuso.ru/data/cache/data/57/e94215167b05157_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13392,'Пока подходят дрожжи мелко нарезать оливки без косточек.','https://vkuso.ru/data/cache/data/6b/2b239d27160826b_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13392,'В подошедшие вспенившиеся дрожжи влить теплую воду и оливковое масло.','https://vkuso.ru/data/cache/data/bb/70db392f9d84abb_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13392,'Добавить мёд.','https://vkuso.ru/data/cache/data/bb/0c3516ac2ad1fbb_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13392,'Соль и сухие травы.','https://vkuso.ru/data/cache/data/50/1f762bbaedecf50_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13392,'И все нарезанные оливки. Хорошо перемешать.','https://vkuso.ru/data/cache/data/34/df7c8c17082a434_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13392,'Просеять цельнозерновую муку в полученную смесь частями в 4 приема.','https://vkuso.ru/data/cache/data/79/dff4e6b7021bd79_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13392,'Тщательно перемешивая сначала ложкой.','https://vkuso.ru/data/cache/data/8b/b319e41ea09f28b_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13392,'И в последний раз вымесить тесто руками около 2-3 мин. Тесто получается слегка влажное и немного липнет к рукам.','https://vkuso.ru/data/cache/data/62/05c9a4797075e62_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13392,'Накрыть тесто пленкой и оставить в теплом месте примерно на 45 мин, пока оно не поднимется как минимум в 2 раза.','https://vkuso.ru/data/cache/data/7f/d7ef4c9f8fe5e7f_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13392,'Подошедшее тесто слегка обмять, выложить на присыпанный обычной мукой стол, посыпать этой же мукой сверху еще немного, слегка подмесить, чтобы оно не липло к рукам.','https://vkuso.ru/data/cache/data/71/fbf82d079209471_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13392,'Разделить тесто на 4 части.','https://vkuso.ru/data/cache/data/7f/6959bffdce8927f_434x295_notrise.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13392,'И сформировать шарики, присыпав их также простой мукой сверху.','https://vkuso.ru/data/cache/data/4b/e5b0cf6d3df754b_434x295_notrise.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13392,'Уложить на противень пекарскую бумагу и присыпать ее обычной мукой, выложить булочки на расстоянии друг от друга и оставить подходить еще на 15 мин. Через 15 мин, когда булочки немного увеличатся в размере сделать сверху крестообразные надрезы.','https://vkuso.ru/data/cache/data/fb/7f80b0df0c1bafb_434x295_notrise.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13392,'Выпекать хлеб 45 мин при 180 С в заранее разогретой духовке.','https://vkuso.ru/data/cache/data/69/446548f5423cb69_434x295_notrise.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13392,'Готовый хлеб вынуть из духовки.','https://vkuso.ru/data/cache/data/77/974aadc31f4d177_434x295_notrise.jpg',16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13392,'И накрыть х/б полотенцем до остывани сформировать шарики, присыпав их также простой мукой сверху.','https://vkuso.ru/data/cache/data/ce/aaa173af4b3abce_434x295_notrise.jpg',17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13392,'Вот такой аппетитный ароматный хлебушек у нас получился.','https://vkuso.ru/data/cache/data/54/97e18c470794c54_434x295_notrise.jpg',18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13392,'А вот такой он в разрезе с кусочками оливок.','https://vkuso.ru/data/cache/data/60/bbca71ce6606f60_434x295_notrise.jpg',19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13393,'Налить в кастрюлю овощной бульон, выложить морковь, картофель, кусочек сливочного масла, нарезанный репчатый лук.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13393,'Прогревать до тех пор, пока лук не станет мягким.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13393,'Добавить тертый корень свежего имбиря, любые другие пряности для овощных блюд.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13393,'Довести до кипения под крышкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13393,'Огонь уменьшить, кипятить до готовности моркови.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13393,'Овощи шумовкой переложить в блендер, влить часть бульона, превратить в пюре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13393,'Перелить массу обратно в кастрюлю, влить взбитые сливки, перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13394,'Мягкий творог посолить, добавить сахарный песок, вбить сырое куриное яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13394,'Массу перемешать, немного размять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13394,'Всыпать муку через сито, приготовить тесто. Оно должно быть мягким.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13394,'Сформовать небольшие сырники мокрыми руками, обвалять в панировочных сухарях.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13394,'Обжарить изделия на растительном масле с двух сторон на среднем огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13394,'Время приготовления – десять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13395,'Массу из творога и сахарного песка взбить при помощи миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13395,'Добавить яйцо, сметану, муку, ванилин и пищевую соду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13395,'Тесто вымесить деревянной лопаткой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13395,'Противень застелить пергаментной бумагой, смазать сливочным маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13395,'Выложить сырники большой мокрой ложкой. Время запекания – семь минут, температура – 170 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13395,'Перевернуть, печь еще столько же.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13395,'Изделия не должны пересохнуть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13396,'Сметану прогреть на водяной бане.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13396,'Всыпать манку, через десять минут она должна разбухнуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13396,'Отдельно приготовить массу из творога с ванилином, сырым яйцом и сахарным песком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13396,'Обе смеси соединить, всыпать крахмал.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13396,'Разогреть сковороду, жарить сырники на масле, по две минуты с каждой стороны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13397,'Мягкий творог перемешать с солью, сахарным песком, вбить сырое куриное яйцо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13397,'Массу размять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13397,'Всыпать муку через сито.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13397,'Приготовить тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13397,'Сформовать колобки, обвалять в панировке, придать сырникам вид небольших котлет.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13397,'Обжарить на подсолнечном масле без запаха с двух сторон, огонь – средний.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13397,'Время приготовления – около десяти минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13398,'У рыбных тушек удалить головы, плавники, хвосты, вынуть внутренности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13398,'Филе промыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13398,'Отжать сок из лимона, натереть им тушки изнутри и снаружи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13398,'Втереть специи: паприку, перец, соль.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13398,'Поставить рыбу в холодильник для пропитывания, время – от часа до двух.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13398,'Решетку мангала смазать растительным маслом, выложить тушки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13398,'Во время обжаривания скумбрию сбрызгивать лимонным соком.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13398,'Время приготовления рыбного шашлыка – двадцать минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13399,'Из белого хлеба с помощью бокала нарезать круглые основы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13399,'Кружки выложить на застеленный пергаментом противень, сушить в духовом шкафу в течение пяти или семи минут, температура – 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13399,'Мягкий творожный сыр перемешать с рубленой зеленью укропа, смазать охлажденный хлеб.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13399,'Огурцы вымыть, обсушить, нарезать наискосок тонкими ломтиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13399,'Положить по ломтику на каждый бутерброд.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13399,'Красную слабосоленую рыбу порезать длинными тонкими полосками.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13399,'Свернуть розочками, выложить по штуке на каждый канапе, украсить укропом.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13400,'3 банана ломаем в миску, и перетираем при помощи вилки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13400,'Песочное печенье нужно измельчить в крошку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13400,'К песочной крошке добавляем подготовленные бананы, добавляем арахис и все перемешиваем. Временно отправляем в холодильник, чтобы масса охладилась.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13400,'Далее из охлажденной массы катаем шарики, часть из них обсыпаем к кокосовой стружке, другую часть обсыпаем в какао, или шоколадном порошке, и снова можно отправить в холодильник, на 30 минут. Достаем и подаем к чаю)',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13401,'Творожный сыр намазать на ломтики ржаного хлеба.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13401,'Помидоры вымыть и обсушить, нарезать тонкими кружками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13401,'Выложить овощи на хлеб, присыпать рубленым зеленым луком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13402,'Салат латук вымыть, обсушить, порвать руками и выложить на кусочки ржаного хлеба.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13402,'Творожный сыр перемешать со свежим рубленым базиликом, черным перцем грубого помола.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13402,'Массу выложить на бутерброды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13402,'Сверху – свежие огурцы, нарезанные наискосок.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13402,'Украсить листочками базилика.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13403,'Приготовить тесто, для этого просеять муку с разрыхлителем, добавить сахар, соль, немного соды. Охладить кусок сливочного масла, натереть на терке, всыпать в муку и перетереть руками в крошку. Влить молоко, замесить довольно густое тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13403,'Раскатать в виде тонкого прямоугольника на присыпанной мукой доске. Разрезать тесто на равные части, тоже прямоугольной формы. Выложить на них кусочки горького шоколада. Закатать «начинку» в тесто, защипать края. Булочки сверху смазать чуть взбитым яйцом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13403,'Печь при температуре 210 градусов в течение 15– 20 минут. При образовании золотистой корочки достать булочки из духового шкафа. Готовую выпечку можно посыпать сахарной пудрой. Подать домашние булочки с шоколадной начинкой в теплом виде, с кофе, молоком, чаем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13404,'Крупные, спелые, яблоки вымыть, срезать верхнюю часть. Аккуратно вырезать сердцевину так, чтобы плод не развалился, толщина стенок должна быть в полсантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13404,'Нарезать изюм без косточек, порубить грецкий орех, смешать. Всыпать начинку в яблоко. Печь при 180 градусах 20 – 25 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13404,'Приготовить соус: смешать йогурт, немного мёда, тертую цедру апельсина и сок лимона по вкусу. Соус должен постоять примерно полчаса. Полить готовые запеченные яблоки с начинкой из орехов и изюма.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13405,'Приготовить блинчик обычным способом. Разогреть на сковороде растительное масло, выложить блинчик, на середину разбить яйцо, так, чтобы не повредить желток, соль – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13405,'Можно разнообразить блюдо кубиками ветчины, колбасы, сосисок, их нужно насыпать на блинчик, а уже затем залить яйцом. Сверху посыпать тертым сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13405,'Края блинчика аккуратно завернуть наверх с четырех сторон (получится квадрат). Жарить оригинальную яичницу в блине под крышкой на тихом огне до готовности яйца. Сразу подать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13406,'Скумбрию подготовить, промыть в холодной воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13406,'Выложить тушки в пластиковый контейнер, подлить соевый соус, оставить для пропитывания на полчаса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13406,'Через каждые пять или семь минут рыбу переворачивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13406,'Порубить зелень укропа или базилика, перемешать с давленым чесноком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13406,'Помидоры нарезать крупными дольками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13406,'Нафаршировать рыбные тушки чесноком, зеленью и томатами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13406,'Рыбу жарить на смазанной решетке на мангале, время – от двадцати до двадцати пяти минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13407,'Рыбу почистить и вымыть, тушки разрезать поперек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13407,'Кусочки выложить в пластиковый контейнер, полить белым сухим вином, поставить на час или на два в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13407,'За время маринования куски рыбы несколько раз перевернуть.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13407,'Продукт вынуть из емкости, натереть солью, тертым мускатным орехом и прованскими травами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13407,'Куски фольги смазать растительным маслом с внутренней стороны.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13407,'Выложить рыбу, завернуть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13407,'Время запекания на мангале – от тридцати пяти до сорока минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13408,'Удалить хвосты и головы, выпотрошить рыбу, промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13408,'Натереть тушку лимонным соком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13408,'Посыпать специями.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13408,'Поставить рыбу в холодильник на час или два.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13408,'Решетку для мангала смазать маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13408,'Жарить рыбу в течение двадцати минут, сбрызгивать свежим лимонным соком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13409,'Зубчики чеснока очистить, пропустить через пресс, жарить на оливковом масле в течение пяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13409,'Чеснок должен стать золотистым.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13409,'Поместить в чашу блендера рубленую зелень, чеснок, превратить массу в зеленое пюре в течение одной минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13409,'Полученную смесь добавить в творожный сыр, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13409,'Еще несколько зубчиков чеснока порубить и обжарить на растительном масле, огонь – средний.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13409,'Добавить креветки, прогревать до золотистого цвета в течение пяти или шести минут, помешивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13409,'Багет разрезать пополам, вдоль, затем каждую половину – ломтиками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13409,'Намазать творожной массой, выложить жареные креветки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13409,'Противень застелить пергаментом, поставить в духовку на пять минут, температура приготовления – 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13409,'Бутерброды посыпать тертым твердым сыром, печь еще пять минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13410,'Мелко нашинковать маринованные огурцы, перемешать с творожным сыром, репчатым луком, тертым твердым сыром, рубленой зеленью, тертым хреном.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13410,'Состав заправить натуральным йогуртом без красителей, поперчить и посолить по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13410,'Вымыть листья салата латук, обсушить, выложить на большую тарелку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13410,'На каждый лист положить намазанный сырной массой зерновой хлеб.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13410,'Далее – ломтики ветчины, кружки томатов, нарезанный соломкой сладкий желтый перец.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13411,'Мягкий творожный сыр перемешать с давленым чесноком, тертыми крабовыми палочками, перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13411,'Очистить от кожуры киви, нарезать кружками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13411,'Выложить сырную массу на кружочки багета, сверху – киви.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13412,'Мягкий творожный сыр смешать с тертым свежим хреном, солью, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13412,'Выложить массу на ломтики белого хлеба.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13412,'Украсить бутерброды кружочками редиса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13413,'Грушу вымыть, обсушить, разрезать вдоль.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13413,'Сердцевину вынуть ложкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13413,'Каждую половину нарезать ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13413,'Багет нарезать, смазать мягким творожным сыром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13413,'Сверху выложить веером нарезанный фрукт, поставить бутерброды в духовку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13413,'Время запекания – от семи до десяти минут, температура – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13413,'Готовый десерт полить жидким натуральным медом, украсить рублеными тыквенными семечками, посыпать молотой корицей.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13414,'Багет нарезать на ломтики по три или четыре сантиметра толщиной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13414,'Смазать творожным шоколадным сыром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13414,'Сверху – пластинки очищенного банана.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13414,'Каждый сладкий бутерброд полить шоколадным сиропом и присыпать толчеными кедровыми орехами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13414,'Шоколадный сироп можно приготовить самостоятельно.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13414,'Поставить на водяную баню небольшую емкость, влить воду, добавить ванильный сахар, подержать на тихом огне.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13414,'Всыпать кусочки темного шоколада, довести до кипения, огонь выключить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13414,'Влить жирные сливки, хорошо перемешать и остудить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13415,'Чечевицу залить 300 мл воды и поставить на огонь. Довести до кипения, варить на медленном огне до готовности (около 30 минут).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13415,'Лук нарезать полукольцами и обжарить на растительном масле на медленном огне в течении 3 минут, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13415,'Затем добавить очищенные целые зубчики чеснока, финики без косточек и готовим еще 5 минут, перемешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13415,'В чашу для блендера отправить грецкие орехи, содержимое сковороды, соль, перец, чечевицу и сок лимона измельчить. Если масса слишком густая и блендер не справляется разбавьте кипяченой водой (40 мл).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13416,'Говядину нарезать на маленькие кусочки, обжарить в кастрюле на среднем огне 7 минут, перемешивая.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13416,'Лук репчатый очистить, нарезать четвертькольцами. Отправить лук в кастрюлю, готовить на среднем огне 10 минут, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13416,'Морковь очистить. Морковь и помидор нарезать маленькими кубиками, добавить в кастрюлю. Также добавить томатную пасту, готовить на среднем огне 10 минут, перемешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13416,'По истечении 10 минут добавить специи (соль, паприку, перец, барбарис, лавровый лист, зиру, сушеные базилик, укроп и чеснок), перемешать, залить водой (600 мл). Греем 5 минут и потом засыпаем маш, накрываем крышкой и варим 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13416,'Картофель очистить, нарезать кубиком, добавить в кастрюлю и засыпать рис. Вливаем еще воды (1 литр) накрываем крышкой, доводим до кипения и варим 30 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13417,'В миску высыпать муку, добавить растительное масло (3 ст. л.), выжать сок лимона, добавить соль (1/4 ч. л.), влить теплую воду. Замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13417,'Лук репчатый нарезать мелким кубиком. Обжариваем в сковороде на растительном масле на среднем огне до золотистого цвета, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13417,'Белокочанную капусту мелко нашинковать, отправить в сковороду к луку и сразу же добавить квашеную капусту. Готовим на среднем огне 20 минут, перемешивая. Добавить сахар, соль (1/2 ч. л.), перец, мелко нарезанные укроп и половину петрушки (10 гр) – снимаем с огня.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13417,'На чистую сухую сковороду высыпать панировочные сухари, добавить растительное масло (3 ст. л.), чеснок пропущенный через пресс. Обжариваем на сильном огне до золотистого цвета, перемешивая. Добавляем оставшуюся мелко нарезанную петрушку (10 гр) – перемешиваем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13417,'На стол выкладываем пекарскую бумагу, посыпаем мукой и на ней раскатываем тесто. Выкладываем на тесто панировочные сухари отступив с одной стороны 5-6 см и по бокам 2 см, поверх сухарей выложить капустную смесь. Сверните тесто в рулет, начинайте сворачивать от начинки к отступу, защипнуть края.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13417,'Наколоть сверху рулет вилкой, чтобы выпустить воздух. Смазать верх рулета растительным маслом. Ставим рулет в разогретую духовку до 200 градусов на 20 минут. Достаем рулет и снова смазываем растительным маслом, отправляем еще на 20 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13418,'Репчатый лук очистить и нарезать тонкими полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13418,'В казан или глубокую сковороду налить растительное масло и раскалить его на сильном огне. Затем добавить нарезанный лук и обжариваем на сильном огне 7 минут, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13418,'Говядину или баранину нарезать небольшими кусочками, добавить в луку и жарить 15 минут, перемешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13418,'Морковь очистить и резать длинной, но тонкой соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13418,'Добавить в казан, посолить и продолжаем готовить на сильном огне 10 минут, перемешивая.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13418,'По истечении 10 минут добавить специи (зиру, барбарис, куркуму, паприку и шафран) и залить водой (600 мл).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13418,'Чеснок очистить от верхней шелухи, не разламывать чеснок на зубчики. Нам нужна целая головка чеснока. Добавить головки чеснока в казан, накрыть крышкой, убавить немного огонь (до середины) и готовить 20 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13418,'По истечении времени вынуть чеснок, но не выкидывать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13418,'Рис хорошо промыть и добавить в казан, залить водой. Рис должен быть покрыт бульоном на два сантиметра.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13422,'Полить только что испеченный манник горячим сиропом и дать полностью остыть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13418,'Готовим рис на среднем огне 25 минут. Отодвигаем рис от стенок, делаем небольшие отверстия деревянной палкой, таким образом перемешиваем, чтобы рис не пригорел.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13418,'Спустя 25 минут выкладываем обратно головки чеснока, накрываем крышкой. Готовим на медленном огне до полного выкипания воды.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13419,'Срезаем с пашины пленочки и лишний жир.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13419,'Натираем солью и специями для свинины с обеих сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13419,'Чеснок измельчаем чеснокодавилкой и смазываем им внутреннюю часть рулета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13419,'Сворачиваем рулет и обвязываем его ниткой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13419,'Вкладываем рулет в рукав для запекания, завязываем его с обеих сторон, предварительно выпустив воздух и делаем сверху несколько проколов зубочисткой.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13419,'Пока рулет горячий, удаляем нитки. Даем ему остыть и нарезаем. Всем добра!',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13420,'В теплое молоко 100 мл добавить дрожжи 7 гр (1 пакетик), 1 ч л сахара и 1 ст.л. муки, перемешать и поставить в теплое место на 15 мин до вспенивания.','https://vkuso.ru/data/cache/data/e8/c7306f44321ebe8_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13420,'В подошедшие дрожжи добавить ванильный сахар 40 гр (или обычный сахар + ваниль), 2 яйца комнатной температуры, растопленное, но не горячее сливочное масло 100 гр и 1/2 ч л соли. Все хорошо перемешать.','https://vkuso.ru/data/cache/data/16/36023c0555db316_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13420,'В получившуюся смесь просеять в два приема муку, перемешивая ложкой. Тесто должно получится вязкое и липкое. Накрыть тесто пленкой и поставить в теплое место на 45-60 мин до увеличения объема в 2-3 раза.','https://vkuso.ru/data/cache/data/1b/27bd4d9abf3d81b_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13420,'Когда тесто поднимется выложить его в форму для запекания (у меня 28х22 см), смазанную растительным маслом и присыпанную мукой. Разровнять поверхность теста лопаточкой, смазанной растительным маслом. Накрыть форму пленкой и поставить еще раз в теплое место на 35-45 мин до увеличения объема еще в 2-3 раза.','https://vkuso.ru/data/cache/data/28/29445e6fa6e0728_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13420,'Пока подходит тесто приготовить обсыпку. Растереть вилкой холодное сливочное масло 50 гр с сахаром 140 гр до получения однородной маслянистой крошки.','https://vkuso.ru/data/cache/data/97/ef3e8e9a3dcb697_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13420,'В подошедшем тесте сделать отверстия обратной стороной ложки, смазанной растительным маслом.','https://vkuso.ru/data/cache/data/ca/2d9a5bf2a535eca_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13420,'И равномерно посыпать масляной крошкой.','https://vkuso.ru/data/cache/data/f9/61d8d4c95fcd8f9_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13420,'Поставить пирог в заранее разогретую духовку. Выпекать 35 мин при 170-180 С до среднего подрумянивания верха и готовности теста. Готовность проверить зубочисткой.','https://vkuso.ru/data/cache/data/80/0e87841b4ed5c80_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13420,'Вынуть пирог из духовки и равномерно полить сливками 10% жирности 200 мл.','https://vkuso.ru/data/cache/data/da/842b21cdb57ceda_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13420,'Снова поставить пирог в духовку и выпекать еще 10 мин. Пирог должен еще немного подрумяниться, а сливки полностью впитаться.','https://vkuso.ru/data/cache/data/5d/bd82d359a39c75d_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13420,'Готовому пирогу дать остыть и осторожно извлечь из формы способом переворачивания двух тарелок.','https://vkuso.ru/data/cache/data/c1/26cc957c2840bc1_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13421,'Воду, сахар и масло поставить на тихий огонь и постоянно помешивая до растворения в однородную массу все ингредиенты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13421,'Далее, добавить муку и так же до загустения.после переложить в миску и дать остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13421,'После того как масса остынет добавить яйца по одному до смешивания яйца, потом добавьте второе яйцо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13421,'После переложим тесто в кондитерский мешок с насадкой для крема звездочка.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13421,'После растительное масло разогреем в кастрюле и тесто произвольного размера опустим в масло и обжарим до золотистого цвета.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13422,'Измельчить очищенные апельсины блендером в 200 мл пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13422,'Апельсиновое пюре смешать с манкой и оставить набухать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13422,'Через 20 минут добавить сахара, муку, разрыхлитель, растительное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13422,'Выпекать в разогретой до 180°С 30 минут в смазанной растительным маслом форме.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13422,'За 5 минут до готовности манника приготовить сироп смешав апельсиновый сок с сахаром. Довести сок до кипения и проварить несколько минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13423,'Нарезаем хлеб на сухарики, перекладываем на противень и отправлением в духовки при 180 С на 15-20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13423,'Пока сухарики в духовке, можно сделать соус. Мелко нарезаем укроп, перекладываем в тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13423,'Выдавливаем чеснок, добавляем сметану 3 ст.л., соль перец по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13423,'Натираем сыр на мелкой терке туда же, и все хорошо перемешиваем. Даем соусу настояться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13423,'Достаем сухарики из духовке, немного даем остыть, и перекладываем в миску, к ним добавляем соус, и все хорошо перемешиваем. И снова сухарики перекладываем на противень, и отправляем в духовку при 180 С на 15-20 минут. Рекомендую следить, что бы сухарики не подгорели! Достаем и подаем к пиву, или просто к столу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13424,'Разогреем каструлю, зальем масло, добавим лук,морковь, сельдерей и в течении 5 минут обжариваем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13424,'Далее заливаем вино, туда же выдавливаем чеснок,томатную пасту , бальзамический уксус и орегано. Размешиваем и через 2 минуты добавляем порезанные баклажаны, грибы, чечевицу, бульон и томаты в собственном соку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13424,'Далее добавим соль, перец. Накроем крышкой и оставим на минут 45-50. Периодически помешивая.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13424,'За пару минут до готовности заливаем молоко и соевый соус. Соус готов. Можно подавать к пасте или использовать как гарнир.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13425,'Взбить в однородную массу сахар, мак, яйца, стружку кокоса и размягченное сливочное масло. Взбить сметану, добавить просеянную муку с разрыхлителем, объединить и перемешать с яично-кококосовой массой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13425,'Переложить тесто в смазанную чашу мультиварки, выпекать основу для маково-кокосового торта в режиме «Выпечка» 65 минут. Если готовить в духовке, то температура должна быть 180 градусов, а время порядка 40 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13425,'Разрезать готовую и остывшую основу на три одинаковых по толщине коржа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13425,'Из муки, молока, яиц и сахара  приготовить крем следующим образом. Чуть-чуть молока смешать миксером с мукой, яйцом, сахаром. Оставшееся молоко подогреть и вылить в него взбитую ранее смесь, при слабом нагреве довести крем до сгущения, дать ему остыть и вмешать пачку размягченного (но не растопленного) масла, можно это сделать миксером.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13425,'Промазать коржи кремом, верх оформить кокосовыми чипсами, готовому торту для улучшения вкуса  надо дать постоять. Приятного и вкусного чаепития!',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13426,'Разрезать размороженную тушку скумбрии с головой вдоль хребта, удалить спинной плавник, вырезать ножницами хребет, удалить жабры и ребра, аккуратно выпотрошить, тщательно удалить черную пленочку с брюшка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13426,'Мелко порубить лук, обжарить на хорошо разогретом масле до изменения цвета, добавить порезанные грибы, обжарить до испарения сока. Включить духовку для разогрева на 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13426,'Потушить в сотейнике овощи (можно использовать смесь из соцветия цветной капусты, белой  и стручковой фасоли), приправить черным молотым перцем, солью, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13426,'Объединить овощи и грибы с мелко порубленной зеленью, перемешать, рыбу сбрызнуть с двух сторон соком лимона, нафаршировать овощной смесью.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13426,'Переложить тушку скумбрии спинкой вверх на противень, сколоть зубочисткой спинку у хвоста, чтобы получить лодочку, поперчить, присыпать измельченным сыром. Задвинуть противень в прогретую духовку.  Скумбрия, фаршированная  шампиньонами и овощами, будет готова примерно через полчаса.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13427,'В глубокой тарелке или кастрюле смешать молоко, сахар, ванильный сахар, соль, дрожжи – перемешать. Вбить яйцо. Сливочное масло растопить и добавить в тарелку, перемешивать. Постепенно всыпать муку и замесить тесто. Накрыть тарелку пленкой и поставить тесто в теплое место на 1 час.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13427,'Спустя час слегка обмять тесто, снова накрыть пленкой и поставить тесто еще на 1 час в теплое место.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13427,'Поверхность для раскатки теста обильно присыпаем мукой, замешиваем тесто (при необходимости подсыпать еще муки, чтобы тесто не липло к рукам).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13432,'Тем временем приготовим остальную часть. Яйца перемешаем с оставшимся сахаром, ванилином и корицей, добавим 50 г размягченного масла, цедру одного апельсина и апельсиновый сок, перемешаем и добавим опару, опять перемешаем до однородности и просеем всю муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13427,'Раскатываем тесто, вырезаем круги и формируем булочки. Складываем круги в линию один на один по 3 штуки (внахлест). Сворачиваем кружочки в рулет и разрезаем их поперек (на 1 булочку 4 половинки). Ставим на противень, застеленный бумагой половинки впритык (во время выпекания тесто поднимется и половинки склеятся).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13427,'Булочки отправляем в разогретую духовку до 200 градусов на 20 минут. Готовые булочки посыпать сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13428,'Нежирную свинину вымыть,  обсушить салфеткой и нарезать кусками толщиной 2-2,5 см. поперек волокон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13428,'Приготовить из раздавленного чеснока и сока половины лимона маринад, положить в него на час-полтора кусочки мяса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13428,'Приготовить из пары столовых ложек натертого имбиря, столовой ложки меда, коньяка и половинки, нарезанного колечками стручка горького перца, соус. Включить прогреться духовку до 160 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13428,'Достать промаринованное мясо, обсушить салфеткой, обжарить в разогретом масле с одной и другой стороны до образования зажаренной корочки, вынуть мясо, переложить в форму для запекания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13428,'В сковороду налить соус, прогреть, помешивая секунд 15-20, залить мясо. Форму со свининой в имбирно-медовом соусе с коньяком и чесноком тщательно запаковать фольгой, убрать на треть часа в прогретую духовку. Подавать блюдо горячим, оформив веточками зелени.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13429,'На разогретом растительном масле обжарить мелко нарезанный репчатый лук до прозрачности и легкого подрумянивания.','https://vkuso.ru/data/cache/data/53/169f04dec5bca53_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13429,'Добавить к луку мясной фарш и обжарить до изменения цветв на огне выше среднего, затем добавить к фаршу резаные помидоры, перемешать и обжарить до выпаривания жидкости, посолить и поперчить по вкусу.','https://vkuso.ru/data/cache/data/d6/2c9b831302449d6_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13429,'В готовый фарш выдавить чеснок, перемешать и снять с огня.','https://vkuso.ru/data/cache/data/74/ffa6a3ba1ca9574_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13429,'Сварить картошку до готовности, добавить молоко и сливочное масло, выдавить чеснок, посолить по вкусу и сделать пюре.','https://vkuso.ru/data/cache/data/87/020ba2d7f416087_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13429,'Смазать формочки или горшочки сливочным маслом.','https://vkuso.ru/data/cache/data/b8/693812bd6bd5bb8_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13429,'Уложить сначала слой пюре.','https://vkuso.ru/data/cache/data/78/8700abdb4998f78_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13429,'Сверху на пюре уложить слой фарша.','https://vkuso.ru/data/cache/data/6b/db6549add87f96b_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13429,'Сверху на фарш уложить еще один слой пюре.','https://vkuso.ru/data/cache/data/da/423a8ff8a61a7da_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13429,'На последний слой пюре сверху уложить тертый сыр.','https://vkuso.ru/data/cache/data/31/103909693a59831_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13429,'Поставить в заранее разогретую до 180 С духовку на 20-30 мин до подрумянивания сыр.','https://vkuso.ru/data/cache/data/69/d19c7ca56f80e69_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13429,'Готовую запеканку по желанию посыпать зеленым луком и срочно подавать к столу, пока она не остыла.','https://vkuso.ru/data/cache/data/f3/4c3506e7dc436f3_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13430,'Измельчить на терке твердый сыр и сваренные вкрутую и остывшие яйца, порезать рыбу и мясистые помидоры на кубики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13430,'Положить в салатник слой рыбы, смазать майонезом, присыпать слоем тертых яиц, смазать майонезом, а поверх – тертым сыром с майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13430,'Верх салата из форели, сыра и яиц закончить слоем помидоров, смазать майонезом, присыпать рубленой петрушкой или зеленым луком, отправить постоять на пару часов в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13431,'Нарезать кубиками картофель, лук и ветчину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13431,'В кастрюле разогреть растительное масло и обжарить ветчину на среднем огне.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13431,'Растопить в кастрюле сливочное масло. Обжарить лук до золотистости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13431,'Добавить муку и хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13431,'Влить куриный бульон и молоко.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13431,'Добавить картофель и варить на среднем огне около 15-25 минут (зависит от того как быстро сварится картошка).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13431,'Выложить в кастрюлю обжаренную ветчину. Посолить, поперчить по вкусу. Добавить сметану и сыр, хорошо перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13432,'Для начала приготовим опару. Нам понадобится половину всего количества сахарного песка добавляем теплое молоко и дрожжи и оставляем накрытым полотенцем в теплом месте минут на 20.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13432,'Замесим тесто. После тесто накроем полотенцем и оставим на час-полтора подходить.Тесто должно увеличится в два раза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13432,'После того как тесто подошло раскатаем его на рабочей поверхности в тоненький пласт, смажем оставшимся мягким маслом и посыпим равномерно измельченными орехами и заранее вымытым и просушенным кишмишом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13432,'После закатаем в рулет и разрежем пополам оставляя в конце 2 см.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13432,'Далее одну часть свернем в круг разрезами снаружи, а вторую половинку также свернем и положим сверху.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13432,'Переложим в форму для запекания и оставим минут на 15 накрытой кухонным полотенцем.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13432,'После запекаем при 170 градусов минут 45 примерно до сухой зубочистки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13433,'Для опары подогреть слегка молоко, положить пару-тройку ложек сахара, размешать, всыпать дрожжи и немного муки, размешать, оставить в теплом месте примерно на 2,5 часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13433,'Перебрать, промыть и просушить изюм.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13433,'Растопить сливочное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13433,'Смешать подсоленные желтки (белки оставить для помадки) и сахар, вылить в опару, размешать, всыпать муку, изюм и ванилин, вымесить хорошо тесто, убрать в тепло, дать в 2,5-3 раза увеличить объем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13433,'Подготовить формы, в каждую положить по кусочку теста, но занять не более половины объема, дать подойти примерно около часа, тесто должно приподняться над формой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13433,'Прогреть духовку, поместить формы, выпекать при 180 градусах.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13433,'Дать куличу с изюмом на сухих дрожжах в духовке остыть, покрыть помадкой, украсить верх цветной присыпкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13434,'Для активации дрожжей смешать их с парой ложек сахара и муки, перемешать хорошо с теплой водой, дать четверть часа постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13434,'Молоко слегка подогреть, масло растопить и дать остыть, изюм промыть и обсушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13434,'Всё перемешать с дрожжами и подсоленной мукой, вымесить тесто, подливая растительное масло, дать постоять в тепле, обмять и дать еще раз подняться.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13434,'Разложить порциями по формочкам, прикрыть тканью, дать подняться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13434,'Прогреть до 180 градусов духовку, поместить на противень формочки, выпекать кулич на сухих дрожжах без яиц и опары до готовности (проверка – «сухая спичка»), время зависит от величины формочек.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13435,'В широкую и достаточно глубокую миску разбить яйца, всыпать сахар, взбить, добавить муку, какао, разрыхлитель, влить растопленное масло, тщательно перемешать до образования однородного теста, дать чуть постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13435,'Колобок теста разрезать на две половины, раскатать, выпечь пару коржей. Один чуть толще, чтобы можно было разрезать после остывания на два. Вишневым ликером  пропитать коржи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13435,'Для прослойки взбить сахар и сливки, оставить часть сливок и несколько вишен для оформления верха торта «Черный лес». Смешать взбитые сливки с подготовленной вишней.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13435,'Щедро прослоить коржи кремом, украсить верх кремом, вишней и стружкой шоколада.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13436,'Чуть подогреть молоко, положить дрожжи, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13436,'В отдельной посуде растереть желтки и сахар, влить растопленное масло, смешать с молоком и дрожжами, подсолить, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13436,'Всыпать стакан муки, кардамон, цедру и ваниль, перемешать, дать подняться в тепле около четверти часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13436,'Сформовать шарики, подходящего размера, разложить их по формам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13436,'Выпекать кулич на сухих дрожжах с цукатами и изюмом при 180 градусах (прогреть заранее духовку) до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13437,'Поставить опару на молоке: подогреть его, положить дрожжи и 4 ст. л. сахара, перемешать, подсыпать муки, размешать, дать постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13437,'Хорошую сметану подсолить, перемешать с желтками и сахаром, все взбить, добавить прогретое и охлажденное масло, перемешать с опарой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13437,'Когда смесь станет однородной ввести цукаты (сухофрукты), всыпать остатки муки, вымешать до получения мягкого теста.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13437,'Дать ему дважды «созреть» и подняться (после первого раза обмять).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13437,'Подготовить высокие формы, положить в каждую по кусочку теста, прикрыть тканью, дать подняться.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13437,'Выпекать кулич на сухих дрожжах и сметане с сухофруктами до готовности, верх оформить помадкой с присыпкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13438,'Перемешать ванилин, корицу и цедру с мукой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13438,'Кефир слегка подогреть, залить дрожжи с сахаром, перемешать, ввести желтки (белки сделают тесто более жестким), тщательно перемешать, чтобы сахар растворился.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13438,'Растопить масло и вместе с растительным влить в тесто, добавить муки, хорошо вымесить, добавить изюм, дать постоять в тепле пару часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13438,'Когда тесто поднимется, опустить его, дать еще раз подняться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13438,'Разложить по формам, оставить на треть часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13438,'Поставить кулич в духовку (прогретую до 200 градусов).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13438,'Выпекать до готовности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13439,'Приготовим опару для теста смешав подогретое молоко, соль, сахар и 1 ст.л. муки. Размешав до однородности и оставить на 20 минут подниматься.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13439,'Когда опара поднялась, добавить растительное масло и оставшуюся муку. Все тщательно перемешать, если муки мало, добавить еще, чтоб вышло тесто средней плотности, не тугое.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13439,'Оставить тесто в теплом месте подходить на 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13439,'Обмять тесто и оставить подниматься еще на 40 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13439,'Для начинки нарезаем лук и слегка пассируем на растительном масле.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13439,'Добавляем к луку нашинкованную капусту. Перемешав и налив немного воды оставляем тушиться под закрытой крышкой до полуготовности.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13439,'Через 10 минут солим и добавляем нарезанные вареные яйца. Перемешиваем и оставляем остывать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13439,'Дрожжевое тесто раскатав в пласт толщиной 5 мм укладываем в форму и формируем небольшие бортики.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13439,'Выкладываем на тесто начинку и поливаем заливкой из сметаны и молока.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13439,'Выпекать пирог в разогретой духовке до 200 ОС в течении 25 мин.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13439,'Готовый пирог немного остудить и посыпать нарезанной зеленью.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13440,'Вымыть и вытереть яйца, разделить на белки и желтки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13440,'Взять чистую и сухую посуду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13440,'Взбить в крепкую пену белки, постепенно добавляя пудру, а в конце влить сок лимона (для вкуса и плотности помадки) и капнуть ванильной эссенции (можно и без нее), взбивать еще пару-тройку секунд.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13440,'Использовать глазурь для пасхального кулича с лимонным соком сразу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13441,'Просеять сахарную пудру, чтобы не было комочков, по каплям добавить воду (молоко), хорошо растереть до однородной, тянущейся гладкой массы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13441,'Всыпать в конце ванилин, чуть перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13441,'Нанести помадку на куличи, присыпать чем-нибудь по вкусу, пока масса не затвердеет.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13441,'Засыхает глазурь для кулича из сахарной пудры и воды довольно быстро, через час точно, если в комнате тепло и сухо.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13442,'Протереть творог сквозь сито, соединить с взбитыми с сахаром желтками, перемешать, осторожно ввести вбитые в крутую пену белки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13442,'Распустить в 150 мл горячей воды желатин, размешать до однородного состояния, соединить с ранее приготовленной массой, перемешать полученный крем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13442,'Положить в подходящую по диаметру форму бисквитный корж, смазать частью крема, прикрыть другим коржом и промазать оставшимся кремом, убрать торт «Тирамису» из готовых бисквитных коржей на 3-4 часа в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13442,'После застывания достать, присыпать измельченным черным шоколадом и подать к столу. Приятного чаепития!',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13443,'Приготовить раствор желатина по рецепту на упаковке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13443,'Засыпать в кастрюльку сахар, влить четыре ложки воды, размешать, прогреть до получения сиропа, слегка остудить (минут 7).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13443,'Растворить в нем набухший желатин, взбить миксером в густую плотную пену.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13443,'Перед окончанием взбивания добавить сок отжатый из лимона, около минуты продолжить еще взбивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13443,'Нанести глазурь для кулича с желатином и лимонным соком на верхушку куличей.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13443,'Хранить ее нельзя, застывает минут за 10-15.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13444,'Шоколадку поломать на кусочки, расплавить на водяной бане.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13444,'Добавить кубики масла, размешать до полного смешивания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13444,'Кипения глазури для кулича из белого шоколада и масла нельзя допускать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13444,'Снять помадку с плиты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13444,'Украсить куличи, дать затвердеть примерно четверть часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13445,'Обсушить. Растолочь специи. Положить зелень. Добавить специи. Залить вином
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13445,'Закрыть фольгу. Запекать 20 мин. при температуре 180°С. Выложить на тарелку. Удалить зелень. Смазать маслом.','https://vkuso.ru/data/cache/data/d2/3a052a48cd12bd2_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13446,'Слегка взбить белки и сахар, прогреть на водяной бане, помешивая, чтобы сахар растворился, но белки не превратились в хлопья.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13446,'Снять с плиты, взбить заварную глазурь для кулича из белков и сахара миксером до получения густой пены белого цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13446,'Выжать в нее сок лимона, еще чуть взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13446,'Массу нанести на верх кулича.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13447,'Белки охладить, взбить, постепенно подсыпая пудру.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13447,'Когда смесь приобретет белый цвет, через ситечко добавить крахмал, чуть взбить и влить свежий сок лимона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13447,'Добавить по вкусу ваниль, хорошо перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13447,'Глазурь для кулича с крахмалом и ванилином готова, можно нанести уже на кулич.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13448,'Перемешать все ингредиенты для коржей, раскатать в два коржа, испечь при температуре чуть ниже 190 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13448,'Для крема взбить сливки, пару пакетиков ванилина с парой ст.л. сахара и сметаной. Промазать коржи торта со сметанно-ванильным кремом и сливочной глазурью приготовленным кремом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13448,'Для оформления приготовить из жирных сливок, сахарной пудры и какао-порошка глазурь, облить торт, убрать для застывания верха и начинки на несколько часов в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13449,'Молоко чуть-чуть подогреть, всыпать сахар и дрожжи, перемешать, до полного растворения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13449,'Добавить размягченное масло и слегка взбитые желтки с яйцами, размешать, прикрыть тканью, оставить в тепле примерно на 12 часов (ночь).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13449,'Тщательно промыть изюм, распарить его в тёплой воде, отжать, перемешать с мукой для лучшего распределения в тесте.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13449,'Массу подсолить, положить ванилин, добавить остатки муки, хорошо вымешать, дать подняться в тепле.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13449,'Подготовить формочки, заполнить их тестом на 1/3, дать подняться до верха, поместить в духовку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13449,'Выпекать александрийское тесто на молоке для куличей начинать при 200 градусах, через 10 минут снизить температуру до 170, выпекать до готовности и появления румяной корочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13450,'Положить в молоко кусочки масла, чуть подогреть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13450,'Положить дрожжи и яйца с сахаром, хорошо взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13450,'Влить коньяк, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13450,'Дать час постоять до появления приятного аромата.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13450,'Всыпать муку с изюмом, посолить, положить ванилин, замесить тесто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13450,'Оставить на 4 часа для «созревания».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13450,'Тесто разложить по стаканчикам, дать хорошо подняться.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13450,'Выпекать александрийское тесто для куличей с коньяком в прогретой духовке.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13451,'Растереть часть сахара с желтками, всыпать оставшийся сахар, влить сливки, перемешать до полного растворения.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13451,'Положить сырые дрожжи, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13451,'Положить мягкое масло, ещё раз перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13451,'Прикрыть льняным полотенцем, дать постоять ночь в тепле.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13451,'Запарить изюм, руками отжать от воды, перемешать его со стаканом муки, можно добавить еще цукатов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13451,'В сливочную массу положить соль, изюм, остатки муки (обязательно просеять), замесить александрийское тесто для куличей на сливках.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13451,'Дать ему подняться и приступить к выпеканию куличей.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13452,'Желтки и весь сахар растереть, влить сметану, добавить теплое молоко с сырыми дрожжами, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13452,'Оставить в теплом месте на 8 часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13452,'Перемешать соль с растопленным маслом, положить в смесь, добавить изюм и коньяк.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13452,'Всыпать порциями муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13452,'Вымесить александрийское тесто для куличей на сметане.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13452,'Подождать пока поднимется, приступить к выпечке.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13453,'Сделать надрез вдоль каждого филе, чтобы получились тонкие пластинки, чуть отбить, присыпать перцем с солью, смазать тертым чесноком со специями, оставить в покое на полчаса. Включить для прогрева до 200 градусов духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13453,'Сыр и помидоры порезать брусочками, соответствующими ширине кусочков мяса. Уложить на филе кусочек сыра и помидора, свернуть в трубочку, обернуть плотно парой кусочков бекона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13453,'Сложить рулетики из куриной грудки с помидорами, беконом и сыром «Фета» в форму и поставить на полчаса в прогретую духовку, подавать в горячем виде с любым соусом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13454,'Масло порезать на мелкие кусочки, чтобы быстрее стало мягким.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13454,'Молоко подогреть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13454,'В яйца всыпать сахар и взбить миксером (около 30 секунд).',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13454,'Перемешать подогретое молоко яйца, дрожжи, добавить масло, всыпать апельсиново-лимонную цедру, дать болтушке постоять около 8 часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13454,'Болтушку посолить, положить изюм, ваниль, цукаты, всыпать порциями муку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13454,'Вымесить александрийское тесто для куличей с цедрой и цукатами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13454,'Дать ему подняться, сформовать изделия и выпечь.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13455,'Всыпать в кипящее молоко полтора стакана муки предварительно ее просеять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13455,'Хорошо перемешать, убрать с плиты, дать заварной части остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13455,'Всыпать немного сахара, добавить половину дрожжей, перемешать, дать постоять опаре около часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13455,'Желтки и сахар взбить, добавить мягкое масло, разведенные в ¼ стакана воды остатки дрожжей, посолить, перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13455,'Белки отдельно взбить, но не очень круто.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13455,'Объединить заварную и основную части опары, хорошо перемешать, влить коньяк, добавить ваниль, взбитые белки и остаток муки, изюм, вымесить тесто.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13455,'Дать ему подойти в тепле и увеличиться в 3 раза.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13455,'Скатать небольшие шарики, разложить их по формам, дать постоять и подняться.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13455,'Заварной кулич на молоке с коньяком выпекать при 180 градусах до готовности, проверять зубочисткой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13456,'Развести дрожжи в сладком молоке, взять половину.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13456,'Всыпать чуть муки, размешать, дать постоять примерно час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13456,'Остатки молока со щепоткой сахара нагреть до кипения.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13456,'Всыпать 2/3 стакана муки, хорошо перемешать, дать остыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13456,'Добавить остаток дрожжей, дать 10 минут постоять.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13456,'Обе пары объединить, влить растопленное масло с желтками и сахаром, посолить, всыпать изюм, перемешать (можно воспользоваться миксером) до получения однородной массы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13456,'Тесту дать созреть в тепле и увеличиться втрое.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13456,'Скатать средние шарики, заполнить формы, прикрыть их тканью, дать подняться.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13456,'Выпекать быстрый заварной кулич на сухих дрожжах в духовке при температуре 190 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13456,'Дать остыть, оформить верх любой глазурью.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13457,'В муку положить соль и разрыхлитель, просеять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13457,'Отдельно взбить половину стакана сахара и масло до небольшой воздушности (приблизительно 2 минуты).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13457,'Положить яйца и взбивать до однородности.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13457,'Далее в эту емкость всыпать сухие компоненты и вымесить тесто, ему надлежит выйти влажным, немного липнущим к рукам.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13457,'Положить в холодильник приблизительно на 1 час.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13457,'Разогреть духовку (200 градусов).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13457,'В небольшой емкости перемешать корицу и остатки сахара.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13457,'Вынуть тесто из холодильника, сделать из него маленькие шарики (в диаметре 3-4 сантиметра), обкатать их в смеси корицы с сахаром.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13457,'Переложить на противень, застеленный бумагой, немного приплющить и поставить в духовку на 10 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13457,'Необходимо обязательно за печеньем наблюдать – когда чуть-чуть расползется и потрескается, можно вынимать, очень важно не пересушить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13458,'Натереть сыр на терке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13458,'Измельчить зелень.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13676,'Добавить немного растительного масла.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13458,'Творог (1-5%) перемешать с яйцами и добавить в эту смесь сыр, измельченный чеснок и зелень, смешать',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13458,'Из получившейся смеси сформировать палочки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13458,'Тщательно обкатать в панировочных сухарях и поджарить с двух боков на раскаленной сковороде до коричневого оттенка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13459,'Кабачки промыть и натереть на терке, лучше крупной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13459,'Затем их немного отжать, поперчить, посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13459,'Сюда же положить яйца, муку, смешать, тесто должно выйти, как на блины.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13459,'Жарить коржи лучше на не очень большой сковородке, тогда они не будут рваться.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13459,'Выкладывать тесто на сковороду ложкой и разравнивать по всей поверхности, поджарить одну сторону, перевернуть и поджарить вторую.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13459,'Из данного количества теста может получиться 3 коржа, количество ингредиентов можно увеличить и испечь от 4 до 6 коржей.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13459,'Далее их необходимо охладить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13459,'Начинка: измельчить чеснок, нашинковать зелень, смешать в емкости чеснок, майонез и зелень до однородности.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13459,'Разрезать помидоры кружочками, если помидоры очень крупные, то сначала их нужно разрезать на части, а потом измельчить тоненькими пластинками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13459,'Взять один корж, намазать его смесью из майонеза.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13459,'Уложить пластины помидоров.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13459,'Прикрыть следующим коржом.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13459,'Промазать и уложить начинку, подобно первому.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13459,'Прикрыть оставшимся коржом, смазать смесью майонеза.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13459,'Украсить помидором и присыпать тертым сыром.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13460,'Небольшие луковицы разрезать пополам, а потом каждую порезать полукольцами и залить майонезом. Нарезать картофель и тоже залить майонезом, с ',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13460,'Выложить на противень слой картошки, прикрыть луком, завершить слоем курятины.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13460,'Задвинуть противень с курицей, картошкой и луком в духовку с температурой 220 градусов примерно минут на 40, присыпать сыром и зеленью, дать сыру чуть расплавиться и сразу подать приготовленную ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13461,'Нарезать небольшими ломтиками куриную грудку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13461,'Выложить на плоскую тарелку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13461,'Маринованные шампиньоны также нарезать ломтиками и выложить поверх мяса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13461,'Оба слоя щедро намазать майонезом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13461,'Раскрошить плавленый сыр и распределить равномерно по всей поверхности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13461,'Наломать небольшими кубиками сухарики и присыпать ими салат.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13461,'Жареный подсоленный арахис потолочь в ступке, чтобы вышла крупная крошка.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13461,'Присыпать салат сверху.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13461,'Украсить блюдо зеленью и можно подавать на стол.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13462,'Натереть морковь на средней терке (можно пропустить через комбайн).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13462,'Нарезать перец соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13462,'Лук и помидоры порезать небольшими кубиками, измельчить зелень, смешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13462,'Переложить смесь в полиэтиленовые пакеты и скрутить колбаской (в таком виде удобно использовать).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13462,'Добавлять заправку в блюдо нужно тогда, когда оно уже приготовилось, перемешать дать закипеть или протушить буквально 2 минуты и можно убирать с плиты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13463,'Грибы промыть, просушить с помощью бумажного полотенца, отломать ножки (они использоваться не будут), порезать их соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13463,'Порезать маленькими кубиками лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13463,'Натереть на терке сыр.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13463,'Обжарить лук на сковородке на топленом масле.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13463,'Долить оливковое или подсолнечное масло, потом добавить грибы, обжарить, добавить муку, смешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13463,'Прожарить еще пару минут, добавить сметану, если получается соус сильно густым, то можно прибавить чуть-чуть молока или сметаны, консистенция должна быть, как жидкая сметана.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13463,'Переложить соус в кокотницы, присыпать сыром и поставить в духовку (250 градусов) на 5 минут, пока не зарумянится.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13464,'Натереть на мелкой терке капусту (кочан должен быть очень плотным), смешать ее с прокрученным луком и мясом, сдобрить солью и черным перцем, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13464,'Скатать из полученного фарша плотные шарики, а потом придать форму небольших котлеток, обжарить в разогретом масле с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13464,'Разбавить немного водой томатную пасту и сметану, переложить ленивые голубцы без яиц и риса в форму, залить приготовленной смесью, положить несколько лавровых листиков и горошин черного перца.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13464,'Форму установить на час в духовой шкаф, готовое блюдо подать с рисом или картофельным пюре.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13465,'Грудку разделать, нарезать маленькими кусочками, обжарить, добавить приправы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13465,'Свежие овощи порезать и заправить майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13465,'На лаваш уложить курицу, смазать кетчупом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13465,'Выложить сверху пару ложек овощного салата, свернуть конвертиком.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13466,'Налить в сотейник с толстым дном воду, дать ей закипеть, подсолить, положить масло и сахар, размешать. Добавить, перемешивая по частям муку, проварить еще пару минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13466,'Снять с плиты, дать слегка остыть, вмешать по одному все яйца, переложить готовое тесто в кондитерский шприц. Побрызгать противень холодной водой, выдавить небольшими порциями тесто с достаточно большими промежутками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13466,'Выпекать основу для заварных пирожных около 45 минут до золотистого цвета и увеличения в несколько раз объема, дверцу во время выпечки открывать нельзя, иначе пирожное не поднимется.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13466,'Дать основе остыть и заполнить сгущенным молоком взбитым со сливочным маслом, используя шприц, или аккуратно срезав верхушку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13467,'С курицы снять кожу, поместить в емкость и налить холодную воду так, чтобы она приблизительно на 5 сантиметров курицу покрывала, поставить на большой огонь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13467,'Как закипит, собрать пену, убавить пламя и варить на маленьком огне приблизительно 4 часа, время от времени необходимо убирать пену и жир.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13467,'Нужно, чтобы осталось воды вполовину меньше, а мясо легко отходило от костей.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13467,'Затем добавить в бульон почищенную морковь, лук и чеснок, проварить снова 30 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13467,'Посолить, поперчить, добавить перец горошек и лавровый лист, варить опять 30 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13467,'Яйца сварить вкрутую, морковь почистить для украшения (можно немного сварить в бульоне, на любителя), нарезать ее разнообразными формами.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13467,'Очистить чеснок и нарезать пластинками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13467,'Достать из бульона вареный лук, морковь и чеснок – они больше не понадобятся.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13467,'Бульон процедить, охладить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13467,'Отделить мясо от костей (кости выбросить), нарезать небольшими кусочками и переложить в тарелку.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13467,'Яйца нарезать вдоль и уложить на мясо, дальше выложить морковь, чеснок, приукрасить зеленью (кинза или петрушка).',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13467,'Тщательно залить все бульоном и отправить в холодильник для застывания.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13468,'Вскрыть консервы, слить сок, удалить крупные косточки, размять вилкой, лук порубить мелкими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13468,'Яйца, сваренные вкрутую и хорошо охлажденные, разрезать, вынуть желтки, размять вилкой, белки измельчить на терке с маленькими отверстиями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13468,'Удалить у яблок кожуру и семечки, измельчить на терке с крупными отверстиями,',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13468,'побрызгать соком лимона для сохранения первоначального цвета.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13468,'Выложить на плоское блюдо слоями: консервы, чуть перченый лук, подсоленные желтки, промазать майонезом. Далее уложить слой яблок, тертого сыра, смазать майонезом, положить кукурузу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13468,'Смешать майонез и тертые белки, подсолить, перемешать, оформить этой массой верх и бока салата.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13468,'Для украшения салата порезать семгу слабого посола на тонкие ломтики, а их в свою очередь на узкие полосы, выложить из них на поверхности салата ромбы, а по центру – розочки, дополнить украшение можно половинками перепелиных яиц и бордюром из творожного сыра, выдавленного из кондитерского мешка и зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13468,'Осторожно прикрыть салат пленкой, дать постоять часов 10-12.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13469,'Нарезать лук на кубики, кабачок очистить и порезать соломкой, обжарить с добавлением мелко порезанного чеснока, зелени и майонеза (добавлять в самом конце).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13469,'Подготовить и порезать мясо, чуть отбить, переложить на противень, промазанный маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13469,'Прикрыть слоем овощей мясо, а на них выложить кружки помидоров, присыпать ',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13470,'Можно использовать свиную шейку и говядину, пропустить мясо два раза через мелкую мясорубку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13470,'Потом прибавить соду, крахмал, перец черный молотый, соль, чеснок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13470,'Замешивать фарш, частями вливать молоко, хорошо его отбить, прикрыть пленкой и отправить в холодильник на 2 часа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13470,'Вынуть фарш.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13470,'Из мясорубки вынуть сеточку и нож, поставить насадку для колбасок, руки смазать растительным маслом, формировать с помощью мясорубки и рук мититеи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13470,'Поджарить с каждой стороны их на подсолнечном масле до золотистого оттенка и уложить в кастрюлю с толстым дном (можно казан).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13470,'Нарезать кольцами лук, выложить на колбаски, положить перец-горошек и лавровый лист, залить все кипяченой водой (солить ее по собственному вкусу), прикрыть крышкой, дать закипеть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13470,'Потом огонь убавить и тушить до готовности (около 30 минут).',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13471,'Нарезать мясо небольшими кусочками, обжарить до золотистости на подсолнечном масле.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13471,'Положить лук, измельченный полукольцами, смешать и жарить еще 3 минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13471,'Потом положить перец (соломкой), шампиньоны (если крупные, то резать на четвертинки, а если мелкими, то ложить целиком), морковь (натереть), томатную пасту и тушить еще 5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13471,'Далее налить воду (300 миллилитров) и тушить дальше на небольшом огне полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13471,'Несколько раз в процессе тушения перемешивать и по необходимости доливать воды.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13472,'Разрезать помидоры пополам.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13472,'Нарезать пластинками сыр.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13472,'Все ингредиенты нанизать на шпажки, чередуя их.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13472,'Заправка: перемешать оливковое масло, уксус, взбить с помощью вилки до консистенции эмульсии, а можно налить в небольшую баночку с крышкой и хорошо потрясти, а также можно взбивать венчиком до той же консистенции.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13472,'Положить в заправку перец и соль.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13472,'Выложить капрезе в посуду, добавить базилик, руколу и полить заправкой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13473,'Просеять муку (можно пару раз), разделить белки и желтки, переложить белки в крупную емкость, а желтки положить отдельно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13473,'Взбивать белки, понемногу добавлять сахар и ванилин, взбивать до тех пор, пока не закончится сахар, должна выйти сравнительно густая консистенция белого оттенка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13473,'Прибавлять желтки по одному и продолжить взбивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13473,'Далее всыпать муку и осторожно перемешивать ложкой снизу-вверх.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13473,'Перелить тесто в форму и отправить в нагретую духовку (190-200 градусов) на 25 минут, открывать дверцу все это время нельзя.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13473,'Духовку выключить и оставить бисквит там буквально на 5 минут (не заглядывать!).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13473,'Творог тщательно размять вилкой, положить сметану (150 грамм + 3-4 столовых ложек), половину банана, взбить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13473,'Порезать бананы кружочками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13473,'Разрезать бисквит на 3 коржа, можно каждый немного смазать вареньем, но можно и без него, по желанию.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13473,'Далее на корж выложить начинку из творога, распределить кусочки бананов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13474,'Взбить добела сливочное масло и сахар.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13474,'Отдельно слегка взбить яйца вилкой, добавить ваниль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13474,'В несколько приемов добавить к маслу, продолжать взбивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13474,'Все сухие ингредиенты смешать, просеять.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13474,'В три приема прибавить данную сухую смесь в масляную, аккуратно смешивать лопаткой снизу-вверх.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13474,'Поделить тесто пополам, одну часть отставить, а вторую часть снова поделить пополам (одна больше, а вторая меньше).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13474,'В ту часть, что больше всыпать какао (2 столовые ложки), в меньшую также добавить какао (1/4 столовой ложки) и муку (половину столовой ложки).',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13474,'Форму смазать маслом, притрусить мукой и выстелить бумагой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13491,'Обжариваем сначала лук и чеснок, а затем добавляем морковь. Обжариваем до золотистости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13474,'Каждую цветную часть теста переложить в пакет, нарисовать на дне формы тестом белого цвета 3 круга на некоторой дистанции.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13474,'Незаполненные промежутки наполнить темным тестом.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13474,'Поверх него нарисовать полоски из пакетика со светло-коричневым тестом.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13474,'Опять взять пакет с темным тестом и нарисовать полоски поверх светло-коричневого так, чтобы данное тесто целиком закрыло то, что светлее.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13474,'Потом нужно темное тесто прикрыть белым, сначала заполнить по краям, а потом наверху – так тесто не будет растекаться.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13474,'Опять нарисовать круги темным тестом, но только там, где раньше были круги из светлого, затем светло-коричневое и снова темное, прикрыть все промежутки и верх белым тестом.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13474,'В том случае, если осталось темное тесто, то необходимо нарисовать им пятна на поверхности.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13474,'Отправить в духовку на 40 минут (180 градусов).',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13475,'Ломти батона смазать тонким слоем масла, установить их вертикально в смазанную форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13475,'Помидоры и ветчину нарезать кружочками, уложить их между кусочками батона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13475,'Яйца взбить с молоком, поперчить, посолить, прибавить мускатный орех.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13475,'Залить яичной смесью батон, помидоры и колбасу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13475,'Присыпать тертым сыром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13475,'Печь в нагретой духовке, пока сыр не зарумянится.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13476,'Взять небольшую кастрюльку, смешать в ней молоко, разрезанный стручок ванили и немного сахара, поставить на небольшой огонь.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13476,'В отдельной емкости взбить яйца с добавлением сахара, добавить муку, кукурузный крахмал, взбить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13476,'Когда молоко практически начало кипеть, достать стручок ванили, извлечь семена и положить их обратно.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13476,'Небольшими порциями добавлять молоко в яичную смесь, тщательно взбивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13476,'Вылить смесь назад в кастрюлю, поставить на огонь и взбивать, пока не загустеет (около 1 минуты).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13476,'Убрать с огня, охладить, поставить в холодильник, чтобы остыл полностью.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13476,'Для блинов смешать молоко, воду, сахар, яйца и муку, пожарить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13476,'Выкладывать на блинчики крем, далее уложить нарезанную клубнику.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13477,'Репчатый лук и сладкий болгарский перец нарезать небольшими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13477,'Морковь потереть или нарезать брусками при помощи слайсера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13477,'Рис хорошо промыть в нескольких водах, замочить в подогретой воде для набухания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13477,'Выставить режим «Жарка» или «Выпечка», прогреть в чаше растительное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13477,'Насыпать лук, жарить под крышкой пять или семь минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13477,'Добавить тертую морковь, прогревать еще столько же.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13477,'Последний ингредиент – перец, все перемешать, тушить десять минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13477,'Овощи разровнять и выложить рис, аккуратно влить воду, чтобы слои не перемешались.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13477,'Соль и специи – по вкусу.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13477,'Установить режим «Крупа», «Рис» или «Гречка».',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13478,'Тыкву очистить и нарезать кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13478,'Яблоки также очистить и нарезать дольками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13478,'Промыть рис.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13478,'Изюм промыть и запарить на две минуты в кипятке.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13478,'Все ингредиенты переложить в чашу мультиварки, залить водой, посолить, добавить сахарный песок, сливочное масло.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13478,'Выставить режим «Плов».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13479,'Пропаренный рис залить водой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13479,'Нарезать кубиками сладкий болгарский перец, репчатый лук, морковь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13479,'Налить в чашу растительное масло, обжарить лук в режиме «Выпечка» до прозрачного цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13479,'Всыпать перец и морковь, тушить десять минут под крышкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13479,'Добавить заранее промытый рис, куркуму, паприку, соль.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13479,'Перемешать, влить воду, выставить режим «Рис», «Плов» или «Крупа».',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13480,'Промыть рис, последняя вода должна стать прозрачной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13480,'Нарезать кубиками репчатый лук, грибы и сладкий перец – полосками, морковь натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13509,'Дрожжи перемешать с сахаром, влить немного подогретого молока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13480,'Включить режим «Жарка» или «Выпечка», прогреть лук, затем остальные ингредиенты, тушить от десяти до пятнадцати минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13480,'Переложить в чашу рис, посолить, добавить специи по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13480,'Полить кашу томатным соком, водой, выставить режим «Плов».',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13481,'Морковь и лук нарезать брусками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13481,'Курагу или чернослив замочить в подогретой воде на десять минут, отжать, нарезать мелкими кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13481,'Куриное филе нарезать кубиками со стороной в два сантиметра.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13481,'Влить растительное масло на дно чаши, включить режим «Выпечка».',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13481,'Обжарить морковь и лук до мягкости.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13481,'Добавить мясо, соль, специи, тушить все вместе под крышкой десять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13481,'Добавить сухофрукты, высыпать ровным слоем рис.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13481,'В центр блюда положить целую головку чеснока.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13481,'Влить кипящую воду так, чтобы не нарушить слои, выставить режим «Крупа» или «Плов».',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13482,'Говядину хорошо промыть, промокнуть бумажными салфетками, освободить филе от прожилок и пленок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13482,'Нарезать продукт небольшими кусочками и выложить в горшочек для запекания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13482,'Промыть рис под проточной водой, выложить поверх мяса ровным слоем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13482,'Морковь и репчатый лук очистить и промыть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13482,'Лук нарезать тонкими полукольцами, морковь натереть.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13482,'Положить на сковороду кусочек сливочного масла, растопить, обжарить овощи до мягкости, помешивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13482,'Переложить обжарку поверх риса, залить подсоленной водой, положить еще один кусочек масла.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13482,'Поставить в духовой шкаф на час, температура приготовления – 180 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13482,'Горшочек вынуть, содержимое перемешать лопаткой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13483,'Курицу промыть, обсушить и отделить кости от мяса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13483,'Филе нарезать кусочками, остальное можно использовать для приготовления бульона.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13483,'Разогреть на сковороде растительное масло, переложить куриные кусочки, посыпать специями, жарить в течение десяти минут, помешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13483,'Очистить лук и морковь, лук нашинковать кольцами, а затем разрезать их на четвертинки, морковь измельчить в виде продолговатых брусочков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13483,'Добавить подготовленные овощи к курице, тушить все вместе 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13483,'Разложить массу в горшочки, добавить в каждый хорошо промытый рис.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13483,'Поперчить по вкусу, залить водой так, чтобы она покрывала продукты на два сантиметра.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13483,'Время запекания – 40 минут, температура – 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13483,'Горшочки вынуть, плов перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13484,'Натереть сыр и морковь. Добавить сырые яйца, сметану, просеянную пшеничную муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13484,'Выпечь оладьи на растительном масле, обжаривать с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13485,'Очистить 1 грушу и нарезать на мелкие кусочки. В сотейнике прогреть 1 ст.л. воды с тремя столовыми ложками сахара до золотистого цвета, в полученный сироп долить еще пять столовых ложек горячей воды. Всыпать грушу и проварить до мягкости. При готовности взбить блендером в однородную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13485,'Яичные желтки взбить миксером, добавить 3 столовых ложки грушевого сиропа. Белки взбить в пену и влить оставшийся сироп, продолжать взбивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13485,'В отдельной посуде смешать по трети от взбитых белков и желтков, добавить картофельный крахмал приблизительно 1 ст.л., соду, лимонную кислоту, перемешать. Массу выложить в застеленную пергаментом форму, печь в течение 12 минут при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13485,'В оставшиеся взбитые желтки добавить одну чайную ложку крахмала. Молоко разогреть в сотейнике, до кипения не доводить. Перелить немного молока во взбитые желтки, перемешать. Массу перелить в молоко и варить крем на среднем огне, постоянно помешивая, чтобы яйца не свернулись.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13485,'Загустевший крем с появившимися пузырьками снять с огня. Смешать столовую ложку желатина в пяти ложках воды, дать набухнуть и добавить в крем. Перемешать и охладить, добавить йогурт, остатки взбитых белков, перемешать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13485,'Корж выложить на дно формы, вылить сверху крем и поставить в холодильник.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13485,'Три груши очистить от кожицы и разрезать пополам. Сварить в сотейнике сироп из 3 ст.л. сахара и 1 ст.л. воды, прогревать до золотистого цвета, добавить еще немного горячей воды. Положить половинки груш и варить 10 минут под крышкой. Через пять минут, после начала прогревания, плоды перевернуть. Вынуть из сиропа, остудить. Жидкость уварить, добавить 1 ч.л. желатина.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13485,'Груши разрезать на тонкие пластинки и выложить на торт. Полить сиропом с желатином, снова убрать в холодильник.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13486,'Филе свинины промыть, обсушить, нарезать брусками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13486,'Разогреть масло на сковороде, обжарить мясо до легкого румянца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13486,'Морковь очистить и нарезать тонкими брусками, лук нашинковать четвертинками колец.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13486,'Овощи пересыпать к мясу, прогревать семь минут, помешивать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13486,'Готовые продукты переложить в горшочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13486,'Промыть рис, выложить поверх свинины с овощами, залить водой так, чтобы ее уровень был выше крупы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13486,'Приправить специями для плова, посолить.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13486,'Перемешать содержимое, поставить горшочки в духовой шкаф, тушить при температуре 180 градусов, крупа должна впитать в себя всю влагу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13487,'Смешать тахини с йогуртом без вкусовых и цветовых добавок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13487,'Добавить измельченный чеснок, лимонный сок, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13487,'Всыпать рубленую зелень петрушки, мелко нарезанный зеленый перец чили, соль, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13487,'Соус подать к рыбе.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13488,'Сушеные грибы вымыть, залить водой и оставить на четыре часа.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13488,'Проварить продукт до мягкости в этой же воде в течение двух часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13488,'Откинуть на сито, бульон процедить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13488,'Грибы нарезать ломтиками небольшого размера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13488,'Если для приготовления блюда берутся свежие грибы – их можно просто промыть и нарезать.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13488,'Рис перебрать, промыть и обсушить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13488,'Репчатый лук очистить и нарезать четвертинками колец, обжарить на растительном масле до прозрачности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13488,'Добавить рис, все вместе обжаривать до тех пор, пока крупа не станет золотистой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13488,'Выложить массу в горшочки, добавить грибы, ингредиенты перемешать, залить грибным бульоном, посолить и поперчить, приправить томатным пюре.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13488,'Поставить горшочки в духовой шкаф, готовить плов при температуре 180 градусов под крышками.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13489,'Морковь и болгарский перец вымыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13489,'Брокколи разобрать на мелкие соцветия, морковь и лук нарезать мелкими кубиками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13489,'Перец очистить от семян, нарезать мякоть кусочками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13489,'Вымыть кабачки цуккини, обсушить, порезать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13489,'Срезать острым ножом кукурузу с початка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13489,'Все овощи выложить в глубокую емкость и перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13489,'Промыть рисовую крупу, переложить в овощную смесь, поперчить и перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13489,'Горшочки для запекания смазать изнутри растительным маслом, выложить смесь, залить подогретой и подсоленной водой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13489,'Накрыть крышками, поставить в духовку на 20 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13490,'Филе нарезать крупными кусками, посыпать смесью разных молотых перцев, солью, оставить на полчаса для пропитывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13490,'Разрезать помидоры черри на четыре части каждую, лук – полукольцами, сельдерей тонко нашинковать поперек.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13490,'Отварить картофель в «мундире» до полуготовности. Остудить, очистить и нарезать круглыми ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13490,'Смешать картофель, размятый розмарин, соль, оливковое масло. Добавить помидоры, лук, сельдерей, овощи перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13490,'Выложить смесь на противень, куски рыбы – сверху. Можно еще поперчить, посыпать специями для рыбных блюд. Печь в течение получаса при температуре 180 градусов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13491,'Отвариваем фасоль до готовности (рекомендую предварительно замочить фасоль на ночь в холодной воде). За 10-15 минут до готовности фасоль нужно посолить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13491,'Измельчаем чеснок и лук. Натираем морковь на терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13509,'Оставшееся молоко посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13491,'Добавляем к отваренной фасоли обжаренные овощи, все специи (при желании вы можете добавить специи, которые нравятся вам), и измельчаем все блендером. Доводим до нужной консистенции с помощью отвара от фасоли.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13492,'Шафран насыпать в небольшую емкость, влить немного воды и оставить на десять минут',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13492,'Филе красной рыбы промыть под проточной водой, обсушить, вынуть мелкие кости.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13492,'Кожу снять, филе полить лимонным соком, посолить, оставить для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13492,'Промыть рис до прозрачности воды, залить продукт новой порцией жидкости, поставить на огонь и посолить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13492,'Довести до кипения, влить шафран и варить десять минут, до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13492,'Репчатый лук очистить, порезать и обжарить на растительном масле.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13492,'Желтый и красный болгарский перец очистить от семенных камер, мякоть нарезать кубиками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13492,'Овощи переложить в рис, перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13492,'Смазать горшочки для запекания изнутри сливочным маслом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13492,'Разложить рисово-овощную массу, сверху – рыба.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13492,'Вымыть помидоры, облить кипятком и снять кожицу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13492,'Мякоть нарезать кубиками, переложит в горшочки, посолить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13492,'Сверху – еще один слой риса с овощами.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13492,'Влить сухое белое вино, поставить горшочки в духовку на 40 минут. Температура приготовления – 200 градусов.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13493,'Разрезать три кабачка средних размеров вдоль на две половинки, вынуть мякоть с семенами. Смешать для начинки сырой мясной фарш.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13493,'Добавить мелко нашинкованную белокочанную капусту, много рубленой зелени (укроп, петрушка), наполовину отваренный рис. Посолить, поперчить по вкусу и начинить «лодочки» из кабачка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13493,'Форму для запекания смазать растительным маслом, выложить кабачки с начинкой. Отдельно приготовить соус: смешать в равных пропорциях сметану и томатный сок, посолить и добавить сахар, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13493,'Смесью залить фаршированные кабачки. Печь в духовке около часа. Незадолго до готовности оригинальные лодочки из кабачков с мясной начинкой посыпать тертым твердым сыром и допечь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13494,'Прогреть на сковороде растительное или сливочное масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13494,'Промыть куриные голени, обсушить при помощи салфетки, обжарить с двух сторон до получения корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13494,'Горшочки смазать изнутри маслом, переложить голени, по штуке на горшочек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13494,'Добавить нарезанную тонкими кружочками морковь, лук – полукольцами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13494,'Следующий слой – нарезанные кубиками клубни картофеля.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13494,'Посолить, добавить перец-горошек, лавровый лист, приправу для курицы или сушеную зелень.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13494,'Влить воду на две трети объема горшочка.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13494,'Готовить под крышкой в течение 40 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13495,'Репчатый лук нарезать кубиками, выложить в горшочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13495,'Мясо промыть, нарезать, уложить поверх лукового слоя.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13495,'По желанию мясные кусочки можно предварительно обжарить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13495,'Добавить мякоть тыквы, нарезанную кубиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13495,'Все продукты не должны занять более двух третей объема горшочка.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13495,'В бульон или обычную воду добавить соль и перец, мелко нарезанный чеснок, перемешать и разлить жидкость в горшочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13495,'Уровень должен быть ниже плечиков, но покрывать продукты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13495,'Если для приготовления используется курица, то суп будет готов через 40 минут при температуре 190 градусов. Для мяса время увеличить до часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13496,'Нарезать шампиньоны кусочками, обжарить на масле, переложить в горшочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13496,'Нарезать лук и обжарить на этой же сковороде, добавить к грибам.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13496,'Нарезать морковь и также переложить в горшочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13496,'Следующий слой – ломтики свежего картофеля.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13496,'Приправить суп перцем-горошком и лавровым листом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13496,'Залить бульоном или подсоленной водой, время приготовления – пятьдесят минут, температура – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13509,'Влить дрожжи в подсоленное молоко, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13496,'Горшочки вынуть, положить в суп сметану, рубленую зелень укропа, дать постоять десять минут под крышкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13497,'Порубить молодой чеснок и положить в казан для обжаривания на растительном масле. Добавить полукольца репчатого лука. При готовности лука, он должен стать прозрачным, добавить морковь, порезанную соломкой или произвольно, тушить все вместе несколько минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13497,'Порезать кубиками кабачок, очищенный от кожицы и семян, добавить к остальным овощам, тушить еще пять минут. Порезать и добавить помидоры. Следующий ингредиент – кусочки мяса, лучше использовать нежирную свинину.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13497,'Тушить блюдо под крышкой на тихом огне около часа. Затем положить молодой картофель, очистить, но не резать, должны быть целые некрупные клубни примерно одного размера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13497,'Можно долить кипяток, если жидкость уже вся выпарилась. Соль, перец – по вкусу. Тушить свинину с овощами и молодым картофелем под крышкой до мягкости картофеля.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13498,'Очистить и нарезать репчатый лук, обжарить на сковороде с маслом в течение минуты.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13498,'Потереть морковь, обжарить еще одну минуту.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13498,'Грибы шампиньоны промыть, очистить, нарезать кубиками, также отправить на сковороду, прогреть пять минут вместе с овощами, разложить в горшочки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13498,'Кабачок нарезать кубиками, выложить поверх обжарки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13498,'В бульон добавить сметану, посолить и поперчить по вкусу, добавить измельченный чеснок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13498,'Залить смесью кабачки с обжаркой, поставить готовиться на полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13498,'Подать с рубленой зеленью.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13499,'Смешать соль, перец, сахар, полученной смесью натереть филе, нарезанное на крупные куски. Примерно на сутки поставить в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13499,'Подать вкусную соленую форель, порезав на кусочки. Можно добавить немного соуса «жидкий дым», несколько капель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13500,'Говядину или свинину нарезать соломкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13500,'Обжарить на сковороде, помешивать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13500,'Мясо вынуть, спассеровать репчатый лук, масло можно добавить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13500,'Переложить в горшочки лук, затем мясо, нарезанную кубиками или соломкой морковь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13500,'Промыть рис, также разложить продукт в горшочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13500,'Добавить в готовый бульон специи, томат-пасту, перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13500,'Залить жидкостью продукты, поставить горшочки в духовой шкаф на 30 – 35 минут, температура приготовления – 180 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13500,'При подаче посыпать суп зеленью.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13501,'Приготовить смесь сахара и соли, натереть ею рыбу целиком. Порезать лимон тонкими кружочками, выложить их на марлю, сверху – рыбное филе.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13501,'Несколько долек лимона можно положить внутрь, в брюшко. Сверху – еще лимон, завернуть и убрать в темное место на 2 – 3 дня. Подать соленую форель с лимоном, порезав на кусочки и удалив лишние соль с сахаром.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13502,'Картофель нарезать кубиками, переложить в горшочек.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13502,'Нарезать болгарский сладкий перец и лук, переложить поверх мяса.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13502,'Морковь нашинковать тонкими кружками, также отправить в горшочек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13502,'Нашинковать краснокочанную капусту, можно взять обычную белокочанную, брокколи, цветную.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13502,'Пересыпать в горшок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13502,'Заранее приготовленный овощной бульон посолить, приправить специями, залить содержимое горшка.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13502,'Поставить в духовку, тушить до готовности в течение сорока минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13503,'Чечевицу промыть, переложить в кипяток и варить в течение пяти минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13503,'Жидкость слить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13503,'Разогреть на сковороде масло, обжарить бекон, нарезанный кубиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13503,'Добавить рубленый лук, все вместе жарить две минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13503,'Добавить нашинкованную морковь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13503,'Следующий ингредиент – маринованный помидоры без кожицы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13503,'Потушить смесь в течение нескольких минут, жидкость должна выпариться, а масса загустеть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13503,'Добавить чечевицу, тушить еще пять минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13503,'Переложить смесь в горшки на половину объема.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13509,'Муку всыпать постепенно, перемешивать ложкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13503,'Бульон или кипяченую воду посолить и поперчить, добавить чеснок, любимые специи, перемешать, залить содержимое горшочков по плечики.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13503,'Поставить в духовой шкаф на 35 минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13503,'Хлеб нарезать кубиками, сбрызнуть оливковым маслом, выложить на противень и подсушить в духовке.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13503,'Подать суп к столу со свежими гренками.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13504,'Мясо нарезать соломкой, обжарить на сковороде без крышки до корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13504,'Мясо вынуть, добавить масло и обжарить нарезанный репчатый лук.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13504,'Следующий ингредиент для обжарки – тертые соленые огурцы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13504,'В последнюю очередь положить измельченные помидоры, тушить две минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13504,'Болгарский перец нарезать мелкими кубиками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13504,'В горшочки разложить обжаренное мясо, затем овощную смесь и болгарский перец.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13504,'Влить воду или бульон, приправить специями.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13504,'Поставить в духовой шкаф на полчаса.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13505,'Перемешать сметану с содой и оставить на несколько минут. Добавить сырые яйца, сахар, взбить. Следующие ингредиенты: мягкое сливочное масло, ванилин из пакетика, снова взбить. Добавить мак и просеянную муку. Выпечь корж в форме при 180 градусах в течение 40 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13505,'Приготовить крем: растереть яйцо, сахар, муку, взбивать венчиком. Влить стакан охлажденного молока, перемешать, варить на тихом огне, постоянно помешивать. Массу остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13505,'Взбить мягкое сливочное масло, добавлять крем небольшими порциями, продолжая взбивать. Готовый бисквитный корж разрезать на два по горизонтали острым ножом. Нижнюю половину можно пропитать сахарным или ягодным сиропом, смазать заварным кремом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13505,'Второй корж порезать кубиками, смешать с остальной частью крема, выложить массу на корж, в произвольном порядке. Полить маковый торт «Смак» растопленным шоколадом, темным или белым, или глазурью. Дать постоять несколько часов для пропитывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13506,'Отделить белки от желтков, белки взбить в течение нескольких секунд. Добавить растопленное сливочное масло, молотый миндальный орех, просеянную сахарную пудру, муку. Массу взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13506,'Налить в смазанные формочки для кексов, наполнять не до верха, примерно на две трети, в процессе выпекания тесто поднимется. В каждый кекс вдавите по две-три ягодки свежей малины, крупной и спелой. Печь нежные малиновые кексы полчаса при 180 градусах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13507,'Пшеничную муку просеять два раза.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13507,'Добавить соль, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13507,'Пересыпать на стол горкой, сделать углубление в центре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13507,'Отдельно взбить сырое яйцо до появления пузырьков.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13507,'Влить молоко и растительное масло, еще немного взбить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13507,'Перелить смесь в муку, вымесить массу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13507,'Тесто должно получиться эластичным, упругим.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13507,'Скатать шар, обернуть пищевой пленкой и оставить на 15 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13507,'Еще раз вымесить, тонко раскатать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13507,'Сформовать пиццу, выложить начинку, печь в духовом шкафу в течение получаса.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13508,'Прессованные дрожжи покрошить, растереть с сахаром, залить небольшим количеством теплой воды, всыпать муку, массу перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13508,'Оставить смесь на 15 или 20 минут при комнатной температуре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13508,'Должны появиться пузырьки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13508,'В небольшую емкость влить молоко, прогреть, до кипения не доводить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13508,'Растопить маргарин на водяной бане или в микроволновой печи.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13508,'Взбить яйца, добавить соль.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13508,'Смешать «заработавшие» дрожжи с теплым молоком, растопленным и остуженным маргарином и взбитыми яйцами.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13508,'В смесь добавить просеянную муку небольшими порциями, замесить тесто.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13508,'Сформовать шар, оставить под сухой тканью на час.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13508,'За это время массу два раза обмять.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13508,'Рабочую поверхность присыпать мукой, тесто раскатать в пласт толщиной от трех до четырех миллиметров.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13508,'Переложить на смазанный маслом противень, разложить начинку, печь пиццу в духовке в течение получаса.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13509,'Влить растительное масло, далее вымешивать массу руками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13509,'Накрыть тесто сухим полотенцем и оставить в тепле на 40 минут или на час.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13509,'Обмять, раскатать в пласт, выложить начинку, выпечь до готовности.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13510,'Скисшее молоко перелить в глубокую емкость, добавить пищевую соду, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13510,'Отдельно перемешать сырые куриные яйца с солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13510,'Смеси соединить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13510,'Всыпать просеянную муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13510,'Перемешивать активно, чтобы не образовались комочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13510,'Готовое тесто должно получиться полужидким.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13510,'Форму для выпекания смазать маслом, присыпать мукой или манной крупой, перелить тесто.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13510,'Разложить ингредиенты для начинки, печь в течение получаса.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13511,'Смешать морковь, приготовленную по-корейски, порезанные огурцы и помидоры, зеленый лук, рубленые укроп и петрушку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13511,'Порезать отварную говядину, натереть твердый сыр. Всё смешать, заправить салат «Цветик-семицветик» с морковью по-корейски майонезом и выложить в большую салатницу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13512,'Прокисшее молоко и сметана должны быть комнатной температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13512,'Добавить сахар и разрыхлитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13512,'Влить растительное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13512,'Ингредиенты хорошо перемешать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13512,'Отдельно взбить яйца с солью, всыпать муку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13512,'Замесить тесто: в мучную массу постепенно добавлять молочную смесь.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13512,'Масса должна получиться однородной и плотной.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13512,'Раскатать пласт, сформовать пиццу, выложить начинку, печь в течение 35 минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13513,'На рабочую поверхность просеять муку горкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13513,'Сделать воронку, влить в нее яйцо, взбитое с солью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13513,'Замесить плотное тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13513,'Скатать шар, обернуть смоченным водой полотенцем на 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13513,'Раскатать массу в пласт по размеру сковороды.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13513,'Саму сковороду смазать маслом, выложить лепешку, жарить пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13513,'Перевернуть, выложить начинку, допечь пирог под крышкой в течение 15 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13514,'Готовое тесто вынуть из холодильника за два часа до начала готовки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13514,'Масса должна прогреться и подойти.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13514,'Стол присыпать мукой, выложить тесто, раскатать по форме противня.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13514,'Сам противень смазать маслом, выложить тесто, смазать смесью из томатного соуса и майонеза.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13514,'На сковороду с маслом выложить говяжий фарш, посолить, поперчить, жарить пять или восемь минут до полной готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13514,'Нарезать тонкой соломкой любые колбасные изделия: от сосисок до сервелата.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13514,'Другой вариант: натереть на крупной терке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13514,'Соленые огурцы нарезать кружками, шампиньоны – пластинками.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13514,'Помидоры облить кипятком, снять кожицу, мякоть нарезать тонкими кружками.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13514,'Очистить и нарезать репчатый лук очень тонкими кружками. Поверх томатно-майонезного соуса выложить фарш, лук, колбасные изделия.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13514,'Огурцы, грибы, помидоры выложить поверх в хаотичном порядке, посыпать тертым сыром, нарезанными маслинами.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13514,'Время выпекания – от 25 до 30 минут, температура – 200 градусов.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13515,'В теплую кипяченую воду добавить дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13515,'Всыпать муку, перемешать до получения жидкой каши.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13515,'Дать смеси постоять в течение 20 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13515,'Муку насыпать на рабочую поверхность горкой, сделать углубление, всыпать соль, влить опару.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13515,'Замесить тесто, подливать воду и всыпать муку попеременно и постепенно.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13515,'Добавить оливковое масло, месить еще некоторое время.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13515,'Сформовать два шара-колобка, накрыть полотенцем или крышкой, через два часа раскатать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13515,'Приготовить пиццу с любимой начинкой.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13516,'Упаковку готовых сухариков смешать с майонезом, несколько сухарей оставить для украшения. Они должны быть в виде брусочков и напоминать «дрова».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13516,'Для дальнейшего приготовления понадобятся разъемные бортики, поставить их на блюдо и выложить первый слой. На сухарики, зеленый консервированный горошек, смазать майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13516,'Следующий слой – порезанная ветчина, майонез. Затем огурцы и натертые яйца, также смешанные с майонезом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13516,'Посыпать зеленью (укропом или молодым зеленым луком), ровным слоем, напоминающим «траву», украсить оставленными сухариками, разбросав их по поверхности в произвольном порядке. Дать оригинальному салату «На траве дрова» постоять пару часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13517,'Сухие дрожжи развести в газированной воде, оставить на десять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13517,'Муку просеять, влить оливковое масло и опару.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13517,'Замесить тесто, влить оставшуюся газировку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13517,'Смазать маслом большую емкость, выложить тесто, оставить на 12 часов, можно на ночь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13517,'Затем тесто вынуть, обмять, оставить в тепле на два часа.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13517,'Разделить массу на три части, скатать в шары.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13518,'Насыпать муку горкой на рабочую поверхность, сформовать в ней «окоп».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13518,'Размять пальцами дрожжи, всыпать в отверстие.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13518,'В теплой воде развести соль, влить в углубление с дрожжами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13518,'Замесить вязкое тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13518,'В нем не должны появиться комки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13518,'Для избавления от уплотнений ком поднимают с поверхности и с силой шлепают им об стол.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13518,'Сформовать шар, сделать крестообразный разрез.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13518,'Большую емкость присыпать мукой, положить тесто, укутать тканью, одеялом, поставить в тепло на два часа.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13518,'Объем массы должен увеличиться вдвое.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13518,'Тесто вынуть из кастрюли, еще раз отбить о деревянную поверхность.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13518,'Смазать маслом жаровню, выложить тонко раскатанное тесто, выложить начинку и выпечь в духовом шкафу.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13519,'Три головы и три хвоста горбуши промыть, удалить жабры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13519,'Залить водой, соль – по вкусу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13519,'Отварить до готовности, время – около двадцати минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13519,'Бульон процедить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13519,'Очистить клубни картофеля, морковь и репчатый лук.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13519,'Нарезать кубиками, морковь можно потереть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13519,'Рыбный бульон довести до кипения, добавить картофель, через десять минут – остальные овощи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13519,'Уху досолить, если есть такая необходимость, поперчить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13519,'Варить еще десять минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13519,'Голову разобрать, кусочки рыбы добавить в бульон.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13519,'Всыпать нарезанную зелень петрушки и укропа, довести суп до кипения и снять с огня.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13520,'Сварить макароны в подсоленной воде до готовности.','https://vkuso.ru/data/cache/data/82/48c934c21722b82_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13520,'На разогретом растительном масле обжарить мелко нарезанный репчатый лук до легкой румяности.','https://vkuso.ru/data/cache/data/cb/324d1ffcaae01cb_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13520,'Выложить в лук мясной фарш и обжарить до изменения цвета и выпаривания жидкости на сильном огне.','https://vkuso.ru/data/cache/data/15/b76c35df254f215_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13520,'Добавить в фарш резаные помидоры и обжарить все до выпаривания жидкости также на сильном огне.','https://vkuso.ru/data/cache/data/ae/f85d0f63b6216ae_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13520,'Выдавить в фарш чеснок, посолить и поперчить по вкусу, перемешать и ослабить огонь.','https://vkuso.ru/data/cache/data/1d/2a6d7c808c0641d_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13520,'Выложить в фарш вареные макароны, перемешать и снять с огня.','https://vkuso.ru/data/cache/data/24/c56638ddd7a4f24_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13520,'Перед подачей на стол по желанию можно посыпать макароны зеленым луком и перемешать.','https://vkuso.ru/data/cache/data/25/69bed849a557225_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13521,'Смешать полтора литра крепкого яблочного сидра, коричневый сахар, несколько палочек корицы, гвоздику и душистый перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13521,'Варить около десяти минут, перемешать. Затем варить на тихом огне еще 40 минут. Подать горячий яблочный пряный сидр на стол в бокалах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13522,'Рыбу очистить от чешуи, вымыть и выпотрошить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13522,'Вынуть позвоночник, отрезать плавники, голову, хвост. Удалить жабры.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13522,'Голову и хвост отварить, пену с бульона снимать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13522,'Посолить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13522,'Рыбные части вынуть, отделить мясо, бульон процедить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13522,'Отвар довести до кипения, всыпать картофель, нарезанный кусочками среднего размера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13522,'Добавить кусочки рыбного филе, варить пятнадцать минут, огонь – тихий.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13522,'Добавить в суп кусочки рыбы, снятые с хвоста и головы, душистый и черный перец-горошек, лавровый лист.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13522,'Подержать уху под крышкой, через пять минут удалить лавровый лист.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13523,'Головы промыть, удалить жабры, еще раз промыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13523,'Залить продукт холодной водой, довести до кипения, варить на тихом огне в течение двадцати минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13523,'Посолить по вкусу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13523,'Вынуть рыбу, разобрать, отвар процедить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13523,'Нарезать клубни картофеля кубиками, измельчить репчатый лук и морковь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13523,'Приготовить обжарку: лук и морковь должны приобрести золотистый оттенок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13523,'Процеженный бульон довести до кипения, всыпать картофель.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13523,'Варить пятнадцать минут на тихом огне.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13523,'Добавить кусочки рыбы, вынутые из головы, обжарку, рубленый укроп, петрушку, перец-горошек.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13523,'Положить на пять минут лавровый лист.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13523,'После окончания варки суп должен постоять пятнадцать или двадцать минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13524,'Замороженную горбушу разморозить при комнатной температуре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13524,'Нарезать филе без кожицы порционными кусками, посолить, поперчить, обвалять в муке, обжарить на растительном масле с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13524,'Нарезать репчатый лук, спассеровать в масле, в конце приготовления всыпать муку и перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13524,'Довести воду до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13524,'Добавить кусочки рыбы, обжарку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13524,'Время кипения – десять минут, огонь – тихий.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13524,'Плавленый сыр натереть на терке, всыпать в суп, прогревать до растворения.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13524,'Перец и соль добавить по вкусу.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13525,'Рис тщательно промываем и отвариваем до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13525,'1-2 луковицы перекручиваем или мелко измельчаем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13525,'Рис сливаем и смешиваем и фаршем, луком и яйцом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13525,'Формируем тефтели и выкладываем на противень, застеленный пергаментной бумагой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13525,'Выпекаем в духовке тефтели 20 минут при температуре 200°С.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13525,'Приступаем к приготовлению соуса. Оставшийся лук мелко нарезаем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13525,'Морковь трём на крупной терке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13525,'Обжариваем морковь и лук в глубокой сковороде до золотистой корочки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13525,'В отдельной ёмкости смешиваем сметану, томатный соус и муку. Мука нужна для загустения. Подливаем 250 мл воды. Перемешиваем.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13525,'Ставим сковороду с луком и морковью на медленный огонь и выливаем туда смесь. Когда соус начнет закипать, доливаем оставшуюся воду. Добавляем соль, перец, по желанию -  лавровый лист. Тушить под крышкой 5-7 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13525,'Тефтели достаём из духовки и выкладываем в сковороду.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13525,'По окончанию готовки можно посыпать зеленью.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13526,'Перловую крупу промыть, всыпать в кипяток, варить пятнадцать минут до полуготовности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13526,'Нарезать кубиками картофель и лук, морковь натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13526,'Обжарить репчатый лук на сливочном масле.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13526,'Все ингредиенты добавить в кастрюлю с крупой, варить до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13526,'Посолить и поперчить по вкусу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13526,'Открыть консервы, вынуть из рыбы кости, мякоть покрошить, опустить в суп.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13526,'Всыпать зелень петрушки и укропа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13526,'Суп должен постоять несколько минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13527,'Кабачок среднего размера нарезать на кружки по 2 см, если кожура толстая и грубая, ее лучше срезать. Вырезать серединки, мякоть можно использовать при приготовлении фарша, семена нужно удалить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13533,'Размять ягоды деревянной ложкой в емкости из стекла или с эмалевым покрытием.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13527,'Приготовить начинку: любой фарш или смесь нескольких фаршей. Замочить в небольшом количестве молока черствый белый хлеб, дать набухнуть, затем отжать. Пропустить через мясорубку хлеб, лук-репку, мякоть от кабачков, филе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13527,'Для «связки» добавить сырое яйцо. Соль, молотый перец – по вкусу. Сделать мясной колобок. Завернуть его в пленку и поставить в холодильник на 30 – 40 минут. Колечки кабачков заполнить фаршем, хорошо уплотнить, чтобы начинка не выпала.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13527,'Приготовить кляр: взбить яйца с молоком и солью. Сначала каждый кружок обвалять в муке, затем окунуть в яичную смесь и обжарить на среднем огне, на раскаленном растительном масле.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13527,'Если мясная начинка кажется сыроватой – можно довести до готовности блюдо в духовке или дотушить кабачки с мясным фаршем в кляре на сковороде под крышкой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13528,'Картофель очистить, крупно нарезать, варить в воде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13528,'Репчатый лук обжарить на масле, добавить чеснок и белую часть зеленого лука.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13528,'Переложить обжарку к картофелю.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13528,'При готовности картофеля добавить филе горбуши, нарезанное крупными ломтиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13528,'Время варки – от пяти до семи минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13528,'Вынуть из супа овощи и рыбу, превратить в пюре при помощи блендера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13528,'Добавить нарезанный укроп, зеленый лук, влить нежирные сливки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13528,'Массу еще раз измельчить блендером, добавить бульон.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13528,'Суп довести до кипения, огонь погасить, добавить в кастрюлю лимонный сок.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13529,'Горбушу вымыть, вынуть жабры, филе порезать на порционные куски.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13529,'Варить в воде голову и хвост, плавники до готовности.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13529,'Соль – по вкусу, можно добавить целую луковицу, а затем ее вытащить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13529,'Бульон процедить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13529,'Рыбу разобрать, отложить съедобные кусочки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13529,'Картофель нарезать кубиками, морковь натереть вместе с петрушкой и сельдереем.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13529,'Нарезать лук.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13529,'Овощи и пшено варить в бульоне из рыбы в течение десяти минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13529,'Добавить кусочки филе.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13529,'Время варки – десять минут, огонь погасить.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13529,'Подержать блюдо под крышкой пятнадцать минут.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13530,'Горбушу промыть, удалить жабры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13530,'Хвост, голову, хребет и плавники положить в мультиварку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13530,'Добавить неочищенную, хорошо вымытую луковицу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13530,'Картофель нарезать кубиками, лук – покрошить, морковь измельчить соломкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13530,'Филе рыбы разрезать на порционные куски.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13530,'Бульон процедить, добавить овощи, варить все вместе десять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13530,'Рыбные кусочки выложить в мультиварку, варить пятнадцать минут, режим «Суп».',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13530,'Всыпать рубленую петрушку и укроп, влить водку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13530,'Вынуть чашу из мультиварки, дать блюду постоять под крышкой.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13531,'Довести воду до кипения, выложить нарезанный кубиками картофель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13531,'Посолить по вкусу, варить десять минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13531,'Приготовить обжарку из моркови и репчатого лука, в конце добавить чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13531,'Рис пересыпать в кастрюлю с картофелем, добавить овощную обжарку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13531,'Прогревать пять или семь минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13531,'Добавить консервированную горбушу, поломанную на кусочки, кости вынуть.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13531,'Варить пять минут, добавить укроп и специи.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13531,'Огонь погасить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13531,'Время настаивания супа под крышкой – от пятнадцати до двадцати минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13532,'Довести воду до кипения, отварить головы и хвосты горбуши.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13532,'Бульон процедить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13532,'Морковь, лук, свежие шампиньоны измельчить, всыпать в суп, варить десять или пятнадцать минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13532,'Перец и соль добавить по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13532,'Положить в кастрюлю кусочки рыбы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13532,'Отдельно взбить яйца, ввести в суп тонкой струйкой, в процессе бульон помешивать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13532,'Добавить рубленую зелень, дать ухе настояться и подать к столу.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13533,'Если для приготовления напитка используется замороженный продукт, то он должен постоять при комнатной температуре.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13533,'Кашицу отцедить через марлю, повесить над миской.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13533,'Выжимки залить водой, добавить сахарный песок, довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13533,'Снять с огня, дать постоять пятнадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13533,'Отвар процедить через сито, перемешать с клюквенным соком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13534,'Приготовить тесто средней густоты, как для оладий. Для этого смешать чуть взбитые яйца со сметаной, затем добавить муку, просеянную с разрыхлителем и солью.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13534,'Тесто вылить в смазанную форму, вдавить в него фрикадельки, близко друг от друга. Натереть сыр, насыпать на тесто между фрикадельками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13534,'Печь при температуре 180 градусов примерно полчаса. Дать домашнему пирогу с фрикадельками немного постоять и подать в теплом виде, разрезав на порции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13535,'Для начала разогреем масло на сковородке, добавим мелконарезанный лук, перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13535,'Пока будет обжариваться, в отдельную посуду разбиваем яйца, добавим порезанный базилик, соль, молотый перец, натрем немного пармезана. Слегка перемешаем и добавим в сковороду.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13535,'Накроем крышкой и оставим на 10-12 минут на среднем огне. Фриттата готова.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13536,'Вскипятить молоко, присматривать, чтобы не «убежало». Отдельно растереть желтки с сахаром, ванилином из пакетика и просеянной мукой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13536,'Влить горячее молоко, перемешать. Варить нежный заварной крем для эклеров на тихом огне до густой консистенции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13537,'Корки цитрусовых нарезать на длинные полоски. Если корки не совсем правильной формы, то можно резать на квадраты или придавать любую другую им форму.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13537,'Подготовленные корки залить горячей водой и проварить после закипания воды в течении 10 минут. Затем откинуть их на сито слив всю воду снова залить водой и поставить на огонь. Что бы избавится от больше части горечи корки нужно проварить таким образом от 2 до 4 раз.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13537,'Теперь приготовим сироп из воды, сахара и лимонной кислоты. Проварив сироп 5 минут всыпаем в него наши будущие цукаты варим их на медленном огне около 40 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13537,'После окончания варки массу откидываем на сито и даем полностью стечь сиропу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13537,'Готовые цукаты можно подсушить в духовке, в комнате или оставить мягкими.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13537,'А если обмакнуть их в растопленном шоколаде то получаются настоящие жевательные конфеты в шоколаде со вкусом солнечного цитруса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13538,'Отварить картофель среднего размера, морковь и куриные яйца. Клубни натереть на крупной терке, так же поступить с морковью, яичным белком и желтком, порезать лук-репку и чернослив, все ингредиенты измельчать отдельно. Из банки с печенью слить масло, саму печень размять вилкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13538,'Салат выкладывается слоями. Первый слой – картофельный, смазать майонезом. Затем печень трески, лук, майонез, морковь, майонез. Следующий слой — чернослив, порезанный соломкой, майонез, белок, майонез. Верх салата-торта «Печень трески под шубой» посыпать раскрошенным желтком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13539,'Форму для выпекания застелить бумагой для выпечки и смазать растительным маслом. Выложить помидоры черри, печь в духовке 10 минут при температуре 200 градусов, затем температуру уменьшить до 170 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13539,'Перемешать яйца, дополнительные яичные белки, легкую сметану, нежирный творог, рубленый чеснок и зелень. Смесь взболтать венчиком и вылить на помидоры. Печь 45 минут, немного остудить, вынуть из формы. Подать фриттату с помидорами черри, порезав клиньями от центра, посыпать рубленой зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13540,'Растереть творог с сахаром и солью. Добавить ванилин из пакетика, сырое яйцо и муку, вымесить. Тесто должно получиться однородным. Присыпать поверхность стола мукой и раскатать толстую колбаску.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13540,'Разрезать на кружки, обвалять в муке, обжарить на растительном масле по полторы минуты с каждой стороны. Затем, нежные аппетитные сырники прогреть под крышкой еще три минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13541,'Взбить яйца с сахаром и солью, добавить растопленное сливочное масло, муку, просеянную вместе с разрыхлителем. Замесить тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13541,'Смазать форму для орешков, в каждую ячейку положить тесто, выпечь «скорлупки». Они должны получиться золотисто-коричневого цвета. Остудить, обломать неровности по краям.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13541,'Соединить «скорлупки» по две, начиняя сгущенкой, лучше вареной, коричневого цвета. Можно положить дополнительно в каждый «орешек с вареной сгущенкой» по кусочку фундука, миндаль, кешью. Соединить половинки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13542,'Нагреть воду, добавить сахар и соль, сухие дрожжи, взбить и оставить на десять минут. Порубить охлажденный маргарин кубиками, добавить к дрожжам. Просеять и добавить в массу муку, порциями, вымешивать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13542,'Когда тесто станет густым и упругим – переложить в полиэтиленовую пленку в виде колобка, убрать в холодильник на несколько часов, можно на ночь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13542,'Для начинки отварить рис, подсолить, поперчить, добавить растительное масло. Порубить вареные яйца, лук-репку нарезать и пассеровать на растительном масле. Все смешать и добавить сливочное масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13542,'Раскатать тесто на кружки, положить в середину рисово-яичную начинку, хорошо защипать. Выложить пирожки из хрущевского теста с яйцом и рисом на смазанный растительным маслом противень «швом» вниз, подогнуть уголки. Печь при температуре 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13543,'Взбить 130 г масла или маргарина с сахарным песком. Вбить яйца по одному. Погасить соду уксусом или лимонным соком, добавить в яично-масляную смесь, всыпать муку небольшими порциями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13543,'В тесто добавить какао-порошок и разделить его на три равные части. Выпечь три коржа поочередно, в смазанной и присыпанной панировочными сухарями форме.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13543,'Приготовить начинку, для этого сварить обычную манную кашу на молоке, остудить. Взбить 300 г масла с сахарной пудрой, добавить кашу и тертую цедру лимона. Еще раз взбить массу венчиком и поставить на полчаса в холод.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13543,'Приготовить глазурь, для этого смешать сметану, какао, сахарную пудру, варить смесь до густой консистенции, добавить кусочек сливочного масла и еще поварить, довести до кипения.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13543,'Манным кремом промазать остывшие коржи, должны получиться толстые слои в два сантиметра, верх торта залить глазурью. Подать домашний торт «Птичье молоко», порезав на порции.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13544,'Взбить яйца с сахаром до образования пены. Отдельно взбить мягкое сливочное масло, порциями добавить яичную смесь, продолжить взбивание. Довести до кипения мед, снять с огня, добавить немного соды и быстро перемешать. Масса должна «вскипеть», станет пышной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13544,'Остудить немного и ввести яично-масляную смесь. Всыпать просеянную муку, замесить тесто, оно должно получиться мягким, но не прилипать к рукам. Форму смазать маслом, выложить тесто, разровнять. Выпечь четыре-пять тонких коржей при температуре 200 градусов. Остудить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13544,'Для крема взбить сметану с сахарным песком, промазать коржи, верх и бока торта. Украсить крошкой, оставшейся от выравнивания коржей, рублеными орехами. Классический торт «Медовый» должен постоять несколько часов в прохладном месте для пропитывания кремовой массой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13545,'Смешать сахар, масло, мед и воду, довести смесь до кипения. Снять с огня, добавить муку, просеянную вместе с содой. Получившееся заварное тесто разделить на шесть-семь частей, каждую раскатать в тонкий корж и выпечь до золотисто-коричневатого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13545,'Приготовить крем: растереть яйца с сахаром, добавить муку, холодное молоко, варить на тихом огне до густой консистенции, помешивать. Снять, остудить, добавить ванилин из пакетика и измельченные орехи: лесные или миндаль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13545,'В почти остывший крем положить сливочное масло и взбить миксером или венчиком. Промазать коржи, верх и бока французского торта «Парижский коктейль», дать постоять для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13546,'Взбить яйца с сахаром и солью в пену. Влить стакан молока, продолжая взбивать, всыпать порциями муку. Влить растительное или растопленное сливочное масло. Добавить соду, погашенную уксусом или лимонным соком. Оставить тесто на 5 – 10 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13546,'Жарить блинчики на среднем огне, они должны быть среднего размера, примерно 20 см в диаметре. При появлении пузырьков, перевернуть пышные американские панкейки и жарить с другой стороны еще 20 – 30 секунд.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13547,'Протереть творог через сито два раза, добавить густую сметану, массу мешать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13547,'Отдельно растереть сливочное масло с сахаром, добавить сырые яйца, растирать далее до полного растворения сахара. Обе массы соединить, добавить промытый изюм без косточек, рубленый миндаль или другие орехи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13547,'Форму заполнить массой, накрыть грузом и поставить в холодильник на день или два. Творожная пасха с изюмом и орехами готова.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13548,'Натереть огурец, выложить в стаканы, сбрызнуть лимонным соком и растительным маслом. Следующий слой – нарезанная кусочками отварная курица, затем помидор без кожицы и семян.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13548,'Помидорный слой тоже нужно полить растительным маслом с лимонным соком. В заключение – слой тертого белка и рубленая зелень, верхний слой — желток. Нежный диетический слоеный салат готов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13549,'Для теста смешать кефир, сахар, два сырых яйца, муку, соду, мед. Масса должна быть однородной. Выпечь в смазанной маслом форме четыре одинаковых коржа при температуре 180 градусов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13549,'Приготовить крем. Для этого смешать 180 г сливочного масла и банку сгущенного какао. Промазать коржи, сложить один на другой, верх и бока торта тоже смазать сливочным кремом и обсыпать легкий торт «Медовик» рубленой крошкой, оставшейся от выравнивания коржей.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13550,'Развести желатин в горячей воде. В другой посуде развести зеленое желе из пакетика, тоже в горячей воде, так, как написано в инструкции. То и другое остудить до комнатной температуры.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13550,'Взбить сметану с сахаром и ванилином из пакетика. В полученную пышную массу вмешать остывший желатин, массу снова взбить. Маленькие крекеры с маком или любые другие, сладкие, поломать руками на кусочки. Вмешать в массу вместе с распаренным темным изюмом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13550,'Мелко порубить острым ножом замороженный шоколад, лучше темный.  Взять разъемную форму, выложить примерно треть основной массы, посыпать шоколадной крошкой, снова крем, шоколад, оставшаяся часть массы. Торт поставить в холодильник на полчаса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13550,'Порезать на половинки крупный зеленый сладкий виноград без косточек. Разложить половинки поверх торта разрезанной частью вниз, плотно друг к другу, выкладывать с середины, концентрическими кругами, залить «зеленым желе. Остудить яркий торт «Виноградинка» в холодильнике, можно оставить в нем блюдо на всю ночь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13551,'Залить желатин водой и оставить для набухания. Затем прогреть почти до кипения, но не кипятить. Смешать сметану с сахаром и ванилином из пакетика. Влить в желатиновую массу сметану, небольшими порциями, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13551,'Нарезать свежую клубнику на половинки или четвертинки, если она крупная. В форму влить часть желатиновой массы, выложить ягоды. Залить желатином. Сделать несколько слоев. Дать застыть заливному десерту «Клубника под снегом» в холодильнике в течение нескольких часов. Подать, порезав на порции.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13552,'Смешать сахар и коньяк, добавить ломтики лимона, апельсина, мандарина, персика, яблок, груш. Фрукты нужно очистить от семян, кожицу или цедру не снимать, цедра добавит в напиток свою толику вкуса и аромата.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13552,'Фруктовую смесь поставить в холод на 8 – 10 часов. Затем массу переложить в большой кувшин, залить апельсиновым соком и красным охлажденным вином, добавить корицу палочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13552,'Оставить сангрию с корицей и фруктами на 15 – 20 минут. В стаканы положить лед кубиками, влить напиток с фруктами, удалив корицу, и подать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13553,'Натереть или мелко нарезать морковь соломкой, репчатый лук – тонкими полукольцами, потушить то и другое вместе до готовности с небольшим количеством растительного масла. За пару минут до конца тушения добавить соль, зелень, специи и томатную пасту, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13553,'Любую рыбу очистить, вымыть, порезать на куски и припустить в кипящей воде с солью и лавровым листом, перцем-горошком. При полуготовности – вынуть, удалить косточки и порезать на кусочки величиной с палец.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13560,'Перемешать. Форму, примерно 17 см в диаметре, смазать сливочным маслом, выложить тесто. Печь пряный сырный кекс с ветчиной при 180 градусах в течение 45 минут. Подать, порезав на порции.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13553,'Выложить в кастрюлю немного морковно-лукового маринада с томатной пастой, затем слой рыбы, снова маринад. Слоев может быть несколько. Потушить сочную рыбу под томатным маринадом на тихом огне, добавить в конце соль, специи и уксус по вкусу. Дать постоять несколько часов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13554,'Нарезать репчатый лук и любые свежие грибы. Обжарить лук на растительном масле, добавить грибы и пожарить вместе до полуготовности. Соль, перец – по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13554,'Булочки с кунжутом разрезать пополам по горизонтали, вынуть часть сердцевины или вмять ее внутрь. Уложить в получившиеся выемки тонкие ломтики свежего огурца и помидоров, посолить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13554,'Затем слой грибов с луком. Посыпать тертым твердым сыром, печь около 10 минут при температуре 200 градусов. Закусочные бутерброды с грибами под сыром подать теплыми. При подаче украсить мелкорубленой зеленью укропа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13555,'Натереть на мелкой терке очищенный от кожуры и семян кабачок, лишнюю жидкость лучше слить. Натереть твердый сыр. Смешать то и другое, добавить сырое яйцо, муку, соль и перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13555,'Тесто должно быть полужидким, как для обычных оладий. Испечь «блинчики» среднего размера, диаметром около 20 см.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13555,'Приготовить начинку: обжарить любой фарш с рубленым репчатым луком и чесноком. Добавить любимые сухие специи. Фарш остудить и смешать с небольшим количеством майонеза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13555,'Прослоить кабачковые блинчики мясной начинкой, сверху – тонкие кружки помидоров, еще немного майонеза. Печь кабачковый тортик с сыром и мясным фаршем при 220 градусах в течение 10 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13556,'Смешать сухой, хорошо отжатый от избытка влаги, творог, сахарную пудру, сливки, размягченное сливочное масло. Масса должна получиться густой. Слепить из полученной массы мокрыми руками шарики или небольшие брусочки. Поставить на блюде в морозильную камеру на 15 – 20 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13556,'Растопить шоколад со сливками на водяной бане. Домашние творожные сырки обмакнуть в глазурь, лучше делать это с помощью двух вилок, выложить на пергамент и снова поставить в холод. Процедура обмакивания должна происходить быстро, чтобы сырок не успел развалиться.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13557,'Нарезать соломкой свежие и маринованные огурцы, крабовые палочки, натереть сыр. Смешать, добавить рубленую зелень.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13557,'Заправить салат «Сочная хрустяшка» майонезом, перемешать. Сухарики длинной формы добавить перед подачей, они не должны успеть размокнуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13558,'Завести обычное блинное тесто: смешать молоко и сырые куриные яйца, добавить муку, соль, сахар, мелко порезанную зелень. Хорошо взбить венчиком, тесто не должно содержать комочков, дать немного постоять, чтобы набухла клейковина. Выпечь 5 – 6 тонких блинчиков, жарить на растительном масле с двух сторон.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13558,'Противень застелить бумагой для выпечки, выложить блины слоями, между ними – кружочки помидоров, посыпанные тертым твердым сыром. Помидоры лучше взять менее водянистые и очистить от кожицы. Можно добавить мелко порубленный чеснок или пропущенный через чеснокодавку. Печь блинный пирог с сырной начинкой в течение 15 – 20 минут. Подать, порезав на порции, как торт.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13559,'Песочное печенье раскрошить, можно сделать это с помощью скалки в полиэтиленовом пакете, чтобы крошки не разлетелись по кухне. Добавить растопленное сливочное масло, перемешать. Массу выложить в форму. Дать немного постоять, чтобы масло впиталось.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13559,'Взбить сливки миксером или венчиком, добавить размятый творог, заранее распаренный изюм. Еще немного взбить. Выложить начинку на «корж» из печенья, украсить цукатами и кусочками любых фруктов, ягод. Английский чизкейк с изюмом и фруктами поставить в холодильник на несколько часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13560,'Взбить подсолнечное масло без запаха, а лучше взять оливковое, с сырыми яйцами, молоком. Добавить погашенную уксусом или лимонным соком соду, соль по вкусу, молотые базилик и паприку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13560,'Натереть любой твердый сыр, например «Российский», вмешать в массу. Порезать кубиками нежирную ветчину, смешать с небольшим количеством муки, чтобы кусочки равномерно распределились в тесте, добавить в основную смесь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13619,'Кабачки вымыть, очистить, мякоть нарезать кубиками небольшого размера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13619,'Лимон ошпарить, цедру натереть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13561,'Смешать кокосовую стружку и сгущенное молоко, добавить сахарную пудру. Масса должна быть густой, можно добавить еще пудру, если она получилась жидковата. Вмешать ванилин из пакетика.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13561,'Слепить шарики средней величины. Можно это сделать с помощью двух ложек, которые нужно обмакивать в воду, или мокрыми руками. Заморозить до твердого состояния.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13561,'Обмакнуть сладости в растопленный на водяной бане шоколад либо облить им выложенные на фольгу «шарики». Выложить домашние конфеты «Баунти» на блюдо, дать застыть и подать на стол.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13562,'Смолоть фундук или другие орехи достаточно мелко. Можно часть орехов оставить в виде довольно заметных кусочков. Добавить сырые яйца, сахар, разрыхлитель.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13562,'Смазать форму маслом и посыпать мукой, переложить вымешанную массу. Печь пять минут в микроволновой печи или в духовке до готовности. Охладить в течение пяти минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13562,'Приготовить крем: вареная сгущенка, сливочное масло или растопленный шоколад. Смешать ингредиенты до однородного состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13562,'Корж разрезать по горизонтали и промазать полученным кремом, посыпать сверху сахарной пудрой. Быстрый ореховый торт без муки и масла готов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13563,'Филе курицы вымыть, удалить кости, порезать грудки на две-три части каждую. Приготовить соус для маринования: разбить сырое яйцо, добавить три столовых ложки муки, столько же майонеза, соль. Можно добавить любимые сухие приправы, например, итальянские травы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13563,'Перемешать. Положить в маринад куриное мясо, оставить на два часа под крышкой. Обжарить маринованные грудки на разогретой сковороде со всех сторон на растительном масле в течение 15 – 20 минут. Сочная куриная грудка в лимонном маринаде готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13564,'Смешать сырое яйцо, одну столовую ложку майонеза, чайную ложку кетчупа или томатной пасты. Мелко порезать сосиску или ломтик колбасы, натереть сыр. Всё перемешать, соль, зелень, специи  по вкусу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13564,'Намазать массой ломтики белого батона. Выложить на смазанный маслом противень, печь в духовке в течение пяти минут, выключить огонь, подержать быстрые горячие бутерброды с колбасой и сыром еще две минуты, не открывая дверку, затем вынуть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13565,'Нарезать соломкой вареные яйца, упаковку крабовых палочек, отварных кальмаров. Кальмары варить недолго, три-четыре минуты, иначе они станут жесткими.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13565,'Нарезать любое филе красной соленой рыбы, добавить нашинкованную пекинскую капусту и консервированную кукурузу из банки (жидкость слить).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13565,'Майонез – по вкусу. Выложить изысканный салат «Морское наслаждение» в салатницу, украсить красной икрой и веточками укропа.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13566,'Начинка: творог или брынза (можно взять то и другое в равных пропорциях)  размять вилкой. Добавить сметану, мелко порезанные вареные креветки, рубленый укроп или петрушку, молотый перец и давленый чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13566,'Массой наполнить корзиночки, сверху положить по готовой отваренной и очищенной креветке, чуть сбрызнуть лимонным соком. Закусочные тарталетки с творогом и креветками готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13567,'Замороженное готовое слоеное тесто из магазина согреть при комнатной температуре, вырезать «цветы» с помощью формочек для печенья с острыми краями.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13567,'Каждый «цветок» поместить в маленькую форму для кекса, «лепестки» отогнуть наружу. В тесте сделать отверстия. Печь в духовке при температуре 180 градусов в течение пяти-семи минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13567,'Приготовить лимонный мусс. Для этого смешать сгущенное молоко и сок двух лимонов. Заполнить «цветы» полученной массой. Края «лепестки» посыпать сахарной пудрой. Простое печенье с лимонным муссом готово.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13568,'Свиное мясо с помощью острого ножа нашпиговать разрезанными вдоль зубчиками чеснока, натереть приправами: корицей, хмели-сунели, соль, молотый красный перец, горчица.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13568,'Смесь приправ лучше немного развести водой и этой смесью смазать мясо со всех сторон. Поставить в холодильник для пропитывания на три часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13589,'Сформировать «розы», для этого поднять один край и обернуть им начинку, затем следующий, им также обернуть начинку и предыдущий «лепесток».',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13619,'Мякоть без косточек измельчить в блендере.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13568,'Запекать в завернутом виде, в фольге, до полной готовности. За 10 минут до окончания термообработки открыть фольгу: мясо должно немного подрумяниться. При подаче свинину, запеченную с корицей и приправами нарезать ровными ломтиками.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13569,'Говядину очистить от пленок, нарезать небольшими кусочками, залить водой, довести до кипения и варить полтора часа на тихом огне, постоянно снимая пену.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13569,'Нарезать репчатый лук, измельчить заранее подсушенные на сковороде грецкие орехи. В готовый мясной бульон всыпать рис, варить 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13569,'Добавить обжаренный на растительном масле лук, орехи, соус ткемали или тклапи (сушеное сливовое пюре), хмели-сунели, перец красный острый и черный горошком.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13569,'Соль – по вкусу. Варить пять-семь минут, добавить выдавленный чеснок и снять с огня. Грузинский острый суп «Харчо» должен настояться под крышкой 10 – 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13570,'Растворить дрожжи в воде, дать постоять 10 минут, добавить соль, сахар, просеянную кукурузную муку. Массу переложить в смазанную маслом миску, накрыть полиэтиленовой пленкой и дать постоять в теплом месте несколько часов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13570,'Когда тесто увеличиться в два раза, разрезать пополам, раскатать половину в виде круга, промазать готовой шоколадной пастой из магазина. Оставшуюся часть также раскатать и накрыть начинку сверху. Края выпечки разрезать и завернуть в виде «лепестков». Всю процедуру проделать на присыпанном мукой листе.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13570,'Сформированный пирог «Шоколадный  цветок» из кукурузной муки смазать яичным желтком и печь при 180 градусах в течение 20 минут. В конце приготовления поднять температуру еще на 20 градусов, чтобы получилась золотисто-коричневая корочка.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13571,'В большой сковороде растопить 50 г сливочного масла. Обжарить куриное филе с двух сторон, переложить в форму для запекания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13571,'Добавить в сковороду еще столько же сливочного масла, обжарить рубленый зеленый лук, мелко нарезанные чеснок и шампиньоны. Смесь переложить к курице.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13571,'Всё в ту же сковороду влить сливки, Амаретто, добавить тертый твердый сыр. Прогреть на среднем огне. Добавить каперсы, перемешать, готовым соусом залить курицу.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13571,'Печь в духовке при температуре 175 градусов в течение 40 минут. Куриное филе, запеченное под соусом Амаретто, готово.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13572,'Снять цедру с апельсинов, залить водой на сутки для удаления лишней горечи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13572,'Нарезать тонкой соломкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13572,'Каждую свернуть в завитушку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13572,'Сварить сироп из воды с сахаром.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13572,'Добавить цедру, варить в течение часа на тихом огне.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13572,'Влить лимонный сок.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13572,'Расфасовать в небольшие баночки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13573,'Фрукты вымыть, нарезать, удалить косточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13573,'Перемолоть вместе с кожурой при помощи блендера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13573,'Массу выложить в емкость, всыпать сахар, долить воду.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13573,'Довести до кипения на среднем огне.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13573,'Корень имбиря очистить, натереть или также размолоть в блендере.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13573,'Добавить в основную массу, варить до густоты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13573,'Разлить в банки небольшого объема в горячем виде.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13574,'Все продукты кроме растительного масла, шоколада, сливок и посыпки соединяем вместе и замесим тесто в комбайне, после накроем пищивой пленкой и оставим на 2 часа в теплом месте.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13574,'После раскатываем тесто в пласт толщиной в 1 см, немного смазав рабочую поверхность растительным маслом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13574,'При помощи стакана и насадки для крема придаем тесту нужную форму для пончиков.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13574,'После готовые вырезанные пончики оставляем на 20 минут отдохнуть в теплом месте, накрыв полотенцем.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13574,'По истечению времени обжариваем на растительном масле на тихом огне в кляре до золотистой корочки с обоих сторон.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13574,'Горячие сливки добавляем к шоколаду и размешиваем до растворения шоколада.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13574,'После обмакиваем пончик в глазури и посыпаем посыпку сверху.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13575,'Яйца взбить, отдельно превратить спелый банан в пюре. Смешать, печь без масла, на сковороде с антипригарным покрытием.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13576,'Вымыть картофель среднего размера, сбрызнуть оливковым маслом и посолить. Наколоть клубни в нескольких местах вилкой. Выложить на застеленный алюминиевой фольгой противень. Печь около часа при температуре 220 градусов до готовности, клубни должны стать мягкими.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13576,'Кубиками нарезать бекон, обжарить на среднем огне на сковороде. Обсушить на бумажных полотенцах, удалив, таким образом, излишки жира. На сковороде с оставшимся жиром пассеровать рубленый репчатый лук, добавить соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13576,'Если жира слишком много,  слить, для обжаривания будет достаточно одной столовой ложки. Лук должен приобрести золотисто-карамельный цвет. Добавить мелко измельченный чеснок и жарить еще полминуты. Снять с огня.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13576,'Остывший картофель разрезать пополам, осторожно, чтобы не развалился клубень, удалить внутреннюю часть ложкой, должны остаться стенки толщиной полсантиметра. Вынутую картофельную массу размять с поджаркой, добавить сметану и тертый сыр Чеддер. Соль, перец молотый – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13576,'Выложить картофельные «лодочки» на противень с фольгой, заполнить начинкой. Сверху посыпать еще тертым сыром того же сорта. Печь 15 – 20 минут. Картофель, запеченный с беконом и сыром Чеддер, готов.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13577,'Для приготовления салата картофель (воду при варке подсаливала), свеклу (в воду при варке добавляла немного сахара, так она вкуснее) и морковь сварила в кожуре. Яйца сварила вкрутую. Когда овощи и яйца остыли, почистила.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13577,'Лук порезала полукольцами, добавила к ним соль, сахар и 6% уксус (у меня был яблочный). Все хорошо перемешала и оставила мариноваться. Заранее я его не мариновала, пока подготавливала все необходимое для салата и приступила к его сборке, лук был готов.','https://vkuso.ru/data/cache/data/ad/082585eb25c8ead_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13577,'Смешала сметану и майонез в однородную массу. Получился майонезный соус. Майонез у меня был домашний, делается меньше минуты, а вкус значительно лучше магазинного.','https://vkuso.ru/data/cache/data/f5/86f61880216f3f5_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13577,'Картофель я нарезала мелким кубиком, можно натереть на крупной терке (так получится быстрее). Выложила первым картофельный слой и смазала майонезным соусом.','https://vkuso.ru/data/cache/data/45/2c1f0a47e113645_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13577,'На картофель выложила вареную колбасу, нарезанную мелкими кубиками. И смазала майонезным соусом.','https://vkuso.ru/data/cache/data/ae/4b9c3376a7fdfae_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13577,'На колбасу положила тонким слоем маринованный лук, соусом не смазывала.','https://vkuso.ru/data/cache/data/47/8dced9ad2ef2647_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13577,'На лук положила свежие и маринованные огурцы нарезанные мелким кубиком. Смазала соусом.','https://vkuso.ru/data/cache/data/f1/81effe9530672f1_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13577,'Затем вареная морковь, также мелко нарезанная и соус сверху.','https://vkuso.ru/data/cache/data/75/348875f24c16275_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13577,'Консервированный горошек и слой майонеза.','https://vkuso.ru/data/cache/data/86/dcaa495bbf59986_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13577,'Белки и соус.','https://vkuso.ru/data/cache/data/71/102642458dad071_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13577,'Свекла и соус.','https://vkuso.ru/data/cache/data/c1/9488aa4be5877c1_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13577,'Последний слой тертые на мелкой терке желтки. Засыпала ими салат и украсила мелко нарезанным зеленым луком.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13578,'Перетереть творог, можно два раза пропустить через сито. Добавить сгущенку, взбить 5 – 6 минут с помощью миксера.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13578,'Добавить какао, можно обойтись и без него. Выложить творожное мороженое в лоток или формочки и заморозить в течение двух часов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13579,'Желатин развести в теплой воде, дать набухнуть. Смешать сметану (лучше взять 20% жирности) и сахар, мешать, пока сахар не растворится. Желатин прогреть, но не кипятить, смешать с основной массой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13579,'Разделить ее на несколько частей, в каждую вмешать разные ингредиенты. Можно взять любые ягоды, какао или тертый шоколад, ликеры, кусочки очищенной мякоти цитрусовых.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13579,'Выливать смеси в форму слоями, каждый остужать в холодильнике до полутвердого состояния, затем заливать следующий. Оригинальный сметанный десерт оставить в холодильнике на ночь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13618,'Апельсины вымыть, нарезать, удалить косточки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13580,'Готовим тесто: Яйца взбиваем с сахаром до пышной белой массы. Добавляем растопленное сливочное масло, томатную пасту и перемешиваем миксером. Добавляем разрыхлитель и постепенно вводим муку, замешивая тесто. Тесто замешиваем сначала с помощью миксера, а затем руками. Отправляем тесто в холодильник минут на 30. Затем разделяем его на 5 частей и каждую часть раскатываем на пергаменте, сразу обозначив размер коржа. Отправляем тесто поместить в разогретую духовку на температуру 200 градусов примерно на 5 минут.','https://vkuso.ru/data/cache/data/60/5e0b72b02502760_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13580,'Готовим крем: взбиваем блендером сгущенное молоко, сметану и творог до однородной массы. Отдельно мягкое сливочное масло размягчаем миксером и добавляем его в творожную массу. Взбиваем крем миксером до однородного состояния.','https://vkuso.ru/data/cache/data/0f/22a4ac832d2e80f_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13580,'Готовим украшение: шоколад растапливаем на водяной бане и выливаем его тонким слоем на силиконовый коврик или фольгу, даем застыть в холодильнике.','https://vkuso.ru/data/cache/data/be/26346e47d6524be_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13580,'Формируем торт: каждый корж, а также верх торта и бока промазываем кремом. Обрезки от коржей измельчаем в крошку. По краю верха торта обсыпаем крошкой, также обсыпаем крошкой бока торта. Застывшим шоколадом украшаем середину торта. Даем торту настояться при комнатной температуре 2 часа и наслаждаемся вкусным тортиком.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13581,'Куриную грудку мелко режем, солим, перчим, обжариваем на сковороде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13581,'Нарезаем овощи.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13581,'В миске смешайте все ингредиенты для соуса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13581,'Тортилью смажьте соусом, выложите овощи и курицу, полете сверху соусом и заверните.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13581,'Обжарьте на сухой сковороде.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'Смешать яйцо комнатной температуры, обычный сахар, ванильный сахар и соль, хорошо взбить венчиком до растворения крупинок.','https://vkuso.ru/data/cache/data/9a/d7ef4d33a17f39a_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'Добавить теплое молоко, теплую воду и дрожжи, взбить до полного растворения дрожжей.','https://vkuso.ru/data/cache/data/0a/196cffe1cf1fa0a_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'Добавить растительное масло комнатной температуры, все хорошо перемешать до однородности.','https://vkuso.ru/data/cache/data/66/d1cbf18a8614766_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'4. Просеять в смесь муку в 2-3 приема.','https://vkuso.ru/data/cache/data/95/30dbf5fa9aedb95_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'Сначала перемешивая ложкой.','https://vkuso.ru/data/cache/data/d7/9322dde3b7c58d7_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'Затем вымесить руками.','https://vkuso.ru/data/cache/data/2a/e1b29b1023ff62a_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'Следить, чтобы тесто получилось не слишком крутым. Оно должно быть довольно сильно липким. Вымесить тесто в течение 5-7 мин пока оно не перестанет сильно липнуть к рукам. Муку не добавлять. Вымешанное тесто должно получиться нежным, эластичным и совсем чуть-чуть будет липнуть к рукам.','https://vkuso.ru/data/cache/data/1d/f4c68523e98ed1d_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'Смазать большую ёмкость растительным маслом, положить в нее тесто, слегка обваляв в масле, накрыть ёмкость пленкой и оставить в теплом месте на 1 час.','https://vkuso.ru/data/cache/data/c7/f429f9cf0abc4c7_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'Через час, когда тесто увеличится в объеме в 3 раза, выложить его на стол.','https://vkuso.ru/data/cache/data/44/405a177be3b3244_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'И слегка обмять.','https://vkuso.ru/data/cache/data/2f/fecd867032f432f_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'Разделить тесто на 6 частей.','https://vkuso.ru/data/cache/data/a4/b3d06f8b98f0ba4_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'И сформировать шарики.','https://vkuso.ru/data/cache/data/03/c6fc0628c446c03_434x295_notrise.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'Каждый шарик раскатать до толщины около 3 мм размером примерно 20х20 см. Стол и тесто мукой не присыпать.','https://vkuso.ru/data/cache/data/4b/3a0ca7fb253864b_434x295_notrise.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'Обильно смазать пласт растопленным сливочным маслом.','https://vkuso.ru/data/cache/data/58/ba80d8491023258_434x295_notrise.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'Посыпать сахаром.','https://vkuso.ru/data/cache/data/6d/402fffa09a0736d_434x295_notrise.jpg',15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'И по желанию корицей.','https://vkuso.ru/data/cache/data/dc/3386163f52f50dc_434x295_notrise.jpg',16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'Свернуть пласт рулетиком.','https://vkuso.ru/data/cache/data/a1/3c0d9a3d9e68ea1_434x295_notrise.jpg',17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'Закрепить край и сложить рулетик пополам швом внутрь.','https://vkuso.ru/data/cache/data/84/42da550cf97cc84_434x295_notrise.jpg',18);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'Надрезать свернутый рулетик со стороны сгиба чуть не дорезая до края.','https://vkuso.ru/data/cache/data/b6/04f3f46d0af16b6_434x295_notrise.jpg',19);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'И разложить в сердечко.','https://vkuso.ru/data/cache/data/93/9bb190052b06993_434x295_notrise.jpg',20);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'Выложить булочки на противень, застеленный бумагой для выпечки, на расстоянии друг от друга и оставить булочки на 20 мин в теплом месте для расстойки. Булочки увеличатся в размере после расстойки примерно в 1,5-2 раза.','https://vkuso.ru/data/cache/data/d3/a8e5d5fb4d49bd3_434x295_notrise.jpg',21);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'Смазать расстоявшиеся булочки взбитым яйцом и поставить в заранее разогретую духовку.','https://vkuso.ru/data/cache/data/b2/70eecc3c9dde2b2_434x295_notrise.jpg',22);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'Выпекать булочки при 180 С около 20 мин до румяности.','https://vkuso.ru/data/cache/data/bc/671afbeffc88abc_434x295_notrise.jpg',23);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'Плюшки остудить и переложить на блюдо.','https://vkuso.ru/data/cache/data/85/29cde5ca13ae185_434x295_notrise.jpg',24);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13582,'Вот такие красавицы получились.','https://vkuso.ru/data/cache/data/b8/4aee09f647f87b8_434x295_notrise.jpg',25);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13583,'Сушеные грибы замочить в холодной воде, дать постоять, затем отварить в той же воде. Репчатый лук нашинковать, обжарить на растительном масле, добавить ломтики грибов, жарить 5 – 7 минут, положить рубленую зелень петрушки, раскрошенные вареные яйца, соль, молотый перец.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13583,'Отварить листья белокочанной капусты, уложить на них готовый грибной фарш, завернуть конвертиком. Залить домашние голубцы с грибами и яйцом сметаной, сверху  тертый сыр. Запечь до готовности в духовке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13584,'Нарезать помидоры и моцареллу пластинками. В форму выложить готовое слоеное тесто, на него помидоры и моцареллу поочередно.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13584,'Соль, перец молотый – по вкусу. Печь слоеный пирог в духовке полчаса при 180 градусах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13585,'Приготовить тесто, для этого смешать сахар, какао, соду, разрыхлитель и муку. Соль – по вкусу. Добавить яйца, кефир, крепко сваренный кофе, растительное масло и ванилин из пакетика. Взбивать до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13585,'Смазать форму для выпечки, вылить тесто, печь полчаса, до готовности, проверить зубочисткой. Готовую выпечку достать, остудить, разрезать на два коржа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13585,'Приготовить шоколадную глазурь. Для этого растопить сливочное масло, добавить какао-порошок. Всыпать сахарную пудру, ванильный экстракт и молоко. Размешать до однородности, в массе не должно быть комочков. Глазурь должна получиться густой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13585,'Промазать коржи, налить глазурь сверху и нанести на бока. Охладить элегантный торт «Черная магия» в холодильнике в течение трех-четырех часов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13586,'Отварить яйцо, порубить. Натереть твердый сыр на крупной терке. Порезать маслины, порубить чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13586,'Все ингредиенты перемешать, добавить зелень, заправить майонезом. Салат выложить в готовые тарталетки и украсить маслинами, листочками зелени.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13587,'Начнём с рулета: любой полутвердый сыр натереть на крупной терке, добавить яйца, сметану и если необходимо соль. Все перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13587,'Противень застелить пергаментом, сбрызнуть маслом. Вылить сырную массу, разровнять придавая форму прямоугольника.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13587,'Ставим в разогретую духовку при 180°С на 10-15 мин. Затем остудить до теплого состояния.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13587,'Для начинки натереть на терке крабовые палочки, отварные яйца. Зелень мелко нарезать. Все соединить, посолить по вкусу, заправить майонезом и перемешать. Начинка готова.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13587,'Выложить начинку на теплый сыр, равномерно распределить отступая от краев 1-2 см.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13587,'Завернуть по широкой стороне как можно плотнее, при помощи пергамента. Аккуратно переложить на пищевую пленку, плотно завернуть в 2 слоя пленки и убрать в холод на 2-3 часа.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13588,'Натереть плавленые сырки, добавить растопленное сливочное масло, яйцо, просеянную через сито муку. Вымесить тесто, подержать в холодильнике полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13588,'Тесто достать из холодильника, раскатать толщиной в полсантиметра, вырезать печенье с помощью формочек. Печь домашнее сырное печенье до золотистого цвета в духовке при 180 градусах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13589,'Приготовить начинку. Для этого нарезать сырое куриное филе на кубики со стороной 1 см. На крупной терке натереть твердый сыр. Смешать, добавить соль и перец, майонез, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13589,'Готовое слоеное тесто раскатать в пласт толщиной полсантиметра. Разрезать на квадраты со стороной в дециметр, сделать на них надрезы от угла, не доходя до центра. На середину положить начинку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13618,'Промыть зеленый крыжовник, удалить плодоножки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13589,'Когда все «лепестки» будут завернуты и булочки сформированы, выложить их на противень и смазать взбитым желтком. Печь закусочные розочки с курицей и сыром 30–40 минут при температуре 180 градусов.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13590,'Заморозить сливочное масло, затем натереть на крупной терке. Добавить сахар, яйцо, просеянную муку вместе с разрыхлителем. Быстро, руками, замесить песочное тесто, скатать его в колобок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13590,'Смазать сливочным маслом разъемную форму для выпечки. Тесто раскатать в пласт, толщиной полсантиметра, перенести в форму, размер лепешки должен позволить сделать высокие бортики.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13590,'Приготовить начинку: взбить сметану с яйцами, сахаром, ванилином. Масса должна быть однородной, вылить её на тесто. Печь ванильный сметанник на песочном тесте 45–50 минут при температуре 180 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13591,'Молодой картофель в мундире тщательно вымыть, положить в кастрюлю с водой и отварить на среднем огне до готовности. Затем достать клубни из воды (саму воду не выливать!) и дать им полностью остыть, после чего картофель очистить и размять в пюре.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13591,'Достать креветки из холодильника и разморозить их до комнатной температуры, затем их тщательно очистить и промыть под холодной водой. В сохраненную воду положить картофельное пюре и хорошенько все перемешать, добавить сыр и подготовленные креветки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13591,'Суп опять перемешать, добавить молотый перец и соль (при необходимости), поставить кастрюлю на минимальный огонь и варить суп 5-7 минут. Разлить по тарелкам готовый крем-суп из креветок с сыром Филадельфия, присыпать каждую порцию рубленым укропом и подать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13592,'Бананы очистить, нарезать кусочками, переложить в чашу блендера, добавить яйца, молоко и сахар. Взбить все в однородную массу, всыпать в нее муку и быстро перемешать тесто, но не до однородности. При необходимости добавить муку, доводя до густоты, сравнимой со сметаной',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13592,'Получившееся тесто выложить на горячую сковородку с маслом и жарить банановые оладьи со всех сторон, пока они не станут коричневого цвета. Разложить готовые банановые оладьи на молоке по тарелкам и украсить кружочками бананов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13593,'Для коржа: отделенные от желтков белки взбить в стойкую пену. Желтки взбить с маслом, сахаром и экстрактом ванили, всыпать муку и тщательно перемешать, чтобы не было комков.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13593,'В тесто аккуратно добавить взбитые белки, добавить измельченную лимонную цедру и хорошо все перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13593,'Круглую форму смазать маслом и равномерно распределить по ней приготовленное тесто тонким слоем.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13593,'Выпекать бисквит 10-15 минут при 160 градусах, после прокалывания изделия зубочистка должна остаться чистой. Готовый корж достать из духовки и оставить в форме до полного остывания.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13593,'Для сырной массы: сливочный сыр взбить до однородности, добавить по одному яйца и желтки, подмешать сметану и сахарную пудру.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13593,'В конце добавить в сырную массу муку, сок и измельченную цедру лимона, тщательно все перемешать (комков быть не должно).',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13593,'Распределить получившуюся массу по остывшему коржу, сразу же убрать в духовку, разогретую до 200 градусов (с конвенцией) или 240 градусов (без конвенции), и запекать чизкейк 40-50 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13593,'Для крема: сметану взбить с сахаром и лимонным соком и смазать кремом поверхность и бока готового изделия, заделывая появившиеся трещинки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13593,'Посыпать верх чизкейка половиной кокосовой стружки, оставшуюся стружку распределить по бокам.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13593,'Клубнику помыть и оторвать плодоножки, ягоды разрезать пополам и разложить на поверхности чизкейка в виде любого узора. На медленном огне подогреть абрикосовый джем, протереть его через сито и аккуратно смазать сиропом клубнику.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13593,'Готовый лимонный чизкейк с клубникой и кокосом украсить свежей мятой и подать к столу, нарезав порционными кусками.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13594,'В кипяченой воде (холодной) замочить желатин и оставить его на полчаса, чтобы разбух. При помощи блендера или миксера превратить творог, сметану и сахар в однородную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13618,'Ингредиенты пропустить через мясорубку или размолоть при помощи блендера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13638,'Обвалять макароны в муке и крахмале.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13594,'Набухший желатин развести в теплом молоке, поставить смесь на небольшой огонь и дать желатину полностью раствориться (важно чтобы он не кипел!). Получившуюся желатиновую смесь влить в творожную массу, хорошо все перемешать и разделить получившуюся массу на три части.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13594,'В первую часть ввести какао, во вторую, измельченное печенье, в третью ничего не добавлять. Глубокую форму или порционные формочки застелить пленкой и наполнить творожными массами, выкладывая их по очереди.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13594,'Убрать десерт «Мраморный» с творогом в холодильник минимум на 6 часов. Перед подачей перевернуть застывший десерт на блюдо или тарелки, снять пищевую пленку и украсить по желанию.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13595,'Небольшими кубиками или тонкой соломкой нарезать кальмары и очищенные яйца, измельчить крабовые палочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13595,'В салатник выложить кальмары, крабовые палочки, яйца и икру, заправить салат «Морской» майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13596,'Лук очистить и нарезать полукольцами, выложить на горячую сковородку, смазанную подсолнечным маслом, и слегка обжарить на среднем огне. Морковь очистить, нарезать небольшими кубиками и добавить к луку. Перец промыть, вырезать семенную коробочку, нарезать овощ соломкой и добавить к луку с морковкой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13596,'Помидоры промыть, нарезать кольцами, которые затем разрезать на 4 части и добавить в сковородку с овощами. Далее добавить к овощам кукурузу и фасоль (если они консервированные, перед добавлением жидкость нужно слить), соль, молотую корицу и перец чили, сушеный чеснок, паприку и молотый томат.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13596,'Куриное мясо промыть, нарезать небольшими кусочками, добавить к овощам и хорошенько все перемешать, филе должно покрыться овощным соусом. Тушить овощное рагу по-мексикански с курицей в районе 10 минут, затем разложить готовое блюдо по тарелкам и подать, присыпав при желании зеленью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13597,'Положить стручки фасоли в подсоленную кипящую воду, варить 7-10 минут, переложить в дуршлаг, дать стечь воде. Болгарский перец разрезать пополам, удалить семена, нашинковать тонкими полосками, помидоры нарезать кружочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13597,'Нашинковать мелко чеснок, обжарить в разогретом масле,  добавить перец и фасоль, залить смесью из тертого сыра, молока, яиц, соли и специй, накрыть крышкой. Овощи в сырной заливке будут готовы после того как заливка станет густой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13598,'В чашу блендера разбить яйца, всыпать сахар, добавить сметану, хорошо взбить. Подготовить противень вылить тесто, выпекать при 180 градусах примерно полчаса, дать коржу остыть, разломать руками на небольшие кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13598,'Развести и  приготовить по инструкции раствор желатина, соединить его с сахарной пудрой и сметаной. Выложить в достаточно глубокую форму слои в следующем порядке: кусочки коржа, сметана, ягоды клубники.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13598,'Поставить очень вкусный и простой летний тортик минимум на 4-5  часов в холодильник (лучше на ночь). Достать форму с застывшим десертом, окунуть на минуту дно в кипяток, резко, но аккуратно перевернуть на блюдо',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13599,'Поставить варить подготовленную грудку курицы без кожи, нарезать мелкими кубиками лук, морковку измельчить на терке и обжарить вместе с луком с небольшим количеством масла. Грибы помыть, почистить, нарезать мелкими кусочками, натереть сыр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13599,'Собрать салат в следующем порядке. Первым слоем выложить две трети морковки и лук в форме полумесяца. Далее уложить слой из кубиков хорошо охлажденной курятины, промазать майонезом, присыпать сырной стружкой, смазать раздавленным или натертым на мелкую терку чесноком и промазать опять майонезом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13599,'Теперь выложить слой из тертых желтков и промазать майонезом, прикрыть слоем из тертых белков (оставить часть для оформления) и тоже промазать тонким слоем майонеза.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13599,'Из оставленной морковки выложить апельсиновую «кожуру», а из белков – прожилки, убрать салат «Долька апельсина» с куриной грудкой  на пару часов (можно и больше) в холодильник. Приятного аппетита!',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13600,'Лист тонкого лаваша равномерно промазать мягким плавленым сыром, присыпать кубиками ветчины и рубленой зеленью петрушки, перьями зеленого лука, укропа, свернуть в трубочку или сделать конвертик.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13638,'В сотейнике нагреть растительное масло до 200°С.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13600,'Осталось только лаваш обжарить в хорошо прогретом масле со всех сторон, до образования привлекательной корочки и порционно разрезать. Рулетики из лаваша с ветчиной, зеленью и сыром готовы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13601,'Всыпать овсяные хлопья в чашу блендера, измельчить, перемешать с белками яиц и водой, дать тесту  постоять 10 минут. Включить прогреваться до 180 градусов духовку. Подготовить круглую форму, смазать маслом, переложить на дно тесто, сделать бортики, проколоть в нескольких местах вилкой (для предотвращения образования пузырей), поставить выпекаться на четверть часа в нагретую духовку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13601,'Разморозить и слегка отжать вишню, мед растопить на водяной бане, половину смешать с ягодами. Другую половину меда перемешать с протертым творогом и белком до однородной массы. Дать основе остыть, наполнить ее творожной массой, сверху уложить ягоды вишни, выпекать нежный тарт с вишней и творогом еще примерно полчаса. Приятного чаепития!',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13602,'Сахар и масло комнатной температуры взбить до состояния однородного крема, добавить взбитые яйца, перемешать, порциями влить молоко, перемешать. Перемешать разрыхлитель и просеянную муку, порциями смешать с яично-молочной смесью до получения теста, не липнущего к рукам, обернуть его пленкой, оставить в покое на полчаса.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13602,'Включить духовку, прогреть до 180 градусов. Поделить тесто на 20 одинаковых частей, каждую раскатать в тонкий пласт, проколоть вилкой, выпекать до кремового цвета, следить, чтобы не пригорели, поскольку пекутся они очень быстро. Подравнять каждый корж сразу после выпекания формой нужного диаметра, обрезки оставить для оформления, перед использованием хорошо зарумянить их в духовке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13602,'Взбить яйца с добавлением крахмала в однородную массу, осторожно смешать с чуть разогретым молоком, поставить варить на малый огонь до получения густой смеси примерно на 10 минут, дать остыть, добавить вареное сгущенное молоко. Взбить в охлажденной емкости белки в устойчивую пену, перемешать все вместе.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13602,'Собрать праздничный торт «Наполеон» с кремом из сгущенки в следующем порядке. Положить на плоское блюдо корж, промазать хорошо кремом, прикрыть другим коржом и т.д. пока не закончатся коржи, смазать бока торта и обсыпать крошкой из обрезков, сделать из нее же на верхнем корже по краю кольцо. Отправить торт ночевать в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13603,'Для начала мак нужно залить чуть горячей водой. Чтобы мак набух. Как залили мак водой, слега перемешиваем и убираем в сторону на 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13603,'Спустя 15 минут, сливаем воду в миску через сито, после чего в сито кладем мак, и слегка прижимаем его, чтобы вода до конца отсоединилась, и мак перекладываем в другую миску. (возможно это действие нужно будет повторить).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13603,'Раскатываем тесто, и на пласт теста добавляем мак, распределяем его по всей поверхности. Итак, лично у меня было 200 грамм мака, и 4 пласта теста. Мака мне хватило на все 4 пласта, так что рекомендую рассчитать ингредиенты именно для вас.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13603,'Как только распределили мак, тесто заворачиваем в рулет. Делим его на равные части. Перекладываем на противень и смазываем его растопленным сливочным маслом. Далее даем слойкам подойти (подняться), так как это слоеное дрожжевое тесто.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13603,'После как только слойки подошли, отправляем их в духовку при 180°С. На 15-25 минут. Лично у меня слойки запеклись за 30 минут. Все зависит от духовки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13603,'Достаем слойки и посыпаем их сахарной пудрой.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13604,'Разобрать кочан салата по листикам, каждый тщательно промыть и обсушить. Порезать слегка черствый багет кубиками по 1,5 см, налить на противень пару ложек масла, насыпать батон, перемешать, чтобы кубики все пропитались маслом.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13604,'Задвинуть противень примерно на 10 минут в прогретую до 200 градусов духовку, перемешать в процессе обжарки несколько раз. Обжарить подсоленные и поперченные куски рыбы на среднем огне с двух сторон (минуты по 3 с каждой).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13604,'Чеснок раздавить или натереть на очень мелкой терке до состояния кашицы. Смешать в миске горчицу, желтки, сок лимонный, чеснок и вустерский соус, приправить солью и перцем, перемешать еще раз. В полученную заправку, непрерывно взбивая венчиком, влить очень маленькими порциями оливковое масло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13604,'В результате должна получиться масса похожая по консистенции на майонез. Разрезать черри пополам, порвать листья салата, уложить их в салатник, добавить черри, и кусочки рыбы. Полить салат «Цезарь с лососем» с помидорами черри заправкой, верх посыпать остывшими сухариками и стружкой пармезана.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13605,'Подготовить рыбу. Очистить, выпотрошить, порезать кусочками. Луковицу среднего размера разрезать пополам, а потом на полукольца. Переложить все в миску, присыпать перцем, дробленым семенем кориандра, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13605,'Приготовить из сахара, яблочного уксуса, соли и воды смесь для маринования, залить рыбу, накрыть крышкой, домашняя селедка, маринованная в яблочном уксусе будет готова через сутки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13606,'Подготовить кусок мяса, порезать на небольшие кубики, переложить на разогретую с  маслом сковороду в один слой, присыпать кольцами лука, приправить солью и перцем, залить равномерно майонезом, запечь мясо в разогретой духовке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13606,'Когда блюдо покроется аппетитной красивой корочкой, убавить огонь и подержать его в духовке еще четверть часа. Достать сковороду, присыпать верх сыром, подать к столу прямо в сковороде. Хорошим дополнением к говядине по-испански с сыром станет рис под томатным соусом с зеленью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13607,'Взбить масло в воздушную массу, положить мед, взбить до однородности, добавить взбитые с ванилином яйца. Объединить со смесью всех сухих ингредиентов, перемешать до образования упругого теста.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13607,'Шар теста разделить на три части, завернуть каждый в пленку и дать полежать час в холодильнике. Раскатать одну часть в пласт толщиной в полсантиметра, вырезать формочкой разные фигурки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13607,'Выпекать нежные сахарные сердечки с медом минут 12-13 до золотистого цвета при температуре духовки 160 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13608,'Черешки сельдерея вымыть, очистить окунуть минут на пять в подсоленный кипяток, сразу обдать очень холодной водой. Также поступить с помидорами, надрезать у плодов верхушки и очистить от кожицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13608,'Порезать на одинаковые кубики сельдерей, помидоры, моцареллу. Чуть обжарить натертую перцем и солью рыбу в разогретом масле с двух сторон. Переложить рыбу в форму, присыпать кубиками сельдерея, сыра, а в конце помидорами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13608,'Поставить рыбу  в прогретую до 200 градусов духовку, держать форму до полного расплавления сыра около 10 минут. Рыба, запеченная с моцареллой и овощами, готова.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13609,'Включить для прогрева до 180 градусов духовку. Отделить тщательно белки, взбить в крепкую пену, добавить к желткам сахар растереть до изменения цвета смеси, он должен быть белый, осторожно соединить с белками. Добавить небольшими порциями просеянную муку, тесто перемешать до однородности.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13609,'Вылить тесто в подготовленную форму, поставить на полчаса в уже прогретую духовку, достать готовую бисквитную основу, дать остыть. Взбить, используя водяную баню желтки с сахарной пудрой, добавить разбухший желатин, растворить его, положить маскарпоне, все размешать. К белкам добавить ванильный сахар и взбить, перемешать с кремом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13609,'Полностью остывший корж разрезать на три части, смешать ликер и черный кофе, пропитать смесью коржи. Собрать бисквитный торт «',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13610,'Разогреть духовку до 180 градусов. Грецкие орехи выложить на противень и отправить в духовку на 8 минут. По истечении времени немного остудить, нарубить ножом на небольшие кусочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13610,'В тарелке соединить петрушку (2 ст. л.), зеленый лук (2 ст. л.), оливковое мало (1 ст. л.), цедра лимона, соль и перец (по 1/3 ч. л.) - перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13610,'Выложить стейки из красной рыбы на противень застеленный фольгой и обмазать со всех сторон приготовленной смесью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13610,'Духовку прогреть до 200 градусов и отправить запекаться рыбу на 17 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13610,'По истечении времени достать рыбу и остудить в течении 10 минут, а пока готовится рыба, приступаем к следующему шагу.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13610,'Болгарский перец очистить от семян и нарезать небольшим кубиком. В сковороде на растительном масле обжарить перец на сильном огне в течении 7 минут, перемешивая.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13618,'Всыпать сахарный песок, размешать и разлить в заранее стерилизованные банки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13638,'Небольшими порциями опустить макароны в масло.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13610,'В тарелку выложить обжаренный болгарский перец, добавить оливковое масло (1 ст.л.), сок лимона, мед, кокосовое масло, мелко нарезанную петрушку (2 ст. л.), красный жгучий перец, соль и черный перец (по 1/3 ч. л.), орехи - перемешать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13610,'Остывшую рыбу выложить на тарелку, поверх рыбы выложить приготовленную ореховую смесь.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13611,'Подготовленное мясо порезать на кусочки, отбить, картофель нашинковать тонкими кружочками, лук  полукольцами.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13611,'Выложить половину картофеля в смазанную маслом форму, присолить, поперчить, прикрыть слоем лука, а затем уложить мясо и опять слой картофеля. Смазать верх блюда майонезом, поставить мясо на 40 минут в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13611,'Для более аппетитной корочки можно подержать блюдо в духовке минут на 10 подольше, подавать свинину под картофелем с майонезом можно как горячей, так и холодной.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13612,'Нарезать укроп.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13612,'Натереть сыр на крупной терке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13612,'В глубокую тару разбить яйца, добавить молоко, соль, перец. Перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13612,'В противень уложить лаваш. Смазать сметаной, посыпать укропом и сыром. Повторить 8 раз.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13612,'Сверху полить яичной смесью.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13612,'Убрать в духовку, разогретую до 200°С на 30 минут. Сырный пирог из лаваша готов! Получается очень нежный и сочный пирог. Всем приятного аппетита! Больше кушайте, никого не слушайте!',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13613,'Расстилаем на противень пергаментную бумагу. Сверху на пергамент кладем рыбу и солим достаточно щедро (я использую крупную соль).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13613,'Добавляем перец и орегано (посыпаем снаружи и во внутрь рыбы).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13613,'Поливаем рыбу соком лимона и добавляем дольки лимона во внутрь рыбы и поверх рыбы.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13613,'Поливаем рыбу оливковым маслом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13613,'Запечатываем рыбу в пергаментную бумагу и кладем в разогретую духовку до 180-200 градусов на 30-35 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13613,'Достаем рыбку и срезаем ножницами верхнюю часть пергамента и ставим ее снова в духовку уже открытую на 10-15 минут. Рыба готова! Она будет сочной и одновременно с золотистой корочкой! Ниже ссылка на видеорецепт! Приятного аппетита!',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13614,'Разрезать каждый пряник вдоль на две части, бананы порезать кружочками. Добавить к сметане сахарную пудру и взбить, положить дробленые орехи, перемешать. Выстелить миску с плоским дном пленкой, края должны свисать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13614,'Окунуть каждый кусочек в сметану, уложить вплотную один к другому, промежутки заполнить крупной пряничной крошкой. Выложить на пряники слой из кружочков банана, прикрыть пряниками, далее опять положить бананы, присыпать слоем дробленых орехов, а затем опять положить слой из пряников, убрать пряничный тортик с банановой начинкой в холодильник.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13615,'Нарезать финики, смешать с изюмом и залить горячим крепким чаем. Дать постоять 25-30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13615,'Яйца взбить с сахаром, добавить разрыхлитель, имбирь, корицу и просеянную муку. Замесить тесто. Добавить чай с сухофруктами и все перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13615,'Разогреть духовку до 180°С. Выложить тесто в форму смазанную растительным маслом или застеленную пергаментом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13615,'Выпекать около 1 часа до готовности (проверить зубочисткой в центре кекса - она должна выходить сухой)',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13616,'Тыкву очистить, мякоть нарезать небольшими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13616,'Апельсин очистить от кожуры и нарезать дольками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13616,'Ингредиенты засыпать сахарным песком, оставить на ночь или на пять часов для пропитывания.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13616,'Поставить массу на огонь средней мощности, влить воду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13616,'Варить до загустения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13616,'Разложить в банки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13617,'Цитрусовые поварить в воде до размягчения кожицы.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13617,'Остудить, очистить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13617,'Половину цедры размолоть в блендере.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13617,'Мякоть нарезать кусочками среднего размера.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13617,'Ингредиенты выложить в кастрюлю, всыпать сахарный песок.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13617,'Прогревать на среднем огне до растворения сахара.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13617,'Затем долить воду, варить в течение часа.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13617,'Остудить и снова проварить.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13617,'Миндальные орешки измельчить, добавить к основной массе и перемешать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13619,'Апельсины или мандарины также обдать кипятком, нарезать дольками вместе с цедрой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13619,'Продукты перемешать с сахарным песком, поставить на тихий огонь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13619,'Массу довести до кипения, остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13619,'Через двенадцать часов прогреть, разлить в банки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13620,'Яблоки вымыть, разрезать, удалить сердцевину, мякоть нарезать пластинками толщиной в полсантиметра.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13620,'Очистить апельсин, убрать пленки, мякоть с кожурой нарезать кусочками.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13620,'Фрукты перемешать, всыпать сахар.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13620,'Дать постоять.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13620,'Поставить на плиту, влить воду, довести до кипения, варить пятнадцать или двадцать минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13620,'Пенку снять, варенье остудить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13620,'Проварить еще раз.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13621,'Взбить сахарную пудру с белками и несколькими капельками лимонного сока в воздушную массу.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13621,'Выпекать около часа при температуре духовки не более 100 градусов, отключить плиту, дать домашнему воздушному безе еще час остыть в духовке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13622,'Чеснок почистить, промыть холодной водой, разделить дольками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13622,'Стерилизовать небольшие банки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13622,'На дно емкостей положить по несколько лавровых листочков, по стручку жгучего перца чили, очищенного от хвостиков и семечек.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13622,'Наполнить банки зубчиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13622,'Влить кипящую воду, прикрыть, оставить на десять минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13622,'Воду слить.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13622,'В кастрюлю влить воду и оливковое масло, всыпать сушеные прованские травы, сахарный песок, соль.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13622,'Варить две или три минуты с момента закипания.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13622,'В каждую баночку влить уксус, а затем горячий маринад.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13622,'Закрутить крышки.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13622,'Банки перевернуть, укутать одеялом, оставить до остывания.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13622,'Хранить в подвале.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13622,'Закуску можно употреблять через две или три недели.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13623,'Очистить и вымыть чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13623,'Влить кипяток, через минуту жидкость слить, сполоснуть овощ холодной водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13623,'Острый перец нарезать кольцами.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13623,'В небольшой кастрюле вскипятить воду, влить уксус, всыпать специи, сахарный песок, соль и перец – по вкусу.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13623,'Маринад варить в течение минуты после закипания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13623,'Чеснок плотно уложить в банку.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13623,'Влить маринад.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13623,'Закрыть и поставить в холодильник на несколько дней.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13624,'Овощ обдать кипящей водой, снять шелуху.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13624,'Стерилизовать банки, сложить головки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13624,'Приготовить рассол из воды, сахарного песка, соли, перца-горошка, уксуса.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13624,'Подержать смесь на тихом огне пятнадцать минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13624,'Маринад немного остудить и теплым разлить в банки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13624,'Закрыть заготовки крышками, остудить при комнатной температуре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13624,'Поставить в прохладное место.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13625,'Смешать тертый сыр и натертый на мелкой терке чеснок, добавить майонез и хорошо перемешать еще раз. Подготовить перцы, срезать верхушку с хвостиком, вынуть все семена, часть нафаршировать сырной массой, добавить яйцо, заполнить оставшуюся часть сырной массой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13625,'Убрать болгарский перец с сырной начинкой и яйцом минимум на три часа в холодильник, достать порезать на диски по сантиметру шириной. Пикантная, сытная и красивая закуска для праздников и будней готова.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13626,'Яйца комнатной температуры соединить с солью взбить до пышности и изменения цвета.','https://vkuso.ru/data/cache/data/1f/e7337a17334d71f_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13626,'В массу постепенно в 3 приема добавить сахар, продолжая взбивать до пышности.','https://vkuso.ru/data/cache/data/71/27d65ebcf706371_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13626,'Добавить ванильный сахар и растопленное слегка остывшее сливочное масло и еще немного взбить до однородности.','https://vkuso.ru/data/cache/data/fc/3394756def8d4fc_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13626,'Муку смешать с разрыхлителем.','https://vkuso.ru/data/cache/data/84/8abdd8cddcb8884_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13626,'Постепенно в 3 приема просеять в массу, перемешивая сначала венчиком.','https://vkuso.ru/data/cache/data/27/37aae2c40530227_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13626,'Затем перемешивать ложкой. Тесто должно получиться очень вязкое и липкое.','https://vkuso.ru/data/cache/data/78/a65601a345b0d78_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13626,'Очистить яблоки от шкурки и сердцевины, нарезать кубиком и добавить к тесту.','https://vkuso.ru/data/cache/data/8c/a0865a218c38c8c_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13626,'Мелко нарезать сухофрукты (в рецепте курагу). Ввести все фрукты в тесто.','https://vkuso.ru/data/cache/data/f5/7211f7982d469f5_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13626,'Все хорошо перемешать.','https://vkuso.ru/data/cache/data/5c/db585afad8f2c5c_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13626,'Выложить тесто ложкой на противень, застеленный бумагой или ковриком для выпечки.','https://vkuso.ru/data/cache/data/db/caf6caa00c69cdb_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13626,'Выкладывать на расстоянии друг от друга, учитывая, что тесто увеличивается в размере при выпечке.','https://vkuso.ru/data/cache/data/40/8bbe5d03a906b40_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13626,'Выпекать 25 мин при 180 С в заранее разогретой духовке до готовности и подрумянивания. Готовность можно проверить зубочисткой.','https://vkuso.ru/data/cache/data/a4/cdee610b52c9aa4_434x295_notrise.jpg',12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13626,'Готовое печенье остудить.','https://vkuso.ru/data/cache/data/b6/ebb2b95c94546b6_434x295_notrise.jpg',13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13626,'Посыпать сахарной пудрой.','https://vkuso.ru/data/cache/data/2e/651c768fd10d82e_434x295_notrise.jpg',14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13627,'Манку сварить на молоке, добавить  взбитую с  маслом сметану и сахар, перемешать, дать крему хорошо остыть. Взбить миксером до однородной  массы  молоко с яйцами, солью, ванильным и обычным сахаром. Добавить порциями просеянную муку, тщательно перемешивая тесто после каждой порции.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13627,'Из полученного теста нажарить блины, каждый подрумянивать с двух сторон. Собрать оригинальный торт «Птичье молоко» из блинов на плоском блюде в следующем порядке: положить блин, хорошо смазать кремом, положить следующий, все повторить до окончания блинов. Последний блин не смазывать, а лишь равномерно облить слегка остывшей глазурью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13628,'Печень нарезать не крупными кусочками и обжарить на сильном огне в разогретой сковороде с растительным масле до образования корочки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13628,'Нарезанный лук и натертую на крупной терке морковь слегка пассировать на той же сковороде добавив еще кусочек сливочного масла. Добавить чеснок и обжаривать еще пару минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13628,'Наполняем горшочки: несколько ложек овощей, слой печени и хорошо промытая гречка. Примерно по 3 ст.л. на горшочек. Сверху кладем по небольшому кусочку лаврового листа, солим и заливаем кипятком. Воды должно быть примерно на палец выше уровня гречки',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13628,'Готовим в течении 30 минут при 180°С.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13629,'В кастрюлю налить воды, отправить в нее куриные ножки. Ставим на огонь и доводим до кипения, затем варим 15 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13629,'По истечении времени добавить картофель, репчатый лук и морковь нарезанные кусочками (размер кусков не имеет смысла, их  нужно будет измельчать в конце). Добавить лавровый лист и доводим до кипения. Снова варим 15 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13629,'Спустя 15 минут достать из кастрюли куриные ножки, немного остудить. Лавровый лист выкинуть. Все содержимое кастрюли измельчить погружным блендером.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13629,'Остывшие куриные ножки очистить от кожи и отделить мясо от костей.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13629,'Добавляем соль, перец, хмели-сунели, петрушку, зеленый лук и консервированный зеленый горошек.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13629,'Снова измельчаем все при помощи погружного блендера. Накрываем кастрюлю крышкой, доводим до кипения, варим 10 минут на медленном огне.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13630,'Открыть консервы, слить сок, размять рыбу вилкой, нарезать картофель и помидоры кубиками, яйца протереть на крупной терке, лук нашинковать мелкими кубиками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13630,'Смешать все в салатнике, подсолить, приправить салат майонезом. Выложить салат полусферой на блюдо, оформить как футбольный мяч, используя зелень, кусочки маслин и белок яйца.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13631,'Порезать рыбу на кусочки, зелень мелко нашинковать, протереть сыр на средней терке. Смешать для заливки в миске сыр и зелень, добавить сливки.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13631,'Уложить в форму кусочки рыбы, приправить солью, черным перцем, залить подготовленным соусом, поставить в духовку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13631,'Тилапия под сливочным соусом с сыром будет готова примерно через полчаса, подавать блюдо лучше горячим, на стол ставить прямо в форме.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13638,'Как только макароны подзолотились, достать их шумовкой и выложить на салфетки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13632,'Протереть сквозь сито отварной картофель, добавить мелко порезанный сыр, чуть муки и пару желтков, все хорошо перемешать, скатать из массы небольшие шарики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13632,'Обвалять крокеты из картофеля с сыром в муке, окунуть во взбитый белок, запанировать, обжарить шарики в разогретом до 170 градусов масле до хрустящей красивой корочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13633,'Положить в чашку блендера сахар, рикотту, яйцо, налить молоко, взбить. Застелить пергаментом форму, смазать маслом, залить творожную массу, дать постоять. Перемешать в миксере желтки, всыпать сахар с ванилином, хорошо взбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13633,'Измельчить до состояния пюре банан, смешать с порубленными орехами, объединить с желтками, перемешать. Добавить просеянный с мукой разрыхлитель, тщательно перемешать, добавить взбитые до устойчивых пиков белки, хорошо перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13633,'Выложить на творожную массу в форму тесто, разровнять, поставить пирог на треть часа в духовку с температурой чуть ниже 190 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13633,'Расстелить на столе полотенце, насыпать слой сахарной пудры, перевернуть на него осторожно бисквит, свернуть аккуратно в трубочку творожной стороной внутрь, дать остыть, украсить рулет из бананового теста с творожной начинкой, как подскажет фантазия.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13634,'Включить и прогреть духовку до 150 градусов. К просеянной муке с разрыхлителем, содой и солью добавить кусочки сухофруктов, орехи, сахар, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13634,'Взбить яйца с добавлением ванили до увеличения объема примерно в два раза, масса должна побелеть. Объединить яичную смесь с мучной смесью, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13634,'Вылить тесто в застеленную пергаментом форму, разровнять, чтобы не было пустот, поставить кекс из сухофруктов с грецкими орехами запекаться на 75 минут до золотисто-коричневого цвета.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13635,'Очистить головки чеснока от шелухи, вымыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13635,'Залить горячей водой на час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13635,'Тару стерилизовать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13635,'Выложить чеснок в банки, добавить вишневые и смородиновые листочки, укроп.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13635,'Приготовить маринад из воды, уксуса, соли.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13635,'Жидкость довести до кипения, залить в банки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13635,'Накрыть тару тканью на пять дней, температура воздуха не должна превышать десяти или пятнадцати градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13635,'Закуску можно употреблять сразу или поставить в холодильник.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13636,'Приготовить из муки, одного яйца, молока и соли тесто жидкой консистенции, хорошо прогреть сковороду, смазать кусочком сала или маслом, испечь обычные блинчики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13636,'Обжарит прокрученное мясо, отдельно мелкие кубики лука, соединить их и еще раз прокрутить. Добавить к мясному фаршу порубленные яйца, приправить солью, черным перцем, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13636,'Положить по ложке начинки на середину каждого блинчика, завернуть в форме конверта. Обжарить вкусные домашние блинчики с мясным фаршем с обеих сторон.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13637,'Воду влить в глубокую емкость, довести до кипения на максимальном огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13637,'Головки чеснока очистить, но не разбирать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13637,'Вымыть холодной водой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13637,'Головки сложить в кастрюлю с кипящей водой, через две минуты откинуть на дуршлаг и сразу же поместить в холодную воду.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13637,'Свеклу вымыть, очистить, нарезать брусками или произвольными кусочками.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13637,'Разложить овощи в банки, их лучше распределять слоями.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13637,'Приготовить маринад: довести до кипения воду (1,5 л), уменьшить огонь до среднего.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13637,'Всыпать соль, сахар, гвоздику, перец-горошек.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13637,'Варить две минуты.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13637,'Снять жидкость с огня, влить уксус.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13637,'Перемешать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13637,'Готовый рассол разлить в банки, остудить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13637,'Закатать металлическими крышками или закрыть полиэтиленовыми.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13637,'Подержать заготовки в темном месте две или три недели при комнатной температуре.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13637,'Поставить в холодильник.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13638,'Отварить макароны в подсоленной воде, согласно инструкции на упаковке.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13638,'Откинуть на дуршлаг и обдать прохладной водой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13638,'Дать стечь лишней жидкости.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13638,'Перемешать макароны со специями. Чипсы из макарон готовы!',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13639,'Прокрутить кукурузные палочки на мясорубке, тщательно перемешать со сгущенным молоком. Сделать небольшие лепешечки, положить в середину по орешку, сформовать шарики, обвалять пирожное в стружке кокоса, сложить на широкое блюдо, поставить десерт на час в холодильник.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13640,'Слегка взбить в маленьком салатнике яйцо с добавлением воды, сыр порезать на кусочки. Все оставшиеся ингредиенты смешать в другой посуде.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13640,'Окунуть каждый кусочек в яйцо, переложить в сухую смесь, обвалять со всех сторон. Раскалить в сковороде масло, обжарить сыр в панировке до соломенного цвета.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13640,'Переложить закуску из моцареллы в панировке на несколько слоев бумажных полотенец для удаления излишка масла.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13641,'Нарезать лук и пассеровать на разогретой сковороде затем добавить чеснок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13641,'Через пару минут высыпать пасту, вылить воду и добавиться тунца. Тушить под закрытой крышкой 10 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13641,'Добавить в пасту зеленый горошек и сливки. Когда они подогреются всыпать натертый сыр, поперчить и посолить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13642,'Протереть яйца, сыр и хорошо охлажденное масло, добавить чеснок, пропущенный через пресс, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13642,'Приправить еврейскую сырно-чесночную закуску белым перцем, солью, сдобрить майонезом,  дать постоять в холодильнике, подавать с тостами или крекерами.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13643,'Муку смешиваем с разрыхлителем.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13643,'Снимаем цедру с апельсина и выдавливаем с него сок.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13643,'Смешиваем в емкости цедру, апельсиновый сок и сахар. Когда сахар растворится добавляем соль, растительное масло, уксус и постепенно вводим муку. Замешиваем тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13643,'Помещаем тесто в форму и отправляем в духовку на 180 градусов примерно на 40 минут.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13644,'Воду подогреть, растворить в ней соль (1,5 ч. л).',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13644,'В миску положить муку, разбить яйцо (1 шт), влить растительное масло (20 мл) и соленую воду. Замесить тесто.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13644,'Добавить в тесто растительное масло (1 ч. л.), обмазать со всех сторон. Накрыть пленкой и оставить при комнатной температуре на 30 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13644,'Очень тонко раскатать тесто. Растопить сливочное масло и смазать им всю поверхность раскатанного теста (масла будет много, но на тесто вылейте все).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13644,'Сверните тесто в плотный рулет и нарежьте шириной 4 см. Каждый кусочек немного приплюснуть ладонью. Выложите тесто на тарелку и отправьте в морозильную камеру на 10 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13644,'Готовим начинку: нарезать лук очень мелким кубиком, смешать с фаршем, добавить растительное масло (2 ст. л.), черный перец, соль и зиру - перемешать.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13644,'Достаем тесто из морозилки и раскатываем кружочки, выкладываем начинку и лепим треугольную самсу. Выкладывать швом вниз на застеленный пергаментом противень.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13644,'Желток отделить от белка, смазываем желтком самсу и посыпаем кунжутом.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13645,'В миске смешать яйцо, соль, сахар и ванильный сахар. Добавить муку и замесить тесто в крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13645,'Добавить сливочное масло и замесить тесто руками в шар. Накрыть пленкой и убрать в холод на 20 минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13645,'Спустя 20 минут достаем тесто из холодильника, немного присыпать мукой и раскатать тесто толщиной 0,5 см, вырезать формочкой тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13645,'Противень застелить бумагой и выложить печенье. Разогреть духовку до 180 градусов, выпекаем до золотистого цвета (около 15-20 минут).',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13646,'Смешать все в большой кружке и выпекать в микроволновке 3-5 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13647,'Нарезать чеснок, лук, болгарский или Чили перец и кинзу на кусочки.','https://vkuso.ru/data/cache/data/5d/d2e2de6c30ca85d_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13647,'В чашу блендера налить половину бульона или воды, добавить все нарезанные овощи и измельчить около 10 сек.','https://vkuso.ru/data/cache/data/06/a255c2ec4f7b206_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13647,'Влить оставшийся бульон и еще раз все измельчить около 10 сек.','https://vkuso.ru/data/cache/data/07/9a77f70ffa1d207_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13647,'Промыть рис, максимально слить из него всю воду, можно даже немного обсушить.','https://vkuso.ru/data/cache/data/fe/dcac8852bb15ffe_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13647,'Обжарить на сковороде промытый рис на растительном масле в течение 1 мин помешивая, рис немного изменит цвет, пропитается маслом и станет прозрачным.','https://vkuso.ru/data/cache/data/06/d0ac0a3f6d80706_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13647,'Залить рис прямо в сковороде подготовленным соусом, посолить и поперчить по вкусу.','https://vkuso.ru/data/cache/data/68/774d182ef096868_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13647,'Накрыть крышкой и держать на слабом огне до полной до готовности.','https://vkuso.ru/data/cache/data/c0/9f764649214a7c0_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13647,'Когда рис впитает всю жидкость и будет полностью готов, крышку снять.','https://vkuso.ru/data/cache/data/5e/52a53907d9f8c5e_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13647,'Рис перемешать и можно подавать, украсив блюдо по своему вкусу.','https://vkuso.ru/data/cache/data/92/180798f4529c592_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13648,'Слегка подогреть кефир, добавить крупное яйцо, добавить соду, соль с сахаром, размешать. Полученную жидкость смешать с мукой до образования «жидкой сметаны».',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13648,'Полученную смесь, при постоянном помешивании, заварить кипящим молоком, влить масло перемешать. Выпекать блинчики «Ажурные» на хорошо прогретой сковороде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13649,'Вымыть овощи, снять верхний слой шелухи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13649,'Стерилизовать банки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13649,'В воду влить уксус и соль, залить рассолом чеснок.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13649,'Хранить закуску в темноте в течение полугода.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13650,'Чеснок разделить на зубчики, очистить, облить кипящей водой, обсушить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13650,'Стерилизовать банки, выложить овощ.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13650,'В кипящую воду добавить лавровый лист, перец-горошек, сахарный песок, соль, тимьян.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13650,'Очистить и натереть имбирный корень, добавить в маринад.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13650,'Ввести уксус.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13650,'Варить смесь в течение двух минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13650,'Рассол разлить в банки, закатать металлическими крышками.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13650,'Емкости перевернуть, укутать пледом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13651,'Стрелки чеснока вымыть, высушить, нарезать кусочками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13651,'Раскалить на сковороде растительное масло, стрелки обжарить в течение семи минут.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13651,'Влить соевый соус, уксус, перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13651,'Всыпать сахарный песок, паприку, перец-горошек красный и черный, молотый кориандр.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13651,'Добавить нарезанные зубчики чеснока.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13651,'Все вместе потушить пять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13651,'Стрелки выложить в банку, влить масло со специями со сковороды.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13651,'Емкости стерилизовать в кастрюле в течение десяти минут, закатать, подержать в темноте в течение недели.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13652,'Из слив удалить косточки, всыпать сахар и оставить для пропитывания.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13652,'Массу поставить на огонь, подлить немного воды.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13652,'Довести до кипения, варить десять минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13652,'Сливы превратить в пюре с помощью блендера или протереть сквозь сито.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13652,'Соус еще раз поставить на огонь, варить до тех пор, пока масса не уменьшится в три раза.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13652,'Добавить чеснок, рубленую зелень кинзы, болотной или перечной мяты, красный острый перец, хмели-сунели.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13652,'Варить пятнадцать минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13652,'Соус разлить в стерильные банки, закатать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13653,'Стебли омбало, зерна укропа, чабрец, кориандр и лавровый лист выложить в кастрюлю.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13653,'Зеленые сливы вымыть, добавить к зелени, влить воду, поставить на огонь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13653,'Довести массу до кипения, огонь убавить, варить до мягкости слив.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13653,'Соус остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13653,'Сливы перетереть в кашицу через сито.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13653,'Долить сливовый отвар, всыпать соль, сахар, мелко нарезанный острый перец.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13653,'Варить до густоты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13653,'Добавить чеснок, варить одну минуту.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13653,'Массу разлить в стерильные банки и укупорить.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13654,'Включить для прогрева до 200 градусов духовку. Растереть с сахаром яйцо, добавить жидкое сливочное масло и сахарную пудру, очень хорошо все перемешать. Влить осторожно молоко, частями, с перемешиванием, всыпать смесь муки с разрыхлителем до образования тягучего и густого теста. Прикрыть миску пленкой, убрать на полчаса в холод.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13664,'Варить десять минут, всыпать рубленую зелень, потушить пять минут и остудить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13654,'Достать миску с тестом, добавляя маленькими порциями муку, вымесить его до гладкости и эластичности, раскатать в сантиметровый пласт и сформовать колечки пончиков. Выстелить противень пергаментом, переложить заготовки пончиков, задвинуть на треть часа в духовку. Пончики  должны увеличиться в размере, приобрести красивый «загар», противень достать и дать пончикам остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13654,'Для глазури нагреть кусочки шоколада с небольшим количеством воды до состояния однородной пасты. Добавить размягченное хорошее сливочное масло вместе с сахарной пудрой, растереть до однородного состояния.  Полученную массу переложить в широкую миску, чтобы было удобно погружать в нее пончики. Готовый американские пышные пончики в глазури разложить на большом блюде и присыпать стружкой из кокоса, или цветной присыпкой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13655,'Сливу перебрать, вымыть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13655,'Залить плоды водой, поставить на огонь.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13655,'Довести до кипения, пламя убавить, варить в течение двадцати минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13655,'Удалить косточки, кожицу, мякоть перетереть.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13655,'Всыпать сахарный песок, соль, кориандр, молотый перец.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13655,'Массу перемешать, варить полчаса, помешивать, чтобы не пригорела.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13655,'Очистить от семян острый перец, вместе с зеленью и чесноком пропустить через мясорубку.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13655,'Добавить к сливам, варить десять минут.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13655,'Готовый соус разлить в банки, добавить растительное масло и закатать.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13656,'Фарш, перемешать со специями, молотой петрушкой, пармезаном и чесноком. Переложить приготовленный фарш на сковороду,  добавить к нему фарш из говядины, чеснок, лук, поджарить до золотистого цвета.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13656,'Порезать помидоры, высыпать их в сковороду к мясу, добавить томатный соус и пасту, добавить воды, все перемешать. Заправить итальянской приправой, базиликом, рубленой петрушкой, сахаром, фенхелем, подсолить, поперчить. Смесь перемешать, тушить, накрыв крышкой, часа полтора на слабом огне, помешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13656,'В широкой кастрюле довести до кипения подсоленную воду, отварить в течении 10 минут листы лазаньи слить воду, промыть листы под холодной проточной водой. Перемешать в миске яйца, порубленную петрушку и творожный сыр мягкой консистенции, подсолить половиной чайной ложкой соли.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13656,'Прогреть духовой шкаф чуть ниже 200 градусов. В глубокий противень налить полтора стакана соуса, затем положить листы лазаньи (6 штук), добавить половину творожной смеси. Положить на нее 1/3 часть всей моцареллы, порезанной ломтиками.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13656,'Полить остатками соуса, присыпать пармезаном. Слои повторить еще раз. В завершении, положить ломтики моцареллы, присыпать стружкой пармезана. Тщательно запаковать противень листом фольги.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13656,'В уже прогретую духовку задвинуть противень примерно на 25 минут, затем удалить фольгу и выпекать еще столько же. Достать самую вкусную домашнюю лазанью с мясным фаршем из духовки,  дать четверть часа остыть и подать к столу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13657,'К готовому фаршу добавить мелко порубленный лук, размоченный и отжатый хлеб, натертый в кашицу чеснок, перемешать, приправить перцем, солью, нашинкованной зеленью, хорошо перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13657,'Колобок фарша тщательно отбить об разделочную доску до плотного состояния. Сформовать небольшие вкусные котлетки, обсыпать их мукой, обжарить до золотистого колера.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13657,'Для соуса обжарить тертую морковь с кубиками лука до красивого цвета, добавить смесь сметаны и молока, немного воды, высушенную зелень, приправить перцем и солью. Подать мясные котлетки с молочным соусом и любым выбранным гарниром.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13658,'Взбить венчиком яйца комнатной температуры с сахаром (желательно мелким), всыпать порошок какао, осторожно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13658,'Смешать муку с разрыхлителем, добавить по частям, взбитые  яйца, очень хорошо перемешать до образования густого теста. Влить в тесто молоко и масло, тщательно размешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13658,'Перелить тесто в подготовленную форму, готовить шоколадный бисквит к чаю на мощности 850 около 4 минут, а на 1000 будет достаточно и 3,5 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13665,'Мягкое сливочное масло растереть с творогом при помощи вилки. Масса должна стать однородной.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13659,'Слегка подогреть молоко, положить дрожжи, всыпать сахар и чуть муки, перемешать, оставить в теплом месте. Когда дрожжи заиграют, и на поверхности появится вспененная шапочка добавить разболтанное вилкой яйцо, перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13659,'Смешать молоко, муку, соль, объединить с опарой, вымесить тесто, влить жидкое сливочное масло комнатной температуры, перемешать в однородную липкую массу (муки больше добавлять не надо), оставить на пару часов в тепле, прикрыв тканью.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13659,'Для приготовления крема, подогреть слегка молоко, всыпать крахмал, добавить сахар, желтки, ванильный и обычный сахар, перемешать, сварить до густого состояния. Дать крему остыть, смешать с маслом, хорошо взбить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13659,'Присыпать стол тонки слоем муки, разделить  тесто на 15 частей. Каждый кусочек раскатать в овальный сочень, мысленно разделить его пополам, отступить сантиметра 3 от края и выложить на одну половину примерно чайную ложку крема, прикрыть другой половиной теста, тщательно залепить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13659,'Переложить на противень, дать постоять треть часа, накрыв тканью в тепле. Смазать верхушки воздушных булочек с молочным кремом желтком, выпекать четверть часа в прогретой до 180 градусов духовке до золотисто-соломенного цвета. Достать противень, накрыть льняным полотенцем, дать выпечке «отдохнуть» четверть часа, присыпать через ситечко сахарной пудрой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13660,'В чашу блендера всыпать сахар, влить сгущенку, вбить яйца, добавить сметану, перемешать, влить погашенную уксусом соду, небольшими порциями всыпать муку, перемешать в однородную массу, напоминающую сметану.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13660,'Чернослив тщательно промыть, если он сильно пересушен, то залить минут на 10-15 кипятком, порезать на длинные полоски, смешать с тестом. В форму залить половину теста, выпекать примерно 20 минут в заранее прогретой до 180 градусов духовке, после его готовности выпечь второй корж, дать им хорошо остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13660,'На плоское блюдо положить корж, щедро пропитать кремом. Порезать другой на квадратики 3х3 см, окунуть каждый в крем, выложить горкой на первый корж, пересыпая слои мелко порубленными орехами, залить все промежутки кремом. Убрать домашний торт «Айсберг» с черносливом на пару часов в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13661,'Обжарить порезанный на маленькие кубики лук, смешать с фаршем, посолить, поперчить, комок фарша хорошо отбить.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13661,'Приготовить из взбитого яйца, стружки сыра и сметаны начинку для мясных кексов,  посолить, поперчить, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13661,'Разложить тесто по формочкам, сделать в середине каждого кекса углубление, заполнить его  сырно-яичной смесью, выпекать полчаса при 200 градусах.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13661,'Дать мясным кексом с яично-сырной начинкой слегка остыть, вынуть из формочек, подать к столу с любым гарниром или салатом.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13662,'Для начала нарежем баклажаны, выложим в дуршлаг или в посуду для сушки салатов.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13662,'Затем посыпаем солью и оставляем на 15-20 минут, чтобы баклажаны отдали влагу.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13662,'Тем временем порежем другие овощи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13662,'Далее разогреваем 2 сковородки, заливаем масло. В одну выдавим чеснок, слегка обжариваем, добавляем помидоры, посолим.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13662,'Во второю добавим лук, перец, баклажаны и также обжариваем все до готовности.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13662,'Далее готовые помидоры добавляем к овощам. Также добавим паприку, черный перец и хлопья острого перца.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13662,'Через пару минут добавляем томаты в собственном соку и томатную пасту. Перемешиваем и оставляем на минут 5. По готовности добавляем зелень.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13663,'Удалить косточки из плодов, всыпать соль, дать постоять.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13663,'Массу поставить на плиту, довести до кипения, варить пять минут на тихом огне.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13663,'Измельчить зелень и перец чили.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13663,'Сначала в общую массу всыпать перец, через пять минут – остальные ингредиенты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13663,'Соус перемешать, огонь погасить.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13663,'Всыпать давленый чеснок, превратить массу в пюре при помощи блендера.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13664,'Вынуть косточки из вишен, всыпать сахар и соль, довести до кипения, варить пять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13664,'Всыпать нарезанный острый перец и чеснок, сушеные травы.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13664,'Массу превратить в пюре при помощи блендера.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13665,'Отдельно соединить сахарный песок, муку, соль, ванилин, разрыхлитель.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13665,'Перемешать сухие компоненты с масляной смесью.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13665,'Тесто завернуть в пленку и поставить на полчаса в холод.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13665,'Стол или другую рабочую поверхность присыпать мукой.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13665,'Раскатать лепешку, разрезать ее на секторы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13665,'Каждый треугольник свернуть в виде рулета, но без начинки.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13665,'Пекарскую бумагу смазать осветленным растительным маслом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13665,'Изделия смазать взбитым яйцом.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13665,'Выпечь в духовке, температура – 180 градусов, время выпекания – 20 минут.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13666,'Мясо порезать на небольшие кусочки, чуть обжарить, добавить взбитые с майонезом яйца, перемешать, смеси дать схватится, но не зажарится. Выключить плиту, добавить в сковороду нарезанную зелень, помидоры, чеснок, сдобрить солью и перцем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13666,'Раскатать готовое тесто, разровнять по его поверхности начинку, завернуть в трубочку, верх рулета из слоеного теста с копченым мясом смазать взболтанным с чайной ложечкой воды желтком, выпекать полчаса при 180 градусах.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13667,'Просеять муку, смешать с парой яиц, стаканом молока, парой столовых ложек сметаны и столовой ложкой сливочного масла, должно получиться довольно крутое тесто. Разделить все тесто на 20 кусочков одинакового размера, раскатать в круглую основу для шаньги (чуть больше 5 см в диаметре), сформовать сантиметровые бортики.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13667,'Для начинки вареный картофель растолочь, перемешать с маслом, молоком, сметаной и яйцами. Положить по паре ложек начинки в середину каждого кусочка основы, смазать смесью яйца со сметаной, выпекать домашние шаньги в духовке до красивого цвета при 250 градусах. Готовую выпечку смазать хорошим сливочным маслом, подать к столу в горячем виде.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13668,'Ягоды перебрать, переложить в кастрюлю, влить полстакана воды, дать прокипеть. Желатин залить водой согласно инструкции на упаковке. Размягченные ягоды протереть сквозь сито всыпать сахар, тщательно перемешать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13668,'Желатин распустить на водяной бане, смешать с пюре из ягод, дать полностью остыть. Взбить в миксере на малых оборотах в достаточно устойчивую пену. Добавить тоненькой струйкой сгущенку, хорошо взбить, разложить десертное суфле из ягод по формочкам, убрать на холод для полного застывания.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13669,'Сливочное масло или маргарин растопить, добавить сметану, соль, муку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13669,'Замесить гладкое тесто, положить его в холод.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13669,'Для приготовления начинки перемешать творог с сахарным песком, ванилином, вбить яйцо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13669,'Вынуть тесто из холодильника, разделить на четыре части, каждую раскатать в виде круглой лепешки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13669,'Разрезать на секторы.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13669,'Выложить начинку на широкую сторону, прижать, скрутить рулеты.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13669,'Печь при температуре 180 градусов, время – 20 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13670,'Изюм залить кипящей водой на десять минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13670,'Жидкость слить, продукт обсушить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13670,'Разморозить тесто при комнатной температуре.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13670,'Сухой жирный творог размять вилкой.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13670,'Можно использовать домашний продукт.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13670,'Вбить яйца, всыпать ванилин, сахар, лимонную цедру.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13670,'Вместо ванильного сахара из пакетика можно использовать ванильную эссенцию.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13670,'Добавить изюм и перемешать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13670,'Оттаявшее тесто развернуть, раскатать и намазать тонким слоем творожной массы, оставить край в два сантиметра.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13670,'Свернуть рулет, нарезать небольшими кусочками по четыре или пять сантиметров.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13670,'Пекарскую бумагу смазать маслом, выложить рулеты швом вниз.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13670,'Перемешать желток с молоком, смесью смазать изделия, поставить в духовку.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13670,'Печь при средней температуре.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13671,'В глубокую чашу добавить муку, соль, растительное масло и горячую воду. Замешать тесто.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13671,'Дать тесту отдохнуть 20 минут под пищевой плёнкой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13671,'Обмять тесто и сформировать колбаску.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13671,'Разделить ее на 4 равные части, из которых сформировать шарики.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13671,'Раскатать каждый шарик на тонкие, круглые лепешки толщиной 3-5 мм.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13671,'Обжарить лепешки на разогретой сковороде.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13671,'Сначала с одной стороны до золотистости, затем с другой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13671,'Перевернуть лепёшку ещё один раз и подождать, пока она надуется и сформируется кармашек.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13671,'Затем обжарить ещё по 30 секунд с каждой стороны. Пита готова. Получаются вкуснейшие хлебные лепешки. Магазинный хлеб не может сравниться с этой свежей выпечкой. Всем приятного аппетита! Больше кушайте, никого не слушайте!',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13672,'Замесить тесто. Перемешать молоко, муку, маргарин, сахар, соль и дрожжи. Растереть для начинки сахар с творогом, добавить яйцо, тщательно перемешать. Раскатать пласт теста, сделать, не задевая середины, на краях «бахрому», выложить на нее начинку, прикрыть внахлест разрезанными полосками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13672,'Хорошо защипать края, дать постоять плетенке из дрожжевого теста с начинкой из творога треть часа, прикрытой льняным полотенцем. Смазать верх плетенки разболтанным желтком, отправить на треть часа запекаться при температуре 180 градусов.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13673,'Творог протереть через сито (можно дважды пропустить через мясорубку или протереть при помощи блендера) и добавить к нему масло.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13673,'В сотейнике смешать вместе: яйца, сахар, ванилин и сливки. Поставить на огонь довести до кипения постоянно помешивая. И не прекращая взбивать венчиком варить на маленьком огне, пока сливки не загустеют, 4-5 минут. Снять с огня и дать слегка остыть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13673,'В творожно-масляную смесь добавить цитрусовые цукаты, изюм и орехи. Перемешать и добавить под остывший заварной крем. Все тщательно перемешать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13673,'Выложить внутреннюю часть пасочницы влажной марлей. Это нужно для того, чтобы пасха легко вынулась из формы. Очень плотно заполнить творожной массой, прикрыть небольшим блюдцем, поставить сверху лёгкий гнёт и поставить в холодильник на 10-12 часов. Вынуть пасху из холодильника, перевернуть на тарелку, снять пасочницу. Аккуратно снимаем марлю. Красавица пасха готова.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13674,'Смешиваем муку, сахар, соль и дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13674,'Делаем в сухих ингредиентах углубление, вливаем воду и растительное масло (немного масла оставим).',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13674,'Замешиваем тесто. Тесто получается не густым, вымешивать его нужно руками, предварительно смазанными растительным маслом (муку подсыпать не нужно). Тесто накрываем полотенцем и оставляем на расстойку на 60 мин.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13674,'Мелко нарезаем оливки (черные, зеленые).
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13674,'По истечению 60 мин, вмешиваем в тесто подготовленную начинку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13674,'Руки смазываем растительным масло и раскладываем тесто по формам. Даем булочкам подойти в течении 30-40 мин.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13674,'Отправляем в духовку на температуру 200 градусов примерно на 30-35 минут, ориентируйтесь по своей духовке.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13674,'Готовим смесь, для смазывания булочек. Измельчаем оставшиеся зелень и чеснок, добавляем к ним растительное масло и хорошо перемешиваем.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13674,'Как только достали булочки из духовки, еще горячими, смазываем их приготовленной смесью.
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13675,'Открыть банку консервированных ананасов. Сок из банки плюс любой натуральный сок, залить желатином, дать постоять около часа или чуть меньше.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13675,'Положить в блендер сметану, творог, влить сгущенку, взбить. Емкость с желатином нагреть на небольшом огне, но не кипятить, а лишь перемешивая растворить желатин в соке.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13675,'Смешать желатиновый «сироп» с творожной смесью, добавить кубики ананаса. Разлить десерт «Старая Рига» из творога в формочки, убрать на пару часов в холодильник и можно дегустировать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13676,'Молоко подогреть, ввести сахарный песок и дрожжи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13676,'Смесь должна постоять.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13676,'Сырое куриное яйцо взбить с солью, влить готовую смесь в дрожжи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13676,'Растопить и немного остудить сливочное масло.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13676,'Просеять муку, ввести в нее дрожжевую смесь.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13676,'Замесить тесто.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13676,'Влить тонкой струйкой топленое масло, перемешивать десять минут. Масса должна отставать от посуды.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13676,'Накрыть массу полотенцем, оставить тесто на полтора часа.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13676,'Растереть до однородности творог, всыпать сахар, вбить желток, всыпать ванилин.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13676,'Перемешать.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13676,'Разделить тесто пополам, раскатать в круглые лепешки, разрезать на шесть секторов каждую.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13676,'Выложить творожную начинку на широкую часть.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13676,'Свернуть рулеты, края защипать.',NULL,14);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13676,'Противень застелить пергаментом.',NULL,15);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13676,'Выложить изделия, дать постоять под пленкой в течение сорока минут.',NULL,16);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13676,'Смазать яйцом, поставить в духовку, печь при температуре 180 градусов.',NULL,17);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13677,'Мягкое сливочное масло растереть с творогом до однородного состояния.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13677,'Всыпать в кефир соль, пищевую соду, влить в творожную смесь, добавить муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13677,'Пластичное тесто разделить пополам, скатать в шары, завернуть в пленку и положить в холодильник.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13677,'Очистить от кожуры и семенных коробочек яблоки.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13677,'Мякоть нарезать толстыми дольками, присыпать сахаром, оставить на 20 минут для пропитывания.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13677,'Раскатать тесто в лепешку в три миллиметра толщиной, разрезать на треугольники.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13677,'Положить по кусочку сладкого яблока, завернуть.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13677,'Время выпекания – десять минут, температура – 180 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13678,'Творог перетереть через сито.','https://vkuso.ru/data/cache/data/80/01ab9eae02b2f80_434x295_notrise.jpg',1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13678,'Положить в творог сливочное масло, нарезанное на кусочки, добавить сахар, ванильный сахар и разрыхлитель.','https://vkuso.ru/data/cache/data/91/49c47a002cfeb91_434x295_notrise.jpg',2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13678,'Просеять в массу муку.','https://vkuso.ru/data/cache/data/00/392f6446f3da700_434x295_notrise.jpg',3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13678,'Перемешать все сначала ложкой, затем перетереть руками в крошку и вымесить нежное податливое тесто.','https://vkuso.ru/data/cache/data/26/bcfa32c132e7126_434x295_notrise.jpg',4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13678,'Тесто положить в пакет и убрать в холодильник на 10 минут.','https://vkuso.ru/data/cache/data/7e/7ed87a1071bc77e_434x295_notrise.jpg',5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13678,'Через 10 мин присыпать стол и остывшее тесто мукой, раскатать в пласт толщиной около 4 мм.','https://vkuso.ru/data/cache/data/3b/51e9cdd23a7b13b_434x295_notrise.jpg',6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13678,'Вырезать любой формочкой печенье, обрезки теста соединить, снова раскатать и вырезать печенье еще.','https://vkuso.ru/data/cache/data/d1/bd78c5876cf60d1_434x295_notrise.jpg',7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13678,'Присыпать печенье сверху сахаром, по желанию можно присыпать его еще маком и/или корицей.','https://vkuso.ru/data/cache/data/4e/61f6f738c50c34e_434x295_notrise.jpg',8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13678,'Выпекать печенье в заранее разогретой до 180°С духовке около 15 мин до готовности и легкого подрумянивания.','https://vkuso.ru/data/cache/data/8d/d9021fabf6af28d_434x295_notrise.jpg',9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13678,'Готовое печенье остудить.','https://vkuso.ru/data/cache/data/27/8909021733cdf27_434x295_notrise.jpg',10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13678,'Подавать к чаю, кофе или с молоком.','https://vkuso.ru/data/cache/data/c2/dc876871f6709c2_434x295_notrise.jpg',11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13679,'Подготовить филе любой рыбы, порезать, посыпать солью с перцем, дать полчаса постоять. Из молока, муки и взбитых яиц с солью приготовить кляр.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13679,'Хорошо прогреть на сковороде достаточно большое количество масла. Насадить кусочек рыбы на вилку, погрузить в кляр, отправить на сковороду, дать зарумянится с двух сторон.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13680,'Мягкое сливочное масло перетереть с желтками, добавить муку, сметану, ванилин, соль и сахар, погашенную уксусом соду.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13680,'Приготовить начинку из сухого творога, белков, мака и сахарного песка.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13680,'Если смесь получилось жидкой – добавить немного муки.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13680,'Тесто раскатать на лепешки, разрезать сегментами.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13680,'Завернуть в каждый треугольник по ложке творожной начинки.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13680,'Посыпать изделия маком, печь 20 минут при средней температуре.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13681,'Замесить тесто из муки, теплого молока, сухих дрожжей, растительного масла, желтка, сахара, соли.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13681,'Оставить массу на час.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13681,'Разделить на жгуты, нарезать кусочками, раскатать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13681,'Приготовить начинку из жирного домашнего творога, брынзы, белка, соли, свежей зелени.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13681,'Выложить массу на кружки, свернуть рогалики.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13681,'Придать форму круга или подковы.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13681,'Пергамент смазать маслом, выложить на противень.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13681,'Выложить рогалики, смазать взбитым яйцом, присыпать кунжутом.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13681,'Дать постоять пятнадцать минут, печь при температуре 180 градусов. Уровень в духовке – средний.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13682,'Молоко немного подогреть.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13682,'Всыпать сахарный песок, перемешать.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13682,'Добавить дрожжи.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13682,'После того, как образуется пена, всыпать муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13682,'Ввести соль и сливочный спред.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13682,'Продукты хорошо перемешать, дать постоять пятнадцать минут, а затем убрать в прохладу на десять минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13682,'Раскатать тесто на пленке, выложить масло, нарезанное на небольшие кусочки, свернуть лепешку вдвое, раскатать.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13682,'В середину положить масло, закрыть краями, раскатать.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13682,'Положить тесто в холод, через полчаса процедуру повторить, а затем еще раз.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13682,'Готовый продукт нарезать треугольниками.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13682,'Каждый кусочек смазать растопленным маслом, свернуть трубочкой, начинать с широкой стороны.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13682,'Заготовки выложить на противень, время выстойки – от сорока до пятидесяти минут.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13682,'Время выпекания – 20 минут, температура – 200 градусов.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13683,'Тесто раскатать, разрезать на квадраты, а затем на треугольники.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13683,'На широкие края выложить варенье, по краям тесто подвернуть, скатать трубочки.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13683,'Рогалики опустить в сахар, а затем запечь до готовности при температуре 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13684,'Перемешать дрожжи с чайной ложкой сахара, залить небольшим количеством теплого молока, дать постоять четверть часа до образования пены.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13684,'Просеять муку, добавить дрожжи, остатки сахара, влить молоко, чуть посолить, замешать тесто, добавить в конце масло и еще раз перемешать до пластичной массы. Прикрыть тесто тканью, дать постоять около часа.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13684,'Разделать на небольшие шарики одинакового размера, чтобы булочки  равномерно пропеклись, нужно надрезать каждую заготовку три раза, но не до конца, переложить на противень, дать постоять примерно четверть часа. Включить прогреваться духовку до 200 градусов.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13684,'Разболтать яйцо вилкой до однородного цвета, смазать мягкие ванильные булочки, присыпать ванильным сахаром, выпекать до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13685,'Слоеное тесто раскатать, нарезать треугольниками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13685,'В миску выложить творог, добавить ванилин с сахарным песком.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13685,'На каждый кусочек теста в его широкой части выложить начинку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13685,'Скатать рогалик, концы соединить.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13685,'Оставить на полчаса, смазать разведенным в воде медом или маслом.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13685,'Запечь до готовности в духовом шкафу.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13686,'Опара: в миску влить теплое молоко, добавить дрожжи, сахар и муку, хорошо перемешать, накрыть пищевой пленкой и оставить на 30 минут.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13686,'Тесто: яйца взбить с сахаром до пышности. добавить опару, затем постепенно добавлять просеянную муку. Добавить соль.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13686,'Когда вся мука будет в тесте, добавить масло и сливки, вымесить тесто. Тесто должно получится мягким и эластичным и не должно липнуть к рукам.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13686,'Накрыть пищевой пленкой и оставить в теплом месте на 1-2 часа.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13686,'Когда тесто поднимется, помесить его еще пару раз (в этот момент можно добавить изюм или сухофрукты).',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13686,'Затем разделить на части и заполнить формы на 1/3. Накрыть полотенцем и дать тесту подняться (у меня на это ушло 30 минут)',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13686,'Выпекать при 180°С 35-40 мин, готовность проверить деревянной палочкой.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13686,'Глазурь: желатин замочить в воде.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13686,'В небольшую кастрюльку добавить сахар и воду.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13686,'Поставить на средний огонь, помешивая довести до кипения, убрать с огня.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13686,'Перелить в миску сахарный сироп, добавить набухший желатин, взбить миксером до побеления.',NULL,11);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13686,'Добавить лимонный сок, еще раз взбить.',NULL,12);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13686,'Поставить миску с глазурью над миской с горячей водой. Украсить куличи.',NULL,13);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13687,'Роскошный шоколадный десерт.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13687,'Из дрожжевого слоеного теста сделать треугольники, прослоить растопленным шоколадом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13687,'Скатать круассаны и оставить на расстойку.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13687,'Смазать поверхность яйцом или медом, поставить в духовой шкаф.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13687,'Температура выпекания – 180 градусов, время – 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13688,'Выбрать не горький огурец, удалить кожуру, протереть на терке с мелкими отверстиями, сок отжать, чтобы соус не был «водянистым». Чеснок измельчить удобным способом: порубить мелко, раздавить прессом или натереть на терке для мускатного ореха. Вымыть и обсушить зелень, мелко нашинковать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13688,'Перемешать огурец, укроп, чеснок, влить сок лимона, оливковое масло, добавить йогурт, приправить черным перцем и солью, очень хорошо перемешать. Подавать соус «Цацики» из йогурта с огурцом, охлажденным, к мясу или птице, а можно намазывать на тосты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13689,'Слоеное тесто разморозить, раскатать, нарезать треугольниками.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13689,'Выложить по ложке сгущенки на широкую часть.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13689,'Свернуть рулеты, смазать поверхность крепким черным чаем, яйцом или медом.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13689,'Посыпать сахаром и запечь до готовности.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13690,'Пшеничную муку просеять, перемешать с солью, пищевой содой, лимонной цедрой.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13690,'Сливочное масло порубить ножом, быстро перемешать с мукой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13690,'Если тесто получилось слишком сухим, в него можно добавить немного ледяной воды.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13690,'Скатать массу в шар, завернуть в пленку, положить в холод на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13690,'Стол присыпать мукой, раскатать тесто в тонкую лепешку.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13690,'Смазать растительным маслом, присыпать сахарным песком.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13690,'Лепешку разрезать на треугольники, скатать рулетами, начиная с широкой части.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13690,'Противень застелить пергаментом, выложить изделия, поставить в духовку.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13690,'Время выпекания – 35 минут, температура – 180 минут.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13691,'Пшеничную муку просеять, добавить охлажденный маргарин, порубить ножом в крошку.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13691,'Вбить сырое куриное яйцо, всыпать сахарный песок, добавить жирную сметану.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13691,'Замесить тесто, оно должно быть мягким и эластичным.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13691,'Положить продукт на полчаса в холодильник, затем разделить на три части, разрезать на треугольники.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13691,'Выложить на каждый по ложке яблочного густого джема.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13691,'Скатать рогалики.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13691,'Выложить изделия на противень, время выпекания – от 20 до 25 минут. Температура приготовления – 200 градусов.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13692,'Подтаявшее сливочное масло растереть с сахарным песком.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13692,'Всыпать ванилин, соль, добавить сметану, просеянную муку частями.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13692,'Замесить мягкое тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13692,'Обернуть продукт в целлофан, положить на час в холодильник.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13692,'Готовое тесто разделить на две части, раскатать тонкие лепешки, порезать на сегменты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13692,'На широкий край положить по ложке сгущенки, скрутить трубочки.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13692,'Края залепить, начинка не должна вытечь.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13692,'Застелить противень пергаментной бумагой, выложить заготовки.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13692,'Температура выпекания – 190 градусов, время приготовления – полчаса.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13693,'Кулинарный маргарин растопить в микроволновой печи.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13693,'Продукт остудить, перемешать со сметаной, всыпать соду и просеянную муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13693,'Замесить мягкое однородное тесто.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13693,'Положить в холодильник на полчаса, раскатать в лепешки, каждую поделить на сегменты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13693,'Выложить по ложке любимого повидла, разровнять, свернуть маленькие рулеты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13693,'Прогреть духовой шкаф до 190 градусов, время приготовления рогаликов – полчаса.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13694,'Смешать все ингредиенты для теста, замесить их до эластичной массы, не липнущей к рукам, оставить его в теплом месте до увеличения объема. Томаты потушить треть часа в сковороде без крышки при слабом нагреве до мягкости и частичного испарения сока.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13700,'Далее в другую посуду добавим сыр, сахар, яйца, ванильный экстракт и все взобьем.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13694,'Разогреть духовку до 220 градусов. Подошедшее тесто разрезать на 4 одинаковые части, раскатать из каждой круглый пласт толщиной в полсантиметра. Разложить на два круга начинку и моцареллу, прикрыть оставшимися пластами, тщательно защипать края.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13694,'Переложить закрытую пиццу кальцоне с овощами и базиликом на смазанный противень, сделать в нескольких местах небольшие разрезы для выхода пара, побрызгать маслом. Выпекать 15-20 минут в предварительно разогретой духовке.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13695,'Мягкое сливочное масло нарезать кубиками, растереть с половиной нормы сахарного песка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13695,'Вбить сырое яйцо, густую сметану, ванилин.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13695,'Пшеничную муку перемешать с пекарским разрыхлителем, просеять в сливочную смесь.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13695,'Замесить тесто, поставить для охлаждения на полчаса.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13695,'Грецкие орехи очистить, пропустить через мясорубку, перемешать с оставшимся сахаром.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13695,'Разделить тесто на восемь частей, каждую раскатать, разрезать на треугольники.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13695,'Сахарно-ореховую начинку выложить на кусочки теста.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13695,'Заготовки свернуть.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13695,'Время выпекания – 35 минут, температура приготовления – 180 градусов.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13696,'Охлажденное сливочное масло нарезать небольшими кусочками, взбить в блендере.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13696,'Всыпать сахарную пудру, соль, влить молоко, добавить желток.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13696,'Массу продолжать перемешивать.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13696,'В чашу блендера всыпать просеянную пшеничную муку.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13696,'Массу взбивать до загустения.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13696,'Тесто скатать в шар, завернуть в пищевую пленку и поместить в морозильную камеру на 15 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13696,'Готовое тесто разделить на четыре части, раскатать тонкие лепешки, каждую разрезать на восемь треугольников.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13696,'Выложить на тесто мармелад, свернуть рулеты.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13696,'Начинка должна целиком помещаться внутри рогалика.',NULL,9);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13696,'Время выпекания – 40 минут, температура – 180 градусов.',NULL,10);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13697,'Замесить тесто из мягкого кулинарного маргарина, муки, сахара и яичного желтка.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13697,'Согреть молоко в сотейнике, положить сливочное масло, растопить.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13697,'Всыпать мак и сахар, перемешать, снять с плиты, остудить.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13697,'Тесто охладить, раскатать.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13697,'Нарезать лепешку на треугольники, выложить начинку, свернуть маленькие рулеты.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13697,'Печь изделия в течение десяти минут, температура – 180 градусов.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13697,'Рогалики вынуть из духовки, смазать взбитым белком, присыпать сахарной пудрой, печь еще 10 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13698,'Смешать в воде сухие дрожжи и сахарный песок.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13698,'Влить молоко, добавить растопленное сливочное масло, заранее просеянную пшеничную муку.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13698,'Массу вымесить, обернуть пищевой пленкой и положить в тепло.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13698,'Раскатать в тонкую лепешку, оставить при комнатной температуре на сорок минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13698,'Смазать лепешку остатками масла, свернуть в виде конверта три раза.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13698,'Раскатать еще раз, накрыть пленкой, оставить на час.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13698,'Нарезать тесто треугольниками, свернуть рулеты.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13698,'Заготовки смазать смесью молока и яйца, печь до готовности, температура – 200 градусов.',NULL,8);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13699,'Освободить грудки от костей и кожи, порезать острым ножом на тонкие полосы. Перемешать крахмал с черным и красным перцем, добавить соль, перемешать, в другой миске взбить яйца, в третью высыпать хлопья. Каждый кусочек обмакнуть в крахмал с перцем, далее в яйцо, а потом тщательно обвалять со всех сторон в кокосовых хлопьях.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13699,'Раскалить в сковороде достаточное для обжарки куриных грудок, количество масла. Довести мяса до соломенного цвета, вынуть из масла, переложить на бумажное полотенце, перевернуть несколько раз, чтобы впитались все излишки жира. Подавать куриную грудку в кокосовых хлопьях горячей с большой порцией салата и любым соусом.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13700,'Начнем с того, что измельчим печенье в блендере, после добавим растопленное масло, снова немного взобьем, пересыпаем в форму и выравниваем.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13700,'Затем готовую массу добавим в форму, выравниваем и отправляем в уже разогретую духовку до 160 градусов на 45-50 минут.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13700,'После готовую и остывший чизкейк отправляем в холодильник минимум на 2 часа, а лучше на ночь.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13701,'Сварить куриное филе в подсоленной воде с добавлением специй, дать остыть, нарезать кубиками, выложить ровным слоем на блюдо.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13701,'Чеснок измельчить удобным способом, перемешать с майонезом и специями, смазать мясо, это будет первый слой.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13701,'Открыть банку грибов, сцедить, обжарить с кубиками лука, выложить на мясо, это второй слой.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13701,'Третьим слоем выложить крупную стружку яиц, промазать майонезом, прикрыть слоем из помидоров.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13701,'Завершить салат «Кучеряшка» с куриной грудкой сырной стружкой, присыпанной мелкими кубиками красного болгарского перца.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13702,'Разогреваем в сковороде оливковое масло. Лук нарезаем кубиками, чеснок пропускаем через пресс. Обжариваем лук и чеснок на оливковом масле 7 минут на среднем огне.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13702,'Томаты перекрутить и добавить в сковороду, влить вино. Доводим до кипения, готовим 3 минуты.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13702,'Перец мелко нарезать, добавить в сковороду. Так же добавить орегано и готовим 2 минуты.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13702,'Всыпать мидии, готовим 5 минут на среднем огне. Добавить сыр Фета, перемешать и прогреть 2 минуты.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13703,'Мясо режем на небольшие куски, заливаем водой (2,5 литра) и ставим на огонь, доводим до кипения, варим 25 минут. В процессе варки образуется пена, ее нужно снимать.',NULL,1);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13703,'Репчатый лук очистить и мелко нарезать. Обжариваем лук в сковороде на растительном масле, на среднем огне в течении 5 мину, перемешивая.',NULL,2);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13703,'Бульон процеживаем через полотенец или через несколько слоев марли и вынимаем мясо.',NULL,3);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13703,'В чистую кастрюлю отправляем вареное мясо, обжаренный лук и заливаем процеженным бульоном. Доводим до кипения, варим на медленном огне 20 минут.',NULL,4);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13703,'Рис залить теплой водой (6 ст. л.) и оставить на 15 минут.',NULL,5);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13703,'Спустя 20 минут варки супа добавить красный перец, соус ткемали, томатную пасту и рис. Доводим до кипения, варим на медленном огне 20 минут.',NULL,6);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13703,'Очищенные грецкие орехи измельчаем в крошку в блендере, отправляем в кастрюлю. Так же в кастрюлю добавляем лавровый лист, хмели-сунели, паприку, соль, черный перец молотый и горошком, чеснок пропущенный через пресс. Кастрюлю накрыть крышкой, варим 5 минут.',NULL,7);
INSERT INTO public.instructions (recipe_id,"text",image,step_number) VALUES (13703,'Суп Харчо снять с огня. Петрушку и кинзу мелко нарезать, отправить в кастрюлю к харчо.',NULL,8);
